Object.assign(window.__LB,{"7500": ["病机", "「脉大」主邪热亢盛，疏泄肺邪后咳不减、痰气带秽，是风邪与浊交蒸、肺胃热郁未解。脉大为病进、为热盛，与痰秽、痰带青绿相应；青绿属风属肝，故言厥阴之病、风气通肝。此段以脉大断邪热鸱张、郁于肺胃。", ["大"]], "7501": ["病机", "「脉象虚细」主正气亏虚、阴血不足，与痰色青绿、心中空豁、舌红苔心霉黑并见，是痰热上盛而真水下虚，上实下虚之候。虚细之脉说明病久正伤、肾水亏耗，不能制上炎之痰热，故仍用上下分治，清上滋下并行。", ["虚", "细"]], "7502": ["病机", "「脉濡滑」主湿盛痰聚，濡为湿、滑为痰。孩儿泄泻后脾运不及，生痰聚湿，复感暑风，邪与痰合，肺胃失降，故咳甚则呕吐。濡滑之脉正应痰湿内蕴、暑风外袭，脾虚为本、痰湿为标，故宜降宜下以肃肺胃。", ["濡", "滑"]], "7503": ["病机", "「脉形仍然沉细」，沉主里、细主虚，示太阴深伏之寒虽经三拗汤搜剔而咳大退，然沉细未改，说明寒邪未尽、阳气未复，正虚仍著。故引「不入虎穴焉得虎子」，示须继续深入搜邪，不可因咳退而遽止，脉象为凭。", ["沉", "细"]], "7504": ["病机", "脉数而右寸关独大，是外感新邪束表、里有伏寒化热之象。原文谓'不寒而热，汗不畅达'，正合邪郁肌表、欲透不得；右寸关候肺脾，独大说明新邪与伏寒相争于上中二焦。故断为'外感新邪，与本病两途'，治当疏泄透邪，勿引动伏气。", ["数"]], "7505": ["病机", "脉形滑大，滑主痰热内蕴，大主邪盛。原文'寒束于外，热伏于中，咳嗽痰黄'，外寒闭表则热不得散，郁而炼液成痰，痰热壅肺故咳痰色黄。滑大之脉正是寒热错杂、痰热内盛之征，故拟辛温寒合方，外散表寒、内清里热。", ["滑", "大"]], "7506": ["病机", "脉细虚软，为肺气亏虚、金令不行之象。原文谓咳嗽已退而'肺气一时难复'，尚带微呛、耳鸣头痛、咽中火冲，乃肺虚不能制木，木邪易动、虚火上冲。细虚软正合不足之候，故用金水六君补其不足，滋肺肾以柔肝木。", ["细", "虚", "软"]], "7507": ["病机", "脉象细弦，细为阴血亏虚，弦主肝木偏旺、气机郁滞。原文'大失血后，瘀血散入肺络'，咳嗽凛寒发热、腹满作痛，是血去正虚而瘀阻肺络、肝气横逆。细弦示本虚标实，故断'病实本虚，恐传入损途'，须防虚损成劳。", ["细", "弦"]], "7508": ["病机", "脉细弦微数，细为阴亏，弦属肝旺，数主火动。原文咽痒呛咳、屡次见红、左卧气冲、暮热少寐，皆肝火内烁、阴分日亏、阳气偏亢之候。弦数示火势未平，细示阴液已伤，故治以金水并调、参以滋肝，标本兼顾。", ["细", "弦", "数"]], "7509": ["病机", "脉形细数，细主阴血亏耗，数主虚火内扰。原文久咳见红、吐血盈碗后咳甚呕吐、音塞不扬，'胃咳之状，咳而呕'，是肺肾并伤、中气亦损，虚火灼金、胃气上逆。细数示损象已成，故谓'损而难复，不可不防'。", ["细", "数"]], "7510": ["病机", "脉形虚细，虚为气不摄纳，细为阴液不足。原文咳嗽半载、咳则火升轰热、曾经见红，是肺肾两亏、虚火上浮、不能收摄。'其标在上，其本在下'点明咳热为标、肾虚为本，虚细之脉正合下元不固，故拟金水双调以固本摄纳。", ["虚", "细"]], "7511": ["病机", "脉象虚细，仍属肾虚液亏之候。原文火升轰然已定、咳嗽略减，而每晨必咳尽稠痰方舒，是肾虚水泛、液炼成痰、上阻肺降。虚细示本元未复，痰浊为标，故谓'再作缓兵之计'，仍守金水双调、缓图其本。", ["虚", "细"]], "7512": ["病机", "脉形濡细，濡主湿、细主阴亏，合苔黄中心浊腻，知湿痰蕴中而阴液已伤。原文谓“阴虚于下，痰甚于上”，清晨咳甚、寐则口干咽燥，正是下虚上实、痰热交阻之象，故以和阴清金兼化痰热为治。", ["濡", "细"]], "7513": ["病机", "脉形虚细，虚为气弱、细为阴亏，舌红苔糙更示阴分耗损。前因天时寒暄、封固不密而咳嗽转甚，乃标邪引动本虚。原文断“阴分亏损，不问可知”，故主张舍标治本，脉虚细正是本虚之凭。", ["虚", "细"]], "7514": ["病机", "脉形濡细，左部带涩，濡细主肺胃气阴并亏，涩则示湿滞血行不畅。症见痰黄稠带青绿、腹满运化迟钝，原文断“肺胃并亏，而湿滞中州”，脉与症合，故只作缓兵之计，先调中化痰。", ["濡", "细", "涩"]], "7515": ["病机", "脉细濡数，细濡为阴亏湿聚，数为热象。原文谓饮聚成痰、阴虚生热，热痰交蒸故咳血频来、痰黄青绿带臭秽，腹中不和。脉数示热郁，濡细示虚与湿，故断将成肺痿重症，仍作缓兵之计。", ["细", "濡", "数"]], "7516": ["病机", "脉形虚细，舌红苔糙，为肺肾久虚、阴分不足之征。风温虽解而寅卯咽痒咳甚、痰稠纳少，原文谓“冲阳挟痰上逆，证属本原”，与痰饮有别，脉虚细正合本虚，故拟金水双调。", ["虚", "细"]], "7517": ["病机", "脉象濡弦，濡主湿、弦主气机不和。呛咳虽止而胃气呆钝、口燥咽干未定，原文谓“肾阴不复，中气下根于肾，所以肾愈虚则胃愈弱”，脉濡弦正是肾虚胃弱、湿阻气滞之象。", ["濡", "弦"]], "7518": ["病机", "脉细，苔白少华，细为气血不足。咳嗽时轻时重，肺气久伤而“窃盗母气”，脾土因而不振，大便时溏。脉细正应脾肺两虚，故用培土生金法，从脉细可验中气之弱。", ["细"]], "7519": ["病机", "脉数，两关滑大不能重按，数主热、滑大主痰热壅盛，不能重按则示阴伤于下。原文谓湿热化火伤阴，虚火挟浊上炎，故咳嗽暮甚、痰青绿气秽。脉数滑大正是痰火鸱张、本虚标实之候，清化不应，勉拟壮水制阳。", ["数", "滑", "大"]], "7520": ["病机", "脉数主热，结合咳嗽夜重、痰黄稠厚、便坚带黑、舌光，显系阴虚火炎、金水并损，虚火内灼；然痰厚色黄，又示胃中湿热留恋，故于清养之中兼导湿热下行，脉数为虚火与湿热交蒸之象。", ["数"]], "7521": ["病机", "脉数濡弦，左部虚弦，舌苔薄白而滑。数主内热，濡主湿，弦主气郁，左部虚弦为肝郁阴伤。原文谓“气阴两亏，而湿热逗留”，湿热郁遏、风邪外触致咳，痰黄稠腥秽，皆湿热蒸腾、气阴耗伤之征。", ["数", "濡", "弦"]], "7522": ["病机", "脉数而滑，数主热，滑主痰，痰热内迫，故咳嗽痰红、痰气腥浊、内热连绵。原文断为“痰热内迫，势成痈痿”，滑数相合，正示痰热壅盛、灼伤肺络，有酿痈成痿之势。", ["数", "滑"]], "7523": ["预后", "脉象急数，急为热盛势迫，数为热炽，湿热蒸腾伤肺，故咳嗽痰秽吐血，原文谓“肺痿情形也”。病在高年，脉急数示邪热鸱张而正气已衰，故曰“难以许治”，属预后不良之候。", ["数", "急"]], "7524": ["病机", "本段未识脉名，纯述症候。肺感风邪久恋，痰湿蒸动，营卫失度而寒热如疟；湿痰蕴遏阳明，筋骨失利而两足痿强；今咳止而气喘难卧、冷汗肢厥，是肺气出而不纳，肾不摄纳，虚多难挽之象。", []], "7525": ["预后", "六脉细涩，细为阴亏，涩为血少气滞，主肾阴久亏、根气失摄。冬令收藏不固，春阳发泄，喘呼不能坐卧，虚阳上浮而唇焦颧红，有汗脱之虞。细涩之脉示根本空虚，故补肾阴以摄肾气，能否应手恐难必也。", ["细", "涩"]], "7526": ["病机", "脉细少情，细主阴血亏虚，少情示胃气不足、脉失从容。肾虚闭藏不固，春阳发泄，肾不藏纳，冲阳挟龙相上逆，肺气不能下通于肾，故喘剧、耳聋、咽阻、二便不利，形神消夺，恐阳气泄越而汗出。", ["细"]], "7527": ["病机", "脉象细数少情，右尺尤觉细涩。细为阴亏，数为虚热，涩为肾气不摄。药后耳聪溲利、喘稍休止，然口渴咽干、动则喘甚，根本空虚不能摄纳之象未除，右尺细涩尤显肾元亏乏，故勉从前意扩充。", ["细", "数", "涩"]], "7528": ["病机", "左脉弦大且数，弦为肝旺，大为阴虚阳浮，数为内热，合示肾阴亏虚、封藏失职，气不收藏而冲逆。原文谓肾虚则“肾气不能仰吸肺气下行”，冲气挟痰饮上逆致咽痒咳嗽见红；脉不沉郁、大而左部为甚，正说明阴虚阳亢而非命阳不足，故断无阳虚之证。", ["弦", "大", "数"]], "7529": ["病机", "脉来沉弦，沉主里、主水饮内停，弦主饮癖气逆。痰喘遇寒触发，胸膺不舒，呀呷有声，苔满白，皆寒饮阻肺、肺气不宣之象。沉弦说明痰饮深伏于里、气机被遏，故宗小青龙意以宣通肺气，使痰饮下降，肺气宣通则痰自降。", ["沉", "弦"]], "7530": ["病机", "脉濡弦，濡为阴血不足、湿滞，弦为肝木郁逆。原文谓“肝肾阴虚，为致病之源，冲阳逆上，为传病之地”，冲气挟痰水上升致头痛面红、咽中如阻、吐血频来。濡弦正合阴虚木郁、冲阳上逆之机，故不可作痰饮主治，惟宜滋水养肝、摄纳肾阴，使水不上泛。", ["濡", "弦"]], "7531": ["病机", "脉沉弦，右部虚软下，沉弦主里、主气逆，右部虚软示中气不足。原文谓“虚上实”，即下虚上实：喘时重时轻、浊精自出，为肾虚不摄、冲气上逆。沉弦说明病根在里，气逆于上而根本已虚，故用雷少逸法补纳兼降逆，不可纯攻其痰。", ["沉", "弦"]], "7532": ["病机", "右部细弱而滞，左部弦大。细弱滞示气弱生痰、脾肺不足，弦大示肝肾素亏而木失涵养、气逆上升。原文谓“气弱生痰，肝肾素亏”，宿饮停痰尽从上逆，蔽阻肺降之路，出纳失常，深恐上实下虚、阴阳离决。脉象正合虚中夹实、上盛下虚之机，故拟辛温寒合方。", ["细", "弱", "弦", "大"]], "7533": ["病机", "左大少情，右濡细软。左大而少情示肝木失涵、虚阳有余，右濡细软示气阴不足。年过花甲、肝肾日亏，一阳来复后气逆痰上，喘定仍眩晕心悸、肢体倦乏，皆下焦空乏、摄纳失职之征。脉象说明根本已虚而肝木余威未平，故恐复至暴厥。", ["大", "濡", "细", "软"]], "7534": ["病机", "二诊补纳肝肾后症尚和平，而左脉仍觉弦搏。弦搏为肝木未柔、下焦空乏未复之象。原文谓“下焦空乏，根本之区，不易图复，理所宜然”，说明虽症状缓解，但肝肾亏虚、木失涵养之根本未复，弦脉仍在，提示需继续摄纳下焦，不可因症平而辍补。", ["弦"]], "7535": ["预后", "三诊左脉稍敛，心悸眩晕俱减。原文未识脉名，仅述脉象由弦搏转敛，与心悸眩晕减轻相应，说明摄纳下焦之法渐效，肝木稍柔、虚阳渐潜。脉症同减为向愈之兆，故再议摄纳下焦以巩固根本，属预后转佳之判断。", []], "7536": ["预后", "原文述“四诊脉象较前柔静，饮食亦复如常”，脉象由病态转柔静，示邪退正复，胃气渐和。“虚能受补”说明正气尚能承受补益，故预后向好，可“扬鞭再进”继续调治。此段重在判断转归，非论具体病机。", []], "7537": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。肝肾素亏，脾土亦弱，水谷不化精微而聚为痰饮，饮阻肺下则气喘痰多盈碗。舌苔白腻亦为痰湿之征。此脉此症，正合仲景“饮家当以温药和之”之支饮病机，本虚标实，脾肾不足而饮邪上泛。", ["沉", "弦"]], "7538": ["病机", "脉沉弦，沉为在里，弦主饮主气逆。先感风寒，复饮火酒，寒热互阻于肺，痰饮上升，肺气不能下通于肾，故气喘痰鸣、胸次窒闷、卧著尤甚。左尺尚觉有神，说明肾气未至大虚，尚非肾不纳气之劣症。时自汗出，为表气不固，故拟开太阳之表以疏邪。", ["沉", "弦"]], "7539": ["病机", "脉濡滑，濡主湿主虚，滑主痰主实。向有痰饮，复感新风，肝木郁勃，痰饮随外感余热与肝气蒸腾而上，迷蒙清窍则神志模糊，阻塞肺气则气喘不能著枕，肾气空虚则汗出溱溱。舌苔灰滞亦痰湿之象。此本虚标实，痰饮上蒙，肺肾出纳失常之危候。", ["濡", "滑"]], "7540": ["预后", "脉见歇止，为元气断续、心气不继之象。汗虽止而懊烦，痰稠腻如胶牵丝不断，舌苔浊腻灰滞，说明无形气火与有形浊痰蕴聚胸中，阻塞肺出肾纳之路。标实本虚，元气能否胜任攻痰降气，实难逆料，故曰“勉再议方”，预后堪忧。", ["歇止"]], "7541": ["病机", "脉弦为肝阳偏亢，两关微滑为火气有余、湿热内蕴。湿热有余，肝阳偏亢，阳气触犯肺胃之络，络损不固则吐血频来；阳气发泄太过则时易汗出。此火气有余、络伤血溢之病机，故治以清养肺胃、益水之上源，而不涉呆滞助湿。", ["弦", "滑"]], "7542": ["病机", "脉细弦，细为阴伤，弦为肝旺；右部兼滑，滑主痰。幼时血症，血膜已破，燥气伤金，金不制木，厥阳上逆，激损肺胃之络，故失血满碗、胸中掣痛。络损难固，血夹杂不能净尽。若不急治，络损日甚，恐致暴涌，故谆谆告诫。", ["细", "弦", "滑"]], "7543": ["病机", "脉细数不调，细为阴伤，数为火旺，不调为升降失序；右关独弦滑，弦主肝旺，滑主痰湿。肝升太过，胃气耸涌不能通降，气火上逆载血逆行，故吐血不止、胸闷恶心、呃忒频频。痰湿内阻，升降不循常度，血出愈多，浊聚愈满，大便不行。", ["细", "数", "弦", "滑"]], "7544": ["病机", "原文以「左脉并不浮露」排除肝肾，又据「多饮多溲」知肺气通调水道而病不在肺，再参「两胁不舒、中脘自喜挫磨」定病位在肝胃。脉不浮露说明病非外感浮越，而是平素郁结伤肝、木火犯胃，胃络受损则血上溢，属内伤郁结之病机。", []], "7545": ["病机", "「脉来弦大」而症见气冲、咯吐全红，弦主肝木气逆，大主火盛鼓动。原文断为「肝火撼胃，胃气逆，血因之而上矣」，说明弦大之脉反映肝火亢盛、胃气上逆，载血上行，故虽血止而气冲未定，仍主肝胃火逆之病机。", ["弦", "大"]], "7546": ["病机", "「脉象左弦」伴血仍不止、头胀少寐、吸气短促，左弦为肝阳偏亢之象。原文谓「无非阳气上逆，载血妄行」，说明弦脉主阳气上逆、肝失潜降，血随气升而妄行，故断为阳气上逆之病机，并虑其涌溢。", ["弦"]], "7547": ["病机", "「脉象浮芤」，浮主风温袭肺、病位在表在上，芤主络损血溢、阴血外泄。原文由咳致见红、时来时止，说明风温犯肺、肺络受损而血外溢，浮芤相合正示风热在肺而血络已伤，故虑其复涌，属肺络受损之病机。", ["浮", "芤"]], "7548": ["病机", "「脉象数大」而见咽痛、呛咳带红、痰稠颧红、清晨血来，数主热盛，大主火升鼓动。原文断为过食甘寒致风热内郁、激损肺络，数大之脉反映膈热内郁、火升迫血，故宜泄膈热，属风热郁肺、火升损络之病机。", ["数", "大"]], "7549": ["病机", "「脉象细弦，舌红少苔」，细主阴血不足，弦主木火内动。原文谓「阴虚木火上凌，营络损破，而气火仍然不平」，说明久咳伤阴、阴虚不能制木，木火凌扰营络而血溢，细弦正合阴虚火动之象，故虑暴涌。", ["细", "弦"]], "7550": ["病机", "「脉细弦而数」，细为阴虚，弦为木火，数为火盛。原文断为「阴虚木火凌金，冲气从而上逆」，说明阴亏于下、木火亢于上，冲气上逆而痰中带红、气冲呛咳，细弦数正示阴虚火逆之机，故拟育阴制冲。", ["细", "弦", "数"]], "7551": ["预后", "二诊「脉细弦数稍缓」，痰红已止、咳亦略减，原文谓「冲阳稍平，肺肾阴伤不复」。数稍缓示冲阳渐平、火势减退，而细弦仍在则阴伤未复，故脉之稍缓为病情向缓之预后，仍须金水双调以复肺肾之阴。", ["细", "弦", "数", "缓"]], "7552": ["病机", "脉细弦数，细为阴血亏少，弦为木火内动，数为火盛。屡次失血致肾水不足，木火上凌损肺，络血外溢；血去阴伤则气不收摄，出纳失常，故呛咳咽痒、气升痰红而稠。脉象与失血伤阴、木火刑金之机相应，故恐入损门。", ["细", "弦", "数"]], "7553": ["病机", "血虽止而脉仍细弦数，细示阴血未复，弦数示木火尚亢；气口独大，说明上焦肺金未肃。血去多则肾阴伤，木火循经上扰，故咽痒呛咳、气从上升。脉象未缓，提示病机仍以阴虚火逆、肺失清肃为主，故再清其上。", ["细", "弦", "数"]], "7554": ["病机", "脉数内热，数主热盛，内热由血去过多、阴伤难复而来。阴虚不能制阳，阳升凌犯肺金，故每晨咳甚、痰不爽出而色带青绿。暮夜呛咳已定而晨咳突出，正合阳升乘肺之机。脉数在此示虚火内扰，故拟育阴以平阳气之逆。", ["数"]], "7555": ["病机", "原文未识脉名，纯以症候立论。水亏木旺，虚火上凌，故咳嗽不已、吐血时止时来；冲阳逆上，咳甚则呕，因冲脉在下而布散胸中。此段重在说明阴亏火逆、冲气上干之病机，症入损门，提示虚损难治，非单论脉。", []], "7556": ["预后", "三诊咳嗽大退、腰酸稍减，脉亦渐和，说明肺肾虚损之势有所缓和，脉症相应。然原文强调肺肾皆虚，何能遽复，调理非旦夕间事。脉渐和在此为向愈之象，但非平复，故属预后判断，提示仍需自卫调养，不可骤补。", ["和"]], "7557": ["病机", "原文未识脉名，以脉症相安立论。金水双调后胸次时觉窒闷，乃冲脉气逆，亦属阴亏所致。阴亏则冲气不摄而上逆，布散胸中，故窒闷。此段说明病机重点在阴亏冲逆，虽脉症相安，仍有余症，属病机分析而非平脉。", []], "7558": ["病机", "脉濡微数，濡主湿，微示正虚，数主热。金类疟后湿热未清，蕴结膀胱，溲血两次；湿热熏蒸肺胃，络损血溢，故咳恋咯红。脉濡微数正合湿热内蕴而阴络受伤之机，故拟开肺气以导湿热下行，使湿热从下而解。", ["濡", "微", "数"]], "7559": ["病机", "脉沉而弦，沉主里、主水湿，弦主肝旺。咳血后元气未复，阳虚肝旺，脐下漉漉鸣响，两目干涩，苔白而腻。膀胱之湿为风所激，鼓动成声。脉沉弦与阳虚肝旺、水湿内停相应，故宜分利水湿，参以养肝。", ["沉", "弦"]], "7560": ["病机", "脉形沉细，沉主里，细主虚，结合失血后神色淡白、气逆带咳、大便溏行，显系脾阳不振，统摄无权，血妄行而屡失。脾为统血之脏，以阳为运，阳衰则运化失职，故脉沉细无力。病久不复为损，损久不复为劳，提示正气难复，有涉虚损之虞。", ["沉", "细"]], "7561": ["病机", "两关弦滑，关候中焦，弦主气郁、滑主痰湿。失血后腰背酸、火时上升，乃中气不足，痰湿内阻，胆胃之气不降，郁而化火。弦滑并见，说明痰湿内壅、气机不畅，故宜调中降胃，兼益肝肾，以复中焦升降之职。", ["弦", "滑"]], "7562": ["病机", "脉形沉细，舌淡苔白，胃钝纳减，临涌时四肢厥逆，乃感寒不解，与湿相合，脾阳遏郁，统摄无权。沉细为阳虚湿困之象，脾阳不运则血失所统，虽大势已定，气冲咽痒未除，还恐涌溢，故当温运脾阳以摄血。", ["沉", "细"]], "7563": ["病机", "气口浮弦，气口候肺，浮主上焦，弦主气逆。久喘咳致肺胃络损，血来如涌，脉浮弦说明气火上逆、络伤血溢，病位在上焦肺胃。浮弦不敛，提示气逆未平，有再涌溢之虞，故当降气宁络以止血。", ["浮", "弦"]], "7564": ["病机", "脉细而不耐重按，细为阴伤，不耐重按为虚而兼邪。血来盈口继发痧疹，风温迫损肺胃，伏风未清则新风易入。脉细不耐按说明正气已伤而风温未澈，不可漫投育阴补益，宜微苦辛凉以澈根蒂，否则恐犯薛氏成劳之例。", ["细"]], "7565": ["病机", "脉象略柔敛，为转机之兆，但心中灼热、咳嗽随气、舌红苔白而糙，乃肝升太过、肺降无权。血止而咳未定，气逆虽减未平，脉虽柔敛而症未全退，恐缠入损门，故拟清金平木、降气育阴，以复肺肝升降之常。", []], "7566": ["病机", "脉细软弱而两寸动数，细软弱为气阴两虚，动数为阳气升动不息。血室未扃，痰中夹红，寐汗纳后饥𩠎，体动气冲，皆由阳气升动、摄纳无权、肺降失职。上愈甚则下愈虚，非有情有质之品不能达病所，故从前法扩充，育阴潜阳以摄纳。", ["细", "软", "弱", "动"]], "7567": ["病机", "脉象沉弦，沉主里主水，弦主饮主痛。痰饮致咯血，中州痞满，噫出腐气，乃脾土为湿痰困乏，不能统血。沉弦说明湿痰内阻、气机郁滞，脾运失职则血不归经，恐损而难复，故当运脾化饮以复统血之权。", ["沉", "弦"]], "7568": ["病机", "吐血后血止而腰府作痛，脉象细弱，细为阴血不足，弱为阳气衰微，正合原文“血去之后，肝肾愈形空乏”，故脉见细弱乃肝肾精血亏虚、络脉失养之征，非实邪为患，治宜益肝肾而清肺胃，以复其不足。", ["细", "弱"]], "7569": ["预后", "腰痛稍减、脉象稍振，是吐血后肝肾空虚渐有恢复之象。原文未出具体脉名，仅言“稍振”，即脉较前有力，示正气渐回、虚损有渐复之机，故为预后转佳之征，效方再为扩充以巩固。", []], "7570": ["病机", "失血后火升内热、脐下坚满、足膝欠暖，脉数细沉。数主虚火，细主阴血不足，沉主病在里，合原文“气虚而脾不统摄，阳气不能转旋于下，则虚火尽越于上”，乃中气亏虚、虚火上浮、下元失温之机，将入损途。", ["数", "细", "沉"]], "7571": ["病机", "腹偏左较舒而结块未化，脉形濡细。濡为湿滞、细为不足，合原文“太阴无旋运之权”，知脾土虚弱、运化失职，湿浊内滞而成结块，脉濡细正应脾虚湿困、转旋无力之病机，故效方出入以健脾化滞。", ["濡", "细"]], "7572": ["预后", "六脉细涩、按之无神，细为阴血亏少，涩为血行不畅，无神则胃气衰败。原文述吐血频年、脾土虚极不能统摄，又因温助命火致肝火逆上、大便作泻，脉证合参，乃脾肾两败、气血俱损之重候，故曰“重地深入”，预后堪忧。", ["细", "涩"]], "7573": ["病机", "脉形左大，寸浮关弦尺涩，右部濡弱，气口带搏。左大弦为木火亢盛，寸浮为阳浮于上，尺涩为肾阴亏耗，右濡弱为中气不足。合原文“木火久郁，触之即发，损络动血，阳浮阴弱”，乃肝火逆冲、肺胃络损、肾水不涵之病机。", ["大", "浮", "弦", "涩"]], "7574": ["病机", "脉左弦大，右部大而濡软。左弦大为肝阴不足、气火未靖，右大濡软为胃液耗损、中气不振。原文谓“肾水肺津，肝阴胃液，一齐耗损”，又“胃为阳土……有气无液”，故脉象反映水液阴津俱亏、胃失和降之病机，治拟滋水养液。", ["弦", "大", "濡", "软"]], "7575": ["病机", "脉濡微滑，濡主湿浊，滑主痰涎。原文述病后痰多、形体恶寒、沉沉欲寐，乃“水谷之气，生痰酿浊，弥漫胸中，以致阳气不能流布，神机不能转运”，脉濡滑正应痰浊内蕴、阳气被遏之病机，故前法参以化痰。", ["濡", "滑"]], "7576": ["病机", "脉形右大，右主气分，大则气郁化热之象。原文谓胸次气郁不舒，呕血由此而起，舌干少津，是气分久郁，上焦不行则下脘不通，郁热伤津。右大之脉正应气郁于上、津液受灼，故治以开展上焦气化、甘凉救津，脉象与气郁津伤之机相合。", ["大"]], "7577": ["病机", "脉细弱而数，左关微弦，尺中小涩。细弱为血去太多、阴血亏虚；数为火来克金；左关弦应肝火偏亢；尺涩主肾本空虚、失于摄纳。原文谓溢血后即咳、晨汗不寐内热、痰多带咸，皆血亏火旺、肾不纳气之候，故恐延入损途。", ["细", "弱", "数", "弦"]], "7578": ["病机", "原文未识脉名，然述两关略柔为起色，而气口之脉大于关部。气口主肺，大于关部则肺气壅逆不降。原文谓血溢时血多喉小、卒不得出，瘀血散入肺络，肺气逆而不降，故咳嗽较血涌时反增。脉象所示正为瘀阻肺络、气逆不降之机。", []], "7579": ["其他", "原文仅言和脉，未列具体脉象要素。所述努力损伤肺络、络血外溢、不时见红、左胁作痛、咽燥舌干，为肺胃络伤、阴津受灼之候。脉和则示病势尚平，故治宜清养肺胃、以和脉络，属因证立法之文，脉象无独立病机可析。", []], "7580": ["预后", "脉细涩而沉，左关带弦。细涩主阴血亏少、脉道不利，沉为病在里，左关弦应肝郁络滞。原文断为内伤重症，谓若得息心静养或能带病支持，是脉见细涩沉弦而正气已亏，故预后须静养维持，脉象与内伤重证之判断相应。", ["细", "涩", "沉", "弦"]], "7581": ["病机", "原文未识脉名，仅言脉症相安。所述带下腰足酸弱、咯血凝厚、气冲作呛，为肝肾阴虚、奇脉不固之候。脉症相安示药后脉与症暂得相应，然腰足酸弱、咯血仍存，说明阴虚未复、冲任失固，故仍守肝肾并调兼固奇脉，脉象仅作疗效佐证。", []], "7582": ["病机", "脉濡而弦。濡主湿滞、胃气不充，弦主肝络拘急。原文谓吐血频来、不时嗳噫、便数日方行，未吐先胸腹作痛、既吐痛定，是踊跻损伤肝胃之络，胃气不降、肝络不和。濡弦并见，正合肝胃络伤、气逆不降之机，故拟降胃除陈补新。", ["濡", "弦"]], "7583": ["病机", "脉象细弦。细为阴血不足，弦主肝气偏亢。原文谓性情躁急，肝经之气火上凌，吐血屡屡，气升呛咳。气火上逆则血随气升，故脉见细弦；细又示吐久阴伤。气为血帅，降血尤当降气，脉象正应肝火气逆、阴血受耗之病机。", ["细", "弦"]], "7584": ["病机", "原文谓二诊后呛咳较平而脉亦略缓，缓为胃气渐和之象，说明前法熄肝降气已使上凌肺金之势稍折。然案中明言此属无根之木，肝阴亏虚、虚阳上浮，脉缓仅是暂时缓和，非病本已除，故仍须参以育阴以固其根，否则虚阳复升则呛咳再作。", ["缓"]], "7585": ["病机", "脉形弦大为肝火亢盛、风热外袭之象。弦主肝病，大主邪盛，肝火积于内则阳络被灼，风热袭于外则络脉不固，内外相合致鼻衄盈碗。脉弦大示火势未平，故原文断还恐有复涌之势，须防再次出血。", ["弦", "大"]], "7586": ["病机", "脉象弦大与上证同，弦为肝风，大为热盛，合而示肺胃风热内迫、阳络受损。鼻衄如注而脉仍弦大，说明邪热未得清泄，气火尚盛，血随气上，故原文恐致厥脱，虑其血脱气随、阴阳不相维系。", ["弦", "大"]], "7587": ["病机", "脉涩主营血瘀滞，两关独弦示肝脾瘀结尤甚。任重受伤则血瘀于内，蓄极暴决故呕血盈盆、便紫黑，瘀阻则面黄力乏、腹中结块。脉涩弦说明蓄者虽去而新瘀复生，故势必复为呕下，临时汗脱之虑正由瘀血内阻、气不摄血所致。", ["涩", "弦"]], "7588": ["病机", "脉细濡弱为久病肠红、营血耗伤之象，右关独弦滑则示湿滞中焦、热蕴肠腑。细濡弱说明正气已虚，弦滑说明风湿热邪袭入大肠营分，虚实夹杂，故非沉阴苦降不足以达肠中，清化与扶正并施。", ["细", "濡", "弱", "弦"]], "7589": ["病机", "脉形浮大为风邪外袭、热迫肠络之象。浮主风邪在表，大主热盛，风热袭入肠胃，血络被伤，故便血四溅如筛，即所谓肠风。脉浮大说明邪尚在阳分、热势偏盛，故宜泄热化风以清肠络。", ["浮", "大"]], "7590": ["病机", "脉滑而实为湿热壅盛之象，滑主湿浊，实主邪结。湿热盛极则湿扰精宫，致无梦而泄二十余年；湿热伤及阴络则鼻红、便血并见。苔白腻亦佐湿盛。原文引经云阴络伤则血内溢，说明上鼻红下便血与遗泄虽症殊而源同，皆由湿热内盛所致。", ["滑", "实"]], "7591": ["病机", "脉象细数为阴血亏虚而湿热未清之象。细主营阴不足，数主热，肛门烙热稍退而便血不止，说明湿热虽减仍损伤营分、阴络内伤。细数并见示阴亏与余热并存，故再拟养肝滋阴壮水，以滋水清余热而固阴络。", ["细", "数"]], "7592": ["病机", "脉形沉细，苔白质淡，沉主里、细主虚，合参肠红稀淡、脘痞腹胀难食，知非实热迫血，乃脾阳不能统摄，血溢下注；脾难旋运则湿停气滞，故肿胀日甚。脉沉细正应脾阳式微、气血不足之机。", ["沉", "细"]], "7593": ["病机", "脉沉细、苔淡白，便血虽减而便泄腹痛、胸脘痞满攻撑、腹膨肤肿，说明脾稍统摄而旋运无权，水湿不化，肝木乘虚偏亢，气湿不能分化。沉细为脾阳不足、湿郁气滞之应，故前法再参分化。", ["沉", "细"]], "7594": ["病机", "脉形沉细，肢体虚浮，便血虽止而脘腹胀满不减、小溲不利、便泄、两足厥逆，是阳气不能敷布，水湿泛溢肌肤。沉细主里虚阳弱，阳虚则水湿不化、四末失温，故须宣布五阳以望转机。", ["沉", "细"]], "7595": ["病机", "尿血不止而尿管不作痛，脉形细弱。细弱为气血不足、肾虚之象，痛者为火、不痛者为虚，故断为肾虚湿热内袭、实少虚多。脉弱正应虚多，湿热虽袭而正气已馁，治当以补虚为主。", ["细", "弱"]], "7596": ["病机", "尿血渐减，脉亦稍缓。前诊细弱为肾虚，今脉稍缓是虚象渐退、胃气来复之征。原文以痛者为火、不痛者为虚，此证不痛而尿血，属肾阴不足，故再益肾之阴，脉缓示病情向缓。", ["缓"]], "7597": ["病机", "尿血递减尚未能止，脉象微数。微为虚，数为热，合尿血不痛之虚证，知肾虚而虚火内迫，血不归经。数非实热之数，乃阴亏火动之数，故治法再育阴泄热，以滋肾阴、清虚火。", ["微", "数"]], "7598": ["病机", "左溲血已止而脉象尚觉弦硬。弦硬为肝肾阴亏、木失柔养、不能固摄之象，湿热乘虚袭其地。血止而脉未和，说明根本未复，故从壮水之中参以坚阴，使肝木得柔、肾能固摄。", ["弦", "硬"]], "7599": ["病机", "脉象沉弦，沉主里、弦主饮主痛。甘凉频进以胃药治肝，火风稍杀而脾阳暗损，旋运不及，胃中水湿停留，故脘痞阻、甚则呕吐。沉弦正是停饮之兆，饮停中焦、气机不利，久恐延膈。", ["沉", "弦"]], "7600": ["病机", "脉沉细，右尺更甚，沉主里，细主虚，右尺候命门火衰。原文谓“火被水抑，不能蒸变”，命火不治则脾土不运，故谷食不化而涌吐，大便频泄。此脉象揭示停饮内阻、火衰土弱之病机，主脾肾阳虚、水饮内停之呕吐泄泻。", ["沉", "细"]], "7601": ["病机", "脉象濡软，濡主湿、软主虚，为脾胃气虚、水湿不化之征。原文谓“久病脾胃气虚，不能运旋”，水谷不化，清浊不分，故食入倒饱、中脘痞胀、汩汩作酸、小溲短少。此脉主脾虚湿困、水饮停留之痞胀呕吐。", ["濡", "软"]], "7602": ["病机", "脉沉细微数，沉细主里虚，微为阳衰，数则示营液耗伤而生内热。原文谓“停饮日聚于上，胃液日耗于下”，营液既虚则木失涵养，肝气横暴挟痰攻冲。此脉象反映脾胃虚衰、营液亏耗、肝木犯胃之复杂病机，主呕吐窒闷、便涩溲少。", ["沉", "细", "微", "数"]], "7603": ["病机", "脉象濡弱，濡主湿滞，弱主气虚，为胃气阴两亏之象。原文谓“屡次挖之使呕，胃中之气阴安得不亏”，谷气不化而酿腐，故胸膈不舒、噫出腐气。此脉主胃虚气逆、谷气不化之痞闷噫腐，治以大半夏汤通补阳明。", ["濡", "弱"]], "7604": ["病机", "脉象沉弦，沉主里、主水，弦主饮、主痛，为水饮内停、阳气不运之征。原文谓“水饮不化，阳气不能旋运”，胃无通降之权，故脘痛呕吐涎水、饮食递减、股肉消瘦。此脉主停饮感寒、胃气上逆之呕吐脘痛。", ["沉", "弦"]], "7605": ["病机", "脉沉细，沉主里、细主虚，为水饮盘踞、中阳不旋之象。原文谓“水气不化，中阳不旋，中脘作痛”，呕吐虽暂定而饮邪未去，阳气不得宣通。此脉主脾阳不振、水饮内停之脘痛，故于温理中阳中稍寓攻逐。", ["沉", "细"]], "7606": ["病机", "脉行沉细，沉主里、细主虚，为脾土虚弱、水湿久停之征。原文谓“水久停，则脾土不能运旋，腐气因而阻痹”，故中脘时痛、大便六日不行。此脉主脾虚湿困、运化失职之脘痛便闭，治当再通阳气以化湿浊。", ["沉", "细"]], "7607": ["病机", "六脉濡软，沉候俱弦，右关尤甚，寸细尺沉，左尺小涩。濡软主脾虚湿困，沉弦主饮停肝旺，涩为营血不畅。原文谓“肝木纵横，挟内伏之痰饮，乘于土位”，木乘土位故痛甚于右、中宫窒塞。此脉主肝旺脾虚、痰饮内伏之证。", ["濡", "软", "弦", "涩"]], "7608": ["病机", "右关弦滑，左关仍弦，沉候有力，示肝木郁而犯土，土中有木，故食入必胀；弦为肝旺，滑为痰聚，沉候有力为邪实。虽高年久病，脉尚实，故可伐肝泻木，辛通化痰调气。", ["弦", "滑"]], "7609": ["病机", "脉象沉弦，沉主里主水，弦主饮主痛，痰饮内阻，肺气失降，故咳嗽痰多气逆，卧著尤甚；饮邪中阻，食入胀满。沉弦为饮邪内结之征，故宜温开饮邪。", ["沉", "弦"]], "7610": ["病机", "脉细沉弦，细为湿滞，沉主里，弦主饮主痛。寒湿之邪蔓延上中，三焦升降之机为寒痰所阻，故脘痞胸痛、咳甚气升、不能著卧、肌肤带肿。脉证合参，深恐升降不通而喘甚致脱。", ["细", "沉", "弦"]], "7611": ["病机", "脉形弦滑，弦为肝木不平，滑为痰气交阻。肺有伏寒，咳绵两载，复感凉燥，咳剧气逆；痰气交阻，土滞木郁，故中脘作痛、小腹胀满、大便不行。弦滑示痰气交阻、肝木不平之病机。", ["弦", "滑"]], "7612": ["病机", "脉象沉弦，沉主里主水，弦主饮主痛。停饮凝痰聚于胃府，胃气升多降少，故呕黏痰涎水、二便不利。沉弦为饮邪内结之脉，脾阳不运，清浊不分，故治以分利清浊、温药和之。", ["沉", "弦"]], "7613": ["病机", "左部柔和，右部沉弦而滑。沉弦为肝木失于条达，滑为痰水凝聚。木郁则土滞，土滞则痰水蓄积，及时而发，呕痰水倾盆，呕动胃络而带紫血。脉象示肝郁土滞、痰水内蓄之病机。", ["弦", "滑", "沉"]], "7614": ["病机", "脉细濡而右关滑，细濡为阴湿弥漫于下，右关滑为痰水聚于胸中。水停心下，阴湿上凌，心阳浮越，故心下虚悸。脉象示痰水内聚、心阳浮越之病机，非心营不足。", ["细", "濡", "滑"]], "7615": ["病机", "脉象沉弦，沉主里主水，弦主饮主痛。胃有停饮，胃阳不展，至暮辄作呕吐。沉弦为饮邪内结、胃阳不振之脉，久则恐延反胃之证。", ["沉", "弦"]], "7616": ["病机", "脉沉弦，沉主里、弦主饮主痛。原文谓“寒饮停于胃府，阳气窒塞不宣”，寒饮结聚中脘，故按之漉漉、自觉寒冷；阳气不达肢末头面，故肢厥畏风。沉弦正合饮邪内踞、阳郁不伸之机，症属停饮，故以温药和之为治。", ["沉", "弦"]], "7617": ["病机", "脉沉细濡软，沉主里，细濡软示脾阳不运、本质既亏。原文谓“痰饮根深，脾阳不运，津液凝滞酿痰”，痰阻肺下则喘咳，肺气不降、甲木上逆则眉棱骨痛。脉象虚软不任猛剂，故疏理痰气、取减轻而不期霍愈。", ["沉", "细", "濡", "软"]], "7618": ["预后", "脉沉弦，舌苔淡白，沉弦主寒饮内结。原文谓“寒湿痰交阻肺胃”，中脘结聚有形、食入痞阻、痰喘气逆，皆痰湿壅塞之象。带病感寒，邪气益张，故断“有喘脱之虞”，用桂枝加厚朴杏子汤以温散降逆，属预后警示之论。", ["沉", "弦"]], "7619": ["病机", "咳逆已止而脉象尚带沉弦，说明痰饮宿根未拔、脾阳未复。原文谓“脾为生痰之源，以阳为运”，沉弦仍主饮邪内伏、阳气不运，故续以补气助其鼓舞运旋，使脾阳振而饮自化，脉象可望渐和。", ["沉", "弦"]], "7620": ["病机", "脉沉弦，沉主里、弦主饮。原文谓“脾土为湿痰困乏，不能统血”，痰饮久踞中州，脾失统摄，故咯血；中州痞满、噫出腐气，皆湿痰困脾、气机壅滞之征。脉沉弦正应饮湿内结，故断“恐损而难复”。", ["沉", "弦"]], "7621": ["病机", "脉沉弦，主饮邪内伏。原文谓“饮邪泛逆，驾熟走轻”，痰饮日久，由喘转为呕吐，吐后神清，是饮随气逆上下走窜之象。沉弦示饮根深踞，故谓“势难杜截”，只能相机行事，属饮邪泛逆之病机。", ["沉", "弦"]], "7622": ["平脉", "脉缓有力，颇得充和，为胃气充足之象；右关稍滑，原文谓“痰湿亦属有余”，是脾湿偏盛而非病脉。大便溏乃中气鼓舞、湿有出路，与火衰脾泄迥异。寐醒口渴不引饮，是卧则气闭湿聚、阻遏清气上升，醒则气行湿散，故宜补气运湿。", ["缓", "滑"]], "7623": ["病机", "脉濡细而右部软滑，濡细示脾虚气弱、津液不布，软滑示伏有痰饮。原文引“饮入于胃，游溢精气”之论，说明脾虚气化失司则水精不布、聚为痰饮，发必致喘。故用苓桂术甘汤内饮治脾，又虑辛温久服伤阴，预筹和平中正之方。", ["濡", "细", "软", "滑"]], "7624": ["病机", "右脉濡滑，舌苔滑润，为湿痰内蕴之象。濡主湿，滑主痰，湿痰阻于中焦，脾阳被困，不能鼓舞运化，故见胃呆少纳、神情委顿；阳气敷布不周，则形体恶寒。此非外感，乃内伤湿痰，脾阳不展，故以六君加味健脾化痰。", ["濡", "滑"]], "7625": ["病机", "脉细弦，右大于左，左略细软且带数意，舌少苔、中心光红。细为阴血不足，弦主胃气不和，数则阴亏有热。病久胃气不复，胃阴连类而虚，阳明失于通降，故不纳不饥、恶心欲吐、痰黏而稠。此胃阴亏虚、虚热内扰之机，故拟甘凉益胃。", ["细", "弦", "数"]], "7626": ["病机", "舌见光红，脉见弦数，弦为胃气不和，数为有热，光红舌乃胃阴亏耗之征。此非人参益智半夏泻心橘皮竹茹等证，乃胃阴虚弱、虚热内生，故宜甘凉养胃。脉弦数在此提示胃阴不足、虚热内扰，与光红舌互参，胃阴之虚显然。", ["弦", "数"]], "7627": ["病机", "脉象沉弦，沉主里、弦主饮，为饮邪内伏之象。癖染日久伤气，气弱不能输运，聚饮生痰，上阻肺降，故咳嗽痰多盈碗。虽属饮象，每先干咳后痰多，是肺金渐燥，将成痰火之症。沉弦在此示饮停于里，气机不畅。", ["沉", "弦"]], "7628": ["病机", "脉象甚弦而带微数，弦主痰气冲逆，数示阴精不足有热。阴精亏于下，痰气凭凌于上，冲阳挟痰上升，故咳嗽痰多、寅卯为甚、心烦汗出。寅卯属木，肝阳升动之时，痰随阳升，故此时病剧。脉弦数正是阴亏痰逆、冲阳上扰之征。", ["弦", "数"]], "7629": ["病机", "脉象弦滑，弦主气郁，滑主痰聚。痰气交阻阳明，纳食中脘痞胀，诸气闭郁，上不得吐、下不得便，是痰阻气机、升降失司。口燥烦渴，火从气化，气由痰阻，郁而化火。弦滑之脉正示痰气交阻、郁火内生之机，故宜化痰开郁。", ["弦", "滑"]], "7630": ["病机", "脉象虚弦，右部濡滑。虚弦为肝肾空虚、阴精未复，中气复虚；濡滑为湿痰内蕴。旋运无权，湿痰难运，阻于肺下则气逆短促，趋于下则两胫肿胀。补肾镇纳不能化痰，肾欲纳而肺不降，故病不退。虚弦与濡滑并见，正合痰火之症，恐滋蔓难制。", ["虚", "弦", "濡", "滑"]], "7631": ["病机", "脉细弦而数，细为阴血不足，弦主肝强，数则有热。抑郁伤肝，肝强土弱，胃失通降，故食入胀满、漾漾欲吐；腹中偏右聚形、月事不行，往来寒热，是木旺太过、少阳机杼不转。胆为肝之外府，肝郁化热，故脉弦数。宜平肝调气，参以散郁。", ["细", "弦", "数"]], "7632": ["病机", "脉沉如伏，为肝强土弱已极、气机郁闭之象。原文述中脘有形作胀、腹笥胀大、肢肿面浮，是木郁土中、脾胃受侮；忽下利脓血、呕黑、四肢厥逆，乃肝气纵横逆扰，血不归藏，有发厥之虞。沉伏示邪闭于里、阳气不达四末，故主肝强土弱、气血逆乱之危候。", ["沉"]], "7633": ["病机", "脉稍起而细弦无力，较前沉伏稍起，示苦辛酸法后邪势略退，然细弦无力仍属阴虚木旺。原文气仍下坠、呕痰黑、目畏火光、溲赤舌干，是气火尽越于外；两足仍厥，为肝阳未平、阴血不足。细为阴亏，弦为木旺，无力则正气已馁，故主阴虚木旺、气火上越之机。", ["细", "弦"]], "7634": ["病机", "脉象细弦，承前阴虚木旺未复。原文四肢转温、面肿大退、胀减气平，是气火渐平；然便利不止、脓血复作，乃肝强土弱、营不收摄，湿热乘隙伤营。细弦为肝旺阴伤之脉，木旺则疏泄太过，营血失守，故主肝强土弱、湿热伤营之病机。", ["细", "弦"]], "7635": ["病机", "脉象细弦，仍属肝强土弱。原文脓血减少、便利较疏、胀松呕退，是参白头翁汤后湿热略清；然利仍不止、两足肿胀尤甚、有时恶心，示脾土未复、湿热伤营未已。细弦为木旺乘土之象，土弱不能制水，故肿胀难消，主肝强土弱、湿热伤营之病机。", ["细", "弦"]], "7636": ["病机", "本段未识脉名，纯论病机。原文述情志久郁、肝木失疏，冲脉属肝，起于气街夹脐上行至胸中而散，故气冲脘痞咽阻。此以冲脉循行解释郁结致气逆上冲之机理，主肝郁气逆、冲脉不降之病机，治法取舒郁结、苦辛降开。", []], "7637": ["病机", "脉细弦微滑，细弦为肝郁阴伤，微滑主痰浊内阻。原文情怀郁结、胸中阳气郁痹不舒、胸次窒塞、不纳不饥、耳胀头巅烙热、大便不行，是肝郁化火、痰气交阻胸膈。弦主郁、滑主痰，故主肝郁痰阻、胸阳痹塞之病机，仿胸痹例治。", ["细", "弦", "滑"]], "7638": ["病机", "脉细弦，苔白质红，为肝郁化阳、风木干土之象。原文情怀郁结、肝木失疏，肝阳冲侮胃土，致中脘有形、不时呕吐、眩晕不寐。细为阴血不足，弦为肝阳偏亢，木旺乘土则胃失和降，故主肝阳犯胃、风木干土之病机，拟两和肝胃。", ["细", "弦"]], "7639": ["病机", "脉两关俱弦，关候肝胃，两关俱弦示肝胃之气未和。原文气分攻撑稍平、聚形亦化、呕吐减、寐渐安，是前法获效；但胸中微痛、水谷作酸、眩晕带下，仍属肝阳犯胃、胃失和降。弦为肝旺之脉，故主肝胃欲和未和、厥阴阳明同病之病机。", ["弦"]], "7640": ["病机", "脉象沉郁，重取带弦，尺中无力，提示肝气郁结，木来克土，脾土不能运旋，故见上吐下泻、腹中有形攻筑、神情呆钝。沉郁为气滞，弦为肝旺，尺中无力为肾虚，木旺正虚，病机深重。", ["沉", "弦"]], "7641": ["病机", "脉象弦滑，按之少力，为厥阳犯脾胃，肝气挟痰上逆，胃浊泛动。弦主肝旺，滑主痰涎，按之少力为年迈正虚。故见呕吐痰涎、气逆至巅、便溏欲泄，治当先降胃府、和其中气。", ["弦", "滑"]], "7642": ["病机", "原文未直接描述脉象，但言“龙相不潜，冲脉不和”，结合“少腹有气上冲，至胸而散”，病机为冲脉之气上逆，龙相火不潜藏，冲脉起于气街并少阴上行，故见心中热辣、气上冲胸。", []], "7643": ["病机", "脉细关弦，细为营血不足，弦为肝阳偏亢。肝阳冲侮胃土，故中脘痞满、经络抽掣。治以育阴熄肝，参以调气，针对营血不足、肝阳上逆之病机。", ["细", "弦"]], "7644": ["病机", "脉形弦滑，重按空虚，弦滑为痰气内阻，重按空虚为血虚。胆火犯中，肝胃不和，挟痰内阻，故中脘不舒、呕吐痰涎。治当和中而泄胆木。", ["弦", "滑"]], "7645": ["病机", "原文未直接描述脉象，但言“脉象相安”，结合痰多中脘不舒、迷沉欲寐、呕吐胶腻，病机为木郁生火，木火扰中，水谷不化津气而凝浊成痰，阳明失通降，太阴失清肃，故呛咳痰多、咽干。", []], "7646": ["病机", "脉象弦滑，弦主气滞，滑主痰凝，痰气交滞于咽，故身热退而咽次仍然哽阻。治当清化痰气，以解痰气交滞之病机。", ["弦", "滑"]], "7647": ["病机", "脉弦大而数，舌红无苔满布裂纹，为木郁生火，肝火散越，灼烁阴津。弦大为肝火亢盛，数为热，阴津日耗，水源将竭，故内热不退、咽中热冲、头目昏晕。治以黄连阿胶汤救阴泻火。", ["弦", "大", "数"]], "7648": ["病机", "左脉弦大为肝阳化风鼓动之象，右脉濡细示脾胃气弱。唇口蠕动、舌强难言乃肝风犯脾，因脾胃开窍于口、阳明脉环口，风阳循经扰动，故脉弦大与濡细并见，主肝风乘脾之病机。", ["弦", "大", "濡", "细"]], "7649": ["病机", "脉细弦而数，细为阴亏，弦主肝旺，数属火动。水不涵木，冲气上逆，气火升动炼液成痰，故见少腹坚硬、先厥后热、痰涌苦厥。脉象反映肝阴不足、冲脉气火上逆之病机，恐致瘛疭发痉。", ["细", "弦", "数"]], "7650": ["病机", "脉形弦数，弦为冲气逆上，数为火化之征。冲气化火，煎熬津液成痰，痰火升扰则中脘聚形、恶心痰涌、头痛发厥。脉弦数紧扣气火上升、痰即有形之火之病机，主冲气逆上化火之证。", ["弦", "数"]], "7651": ["病机", "原文明言脉并不数，故脉象要素不取数。大便未行、灼热不退、寅卯之交振痉，乃肝胆之火内炽，火郁于里而未形于脉数，故脉不数。此段以脉不数反衬火郁之深，主肝胆火炽、势需暂排之病机。", []], "7652": ["病机", "脉象沉弦，沉主里、弦主肝。肝藏之气挟痰阻胃，胃气不降则肺气不能下行，故中脘不舒、胁胀碍食、气逆如喘。沉弦正合肝气挟痰内阻、胃肺气逆之病机，主肝胃不和之证。", ["沉", "弦"]], "7653": ["病机", "脉数软滑，数为火升，软滑主痰湿内蕴。甲木与戊土不降、乙木独升，木火上升则肌肤灼热，痰湿内滞则咽中牵腻。脉象反映木火升动兼痰湿之病机，故虑其损久不复。", ["数", "软", "滑"]], "7654": ["病机", "脉细弦而带微数，细为水亏，弦为木旺，微数属火。水亏木旺、肝风鸱张，风阳上旋则头昏目重，木侮胃土则中脘痛、虚里动跃，荣血不和则肌肤作麻。脉象紧扣肝升太过、胆降不及之病机。", ["细", "弦", "数"]], "7655": ["病机", "右寸小涩主肺金久损，关部带滑为痰，左寸关俱弦乃肝火。邪与痰合、肝火上犯，咳剧吐秽痰，脐上动跃为水邪干土。脉象反映肝火挟痰蒸肺、气阴皆虚之病机，主痰热阻肺之证。", ["小", "涩", "滑", "弦"]], "7656": ["病机", "脉细弦而数，细为阴血不足，弦主肝木气逆，数则阳热内动。陈子岩素患肝阳，冲气逆上，侮胃则胀痛呕酸𩠎杂，便闭苔黄，骨热皮寒，气逆短促，皆肝胃不和、冲阳上逆之候。脉弦数应木火内炽，细则阴分已伤，故虑其气冲不已，转成奔豚。", ["细", "弦", "数"]], "7657": ["兼症", "脉细弦，重按带滑，弦为肝郁络滞，滑主痰浊内蕴。前诊胀痛呕酸已止而便未行，痰气欲降无由，遂窜入络，季胁腰膂背肋痛而转侧不能，甚则发厥，吐稠痰方定。脉细弦见络气痹阻，带滑则痰浊未化，故恐复厥，议逐痰通府宣络。", ["细", "弦", "滑"]], "7658": ["病机", "脉弦滑而数，重按少力，弦为木火，滑主浊痰，数则火盛，少力示阴津受烁。便畅痛止为络滞暂通，然气逆如喘、胸闷酸涎、头昏眩晕，乃木火与浊痰相合蒸腾于上，消烁阴津，故舌苔黄掯干毛，恐起糜腐，法当清泄木火、化痰救津。", ["弦", "滑", "数"]], "7659": ["病机", "脉数较缓，数主火，缓为势减，是清泄化痰后木火稍平之象。然呛咳气升、季胁吊痛、闻食臭即𩠎杂头晕，乃厥气纵横之余威尚盛，气化为火逆犯肺金，消烁津液，水源不能涵木。若肝胆之火挟龙雷上逆，便成喘汗之局，故议滋水养肝兼泄气火。", ["数", "缓"]], "7660": ["病机", "脉细弦，细为阴津不足，弦主肝木气火。舌黄大化、渴减安谷，是津回胃醒；但气火不平挟痰上逆，肺当其冲，呛咳喘呼、欲寐不得、咽中燥痛，一派气火升浮之象。细弦正示水不制火，壮水之品又腻滞碍痰，故拟益水之上源，兼清泄气火、化痰热。", ["细", "弦"]], "7661": ["病机", "脉细弦，细主阴亏，弦为肝气。胃纳渐起、诸恙和平，而呛咳引动气即上冲、咽中微痛，乃肝经气火升浮，致上焦肺气不降、下焦肾阴不摄。细弦之脉应阴不涵木、气火不敛，故拟益肾水以涵肝木，使阴气收纳于下，略参化痰而不涉呆滞。", ["细", "弦"]], "7662": ["病机", "脉细弦，细为营分虚少，弦主风阳内动。湿痰素盛而每至春升神情迷倦、耳鸣如蝉、精神不振，舌心剥脱，是虽有湿痰而营分更虚，风阳乘春升上逆。细弦之脉正合营虚阳浮，故拟养营而不涉柔腻，使营充则风阳自潜。", ["细", "弦"]], "7663": ["病机", "脉虚弦，虚为肾水空乏，弦主肝阳上升。向有遗精，水亏不能涵木，肝阳扰神则心悸，外越则汗，上升则头眩耳鸣。虚弦并见，正是下虚上实、水不涵木之象，故非壮水不足以涵木，与遗精、悸、汗、眩、鸣诸症相应。", ["虚", "弦"]], "7664": ["病机", "脉弦而滑，弦主肝风，滑主湿痰。肝阳上升不熄，故眩晕目昏；风与湿相合，风主动摇，故四肢作酸、身如舟行。此脉象揭示肝风挟湿痰上扰之病机，主眩晕、身摇等症。", ["弦", "滑"]], "7665": ["病机", "脉象左弦，左关候肝，弦为肝脉。肝气抑郁，肝阳上扰，故中脘之下有形攻撑跳动，寤难成寐。此脉象说明肝郁阳亢之病机，主攻撑跳动、失眠等症，宜开怀颐养。", ["弦"]], "7666": ["病机", "脉象糊滑，关部带弦，滑主痰湿，弦主肝风。体丰湿痰素盛，熬夜劳神，阳不收藏，肝阳挟痰上升，故头昏眩晕、恶心欲呕、胸闷不舒。痰火交炽，恐风旋不熄而致发痉。", ["滑", "弦"]], "7667": ["病机", "脉细弦少力，细为血虚，弦为肝旺。产后血虚火炽，血不养肝，冲气肝阳逆上，故呕吐酸苦、口渴咽燥、气从上升、少腹满、中脘气冲。此脉示血虚肝阳上逆之病机。", ["细", "弦"]], "7668": ["病机", "脉细弦尺涩，细弦主肝阴不足、肝阳上扰，尺涩为肾阴亏虚。肝气化火劫烁阴津，营液不能营养，故筋骨作痛、眩晕心悸耳鸣、颧红火升、胸次窒闷。此脉示肾水亏而风木内动之病机。", ["细", "弦", "涩"]], "7669": ["病机", "脉象细弦，左尺小涩，右尺不藏，细弦为阴亏阳亢，涩为阴液耗伤。烦劳激动阳气，壮火食气，风阳乘虚入络，营血不能荣养筋络，故肩背腰膂股腨皆痛、火升心悸耳鸣头晕。此脉示阳火内燃、阴液消耗之病机。", ["细", "弦", "涩"]], "7670": ["病机", "脉象细弦，尺部带涩，细弦主阴亏阳亢，尺涩为肾精不固。阴分久虚，下虚上实，风阳上逆，故腹中极热、眩晕火升、精水不固。水亏木旺，此脉示肾阴亏虚、肝阳上逆之病机。", ["细", "弦", "涩"]], "7671": ["病机", "脉濡细，关弦尺涩，濡细为血虚，关弦主肝阳，尺涩为阴亏。血虚木旺，肝阳上升，故头胀眩晕、发则𩠎杂易饥、心神扰乱。此脉示血虚肝阳上扰之病机，治宜养肝和阳。", ["濡", "细", "弦", "涩"]], "7672": ["病机", "原文述“脉渐耐按”，指脉象由不耐按渐至耐按，反映正气渐复、脉有根底；然“头晕似有漂浮之意”，乃阳升不熄、虚阳上浮之象。脉虽渐和而症见浮晕，说明下元亏虚、制阳无力，故曰“当助其所以制伏阳气者”，主病机为阳升不敛、本虚标浮。", []], "7673": ["病机", "脉弦滑，弦主肝胆气逆，滑主痰湿内盛。体丰多湿，湿盛生痰，痰阻胸脘，胃气不降，胆木失降，遂成有升无降之局。症见呕吐、如坐舟中、目赤，皆胆中气火挟命阳浮逆于上所致。原文断为“中风之根”，强调痰气阻隔、升降失司为病机关键。", ["弦", "滑"]], "7674": ["病机", "脉由弦急转“稍柔缓”，是胃胆渐降、肝阳稍平之象，故“躯体之升浮荡漾，亦减于前”。原文指出水不涵木固令阳升，然“胃胆不降，亦能使之上逆”，说明此证病机不独在肝，更在胃胆失降。药后脉缓症减，示中焦通降得复，气逆自平。", ["缓"]], "7675": ["病机", "脉细弦滑，细为阴伤，弦主肝火，滑主痰浊。脘胁阻窒，肝火挟痰内阻，水火升降之道不通，坎离不相交济，故见火冲不寐、肌肤发疹、面目带肿。原文明言“肝火挟痰内阻”，痰火交阻、升降失司为本段病机核心，治宜清气化痰以通坎离。", ["细", "弦", "滑"]], "7676": ["病机", "原文未出脉名，然述“便血之后，血虚不复，肝阳上僭”，眩晕心悸、面浮肢肿、带下连绵、经事涩少，皆一派内亏见证。病机为血虚不能涵木，肝阳上僭，兼奇脉不摄。故拟“养肝熄肝，兼摄奇脉”，以养血平肝、固摄奇经为治。", []], "7677": ["病机", "脉细弦数，细为阴伤，弦主肝木，数则为火。风痰入络，肝阳暴升，肝气横逆，风木干犯胃土，胃阴暗伤，渐化为火，故发热头胀、不寐、口渴、便闭。原文谓“木犯胃而胃阴暗伤之象”，恐复致厥，病机为肝火犯胃、胃阴耗伤、木横土衰。", ["细", "弦", "数"]], "7678": ["病机", "脉弦滑，弦主肝阳，滑主痰饮。向有痰饮，肝阴不足，脾胃湿痰悉随肝阳鼓舞，君火为水气所干，以致心悸不宁、筋脉动跃、背脊寒冷、汗出。原文谓“摇撼震动”，病机为肝阴亏虚、痰饮上凌、水气干心，故无性命之忧而有频年之累。", ["弦", "滑"]], "7679": ["预后", "脉由弦大转柔，是肝胃阴伤渐复、阳土得和、风木不摇之象，故烦𩠎定、热退、面红转淡、苔腐化。原文以脉“转柔”为药应之验，断为“伏邪之后，肝胃阴伤”，并诫若再以蕴湿论治则阴愈伤热愈甚。此段重在凭脉判断转归，属预后。", ["弦", "大", "柔"]], "7680": ["病机", "脉弦虚大，右部歇止，弦为肝阳不潜，虚大为心肾交亏、水火不交之象。神气不能自持、言语错杂、健忘善悲，皆由心肾亏虚、肝阳上扰所致。八秩大年，脉证相符，故言“何敢言治”，示病机深重。", ["弦", "虚", "大"]], "7681": ["病机", "脉象沉涩，右关独弦，沉涩主气血滞涩，右关弦为肝气失疏、肝阳逆犯。左腹积聚、心悸耳鸣、四肢烙热，皆肝阳不敛、阳气未能遽敛之征。食不馨增、肢体困乏，乃胃气不和。故拟和中醒胃，兼养肝阴，阴生则阳自长。", ["沉", "涩", "弦"]], "7682": ["病机", "脉象弦滑，弦主肝风，滑主痰热。神昏不语、喉有痰声、脘腹饱满、头汗溱溱，皆肝风挟痰上升、清窍蒙闭之候。舌红苔黄、中心霉黑，湿热熏蒸于上。唇口蠕动，风阳震动。故断为痰火蒙闭于内，恐致厥脱，勉拟清泄痰火、芳开蒙闭。", ["弦", "滑"]], "7683": ["病机", "脉细弦数，细为营阴不足，弦数为肝火风上旋。头痛、口眼㖞斜、舌强言謇，乃风火蒸痰，袭入少阳阳明之络。脉证合参，病机为风火痰热阻络，故拟化痰平肝泄热。", ["细", "弦", "数"]], "7684": ["病机", "脉细而沉取弦搏，细为阴伤，沉取弦搏为肝火风震撼、痰热内结。心悸不寐、肉𥆧筋惕、肢震头摇，皆风火痰相煽之象。苔浊厚腻，津液凝痰，痰转化热，与风火彼此相煽，故有莫御之势。拟化痰熄风，参以宁神镇肝。", ["细", "弦", "搏"]], "7685": ["病机", "脉象弦滑，弦主风，滑主痰。仍筋惕肉𥆧、悸眩不寐，舌苔腻浊，知痰火风鼓旋不熄。前诊化痰熄肝，脉证相安，而痰风未靖，故再化痰熄肝，以竟其功。", ["弦", "滑"]], "7686": ["病机", "脉细而沉取带滑，细为气弱，滑为痰凝。头眩旋晕、心悸火升不寐、痰多𩠎杂，皆气弱生痰、胆胃不降、肝木独升之候。故欲平肝当降胆，欲降胆当降胃，欲降胃当化痰，层层相因，病机昭然。", ["细", "滑"]], "7687": ["病机", "脉象弦滑而濡，弦滑为痰风内动，濡为正气虚。神识迷乱、两手引动、频转矢气、大便不行，由气滞不宣、浊痰弥漫、神机被阻、胆阳上逆、风阳勃动所致。病实正虚，恐成昏痉喘厥之虞，故疏府涤痰势不容缓。", ["弦", "滑", "濡"]], "7688": ["病机", "脉弦滑而舌苔满布白腻，渴不欲饮，是浊痰弥漫、蒙阻清窍之象。弦主痰饮气郁，滑主痰湿壅盛，痰积虽得呕出畅解而脉象未变，说明痰浊仍弥漫未清。年及古稀正虚病实，虽神识转清、脘胁胀松，仍恐化痰不尽、郁而化燥生风，故以化痰宣泄气火为治。", ["弦", "滑"]], "7689": ["病机", "原文以「阳明脉络失和」言病机，未列具体脉象要素。四诊后右脉稍觉有力、舌苔大化，为痰积渐达、气火稍泄之转机；然火时上升则两颧红赤，胃土少降则恶心，胆阳上逆则遍身作痛。故知痰积虽达而胃降未复，阳明络脉失和，胆阳循经上逆，治当降胆胃、化痰浊。", []], "7690": ["病机", "脉弦滑而舌苔根尚厚腻，是痰邪未清之征。弦主肝木、滑主痰浊，痰浊留恋则呛咳痰多；甲木少降、肝风上旋，则头旋眩晕、目不能开；风痰阻痹络气，则胸膺背肋牵掣作痛、胸中似有冷物搏聚。故以化痰熄肝宣络为治，紧扣「痰邪未清」四字。", ["弦", "滑"]], "7691": ["病机", "脉象弦滑，为胆胃之气未降、痰气郁结之象。六诊后遍身掣痛已定、眩晕大减，是风阳渐平、脉络自和之征；惟胸中窒闷、呛咳痰多，说明肺胃之间痰饮不能遽澈。弦滑不去则痰气之郁未开，故仍须和中降气化痰，使胆胃下降而风阳自平。", ["弦", "滑"]], "7692": ["病机", "脉弦滑而软，弦滑为痰热未清，软为阳明脉络空虚之象。神渐守舍、怔悸大减，是清化痰热育阴之效；然虚里仍然动跃，说明厥阳上扰未熄。脉软提示正气不足、络脉空虚，故不能一味清化，当于前法中加入育阴和阳，使虚里动跃得平。", ["弦", "滑", "软"]], "7693": ["病机", "脉象虚弦，虚为液亏、弦为肝阳不潜。腹时㽲痛、眩晕头昏、心中跳荡，皆肝木升腾、阳气不熄之症；带下舌光，尤见阴液亏虚不能涵养肝木。液虚则木失滋荣，阳气因而升腾，故治拟平肝熄风木，以涵养为根本，非单纯镇潜可解。", ["虚", "弦"]], "7694": ["病机", "原文仅言「经脉跳动」，属描述性脉象，未列具体脉象要素。热气随处攻注、经脉跳动、脘胁皮肤板滞，是木旺阳升、气滞不行之象。气滞则热郁，热郁则经脉跳动不宁，皮肤板滞亦气机不畅所致。故治以和阴涵肝木、兼化热痰，使阳升得平而气滞自通。", []], "7695": ["病机", "脉象细软，细为阴亏、软为气虚，正合脾气胃阴并虚之候。大便解出黏痰、烦扰宁静，是结痰稍开；然日晡复烦渴、涕泪俱无、头摇面青、舌光无苔，皆胃阴亏耗、肝风震动之象。细软之脉见于慢惊，提示正虚风动，仍在险境，故培脾土养肺胃之阴以熄肝木。", ["细", "软"]], "7696": ["病机", "脉象细数，细为阴血不足，数为虚热内扰。原文谓'阴虚气弱，木旺生风'，惊搐虽定而涕泪不下、上下唇干燥，正是阴津未复、肝木化风之象。细数脉应此阴虚内热、风动未息之机，故断为阴虚气弱、木旺生风，治当从效方扩充以滋阴柔肝。", ["细", "数"]], "7697": ["预后", "脉亦柔缓，柔缓为胃气渐和、肝木已平之象。原文述扶正御肝、益荣涵木后，风木已平、惊搐不发、津回涕下、面青退而脉转柔缓，说明慢惊属虚，经治后正气渐复。脉由急劲转柔缓，是病退向愈之征，然原文又辨阳衰阴弱，提示虚证尚需分阴阳调治。", ["缓"]], "7698": ["病机", "左脉弦大为肝阳上亢，尺部空虚为肾阴亏于下，合之即'下虚上实'。原文眩晕不定，正因下虚不能涵木、肝阳化风上扰。弦大见于左关，主肝经气火；尺部空虚则根本不足。脉象直接点明上实下虚之病机，故拟介类潜阳，为进一层治。", ["弦", "大", "虚", "空"]], "7699": ["病机", "脉象细弦，细为肾水不足、阴血亏虚，弦为肝经气横、风阳内动。原文谓肾水不能涵养肝木，肝气横扰则腹胀胸闷，风阳上旋则眩晕，牙龈胀痛亦属风阳阻于胃络。细弦脉正应水亏木旺、风阳上扰之机，故宜柔养以滋水涵木、柔肝熄风。", ["细", "弦"]], "7700": ["病机", "脉弱而弦，弱主正气不足、气血亏虚，弦主肝气郁滞、阳升不降。原文但寒不热、腹满作痛、头昏目眩、饮食少思，正是气滞于下、阳升于上之候。弱为脾虚气弱，弦为肝木偏旺，合示土虚木乘、气机升降失司，故宜调气熄肝以复升降。", ["弱", "弦"]], "7701": ["病机", "脉细濡而右关带滑，细濡为阴津不足、阳气不布，右关滑主痰浊内蕴。原文谓清津为阳气所炼、渐欲成痰，浊阻清位，故昏晕不定、有时汩汩作酸。脉象揭示阴虚阳扰、痰浊渐生之机，昏晕非纯虚所致，乃清浊相干，故再以退为进，化痰育阴并施。", ["细", "濡", "滑"]], "7702": ["病机", "脉滑主痰浊内盛，苔腻为湿浊上泛之征。原文眩晕呕吐、舌本牵强、火升右太阳作痛，明言'肝阳挟痰上升'。滑脉应痰，肝阳化火挟痰上扰清窍，故眩晕呕吐；痰阻经络则舌本牵强。脉滑苔腻正是痰浊内蕴之据，故宜化痰熄肝，痰去则阳潜晕止。", ["滑"]], "7703": ["病机", "脉象沉弦，沉主里、主饮，弦主肝、主痛。原文白疹已化、热渐轻，而四肢欠温、痰多频咳、热冲至巅则头昏眩晕，明言痰饮内阻、阳气不克宣通，'无痰不作眩'。沉弦脉正应痰饮内伏、阳郁不伸之机，饮阻则阳不达四末而肢冷，痰逆则眩，故拟化痰通阳。", ["沉", "弦"]], "7704": ["病机", "脉沉弦而左部细弱，沉主里、弦主饮，细弱为虚。原文谓“脾胃肾皆虚，气不收摄”，痰多咳逆气喘正因中下虚寒、水饮上泛、摄纳无权，故脉见沉弦细弱，治拟摄纳阳气，以复气机升降之常。", ["沉", "弦", "细", "弱"]], "7705": ["预后", "脉细涩如丝，细为阴血亏少，涩为血行不畅，正合“营血久亏，肝木失养，风阳大动”。阴血既竭，阳无所附，故痉厥频作、神识昏迷，原文断为“深有阴阳相决之虞”，示阴竭阳越、预后凶险，非寻常痉厥可比。", ["细", "涩"]], "7706": ["病机", "脉象虚微，虚为气不足，微为阳衰微。痉厥后身发白疹，乃“病久中虚之极”，气阴两伤而虚阳浮动，故屡次发热。原文谓“阴不足而阳有余”，即阴亏不能敛阳，脉虚微正是气阴耗损、阳失潜藏之象，故治当气阴兼顾。", ["虚", "微"]], "7707": ["病机", "脉弦而滑，弦主肝风，滑主痰浊。原文谓风阳大动、甲木不降，胆失决断而惊悸善恐，有形之痰随之上逆鼓动，故脉见弦滑，舌红苔黄浊亦痰热之征。此脉象揭示风痰内扰、胆胃不和之病机，治拟化痰宁神、潜阳熄肝。", ["弦", "滑"]], "7708": ["病机", "脉尺涩关弦，尺涩为下焦阴血不足，关弦为肝阳偏亢。原文谓“厥阳上升太过”，气冲咽喉、呛咳呕吐、色夺出汗欲厥，皆厥阳上逆、气血不降所致；厥后耳鸣头晕，亦阳升风动之象。脉象正合下虚上实、厥阳上升之病机。", ["涩", "弦"]], "7709": ["病机", "脉数弦大，数为热盛，弦大为火风鼓动、邪实气张。原文谓醉酒蕴热，又逢君火行令，心火肝阳为之鼓动，火风热内闭，致神昏口噤、搐搦发痉、目赤颧红便闭。脉数弦大正是火风热内炽、厥症急险之征，故急应泄热降火、通络窍。", ["数", "弦", "大"]], "7710": ["病机", "脉数濡滑，数为热，濡为湿，滑为痰。原文谓邪湿内蒸，浊痰悉化为火，灼伤肺胃阴津，故见汗出、讝语、肢搐、咽痛白糜。脉数濡滑正示湿热痰火交蒸、阴分愈亏之机，舌绛苔黄灰亦相合，故有虚脱之虞，治拟泄热和阴。", ["数", "濡", "滑"]], "7711": ["病机", "原文未识脉名，仅言“脉左尺不藏”，左尺候肾，不藏即肾失封藏、龙相火动。脾肾两亏则饮食生痰，痰凭木火之势化热，竟夜不寐，苔黄舌红，皆阴虚阳亢、痰热内扰之象。此段以尺脉不藏点出龙相妄动、本虚标热之病机，治拟潜阳和阴兼苦泄。", []], "7712": ["病机", "左关候肝，脉滑主痰。素体痰多，交夏君火行令，火与痰合，痰浊弥漫心窍，故言语不能自如、健忘胃钝。神识虽清而左关脉滑，正说明痰阻于中焦，心肾气机不相交通，祛浊痰则心肾自交。", ["滑"]], "7713": ["病机", "脉象虚弦，虚为中气不足，弦为肝木偏旺。中虚挟痰，痰热化风，撼扰神舍，故心中跳动、火从上升。虚弦之脉说明下虚而上扰，填补其下以涵濡肝木，反碍在上痰热，故惟用介类潜阳，使虚风得潜、痰热不升。", ["虚", "弦"]], "7714": ["病机", "左寸沉滞、关部细弦、尺中小涩，右寸滑濡软、关滑带弦、尺较劲，皆中气脏阴亏虚、挟痰内蔽之象。产后未满百日，血虚气弱，肝木偏亢，厥阳上旋，清津浊液被阳气炼结成痰，心火不能下降，心胸转为阳火燔蒸之地，故窒闷、神呆、恐怖。", ["沉", "滞", "细", "弦"]], "7715": ["病机", "前诊脉细弦而不洪大，与虚里跳动相应，断为中气虚不能制木、魂不安谧。服攻劫大吐大下后，右部脉转滑微大，寸脉依然细滞，说明肝郁气结，由胠胁蔓及虚里，气郁则痰滞，痰踞机窍要地，阻神明、乱魂魄，故神志未灵。", ["细", "弦", "滑", "大"]], "7716": ["病机", "脉滑主痰湿内盛。头胀眩晕、火升、频带燥渴、痰多，是痰湿化火生风之候。滑脉说明痰浊内蕴，与阴虚阳亢之脉象不同，故治疗当从化痰湿、清火风着眼，而非单纯滋阴潜阳。", ["滑"]], "7717": ["病机", "两关候肝脾，脉弦滑为肝火挟痰之象。多言呼唱、未能寐、腹中气满不舒，是肝火挟痰内扰，肝经之气散漫不平，心神为之摇撼。药后稍定，脉仍弦滑，说明痰火未清，再守化痰护神之意。", ["弦", "滑"]], "7718": ["病机", "左脉候肝胆，弦大为肝胆火旺之象。痰火交炽，曾经糊乱，今神识虽清而左脉弦大，说明肝胆之火尚未宁静，痰火余焰未息，故脉象仍见弦大，当继续清降肝胆痰火。", ["弦", "大"]], "7719": ["病机", "脉象濡细，为气阴已亏之象。向有痰饮，复感风温，风化为火与痰相合，痰火交炽，肺肾之气不能相通，故气喘难卧、痰声漉漉、烦闷、颧红。脉濡细而痰火独盛，说明正虚邪实，草木难以为功，勉拟育阴化痰以通肺肾。", ["濡", "细"]], "7720": ["病机", "脉滑主痰，原文“痰多脉滑”即痰湿内盛之象。由湿生痰，痰郁化火，火盛生风，故痰为火之本，风为火之媒。脉滑反映痰浊壅滞，与中脘渐舒但痰多相应，提示病本在痰湿，治当求本。", ["滑"]], "7721": ["病机", "脉滑主痰，脉弦主肝阳。原文“脉滑而弦”伴神情昏愦、言语无伦、唇朱兼紫，显系痰火与肝阳交炽，上扰心神。滑为痰火内盛，弦为肝阳亢逆，故拟泄热化痰以平交炽之邪。", ["滑", "弦"]], "7722": ["病机", "六脉弦数，弦主肝，数主火。原文“怒火如狂”乃肝火扰攘，心神不宁。弦数并见，说明肝火亢盛，内扰心神，故拟护神化痰熄肝，以清肝火、宁心神。", ["弦", "数"]], "7723": ["病机", "脉弦带滑，弦为肝阳上亢，滑为痰湿内蕴。原文头痛偏右、痰带红、眩晕心悸，乃肝肾阴精不足，脾胃痰湿有余，胆胃不降，肝阳上升太过。弦滑相合，正示阴亏阳亢、痰湿上逆之机。", ["弦", "滑"]], "7724": ["病机", "左关脉大，左关候肝。原文“阴涵不足，阳升有余”，脉大乃肝阳亢盛、阴不涵阳之象。虽寐安轰热减，仍头偏作痛，说明阳升未平，故前法再参和阴，以涵阴潜阳。", ["大"]], "7725": ["病机", "脉象细弦，细为阴分不足，弦为阳气不潜。原文“热气时从上冲”，正是阴亏于下、阳浮于上之征。细弦并见，示阴分不足而阳气不潜，故前法再进一筹，育阴潜阳。", ["细", "弦"]], "7726": ["病机", "脉濡缓微滑，濡缓主湿，滑主痰。原文苔白厚腻，头痛眩晕，乃肝阳挟痰上腾。濡缓微滑反映痰湿内盛，肝阳乘之上升，故拟熄肝化痰，以平上腾之痰阳。", ["濡", "缓", "滑"]], "7727": ["病机", "脉象细弦，细主阴亏，弦主阳亢。原文引经云“头痛巅疾，下虚上实”，原因肾水内亏，阳气上冒。细弦正合下虚上实之机，故再拟育阴潜阳，以补下虚、潜上冒之阳。", ["细", "弦"]], "7728": ["病机", "两关脉弦，关候肝胆与脾胃。弦为肝木之象，木旺则克土，少阳胆火与阳明胃气皆失和降，故头晕渐致作痛、痛引耳后、恶心欲吐。脉弦在此提示少阳阳明不降，气火上逆之病机。", ["弦"]], "7729": ["病机", "脉象细沉，久按带弦。细沉主里虚，弦为水寒脉道不利。原文谓“痰湿遏伏，则水寒而脉道不行”，脑为髓海，痰湿水类上遏，故头痛连脑、遍身经络抽掣。脉细沉带弦正是痰湿遏伏、水寒脉道不行之象。", ["细", "沉", "弦"]], "7730": ["病机", "脉缓而关部仍弦。缓为脾土之常，关弦独见，知肝木火风未熄。前投清震汤痛势随退，但脚膝腿股刺痛，乃火风流窜经络。脉弦不去，说明木火之势虽挫而根未除，犹恐上腾致变，故拟清泄以锉其锋。", ["缓", "弦"]], "7731": ["病机", "脉微数，右关带弦。微数示胃气未苏而有余热，右关弦乃肝木乘侮胃土之征。头痛之余，肝木未平，胃土受侮，阳明失通降之权，故不食、头晕、吞酸恶心、中脘气攻、腹中㽲痛。脉象正合肝胃不和之机。", ["微", "数", "弦"]], "7732": ["病机", "脉数，重按细弦，轻取微浮。数主热，细弦为火郁于内，微浮示风火之余威窜络。原文谓“火足以乱我神明”，故痛甚讝语；风火游行甚速，故遍体作痛。脉象与风火窜络、余烬未消之证相符。", ["数", "细", "弦", "浮"]], "7733": ["病机", "脉形尺涩。尺候下焦肝肾，涩主血少气滞。向有胃痛、偏左腹硬，是肝气郁结；头痛右甚引目痛，乃肝火风上旋。尺涩说明下焦阴血不足，不能涵木，致肝火风上扰清窍，故宜清以泄之。", ["涩"]], "7734": ["病机", "脉弦尺涩。弦为肝火风未熄，尺涩为下焦阴血不足。偏右头痛引及目珠、辛劳则咽中燥痛，皆肝火风上扰、阴血亏虚不能濡养之象。脉弦尺涩正示“养不足之阴，泄独胜之热”之病机所在。", ["弦", "涩"]], "7735": ["病机", "脉洪大稍敛，关脉仍弦。洪大为火热之象，稍敛知痛减而火势略挫；关弦独存，是肝火风未能尽平。厥气附和，气上冲咽、寤难成寐，皆肝火未熄、厥气上逆之故。脉象说明前法虽效，仍须再参调气。", ["洪", "大", "弦"]], "7736": ["病机", "脉细涩为阴血不足、脉道不利，左部带弦乃阳气郁而不潜，肝阳上扰。头痛仍盛、呕吐咳逆，皆阳气未能下潜、上逆犯胃冲肺所致。细涩示阴亏，弦主肝旺，故病机为阳气不潜、阴血亏虚。", ["细", "涩", "弦"]], "7737": ["病机", "右脉弦大为风邪鼓动之象，阴分素亏则肝木失养，外风引动内风，上扰清窍。头痛在额、鼻窍不利，为风阳上攻。弦主风、主肝，大示邪盛，故病机为阴亏风动、内外合邪。", ["弦", "大"]], "7738": ["病机", "脉沉弦为中阳不足、寒浊内阻之象。沉主里、主阳虚，弦主痛、主寒饮。中脘有形作痛，乃寒浊阻于胃府，阳气不运，气机凝滞。故病机为中阳式微、寒浊内结。", ["沉", "弦"]], "7739": ["病机", "脉沉弦细为痰气郁结、阳气不宣之候。沉主里，弦主气郁饮停，细示正气不足。苔白罩霉、食入痞阻，皆痰气壅滞胃中、宣通失职。故病机为痰气交阻、胃失和降。", ["沉", "弦", "细"]], "7740": ["病机", "苔霉全化、中脘渐舒，示痰气稍解，然脉尚带沉弦，说明痰气郁结未彻，肝胃未和。沉弦为气郁饮停之根未除，故需肝胃两和、疏通痰气，防其复聚。病机为痰气未尽、肝胃不和。", ["沉", "弦"]], "7741": ["病机", "关滑主饮停于中，沉候濡缓为脾虚湿困之象。饮停于内则土滞，土滞则木郁，故中脘作痛、呕吐、寒热交作。滑为饮，濡缓为虚湿，病机为饮停土滞、木郁不达，难杜根株。", ["滑", "濡", "缓"]], "7742": ["病机", "脉形细弱为先天不足、气弱失运之征。气弱则生寒，运迟则生湿，寒湿交阻，故背腧作胀、中脘作痛、不纳不饥。细弱主虚，病机为气弱寒湿交阻、运化失职，急则治标。", ["细", "弱"]], "7743": ["病机", "脉沉弦为寒饮停阻胃中之象。沉主里、主水饮，弦主痛、主寒。寒饮内停，胃气上逆则呕吐涎水，气机凝滞则中脘胀痛。恐致痛厥者，乃寒饮闭阻、阳气不达。病机为寒饮内结、胃阳被困。", ["沉", "弦"]], "7744": ["病机", "脉两关俱弦，关候中焦，弦主气郁、主痛。原文谓“厥气挟痰，阻于胃府”，厥气上逆，痰浊内阻，胃府气机壅滞，故中脘作痛、腹满气撑、便阻不爽。气痰久郁，胃失和降，渐成噎膈之变。", ["弦"]], "7745": ["病机", "脉形弦滑，主痰气内阻；独尺部濡细而沉，尺候下焦，濡细沉为命火衰微之象。原文谓“在下之蒸变无力，在上之痰气停留”，火不蒸腾，痰气凝滞中脘，故痛而遍体作酸，胃病不能束筋骨利机关。", ["弦", "滑", "濡", "细"]], "7746": ["病机", "脉细关弦，细为血少，关弦主木郁。原文谓“木郁土中，中脘作痛”，肝气郁而化火，冲侮胃土，故胃脘烘热。此肝火犯胃之机，治宜条达木气，开展襟怀。", ["细", "弦"]], "7747": ["病机", "二诊脘痛止、胸闷呕吐减，而两关脉弦未退。关脉候肝胃，弦为肝气偏旺。原文谓“还是肝阳犯胃未平”，说明虽症减而病机未除，肝阳仍犯胃土，故脉象未和。", ["弦"]], "7748": ["病机", "左胸痛而脉弦，弦主气郁、主痛。原文谓“当舒气郁”，胸中气机郁滞，不通则痛，故脉见弦。治以颠倒木金散法加减，舒气解郁，气畅则痛止。", ["弦"]], "7749": ["病机", "脉象沉弦，沉主里、主水饮，弦主饮癖、主痛。原文谓“饮悬胁下，脾肺之络在右也”，水饮悬积胁下，络脉不和，故右胁作痛。沉弦为饮停于里之征。", ["沉", "弦"]], "7750": ["病机", "左脉弦大，右关带滑。弦大为肝气横逆，滑为湿痰内蕴。原文谓“气湿郁阻不宣”，胁下痛仍不定，乃气湿交阻，络脉不通。再为宣通，使郁开湿化。", ["弦", "大", "滑"]], "7751": ["病机", "脉形濡细，濡主湿、细主虚。原文谓痰湿气三者互聚，阻隔脾肺道路，升降开合之机皆阻，故右胁痛甚、中脘板滞、呃忒气坠。然脉见濡细，正气已虚，病实正虚，深恐呃甚发厥汗脱。", ["濡", "细"]], "7752": ["病机", "脉沉主里主寒，此案腹痛而脉沉，原文直断为“气寒而肝横也”。寒邪客于肝经，肝气横逆，气机凝滞不通，故腹痛。沉脉应里，说明病位在里，非表邪所致；寒性收引，肝失疏泄，横逆犯中，故以沉脉示气寒肝横之病机。", ["沉"]], "7753": ["病机", "脉形沉细，沉主里、细主虚，示病在里而正气不足。原文言“木失条达，东方之生气，挟肠胃之湿热，郁而生虫”，前年大便解出长虫，是肝失疏泄、湿热郁蒸生虫之征。沉细脉应里虚，虫积日久耗伤气血，故脉不任按而细，治以调气温中兼劫虫。", ["沉", "细"]], "7754": ["其他", "原文未识出脉名，仅言“脉症相安”，说明脉与症俱较前诊为平，无突出脉象可录。腹痛仍未全定，是余邪未尽、气机未畅。脉症相安提示前法已效，故“前法进退，以图徐愈”，属守方缓图之诊，非另立新脉机。", []], "7755": ["病机", "脉细虚软，细主阴血不足，虚软主正气亏弱。原文言“冲脉布散胸中”，今痛从少腹上冲日久不止，显属“奇脉空虚，厥气肆扰”。冲脉为血海，空虚则气无所附，厥气自下上逆，故脉细虚软而布散无力，主奇脉空虚、冲气上逆之病机。", ["细", "虚", "软", "散"]], "7756": ["病机", "脉象虚弦，虚为营血亏虚，弦为肝风内动。原文述胁痛吐下皆血，血去之后“络隧空虚，风阳入络”，致胸膺腰膂两胁皆痛、时或眩晕。血虚不能濡络，肝阳化风窜络，故脉虚而弦，主阴血亏虚、风阳入络之病机，治宜育阴熄肝、养营和络。", ["虚", "弦"]], "7757": ["病机", "脉形沉细，沉主里、细主虚，示病在肝肾而正气不足。原文断为“肝肾虚而湿寒乘袭”，右腰府作痛。腰为肾之府，肝肾亏虚则寒湿乘虚客之，沉细脉正应里虚寒湿内侵之象，故主肝肾虚而湿寒痹阻之病机。", ["沉", "细"]], "7758": ["病机", "原文未识出脉名，从症测机。痛胀退而复甚、腰膂作酸、大便不调，原文谓“痰湿之闭阻虽开，而肝肾之络暗损”。标证虽减，本虚已露，故宜“舍标治本，而通和奇脉”，主肝肾络损、奇脉不和之病机，非以脉断。", []], "7759": ["其他", "原文未识出脉名，仅言“脉症相安”，示脉与症均较前诊平稳。惟腰府仍酸、大便涩滞，原文归为“营络不和”，是通和奇脉后余邪未净、营络未畅。脉症相安说明前法合度，故“前法进退”，属守方调理之诊。", []], "7760": ["病机", "原文未载脉名，仅言「脉症相安」，说明脉与症无相违逆，病势尚稳。然「腰府作酸」而断为「络虚气滞」，是据症推机：腰为肾府，络脉空虚则气行不畅，滞而作酸。脉症相安提示正未大伤、邪未鸱张，故可守效方扩充，缓图络虚气滞之复，非急症危候。", []], "7761": ["病机", "左关候肝，脉左关弦，是肝木偏旺之象。原文谓「脾虚木旺，木侮胃土」，木郁土中，肝气横逆犯胃，故中脘作痛、甚则呕吐；脾受木侮，运化失司，故大便时泻时止。弦为肝脉，郁而不达则弦，久延恐成膈证，正合「木郁土中」之论。", ["弦"]], "7762": ["病机", "两关俱弦，关候肝脾，弦为肝木之脉。原文断为「肝阳冲侮胃土」，肝阳偏亢，冲逆犯胃，胃失和降，故食入辄作呕吐。两关俱弦说明肝脾同病、木土相争，久则胃气受戕，恐成膈证，故拟苦辛通降以平肝降胃。", ["弦"]], "7763": ["病机", "二诊「脉弦稍平」，较前弦势已减，故「呕吐略减」，说明肝阳逆犯胃土之势稍缓。弦为肝脉，稍平即肝阳渐敛之征，然仍未尽平，故断「的属肝阳逆犯胃土」，续用和中镇逆、苦降辛开，使肝胃渐和，脉症相应可参。", ["弦"]], "7764": ["病机", "沉脉主里主水，弦脉主饮主痛。脉象沉弦，是水饮停聚于里之象。原文谓「水饮停聚胃府」，饮邪内踞，胃气不通，故中脘作痛、甚则呕吐。沉弦并见，说明病位在里而饮邪结聚，故治当「缓以攻之」，不可峻下伤正。", ["沉", "弦"]], "7765": ["病机", "二诊呕吐不止、中脘板滞，脉仍沉弦。沉主里，弦主饮主痛，脉象沉弦说明痰饮之邪仍阻于胃府，不能通降。前诊攻之而未解，故断「还是痰阻胃府」，中脘板滞即痰阻气机之征，再拟苦辛开降、芳香化浊以化其痰浊。", ["沉", "弦"]], "7766": ["病机", "脉象沉弦，沉为在里，弦为饮为痛。原文谓「胃有停痰，胃阳不展」，痰饮内停，阳气不布，胃失和降，故至暮辄作呕吐。暮时阳气渐衰，痰饮愈阻，故呕吐定时而作。沉弦示痰饮结聚在里，久则胃阳愈困，恐延反胃之证。", ["沉", "弦"]], "7767": ["病机", "原文未载脉名，仅言「脉证相安」，示脉与症相应而无败象。至暮腹满、酸水上涌，断为「营滞不行，土郁湿困」：营血滞涩则气机不畅，土受湿困则运化失职，暮时阳衰湿滞愈甚，故腹满酸涌。脉证相安说明病势尚缓，「不能急切图功」，当缓调营滞、化湿运土。", []], "7768": ["病机", "脉濡为湿象，左滑主痰。原文谓“肝阳挟痰上冲胃土”，濡滑相合，正示痰湿内蕴、肝阳化风上扰。头痛眩晕、呕吐涎水乃风痰上逆之症，腰胁酸楚则肝络失和。脉象与症候互参，病机在肝胃，痰浊随风阳上冲，故脉不弦劲而见濡滑，是痰湿偏盛之征。", ["濡", "滑"]], "7769": ["病机", "脉象虚弦，虚为胃液暗亏，弦乃肝木横逆。原文言“肝木横逆之余，胃土有升无降，阳明之液暗亏”，呕吐蛔虫、口渴频饮、舌苔糙白，皆胃阴耗伤、肝气犯胃之候。虚弦并见，说明正虚而邪实，肝逆未平，胃液已亏，故有呃忒致厥之虑。", ["虚", "弦"]], "7770": ["病机", "两关俱弦，关候肝胃。原文谓“肝气不和，乘于胃土，胃中之阳气不能转旋”，食入哽阻、涎沫上涌，正是肝气犯胃、胃阳不旋之噎膈。年逾花甲阴液已亏，弦脉主肝旺，亦示胃气受遏。此非寻常噎膈，乃肝胃同病、本虚标实之候。", ["弦"]], "7771": ["病机", "脉细关弦，细为阴血不足，关弦主肝火内燃。原文言“肝火内燃，致胃阴亏损，不能柔润”，故食不得入、寐醒燥渴、舌红苔黄心剥。津液凝滞酿痰，痰多则津液愈耗，脉细弦正合肝火灼阴、胃失柔润之机。条达肝木、泄气火以保津液，即针对此病机。", ["细", "弦"]], "7772": ["病机", "原文未识脉名，仅言“脉滞”，属描述性脉象，故脉素取空。嗜饮损伤中阳，气不施化，食入哽阻、痰涎上涌、苔白质腻，皆中阳不振、痰湿内停之象。脉滞示气机壅塞、痰湿凝阻，与噎膈重证相应，病机在脾胃阳虚、气化不行。", []], "7773": ["病机", "两关弦滑，关主肝胃，弦为肝郁，滑主痰涎。原文谓“胃阴枯槁”，肠红痔坠日久营液大亏，食入哽阻作痛。弦滑并见，示肝气挟痰上逆而胃阴已竭，是噎膈重证之脉。滑虽主痰，在此则为津枯痰凝、虚中夹实之象，故言难治。", ["弦", "滑"]], "7774": ["病机", "脉滑而弦，滑主痰涎内凝，弦主肝气不舒。原文言“胃阴枯槁”，食入胃中仍觉哽痛、舌心作痛，是津液凝滞酿痰、痰愈多则津愈耗之候。弦滑之脉在此非实痰壅盛，乃胃阴亏而肝气横、痰浊凝滞之虚中夹实，故用大半夏汤法润降。", ["滑", "弦"]], "7775": ["病机", "脉左大于右，左候肝、右候脾胃。原文谓“阴伤不复之证”，食入哽阻、胃阴尤为枯槁。左脉大于右，示肝阴亏而肝气偏旺，胃阴耗损不能柔润，是阴伤不复、肝胃同病之机。前用大半夏汤法当合，即其意扩充，仍以润养胃阴、条达肝木为要。", ["大"]], "7776": ["病机", "脉弦稍平，是肝火渐敛而未尽，弦为肝脉，稍平示亢势略减。然肠红连日不止，乃肝火内燃、胃阴枯槁，相火妄动，肾开窍于二阴，火迫血溢，故下血不止。脉虽稍平而症未减，说明病本在肝胃阴亏火旺，脉象变化滞后于症情，不可因脉缓而轻视。", ["弦"]], "7777": ["病机", "两关弦滑，关候肝胃，弦主肝郁气逆，滑主痰气壅盛。中脘不舒、按之坚硬胀满、气逆如喘，是抑郁动肝，肝气冲入胃中，气痰交阻于膈。脉弦滑应此气逆痰壅之机，久则膈道不通，将成噎膈重证，故曰非旷怀不能为功。", ["弦", "滑"]], "7778": ["主病", "脉沉细，沉主里、细主虚，苔白质腻为寒湿内蕴。朝食暮吐、物不变化，是中阳不旋，腐熟无权，宿谷停留反出。沉细正合中阳衰微、无力运化之机，故断为反胃重证，病在脾胃阳虚，非实热呕吐可比。", ["沉", "细"]], "7779": ["病机", "左虚弦，右濡滑，关部三十余至一动，是肝阴不足而脾气虚损。虚弦为肝血不藏，濡滑为脾虚湿聚，脉来迟缓更示阳气鼓旋乏力。水湿不能分泄，混入肠中，黎明阳气发动时傍流而下，故晨泄兼肠红。脉症合参，脾虚胃弱、肝不藏血之机显然。", ["虚", "弦", "濡", "滑"]], "7780": ["病机", "右脉濡滑较退，是温脏清腑后湿浊渐化之征。濡主中气虚，滑主湿热，脉退说明脾土阳气不足与大肠湿热有余之势均减。刻下大便溏燥不调，为脾气未复、运化未健。前法参入分消，祛湿即所以崇土，脉象好转印证药已中机。", ["濡", "滑"]], "7781": ["预后", "右脉滑象渐退，溲亦渐利，是湿热有外泄之机。滑脉主湿浊内蕴，渐退则邪有出路，故断为向愈之兆。特胃纳不醒，乃湿去而胃气未苏，当和中芳运以醒脾开胃。此段以脉象消退言预后，说明湿热渐化而脾胃功能尚待恢复。", ["滑"]], "7782": ["病机", "脉细关弦，细主正虚，关弦主肝脾不和、气滞积阻。外寒束缚里热，挟积不化，头痛发热而腹痛水泻，泻虽暂定而腹痛未止，浊积必然未化。脉细弦正应气机郁滞、积浊内停之机，故拟调气运中以磨化之，非纯补纯攻所宜。", ["细", "弦"]], "7783": ["主病", "脉象濡软，濡主湿、软主虚，合舌苔淡白，是湿困脾阳之象。嗜饮多湿，湿邪内盛，脾阳受困，运化失职，故大便泻利。濡软之脉正合脾虚湿盛之机，治宜理脾温中，使湿化阳复则泻利自止。", ["濡", "软"]], "7784": ["病机", "右脉滑，为湿郁腑中之象。湿邪内蕴，水液不得正常分利，渗入大肠，故便泄如前；小溲欲解不爽，亦因湿阻气机，水道不利。脉滑主湿主痰，此处与便泄、溲涩并见，说明湿郁在腑，脾运失职，水谷不化，下注为泄。治当再参分利，使湿有出路。", ["滑"]], "7785": ["病机", "脉细弦数，细为营液日耗，弦为木郁不达，数为内热。木郁不克条达，气分攻撑不平，土被木克，运化无权，故寅卯之交依然便泄；内热耗营，脉细数并见。此肝郁乘脾、营液渐亏之候，久则恐入损途，非单纯实邪可比。", ["细", "弦", "数"]], "7786": ["病机", "脉形沉细，沉为阳气不运，细为土虚木旺。久泻不止，阳气衰微，不能温煦四肢，故四肢逆冷；神迷如寐、呕吐咬牙，乃土虚木贼、虚风内动之兆。脉沉细与此症相应，将成慢惊，属儿科危候，故曰切勿轻视。", ["沉", "细"]], "7787": ["病机", "脉象濡软而滑，濡软主湿，滑主痰湿内蕴。素体湿甚，湿热内蕴，脾土不能转旋，水谷不分化，尽注于肠，故胀满而致便泄，色如败酱；得泄转松，然中脘有形、气冲嗳噫，肝木暗动。苔白质腻、口味带甜，皆湿浊内蕴之征，恐致呃忒。", ["濡", "软", "滑"]], "7788": ["病机", "脉象转滑，关部独弦。滑为湿热内蕴，弦为木气郁滞。府浊得泄而自利仍不稀疏，腹中胀满，有形上冲直抵中脘，恶心嗳噫，口甜干腻，苔白转黄，皆湿热内蕴、清浊升降失司、土滞木郁、横暴之气肆逆之象。望六之年，正不胜病，故遵苦辛酸法。", ["滑", "弦"]], "7789": ["病机", "右尺细弱，左尺小涩，两关右弱左弦，两寸右微左略搏。右尺细弱为命火衰微，左尺小涩为水亏，两关左弦为木旺，右弱为土虚，两寸右微左搏为心肺阴液不足。晨泄而痛，非单纯肾泄，乃水亏木旺、肝木抑郁乘土，故痛而不暴注。烟性提挈暂缓标急，根本未复。", ["细", "弱", "涩", "弦"]], "7790": ["病机", "脉细而两关俱弦，细为营血不足，弦为肝木偏亢。痛泄日久，风木旺时痛痢日剧，少腹为重，冲气不和，肝木横暴之气郁怒冲突于中，故痛起不能支撑；阳气鼓荡，上撼心神，则怔悸、耳鸣头晕。夏秋便中带血，兼有湿热参杂。", ["细", "弦"]], "7791": ["病机", "两关俱弦，左寸虚微，尺部细涩。弦为虚肝肆横，虚微为心气不足，细涩为血少阴亏。血去太多，木失涵养，致虚肝下克脾土、上撼神舍，中流无砥柱，故痛而按之稍缓、便利带血、心中热辣、𩠎杂不食。木乘土位久不复，延入损症，治当柔肝和胃。", ["弦", "虚", "微", "细"]], "7792": ["病机", "原文“脉缓热退”紧承“痛势减轻，利下较爽，圊数亦疏”，说明邪热已退、脾胃渐和，脉由数转缓为邪衰正复之象；然苔稠厚而糙尽化，提示脾阴亏损、肝木势横未全平，故脉缓非纯平脉，乃热退而虚象渐露，主脾阴不足、肝木偏亢之病机。", ["缓"]], "7793": ["病机", "下痢顿止、痛失胃开，而“脉细弦微数”，细为阴血不足，弦属肝木未柔，微数示湿热未清；结合“舌苔未化，心中仍似有烦热”，说明育阴之后脾阴渐复而湿热余邪未尽，脉象反映虚中夹实、肝木偏旺、湿热留恋之病机，故仍从育阴中兼清湿热。", ["细", "弦", "数"]], "7794": ["病机", "“脉象滑数，舌红苔白”，滑主湿滞食积，数主热，与“里结后重，色白如冻，间带赤腻，脐下拒按不纳不饥”相应，说明停食阻气，风邪湿热尽趋于下，转成痢疾；滑数非虚，乃实邪壅阻肠胃、气血与湿热搏结之象，故拟苦辛开通。", ["滑", "数"]], "7795": ["预后", "“脉滑数转为细弱”，滑数为湿热实邪，细弱为血液耗残、正气转虚；原文谓“有形之积虽化，而风湿热从气入血，血液耗残，木失柔养，虚肝肆横”，故少腹作痛更甚、火升颧红、唇色如朱、神情委顿。脉由实转虚，示邪未尽而正已伤，属病情转折之预后判断。", ["滑", "数", "细", "弱"]], "7796": ["病机", "“脉数不爽”，数主热，不爽示气机郁滞不畅；与“舌红苔黄，唇口糜碎，临圊腹痛，后重气坠，不纳不饥”相合，说明肠胃湿热郁阻，胃浊蒸腾于上则不思纳谷、唇口糜碎，肠中屈曲为湿热所阻则府气不能宣通、后重不爽，故脉数而不流利，主湿热怫郁、气机壅塞之病机。", ["数"]], "7797": ["病机", "“脉象细数”，细为阴伤，数主伏热；原文谓“厥阴伏热乘脾，肠胃气机皆阻”，故仍腹痛后重、色赤如膏冻。痢减疏而脉细数不退，说明湿热未净、厥阴伏热未泄，阴分已受耗伤，脉象反映虚中夹实、热伏阴伤之病机，故再拟苦辛开通兼泄厥阴伏热。", ["细", "数"]], "7798": ["病机", "“脉数，舌红苔黄”，数主热；所下黄腻起沫，沫属气、黄属湿，结合发热颧红、小溲浑浊，说明湿热怫郁、欲开不开、蒸腾于胃。赤积虽退而脉数不减，示湿热未清、气机仍阻，故脉数主湿热郁蒸之病机，泄化湿热、疏通肠胃怫郁为目前定局。", ["数"]], "7799": ["病机", "“脉数右大，舌红苔黄”，数主热，右大主邪盛于气分；痢减而身复发热、一昼夜不能熟寐，原文谓“厥阴必有伏热，其上中湿热，因内虚而陷入于下”，今肠胃怫郁稍开而湿热充斥三焦，熏蒸为热，故脉数右大，主湿热充斥、厥阴伏热之病机，仿协热下痢治之。", ["数", "大"]], "7800": ["病机", "脉濡且滑，濡主湿、滑主热，合见为湿热内蕴。原文述肛门如坠、迸迫不舒，服升补药下坠不退，说明非中气下陷，乃湿热压滞府气，气机不得宣通。湿热胶结，故濡滑并见，主湿热下坠之病机，与肛门坠迫、下痢后重等症相应。", ["濡", "滑"]], "7801": ["预后", "右脉结代较和，结代本主气血虚衰或邪阻脉道，今较前为和，示邪势稍退、脉气渐复。然原文谓其色犹带赤腻，湿热之邪尚盛，虽见转机尚不足恃。脉象缓和仅为暂时之象，病机仍以湿热壅盛为主，不可因脉和而遽断向愈。", ["结", "代"]], "7802": ["预后", "脉细无神，大有雀啄之意，雀啄为真脏死脉，主胃气将绝。原文述气怯懒言、频频哕恶、不能饮食，乃暑湿热冲斥三焦，胃气遏伏不宣，脾气涩滞。虽痢减脐痛化，然正虚病实，脉见无神雀啄，示胃气衰败，预后堪忧，于大局无裨。", ["细", "雀啄"]], "7803": ["预后", "原文未识脉名，仅言脉亦起。三诊痢渐减疏，肛门涩滞已爽利，里急亦松，恶心亦定，诸症递退而脉随之起，示邪去正复、脉气渐振。脉起与症减相应，为病势向愈之兆，故主预后转佳，非主病机之脉。", []], "7804": ["病机", "脉细主气血不足，亦主有形之积阻滞脉道。原文述疟后下痢、腹痛甚剧、苔白质掯，乃有形之积与无形之气郁阻府中，气血运行不畅，故脉细而痛剧。细脉在此示积阻气郁、正气受困，主府中郁阻之病机，与腹痛、苔白质掯相应，治宜温通。", ["细"]], "7805": ["病机", "脉细不爽，细主脾虚，不爽示湿滞脉道不利。原文述痢后脾虚湿滞，腰脊不舒、面带微肿、食入运迟、时多沉睡，皆脾为湿困、脾土旋运不及之象。湿困脾阳，脉道不畅故细而不爽，主脾虚湿困病机，久则恐有胀满之虞。", ["细"]], "7806": ["病机", "脉沉而滑，沉主病在里，滑主湿热痰积。原文述数年前下痢虽愈，每至夏秋湿热蒸动即发，脉沉滑正合湿热伏留肠胃、根蒂未清之机。沉为伏邪在里，滑为湿热内蕴，触之即动，故主湿热伏留病机，治当以通为止。", ["沉", "滑"]], "7807": ["病机", "脉细不爽，细主血液耗损，不爽示湿热阻滞脉道。原文述休息痢迁延数载、临圊作痛，湿热伏留肠胃屈曲之处，血液由里耗损，天癸不行。脉细正合血耗，不爽合湿滞，主湿热伏留、血液耗损之病机，非孕象，先为疏通。", ["细"]], "7808": ["病机", "脉濡微滑，濡主湿、微主虚、滑主湿积。痢成休息，色赤黏腻，苔白心黄，乃湿热郁阻大肠屈曲之处，病久邪深，故脉见濡微滑，示湿滞未化而正气已伤，不能一蹴而几。", ["濡", "微", "滑"]], "7809": ["病机", "脉濡而滑，濡为湿象，滑主积滞。痢成休息，临圊仍痛，此湿积伏留大肠屈曲之处，气血不畅，故脉濡滑，暂为疏通以去其积。", ["濡", "滑"]], "7810": ["病机", "脉数左尺坚硬，数主热，坚硬主实。下痢肛门火热滞坠，小溲热痛，苔白质红，乃下焦火挟热上冲，肺胃之气欲降不能，彼此鼓激，故呃忒又盛，忌款未退仍在危地。", ["数", "坚", "硬"]], "7811": ["病机", "脉数，右关沉糊。数主热，沉糊主湿郁。暑湿热三气郁阻肠胃不化，热迫于下，湿热之气俱结于上，胃中阳气不通，故呃忒不止、下痢频频，痢证忌象频见。", ["数", "沉"]], "7812": ["预后", "脉象稍稍有神，乃胃气渐复之兆。木邪素旺，暑湿热郁阻肠中，胃失通降，清升浊降失常，虽呃逆较疏、下痢较爽，仍属险途，脉有神仅示转机。", []], "7813": ["病机", "脉沉略起，沉主里、主寒，略起示阳气稍振。平素所有之寒阻遏中阳，致气血鼓激、胃气逆冲，故脘中阻塞、酸水泛出，虽呃痢俱减，仍须竭力以希造化。", ["沉"]], "7814": ["病机", "脉微数，微主虚、数主热。呃止两日而下痢不减，腹痛溲少，糜黄甚臭，乃上寒下热，虚中夹热，未便苦寒，姑以轻剂扩清火府。", ["微", "数"]], "7815": ["病机", "脉象常带细数，细主阴伤，数主热。休息痢因湿热逗留，红赤之物缘湿热迫伤营分，邪郁大肠久而不去；今不热不痛不后重，而脉细数，乃痢伤脾阴，脾失统血，血液渗溢，故红腻时见。", ["细", "数"]], "7816": ["其他", "原文仅言「三诊脉症相安」，未载具体脉象，属诊后疗效转归之记录。脉症相安说明前诊方药切中病机，正气得安、邪势渐退，故可「再守效方出入」，于原方基础上略作加减。此段无脉象可析，主旨在于述治疗经过与守方之意，非论病机。", []], "7817": ["病机", "「脉虚喉舌起腐」，虚脉主正气不足。湿热久蕴化燥，灼伤阴液，阴亏于下则气撑腹痛下痢，阴伤于上则喉舌起腐。脉虚正合阴液耗伤、正气已馁之象，故曰「深入重地，图治为难」，示邪盛正虚、攻补两难之危局。", ["虚"]], "7818": ["病机", "「脉数滑，久按少情」，数主热，滑主湿盛痰浊。湿热内郁，下压府气则临圊痛坠，上熏灼阴则口糜腐布、糜饮反出。久按少情示郁热内闭而胃气已困。原文断为「湿热内郁」，并虑「厥脱之虞」，故拟清燥并行、甘苦合化。", ["数", "滑"]], "7819": ["病机", "原文作「脉滞不爽」，属脉象描述而非定名，故脉素取空。滞而不爽示气机郁遏、湿浊壅阻。暑湿热郁阻肠胃，下迫则下痢赤腻、里急后重，苔黄糙掯亦为湿热熏蒸之征。烟体阴津素亏，故特言「未可与寻常并论」。", []], "7820": ["病机", "「脉细数」，细主阴血亏少，数主热。下痢不止而所下紫瘀，是湿热深入营分、灼伤血络；口燥舌干、苔灰滞，乃清津不布。细数之脉正应营阴耗伤而热未清，故虑「元气难支，虚中生变」，示正虚邪恋之险。", ["细", "数"]], "7821": ["病机", "「脉形濡滑」，濡主湿、滑主湿浊痰滞。湿热郁于大肠，迫血下行，故便后下血淋漓。濡滑之脉与湿热内蕴相符，非虚寒失摄之象。原文据此立「苦燥湿，寒胜热」之法，以苦寒清化肠中湿热，脉症相印。", ["濡", "滑"]], "7822": ["病机", "「脉象滑大」，滑主湿浊，大主邪盛有余。肠澼不止、肛门下坠，是湿热不化、壅遏大肠，府气受压而坠。滑大之脉示湿热邪势尚盛，非虚坠可比，故治法以和营兼清湿热，清化为主而不事温补。", ["滑", "大"]], "7823": ["病机", "「脉象虚弦」，虚主阴分久亏、脾气不足，弦主肝脾不和、燥气内动。向有便血则阴亏，寒饮伤脾则统摄失职，肠澼日久脏阴愈亏、腑阳愈燥，故燥粪杂下。虚弦正合阴亏脾弱之机，故养阴之中参以培脾，兼清湿热。", ["虚", "弦"]], "7824": ["病机", "脉弦大为痰热内滞之象。痉搐之后，痰热壅阻，清津不升则舌干无津，浊液不降则便闭身热痰多。弦主痰饮、主肝风，大主热盛，脉证相合，示痰热胶结、津液耗伤，属衰羸之候，非实热单纯可下。", ["弦", "大"]], "7825": ["病机", "六脉细涩，细为血少，涩为血行不畅。年近古稀，腿股软弱，大便不解，正是血液枯燥、肠道失润之征。脉细涩与血液枯燥相应，故宜养血润肠，而非攻下。此段以脉象明示虚秘之病机在血燥。", ["细", "涩"]], "7826": ["病机", "脉濡不爽，濡主湿、不爽为湿滞气机之象。便不畅行、胸次不舒、便阻则头面发㾦瘰，皆湿热有余、脾土不能鼓舞运旋所致。脉濡与湿热内蕴、脾运失职相应，故拟和中泄浊、参以分利，从湿浊论治。", ["濡"]], "7827": ["病机", "关弦右部微滑，弦为肝木之气不和，滑为浊在府中。下坠之气不松，因浊不得泄，致肝木之气不能和协。脉弦滑示浊滞与肝郁并存，故暂为破泄府浊以觇动静，是脉象指示病机在府浊内阻、肝气失协。", ["弦", "滑"]], "7828": ["病机", "脉细带涩，细为阴血不足，涩为阴不固摄、血行不畅。泄浊后坠气较松，然肛门不能收摄、气冲作呛，府浊虽稍泄而病久肾虚，阴不固摄，故呛咳不退。脉细涩正合肾虚阴亏、固摄无权之病机，再摄其阴为治。", ["细", "涩"]], "7829": ["预后", "脉细而弦，细为肝阴不足，弦为肝气升发太过。交春令肝藏之气勃然升发，流行之机为之阻，大腹仍胀，寅卯木旺气觉攻撑。脉细弦示肝旺乘脾、气机壅阻，恐成气胀大症，故以预后立论，警示胀势可进一步加重。", ["细", "弦"]], "7830": ["病机", "脉象沉弦，沉主里、主阳虚，弦主气机郁滞。至暮不能纳食、食即胀满、天明始退，因脾阳不振，暮则阳无以化，胀满辄甚。脉沉弦与脾阳不振、气滞胀满相应，故指出鼓胀根源未可忽视，病机在阳虚气滞。", ["沉", "弦"]], "7831": ["病机", "脉沉弦重按带滑，沉弦主水气内停、气机郁逆，滑主痰火。肿势不增不减、气急痰鸣、便溏尿少、心中灼热懊烦，是水气逆射于肺、痰火交炽胸中。脉沉弦带滑正合水逆痰火之机，势恐喘脱，病机凶险。", ["沉", "弦", "滑"]], "7832": ["病机", "脉沉细主里虚，沉为在里，细为阳衰。原文谓“脾肾阳衰，不足以运旋鼓舞”，故食入运迟、腹胀脐下甚、咳嗽痰多，皆火不暖土、土不制水之候。脉沉细正合真阳不治、土德愈衰之机，法当补火生土。", ["沉", "细"]], "7833": ["病机", "脉沉细而舌苔黄滑，沉主里、细主虚，湿热溢于皮肤肌肉，故体半以上仍肿不退。前用导水而肿势半消，今湿邪偏着于上，脉沉细示脾虚湿蕴未化，故用越婢汤发越脾土之湿，从表分消。", ["沉", "细"]], "7834": ["预后", "脉沉主里、主水，苔黄质腻为湿热内蕴。原文谓“脾虚而湿热泛滥莫制，将至喘脱”，遍体虚浮、肿满窒塞、小溲不利、气逆喘促，皆水湿上逆射肺之危候。脉沉而症见喘促，正示正气内溃、水邪无制，故断为喘脱将至。", ["沉"]], "7835": ["病机", "脉细沉迟，细为阳虚，沉为水蓄在里，迟为寒凝。原文谓“湿寒泛滥，水气重症，方兴未艾”，目窠先肿、腿足俱胀、脘腹不舒，皆寒湿困脾、水气四溢之象。脉迟与湿寒相应，示病势方盛未已。", ["细", "沉", "迟"]], "7836": ["预后", "脉沉细如丝，为命火式微、阳气欲绝之象。原文谓“命火式微，水气泛滥，而逆射于肺”，故气喘虚浮一毫不退。脉细如丝示正气已衰，水邪上逆射肺，恐逆甚而喘而厥而脱，故谆谆告诫不可不慎，属危重之候。", ["沉", "细"]], "7837": ["病机", "脉沉滑，沉主里、主水，滑主湿盛痰壅。原文谓“脾虚而湿热泛滥，水气重症，为势正盛”，足肿至遍体虚浮、两胫红赤、二便不利，皆湿热壅遏、水气泛溢之实证。脉沉滑与湿热内盛相应，示邪势方张。", ["沉", "滑"]], "7838": ["病机", "脉细沉弦，细为脾虚，沉为水蓄，弦为饮邪郁遏。原文谓“水饮之气，郁遏脾阳，水从泻去，而脾以泻虚，致水气泛溢”，故胃脘痛、腹大、泄后肿甚，朝面暮足。脉沉弦正合水饮内郁、脾阳受困之机，为水胀根源。", ["细", "沉", "弦"]], "7839": ["病机", "左脉细弦为肝体不足、肝用过横，右脉滑大为痰水内壅。原文谓“肝横太过，无形之气，挟停痰积水内阻，致脾肺升降之道窒塞不通”，故胀势偏右、恶心呕痰、喉间漉漉。脉弦滑大正示气挟痰水、郁阻中焦之机。", ["细", "弦", "滑", "大"]], "7840": ["病机", "脉滑主痰湿内盛，苔白质腻亦为湿浊之征。原文谓气逆痰升致面浮足肿，朝面甚暮足甚，乃外感风邪与内湿相合，风湿相搏。风性轻扬旋于上故面浮，湿性重坠趋于下故足肿。脉滑正应痰湿壅盛之机，恐湿邪弥漫而成肿胀之症。", ["滑"]], "7841": ["病机", "脉象濡滑，濡主湿、滑主痰，为湿浊未清之象。二诊后两胫肿胀大退而足跗仍肿、面色带浮，原文谓风旋于上、湿坠于下，说明风邪未靖、湿邪留恋。濡滑之脉应脾运未复、湿浊尚滞，故再培土利湿以竟全功。", ["濡", "滑"]], "7842": ["病机", "脉沉弦，沉主里、弦主饮主痛，舌苔白滑亦水湿之征。原文谓脾虚湿邪不运，溢入肌肤，名曰饮肿，由足肿而遍体虚浮、二便不利。沉弦正合水饮内停、脾运失职之机，恐水气上逆射肺而致气喘，故拟开鬼门法以宣肺发汗逐水。", ["沉", "弦"]], "7843": ["病机", "脉沉郁带数，沉主里、郁主气滞、数主湿热。原文谓吸烟之体湿痰必盛，食百合寒腻伤脾助湿，脾土不运则清浊升降失司，浊气在上生䐜胀，湿郁生热故中脘火热、口渴溲赤。土滞木郁，肿属脾胀属肝，一派湿热闭郁，鼓胀之症已成。", ["沉", "郁", "数"]], "7844": ["病机", "脉糊滑，滑主痰湿，糊示湿浊黏滞不清。原文谓情志抑郁、气机不运，湿热闭阻，三焦升降失司，致大腹胀满、腿股肿胀、肢体面目发黄，苔白罩灰。滑脉应湿热痰浊内壅，气机痹阻，故为鼓胀重症，勉拟辛开淡渗苦泄以分消湿热。", ["滑"]], "7845": ["病机", "脉数主热，舌红苔腻为湿热之征。原文谓似疟后湿恋未清，误服血肉大补及养血甘寒之剂，助湿伐气，致湿热壅滞充斥三焦，大腹膨胀延及胸脘、二便不利。数脉正应湿热内盛，鼓胀重症，治当疏气运脾泄湿，以土恶湿也。", ["数"]], "7846": ["病机", "脉弦大久按濡滑，弦大主虚中夹实，濡滑主湿。原文谓腹满不舒并无胀大情形、足跗带肿，断为气虚脾不运旋、湿寒内阻之中满症。弦大按之濡滑，正示脾气虚弱而湿寒内停，本虚标实，故图治非易。", ["弦", "大", "濡", "滑"]], "7847": ["其他", "原文仅言脉症尚属和平，未载具体脉象，故脉象要素为空。此为二诊记录，投剂之后脉症平和，示前法切中病机、病情稳定，未便遽事更张，当守方续进。属诊疗过程之记述，非主病、病机或死脉之论。", []], "7848": ["病机", "右关脉尚带弦搏，弦为肝木之象，右关候脾胃，脉弦见于右关，是木旺乘土、土衰失运之征。木旺则其气冲突，故欲嗳不爽；土衰则运化无权，故胀满虽松而未已。此脉象直接揭示肝强脾弱、气机壅滞之病机，主胀满、嗳气等症，治当疏肝之用、柔肝之体。", ["弦"]], "7849": ["预后", "四诊脉象柔软，柔软为胃气渐复、病邪退舍之象；左关部久按才见弦象，说明肝木偏旺之势已减，仅存余绪。两日内胸腹舒泰、并不胀满，为起病以来未有之境，与脉象柔软、弦象减轻相应，故知药既应手，病势向愈，可踵效方消息之。", ["弦", "软"]], "7850": ["主病", "脉数带滑，数为热，滑为湿盛，湿热交蒸之象。面色目眦带黄、便利色赤，皆湿热充斥三焦之征；腹笥胀大而胀势不以利减，是湿热壅滞、气机不通。脉数滑与湿热充斥三焦相应，鼓胀重症见此脉，主湿热壅盛、病势深重，故不能许治。", ["数", "滑"]], "7851": ["病机", "脉滞苔白，滞为气机壅塞、湿浊内停之象，白苔主湿。瘕块散漫、大腹胀大如鼓、二便不利，皆脾虚而湿热壅滞三焦所致。脉滞与脾虚湿壅、气机不畅相应，鼓腹重症而脉见滞象，说明正虚邪实、运化无权，故勉方图幸。", ["滞"]], "7852": ["病机", "脉形濡滞，濡为脾虚湿盛，滞为气机壅阻。大腹胀大按之坚硬、阴囊肿胀，是脾虚木旺、水湿壅聚之候。濡滞之脉与脾虚失运、湿浊内停相应，鼓胀重症而脉见濡滞，说明正虚邪实、难以人力争功，故勉仿经旨工在疾泻之意。", ["濡", "滞"]], "7853": ["病机", "身热大势虽退而脉仍未静，是余邪未清、湿浊内留之征。溏泄之后转为便闭、腹笥胀满按之不柔，乃邪少湿多、湿困脾土，鼓舞运旋不及，大肠传化失司，所谓湿闭是也。脉未静与湿困脾土、气机不畅相应，故宜调气泄浊。", []], "7854": ["主病", "脉数浮滑，数为热，浮为风邪在表，滑为痰湿内盛。痰饮咳逆多年，气血逆乱，痰带红；兼感风邪，风与湿合，溢入肌肤，面浮肤肿、喘咳不平、腹胀脘痞、小便不利。数浮滑之脉与风邪外袭、痰湿内蕴相应，主痰饮兼感风邪，有喘胀之虞。", ["数", "浮", "滑"]], "7855": ["病机", "脉形细沉，细为阳虚，沉为病在里。痰气郁阻不开、痰出不爽、腹胀面浮足肿、小溲不利，皆缘脾肾阳虚，不能旋运，痰饮随风四溢、泛滥横行。细沉之脉与脾肾阳虚、水湿内停相应，主痰饮泛滥，有喘胀之虞，故拟开痰温肾行水之法。", ["细", "沉"]], "7856": ["病机", "脉沉弦为痰饮化水、水气内停之象。沉主里主水，弦主饮主痛。原文谓“痰饮而变成水气之症”，水湿渗入肌肤，先从足肿渐及胫股阴囊，腹满脘硬，食入发喘，皆水气上逆、壅阻肺胃所致。花甲之年舌光无苔，病实正虚，脉沉弦正合水饮内结、脾肺胃暗损之机。", ["沉", "弦"]], "7857": ["病机", "脉沉弦而重按少力，为脾肺肾三脏均虚、命阳不能化水之候。沉主里主水，弦主饮，少力则示虚。原文谓“水溢肌肤，蒸变无权”，故见足肿、纳减、小溲短少、遗尿不禁。痰饮多年，久病多虚，脉象正反映阳虚水泛、本虚标实之病机。", ["沉", "弦"]], "7858": ["主病", "脉形糊滑，为湿热蕴遏之象。滑主痰湿，糊示湿浊黏滞。原文直指“湿热蕴遏，为五瘅中之谷瘅”，四肢面目俱黄乃湿热熏蒸肝胆、浸淫肌肤所致。脉滑与谷瘅之湿热内蕴病机相应，故主病明确。", ["滑"]], "7859": ["病机", "脉涩主血虚营滞，涩为血少气滞之象。原文谓“产后劳伤，血虚营滞不和”，谷多气少、面色浮黄、肢倦体乏，皆营血不足、运行不畅之症。脉涩与舌淡并见，正合血虚营滞之病机，非单纯气分病可比。", ["涩"]], "7860": ["病机", "脉形濡弱，为脾胃亏虚、气失旋运之候。濡主湿主虚，弱主气虚。原文谓“嗜饮中虚，气失旋运，水谷之气不化为津，转化为痰”，痰阻营卫则寒热交作，中脘久痞。脉濡弱正反映脾胃愈亏、浊痰愈甚之本虚标实病机。", ["濡", "弱"]], "7861": ["病机", "左关独弦，为肝木不和、厥气失疏之象。弦主肝主痛，左关候肝。原文谓“厥气失疏，风阳扰攘”，故腹胀脘痞不纳、时发时止，甚则心神恍惚。脉左关独弦，正说明肝气郁滞、风阳内扰之病机，与他部脉象对比更显肝病独著。", ["弦"]], "7862": ["病机", "脉细濡而关部带滑，为湿热郁阻中州之候。细濡主湿主虚，滑主痰湿。原文谓“脾清不升，胃浊不降”，故不纳不饥、泛酸欲吐、寤难成寐。脉象反映湿浊内蕴、脾胃升降失司之病机，关部带滑更示中焦湿滞为著。", ["细", "濡", "滑"]], "7863": ["病机", "脉右部弦滑，为肝肠暗动、木郁土中之象。弦主肝主郁，滑主痰主实。原文谓“胃府之气略得通降，而肝肠暗动，遂令木郁土中”，故中脘虽舒而杳不思纳、腹中攻撑、大便不解。右部弦滑反映肝木乘土、气机壅滞之病机。", ["弦", "滑"]], "7864": ["病机", "脉象尚带弦滑，弦主肝郁气滞，滑主痰湿内蕴。胀满虽舒、痞阻稍松、稠痰吐出，是痰浊得降之象；然脉仍弦滑、舌红苔黄，说明肝胃之气未和、痰热未清，气机郁滞与痰湿互结仍是病本，故从效方再进，以调和肝胃为要。", ["弦", "滑"]], "7865": ["病机", "左寸关带弦、右寸关弦滑，主肝胃气郁、痰湿内阻；尺部数细而坚硬，数细为阴分不足兼有火象，坚硬示郁结深着。原文谓「气有余、便是火」，气郁生火故心胸烙热、痰中带红，舌苔白腻底红亦为气火夹痰湿之征，故再理肝胃之气而和其阴。", ["弦", "数", "细", "滑"]], "7866": ["病机", "左寸关弦象稍退、右关弦滑亦稍柔和，是肝胃之气渐得调和之征。弦主气郁，滑主痰湿，二脉柔和说明郁滞稍解、痰湿渐化，故胀满渐舒、略能安谷。脉象好转与症候相应，仍从肝胃调和以巩固疗效，防其反复。", ["弦", "滑"]], "7867": ["病机", "脉细而滑，细为正气不足，滑为湿浊痰热内蕴。中气虚弱则不饥不纳、二便不利；湿热郁阻中焦则中脘痞阻、口腻苔浊、卧难成寐。升降失司，清浊不分，故拟开上焦以宣通肺气，使气化湿亦化，枢机得转。", ["细", "滑"]], "7868": ["病机", "脉象濡滑，濡主湿、主气虚，滑主痰浊。中脘痞阻、饮食不进、口腻痰多，正是浊阻胃中之象。湿浊壅遏胃府，通降失职，故脉见濡滑。治先为通降，使胃浊下行，则痞阻可开，饮食可进。", ["濡", "滑"]], "7869": ["病机", "脉象濡滑，仍主痰湿内盛、胃气不降。通降之后仍不纳，略进谷即中脘不舒、味变酸浊，是痰湿闭阻胃口、气郁不宣之故。濡为湿象，滑为痰征，痰湿胶结则胃府难开，故再降胃化痰而兼宣气郁，使湿化气畅则纳谷自复。", ["濡", "滑"]], "7870": ["病机", "脉象濡细，重按少力，濡为湿、细为虚，重按无力则中气不足之征明显。舌苔白腻不化、不纳不饥，是脾虚不能化浊，湿浊停聚胃中。前数诊以通降为主，此诊脉转濡细无力，说明邪减而正虚显露，故再扶持中气、展胃阳以化湿浊。", ["濡", "细"]], "7871": ["病机", "脉濡细，右关带滑，濡细主中气不足，右关滑主湿热结聚于胃。胃气虽稍醒，然略多纳即气辄上冲，是脾虚不能运化、湿热结聚、通降无权所致。正虚邪结并见，故拟苦辛开通，辛以开郁、苦以泄热，使湿热化而胃气降。", ["濡", "细", "滑"]], "7872": ["病机", "脉迟主寒主虚，苔白亦为寒湿之象。原文言情志抑郁、木不条达，致气湿瘀滞、酒积不行而成积聚，食入胀满、色夺形衰，皆脾阳不振、气机壅滞之征。脉迟正应阳气不足、推动无力，故断为元气耗损之渐，恐入损门。", ["迟"]], "7873": ["病机", "脉沉主里，弦主痛主寒，亦主气机郁滞。左少腹结聚有形、按之坚硬，沉弦相合，说明寒邪与气交阻于下焦，气血凝滞成积。原文断为气寒交阻，恐成胀病，正因寒凝气滞、久则气机壅塞，胀满由生。", ["沉", "弦"]], "7874": ["病机", "脉沉主里，滑主痰湿。中脘结块按之不甚痛，说明病在分肉之间而非脏腑深处。沉滑之脉反映痰湿内停、流注分肉，结而成块。原文直指痰湿流入分肉之间，脉象与结块性质相符，非瘀血坚积之痛。", ["沉", "滑"]], "7875": ["病机", "脉弦主气滞，滑主痰湿。时病之后左胁下癖块胀大、腹满不舒，弦滑相合，说明脾土不运、胃络阻滞，气血痰湿互结于胁下。原文拟宣通气血、参以运土，正针对弦滑所反映的气滞湿阻、络脉不通之机。", ["弦", "滑"]], "7876": ["病机", "脉沉迟主里寒，经事当至不至、面色萎黄，为寒凝胞门、血行不畅之象。原文言寒入胞门，与肠外之汁相抟，石瘕之属，沉迟正应寒邪内结、阳气不运。故须耐心善调，不可急切攻夺，恐伤正气。", ["沉", "迟"]], "7877": ["病机", "脉象糊滑、苔白微腻，为湿浊内蕴之征。两足软弱、肌肤作麻、中脘痞满、恶心欲呕，皆湿郁胃中、胃失和降所致。原文谓胃为十二经总司，胃病则不能束筋骨利机关，故成痿症情形，当取阳明以运湿。", ["滑"]], "7878": ["病机", "原文以脉络不和言病机，未及具体脉象。寒湿停阻胃中，呕吐恶心、频渴欲饮，因寒湿内阻则清津不升；咳嗽少腹两旁牵痛、四肢脉络不舒，皆阳明脉络不和之征。故再温运湿邪、降阳明，以通脉络。", []], "7879": ["病机", "脉象沉弦，主里主饮主气滞。脉络稍和、呕恶口渴减轻，是药后寒湿渐化；然胸中如有物阻、大便不行，说明寒湿停饮仍阻于阳明，气机未畅。沉弦正应饮邪内停、气机郁滞，故不得不暂为控逐。", ["沉", "弦"]], "7880": ["病机", "脉沉弦稍起，沉为在里，弦属肝木。呕吐大减、施化得行，是胃气渐复；然胃病土难御木，风木大动，故关脉络失和，四肢痿软。此脉示木旺乘土、络脉失养之机，主胃病及肝、筋脉痿软之候，治当柔养脉络、和营液。", ["沉", "弦"]], "7881": ["病机", "原文未出脉名，以症言机。面肿发赤瘰作痒、腿股带肿、恶心呕吐、手臂筋脉抽掣，皆风湿相搏之象。风湿外袭，阳明脉络失和，故筋脉抽掣；湿阻胃气，故恶心呕吐。主风湿痹阻阳明、络脉不和之病机。", []], "7882": ["病机", "脉象糊滑，苔白心黄，滑主痰湿。恶心呕吐、频渴欲饮、随饮随吐、手臂筋脉抽掣，是湿痰蕴阻胃中，清津不升、浊液不降。糊滑之脉正应痰湿内蕴，主胃中湿痰、升降失司之病机，故拟苦辛通降。", ["滑"]], "7883": ["病机", "脉形沉细，沉为在里，细主阳虚阴盛。呕恶大减而未尽止，形体恶寒、头巅觉冷、自汗淋漓、筋脉抽掣，是湿寒郁阻阳明，阳气不能敷布外卫。沉细之脉正示湿寒内郁、阳不布达，主阳明湿寒、卫阳不固之病机，再当温化。", ["沉", "细"]], "7884": ["病机", "沉细之脉两关转大、颇带弦象，是湿痰温化后胃病未复，土难御木，风阳从而扰胃。呕吐复盛、中脘胀满痞阻、恶风自汗筋脉抽掣，皆肝木犯胃之候。关大带弦正示木旺乘土，主肝胃同病、风阳扰胃之机，故从肝胃主治。", ["沉", "细", "大", "弦"]], "7885": ["病机", "右脉转大而觉濡软，大而濡软为胃阴不足、虚而无力之象。频吐频渴、想吃甘甜、自汗恶风，是频吐损伤胃阴，湿寒成燥。濡软之脉不任重按，正应胃阴亏虚，主吐伤胃津、燥化之病机，故再以甘凉和胃阴。", ["大", "濡", "软"]], "7886": ["病机", "脉象滑数，滑主湿，数主热。湿热淋浊之后，髀关不时作痛、遍身作痒，是湿热流入络隧，壅滞筋脉。滑数之脉正应湿热内盛，主湿热痹阻络隧、恐成痿痹之病机，当清利湿热、宣通络隧。", ["滑", "数"]], "7887": ["预后", "原文未出脉名，仅言脉症相安。三诊脉症相安，是病势已趋平稳，然屈伸行动髀关仍痛，乃风寒湿阻络未宣、余邪未尽。脉症相安示正气渐复、预后尚可，主络痹未通之余候，仍须宣通络隧以竟全功。", []], "7888": ["治法", "原文仅言“痹痛稍减”，未载脉象，故脉象要素为空。此段为二诊记录，承前诊痹痛略缓，续以“宣通脉络，理湿祛风”为法，说明前诊辨证属风湿痹阻脉络，药后痛减而湿邪未尽，故仍守宣通祛湿祛风之治，属治法范畴，非凭脉断病。", []], "7889": ["病机", "脉象沉细，沉主里、细主虚，示邪痹于里而营卫气血不足。原文“遍身作痛渐平，而右腿骱仍然酸痛”，乃风寒湿三气内袭，经络阻痹，营卫气不宣通，“不通则痛”。脉沉细正合邪留络隧、气血不畅之机，故主痹痛缠绵、局部酸痛之候。", ["沉", "细"]], "7890": ["病机", "脉沉而滑，沉主里、滑主痰，合苔白腻浊，正应“肝气夹痰内阻”。寅卯之交腹中胀满蔓及腰膂、髀关重著作痛，乃肝气乘时发动，夹痰湿阻于内，气机不得宣通。脉沉滑与痰浊内蕴、气机壅滞相应，故用太无神术散法理气化湿。", ["沉", "滑"]], "7891": ["病机", "脉象沉郁、重按带滑，沉郁示气机不畅，滑主痰湿。原文“湿痰留络，恐成痹症”，尾闾作痛、腰膂髀关经脉牵掣、步履不便，皆湿痰阻于络隧、气血不得流通之候。脉沉郁带滑正合痰湿留络之机，故断为痹症将成，治当化湿通络。", ["沉", "滑"]], "7892": ["病机", "脉形沉滑，沉主里、滑主湿痰。原文“感寒夹湿，阻痹络隧”，故遍身络隧不舒、动辄作痛。寒湿内袭，着于络脉，气血运行受阻，不通则痛。脉沉滑与寒湿阻痹之机相应，故治宜温通，以散寒化湿、宣通络隧。", ["沉", "滑"]], "7893": ["病机", "原文仅言“四肢脉络不和”，属症状描述而非脉象，故脉象要素为空。此段论痰湿有余于上、肾水空虚于下，木失水涵，肝气横暴克脾则胀；营卫不宣，阳气上升，神不归舍，故将寐心中难过、胸膺不舒。主旨为脏腑病机，先降胆胃使神归舍。", []], "7894": ["病机", "原文未载脉象，故脉象要素为空。此段述湿毒流筋骨、邪去络空后叠投肝肾并调而渐愈，惟卧著则肢节作痛。原文以“血中之气不行”释之，谓气血周流本无一息之停，卧则血中之气运行不畅，故肢节作痛，治宜养血和络兼宣通祛风，属病机分析。", []], "7895": ["病机", "脉象弦滑，弦主肝风，滑主痰，此则“血虚肝风入络，络热则机关为之不利”。腰膂髀关腿股作痛、肩臂难以举动，乃血虚不能濡养络脉，肝风入络化热，机关失利。脉弦滑与风动络热之机相应，故断为难治，属病机分析。", ["弦", "滑"]], "7896": ["病机", "原文未识脉名，从“血崩之后，由渐而来”及“酸多痛少”可知病本在血虚，奇脉纲维失护。腰膂髀关属肝肾奇经所辖，血虚则络脉空虚，故酸多痛少、步履艰难。此段重在阐发血虚致奇脉失养之病机，非以脉断病，故脉象要素从缺。", []], "7897": ["病机", "脉细弦而数，细为血虚，弦为肝风，数为热气上冲。原文“遍体经络作痛，头旋掉眩，鼻流清涕，时辄不寐”，正是血虚肝风袭入络隧、热气逼液为涕之候。细弦数并见，说明营血不足而风热内扰，故拟养血荣经以熄风。", ["细", "弦", "数"]], "7898": ["病机", "脉象细弦，细主营血不足，弦主肝风内动。原文“节骱仍然作痛，头旋掉眩，少寐多涕，频渴欲饮”，皆由营血亏虚、肝风袭入经络所致。细弦之脉与血虚风动之症相应，故二诊仍拟养血化风，以柔肝荣络为治。", ["细", "弦"]], "7899": ["预后", "四诊“脉弦稍柔，经络掣痛较退”，弦为肝风之象，稍柔则示风势渐缓、营血渐复。前诊脉弦劲，今转柔和，与掣痛减退相应，说明养血宣络之法已见成效。此段以脉象变化判断病情向愈，故归预后。", ["弦"]], "7900": ["病机", "脉弦主肝风，头晕为风阳上扰之征。原文“营血久亏，血不养经，手足经络作痛”，说明血虚不能荣养经络，肝风内动故脉弦、头晕并见。弦脉与血亏风动之症相应，故治以养血熄风，使营血充而风自平。", ["弦"]], "7901": ["病机", "脉象细数而虚，细为血少，数为热，虚为阳明脉弱。原文“腹中作痛胀，而致经络作痛，腿膝尤甚，大便不行”，乃阳明脉虚、风阳乘入所致。虚细数之脉与营血不足、风阳内扰之症相应，故宜养血熄肝，兼顾阳明。", ["细", "数", "虚"]], "7902": ["病机", "原文未识脉名，以“营血不足，络隧空虚”立论，进而推及“木旺水亏，少阴真阴愈少，则少阳木火愈盛”。节骱痛、背腧板胀、逼液为涕、烁金则喑，皆由真阴亏而木火盛。此段重在阐发肝肾阴虚、木火刑金之病机，故脉象要素从缺。", []], "7903": ["病机", "脉缓微弦，缓为常脉而微弦主肝风未靖，重按少力则示中气不足、阳明脉弱。原文“熄风养血，臂痛稍轻”，说明风势已减而气血未复。弦而少力与臂痛稍轻相应，故从前法兼补阳明，以培中气而荣经络。", ["缓", "弦"]], "7904": ["预后", "原文“脉渐柔软”是二诊所见，与臂痛略轻并见，说明前此脉必偏弦硬，今转柔软，为邪退正复、气血渐充之象。脉柔软则营卫通利，筋脉得养，故臂痛减轻。仍守调补气血，正合“气血一充，则调理自和”之旨，属脉象好转之预后判断。", ["软"]], "7905": ["病机", "原文以“阳明脉络空虚”立论，虽未明言脉象，然由遍身酸痛大退而肝阳上升、𩠎杂气冲、经脉抽掣、四肢厥逆并见，可知脉必虚而兼弦。阳明络空则肝阳乘袭，虚风内动，故见抽掣厥逆。治以通补阳明、参以熄肝，正针对络虚风袭之机。", []], "7906": ["病机", "“脉形濡滑”主湿痰内蕴：濡为湿象，滑为痰征。原文言“胃中湿痰闭郁”，湿痰阻于中焦，营卫不达四肢，故左肩项四肢麻木，麻少木多；舌心灰润亦湿痰之验。治拟二术二陈进退，燥湿化痰以通络，脉证相合。", ["濡", "滑"]], "7907": ["病机", "“脉象濡而带弦”，濡主湿痰素盛、中气复弱，弦主木旺风动。高年营血亏则木失涵养而虚风内动，气弱则阳明络空，风阳袭入筋络，营卫滞而不行，故四肢麻木不遂、腹中板滞。舌胖心剥亦符。治通补阳明、舒筋养血而不涉呆滞。", ["濡", "弦"]], "7908": ["病机", "“脉细沉濡”主气血暗衰、风寒湿伏于经络。细为营血不足，沉为病在里，濡为湿滞。年逾大衍，气血暗衰，风寒湿乘瑕袭入，营卫之气滞而不行，故四肢酸麻、厥逆恶寒。原文以“有营若无营、有卫若无卫”喻营卫滞涩，脉象正合此机。", ["细", "沉", "濡"]], "7909": ["病机", "“脉形软滑”主痰湿内盛：软为湿象，滑为痰征。原文言“痰湿阻肺，兼袭经络”，痰湿壅肺则咳嗽气逆痰多，流注经络则偏左麻木不用。脉软滑与痰湿之邪相应，故叹“图治不易”，示痰湿胶固、络脉受阻之病机。", ["软", "滑"]], "7910": ["病机", "“脉形弦滑”主痰热内阻、气虚风动：弦为肝旺，滑为痰热。原文谓“气虚而痰热内阻，类中之根”，痰热挟风上扰，故偏左麻木不能运动，胸腹热气注射。弦滑之脉正反映痰热内壅、肝风欲动之势，为类中先兆之病机。", ["弦", "滑"]], "7911": ["病机", "“右关脉滑”主胃中痰气交阻，右关候脾胃，滑为痰征；“脉之长”应阳明为经脉之长。原文言胸次作闷、中脘不舒，乃痰气交阻于胃；阳明病则四肢作麻。脉滑而长，正合痰气阻于阳明、经脉失和之病机。", ["滑", "长"]], "7912": ["病机", "脉象糊滑，滑主痰湿。原文谓“湿痰内滞，络隧不宣”，湿痰壅阻络脉，气血不能流通，故遍身麻木；痰湿内困中州则中州不舒，小溲结而不爽；脏腑精气被痰湿阻遏不能上注于目，故目盲失明。脉滑与湿痰内滞之机相应，属邪实阻滞之候。", ["滑"]], "7913": ["病机", "脉仍弦滑，弦主风、滑主痰湿。原文言“湿痰尚盛”，虽麻木大退、步履渐能、两目略见物，属转机，但脉象未变，说明湿痰深伏络隧未清，风与痰湿相搏仍盛。脉症合参，邪未尽去，故再祛湿疏风，不可因症减而松懈。", ["弦", "滑"]], "7914": ["病机", "脉濡而滑，濡主气虚湿困，滑主痰。原文谓“气虚夹湿夹痰，营卫流行为之所阻”，气虚则推动无力，湿痰内停，营卫运行受阻，故每至睡卧四肢作麻、痰不爽利。脉濡滑正合气虚痰湿之机，故治以补气化痰，气旺则痰行水消。", ["濡", "滑"]], "7915": ["病机", "脉形细弱，细主营血不足，弱主气虚。原文谓“营卫不足，风与湿袭留不解”，营卫亏虚则外邪易袭而留连不去，四肢作麻即营卫不充、络脉失养之象。脉细弱与营卫不足相应，正虚邪留，故言势难急切图功。", ["细", "弱"]], "7916": ["病机", "本段未识脉名，以症测机。原文谓“素体丰盛，湿痰有余”，痰湿有余则太阳经气不宣。手小指麻木、右膝腘微痛，皆属太阳经脉所过部位，故知痰湿阻滞太阳经气为病本，宗东垣丸药养之之意，参太阳引经之药以宣通经气。", []], "7917": ["病机", "脉象沉细，沉主里、细主阴血不足。原文谓“水亏之极，损及命火，以致不能蒸化清津上升”，肾水亏极累及命火，气化无力，津不上承则舌干少津，肌肉消瘦；水液下趋则溲多浑浊。脉沉细正合水亏火衰之机，汤药气浮难达下焦，故宜丸药入下。", ["沉", "细"]], "7918": ["预后", "本段未识脉名，原文仅言“脉症俱见起色”，即脉象与症候均较前好转，属病情向愈之象。故曰“效方出入，再望转机”，示守效方随症加减，继续观察转机。此段主旨在于判断预后，非论具体脉象要素，故脉象要素从缺。", []], "7919": ["病机", "脉形濡细，濡主湿、细主虚。原文谓“肾水不足于下，痰热凭凌于上”，下虚则败精失道、精浊不止；上实痰热则旧咳复发、寅卯气升不能著卧、痰色灰黑。脉濡细正合下虚上实、虚实夹杂之机，故言尚可抵御而难望霍全。", ["濡", "细"]], "7920": ["病机", "脉象细弦，细为阴血不足，弦为肝木偏旺。寅卯气升不能著卧，乃肾虚不能涵木，冲阳挟痰上逆；精浊又示下焦不固。细弦合参，正合肾虚肝逆、痰浊上扰之病机，故法宜兼顾。", ["细", "弦"]], "7921": ["病机", "脉象虚濡，虚为精气不足，濡为湿滞而软。无梦泄精、腰府作酸，是精道滑而不固，肾气失藏。虚濡之脉不任固摄，故主精滑不固，治宜固精益肾。", ["虚", "濡"]], "7922": ["其他", "原文未识脉名，仅言「脉证相安」。三诊固肾益脾后脉证俱安，说明前法切中病机，脾肾渐复。此段重在述疗效与治法延续，非论脉主病，故脉象要素从缺。", []], "7923": ["病机", "脉虚形虚，虚为气血阴阳不足。肾阴虚则精不藏，肝阳强则气不固，久病气阴皆虚而滑泄；少阴枢病则寒热，骨髓空虚则腰酸足软，脏阴亏则腑阳燥而便难。脉虚正合虚损之机，故曰难治，先固摄其下。", ["虚"]], "7924": ["病机", "脉形虚大，虚为阴精不足，大为虚阳外浮。精髓空虚、开阁失度，故倏寒倏热；脏阴不济燥金，则大便旬日不行；阳升筋掣。虚大之脉不敛，正示阴亏阳浮、精虚失固之机，前法参滋润养脏。", ["虚", "大"]], "7925": ["预后", "原文未识脉名，仅言「脉神较振」。三诊后大便颇通、滑泄期远、胃纳馨旺，脉神渐振，是滋肾固精养脏见效之征。此段以脉神转佳判断预后向安，故归预后，脉象要素从缺。", []], "7926": ["预后", "脉虽细弱，渐觉有神，形色亦渐华泽，是肾气渐复之象；然遗泄有时仍作，终属肾气不固。细弱为不足，有神则生机未绝，故预后可望，仍须固补。此段以脉神判转归，归预后。", ["细", "弱"]], "7927": ["其他", "原文未识脉名，仅言「脉证相安」。摄纳肾阴后脉证俱安，然无梦泄精仍属肾阴不固，故前法参以固摄。此段述治法延续与疗效，非专论脉主病，脉象要素从缺。", []], "7928": ["病机", "前投分利湿邪而脉仍濡滑，说明水湿黏腻难化，不能分清泌浊，故精窍不固而遗浊相兼。濡主湿、滑主痰湿内蕴，湿邪留恋则气化不利，精浊下注。原文谓'湿为黏腻之邪，非一蹴所能几'，正合濡滑不去之象，故拟汤丸并进、上下分治以化湿固精。", ["濡", "滑"]], "7929": ["病机", "梦遗频来而脉濡细，左尺涩弱、左寸浮大，是心肾两亏、水火不济之候。濡细为气血不足，尺涩弱示肾精亏虚，寸浮大乃心火不敛、虚阳上浮。心肾失交则精关不固，故从心肾主治，以交通水火、固摄精室。", ["濡", "细", "涩", "浮"]], "7930": ["预后", "有梦而遗渐至咳嗽、往来寒热、汗出方解，脉细数少力，是气血并亏、阴阳不相护守。细为血少，数而少力为虚热内扰、阴不敛阳，故寒热汗出。原文断'恐损而不复'，属虚损之候，预后堪虑，故用二加桂枝龙牡汤以调阴阳、觇动静。", ["细", "数"]], "7931": ["病机", "浊症两月，小溲虽畅而马口不净、时有渗溢，脉大不耐重按，是气虚不摄之象。脉大而按之无力，非实热壅盛，乃正气虚浮、固摄无权，故精浊渗溢不止。原文直断'此气虚矣'，治当补气摄精，而非清利。", ["大"]], "7932": ["病机", "小溲淋痛，痛甚则闭结不宣、欲解难解，脉数洪滑，是湿热蕴结膀胱、气化不行。数主热，洪滑主湿热壅盛，湿热阻滞则膀胱不能化气，故淋痛闭结。原文称'气淋'，实由湿热郁阻、气机不利所致，治当清利湿热、通利膀胱。", ["数", "洪", "滑"]], "7933": ["病机", "下坠之气直入尿管而痛，甚则抵及肛门，小溲滴沥不爽，右脉濡滑、左部细弱无力，是肾气亏损不能收摄。濡滑为湿浊内蕴，细弱无力为肾气虚衰，气失固摄则下坠作痛、小便不爽。原文谓'肾气亏损，不能收摄'，故以咸润摄下为治。", ["濡", "滑", "细", "弱"]], "7934": ["治法", "四诊小溲已能约束，惟水道尚窒塞，本宜逐步进逼，然天暑脉虚，故暂为退守、乘机进治。脉虚示正气不足，暑热耗气，若峻攻逐水恐伤正，故取退守缓图之法。此段以脉虚为据，论治当顾护正气、待机而进，属治法权衡。", ["虚"]], "7935": ["病机", "小溲淋痛而脉形弦滑，是肝火湿热郁阻膀胱。弦主肝郁火旺，滑主湿热内蕴，肝火下移、湿热互结则膀胱气化受阻，故淋痛。原文断'肝火湿热，郁阻膀胱'，先为疏泄，以清肝泻火、利湿通淋为治。", ["弦", "滑"]], "7936": ["其他", "原文仅言“脉证相安”，未出具体脉象，故脉象要素为空。所述“小便仍有牵腻之物”，乃瘀腐未清、余邪未尽之象；脉证相安说明正气尚能支，但湿浊瘀滞未净，故需“重药轻投”，以缓消余邪，不可峻攻。", []], "7937": ["病机", "脉象濡弱，主气血不足、肾气亏虚。腰为肾府，少阴之脉循喉咙，故腰酸久不止、晨起咽痛，参合脉症为肾气虚、肾阴衰、阴阳交亏。然淋浊之后必有湿热，故补下元时仍带流利，防滋腻恋邪。", ["濡", "弱"]], "7938": ["病机", "脉细弦微滑，细主虚，弦主郁，滑主湿。久浊黄稠、茎中痛、目赤、腿股酸楚，乃肾虚湿热伏留未楚，精水混淆不分，精关难扃固。脉症合参，虚中夹实，故拟理湿泄热而化败浊。", ["细", "弦", "滑"]], "7939": ["病机", "脉濡不滑，右尺鼓指。濡主湿，不滑示湿滞未甚；右尺候肾与下焦，鼓指为湿热逗留之征。小溲不作痛而马口干结，乃下焦湿热驾轻就熟、缠绵难霍全之故。", ["濡", "滑"]], "7940": ["病机", "脉象左大，左脉候肾，大主邪实。小溲漩脚起沫、有时作痛，为肾虚而湿热留恋下焦，气化不利，精微下泄。脉大与肾虚并见，乃虚中夹实，故拟苦泄湿热、咸以化之。", ["大"]], "7941": ["病机", "脉细而沉候弦硬，细主阴伤，沉候弦硬为湿热蕴结膀胱、气机壅滞之象。小溲淋痛、闭癃不爽甚至涓滴不通，正是湿热结于下焦、膀胱气化不行，恐致癃闭，故脉见弦硬。", ["细", "沉", "弦", "硬"]], "7942": ["病机", "脉濡主气虚湿滞，苔白少华亦为脾肾气弱之征。肾气不足则暮夜溲多，脾胃气虚则纳少胃钝。脉症相合，病机在脾肾气虚，故宜补气益肾，使气化复常。", ["濡"]], "7943": ["病机", "脉滑主痰湿，苔黄质腻为湿热之象。小溲频数而不作痛，乃痰湿有余，膀胱之气为湿所压，气化失司。证已年余，湿性黏滞，驾轻走熟，故恐难一蹴而几。", ["滑"]], "7944": ["病机", "脉滑而大，滑主湿痰，大主阳衰。原文谓“湿痰郁遏，火不用事”，真阳亏损则火衰，湿痰内阻更遏相火，故脉见滑大。痰多阳痿，乃湿之有余、火之式微，滑大之脉正示湿痰壅盛而真阳不振之病机。", ["滑", "大"]], "7945": ["病机", "脉象濡滑，濡主湿，滑主痰。原文谓“湿邪流行入络”，致髀关腿膝酸麻、腰背痛、阳道不举。湿邪久困，相火郁遏，络隧为湿所阻，气血不能宣畅，故脉濡滑。此脉主湿阻络脉、相火不伸之病机。", ["濡", "滑"]], "7946": ["预后", "原文述二诊“脉象稍觉流畅，相火有燃动之机”，乃祛湿和络后湿邪渐退、真阳有复苏之象。前因湿邪抑遏，虽有真阳无从发露；今脉转流畅，示药已应手，预后向愈，故再扩充以进。", []], "7947": ["病机", "脉形濡滑，舌苔白腻，濡滑主湿。原文谓“湿酸郁遏，致命火不能用事”，湿邪郁遏相火，故腿股作酸、阳道痿顿。欲助命阳，当先去其遏我命阳者，濡滑之脉正示湿遏命火之病机。", ["濡", "滑"]], "7948": ["其他", "本段未识脉名，专论七疝隶于肝，少腹前阴皆厥阴部位。劳倦奔走则元气下陷，筋肿上冲心胸，乃肝脉游行之地。治法不越辛温苦泄，然劳碌气陷者苦泄则气益陷，故先举陷下之气，稍佐辛温，标本兼治。", []], "7949": ["病机", "脉象时常带数，右三部微滑，左三部无数象。数主热，滑主湿，右脉候气，故知气分湿热逗留。湿热润下，压坠府气，所以有疝气情形。此脉主气分湿热下注、府气受压之病机，拟理气泄湿。", ["数", "滑"]], "7950": ["病机", "右脉濡细，左脉细弦。濡细主湿，细弦主肝。原文谓“冲任虚寒，湿压气坠”，少腹偏右筋突痛胀，平卧则压坠稍衰而痛减。右濡细示湿盛，左细弦示肝经虚寒，合为冲任虚寒、湿压气坠之病机。", ["濡", "细", "弦"]], "7951": ["病机", "本段未识脉名，论寒痰内阻，络气不宣，胸胁肋游行作痛、睪丸痛胀。引经云“冲脉为病，男子内结七疝”，冲脉起于气街，挟脐上行至胸中而散，故上则胸痛，下则疝痛，病虽悬殊，其源则一，皆冲脉为病。", []], "7952": ["病机", "原文未载脉象，然述睾丸痛胀上攻中脘、恶心呕吐、倏寒倏热、便闭溲赤、舌红苔白，显系湿热流入厥阴，冲脉之气挟湿热上冲犯胃。冲脉隶于肝，又属阳明，起于气街布散胸中，故肝病不退则冲气上逆，属冲疝重症。脉象虽缺，病机为湿热郁阻厥阴、冲气上逆。", []], "7953": ["病机", "脉左部细弦，右部沉郁。细弦为肝经气郁不舒，沉郁主气火内郁、标热本寒。腹中攻撑、得热熨则缓、热汤入口痛甚、吐出痰涎，皆肝气横扰、寒痰内聚之象。脉象反映肝郁气滞、寒痰阻络，故治以温脏泄气火、化痰降胃气。", ["细", "弦", "沉"]], "7954": ["病机", "右脉沉郁稍起，渐见滑象。沉郁为气火痰浊郁结中焦，滑主痰浊内盛。痛势渐轻而呕恶不止、吐物酸秽，乃厥气逆冲、胃土不降，气郁化火、痰浊酿酸。脉由沉郁转滑，示郁结稍开而痰浊未化，故议清泄郁结、降浊镇逆。", ["沉", "滑"]], "7955": ["病机", "脉左弦右滑。左弦主肝气横逆、疝气上冲；右滑主痰聚胸中、胃浊不降。症见呕恶秽臭、胃中窒闷、面晦目红，乃火府之气不克下行，转从上逆，糟粕从胃底翻出，胆阳上逆。脉象示肝逆痰阻、肺气不通，故议控逐胸中结聚，使肺气下通大肠。", ["弦", "滑"]], "7956": ["预后", "脉数转缓。数脉原主郁热内扰，今转缓为邪退胃和之兆。攻逐后大肠开通、糟粕下行、呕吐臭秽已定、胸闷开、疝痛大减、渐能安谷，故脉由数转缓，示郁热渐清、气机得畅，出险履夷。再拟调和中气、疏泄肝木、分化湿热以善后。", ["数", "缓"]], "7957": ["病机", "脉濡而滑。濡主湿、滑主痰，濡滑相合为湿浊内蕴之象。睾丸偏左作痛牵引腰府、中脘不舒，乃肝肾湿热内伏，湿性濡滞、热性滑疾，故脉见濡滑。治先调气利湿，使湿热分消，气机通畅则痛胀自缓。", ["濡", "滑"]], "7958": ["病机", "脉细弦数。细主阴血不足，弦主肝气郁结，数主热郁于内。少腹偏右作胀、便艰时紫黑、气冲嗳噫，乃湿热内郁、血气结滞不宣，渐成㿉疝。脉细弦数正合湿热郁结、血滞气阻之机，故曰极难图治。", ["细", "弦", "数"]], "7959": ["病机", "脉沉而弦。沉主里、主寒，弦主肝、主痛。少腹有气上冲、支脘作痛，乃肝肾湿寒内盛，寒凝气滞，肝脉拘急，故脉沉弦。沉弦并见，为湿寒在里、肝气不舒之确征，治宜温化，使寒湿去而气机畅。", ["沉", "弦"]], "7960": ["病机", "脉象微滑，舌苔黏腻，为湿热内蕴之征。肺痈后湿热下趋大肠，致痔坠下血；胃钝少纳、中脘不舒，乃湿热困阻中焦。脉滑主湿，微滑示湿重于热，故非阴虚络伤，而是湿热伤营、营络不固，治当苦温胜湿、大苦泄热。", ["滑"]], "7961": ["病机", "原文未载脉名，但述“阳气上逆不平，面色浮黄，筋脉跳跃”，此由血去阴伤，阴不涵阳，致阳气上逆、筋脉失养而跳动。面色浮黄为土虚木乘之象，治以培土养肝，使阴血得复，阳气自平。", []], "7962": ["病机", "脉弦尺涩，弦主肝阳升动，涩主阴血不足。心悸跳荡、不寐、偏左头痛，乃阳升不熄、风阳上扰；腰股作酸，尺涩为肾阴亏虚。总由水不涵木，肝阳上亢，治拟熄肝宁神。", ["弦", "涩"]], "7963": ["病机", "脉形左大，左脉候肝，大为有余之象。惊动胆木，神情扰乱，虽循止而肝火尚未平靖，故脉左大。肝火内扰，胆木不宁，治当重镇清泄，以平肝火。", ["大"]], "7964": ["病机", "原文未载脉象，但言“脉症相安，然阳气仍复上升，皆由木失滋涵”。脉症虽暂安，而阳气上升未已，根在肾水亏虚，不能涵养肝木，致木失滋涵、阳气上逆。治再滋肾养肝，宁神熄木，以固其本。", []], "7965": ["病机", "原文未出脉，然述腰股作酸为肾虚已著，偏左头痛为血虚木旺，心悸不寐为水亏风阳撼扰。所谓“曲直动摇，风之象也”，总由肾水亏虚，肝木失养，风阳上扰。治当滋肾水以熄风。", []], "7966": ["病机", "左脉沉弦，沉主里，弦主肝木。便泄稍减而腹仍㽲痛，胸脘窒闷，入夜不寐，乃肝木未疏和，木旺克土，胃土失降，所谓“胃不和则寐不安”。治当疏肝和胃，使木土相安。", ["沉", "弦"]], "7967": ["病机", "脉左弱缓大，右关带滑。左弱缓大为气虚，右关滑为痰湿。体丰气瘠，脾虚生湿生痰，痰阻中枢，胃土少降，胆木不能下行，肝升太过，鼓动阳气，上为耳聋。病绪虽繁，不越气虚挟痰，脉症相符。", ["弱", "缓", "大", "滑"]], "7968": ["病机", "原文以“脾脉散舌下故也”点明脾络受风痰鼓击，脉气涣散不聚，故言语謇涩。风阳既盛，湿痰随之上袭，脾脉失其约束而散，主风痰入络、脾脉不敛之病机，与惊动胆木、升降失常、离坎不交之不寐相应。", ["散"]], "7969": ["病机", "右脉濡缓，濡主阴伤湿滞，缓主阳气弛纵。姜附过剂耗阴，在下之水不能吸阳下行，阳胜于阴而化风，游行背部腹部，热气注射却不甚。脉濡缓正合阴伤不能制阳、湿滞中焦之病机，主不寐而阳浮化风之候。", ["濡", "缓"]], "7970": ["病机", "右寸关脉顿洪大，沉取甚滑。洪大为虚阳上浮，滑则为痰。阳气两昼一夜未潜，脉象遽随之而大，说明阳升所致之脉大属虚阳无疑；关部独滑，乃津液为阳气所炼，凝成胶浊，胃中有痰。主虚阳不潜、胃中痰热阻遏水火交通之路。", ["洪", "大", "滑"]], "7971": ["病机", "脉细左关微弦右关带滑。细为阴血不足，左关微弦属肝火偏动，右关带滑乃胃中湿痰所据。湿痰阻梗胃府，坎离相交之路不通，水火不能相媾，所有湿痰悉借肝火鼓动。主湿痰阻胃、肝火鼓动、阴阳不交之不寐。", ["细", "弦", "滑"]], "7972": ["病机", "脉弦肤肿，经谓“热胜则肿”。惊动胆木，甲木漂拔，乙木过升，阳气有升无降，升降乖违，日久不寐。弦为肝胆气逆之象，气逆化热，热胜则肤肿。主胆木不降、升降失常、水火不济之病机，与不寐、肤肿相应。", ["弦"]], "7973": ["病机", "原文未识脉名，然述“脉左尺不藏，苔黄舌红，龙相亦动”。左尺不藏为肾失封藏，龙相火动；苔黄舌红为痰热内蕴。脾肾两虚，饮食生痰，痰凭木火之势化热，竟夜不能交睫。主脾肾两虚、痰热化火、龙相不潜之病机。", []], "7974": ["预后", "原文未出脉象，仅言“脉症相安”。前以滋水宁神为法，今脉与症俱安，说明阴水渐复、神得宁谧，水火有既济之象。此为治疗后脉症相应的佳兆，主预后向安，故前法扩充续进。", []], "7975": ["病机", "脉细左弦。细为元气未复、阴血不足，左弦属惊动肝胆、肝阳偏亢。大病之后元气未复，复因惊动肝胆，心悸少寐。脉细弦正合阴血亏虚而肝胆气逆之病机，主宁神潜阳，使浮越之阳气复归阴中。", ["细", "弦"]], "7976": ["病机", "脉象弦滑，弦主肝旺，滑主痰湿。原文谓“病后湿化为痰，痰在胃中，则胆寒肝热”，痰湿内蕴，肝热上扰，故痰多咳甚、寤难成寐。弦滑之脉正合痰湿化热、肝胆气逆之机，治以化痰宁神，使痰去热清则神安。", ["弦", "滑"]], "7977": ["病机", "原文未出脉名，然述“阳升不潜”“肾虚则空及奇脉”“痰湿素盛”。阳不潜藏则汗出遗泄，肾虚则腰痛、尾闾作痛，痰湿内盛则当参蠲饮。病机为肾阴阳两虚、虚阳上浮，兼痰湿中阻，故从阴柔药中参和平蠲饮，标本兼顾。", []], "7978": ["病机", "脉左大，左脉候心肝肾，大则阳气浮越。原文谓“中气无权，阳气尽从上冒，则肾阴不能上交，阳气浮而少阴病矣”，面青、舌无华、但欲寐皆少阴病象。阳浮于上，阴不交阳，再进则阴阳脱离，故用桂枝汤和阳、介类潜伏，以交阴阳。", ["大"]], "7979": ["病机", "二诊未出脉名，但言“左脉稍敛”，较前左大已减，知阳气上冒之势稍平。然仍神迷如睡、时带错语，乃“阳气上冒未平，炼液成痰，神机愈蔽”。病机为阳浮痰蒙、神机不运，故于潜阳中参开郁化痰，使痰化阳潜则神清。", []], "7980": ["病机", "右关脉稍觉沉实，右关候脾胃，沉实主宿垢内滞。原文谓“中虚宿垢未清，阴阳稍通，坎离仍未互抱”，虽阳气稍潜、大便通行，而中脘作痛、脉沉实，知胃府宿滞未净。故从阳引阴、从阴引阳，参磨滞之品，合胃以通为降之旨。", ["沉", "实"]], "7981": ["病机", "六脉濡细而模糊不爽，濡主湿，细主虚，模糊为湿浊蒙蔽。原文谓“体中之湿有余，兼复嗜饮，酒性升热，遂致胃中之湿热熏蒸，迫液外泄”，汗出非自汗盗汗，乃湿热迫液。濡细之脉正合湿盛热蒸、液泄过多之机，故治惟祛热渗湿，使湿热下行则汗自止。", ["濡", "细"]], "7982": ["病机", "脉象细弱，细主阴伤，弱主阳虚。原文谓“阴伤及阳，以甘药补中”，叠进黄耆建中汤后咳嗽盗汗俱减，然痰涩不爽、半饥咳甚、形体恶寒，皆中气不振、阴阳并虚之象。细弱之脉正合阴损及阳、中气不足，故以甘药补中，使中气复则阴阳渐和。", ["细", "弱"]], "7983": ["病机", "脉象细弱，细为阴亏，弱为阳衰。原文谓“吐血之后，阴伤及阳”“阴阳并虚，少阴之脉贯喉，中气下根于肾”，故盗汗虽止而形体恶寒、咽中如阻、胃纳不起。细弱之脉正合阴阳并虚、肾不纳气、胃气不振，故汤丸并进，上下分治，以复中肾之虚。", ["细", "弱"]], "7984": ["病机", "脉细弱少神，细为阴血不足，弱为阳气衰微，少神则胃气已馁。咳甚痰多白腻、食入运化迟钝，是肺脾肾三脏俱损，阴伤及阳，脾失健运则痰湿内生，肾不纳气则咳甚不减。脉症合参，属虚损之候，故曰'再摄其下'，重在固摄下元。", ["细", "弱"]], "7985": ["病机", "脉数细弦，弦为肝旺，数为郁热，细为阴伤。素有肝气胀满，春升木旺之时，肝气逆犯太阴，呛咳痰稠、寐则汗出，皆木火刑金、肺失清肃之象。肺为水之上源，水源失化则病势入损，故曰'恐水源失化，而入损门'。", ["数", "细", "弦"]], "7986": ["预后", "三诊咳嗽盗汗俱减，是症情向愈，然脉仍细数，细为阴虚，数为虚火未靖，说明阴分未复、虚热犹存。脉症相较，症减而脉未和，故断为'阴虚不复'，须守效方进退，再期应手，示预后尚需时日调养。", ["细", "数"]], "7987": ["病机", "脉数而弦，数为阳热，弦为肝旺。轰热盗汗不退、手指肿、口燥欲饮，经前乳房作痛，皆肝阳不潜、阳气不收，郁而化火，灼阴外泄。前已潜阳宁神而热汗未除，故知阳气不收为病机关键，再以育阴泻火固表为治。", ["数", "弦"]], "7988": ["病机", "脉数软滑，数为热，软滑主痰湿内蕴。病后自汗、咽中牵腻、火升则肌肤灼热，是甲木（胆）与戊土（胃）不降，乙木（肝）独升，木火挟痰上扰。脉软滑示痰湿未化，数示郁热，故虑其损久不复，当从肝胃升降论治。", ["数", "软", "滑"]], "7989": ["病机", "原文未识脉名，从症论治。先发肝厥，继则𩠎杂脘痛、涌涎少寐，皆木郁之极、肝阳冲胃所致；经行后带下如注，因奇脉隶于肝，肝病则奇脉失固。症象虽杂，总归肝胃不和、奇脉不摄，故先从肝胃主治。", []], "7990": ["病机", "原文未识脉名，据症析机。涎下略少仍不止、𩠎杂易饥、足软腰酸、腹时胀满，是冲气不和、冲脉不固，气逆于上则涎多𩠎杂，下元不摄则腰酸腹满。病本在奇脉失固，兼有气机失调，故再摄奇脉、兼参调气。", []], "7991": ["病机", "脉虚弦，左尺细涩。虚弦为阴血亏而肝阳偏亢，细涩为下元精血不足。产后血虚不复，收藏不固，寅卯木旺之交咳呛更甚，心𩠎头晕腹满，皆阳气升多降少、阴不恋阳之象。故拟育阴封固，使阳有所藏。", ["虚", "弦", "细", "涩"]], "7992": ["病机", "脉弦为肝阳升动之象，舌光示阴液已亏。原文谓「火时上升，不寐头痛𩠎杂，甚则脘痛」，火升扰神则不寐，上冲则头痛，横逆犯胃则脘痛𩠎杂。脉弦与舌光并见，说明阳升不熄、阴不制阳，故拟宁神和阳，以潜降浮越之阳。", ["弦"]], "7993": ["病机", "脉象细弦，细为阴血不足，弦为肝气偏旺。脘痛偏左为甚、时作𩠎杂，乃肝气横逆犯胃、胃失和降所致。原文断为「肝胃不和」，细弦之脉正示肝体不足而肝用有余，故治法当平肝和胃，柔肝以制其横逆。", ["细", "弦"]], "7994": ["病机", "两关脉弦，关候肝胃，弦主气机郁滞。中脘作痛、两胁胀满、𩠎杂不能食，皆肝气郁结、横逆犯胃之候。原文明言「肝胃不和」，两关独弦正说明肝胃气滞偏著于中焦，故拟平肝调气和胃，使气机畅达则痛胀自解。", ["弦"]], "7995": ["病机", "脉细弦少力，细为阴亏，弦为风动，少力则正气已虚。惊风后风痰入络，舌强不语、状如傀儡，继而痉厥、颧红火升、目斜口开手撒、四肢厥逆，皆肝阴肾液亏虚、风邪升动之象。原文谓「络隧之中虽有风痰内阻，而肝阴肾液已亏」，故拟育阴潜阳。", ["细", "弦"]], "7996": ["病机", "脉象弦滑，弦主风动，滑主痰聚。痫厥仍至，说明风痰入络、蒙蔽清窍之势未解。原文直言「风痰入络，不易图治」，弦滑之脉正是风痰相搏之征，痰不化则风不熄，故痫厥反复，预后缠绵。", ["弦", "滑"]], "7997": ["病机", "脉弦为肝阳逆上之象。稍涉忿怒即阳气不入于阴而寤不成寐，苔白心黄示痰浊内蕴。原文恐「浊痰随时上逆，而致癫痫」，说明弦脉主肝阳亢逆，阳升挟痰上扰，既可扰神不寐，亦可蒙窍成痫，病机关键在于阳逆痰升。", ["弦"]], "7998": ["病机", "脉象弦滑，弦属少阳火郁，滑属痰浊内蕴。降火化痰后寐稍安，而胸次窒闷、时作烦𩠎，说明痰火未尽。原文谓「阴分素亏，而少阳之火挟痰内扰，春升之际，势多周折」，弦滑之脉正示痰火未清，逢春升之气则易反复。", ["弦", "滑"]], "7999": ["预后", "原文以「脉象亦觉柔和」与不寐𩠎杂大退并见，脉由弦滑转柔和，说明痰热内扰之势已减，气血渐趋和调。脉象柔和为胃气渐复、邪退正安之征，故断「的是痰热内扰，效方再进一筹」，示病机已明、预后向善，守方续进可期痊愈。", []], "8000": ["病机", "脉虽稍觉柔和，但左寸尚弦大，弦为肝火，大为火旺，左寸候心，故知心火未宁。不寐神烦虽退，余热仍扰心神，当再宁神泄热，使心火下行，则肾水自固，此脉示心火未清之病机。", ["弦", "大"]], "8001": ["病机", "湿热之后痰湿未清，肝火挟痰上升而发厥，厥回脉仍弦数。弦主肝郁痰滞，数主火盛，脉象弦数说明痰火尚未平靖，肝火与痰浊交炽，故宜清泄以平痰火。", ["弦", "数"]], "8002": ["病机", "下痢呃忒，投温补中阳而呃不止、沃出涎水，脉象弦滑。弦主气郁饮停，滑主痰食内聚，脉弦滑说明胃中夹杂痰食，气机被阻，胃气上逆，故呃忒难止，勉方图幸。", ["弦", "滑"]], "8003": ["病机", "呃忒每至咳痰稍止，脉浮带滑。浮主肺气不降，滑主痰湿内蕴，脉浮滑说明肺气闭郁、清阳不展，痰阻气逆而呃，久则恐致变痉，故当宣肺化痰以展清阳。", ["浮", "滑"]], "8004": ["病机", "久虚不复，肾气不能收摄，气短冲逆嗳噫，病由遗滑而来，脉象细弦。细为阴血亏虚，弦为冲气上逆，脉细弦说明肾虚不摄、冲气上逆，气血并亏，故拟气血并调以图徐复。", ["细", "弦"]], "8005": ["病机", "久虚不复，气短不续，虽能安谷而非馨进，脉象细弱如丝，舌滑少苔。细弱如丝为气阴大虚之象，说明中气肾阴皆虚，胃气不能鼓舞，俯仰失职，故拟气阴并调。", ["细", "弱"]], "8006": ["病机", "痰嗽感风温，热与痰合蒸腾损肺，咽痛音喑，痰稠青绿，脉象细数。细为肺津亏耗，数为虚火内炽，脉细数说明气火尽从上凌，肺津为痰热所耗，金水不能相生，肾水日亏，虚劳喉痹难治。", ["细", "数"]], "8007": ["病机", "清化痰热后咽痛音喑不减，脉象细数颇有促意。细数主阴亏火旺，促意示虚阳上逆，说明痰热虽壅于上，而肾水内亏，虚阳亦从上逆，故再上下分治以觇造化。", ["细", "数"]], "8008": ["病机", "脉气口带浮，浮主表主风，风热之邪上袭肺系，肺络受灼，故不时咽痛，甚则吐血。风热迫损肺络，血随气逆而出。脉浮与咽痛、吐血并见，说明病位在上在表，邪未深入，治宜微苦辛凉以清透风热、凉血宁络，不可过用苦寒直折。", ["浮"]], "8009": ["病机", "原文未识脉名，以症测机。冬令过温，少阴之热循经发为喉痛，戌亥时肢节筋脉牵掣而无表邪见症，是少阳之风从内而鼓，木火动则风生，风煽则火炽，一阴一阳结为喉痹。风火相合，火势恐暴炽，故不可再投表散以张其焰，惟甘凉镇润为合古人治法。", []], "8010": ["病机", "脉形沉弱，沉为在里，弱为不足，与面色青黄相应。脉经谓营气不足面色青、卫气不足面色黄，肝为营之源、肾为卫之本，沉弱之脉正见平日肝肾不足。前投镇润后喉痛大定、牵掣未作，火风已分，然脉仍沉弱，说明本虚未复，故仍从前法出入调治。", ["沉", "弱"]], "8011": ["预后", "原文未识脉名，以脉静身凉为凭。四诊咽赤肿痛大退，脉静身凉，邪势已解，出险履夷，是病退向愈之象。惟腹中气觉呆钝，乃热化湿动、余邪未清，故再清余炎兼理湿邪。脉静与身凉并见，说明正复邪衰，预后转佳，非死脉之比。", []], "8012": ["病机", "脉数右寸关较大而不耐重按，数主热，大主邪盛，不耐重按则兼虚。由瘀化水，水入足三阴郁而生热，肝胆之火因之而起，阴分愈烁，阴不藏阳，阳气炽于阴分而浮越于外，故足肿赤痛、口碎咽疼。右寸关大数，正见浮越之火与阴虚并现，故用肾气导火归原。", ["数", "大"]], "8013": ["病机", "脉大而数，大主邪壅，数主热盛。右面发泡疮、目胞赤肿、身热，是风湿热三邪壅于阳络，郁蒸肌肤而发。脉大数与身热疮肿相应，说明邪势方张、热毒偏盛，故先为清泄，使风湿热从阳络而解，不可早用温补。", ["大", "数"]], "8014": ["病机", "脉形浮滑，浮主风主表，滑主痰主热。左目红赤、目胞肿胀、泪下多眵，是风热内郁，循经上攻目窍。浮滑之脉与目赤眵泪并见，说明风热挟痰郁于上焦，病位偏表偏上，故先为清解，透风热于外，使目窍之郁得开。", ["浮", "滑"]], "8015": ["病机", "原文未识脉名，以症辨机。两目并不红赤，仅多眵模糊、视物少神、睛脉不清，与风火目赤之候迥异。素体湿痰，痰湿上蒙清窍，故目眵模糊而少神，睛脉不清。此非风火为恙，说明病本在湿痰内阻，治当从痰湿着眼，不可误作风火清散。", []], "8016": ["病机", "脉数主热，微弦应肝，风为阳邪通于肝，风热相搏故脉见数而微弦。原文言\"风热未清\"，目眦痒多泪，乃风热客于肝窍、精气受扰之象。数示热势未息，弦示肝经风动，故治以养血清肝熄风，使风热去而精气不伤。", ["数", "弦"]], "8017": ["病机", "原文未识脉名，仅言\"脉症相安\"，故脉象要素从缺。右目不赤不痛而时常流泪，不因见风亦作，是肝胆气弱、肾水不足，风邪虽存而不能自越。脉症相安说明邪势已缓，正虚为主，故以丸药缓图，培补肝胆肾水以托邪外出。", []], "8018": ["预后", "原文未出脉名，只言\"脉症相安\"，脉象要素从缺。前用化浊熄肝之法后脉症相安，说明药证相符、病势向安，故守前法出入再进。此段主旨在于判断疗效与转归，属预后范畴，非专论某脉所主之病。", []], "8019": ["病机", "左脉虚弦，虚为阴血不足，弦为肝木失柔。牙疼胸闷并见，是肝阳不潜，走窜于胃络所致。原文明言\"肝阳走于胃络\"，虚弦正示肝体不足而肝用偏亢，阳动于上则牙疼，犯于中则胸闷，故脉虚弦为辨证眼目。", ["虚", "弦"]], "8020": ["病机", "脉滑而数，滑主痰湿壅盛，数主火热内炽。左偏齿痛微肿，先觉脚冷，火升则痛剧，是阴虚不能制阳，虚火循经上炎。原文断为\"阴虚火痛无疑\"，滑数示火势与痰湿相兼，苔薄白亦合，故治养阴降火兼清疏。", ["滑", "数"]], "8021": ["病机", "脉弦带数，弦属肝阳亢逆，数属虚热内动。阴分素亏则阳失所制，虚阳上亢，热走胃络，故牙缝出血、时觉浮动，原文称\"齿衄\"\"牙宣\"。弦数并见，正合阴虚阳亢、虚热迫血之机，故当育阴以制其阳。", ["弦", "数"]], "8022": ["病机", "脉细涩主营血不足、湿滞血行不畅，关部独弦则肝气偏旺。牙龈肿胀出脓、畏风肢疲，是厥阴肝阳走于胃络，湿热腐肉成脓。原文言\"厥阳走于胃络\"，细涩示正虚湿滞，关弦示肝旺犯胃，故拟清胃泄肝，标本兼顾。", ["细", "涩", "弦"]], "8023": ["病机", "脉弦而尺虚，弦为肝木失养而阳气化风，尺虚为肾本空虚。下则遗精，上则眩晕呕吐欲仆、耳鸣失聪，正是肾水亏虚、木失涵养，阳气尽从上越之象。原文\"肾本空虚，木失涵养\"点明病机，弦虚并见示本虚标实，故拟滋水潜阳。", ["弦", "虚"]], "8024": ["病机", "脉弦为肝阳偏亢，尺涩为肾阴亏耗，数则阴虚生内热。原文以「阴虚火盛」点明病机：肾水不足则木火失制，上扰清窍故遗精眩晕、耳鸣渐聋、右目翳障。尺涩且数正是下焦阴亏火动之征，故拟滋水清肝，标本兼顾。", ["弦", "涩", "数"]], "8025": ["病机", "脉弦主肝木火旺，滑数主痰热内蕴。原文谓「肾水不足，木火上腾，炼液成痰，痰随火生」，痰火占据清空之地，故耳鸣窍闭、头胀眩晕、目翳不化、稠痰灰黑。弦滑数并见，正是痰火交炽之象，故急则治标，清火豁痰为先。", ["弦", "滑", "数"]], "8026": ["病机", "前诊脉弦滑为痰火内盛，今转为细弱，原文谓「浊火已退三舍」，示邪势已衰而正亦不足。然眩晕呕吐、咽燥口干仍在，乃「下虚上实」之候，细弱正见下元亏虚。故不再清火豁痰，而「再填实其下，以治其本」，从脉转细弱悟出虚象。", ["弦", "滑", "细", "弱"]], "8027": ["病机", "脉弦为肝风内动，滑为痰浊内蕴。原文断为「肝风挟痰上逆，致浊邪阻塞清窍」，故耳鸣不止、耳窍闭塞。弦滑并见，正合风痰上扰之机。病已经年，风痰胶结，故言草木不能遽然奏效，示其病程缠绵、难以速愈。", ["弦", "滑"]], "8028": ["病机", "脉细弦为肝火内郁而阴血已伤，左尺小涩尤见肾阴亏耗。原文谓「肝火熏蒸，上逼于脑」，致鼻渊久漏、气味臭秽。久漏则脂液日耗，细涩之脉正是阴液枯槁之兆，故深恐难支，示其正虚邪恋、预后可虑。", ["细", "弦", "涩"]], "8029": ["病机", "脉细弦主湿郁化热而阴分受灼。原文谓「阳明湿热，熏蒸于肺」，浊涕从脑而下，正是湿热循经上蒸清窍之象。细弦不洪大，说明湿热郁遏而非炽盛，故治法「姑导湿下行」，使湿热从小便而去，从下夺邪。", ["细", "弦"]], "8030": ["病机", "脉形滑大为热盛之征，滑主痰浊，大主邪热亢盛。原文断为「肺热内郁，浊火上蒸」，故左鼻窍窒塞。咳嗽不甚盛，说明热郁于上焦清窍而未全归于肺，滑大之脉正应内郁之浊火，故治宜清泄肺热。", ["滑", "大"]], "8031": ["病机", "气口独大，气口属肺，独大则肺经火盛可知。原文谓「火风已解，而平素动辄鼻塞」，说明外风虽去，而肺中浊火未清，上蒸鼻窍故常塞。独大之脉正指肺热内郁，故宜清宜泄，专清肺经郁火以通窍。", ["大"]], "8032": ["病机", "原文言“右阳明脉络空虚”，非具体脉象，指阳明络脉空虚，风阳乘虚窜络。络虚则背痛不止、偏右头痛；风阳化火，木火亢甚，故去年咯吐见红。病机为络虚风动、木火亢盛，治当平肝泄热，然络虚非旦夕可复，故谓“勿望一蹴而几”。", []], "8033": ["病机", "脉细弦，细为络虚，弦为风阳内动。左背腧牵掣不舒、不时眩晕，乃阳明络虚，风阳上僭；舌红苔白而渴，示风阳化热伤津。病机属络虚风动、肝阳上扰，故宜通补阳明以实络，参以熄肝潜阳。", ["细", "弦"]], "8034": ["病机", "脉弦滑，弦主肝气偏旺，滑主湿痰盛。肝气挟痰入络，故左肩臂酸痛。原文明言“肝气偏旺，湿痰复盛”，痰随气升，阻于络隧，不通则痛。病机为肝旺痰阻、络脉不和，治宜化痰宣络，使气顺痰消则痛自止。", ["弦", "滑"]], "8035": ["预后", "二诊后大便畅解、右肩臂酸痛大退，脉由弦滑转为“弦稍柔”，示痰浊下行、络气渐通，肝弦之势稍缓。脉弦稍柔为药已应手之征，病机向愈，故曰“宜再扩充”，继续宣通络隧、搜逐余痰，以竟全功。", ["弦"]], "8036": ["病机", "脉沉弦，沉主里、主水饮，弦主饮癖。肩臂痛渐定而湿痰未化，痰阻肺气，故行动气短。原文谓“痰饮内盛，不流于彼，即聚于此”，说明痰饮流窜为患，其源则一。病机为痰饮内盛、肺气受阻，脉沉弦正合饮邪在里之象。", ["沉", "弦"]], "8037": ["病机", "两关脉滑，关候中焦，滑主痰湿。平素易呕痰，今腿股作痛牵掣、腰膂不舒，乃痰湿流入经络，阻遏气血。原文断为“痰湿流入经络”，脉滑与呕痰、肢痛相应，病机属痰湿内盛、流注络脉，治当化痰通络。", ["滑"]], "8038": ["病机", "脉数细弦，数为热，细为湿滞络脉，弦主肝火。热势递减而右足赤肿作痛，乃肝火湿热袭入足三阳经，脚气情形。从湿温传变，湿热下注，恐有冲心之患。病机为肝火湿热下袭、络脉壅滞，脉数与赤肿相应，示热邪尚盛。", ["数", "细", "弦"]], "8039": ["病机", "脉数滑，数为热，滑主湿痰。左足膝仍痛，苔白质腻，乃风湿热袭入足三阳之络，邪势尚盛。原文谓“为势尚盛”，脉数滑与苔腻、膝痛相应，示湿热痰邪壅阻络脉，病机属风湿热痹阻、络气不通，治当清化通络。", ["数", "滑"]], "8040": ["病机", "原文未识脉名，然述“外寒束缚里热，致风湿热袭入络隧”，腿肩臂痛而“经络烙热”，即《内经》脉痹、热痹。病机为外寒束表、里热郁蒸，风湿热邪痹阻络隧，气血不通则痛，热郁则烙热。脉象虽缺，据证当见数或滑数之象，主热痹。", []], "8041": ["病机", "脉弦微滑，弦主风、主饮，滑主湿、主痰。原文“风与湿袭入脾脏”，脾主四肢肌肉，风湿困脾，水湿泛溢则足肿按之坚硬、肌肤麻木、头面微肿。脉弦滑应风湿内郁之机，故急宜疏泄，使风湿从表里分消。", ["弦", "滑"]], "8042": ["病机", "关脉弦，右部带滑。弦为肝木之脉，滑主湿热与虫动。原文“湿热内郁，肝木不克疏，泄蛔动情形”，腹痛时作时止，正是蛔动之征。肝失疏泄，湿热蕴结，蛔虫不安，故脉关弦而右滑，主湿热内郁、蛔动腹痛。", ["弦", "滑"]], "8043": ["病机", "脉象虚软，气口及左关俱带浮弦。虚软为气血亏损之本质，浮弦为风邪乘虚外袭之标象。原文“气血亏损，风邪乘虚而入”，正合虚软中见浮弦之脉。故主气血不足、风邪外袭，治当补益中兼以祛风。", ["虚", "软", "浮", "弦"]], "8044": ["病机", "脉象弦紧，弦主风湿痹阻，紧主寒主痛。原文“湿热流入筋骨，遍身作痛”，湿热痹阻筋骨，气血不通则痛。弦紧为邪实痹痛之脉，虽言湿热，然脉紧亦示邪气搏结、经络壅遏，故宜祛风理湿以通痹。", ["弦", "紧"]], "8045": ["病机", "脉弦紧稍柔，较前紧象略减。原文“湿热未楚，肝肾已虚”，肩胛腿膝酸楚、步履疲软，为肝肾亏虚、筋骨失养之征。弦紧示湿热余邪未清，稍柔则邪势渐缓。病机属湿热留恋、肝肾两虚，故从厥少二阴主治。", ["弦", "紧"]], "8046": ["预后", "原文未识脉名，然言“培补肝肾，兼清湿热，脉证相安”，示治疗后脉与证俱趋平和，为向愈之兆。然“两手腿股广痘未消”，余邪湿热未尽，故前法仍参清化。此段重在判断预后，脉证相安而余邪未清，仍需守方清化。", []], "8047": ["病机", "脉细弱，重按微滑。细弱为肝肾亏虚、气血不足之象，微滑示湿热内蕴。原文“湿热袭入肝肾，易入难出”，阴茎短缩、近根带肿、溺有余沥，皆湿热下注、肝肾受损之征。脉证合参，主正虚邪恋、湿热深伏肝肾，故难图治。", ["细", "弱", "滑"]], "8048": ["病机", "脉细为阴血不足，左尺坚硬鼓指乃湿毒深伏于肾、久郁化热、结聚不散之象。少阴之脉系舌本、循喉咙，故肾中湿毒上攻，致喉间糜碎、舌下肿胀。此脉主肾经湿毒蕴结，与淋浊、横痃下疳等前症相应，示病根深伏，非单纯虚证。", ["细", "坚", "硬"]], "8049": ["病机", "脉细弦为阴血亏虚而肝木偏旺之象。左湿火深伏于肾，少阴脉上循喉咙，故咽辄哽痛；火郁于内，循经上冲，则背脊轰热直至头巅。细主阴伤，弦主木旺火郁，此脉示湿火内伏、阴亏火炎之病机，因病久且深，故极难奏效。", ["细", "弦"]], "8050": ["病机", "脉虚弦滑，虚为气血两亏，弦为肝火偏亢，滑为痰浊内蕴。肝火挟痰窜入少阳阳明之络，结于颈项，故结核坚硬、按之不移。此脉示正虚而痰火结聚之病机，虚痰不化则恐延入损途，与颈项结核相应。", ["虚", "弦", "滑"]], "8051": ["病机", "脉细弦而数，细为阴血亏虚，弦为肝木偏旺，数为虚火内炽。阴虚木旺，虚火上炎则内热连绵、咯血咽痛；木乘土位则腹痛便泄。此脉示脏阴亏损、肝火犯土之虚损病机，与盘颈疬痰、咯血、腹痛便泄诸症相应，故言虚损难治。", ["细", "弦", "数"]], "8052": ["病机", "脉数细弦，数主虚火内炽，细主脏阴亏损，弦主肝木偏旺。前诊酸甘制木后腹痛便泄已止，然虚火上炎未平，故咽痛音闪。此脉示脏阴皆损、虚火未戢之病机，与咽痛音闪相应，阴损难复，故曰何易言治。", ["数", "细", "弦"]], "8053": ["病机", "脉象细弦，细为气血并亏，弦为肝木强旺。疬痰既久，气血耗伤，不能制伏肝木，肝强克土乘脾则腹痛便泄，犯胃则脘痛呕吐。此脉示气血亏虚、肝木乘土之病机，与中脘作痛、舌质纹裂相应，故急者先治其标。", ["细", "弦"]], "8054": ["病机", "脉形带数，数为阴伤火炽之征。胸膺作痛稍轻、不自觉热，似热势稍减，然脉数未除，知阴伤火炽仍在；痰核随处结聚，恐其流窜。此脉示阴亏火旺、痰火流窜之病机，故再熄少阳木火，参以化痰和络。", ["数"]], "8055": ["病机", "脉象稍缓，缓为胃气渐和、病势稍退之象，较前数脉为缓。然舌红苔腻，左胸膺作痛牵引背肋，乃络隧不和、痰湿未化。此脉示正气稍复而痰湿络阻未清之病机，与胸膺痛、苔腻相应，故再宣通化痰和中。", ["缓"]], "8056": ["病机", "原文“脉数转缓，内热已退”，数脉主热，转缓则热势已减，故断内热退；然“滑泄频来”为湿浊下注、精窍混淆之象，环口发疹㾦亦湿热外蒸。脉由数转缓而滑泄不止，说明阴虚挟湿、虚火虽退而湿浊未清，故前法参以分清，标本兼顾。", ["数", "缓", "滑"]], "8057": ["病机", "原文未出具体脉名，仅言“痰阻络中，脉络从而不和”。滑泄既止而右半体牵掣，是痰浊留滞经络、气血不得流通所致，脉络不和即络脉失于宣畅。此非外邪，乃内痰阻络之病机，故拟化痰宣络以通其壅滞，使络气和调而牵掣自解。", []], "8058": ["病机", "原文“脉象弦紧”，弦主肝郁气滞、紧主寒凝痛结。大解带黑、脘痛呕吐虽减，而咽中哽阻、中脘坚硬仍在，说明营滞未全宣通，寒痰气血互结于中。弦紧之脉正应气结寒凝、痛阻之机，故效方扩充，继续宣通营滞以散结。", ["弦", "紧"]], "8059": ["病机", "原文“筋脉跳动，甚至欲厥，经一月再行”，脉跳动即动脉，主惊、主痛、主阴阳相搏。营血久亏则肝木失涵，风阳内动，故筋脉跳动、气逆欲厥；血亏冲任不固则经一月再行。动脉在此示风阳震动、阴不涵阳之病机，故再育阴以涵肝木。", ["动"]], "8060": ["病机", "原文“脉形不爽”，未出具体脉名，属脉气不畅之描述。少腹作痛、经事不行，兼面部丹赤成片不时发露，是营气不宣、气血郁滞于下而郁热上浮。脉形不爽正应营气壅滞、血脉不利之机，故治宜宣通营气，使郁滞得行而经通痛止。", []], "8061": ["病机", "原文未载脉象，仅言“经停少腹作痛，营气滞而不宣”。经停而少腹作痛，是营血凝滞、奇脉不通之候，冲任气血壅阻则痛，血海不盈则经闭。此段主旨在于营气滞而不宣之病机，故当通和奇脉，行其凝滞，使冲任通调而月事自下。", []], "8062": ["病机", "原文“脉象弦硬，气血郁滞”，弦为肝旺，硬则气结血瘀、失于柔和。木旺克土则脾不运旋，故腹笥板硬、痛泄、胸痞；气血郁滞则月事不来。弦硬之脉正示肝木横逆、气血壅结之机，故用抑气散合逍遥宣畅气血，必待月事通行方稳。", ["弦", "硬"]], "8063": ["病机", "原文“脉濡细，苔薄白”，濡主湿、主气虚，细主阴血不足。阴虚气弱则脾不运旋、封藏不固，故大便或结或溏、经事愆期、不时带下；冬令易感风亦气弱卫疏之征。濡细之脉正合气阴两虚、脾运不健之病机，故拟气阴并调。", ["濡", "细"]], "8064": ["病机", "脉象濡细，濡主气虚湿滞，细主阴血不足。原文述脾虚大便或结或溏、肾虚封藏不固、经不应期、时为带下，皆脾肾气阴两虚之候。濡细并见，说明气阴并亏而湿滞内蕴，故治以气阴并调、从前法扩充，紧扣脾肾虚损、收藏失职之病机。", ["濡", "细"]], "8065": ["病机", "原文未载脉象，纯以症候立论。脾虚不运则大便时溏，肾虚不藏则封固不密，冬令易召外感而为喘咳，经事不应期、带脉不固，皆脾肾两虚、收藏失职所致。病机重在脾肾并损，故治法宜从脾肾并调，与上诊气阴并调之法相承。", []], "8066": ["病机", "脉象细涩，细为血少，涩为气滞血瘀。原文述情怀抑郁、木土失和、中脘作痛，冲脉之气因而阻滞，经事数月方行，面色浮黄、唇白舌淡无华，皆气血皆滞之象。细涩正合营血不足而气机壅滞，故断为气血皆滞，当为宣通。", ["细", "涩"]], "8067": ["病机", "二诊脉细稍起，细为营血不足，稍起示宣通后气机略展，然经事未来、脘腹作痛仍在。原文断为久病营血必滞，说明前诊宣通营滞已见小效而瘀滞未净，脉细未复，营血仍亏，故仍守宣通之法，以通为治，不可骤补。", ["细"]], "8068": ["病机", "原文未载脉象，以症测机。经来淋沥、少腹作痛、腿股牵引不舒，系冲瘀未清，瘀阻冲脉则固摄失职，故淋沥不止。原文警示恐壅极而致崩败，说明瘀血壅滞日久有溃决之虞，病机在冲瘀未清、固摄无权，治当化瘀以复冲脉之固。", []], "8069": ["病机", "脉弦尺涩，弦主气机郁滞，尺涩主下焦血瘀。原文述经来淋沥、少腹作痛，脉弦尺涩，断为冲气不调则冲脉不固。弦为冲气失调之象，尺涩为冲脉瘀阻之征，瘀阻则血不循经而淋沥，故病机在冲气不调、冲脉失固。", ["弦", "涩"]], "8070": ["预后", "脉缓苔薄白，缓为胃气调和之象，非病脉。经停十五月之久而起居如常，脉缓苔薄白，原文断为歇，不治自愈，但须徐以待之。此以脉缓苔薄白证明气血冲和、无病邪内扰，故属生理性经歇，预后良好，非闭经之病。", ["缓"]], "8071": ["病机", "原文未载脉象，以冲脉立论。诸经之血会于冲脉而下为月经，冲气不调则经来血聚，冲气不通则胀势每甚。病机在冲气不调、气血凝聚不通，故胀满显著，治仿金匮温经法，以温通冲脉、调其气血，使冲气通畅则胀自减。", []], "8072": ["病机", "原文未载脉象，以“经事愆期，腹痛脐下滞坠，按之尤痛”定位冲脉气滞。冲脉起于胞中，气滞则经候愆期、脐下坠痛拒按，属实证。按之尤痛提示气滞血瘀、不通则痛，故治法“姑为宣通”，以行气通滞为要，非虚证可补。", []], "8073": ["病机", "原文未出脉，从“经前腹胀，带下腰酸，悸眩少寐，心中作痛”推病机为气滞血少、血不养肝。肝血不足则悸眩少寐，肝木旺则阳气升浮，带脉不固则带下腰酸。奇经隶于肝木，故补血之不足、疏气之有余，标本兼治。", []], "8074": ["病机", "脉弦主肝木偏旺，尺涩主下焦阴血不足。症见经事先期、寒凛火升、嗳噫眩晕、苔黄，乃肝阴不足、胆胃之气不降，阳升于上而火逆。弦为肝旺之象，涩为阴亏血少之征，故拟通降阳明、参泄肝木，使胆胃下行而肝阳得平。", ["弦", "涩"]], "8075": ["病机", "原文先言虚寒之脉“必沉细”，今反见“脉象濡滑”，濡滑主痰湿内蕴。经来日迟而诸如平人，惟四肢作酸，知非血虚寒凝，乃痰湿占于血海，营卫之气不得宣通。故不治血而治其所以病血者，理气化痰驱湿，湿去则经自调。", ["沉", "细", "濡", "滑"]], "8076": ["病机", "原文未载脉，以“经来淋沥不止，少腹酸痛，偏右痞块攻筑，血色紫殷”断为冲脉气滞。气滞则血行不畅，瘀阻胞宫，故淋沥不止、血色紫殷；气聚成形则痞块攻筑。治宜调冲任而宣气滞，使气行则血行，淋沥可止。", []], "8077": ["病机", "二诊淋沥仍然不止，兼中脘痞闷、少腹酸坠，原文断为“冲气不和，冲脉不固”。冲气上逆则中脘痞闷，冲脉失固则淋沥不止、少腹酸坠。前诊宣通未效，此转拟和营平木，柔肝以安冲任，使冲气平而血自固。", []], "8078": ["病机", "脉虚弦，舌心光剥，为水亏木旺、土弱肝强之象。曾经血崩，营血亏损不能养肝，肝木克土则便泄、脐下气聚；阴虚阳浮则心悸、咽中如阻、痰核结聚。虚为血少，弦为肝强，故养血柔肝为治本之道，肝柔则土不受克。", ["虚", "弦"]], "8079": ["病机", "原文未出脉，从“带下腰酸，小便不禁，心悸火升”断为带脉不固、肝肾空虚、阳气上逆。肝肾亏虚则带脉失约而带下腰酸、小便不禁；阴不制阳则阳气上逆而心悸火升。病本在肝肾，标在带脉不固与阳浮，治当固带脉、补肝肾、潜阳降逆。", []], "8080": ["病机", "原文未出脉名，以「带下大减」「小便亦能约束」言药后带脉渐固，而「心悸火升」仍在，断为「阳升而奇脉不固」。阳升则心悸火升，奇脉不固则带下、小便失约，故二诊虽减而未愈，仍守效方进退，侧重阳升与奇脉不固并见之病机。", []], "8081": ["病机", "原文未出脉名，三诊「带脉渐能约束，火升亦定」是前法已效，而「寐醒舌干口燥」为阴液耗损不复之征。带脉约束、火升得定属阳升渐平，舌干口燥属阴伤未复，故前法参入甘凉，于固带之中兼顾滋养阴液，示病机由阳升转为阴液不复为主。", []], "8082": ["病机", "原文未出脉名，述少腹作痛、带下、腰痛并见，断为「冲气不和，带脉因而不固」。冲气不和则少腹作痛，带脉失固则带下，腰为带脉所系故腰痛。三症相因，说明带下腰痛非独湿热，乃冲气逆乱牵及带脉不固之病机。", []], "8083": ["病机", "脉象带数，数为热，主肝火湿热内盛。赤带绵下属湿热沦陷于下，遍体作痛、小便烙热甚则微痛皆湿热下注之症，头空昏晕为肝火上扰。脉数与肝火湿热相合，故断为肝火湿热沦陷于下、带脉从而不固，数脉正是热邪内迫之征。", ["数"]], "8084": ["病机", "脉形滑大，滑主湿、主痰，大主邪盛，合为肝火湿热壅盛之象。久带不止、腰府酸楚，是湿热沦下、带脉不固所致。脉形滑大与湿热沦下相应，然久带不止而脉犹滑大，正邪盛未衰，故原文戒以「恐损而难复」，示湿热久羁、带脉损伤之病机。", ["滑", "大"]], "8085": ["病机", "脉象濡软，濡主湿、软主虚，合示湿邪内蕴而正气不足。带下腰楚为八脉不固，中脘作痛为湿阻中焦，湿热沦下则带下不止。濡软之脉与湿热沦下、八脉不固之症相应，说明此带下非纯实，乃湿盛正虚、带脉失约之病机。", ["濡", "软"]], "8086": ["病机", "脉象弦滑，弦主饮、主痛，滑主痰水，合为痰饮内盛之象。不时气喘、喘则欲厥，是痰水之气上逆射肺；偏右头痛、带浊绵下，是痰水沦陷于脾、带脉不固。原文明言「饮阻肺下」，痰水上逆则喘厥，下陷则带浊，弦滑之脉正应痰水饮邪之病机。", ["弦", "滑"]], "8087": ["病机", "原文未出脉名，述半产之后继以血崩，崩则八脉损伤、带脉不固，故带下连绵、按月经来甚多。半产与血崩相继，精血骤耗，冲任带脉皆失维护之职，故原文谓「维护皆失其职，不能急切从事」，示八脉损伤、气血难复之病机，非旦夕可图。", []], "8088": ["治法", "原文未出脉名，仅言「右肝经之脉环阴器」，辨其「形非枣核」故不作阴茄，断为阴肿痛。病机在肝经气血郁滞，故拟逍遥散法「舒木郁」，参宣畅气血之品。脉象无载，治法从肝郁立论，属内服调气之思路。", []], "8089": ["病机", "原文未出脉，述淋带漏下、少腹「冷气结聚」、气分攻撑，断为「冲气不和，冲脉不固」，视为崩败之先声。冲脉失于固摄，气逆结聚，故漏下不止；病机在冲脉不固、气机不和，属崩漏先兆之论。", []], "8090": ["病机", "脉细弦，细为血去过多、脉道不充，弦为木失涵养、厥阳偏亢。崩下虽和而呕吐恶心、滴水难容，是厥阳冲侮胃土，胃中浊阻不降。苔浊质腻佐证浊阻。血虚阳亢、胃逆不降，故「恐致痉厥」，病机重在肝胃。", ["细", "弦"]], "8091": ["预后", "脉形濡大，濡为中气虚馁、脉道软缓，大为虚而无力之象，非实大。年近花甲崩带日久，中气亏虚不能摄血，故脉见濡大。正虚日久，草木难效，原文断「恐难以草木奏功」，属预后不良之判。", ["濡", "大"]], "8092": ["病机", "脉沉弦，沉主里、弦主饮，与苔白黏腻相合，知「饮邪阻肺」，故久咳痰多气逆。天癸当止反多，是冲任不固之兆，饮阻于肺、气机不降，兼有崩坏之虞。病机为饮邪内阻、肺气上逆，兼冲任失守。", ["沉", "弦"]], "8093": ["病机", "原文未出脉，述崩淋不止、腰府作酸、其血即下，断为「奇脉暗损」。腰为奇经所系，血下而腰酸，是冲任督带固摄无权、奇脉暗伤。病机在奇经亏损、固摄失职，故治法「再参固摄」，属虚损崩漏之论。", []], "8094": ["病机", "脉形沉滞，沉主里、滞主气机壅阻。经积九月而崩，崩后停年余，腹满气坠、胸脘灼热，是「血因气滞，冲脉阻闭」。气滞血瘀，冲脉不通，壅极而决则复崩，故脉沉滞主气滞血阻、冲脉闭阻之病机。", ["沉", "滞"]], "8095": ["病机", "脉数濡软，数为虚热、濡软为气血不足，与舌苔浮白无华相应。崩漏日久，块片而下、头晕耳鸣、面浮黄、食少脘闷，是「肝脾并亏，统藏失职」。肝不藏血、脾不统血，故久崩不止，虚象显著，恐复下致晕厥。", ["数", "濡", "软"]], "8096": ["病机", "脉细为阴血亏虚，关部弦劲乃厥气冲侮胃土之象。原文谓'阴血失营，致厥气冲侮胃土'，故漏经成块、胸脘不舒、涎涌作恶、气撑腹满皆由血虚气逆、肝胃不和所致。细而关弦，正虚中夹实之候，故诫'恐虚中生变不可不慎'。", ["细", "弦"]], "8097": ["病机", "脉虚左大、右关无情，乃胃阴耗残之甚。原文'口中黏腻，津液悉成涎沫''舌边白糜星布'，皆胃阴亏耗、虚火挟浊上蒸之征。冲瘀既行胸满虽松，而阴伤未复，故虑'虚火挟浊上蒸，而糜腐大布'，即所谓虚中生变。", ["虚", "大"]], "8098": ["预后", "本段未识脉名，仅言'脉象较敛'，为药后胃阴渐复、逆气渐降之象。原文'口腻恶心顿减''舌糜已化'，说明降胃和阴之法应手，病势向愈。脉敛与症减相应，故断为药既应手、宜再扩充，属预后佳兆之论。", []], "8099": ["妇人", "脉弦滑为肝气不和兼痰湿内蕴之象。经停二月有余而腹满、𩠎杂欲呕，原文断为'恶阻而兼肝气不和'。滑主孕、弦主肝郁气滞，气逆犯胃则呕，气滞则胀满，故脉症合参属妊娠恶阻之候。", ["弦", "滑"]], "8100": ["妇人", "脉弦滑而浮，浮为感风之征，弦滑主孕。原文'感风咳嗽''怀孕在身'，说明外风袭肺致咳，而脉之弦滑示胎孕在身。故治咳须顾胎，原文诫'勿犯其下'，即勿用伤胎下坠之品，属妊娠兼感风之候。", ["弦", "滑", "浮"]], "8101": ["妇人", "脉弦而滑，弦主气分不和，滑主血行紊乱。经停三月而每月淋沥色赤鲜、气攻漉漉，原文断为'气分不和，致血紊乱，胎漏之象'。气滞则血不循经，故漏下淋沥，脉弦滑正合气乱血扰、胎元不固之机。", ["弦", "滑"]], "8102": ["妇人", "脉缓急不调，缓为胎气本象，急则示胎系震损、气机失和。原文'劳动，胎系震损''见红，腰酸腹满'，皆因劳伤动胎、气滞不固所致。脉象缓急不均，正应胎元动摇之候，故急宜安固，参以理气，盖安胎以理气为先。", ["缓", "急"]], "8103": ["妇人", "脉缓微滑，缓为平人之常，微滑示胎孕之象。经停五月余而不时漏下，饮食起居如平人，原文断为'胎漏见象'。脉缓而不数、滑而不弦，说明气血尚和，惟阴分有热迫血渗漏，故宜和阴泄热、参以调气。", ["缓", "滑"]], "8104": ["病机", "脉缓微滑，缓为胃气尚和，滑主血分有热。漏下已止而脉见微滑，说明血热未清、胎元不固，故虽起居如平人，仍从胎漏主治。滑脉应于妊娠，微滑示热未净，缓则示正气未大伤，病机重点在血热不固。", ["缓", "滑"]], "8105": ["病机", "脉细沉弦，细为气血不足，沉主里、主气滞，弦为肝气横逆。原文谓“气分寒滞，气机闭塞”，寒气不运、水气更郁，故脘腹胀满、恶寒。妊娠心胆脉养之际，此脉示寒滞气闭，深恐损动胎元，病机在气分寒凝、肝气不舒。", ["细", "沉", "弦"]], "8106": ["病机", "脉象沉弦，沉主里、主水气，弦主肝气、主饮。原文谓“肝气挟痰饮上逆，肺气不能下降，则脾土失其运旋，遂致水气泛溢”，故见遍体浮肿、气升不能著卧。沉弦为饮邪内停、肝气上逆之象，病机属子肿，痰饮与水气交阻。", ["沉", "弦"]], "8107": ["病机", "脉象虚弦，虚为阴血耗损，弦为风阳内动。原文谓“阴分既耗，木失涵养，风阳大动”，故见梦魇、唇燥口噤、四肢牵强、忽笑忽哭。虚弦示肝肾阴亏、风阳上浮，痰阻肺胃，两木同升，病机属血虚风动、胎元不固。", ["虚", "弦"]], "8108": ["病机", "原文未识脉名，然述产后数载经事不行，当至之期腰腹作痛、欲行不行，此冲气不和、冲脉不利之候。冲脉不利则营卫宣通失畅，故经闭而痛。又喉证之后余毒未清，故宣通营卫须兼顾余毒，病机在冲脉不和、营卫阻滞。", []], "8109": ["病机", "脉濡主湿、主气虚。产后两月下痢不止，色黄而腻，身热脉濡，原文谓“气湿不宣，恐成休息”。濡脉示湿邪困阻、气机不宣，湿与热合，滞于肠道，故下痢黄腻而身热。病机为湿滞气阻，久则恐成休息痢。", ["濡"]], "8110": ["预后", "脉数而弦，数主热、主邪盛，弦主痛、主气滞。产后恶露未清，营气阻滞，气聚成形，腹中痛胀、寒热往来，脉数弦为实象。原文谓“恐从实变虚，而至难复”，示邪实日久耗伤正气，预后堪虑，病机在营滞气聚、实中夹虚。", ["数", "弦"]], "8111": ["病机", "六脉虚微，虚微为气血大虚；右寸关沉弦，沉主里、弦主饮。新产之后气逆如喘、痰多白腻、不能著卧，原文谓“水寒之气袭于外则应于内”，两寒相感，中外皆伤，故气逆上行。虚微示正虚，沉弦示寒饮内伏，病机属虚寒夹饮、肺气上逆。", ["虚", "微", "沉", "弦"]], "8112": ["病机", "脉数浮大，为风邪外袭，卫气奋起抗邪，故浮大而数；左部沉迟，乃营血瘀滞，恶露涩少，少腹作痛，按之微硬，牵引腰尻。外有风邪，内有气瘀，故恐成时证。脉象与头痛发热、得汗不解、恶露涩少、少腹硬痛相应，示表邪未解而营卫壅滞。", ["数", "浮", "大", "沉"]], "8113": ["病机", "脉象弦紧，弦主肝风，紧主痛与寒。子痫由胎热有余，火风鸱张，胎受热迫而坠。小产后恶露不行，败血上冲，神糊妄语，脉弦紧正是瘀血上冲、肝风内动之象。紧为瘀阻气机，弦为风动，故云极为危险，与神昏、妄语、恶露不行相应。", ["弦", "紧"]], "8114": ["病机", "脉细关弦，细为营血不足，弦为气滞。产后恶露未行，气血凝滞，腹中有形作痛，临圊更甚，气升汗出不止。营滞阻气，气滞为液，液泄为汗。脉细弦应于关部，正示肝脾营气郁滞，与腹痛、汗出相应，故宜宣通和化，通则不痛。", ["细", "弦"]], "8115": ["病机", "此段无脉象，专论产后汗出之理。汗为血之液，夺血者无汗，指脱血而言；产后瘀露为有余之血，非脱血可比。初产百脉沸腾，阴虚阳亢，啜热汤饮而津津汗出，乃卫气流通，阳从汗泄，身体舒和。若绝无汗，则卫气闭塞，必将发热。故产妇宜微汗，不宜无汗，亦不宜多汗。", []], "8116": ["预后", "三诊脉弦稍收，较前弦紧之势已减，便稍转润，临圊作痛亦减。足见血燥气滞，府浊因而不泄。脉弦稍收，示气滞渐通，但血燥未复，府浊未净，故前法再参破浊。脉象与便润、痛减相应，说明病情向愈，然余邪未清，仍须通化。", ["弦"]], "8117": ["病机", "脉象细数微滑，细为阴伤，数为火旺，滑为痰聚。胎前感风，产后不彻，咳嗽三月，痰多口腻，凛寒内热，汗出不能左卧。久咳损肺，阴阳二气有偏，气即为火，液即为痰，证入损门。脉细数滑与痰多、内热、汗出相应，示肺损痰火内蕴，非轻浅之候。", ["细", "数", "滑"]], "8118": ["病机", "脉象弦紧，弦主气滞，紧主瘀痛。产后匝月，少腹坠痛，腿股腰尻作酸，带下阵阵，并有结块同下，腹满不舒，胃钝少纳。此由旬日之间恶露停留，旋虽复至，而脉络已滞，遂令瘀浊化带。脉弦紧与坠痛、结块、带下相应，恐其崩败，故当警惕。", ["弦", "紧"]], "8119": ["病机", "脉滞而硬，滞为气机郁阻，硬为瘀结有形。因痢而产，产后痢仍不止，腹痛里急后重，恶露不行，少腹按之硬痛，所下瘀黑，杳不思纳，胸脘不舒。此暑湿热三气郁阻肠中，瘀露不行，府气更加郁结。脉滞硬与少腹硬痛、瘀黑下物相应，古云胎前下痢产后不止，极为郑重。", ["滞", "硬"]], "8120": ["病机", "脉虚无力，苔白少华，为恶露下后瘀块虽去而中阳已伤之象。屡下紫黑瘀块、少腹舒、圊数减半，是府中阻滞稍宣；然临圊后重、气坠、全不思纳、胸中哽塞，皆中阳结痹、运化无力所致。脉虚无力正应中阳不足，虽得转机而正气已馁，故曰尚不足恃。", ["虚"]], "8121": ["病机", "原文未出脉名，以症测机。头面遍身发出赤㾦、口渴稍定，是暑热藉外越；少腹结块消而按痛、下痢昼夜二十次，冲瘀未清。冲脉起于气街布散胸中，故少腹痛松则胸中痛甚，上下相应。此冲瘀未清、冲气逆上之病机，宣瘀使冲脉通、胸中旷，安谷则昌。", []], "8122": ["病机", "产后旬余，恶露通行而频有带下，偏左头痛，脉形弦细。弦为肝旺，细为血少，血虚则肝木失养而生风，风阳上升故偏左头痛。带下频仍亦属血虚不摄。此血虚生风、阳气上升之病机，故治以养血熄肝，使血充风息则头痛自止。", ["弦", "细"]], "8123": ["病机", "新产九朝，血从上冒虽暂定，而肝阳上逆，冲胃则呕吐，乘脾则泄泻，扰神则不寐，甚而作呃。脉左倍于右、按之鼓指，左候肝，鼓指为阳升太过、肝阳鸱张之象。胃逆之极故作呃，深恐阳升太过致发厥，故急为镇逆宁神，折其上逆之势。", ["大", "鼓"]], "8124": ["病机", "产后恶露淋沥，偏右肢体络隧不舒。脉象坚细，重取带弦，坚细为营血不足而络脉不柔，带弦则气机不畅。陈者不除、新者不布，正言瘀血未净、新血不布之象。左半主血非气不流，右半主气非血易散，故虽右半不舒亦关营血，治拟和营调气。", ["坚", "细", "弦"]], "8125": ["病机", "多食桂圆辛甘温热，血热内迫致四月坠胎，胎前后血来如涌，营血暴亏。脉象虚弦，虚为血虚之极，弦为木燥生风。血虚不能荣养肝木，故头晕耳鸣、神识昏乱、目窜搐动、二便皆热。此血虚生风、有厥脱之虞，故拟滋肾养肝以柔木熄风。", ["虚", "弦"]], "8126": ["病机", "腹满中脘痞胀，肝气郁于胃中；乳中结核、咽痛、膝膑起块，皆气郁生火、炎上窜络之征。脉弦而数，弦属肝旺，数属火盛，正是木旺之征。气有余便是火，故治从肝胃两和，使气机宣通则郁热自退。", ["弦", "数"]], "8127": ["病机", "原文未出脉名，仅言脉证相安。两乳房结核时作微胀，经迟涩少，乳房属胃、乳尖属肝，结核胀为气郁；经迟涩少则营分失和、血行不畅。脉证相安示病势未深，故再调气和营，使气畅营和则结核胀满可消、经行自利。", []], "8128": ["病机", "脉滑主痰湿内蕴，重取濡软则示脾虚气弱。原文谓“脾虚则液滞为痰，胃实则胆逆为晕”，滑脉应痰，濡软应脾虚，故病机为脾虚胃实、痰湿中阻、胆阳上逆，主眩晕，兼见中气空虚。", ["滑", "濡", "软"]], "8129": ["病机", "脉沉弦带滑，沉主里，弦主气滞饮停，滑主痰湿。原文谓“气虚生痰，痰湿内伏，流行被阻”，卫气不能敷布，故四肢欠温、神情不振。此脉似阳衰而实非阳衰，乃阳气不能从中用事，主痰湿内伏、气机不畅。", ["沉", "弦", "滑"]], "8130": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。原文谓“饮气内伏”，控逐后气分仍难舒展，因脾胃失运、水湿停留、木难疏泄，厥气郁滞与土相仇，故脘胁肋攻撑作痛。此脉主肝胃不和、饮停气滞之病机。", ["沉", "弦"]], "8131": ["病机", "原文未识脉名，然述淋浊止涩、湿热内留，致尾闾作酸、少腹胀痛、便溏带泄。此乃湿压气坠、脾运不及之病机。利气调中、苦温合化取效，说明湿热壅滞、气机不畅为主，初愈不可骤补呆滞，当参补而不滞之品。", []], "8132": ["病机", "脉浮弦，浮主表主风，弦主湿主痛。原文谓“肾本素亏，风与湿郁，遂致太阳之经气不行”，肩背痛、脊强腰折，腰为肾府、背为阳明，故病机为肾亏风湿痹阻、太阳经气不利，主腰背强痛。", ["浮", "弦"]], "8133": ["病机", "脉常数，左部带弦，数主火，弦主郁主痰。原文谓“气郁则生火，火郁则生痰，肝火挟痰上升”，流入少阳之经，凝而不散，故痰疬垒垒、肢热心悸、眩晕腰酸。此脉主肝火挟痰、木火偏旺、营阴被烁之病机。", ["弦", "数"]], "8134": ["病机", "脉沉细，右寸关滑大。沉细主里虚，滑大主痰湿壅盛。原文谓“湿痰内盛，水寒之气，迫热上行，损于肺胃之络”，故咯吐灰黑稠痰、渐致吐血。此脉主湿痰内盛、水寒迫热、肺胃络伤之病机，投辛温而血止，正合此理。", ["沉", "细", "滑", "大"]], "8135": ["病机", "原文未识脉名，述喉有石鹅、不时身热，谓“阳有余阴不足”，手少阴心火旺、足少阴肾水亏，火旺水亏相因。童真未足，症象如此，病机为心肾水火不济、阴虚火旺，主喉疾身热，治当补不足泻有余。", []], "8136": ["病机", "右脉微滑，为胃有湿痰，胃欠通降；左关独弦，为风木偏亢。胃降不及则胆气不能下行，肝脾升有余而胆胃降不足，遂致眩晕。原文谓“弦为风木，偏亢之征”，又言“胃有湿痰，而胃欠通降”，说明病机为痰湿中阻、木亢升浮，故见冒眩。", ["滑", "弦"]], "8137": ["病机", "脉来弦滑，由痰气内滞，甲木升浮。陡然发厥乃阴阳一时闭塞，胃失通降，木邪摇撼所致；厥后𩠎杂、得食痞满，皆痰气内阻、胃不降浊之象。原文“痰气内滞，甲木升浮”点明病机，治宜通补中参以化痰熄肝。", ["弦", "滑"]], "8138": ["病机", "脉象沉弦，沉主里、弦主肝，为胃有痰滞隐伏、肝木横犯之征。胃痛呕吐久发，叠从肝胃主治而旋止旋发，因胶稠痰滞内踞，猛剂攻逐非久病所宜。原文“胃有痰滞隐伏”与“木邪摇撼”相应，故以胃苓法寓猛于宽。", ["沉", "弦"]], "8139": ["病机", "脉象濡滑，濡主湿、滑主痰，非虚寒之沉细。经来日迟而诸若平人，惟四肢作酸，乃痰湿占于血海，营卫之气不克宣通。原文“痰湿占于血海”点明病机，故治宜理气化痰祛湿，不治血而治其所以病血者。", ["濡", "滑"]], "8140": ["病机", "脉濡细，左关微弦。濡细为营血不足，左关微弦应肝，冲脉未满故月事数月一行；临行无痛胀涩少，惟清晨阳旺时腹中微热，乃血虚不能充盈冲脉。原文“营血不足，虽至一月，冲脉未满”说明经迟之由，拟调气以生血。", ["濡", "细", "弦"]], "8141": ["病机", "脉小软左涩，小软为气血不足，左涩为营血流行迟钝。经事愆期而腹不痛、来反过多，乃八脉拥护无权、营卫流行迟钝所致。原文“气血不足，营卫流行迟钝，八脉拥护无权”直指病机，故拟补气益血，参以升清。", ["小", "软", "涩"]], "8142": ["病机", "脉见细软，细为血虚，软为风壅不劲。头痛起于新产，额作辛胀而眉骨不痛，非外感可知；细软之脉更证血虚风壅阳络。原文“血虚风壅阳络”点明病机，故仿竹林子玉露散法，养血熄风。", ["细", "软"]], "8143": ["病机", "脉象沉细而糊，沉细为阴精不足，糊为气滞湿郁、真火无光。目糊不明而不红赤肿胀，阴滞之剂欠适，化湿祛风豁痰尚和，说明非纯阴虚，乃气滞湿郁与阴虚阳火离散兼见。原文“阴虚而阳火离散，与气滞湿郁而真火无光”并提，故目障由此而起。", ["沉", "细"]], "8144": ["病机", "原文未识脉名，但述“左膈消之症”经清金益阴后“大势已退”，而“口渴终不能全愈，苔黄心糙”，病机为肺热来自少阴，胃府浊痰郁而生热，胃脉通心，君火日动移肺。故以开展气化、不令胃中蕴郁为治，即“不治热而治热之法”。", []], "8145": ["病机", "右关脉滑大有力，主胃中湿热蒸燔；两尺敛静，知非阴亏火旺。血之上冲由胃热迫涌，阳明多气多血故吐后如常。左胁霍霍有声乃胃热上蒸、肺肝气逆。治宜清降胃土、平肺肝，勿犯实实虚虚。", ["滑", "大"]], "8146": ["病机", "脉象沉弦，面色晦黄，全无阳气有余之象，乃水气内停之征。心中悸动遇操劳或暮夜临卧而作，平素多湿，正合《金匮》水停为悸之条。病机为湿郁水停、阳气不布，治宜温理脾胃，补中寓泻。", ["沉", "弦"]], "8147": ["病机", "脉情濡而带滞，非阳气式微，乃病后湿郁、阳气不能敷布于四末。故四肢欠温而厥，但容光华泽，与阳虚肌肤淡白者不同。治拟补气运湿，宣通阳气，使湿去则阳自达。", ["濡"]], "8148": ["病机", "原文未识脉名，述中脘痛、月事不调、白带绵下、头疼眩晕、经脉抽掣、骨节作痛。病机为带下频仍、脂液耗损，肝木失涵，厥气冲胃则脘痛，化风则抽搐。治宜养血调气，兼益脾肾，气血充和则孕育可期。", []], "8149": ["病机", "脉象濡而带滑，非阳虚之候。腿股厥冷、脉络不舒，乃阳气有所不通，非阳气衰微。服鹿茸后诸病杂出，更证补阳之误。濡滑主湿郁气滞，治当通阳化湿，不可峻补。", ["濡", "滑"]], "8150": ["病机", "右关独大，主胃热。口有秽气、时渴，胃热明矣；面色无华，因胃液被灼，水谷化血微少，血不充则不上华面。治宜清胃热以裕生血之源，非蛮补所能塞责。", ["大"]], "8151": ["病机", "原文未识脉名，述夙有哮喘，肺不降、脾不运，生痰聚饮，气机凝滞，致少腹疝瘕、脐下有形、小腹胀满按之坚硬。病机为冲气不调、脉络皆阻，积聚由生。治宜宣通脉络，勿恃滋补。", []], "8152": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。原文谓“痰饮内伏”，上阻肺气则气逆，下困脾运则脾约，阳气不宣，胃土失降，胆木漂拔，精关混淆。故见卧则气逆、便艰、肢厥、胸热上冲、呕酸、筋掣、遗精。脉沉弦正合痰饮内伏、阳气不宣之病机。", ["沉", "弦"]], "8153": ["病机", "脉浮滑，浮主表主气浮，滑主湿主痰。原文谓“脾湿有余，扰动精关，心胆气浮”，故疟后遗泄、多梦纷纭、体软力乏。进分清之剂遗泄转减，说明湿浊内扰为病本，脉浮滑正是湿浊扰动、心胆气浮之象，非纯虚之候。", ["浮", "滑"]], "8154": ["病机", "脉弦微滑，弦主肝主风，滑主痰主火。患者形瘦阴虚多火，值春升之时，相火风木司年，阴虚不耐升发，肝脏阳气一时上冒，故卒然厥逆、神情迷愦。脉弦微滑反映风木升动、痰火内郁之机，治当益阴涵木、潜伏阳气。", ["弦", "滑"]], "8155": ["病机", "脉细左弦，细主阴亏，弦主肝阳。原文谓“肝肾并亏，厥阳尽从上逆”，故咽中灼热、头旋眩晕，甚则不省人事。左弦为肝阳上逆之征，细为肝肾阴血不足之象，脉症合参，病机为阴亏阳浮、肝风上扰，治宜育阴熄肝镇肝。", ["细", "弦"]], "8156": ["病机", "原文未识脉名，从症论理。久带不止，液耗阳升，头旋眩晕，足膝作酸，显系肝肾空乏、带脉失约。带脉为一身约束，带脉有损则脾胃之湿渗溢，脂液俱耗。病机重在液耗阳升、脾肾两亏，故治宜补益中气兼摄脾肾，非单纯固涩带脉。", []], "8157": ["病机", "原文未识脉名，以症推机。龟背高凸，先天禀赋有亏；两膝膑酸痛，肝肾空乏已甚；神疲力少、时或凛热，皆督护气血经络失职之候。督行于后，任行于前，八脉空虚则运动之机不灵。病机为先天亏虚、肝肾八脉并损，治宜大益肝肾并补八脉。", []], "8158": ["预后", "原文未识脉名，以症论预后。高年气血两亏，营卫不宣，脉络抽掣，四肢不遂，脏阴亏损则脏络不和，冲阳逆升则痰饮泛逆、气喘痰多，虚风自动。原文谓“古稀之年，气血有亏无长”，虽有补养宣化诸法，终难挽回，故主预后不良，尽力而已。", []], "8159": ["病机", "原文未识脉名，从症析机。产育频多，营血亏损，木失涵养，阳气升浮；夏月阳泄之时头胀眩晕胸闷，产后营气更亏，少肠木火勃升，胸闷头晕汗出、手足烙热、咽痛音喑。少阴少阳之脉皆循喉，故见咽痛音喑。病机为营血亏虚、木火升浮，治宜育阴涵阳。", []], "8160": ["病机", "原文以“关脉络不和”言胃病及络，湿聚中州则胃气不和，机关脉络失和而身痛。湿由脾失运化而生，气机鼓舞则脾运，故病机在脾弱湿困、气不运湿，非单论脉象，乃由湿滞致络脉不和之机。", []], "8161": ["病机", "脉大有力为气郁生热之征，热从内吸则子宫枯燥、不能摄精，热盛生风则头旋眩晕、脉络不和。经事无故而不孕，正由气郁化热、风阳鼓旋，故脉大有力主实热内郁，非虚损可补。", ["大"]], "8162": ["病机", "原文未识脉名，主述左脐旁瘕聚攻筑胀痛、偏右头疼、劳则带下。病机为木郁不条达，厥阴气滞积而成瘕，木旺阳升则头痛，冲气不和则奇脉不固、脂液渗泄，故以疏肝调气为法。", []], "8163": ["病机", "脉象濡滑而左尺少力、右尺沉细，濡滑主湿浊内蕴，尺弱沉细主命阳不振。壮年而神情疲弱、时多迷睡，正合少阴欲寐之文，乃阴浊弥漫、胸中阳气失旷，故宜调摄中寓扫荡阴霾。", ["濡", "滑", "细", "沉"]], "8164": ["病机", "脉形弦细、左部涩弱且有数意，弦细为阴亏木失涵养、肝强木燥，涩弱为营血亏少，数意为热迫。阴血被热所迫不能固藏，故经水反多甚至一月再至，阳化风上旋则头晕心悸轰热，总属阴弱阳强。", ["弦", "细", "涩", "数"]], "8165": ["病机", "脉象弦大，原文断为阳气有余之征，非阳衰不振。肾水不足则虚阳尽越于上、阳不下降，故上见眼目昏花、火升面热、咯稠痰，下见阳道不通。弦大为阳亢有余，与阳气衰乏者判如霄壤。", ["弦", "大"]], "8166": ["病机", "脉象细弦、关部坚硬、人迎浮露，细为营分不足、木少滋濡，弦坚为厥阳上升、甲木漂拔，浮露为阳越于上。胆失决断之职则神情妄乱、目不交睫，腹撑头晕仍是木旺见端，故拟平肝宁神。", ["细", "弦", "坚", "浮"]], "8167": ["其他", "此段论伤寒温病之异及风温辨治，未识脉名，亦不以脉象为主。原文辨秋分后咳热、痰厚稠、气喘痰鸣之证，谓与叶薛所论风温见症不符，属岁气流行之异，故列其他，不涉脉诊病机。", []], "8168": ["病机", "原文述费都督目赤多泪羞明、眉骨作痛，脉细濡而模糊。细为阴血不足，濡为湿滞，模糊示湿浊蒙蔽清窍。此非单纯水亏木旺，乃风霜雨露外感，湿邪蓄伏，兼鹤膝风旧疾，湿痹于膝，外湿引动内湿，清阳不升，故目窍不利。风药燥湿，正针对湿伏之机，非归地杞菊补水所能解。", ["细", "濡"]], "8169": ["病机", "原文述夫人胸胁痛、气升、寒热、精神疲备，脉弦。弦为肝脉，主气郁。丹溪云上升之气多从肝出，两胁隶肝，胆附肝叶为开合枢纽。木郁则痛，亢极则气升，肝胆同病，枢纽不灵，开合失常，故为寒为热。病退而精神气力衰微，乃元气为病魔所伤，弦脉示肝邪未净而根本已虚。", ["弦"]], "8170": ["主病", "原文论霍乱寒热之辨，述脉伏不起、脉伏肢冷。伏脉主邪闭阳气，寒湿霍乱中阳被困，阳气不能外达，故脉伏而肢冷。此与热症霍乱之目中流火、肛门灼热相对，寒症十中一二，脉伏肢冷正是寒湿内闭、阳气不伸之据，故当温通而非清解。", ["伏"]], "8171": ["病机", "原文论阴阳离决之机，谓阳为阴逼不走即飞，阴遇阳消非枯即槁，阴不交阳、阳不交阴，上下几如两截，枢机失政。引仲圣寸脉下不至之文，说明阴阳不相维系则精不能独居。神太用则歇，精太摇则竭，气太劳则绝，如薪尽火不传、崖溃水不治，即阴阳离决之比。此段纯论病机，未出具体脉象。", []], "8172": ["病机", "原文辨温病与湿温，温乃阳气发泄，一起即热，故脉洪而大、数而细。洪大数主阳热亢盛，热盛于表里则但热不寒、烦渴神昏、溲赤便结、舌绛焦裂；数而细则示热灼阴伤。湿温夹湿则脉不若纯温之洪数，甘寒动湿，故治当别于湿寒，明乎阳泄成热之机。", ["洪", "大", "数", "细"]], "8173": ["病机", "原文论痉，引内经诸痉项强皆属于湿，金匮分刚痉无汗表实、柔痉有汗表虚。痉由太阳而发，太阳脉起目内眦，下项连风府，循督脉行背，故颈项强急、口噤背反皆经脉所过。又太阳发汗太多致津液外脱而痉，明表实邪不出、表虚邪即入，及过汗伤津成痉之机。此段未出具体脉象。", []], "8174": ["病机", "原文论痢，谓受病之始必由于寒，夏日贪凉食冷，寒气入肠胃，至秋阳内入相争，腹痛后重为气病，由气及血则赤白互下。辨河间主湿热、丹溪分气血之偏，张石顽以血色鲜紫属热、瘀晦稀淡如鱼脑属寒。强调湿与热对举，气壮伤天者郁热多，气弱伤人者阴寒甚，当辨寒热虚实。此段未出具体脉象。", []], "8175": ["主病", "原文论白喉养阴忌表，辨喉症宜暂表者必头疼板痛、鼻塞流涕、音声重浊，为外寒包热之轻浅，辛凉散之即愈。脉多弦紧，弦主痛、主寒，紧主寒束，正合外寒包热、寒邪束表之机。少阴脉上循喉咙为津液往还之道，故咽痛详于少阴，治当清润，不可妄用辛温表散。", ["弦", "紧"]], "8176": ["病机", "脉数无力，数主热，无力为虚，合身热不扬、舌苔白不厚，知温邪挟湿，老年正虚，无力送邪外达，热为湿遏故不扬。虚体感邪，邪易内走，故急解之。", ["数", "虚"]], "8177": ["病机", "脉数主热，温邪挟湿，表热咳嗽，胸闷，为邪恋肺胃。肺失宣降则咳，胃受邪则胸闷，数脉示热未清，故宜清解。", ["数"]], "8178": ["病机", "脉濡主湿，湿温发热四日，有汗不解，舌不生苔，为湿邪深恋，阻遏气机，汗出而湿不化，故邪深恋也。", ["濡"]], "8179": ["预后", "脉细且伏，细为阴伤，伏为邪闭，湿温五日，阳明表里兼阻，三焦不通，上下失贯，陡致呃忒，一候不得大汗，虑其神昏变幻，故为预后不良之象。", ["细", "伏"]], "8180": ["病机", "脉数主热，湿温解后复病，灼热无汗，头蒙膺闷，表里两阻，烦劳之体兼发劳倦，温邪挟滞，周体作痛，表热脉数，宜解达之。", ["数"]], "8181": ["病机", "脉细弦数，细为阴伤，弦主少阳，数主热，湿温化火内蒸，两候余，舌红苔剥渴饮，灼伤阴液，连热不已，阳明之邪多于少阳，故宜甘凉辛凉玎济之。", ["细", "弦", "数"]], "8182": ["病机", "脉细数耎，细为阴伤，数为热，耎为湿滞，湿温病邪迫脏腑而致便泄，表热仍蒸，舌干苔黄，湿热内蒸，阳明表里俱病，当从手足二经治之。", ["细", "数", "耎"]], "8183": ["病机", "脉数未和，温邪退而复蒸，蒸而复退，胸膈稍舒，数脉示余热未清，将在化火，又恐复热，故常以清解，防其死灰复燃。", ["数"]], "8184": ["病机", "脉细弦数，细为阴伤，弦主热郁，数示热炽。原文“舌绛无苔嗌干渴饮”乃阳明热深且炽，蒸灼三候有余，湿热暑气交蒸，耗伤津液，故脉细弦数。此脉主阳明热盛、津伤液耗之病机，与舌绛、嗌干、渴饮相应。", ["细", "弦", "数"]], "8185": ["主病", "脉数主热，暴暑侵感，暑热内迫，故身热往来而脉数。渴饮为暑热伤津之征。原文“暴暑侵感身热往来脉数渴饮”，脉数与身热渴饮相应，说明暑热之邪外袭，正邪交争，热盛津伤，主暑热病。", ["数"]], "8186": ["病机", "脉濡数，濡主湿，数主热，暑湿热混蒸，三焦不通。原文“发热呕恶舌垢便利”，湿热内蕴，气机不畅，故脉濡数。此脉主湿热弥漫三焦、气化不利之病机，与发热、呕恶、舌垢、便利等症相应。", ["濡", "数"]], "8187": ["病机", "脉细数不显，细为邪伏阴分，数为热郁于内。酷暑助邪郁蒸阳明，表不达汗，舌红苔垢，邪伏不显。脉细数不显正合邪伏之象，主暑热内伏阳明、表气不通之病机，非轻浅之候。", ["细", "数"]], "8188": ["病机", "脉极数急，数急为热极之象。病九日酷暑日逼，化火伤津，舌绛液涸，热灼营阴。脉极数急说明暑热化火，内逼营血，津液耗涸，主热盛阴伤之病机，与舌绛液涸相应，故宜清之。", ["数", "急"]], "8189": ["治法", "脉数主热，暑伤气营，舌绛为营热之征。暑热内侵，气营两燔，故脉数。原文“暑伤气营舌绛脉数”，脉数与舌绛相应，说明暑热伤及气营，热势炽盛，故以辛寒甘寒清解为治。", ["数"]], "8190": ["病机", "脉濡主湿，暑暍薰蒸，湿邪内恋。原文“发热朝缓夕剧头蒙脉濡舌垢”，湿浊蒙蔽清阳则头蒙，湿恋不解则发热起伏。脉濡与舌垢相应，说明暑湿深伏、邪恋不解之病机，一候解达为串。", ["濡"]], "8191": ["病机", "脉数不歇，数主热，不歇示邪热持续不退。暑湿深伏阳明，呕恶舌垢，湿热内蕴。脉数不歇说明邪恋不解，热势未衰，主暑湿伏于阳明、邪热缠绵之病机，故与苦泄以清解。", ["数"]], "8192": ["病机", "脉数主热，暑湿内蒸，热邪偏盛，故身热作咳、舌垢。脉数一候，说明暑湿化热，邪未解达，仍当解达，以透邪外出。此脉数非虚数，乃实热之象，与身热、舌垢相应，示暑湿内蒸之病机。", ["数"]], "8193": ["病机", "伤暑发热旬日，愈而复蒸，神蒙，脉数舌有苔渴，症非浅者。脉数主热，暑热内蒸，蒙蔽神机，故神蒙；热盛伤津，故渴；舌有苔，示邪未化燥。脉数与此症候相应，说明暑热深恋，非轻浅之候。", ["数"]], "8194": ["病机", "脉细小数，细主阴伤，数主内热，素有血症，阴分内热，近感暑热，日午潮热。脉细小数乃阴虚内热之象，与潮热相应，说明阴分不足，暑热外袭，宜乎清化，以清暑热、养阴分。", ["细", "小", "数"]], "8195": ["病机", "烦劳伤中，气虚于内，藉感暑邪，表发热，频呃，手振，脉数而虚。数主邪热，虚主气馁，气虚邪恋，故脉数而虚。频呃、手振乃气虚风动之象，非轻浅者，宜扶气达邪，标本兼治。", ["数", "虚"]], "8196": ["病机", "暑风闭腠，发热头蒙，胸闷呕恶，脉濡数，汗不遍身，舌无苔。濡主湿，数主热，暑风挟湿，闭郁腠理，故汗不遍身；湿阻气机，故胸闷呕恶。脉濡数与暑风闭腠之病机相应，邪深恋也，宜解达之。", ["濡", "数"]], "8197": ["病机", "风热内蒸，暑风外侵，三候余表热未解，化火伤阴劫津，脉极滑数。滑主痰热，数主火盛，极滑数乃热炽阴伤之象。深恋阳明，势将走入阴经，非轻浅，宜清解达泄，辛凉甘凉兼施。", ["滑", "数"]], "8198": ["病机", "阳明热炽，劫津生痰，深恋肺胃，咳不爽，脉濡数。濡主湿滞，数主热炽，热炽劫津，痰湿内恋，故咳不爽。脉濡数与阳明热炽、痰湿深恋之病机相应，宗西昌法，清解达泄。", ["濡", "数"]], "8199": ["病机", "暑风发热，袭于肺中，咯吐腥痰，脉极数，舌绛干涸。极数主热炽，舌绛干涸示阳明热炽戕阴，劫灼津液。热伤肺络，故咯吐腥痰。脉极数与阳明热炽戕阴之病机相应，宜滋清之，以救阴液。", ["数"]], "8200": ["病机", "脉浮数主阳明表热，浮为邪在表，数为热盛。原文“发热音嘶舌白腻”为暑风袭表之象，故脉浮数应阳明客邪未解。疝气属厥阴，但先见浮数表脉，说明新感暑风引动旧疾，当先解表邪，后治疝。", ["浮", "数"]], "8201": ["病机", "脉弦数主少阳阳明合病。弦为少阳枢机不利，数为阳明里热。原文“表热里泄脘闷腹痛舌苔黄”为暑湿兼滞，邪踞少阳阳明之间，故脉弦数相应，治宜表里两解。", ["弦", "数"]], "8202": ["病机", "脉濡数主暑湿内蕴。濡为湿邪黏滞，数为暑热熏蒸。原文“暴暑薰蒸呕妨谷脘闷蒙”为暑湿蒙蔽三焦，气机不宣，故脉濡数，治当清暑芳香宣化。", ["濡", "数"]], "8203": ["病机", "脉濡涩主暑湿夹滞、三焦不宣。濡为湿阻，涩为气机不畅。原文“咳咽塞妨谷脘闷腹膨便溏”为暑邪吸受，三焦不贯，湿滞内阻，故脉濡涩，治宜芳香宣达通三焦。", ["濡", "涩"]], "8204": ["病机", "脉细数主阴虚内热。细为阴血不足，数为虚热内蒸。原文“失血之后阴虚内蒸又感暑邪发热”示阴亏之体复感暑热，脉细数说明邪从阴化，治当养阴清暑。", ["细", "数"]], "8205": ["病机", "脉濡数伏主暑湿内阻、气机郁伏。濡为湿滞，数为暑热，伏为邪郁不达。原文“伤暑旬日表里俱阻气逆呕吐”为暑湿壅遏三焦，故脉濡数而伏，提示病势增剧。", ["濡", "数", "伏"]], "8206": ["病机", "脉弦数主少阳阳明同病。弦为少阳邪郁，数为阳明热盛。原文“昼暑夜凉感于阳明兼走少阳舌黄苔垢妨谷”示暑邪偏于阳明而兼少阳，故脉弦数，治宜清化阳明兼和少阳。", ["弦", "数"]], "8207": ["病机", "脉滑数主暑湿痰热内蒸。滑为湿浊痰滞，数为热邪未清。原文“伏暑似疟挟湿内蒸表热甫退舌红苔黄垢腻”示邪未净，脉滑数应湿浊壅遏气分，治当清化湿浊。", ["滑", "数"]], "8208": ["病机", "脉细数弦滑，细为阴伤，数为热炽，弦滑主暑热内蒸、痰湿交阻。原文“秋暑蒸灼但热不寒”似瘅疟，乃暑热深伏，故脉见细数弦滑；热盛于阳明，故“起于午蒸于晡剧于夜”，一候应解，示邪有外达之机。", ["细", "数", "弦", "滑"]], "8209": ["病机", "脉濡数滑，濡主湿，数主热，滑主痰湿内蕴。原文“日晡不寒而热”“舌红苔黄”为暑邪内伏，湿与热合，故脉濡数滑；暑湿欲化火，故治以辛凉清之，使湿开热透。", ["濡", "数", "滑"]], "8210": ["病机", "脉弦滑数，弦主少阳，滑主湿痰，数主热。原文“伏暑发热退而复蒸”“舌红苔黄垢腻”乃暑湿内伏，热退而复蒸者，邪未尽也；弦滑数脉应秋令暑湿化热，故用西昌法清透。", ["弦", "滑", "数"]], "8211": ["病机", "脉细弦数，细为阴血不足，弦主湿郁，数主热。原文“伏暑挟湿内蒸似疟不准”“舌苔滑腻纳谷腹膨”为暑湿恋于阳明，老年气虚不能振达，故脉细弦数而表热不振，邪恋不解。", ["细", "弦", "数"]], "8212": ["病机", "脉弦细，弦主少阳，细主阴分渐虚。原文“新凉束暑屡欲发热不定日期”“舌灰苔干”为暑湿犹恋，阴分已伤，新凉外束，故脉弦细；当清少阳之热，兼透新凉。", ["弦", "细"]], "8213": ["病机", "脉弦细数，弦主少阳，细主阴伤，数主热。原文“阳明伏暑经府交病表热里泄”为暑热内迫阳明，经府同病，五日不解，阴液渐耗，故脉弦细数；与柴葛解肌法以透表清里。", ["弦", "细", "数"]], "8214": ["预后", "原文未明脉象，但言“形神色脉一派火象”，可知脉必数疾洪实。伏暑两候，邪火深炽，劫夺阳明津液，势将内陷生风，故见一派火象；急投辛寒甘寒已嫌迟，示预后险恶。", []], "8215": ["病机", "脉细弦，细主阴血不足，弦主少阳郁热。原文“伏暑甫热微蒸不寒而热”“高年矣”为暑热初起，高年气阴已亏，邪热不甚，故脉细弦；治以轻味清化，勿伤正气。", ["细", "弦"]], "8216": ["病机", "脉细数，细为阴伤，数为热盛。秋暑化燥，燥邪入肺，故咽痛咳呛、入夜微热、舌红苔黄。脉细数反映燥热伤阴、少阳阳明兼症，邪热内传，治宜清达。", ["细", "数"]], "8217": ["病机", "脉弦主少阳，凉风束暑，暑热内蒸不达于表，故头痛、膺闷。邪由阳明走少阳，脉弦为少阳枢机不利之象，仍应清化。", ["弦"]], "8218": ["病机", "脉细数，细为阴伤，数为热盛。秋暑灼肺，咳呛发热头痛，衰年阴液不足，虑其不胜灼热，邪热内走，脉细数示正虚邪盛。", ["细", "数"]], "8219": ["病机", "脉浮数，浮为邪在表，数为热盛。秋金燥邪灼肺，咳呛晡热，舌红苔黄嗌干，脉浮数示燥热伤肺、邪热在表，宜清之。", ["浮", "数"]], "8220": ["病机", "脉濡主湿，伏暑内热，□缠两旬，似疟不准，舌白膺闷，未经汗解，邪恋少阳阳明。脉濡示湿邪内蕴，暑湿交蒸，治宜辛凉甘凉相济。", ["濡"]], "8221": ["病机", "脉数主热，伏邪发热，秋杪燥令尚甚，热恋阳明化火内炽，唇燥齿干，身热剧于夜分。脉数示阳明热盛，燥火内燔，治宜清达辛凉。", ["数"]], "8222": ["病机", "脉细弦，细为湿滞阴伤，弦主少阳。伏暑至秋而发，不寒而热，热作于夜，舌苔腻口甜作渴妨饮，阳明湿热暗助少阳暑邪，本质湿热浮于秋令暑热。", ["细", "弦"]], "8223": ["预后", "脉极数而细软，数为热盛，细软为阴骤虚、正气不支。伏邪发于初冬，内蒸转剧，发热咳嗽，舌绛黄苔灰垢，邪犹内燔，邪正两脱，预后可虑。", ["数", "细", "软"]], "8224": ["治法", "脉濡涩细，濡为湿滞，涩为血行不畅，细为营血不足。感冒新寒，营卫失和，诸络酸楚，乃寒邪外束、营血内虚、络脉痹阻之象。脉濡涩细提示正虚邪恋，非单纯表实证，故用当归桂枝汤加味，养血通络、调和营卫，佐以祛邪。", ["濡", "涩", "细"]], "8225": ["治法", "脉浮数，浮主表，数主热。亲寒袭卫，恶风发热头痛，为风寒外袭、卫阳奋起抗邪之太阳表证。脉浮数说明邪在肌表而正气抗邪有力，热势已显。治宜解达，疏解表邪，使邪从外散，表解则热退痛止。", ["浮", "数"]], "8226": ["主病", "脉浮，为风邪伤卫之征。风伤卫，头痛、恶风、翕翕发热，乃太阳中风证。风性轻扬，袭表则卫气不固，营阴外泄，故脉浮而发热恶风。此太阳病也，治宜疏解，用桂枝汤加减调和营卫，解肌祛风。", ["浮"]], "8227": ["主病", "脉浮缓，浮主表，缓为营卫不和、风邪伤卫之象。风伤卫，恶寒恶风，热芒于夜，表邪犹在，仍作太阳治之。脉浮缓说明风邪未解，卫强营弱，故用桂枝汤加减调和营卫，解肌发表。", ["浮", "缓"]], "8228": ["病机", "脉浮数，浮主表，数主热。冬温一候，头蒙发热，舌红嗌干，风化火也。风温之邪袭表，化热伤津，故脉浮数而舌红嗌干。此表热未解，里热渐生，治宜清泄，透表清里，使风火之邪得解。", ["浮", "数"]], "8229": ["治法", "脉浮数，浮为邪在表，数为热盛。冬温发热咳嗽，乃风温袭肺，表热壅盛。脉浮数说明邪热在表，肺失清肃，故咳嗽。治宜清解，疏风清热，宣肺止咳，使表解热清则咳自止。", ["浮", "数"]], "8230": ["病机", "冬温六日，邪恋肺胃，入暮热之极，呓语咳嗽气急，舌红口渴，脉未达者，已化火也。脉未达说明邪热内闭，未能外达，热灼肺胃，故见呓语、气急、口渴。治先从阳明解达，得汗乃妥，使邪从汗解，热退津存。", []], "8231": ["治法", "脉数，主热。风温病阳明兼走少阳，表热乍蒸乍退，咳嗽一候矣。脉数说明邪热内盛，少阳枢机不利，阳明热盛，故表热起伏。治从少阳阳明清之，和解少阳，清泄阳明，使热退咳止。", ["数"]], "8232": ["病机", "脉浮数，浮为邪在表，数为热盛。冬湿化火内蒸，表热不扬，舌红苔黄，示邪恋阳明而兼表，热郁气机，蒙遏不宣。脉浮数正合表热未解、里热已蒸之机，故治以分解达邪兼清宣化，使气机之蒙遏得开。", ["浮", "数"]], "8233": ["病机", "脉弦数，弦属少阳，数主热盛。冬温化热，阳明少阳兼症，朝凉暮热，舌绛苔黄，示热郁少阳阳明，枢机不利。脉弦数应此热郁半表半里之机，故仍以清化和解为治。", ["弦", "数"]], "8234": ["主病", "脉眩数，眩示风动，数主热蒸。暑风为疟，化热蒸灼，嗌干渴饮，显系阳明热盛、风火内动。脉眩数正合暑风化热之病机，故断为阳明疟，治以和解兼清。", ["眩", "数"]], "8235": ["病机", "脉数而眩，数为热盛，眩为风动。寒轻热重，舌苔不布，胸脘瞀闷，示阳明邪多而少阳邪少，热郁气滞。脉数眩应此热盛风动之机，故仍与柴胡加括蒌汤和解兼清。", ["数", "眩"]], "8236": ["病机", "脉弦而数，弦属少阳，数主热盛。暑风为疟，疟日作作于夜，寒热俱甚，示暑风化热，郁于少阳，枢机不利。脉弦数正合少阳热郁之机，故治以解达。", ["弦", "数"]], "8237": ["病机", "脉濡极数，濡主湿滞，数主热蒸。暑湿为疟，疟虽轻短，余邪留恋，居素中虚，湿恋不清。脉濡数应此湿遏热伏、中虚湿恋之机，故治以和之为稳。", ["濡", "数"]], "8238": ["病机", "脉弦数，弦属少阳，数主热盛。暑风湿热溷蒸为疟，疟作间日，寒轻热重，舌白苔黄，头痛胸闷，示暑湿深重，郁于少阳阳明。脉弦数正合湿热郁蒸之机，故当提达兼和。", ["弦", "数"]], "8239": ["病机", "脉细弦，细主阴伤，弦属少阳。湿温化疟，疟久伤阴，少阳阳明两不和谐。脉细弦应此阴伤而枢机不利之机，故治以滋清化之。", ["细", "弦"]], "8240": ["病机", "疟已近一载而仍蒸灼，脉细数而弦，细为阴伤，数为热蒸，弦属少阳。三阴疟久延，邪恋少阳一经，阴分已耗而邪热未清，故独见弦象。治只宜和解，不可峻补，亦不可妄截，使少阳枢机得转则邪自解。", ["细", "数", "弦"]], "8241": ["病机", "三阴疟经年，虽能纳谷而脉细犹弦，弦为邪踞三阳之腑，细为阴伤及三阴之脏，腑病转脏，故拖延岁月。原文谓达邪宜顾阴、宜益气，气能生阴而不伤气，气充则疟可退，示人于细弦中识邪恋正虚之机。", ["细", "弦"]], "8242": ["预后", "疟后脉和，是邪已退而脉象平复，然消导失权，营卫尚不和谐，脾胃运化未复，故虽脉和而恐寒热复作。此段以脉和断邪退，又以营卫不谐、消导失权虑其复发，属瘥后防复之预后判断，非主病之脉。", []], "8243": ["治法", "疟复作而仍间日发，脉犹弦，弦为少阳邪未解之象，邪留半表半里，枢机不利。脉既犹弦，则当从少阳和解，不可因其反复而遽用补法，补则闭邪。原文明言当和解不宜补，正以弦脉为凭，示邪尚在而正未大虚。", ["弦"]], "8244": ["病机", "伏暑疟转三阴，寒颇重而脉反强细，强为邪势鸱张，细为邪深伏于阴分，脉与重寒相应，知邪深伏而非表浅。原文谓截之尚早，宜两调营卫，盖邪未透达，早截则闭邪，故以强细之脉断邪伏之深，治当调和营卫以透达。", ["强", "细"]], "8245": ["病机", "瘅疟但热不寒，日晡而作，兼咳嗽，脉浮且数。浮为邪在表分，数为热盛，知阳明邪兼少阳，热郁蒸于外。原文宜从少阳、阳明清之，正以浮数之脉示邪热在表里之间，当两经并治，清透为法，不可温散。", ["浮", "数"]], "8246": ["病机", "新寒引动伏邪，疟发间日而寒重热轻，脉细小而迟。细为营虚，迟为卫气不充，营卫不相和谐，故寒多热少。原文直指卫气不与营和，正以细小而迟之脉为据，知非邪盛，乃营卫失调、阳气不达所致。", ["细", "迟"]], "8247": ["治法", "胎疟反复，邪恋募原三月，元不能复，营卫失调则阴阳不和，纳少便溏，脉微。微为元气虚衰、中宫不振之象，纳少便溏亦脾弱之征。脉微不宜攻邪，宜平中宫以扶脾胃，使中气立而营卫自调，阴阳自和。", ["微"]], "8248": ["病机", "疟后余热未尽，内蒸不瘥，黄昏潮热，脉细极数。细为阴伤元虚，数为余热内蒸，故脉细极数主元气不振而余邪未净。原文谓“邪虽留恋不可从表”，正因脉细示正虚，数示邪热，故只宜扶助正元，元气充复则余邪自退，此脉象揭示虚中夹实之病机。", ["细", "数"]], "8249": ["预后", "似疟非疟缠绵二月余，咳嗽形消色夺，脉芤数，会失血。芤为血虚失血之象，数为阴虚内热之征，形消色夺而脉芤数，示青年气血耗伤已深。原文谓“怯之一途不免矣”，即脉芤数见于久病形夺者，主虚劳损怯之预后不良，非一般表证可比。", ["芤", "数"]], "8250": ["病机", "便泄腹痛而脉濡，濡为湿滞中焦、脾胃失司之象。湿困脾运则便泄，气机不畅则腹痛，脉濡正合湿邪内阻、脾不健运之机。原文谓“脉濡妨谷脾胃失司”，点明濡脉主湿伤脾胃，故治以清暑和脾，使湿化脾运则泄痛自止。", ["濡"]], "8251": ["病机", "暑湿夹滞混蒸发热，热退便泄腹痛，舌苔犹腻，脉濡数。濡主湿浊内蕴，数主暑热内蒸，濡数并见，正合暑湿夹滞、三焦失贯之机。原文谓“三焦夫贯清之和之”，即脉濡数示湿热滞阻三焦气机，故当清暑化湿、疏利三焦，使湿热分消则诸症可解。", ["濡", "数"]], "8252": ["病机", "表邪里出化而为痢，痢下后重，脉细数。细为阴血耗伤，数为湿热内蕴，痢下后重而脉细数，示暑湿夹滞伤及阴分，邪滞肠道而正气已损。原文谓“暑湿夹滞也当升清导滞”，即脉细数主湿热滞下兼阴伤，故治宜升清导滞，不可纯用攻下。", ["细", "数"]], "8253": ["病机", "暑伤气、湿阻气，表热里泄，脉微，呃逆，高年中虚邪恋。微为阳气虚衰之象，高年气弱，暑湿伤气而中阳不振，故脉微。原文谓“必当温阳达邪”，即脉微示中虚阳弱、邪恋不去，非单纯清暑可解，须温阳以助气化，达邪外出。", ["微"]], "8254": ["病机", "老年中虚，湿热内阻，阻闭三焦气机，上呃下腹痛，脉微，便溲短。微为阳气衰微，老年中虚阳弱，湿热阻闭三焦，气机不通，故脉微而见呃逆腹痛、二便短少。原文谓“通贯三焦必兼温阳逐邪”，即脉微示阳衰为本、湿热为标，须温阳通利并行。", ["微"]], "8255": ["病机", "始初霍乱而为痢，痢下无度，腹痛后重，脉濡涩数。濡主湿滞，涩主邪结血滞，数主热郁，三脉并见，示邪滞深结中宫、气血壅阻。原文谓“邪滞深结中宫必当推荡使下”，即脉濡涩数主湿热积滞胶结肠道，非轻清可解，须推荡攻下以去其结。", ["濡", "涩", "数"]], "8256": ["病机", "脉濡主湿，暑邪夹滞混蒸为痢，湿浊滞于阳明气分，故红滞居多而后重。濡为湿盛阳微之象，湿滞气阻则里急后重；先宜升清泄浊，正合濡脉湿困、清浊不分之机。", ["濡"]], "8257": ["病机", "脉濡数为暑湿食滞之征。便泄三日而不后重，是湿滞留恋阳明，未成痢积。濡主湿，数主暑热，暑湿食滞交阻阳明，故急当升清降浊，使清升浊降而泄自止。", ["濡", "数"]], "8258": ["病机", "脉细数为阴伤之象，舌光红更证痢伤阴也。伏暑酿痢缠绵半载，由冬及春至夏，久痢耗损阴液，故脉细而数、舌光红。拟仲圣法者，示当救阴清热，非徒治痢。", ["细", "数"]], "8259": ["病机", "脉数而舌光，久痢半载余，阴液大伤，虚热内生，故脉数、舌光无苔。数脉在此非实热，乃真阴亏耗、虚阳偏亢之象，惟宜滋降，以救将竭之阴，不可再事攻伐。", ["数"]], "8260": ["病机", "脉细弦主邪深正虚。痢延半载成休息痢，犹有下重，是余邪滞于肠腑、正气已伤。细为阴血不足，弦为气滞邪恋，邪深药浅故缠绵难愈，以李东垣清暑益气汤扶正祛邪。", ["细", "弦"]], "8261": ["病机", "脉细无力，休息久痢致脏真极虚，气血俱亏，故脉道不充而细、鼓动无力。脾肾阳虚不能固摄，奇经亦失所养，故当温摄脾肾、先调奇经，以复其根本。", ["细"]], "8262": ["病机", "脉微细为阳气衰微、阴血不足之候。老年脾肾两虚，下痢而兼腰痛，是肾气亦惫。微细之脉示元阳不振、脾肾双亏，故必当温补脾肾，庶可止痢而固其本。", ["微", "细"]], "8263": ["病机", "脉细极数，细为阴亏，数为虚热，痢下红滞、犹欲后重，是湿滞未清而气阴两亏。初秋至秋末久延不止，正虚邪恋，故兴仲圣法，扶正与祛邪兼顾，不可偏执。", ["细", "数"]], "8264": ["病机", "青年血气初定，本应充盈，却见道泄无梦而脉细尺数。细为阴血不足，数为相火妄动，尺部应肾，数而细说明肾阴亏而虚火扰，坎离失交。原文归因于心猿意马，即情欲妄动暗耗真阴，故脉不静而细数，主阴虚火动、心肾不交之病机。", ["细", "数"]], "8265": ["病机", "原文言思虑偏于心神，失藏失守，似痫非痫如呆，脉促而乱。促为急促不匀，乱为节律散乱无序，反映心肝脾三脏失藏、神魂魄不守，气机逆乱。七情所伤致脏气不藏，故脉来促乱，主情志内伤、神志失守之病机，非外邪实热所致。", ["促", "乱"]], "8266": ["病机", "阴气过泄则内热自生，日晡潮热而脉极细数。极细为真阴亏耗，数为虚火内煽，阴不制阳，相火胜于君火。原文谓至虚之处便是客邪，故内热可外发为疡，海底穴痛肿属少阴肾经隙处。脉极细数正示下真不保、虚火内炽之病机。", ["细", "数"]], "8267": ["病机", "男子十六天癸至，血气当勃勃，今脉细数而耎，胃纳不旺、面不华泽、肢体不健。细数为阴血不足而虚热内生，耎为脉体软弱无力，示血气未充、真阴暗伤。原文归因于欲念妄动耗损真阴，故脉不充实，主阴血亏虚、脾胃不旺之病机。", ["细", "数", "耎"]], "8268": ["病机", "湿热内蒸，蒸热发黄，脉涩数。数为热蒸，涩为湿滞血行不畅，湿热交阻于阳明，故脉来涩数。原文辨非酒湿，乃运谷迟呆、水谷之湿所积，老年气不胜湿，湿恋阳明。涩数相合，正示湿热壅滞、气机不利、脾运不健之病机，治当培中阳以化湿热。", ["涩", "数"]], "8269": ["病机", "童子伤水谷之湿，湿热内淫而面肿、小溲不利，脉细数。细为湿阻气机、脉道不充，数为湿热内蒸，湿热郁于脾肺，水道不利故肿。原文称湿肿、河白病，谓修之即愈。脉细数示湿热内蕴、脾失健运、水湿泛溢之病机，病在童子，正气未大伤。", ["细", "数"]], "8270": ["病机", "素便溏则脾阳久虚，虚而木乘，腹脘痛胀，脉细虚弦。细虚为脾土衰而气血不足，弦为肝木偏旺，土衰木旺故脉细虚中兼弦。原文直断土衰木旺，木得桂而枯，示温阳培土、平木之法。此脉主脾阳虚弱、肝木乘侮之病机，痛胀由木侮中宫而作。", ["细", "虚", "弦"]], "8271": ["病机", "始衰之年操劳太过，胃纳不旺，常欲眩晕，脉细无力。细为阴血不足，无力为阳气衰微，阴不内守而阳亦衰，故虚阳不制。体丰者往往有之，肥人多气虚痰湿，劳伤中宫则二气俱损。脉细无力正示阴阳两虚、中气不足之病机，宜培二气为治。", ["细", "无力"]], "8272": ["病机", "原文谓「脉数不鼓指」，数而无力不鼓指，非实热，乃脾胃枢机不利、纳运失职所致。胃主司纳、脾主消导，不纳不运则中焦气机壅滞，郁而脉数；正气不足故不鼓指。此脉主脾胃虚弱、枢机不利之病机，与不纳不运之症相应，故治法先理中焦。", ["数"]], "8273": ["病机", "原文言「脉迟细而馍糊」，迟细为阳气不足、气血两亏之象，模糊示胃气衰而脉道不充。肝升太过、右降不及，肝阳扰心则失慧，胃气不降则反胃，久则气血生化不足故脉迟细。此脉主肝胃不和、升降失司之病机，与神志清而失慧、常反胃相应，治当养肝和胃以助资生。", ["迟", "细"]], "8274": ["病机", "原文谓「右脉衰微左尺更耎」，右脉候脾胃，衰微为脾土虚衰；左尺候肾，耎弱为肾阳不足。中下两阳无以生土，火不生土，故常自便泄兼夜数次。此脉主脾肾阳虚、火不暖土之病机，与便泄夜数相应，治当温培中下之阳以实脾土。", ["微", "耎"]], "8275": ["病机", "原文言「两脉细涩几成中满」，细为阳气虚衰、脉道不充，涩为湿阻气机、血行不畅。脾阳久虚无以运湿，湿遏消导，气机壅滞，中下两阳式微，故脘胀复胀，渐成中满。此脉主脾阳虚衰、湿阻气滞之病机，与脘胀中满相应，治当温阳泄湿，与真武汤。", ["细", "涩"]], "8276": ["治法", "原文谓「脉不鼓指」，示肾气不足、真水下亏，非实邪壅盛。老年真水下亏，浊阴不化，小溲不清，虽兼湿热，然肾气充足则湿热自化。脉不鼓指断不可再泻膀胱，泻膀胱即泻肾。此段以脉象辨虚实，主肾虚不可攻伐之治法，与年七旬癸水久绝相应，当以填补为要。", []], "8277": ["病机", "原文未明言脉象，以「少阴之脉循喉咙挟舌」立论。少阴水亏不制处阳，虚火上炎循经上灼咽喉，故咽痛百余日矣。此属少阴水亏、虚阳上浮之病机，与久咽痛相应。治以钱仲阳补肺阿胶汤添入咸苦，滋阴降火、引阳下行，正合水亏不制阳之旨。", []], "8278": ["预后", "原文谓「脉细弦数犹恐血溢末止」，细为阴血不足，弦为肝阳偏亢，数为阳热内扰。交冬温暖，冬不藏阳，阳气不潜伏，逼近冬至阳生，阳动血溢而咯血。脉细弦数示阴虚阳亢、血热未清，故恐血溢未止。此脉主阴虚阳浮、血不归经之病机，预后当滋阴降阳。", ["细", "弦", "数"]], "8279": ["病机", "原文谓「脉数舌黄」，数为热，舌黄为热象。风入脑鼻，垂腥涕稠厚成块，风化为火，留恋肺胃，热壅鼻窍，故成鼻渊。脉数正示风火内盛之机，与舌黄、腥涕稠厚相应。此脉主风火化热、留恋肺胃之病机，鼻渊之机在于风化为火，治当清肺胃风火。", ["数"]], "8280": ["病机", "原文言肺胃热炽生痰作嗽，嗽久伤阴致阴虚阳亢，故咳少呛多而痰见血点。脉细芤数者，细为阴伤，芤为失血，数为热炽，正合虚在少阴、热恋阳明之机。初起风温袭肺，误闭其邪则邪郁化火灼肺，肺为娇柔不胜火灼，遂成劳嗽，治当柔阴保金生水，用甘咸之品。", ["细", "芤", "数"]], "8281": ["病机", "阳明失血脉细，目晡肤热，乃血去过多伤及真阴，阴亏阳亢所致。脉细为阴血不足之象，与失血后真阴亏虚相应。原文谓治法无非摄阴潜阳，然草木之功究竟式微，自保下真尤为要著，说明此脉主阴亏阳亢、血去伤真之病机，预后须重下真固本。", ["细"]], "8282": ["病机", "胃中虚客气上逆而多噫嗳，纳谷运迟，脉见濡细数。濡为气虚，细为阴亏，数为虚热，合之中气久虚、真阴亦亏。中虚则客逆不降而噫嗳，运迟则纳谷不化，阴亏则脉细数，此脉正示中气与真阴两虚、虚气上逆之病机。", ["濡", "细", "数"]], "8283": ["病机", "木火扰中，纳谷辄吐，脉细无力，原文断为鬲症，且属衰年。脉细无力者，正气已衰、胃气虚弱之象，木火虽扰而中气无力以抗，故纳辄吐。衰年见此细弱之脉，说明中虚火扰、胃气上逆而成鬲症，虽治仅可调之，预后难期速效。", ["细"]], "8284": ["病机", "烦劳伤中，中阳失运，纳谷不化而中脘作痛，两关脉软。关脉候中焦，软为阳气不振、运化无力之象，与中阳失运相应。原文谓斯中鬲也，且培之，说明此脉主中阳亏虚、纳运失职之病机，治当培补中焦而非攻伐。", ["软"]], "8285": ["病机", "肝脾肾三阴素亏，生化日薄，纳谷颇少，血生于谷而谷无生血，阴亏可知。脉极耎细数，细数为阴亏虚热，耎为不足，中心嘈杂不寐亦阴亏阳扰之征。女子二七之年正壮盛而有斯疾，责在先天真阴不充，非关后天，故以复脉汤近之，主真阴亏虚之病机。", ["细", "数"]], "8286": ["病机", "脘胁作痛，按摩则缓，脉弦细，原文断为肝著。弦为肝脉，细为络脉不畅，著者肝络之气著而不移，故痛处固定而按之稍缓。此脉主肝络气滞、著而不行之病机，与脘胁作痛相应，宜金匮旋覆花汤通肝络。", ["弦", "细"]], "8287": ["病机", "脊痛骨突三年，痛引腰膂，原文断为虚损症，病属奇经八脉之督带。虽未明言脉象，然以妇科二七天癸至、五七天癸衰论之，衰年损病难以复元，说明此属督带空虚、真元亏损之病机，补剂调理仅可颐养天年，非可复元之候。", []], "8288": ["病机", "脉细如丝，为血海空虚、肝血乏贮之象。血虚不能充盈脉道，故脉细如丝；血虚不能养胎，故结缡五载从未孕育；血虚水泛则面浮肢肿；厥少真阴枯耗，天癸定期二三月之久，皆由血虚冲任失养所致。", ["细"]], "8289": ["病机", "原文未出脉象，直言任脉为病。任脉总司一身之阴，为病则阴寒湿浊下注而为带下，气血瘀滞结聚而为瘕聚。此以任脉病机统摄带下、瘕聚二症，示病位在任脉，非以脉断。", []], "8290": ["病机", "停经之脉细涩不畅，乃血虚而冲脉不充、脉道不利；妊娠之脉滑搏流利，为血聚养胎之常。举之若无、按之濡耎，正是血虚之脉。血虚藏于肝、出于冲脉，冲为血海，故女子以血为本，补血摄冲任为一定之理。", ["细", "涩", "滑", "濡"]], "8291": ["妇人", "经阻三月而脉数滑搏，非停经闭经，乃妊娠之象。滑为血聚养胎，数为胎气有余化热；热扰胃气则呕吐妨谷。脉症合参，断为妊象，故当安之，不可妄投破血通经之品。", ["数", "滑"]], "8292": ["妇人", "经阻四月余，脉虽小而滑数，小为血聚养胎、脉道约束，滑数为胎气有余；纳谷辄吐、形色华泽、微有寒热，此非停经乃恶阻之甚者。胎气上逆犯胃则呕吐，营卫失和则寒热，故当和之安之。", ["小", "滑", "数"]], "8293": ["妇人", "妊娠七月，手太阴肺经养胎之际，脉浮滑数。浮为胎气外达，滑为血聚养胎，数为胎火内动；胎元自在长养，虽有汗不宽舒，乃火不胎静之故，非病态，无妨。", ["浮", "滑", "数"]], "8294": ["病机", "产后将及两月犹血不归经，脉弦细。弦为肝失柔和、气机郁滞，细为血虚脉道不充；显见肝不藏血、脾不统血，藏统失职，故血不归经。当宗仲圣法调治，不可一味止血。", ["弦", "细"]], "8295": ["病机", "心生血、肝藏血、脾统血，血从气生。气不生血则生内热，心惕神疲；脉微为气血俱虚、阳气不振之象，故癸水愆期。脉微主虚，凉血必兼益气生血，方合一定之理。", ["微"]], "8296": ["其他", "此段为医论序文，借吕东莱论将之语喻医道，强调'医于未病''医于将病''医于已病'及'亢阳者抑之，纯阴者化之，阴阳驳杂者调之'。所列浮沉迟数四脉仅作脉名泛举，非具体诊案，故不主某病某机，旨在阐明医道难言、治贵知机之理，属医论而非脉诊病机之文。", ["浮", "沉", "迟", "数"]], "8297": ["病机", "原文未出脉名，论中风有真中、类中之分，经络脏腑气血之别，谓'经络素虚，风乘虚入'。其病机核心在络虚风袭，故见卒然牙关紧闭、偏头风痛、脑鸣肢痹、筋脉抽搐等；虚风、肝风为患者亦附列本门，示风邪乘虚入络、肝风内动之机，非据脉而言。", []], "8298": ["病机", "原文未出脉名，论吐泻责之脾胃，兼窥六淫、脏腑寒热。'暴吐泄泻，厥逆无脉者'从肾为胃关，用白通汤加猪胆汁反佐通阳，说明吐泻剧烈可致阳气暴脱、脉道不充而厥逆无脉，病机在脾肾阳衰、阴阳不相顺接；土虚木乘、胃寒肠热亦各有所主。", []], "8299": ["病机", "原文未出脉名，论淋浊'茎中热痛，如刀刺剔''溺时艰涩'，推原精溺同门异路，败精腐浊逗遛管中，与溲溺并道相迫而痛。病机以败精阻窍、脾虚下陷、湿热下注为主，败精因劳役而成者十居六七，故治取升清、祛浊、清热、利湿，澄源而流自清。", []], "8300": ["妇人", "原文未出脉名，专论产后诸疾，如五更泄泻、崩漏、阴菌下坠、前后二阴诸疾，以固奇经八脉为纲纪；又列血寒凝位、寒入阴中、厥阴中寒、中虚血寒、津液内涸等，悉分虚实寒热酌治。要旨在产后气血亏虚、奇经失养、寒瘀互结之病机，故概列产后门。", []], "8301": ["小儿", "原文未出脉名，分痉厥、痫厥二门，以大小男妇为别。小儿体气孱弱、血脉未充、筋骨柔脆，易感六淫，故手足抽搐、角弓反张为痉，四肢逆冷为厥；男妇则因七情郁结、血气盛衰、产后血虚及厥阴肝邪为患，四肢僵痹、不省人事为痫厥，示虚实暴渐之异。", []], "8302": ["病机", "脉得细涩，十指微冷，面黄白，潮热时有时无，俨然虚极之象；然胸前板结、谵语耳聋、眼翻牙紧，实为伤寒失表、寒郁成热、热极变寒之大实羸状。细涩滞涩非真虚，乃郁热蓄盛、阳气不达、脉道不利所致，故河间谓'脉又滞涩，有微细欲绝之象'，投温药则不可救，宜表里两解。", ["细", "涩"]], "8303": ["误治", "原文未出脉名，叙危廷阶发热恶寒，屡进表散、柴葛解肌、大柴胡，致汗大出、气逆干呕、胸板结、腹鸣利下不止。引仲景'胸中实，下利不止者死'，指出误下伤中、寒热错杂于中焦之险候，故用生姜泻心汤、甘草泻心汤辛开苦降、调中止利，属误治变证之案。", []], "8304": ["病机", "脉来弦滑，弦主饮邪，滑主痰湿，知非热邪实结在里。原文谓“痰饮阻滞肠胃”，承气苦寒误下，徒损胃气，致传化失常，湿邪不走，痰饮愈逆，故胀满愈增。此脉象说明病机为痰饮内阻、气化不利，主病在肠胃，与大小便不利、咳唾多涎、呕逆上气相应。", ["弦", "滑"]], "8305": ["病机", "脉弦数劲指，重按有力，弦主里急，数主热，劲指有力为实热内结。原文谓“热邪内陷”，症见里急后重、下痢红白、烦渴谵语、呕逆胸满、腹痛拒按，皆湿热壅滞、气血受阻之象。此脉说明病机为湿热积滞、热邪内陷，主痢疾实证，与上述症候相应。", ["弦", "数", "劲", "有"]], "8306": ["病机", "脉浮紧而数，浮主表，紧主寒，数主热，为太阳伤寒表实之象。原文谓“太阳病，未经发表，邪陷肌肤”，症见发热畏寒、肢体怠惰、头腰重坠、通身带浮，皆表邪未解、寒郁化热之征。此脉说明病机为表寒外束、郁而化热，主太阳表实证，与头腰重坠、喘咳等相应。", ["浮", "紧", "数"]], "8307": ["病机", "原文未识脉名，但言“脉无阴象，腹无满结，胸无呕哕”，说明里无实邪结聚，病机为太阳失汗，邪郁肌表，湿热内蒸。症见遍身骨节疼痛、满头大汗热蒸、面目如橘色之黄、小便如栀子之汁，皆郁热不得外达之象。此脉象提示病机为表里郁遏、湿热发黄，主太阳阳明合病，与黄疸、身痛相应。", []], "8308": ["病机", "脉象颇大而气不相续，大脉主虚，气不相续为正气不足。原文谓“风湿为病”，症见遍身骨节疼痛、手不可触、微汗自出、小水不利、身面手足微肿，且重裘不脱，皆表虚里虚、风湿留着之象。此脉说明病机为风湿痹阻、表里俱虚，主风湿病，与骨节疼痛、水肿相应。", ["大"]], "8309": ["病机", "脉颇浮数，浮主表，数主热，为风热内蕴、抑遏于中之象。原文谓“风热内蕴，抑遏于中，若不外达，势必内攻脏腑”，症见恶寒发热、头痛身疼、人事昏惑、唇舌俱淡，皆风热郁遏、不得外达之征。此脉说明病机为风热内蕴、表邪未透，主疮疹内陷，与神识昏惑相应。", ["浮", "数"]], "8310": ["病机", "脉来数急，数主热，急主阴伤，为热盛阴亏之象。原文谓“下多亡阴”，症见身体倦怠、两目赤涩、谵语声高、潮热燥渴、下利，皆热邪内陷、阴液耗伤之征。所幸小水甚长，足征下源未绝。此脉说明病机为热盛阴伤、下多亡阴，主瘟疫下利，与谵语、燥渴相应。", ["数", "急"]], "8311": ["病机", "脉来鼓指无力，鼓指为虚阳外浮，无力为正气大虚，为阴阳交困之象。原文谓“表里有交困之象，阴阳有立绝之势”，症见身重如山、躯骸疼痛、谵语重复、声微息短，皆正虚邪陷、阴阳将脱之征。此脉说明病机为阴阳两虚、正气欲脱，主瘟疫虚证，与声微息短相应。", ["鼓", "无", "力"]], "8312": ["病机", "原文述“脉象模糊”，为描述性脉象，非具体脉象要素。结合症见神识昏迷、谵语不食、大便不通、小溲或遗、舌白干刺，病机为风温误治，邪不在脏腑，仅在三焦，致气机闭阻、神机失用。脉模糊反映邪郁三焦、气血运行不畅，非虚非实，故两生争用温补与攻下皆不确。", []], "8313": ["病机", "脉来长而不洪，长主气机郁滞而邪热未盛，不洪说明热未炽张。症见形瘦面垢、身热谵语、自汗多渴、头痛如劈，为暑邪内蕴、气虚身热之候。脉长与面垢合参，知暑邪伤气，热郁于内而未化火成洪，故以甘寒解暑取效。", ["长"]], "8314": ["病机", "脉寸部浮数，浮主邪在表，数主热盛。症见恶寒发热、大热不寒、饮水不辍、唇焦舌燥、便闭胸痛、烦躁，为温热病从口鼻直入，热结于胃，来势急暴。脉浮数而躁无静、刚劲冲指，示邪热内结如燎原，须防痉厥，故急攻以凉膈散。", ["浮", "数"]], "8315": ["病机", "六部俱紧，重按无力，略有弦意，紧主寒，弦主痛，无力为虚。症见咳嗽吐血、胸紧减食、恶风背寒，为风寒两伤营卫，肺气郁闭，邪无出路，迫血妄行。脉紧弦而不数大，知非内热迫血，乃外寒束表，故当疏泄腠理，夺汗则血止。", ["紧", "弦"]], "8316": ["治法", "原文仅列“生脉散”方名及“脉散”二字，脉散主气阴耗散，元气不敛。生脉散以人参、麦冬、五味子益气敛阴，正对脉散所主之气阴两伤、脉气涣散之机。此段以方示法，示人脉散当用敛补，非主病之具体症候。", ["散"]], "8317": ["病机", "脉象紧数之至，紧主寒邪外束，数主热郁于内。症见潮热咳血、胸紧头疼、久病形神未衰、声音犹重、厚衣不除，为表邪入阴、扰乱营血，外寒内热交争。紧数并见，知非单纯内伤虚火，乃外感明征，故以参苏饮提出阳分，使邪从汗解。", ["紧", "数"]], "8318": ["病机", "脉紧无汗，紧主寒，无汗为表闭。症见畏寒发热、咳嗽失红，为表邪入阴、营血被扰，与前案同属外寒束表、邪无出路之机。紧脉示寒邪闭郁腠理，当夺汗以解，前医不识表邪入阴，故治弗效。", ["紧"]], "8319": ["预后", "脉躁疾，躁为阴不敛阳，疾为阳亢无制。症见面色如赭、口秽、神情张皇、汗大如雨、身热烙手、舌苔满黄，为孤阳独治、阴不守阳之危候。躁疾之脉示阴阳离决，亢阳外越，故预后不良，原文叹“显孤阳不生之机”。", ["躁", "疾"]], "8320": ["死脉", "脉洪大急疾异常，尺肤烁指，为温病汗出复热、脉躁疾不为汗衰之象，即《内经》阴阳交死证。洪大急疾示邪热炽盛，阴液耗竭，正不胜邪，故狂言不能食，预后不良。", ["洪", "大", "疾"]], "8321": ["病机", "脉小数促，为暑温之邪深陷营分，热盛而促；转涩小，示下元阴亏，阴不化气，故溺短艰。数促仍存，邪未透表，故寒热烦冤。脉变反映邪陷与阴伤并见。", ["数", "促", "涩", "小"]], "8322": ["病机", "六脉举按皆无，脉伏之假象，实因郁热蓄盛，热深厥深，脉反滞涩。胸腹饱胀拒按、便闭溺赤、咽肿耳聋，皆热邪内闭，非阴寒虚阳，误辨则危。", ["伏", "涩"]], "8323": ["其他", "脉不躁，示无热邪内扰，与口不渴、大汗呕吐相应，属暑月饮水过多，胃中水停，非热盛。故用温胃剂取效，汗多眩悸为水气上逆，非脱证。", []], "8324": ["病机", "脉虚重按若无，非脉绝，乃暑伤气阴，气虚身热。额汗溺短、烦渴、背微恶寒、四肢逆冷，皆暑热耗气、阳郁不达之象，非阳虚，故温补无功。", ["虚"]], "8325": ["病机", "脉来浮滑，浮主风邪上受，滑主痰涎壅盛。风痰中上，故咽肿牙紧、声音不出、汤水难入；身中麻木畏寒，亦风痰阻络之征，非痈毒。", ["浮", "滑"]], "8326": ["病机", "脉左浮大，左属肝，浮大为虚风内动之象。风居空窍，扰乱不息，故偏头风、自汗不止、鼻出冷涕；火升便艰，为虚风挟火，非外风鼻渊。", ["浮", "大"]], "8327": ["病机", "脉象缓大，非气血之华，乃真阳外露、肝风内鼓之征。水不濡木，肾气将腾，故麻木、脑鸣、头眩耳鸣肢堕，缓大为虚风内动，卒倒痱中之兆。", ["缓", "大"]], "8328": ["病机", "脉小弦，弦为肝象，小示正气不足。患者便血清淡、腹中愊愊有声，乃虚风内扰、肝风内动，血不能藏。经云久风成飧泄，风属无形有声，与脉弦肝象相合，故断为虚风而非湿热实火，治以扶土制木。", ["小", "弦"]], "8329": ["病机", "左脉沉缓、右脉数急，沉缓属阴分受困，数急为虚阳上浮。面黑目赤、上热下冷、舌干黑、肢体若僵，似水衰火炎而实为风邪所中、误治致阴阳乖违。左肢微肿扪痛，正是风中经络之征，故参喑厥风痱例治。", ["沉", "缓", "数", "急"]], "8330": ["病机", "原文未识脉名。症见疮毒脓水淋漓日久，忽微热抽掣、目瞪痰响，全似惊风。其阴血先已失守，津液枯涸，筋脉不荣，阳气不藏，乃阴阳两竭之候。辛散之剂更耗其阴，故掷大秦艽汤而用理阴煎加芪附收摄。", []], "8331": ["病机", "脉来缓大，缓为虚象，大为气不敛。暴病无寒热、小水仍利，非三阳实邪；抽搐角弓、牙关紧急而神识清明，是血虚风中、筋脉瘛疭。缓大正合血虚不能荣筋，故用十全大补重肉桂加附子，扶阳以摄阴。", ["缓", "大"]], "8332": ["病机", "此段未出脉。承前案而论，血虚风中当以补益为治，若误作疏风化痰则致不起。原文辨阳邪发之必渐、阴邪发之必骤，闭症多握拳、脱症多撒手，并分中腑中脏中血脉中经络及真中类中，皆属中风辨治之要。", []], "8333": ["病机", "脉沉实而滑，沉实主里实，滑主痰、主孕。唇红面赤、仆地眼翻口噤、两手握固，似痰火闭窍，然饮食间微呕、脉滑有胎，故断为胎痫。前医误用大黄槟榔破泻，体坚病实尚可无碍，治以四物加枯芩半夏养血清痰。", ["沉", "实", "滑"]], "8334": ["病机", "此段为案后识语，未出脉。强调中风、中痰、气厥、血厥虽起于仓卒，决无屡发不愈；妇科患此当拟度其胎。有脉可凭、有症可据、有因可问，故预许为胎痫。方中收魂养神镇惊消痰补虚润燥，皆出乎心裁。", []], "8335": ["病机", "脉来弦数劲指，弦属肝、数属火、劲指为火盛搏急。形体清瘦、夜寐乱语惊怖、颧赤如烙、眩晕肢冷痰鸣，皆肝火太旺、血燥无以荫胞所致，故胎小不育，且火动生风、痰随气升而发厥。弦数劲指正合肝火血燥之机。", ["弦", "数", "劲"]], "8336": ["病机", "原文谓「尺涩关弦」，涩主血虚，弦主肝燥。尺候下焦阴血，涩则血少不充；关候肝木，弦则肝燥失柔。合之形质禀木火，性急多怒善忧，前此眩冒乃「肝风张」，故不用驱风而取养肝润燥获效。此脉示血虚肝燥、木火内动之机，主眩晕冒瞀，善后当补水滋润以柔木。", ["涩", "弦"]], "8337": ["病机", "原文「沉伏中忽显弦数，弦数中忽然沉伏」，沉伏主邪郁闭阻，弦数为肝火内动。症见呕吐呵欠、腹中绞痛、十指紧撮，乃「木强土弱，肝风病耳」，土衰木乘，胃不容谷，肝阴被火劫而筋急牵引。脉之忽伏忽显，正邪正相争、风火郁发之象，故辛散逐风反助火劫阴。", ["沉", "伏", "弦", "数"]], "8338": ["病机", "原文「按浮为风，大为虚」，断为「营卫不固，血虚风袭之候」。孕后血聚养胎，营卫空虚，风邪乘袭血脉，故周身痛痹、四肢拘挛、皮如蛇蜕。起居饮食如常，外无六经形症，内无便溺阻格，惟肢节间病，正是风中血脉而非中腑脏，故以当归四逆汤重用当归养血祛风而愈。", ["浮", "大"]], "8339": ["病机", "原文「脉盛筋强」，盛为邪火亢旺，筋强示肝木失柔。纵欲多则水竭于下，火炽于上，肝风上扰而头左大痛，疏风清火愈服愈甚，正因未治其本。故取养肝熄风、滋阴潜阳，仿济阴复脉、畜鱼置介之法，药下痛止。此脉主阴虚阳亢、水亏火炽之头痛，房劳不节则复发。", ["盛", "强"]], "8340": ["病机", "原文「脉来浮缓」，二便胸腹如常，仅苦头痛、微畏寒、得食稍可。浮缓非表邪，乃中气大虚、清阳不升、浊阴不降之象，故发表温补皆加重。前药辛温过亢劫肾水，致舌苔满黄、小水短赤。此脉主中虚气陷之头痛，法宜补中益气升清降浊，非外感可汗。", ["浮", "缓"]], "8341": ["病机", "原文列头痛「或风，或火，或寒，或痰，而脉遂成或浮，或数，或紧，或滑之形」，浮主风、数主火、紧主寒、滑主痰，四脉各对应一因。然今诊「来去应指纯静」，主绪清晰不紊，是脉与病相合而无败象，故引叔和六阴永寿之说为吉征。此段辨头风脉因相应，属病机与平脉相参之论。", ["浮", "数", "紧", "滑"]], "8342": ["其他", "原文「诊得脉如平人，不疾不徐」，脉无异常而眉棱骨内痛如刀刺，天明发、至午剧、至夜失，呈定时发作之奇症。脉平而症剧，说明病不在脉象可察之常轨，故作者自谓临症十余载未尝一遇、书中亦不载。勉从「厥阳上冒，鸡性助肝」立论，属罕见症候之记录，非平脉主病之常法。", []], "8343": ["病机", "原文仅言「脉来浮大」，然叙症为暑月腹痛呕吐、舌红口渴、目泛神昏、身热肢厥，前医误用柴胡香茹芩连寒凉，致阴毒内陷。浮大之脉在此非表非实，乃阴寒内盛、虚阳外浮之象，故断为「阴毒」，径用附子理中汤丸温中回阳，汤丸互进昼夜不辍。此脉主阴盛格阳、寒毒内闭之危候。", ["浮", "大"]], "8344": ["其他", "本段叙述刮痧治疗中阴寒沙毒之气所致呕恶胸腹痛，未涉及脉象，故脉象要素为空。原文强调“中阴寒沙毒之气”，病机为寒毒闭阻气机，升降失常，故见上呕下痛、气升痛剧、咽喉塞、声不出，属寒实闭证，非脉诊可辨。", []], "8345": ["病机", "脉来浮数，似表热，但患者平素面色失华、声音不扬，为中虚之体；潮热夜发、覆被、不喜冷水、啜粥辄呕，知表虽热而里实寒。浮数为虚阳外浮之象，非阳明实热，故断为中虚寒盛、虚阳上浮之病机。", ["浮", "数"]], "8346": ["病机", "诊脉洪大，按之寂然，洪大为外浮之象，按之寂然示中空无根，乃误汗后阴竭阳浮、戴阳于面之候。原文“误汗愈涸”“元气随汗立散”点明阴液枯竭、孤阳飞越之病机，故见大汗、舌刺、面赤、神昏、二便不利。", ["洪", "大"]], "8347": ["病机", "脉洪而大空，洪为热象，大空则中虚无力，乃误用疏风清肺、柴葛知母花粉后，阳浮于上、下元虚寒之病机。原文“阳已戴于上”“下寒”及“无根飞越孤阳”说明虚阳上越，故面红目赤、舌刺无津、谵语，而下实寒。", ["洪", "散"]], "8348": ["其他", "本段仅列“生脉散”方名，脉象写法为“脉散”，但无具体脉症描述。散脉主气血耗散、元气离散，然原文过简，无法据以分析具体病机，故仅录脉象要素，不作深论。", ["散"]], "8349": ["病机", "原文未明确脉名，但述“脉虽鼓指，重按全无”，鼓指为浮大无根之象，重按全无示中虚极，乃肾气素虚、真阳浮越肌表之病机。故见面色如妆朱红、热势沸腾、上身躁扰、下半僵冷，属戴阳证，恐战汗亡阳。", []], "8350": ["病机", "脉缓大而空，缓大为中气不足、虚阳外浮之象，空则主营血内亏。患者素有肠风便血、经不及期，外肥内虚，故知中气大虚，病从饮食劳倦而来，外耗卫、内夺营。误用达原、大柴胡后热炽躁扰，乃虚体误攻、气脱于外之变。", ["缓", "大", "空"]], "8351": ["病机", "按脉冲指，忽散如汤沸腾，散脉主元气离散、虚阳浮越。患者老年劳力感寒，误用疏散，气急神昏、黏涎满口、二便如常，形羸色晦，知为虚阳上攻脱绝之候，与热盛神昏迥异，故急用附桂理阴煎、黑锡丸回阳镇摄。", ["散"]], "8352": ["病机", "脉来虚大，为产后血虚感寒，气血不足而脉道不充，故虚；虚阳外浮，故大。继而脉来如汤沸腾，乃阴虚阳越，虚阳上奔，脉势汹涌无根，与面红目赤、耳聋谵语相应，属危笃之候。此脉由虚大转为沸腾，示阴竭阳脱，非外感实热。", ["虚", "大", "数"]], "8353": ["病机", "脉来浮缓，浮为风邪在表，缓为营卫不和，素禀阳虚，秋令伤风，寒热间作，正合桂枝汤证。后误汗伤津，辛散耗阳，脉转冲指，乃阴气弥漫，虚阳上冲，与满面红赤相应，非实火，乃误治致阴阳离决之象。", ["浮", "缓"]], "8354": ["病机", "脉虽细涩，然寸关劲指甚锐，细涩为阴血亏少，劲锐为胃气尚存、邪火内郁。面额黧黑、唇口干燥、完谷不化，乃阴亏火旺，中焦失运。脉得劲指，示生机未绝，故直许可治，非纯虚细涩之比。", ["细", "涩", "劲"]], "8355": ["病机", "脉得缓中一止，即结代之脉，为阳衰阴凝、营卫虚弱之象。卫阳虚则发热，营阴凝则畏寒，肺卫心营之机阻滞，气血不得周流，故脉结代时止。与咳嗽多痰、形体日羸、潮热畏寒相应，非痨瘵死候，乃可复脉之证。", ["缓", "结", "代"]], "8356": ["病机", "脉来鼓指，洪大无伦，为肾气上奔，虚阳外越之象。年逾七旬，阴亏下元先衰，耳中流血水、耳傍筋痛，乃肾气上奔，非湿热停耳。洪大无伦者，脉无胃气，虚阳浮越，与人事昏沉、几欲脱相应，属险候。", ["洪", "大"]], "8357": ["病机", "脉得浮大而空，两关甚急，浮大为虚阳外浮，空为阴血亏竭，关急为肝木失养、郁而化火。失血阴虚，肾水涸竭，肝木发荣无资，发为寒热，渐至枯槁。此脉示阴虚阳浮，非外感实邪，柴芩斧斤之药愈伐其生。", ["浮", "大", "空", "急"]], "8358": ["死脉", "脉辟辟然如弹石，为肾阳衰败、胃气已绝之死脉。辛苦劳力，久咳气急，两足浮肿，胶痰满口，肾阳不化，肺气不输，误进滚痰丸更伤正气。肩耸目直，脉如弹石，毫无柔和之象，势难逆挽，仅一线生机。", ["弹石"]], "8359": ["病机", "脉得尺部浮大而空，尺部候肾，浮大为虚阳外浮，空为元海无根，真阳上脱。忧怒后鼻塞咳嗽，误服散滞之品，气促面赤，喉中痰响，皆虚阳上奔之象。急与黑锡丸镇纳，继进大补元煎加桂附，引火归源，方得安卧。", ["浮", "大", "空"]], "8360": ["病机", "右脉数急主阴液亏虚、虚热内扰，故咳嗽多痰、呼吸急促、卧不着席；左脉迟软为阴血不足、脉道不充。三载劳损，阴液虚而虚阳偏亢，故右数急左迟软并见。投炙甘草汤复脉救阴，正合『阴液虚』之病机，非实火可清。", ["数", "急", "迟", "软"]], "8361": ["其他", "此段仅载炙甘草汤（复脉汤）方名及出处，未及脉象与病机，属方剂条目，故脉象要素为空。原文『方见前本门寒热如疟』提示该方前已列于寒热如疟门，此处不复述脉证，不能据以推断病机，只作方剂互见处理。", []], "8362": ["病机", "脉俱迟软、时多歇止，如徐行而怠、偶羁一步，正是结代之脉，主诸脏俱虚、气血衰少；独左关肝部弦大不歇，为土败木贼、肝木乘脾之象。咳泻潮热而补脾肾不效，正因各脏俱虚而肝独盛，虚中夹贼，故以结代脉断其虚损之机。", ["迟", "软", "结", "代"]], "8363": ["病机", "脉来虚软，主气血不足、脉络空虚。面色㿠白、肢体怠倦为气虚，舌尖深红为阴亏火动，左胁气煽不寐因阳明脉络空虚、肝风内鼓。前服归脾养心不应，是未及肝肾，故以甘温填纳封固取效，脉虚软正合『心脾肝肾俱病』之虚象。", ["虚", "软"]], "8364": ["病机", "此段论阴阳血气生成之道，谓分娩后调理失宜，阴血既伤则阳气偏盛变为虚火，成虚火劳瘵之萌。原文未明写脉象，仅言『脉从内变，色不外华』，故脉象要素为空。其病机在阴精日损、虚火内烁，见潮热、鼻血、食少力稀，非外感实火可比。", []], "8365": ["病机", "两尺蹇滞，如刀刮竹、挺挺现指，即涩脉，主气血衰残、精血枯涸。肾属水，水涸则面黧、火亢则天庭火光，阴阳亢战，故阳强不能藏密、临战即泄。脉涩异常与明堂青色、满面黧色相应，断为艰嗣之候，非泥滑之常脉。", ["涩"]], "8366": ["病机", "脉来弦数时忽一止，即弦数而结代，主肝郁化火、气血痰凝阻，冲气上逆。少腹气上则心中战栗、寒热冲咽咳嗽，服疏表补脾滋阴降气皆误，正因弦数结代非单纯虚证，乃气逆痰阻、脉道不利之候，故诸治反剧。", ["弦", "数", "结", "代"]], "8367": ["死脉", "此段为答门人问死期脉解，专论死期脉象之辨，原文未列具体脉名，故脉象要素为空。其主旨在于据脉判断预后死期，属死脉范畴，非主病、病机之论，亦不涉具体症候与治法，只作死期脉理阐释。", []], "8368": ["死脉", "原文谓“脉至如火薪然”，即洪大已极之脉。久病见此，为真脏脉尽发于外，心精已夺，故主死。其死期在草干之时，因秋令金气深，阳气消，残阳之脉极则必尽，合天时阳气并消，故不得生。此脉象反映心精耗夺、阳气外越之病机。", ["洪", "大"]], "8369": ["病机", "脉象细数，形羸发脱，腿股大肉已尽，脚垂纵缓废弛，为痿躄之候。细数乃津液枯焦、燥气焚金之象，肺热叶焦则生痿躄。起自秋间寒热咳嗽，误进燥药，津液枯焦，故脉细数。此脉主肺热叶焦、阳明虚而宗筋失润之病机。", ["细", "数"]], "8370": ["病机", "原文未识脉名，然述四肢疼痛不能运动，误进驱风燥湿等剂后烦热汗出、耳聋口燥、胸紧气促、四体不知痛痒。此由形体肥盛、素多痰火，痰火召风入窍，聚结经络，肺热叶焦则生痿躄。风药多燥，助热加病，故脉象虽未言，病机为痰火风杂并、肺热叶焦。", []], "8371": ["主病", "脉得弦紧而数，时劲于指，主表里风热之症。弦紧为风，数为热，劲于指为邪实。症见四肢十指肿痛、手足不能运动、似恶寒或微热、舌苔灰白、面色枯黑，为风热壅盛、表里俱实。故用防风通圣散双解表里，一剂便通肿消，二剂泄黑粪汗出痛止。", ["弦", "紧", "数"]], "8372": ["病机", "两脉细劲，面黑耳聋，为肝血大伤、肾水浆竭之候。细为阴血不足，劲为失柔，乃阴亏不能濡养经脉。初起便血，渐至两足痿弱，服归耆参术其血愈下、其足愈软，是补气反耗阴血。此脉主肝肾阴血枯竭、筋脉失养之病机，故以虎潜丸滋阴降火。", ["细", "劲"]], "8373": ["病机", "左数右涩，知为肝气太过、脾阴不及。数为肝热，涩为脾阴不足。体丰多劳，喜食辛酸，酸味太过则肝气以津、脾气乃绝，形肉消夺，阳痿不起。此脉主肝热脾阴虚、筋膜干急之病机，故用加味逍遥散清肝扶脾，后以六味地黄丸滋阴复形。", ["数", "涩"]], "8374": ["病机", "肾脉独大，右尺尤甚，为孤阳不生之象。服补养丸剂及附子、鹿茸等温补，反致两足无力、阳痿不举、玉茎尽缩。肾脉独大乃火旺无制，孤阳独亢，阴精被灼。此脉主肾火偏亢、阴不配阳之病机，故用滋肾丸滋阴降火，使阳得阴生。", ["大"]], "8375": ["病机", "诊得弦紧异常，目红唇燥，知为误治。病发浑身洒淅麻痹、腹痛囊胀茎缩，医者以阴症治，投灯火姜附，致胆火先燃、肾火乃盛。弦紧为肝胆火郁、气机壅滞之象，目红唇燥为热象。此脉主胆家火旺、肾火随之之病机，故用左金丸合温胆汤清胆泻火。", ["弦", "紧"]], "8376": ["病机", "脉大舌黄，身有微热，是风湿内蕴、久而化热之象。风为阳邪，湿性黏滞，风湿相合，萃于经脉，郁而化热，故脉大而舌黄。原文断为风痹而非脚气，因无恶寒发热胸满呕吐，且脉大舌黄主风湿化热。风性游移，故痛处流走，成周痹行痹；湿凝为肿，风胜为痛，脉大正示邪势方张、经隧壅滞。", ["大"]], "8377": ["病机", "形瘦多火之体，风热误汗，汗出昏厥，面红脉大。脉大者，火气焚灼，阳失阴守，独上而不下，故为厥逆。原文谓“阳失阴守，是以阳气独上而不下”，与亡阳有别，乃血液衰弱之体汗出过多，阴不维阳。脉大非实热可清降，当生阴以维阳，故用白薇汤达冲任、生血液、缓火势。", ["大"]], "8378": ["病机", "寸口洪大，两尺弦紧，腹中如焚欲饮冷水，卒然昏倒口开手撒。洪大为君火专权、火气上炎，弦紧为肾阴枯槁、水火相错。夏月红块未经清解，误用草药，热郁于内，阴亏于下，发为痱中。原文拟“肾阴枯槁，水火相错”，洪大与弦紧并见，正示上盛下虚、本虚标实之机。", ["洪", "大", "弦", "紧"]], "8379": ["病机", "各部应指急数有力，唇齿干燥，大便不通，虽见手撒遗溺似脱，实为肝火厥逆之候。形长肌瘦、喜温补、当木旺之时，肝气燥急，乳胁作胀；肝主筋，筋脉不萦故四体不用；木火生风故目精动摇。急数有力正示火盛风动，非虚脱可比，原文以“六脉俱有力”驳脱结之说。", ["急", "数"]], "8380": ["病机", "两尺脉细，甚则无，胸腹大痛、昏倒、手足逆冷、两手握固。症与脉反，若真脱必有面青大汗，今无之，故知非绝。原文引“上部有脉，下部无脉，其人当吐不吐者死”，断为伤食所致，胸中痞塞，阴阳不通，上下阻绝。尺细非肾绝，乃食滞中焦、阳气不达下之象，吐后即醒。", ["细"]], "8381": ["病机", "尺脉虽无而寸关甚坚，面色未变，喉无痰声，身体仍温。壮年体强，食后猝然胸膈大痛、昏倒肢冷，非中风中寒中气。寸关坚示食滞贲门、阻遏阳气不得下行，故尺脉不至。原文断为食厥中食，引“上部有脉，下部无脉，其人当吐”之训，烧盐涌吐痰食而愈，坚脉正主实邪壅塞。", ["坚"]], "8382": ["病机", "脉上浮下伏，继则紧伏、沉伏，转沉数。仆倒目闭口噤、手撒脚僵，先服胡椒龙眼，气机壅塞。上浮下伏与“上部有脉，下部无脉，其人当吐”相符，示邪阻中焦、阴阳不相顺接。紧伏为气闭，沉数为郁而化热。原文细辨会厌机枢不利、心地尚明，非真脱，脉伏非绝，乃气厥食滞之候。", ["浮", "伏", "紧", "数"]], "8383": ["病机", "连值房劳，小腹胀痛喜按，二便阻滞，食入即吐，无烦热，唇舌如常。前医作阴症用温补，又作实热用硝黄巴霜，愈攻愈闭，吐涎如菜汁。此非纯实可攻，乃房劳伤肾、气化不行，下窍不通则上窍不纳，关格之机。原文叹“上不得入，下不得出”，攻补皆误，脉象未载，当从症辨其本虚标实、气机窒塞。", []], "8384": ["病机", "脉弦数冲指，弦主痛、主饮，数主热。患者腹痛呕吐苦水、二便阻塞，乃宿积痰饮内结，气机壅滞，郁而化热，故脉见弦数。虽四肢厥逆似阴，但脉数冲指、饮烧酒稍可，说明非真阴症，而是酒毒湿热痰积内蕴，气逆攻痛，故脉象反映实邪内结、气机攻冲之病机。", ["弦", "数"]], "8385": ["病机", "六脉沉伏，沉主里、伏主邪闭。症见四肢逆冷、面色青白、吞酸呕吐、二便不通，似阳虚阴盛，但舌滑润非燥，知为阳气不舒、阴浊僭倨，冷痰停积中焦，闭结胶黏，致成关格。脉沉伏正是阳微阴浊内闭、气血不得宣通之象，故非承气咸寒可开，当通阳泄浊。", ["沉", "伏"]], "8386": ["病机", "两脉紧急可骇，紧主痛、主寒积，急主气逆攻冲。患者素多酒色，湿热壅膀胱、冷积聚胃腑，前阻小便后塞大肠，气无下降之权，只有升逼之势，故人迎气口脉紧急可骇。此脉象反映冷积与湿热互结、气机逆乱之关格极候，势在难挽。", ["紧", "急"]], "8387": ["病机", "脉来浮缓迟弱，浮缓为胃气虚弱，迟弱为阳气不足、津液不布。患者胸腹胀痛、大解不通，但身无寒热、口不作渴、舌无苔积，知为阴结而非阳结。脉象反映胃气虚弱、津液不布、大肠传送无力，故水谷结而为胀，当以理中汤温补胃气，非攻下所宜。", ["浮", "缓", "迟", "弱"]], "8388": ["病机", "尺寸沉小，沉主里、小主虚，但劲指有力，说明邪实内闭而正气尚存。患者大小便秘、少腹胀痛、面色正赤、额汗如珠，乃湿热闭阻下焦、膀胱气化不行之淋秘危症。脉沉小劲指，反映邪闭于里而正气未绝，故尚可设法通利，仿滋肾通关之意。", ["沉", "小"]], "8389": ["病机", "脉洪大，洪主热盛、大主邪实。患者腹鼓脚浮、小水短少、大便甚艰、气逆上冲，服五苓八正反剧，乃湿热内蓄下焦、膀胱气壅不行。脉洪大而神彩尚存，足征禀赋厚、邪虽盛而正未衰，故可耐此重症。此脉反映湿热壅盛、气化不行之单胀闭症，当泻湿热、化膀胱之气。", ["洪", "大"]], "8390": ["病机", "两尺坚搏，尺部候肾与下焦，坚搏主邪实内结。患者善饮嗜炙，素蕴湿热聚于下焦，膀胱气化不行，故溺艰腹胀。房劳后症倍盛，脉见两尺坚搏，正是湿热壅结下焦、肾阳被遏之象。此脉反映病源在酒色不节、湿热日聚，久则肾阳日耗，他日腹鼓喘急之患难免。", ["坚", "搏"]], "8391": ["病机", "脉来沉迟，沉主里、迟主寒，此段论小水不通之癃闭，详析气化不利诸因。脉沉迟提示下焦阳虚、气化无力，属有阴无阳而阴不生之证，当用八味丸、肾气汤引入肾命熏蒸而化。此脉象反映肾阳不足、膀胱气化失司，故小便不通，与湿热郁闭之脉数者不同。", ["沉", "迟"]], "8392": ["病机", "寸部浮弦时止，尺部沉迟而疾，浮弦为阳为痛，时止为气机阻滞；尺沉迟主下焦寒凝，疾则寒凝气滞之甚。合之痛闷、小水紧迫、四肢厥冷，知非阳明实热，乃生冷伤脏，冷结关元，阳气不化，膀胱气化失司，故癃闭。", ["浮", "弦", "沉", "迟"]], "8393": ["病机", "脉来浮数，肌热灼指，舌边红刺、满舌白苔、中心黄黑，为暑热外淫、肠胃寒热错杂之象。浮数非纯表热，乃热邪扰于中上二焦；误用石膏竹叶汤清里，反致心胸胀满、神昏躁扰，是胃中寒而肠中热，寒热格拒，故先连理温中，继半夏泻心调其寒热。", ["浮", "数"]], "8394": ["预后", "六脉全无，四肢冰冷，肌肉大夺，吐泻汗厥并见，是暑月寒邪直中少阴，阳气暴脱，脉微续出乃残阳一线未绝。胃为肾之关，寒邪斩关直入，与少阴肾寒之气滔天莫制，大热之药势必拒格，故先以回阳火焠挽逆，再进大剂附子理中加益志，冀续微阳。", ["微"]], "8395": ["治法", "此段论回阳火灸法，非专论脉，然以诊脉下指之理喻灸法部位：脐下三焦，中焦宜稍偏，病人长则下焦宜疏，短则宜密，犹诊脉下指之轻重疏密。回阳火能回阳于无何有之乡，凡暴中阴寒、阳缩、痰厥、气闭，用之得当立效，是外治回阳之法。", []], "8396": ["病机", "脉甚微，腹痛泄泻，十指稍冷，为阴寒初入，阳气式微。理中汤仅理中焦，药力不及下焦，故服后泄未止、厥逆愈进、腹痛愈甚，再诊无脉，知阴寒已入肾。肾司开阖，寒侵则开阖失职，故改白通汤复阳散寒，温暖肾气而安。", ["微"]], "8397": ["病机", "六脉俱无，面青唇白，腹痛厥逆，二便阻闭，胀闷之极，攻下而痛愈重，知非实热内结，乃寒邪入肾，肾气不能温煦，开阖之权尽失，故二便皆闭。与白通汤复阳散寒，使肾气得权，开阖复旧，溺长便利而安。", []], "8398": ["病机", "此段设问答以明少阴肾为胃关之义：肾受寒侵，开阖失职，或开而无阖则下利不止，或阖而无开则二便皆闭，虽症异而受病同，故均以白通汤复阳散寒、温暖肾气，使肾气得权，开者有合、合者有开。此《金匮》奥义，仲景隐而未发，悟其开阖之理则治法变化无穷。", []], "8399": ["病机", "两寸弦数，弦主肝旺，数主热盛，寸部应上焦，知脏体属阳，肝火冲逆，犯土侮金，故潮热泄泻、呕吐蛔虫、咳逆胁痛。前医误投温补，致热盛神昏、面红目赤、汗大如雨，似虚脱而实为戴阳假象，断无阴液消亡之理，故用温胆汤加石斛、桑叶、白附清肝降逆而安。", ["弦", "数"]], "8400": ["误治", "原文未明言脉象，但述‘语声低陷，神彩外扬，声陷而气必弱，神扬而内必空’，此即阳虚阴盛、气血内脱之征。腹痛夜半属阳虚阴盛，误作食积，妄用桂枝、白芍、黄芩、木香等，更下痰血数升，致四肢厥逆、躁扰而逝。脉象虽缺，然声低神扬已示根本已离，误治促其脱亡。", []], "8401": ["病机", "左关弦大之至，兼腹痛下痢、唇舌虽红而不喜茶水，知非实热。前医屡进消导苦寒，致潮热下坠。脉弦大非沉细，乃劳伤中气、营卫不调，营虚血不藏、卫虚气不固之下痢红白。弦大主木旺乘土，故制木、补土、提气三法在所必须。", ["弦", "大"]], "8402": ["病机", "原文虽未明言脉名，但云‘安得月余痛泄之病，尚有弦数之脉’，可知脉见弦数。弦主木邪，数主热，木邪乘土，故小腹绞痛、里急泄泻、腹筋牵引阴中；下寒上热，呕吐不纳，胸热腹寒，此关格之象，治仿进退黄连汤以平木清上温下。", ["弦", "数"]], "8403": ["病机", "诸脉弦小，惟两关洪大之至。弦小为气血不足，洪大为阳明胃中伏火。症见潮热畏寒、大汗易饥、便坚、牙紧流涎，皆胃火中消之候。前医误作三阳疟疾，妄用柴胡、大黄，更伤胃津。脉症相参，病在阳明胃，非太阳少阳，故以泻黄散清胃泻火。", ["弦", "小", "洪", "大"]], "8404": ["病机", "六脉急数，症见大热不寒、不知人事、牙关紧闭、面唇俱赤、胶痰满口、遍身痿软。急数主风火内炽，热则筋弛，故身软如无骨；风乘火势，火借风威，卒倒无知，乃真风火之症，类中也。治先吐痰，继疏风清热、通关化痰，使表里清而神识朗。", ["急", "数"]], "8405": ["预后", "左手沉涩，右手缓大。沉涩为饮邪内伏、阳气不布，缓大为脾虚痰盛。症见喘急痰鸣、咽塞喉锯、面赤足冷、痰如浮沫、二便艰涩，乃阴饮僭踞阳位，阳被阴逼。喘急沉涩已属败症，足胫冷示阳衰，故曰未易治。", ["沉", "涩", "缓", "大"]], "8406": ["病机", "脉来濡滑，濡主湿，滑主痰。症见恶寒胃痛、左胁疼痛、时发眩晕，乃胃中痰饮流注肝络，风旋痰眩之象。前医疏渗耗气，痰饮未去而肝络受侮。濡滑之脉正合痰湿内蕴，故以二陈加芥子、瓜蒌、枳实化痰通络而痊。", ["濡", "滑"]], "8407": ["病机", "脉又沉迟，症见独热无寒、间日一发、口不渴、身无汗、热从骨髓透肌表、四肢如焚而扪之烙手、舌润。沉迟主阳气郁遏，非瘅疟之弦数。过食生冷抑遏阳气于脾土，郁极而发，故至期发热如疟。治以升阳散火汤，使清阳出上窍，浊阴归下窍。", ["沉", "迟"]], "8408": ["病机", "原文未识脉名，但述“溺短无汗”，知为外寒内热、伏火畏寒之症。火郁土中，脾土主信，故疟按期而发。脉象虽缺，然从症推机，病机在于火郁脾土，外寒束表，内热不得外达，故独寒无热，治以升阳散火汤发散郁火。", []], "8409": ["预后", "妊身九月患疟，脉来躁乱，舌显镜光，面白唇红，青筋满露，乃津液大伤、胃火掀腾之象。汗后脉躁，最犯禁例，正虚邪盛，治不得法则母子难保。躁乱脉示胃火炽盛而津液枯竭，木邪侮土，预后堪忧。", ["躁", "乱"]], "8410": ["病机", "疟疾二旬，脉皆和平，舌苔黄滑，叠投补剂而胸膈加痞，嗳气摸胸，知饮食伤胃，食滞未消，为食疟。脉和平非无病，乃食滞内阻，营卫不通，枢机不利，故疟不愈。法当消补兼行，疏通脾胃。", ["和平"]], "8411": ["病机", "疟发无定期，寒热如冰烙，面赤口渴，脉弦大，乃水不生木，阴阳不协，亢龙有悔，似疟非疟。弦大为木旺水亏之象，虚阳外浮，非真疟疾，故八味丸补肾水而愈。", ["弦", "大"]], "8412": ["病机", "脉来洪大无伦，两尺上涌抵指，唇红面赤，喜饮热汤，舌白苔满，吐稠痰，乃阳维为病，劳疟。洪大无伦为阳浮于上，尺涌抵指为虚阳上越，阴阳不调，寒热交作，法当引阳回宅，大固中州。", ["洪", "大"]], "8413": ["其他", "原文仅“诊脉控弦，明者亦惊”，控弦即弦脉劲急，如按琴弦，主木旺、痛、饮。明者惊其脉象劲急，提示病机属肝木偏亢或饮邪内停，然文短未及具体症候，仅示脉象可畏。", ["弦"]], "8414": ["病机", "疟两月，神不衰，发时心中寒，寒久热甚多惊，触外风致四肢僵硬，气急上冲，便秘脉浮。浮脉主表，外风引动内风，气逆不降，肺气痹阻，故便秘而气急。治以宣肺降气，便通气平。", ["浮"]], "8415": ["病机", "疟症误治，寒入里化热，纯热无寒，口渴溺闭，神识昏迷，舌白干刺，脉浮数。浮数主热邪蒙闭上焦气分，肺热痹阻，清窍窒塞，浊窍不通，治当轻清解上焦窒塞。", ["浮", "数"]], "8416": ["病机", "脉浮大主风邪在表，肺气壅塞；独肺部沉数，示风邪内入化热，肺失清肃。症见浮肿、尿少、气急，乃风邪闭腠理，营卫不通，水气泛溢三焦。治以开鬼门，疏肺窍，腠理通而水自行。", ["浮", "大", "沉", "数"]], "8417": ["病机", "脉来弦数鼓指，弦主饮主痛，数主热，鼓指为邪气盛。症见咳嗽气急、寒热、尿短、腹胀，肺气受病，表散不应，清里反逆，挟虚可知。秋尽燥金气虚，肺失治节，风寒外郁，水湿内停，故脉弦数而症错杂。", ["弦", "数"]], "8418": ["病机", "脉属虚而症似湿热，疟、肿、便血三症皆虚中挟热。暑热伤气，渴啜瓜果，湿热蕴胃，三焦不化，营卫失常。脉虚为正虚，故凉血消肿治疟不效。先洁净府以杀暑热，再提陷邪从鬼门出，腠理自和。", ["虚"]], "8419": ["预后", "脉虽未识，但诊得和缓之意，知胃气与真阳尚有微存，故断为可治。单腹胀证本难治，阳气所存无几，阴气混扰，然先天禀赋厚，急进大药尚可挽回。脉有和缓即胃气未绝，为预后佳兆。", []], "8420": ["预后", "水肿症脉宜洪大，今见沉细，为火土伤败、阳气衰微之兆，故列为一不治。兼囊茎俱肿、滑泄而肿不消，共三不治。脉沉细主里虚，与洪大相反，示正气溃败，虽用回阳破格，病全不减，预后不良。", ["沉", "细"]], "8421": ["病机", "脉象俱属大虚，大而无力为虚，示脾肺两脏气化不行，水壅经络，泛溢皮肤。症见浮肿腹胀、茎肿亮、咳嗽气促，皆水湿泛滥。初与术附姜桂益火燠土，与皮肤无涉，故诸症自若；改五皮饮以皮行皮，水从溺去而肿消。", ["大", "虚"]], "8422": ["病机", "脉颇浮大，浮主风，大主虚，高年肾气不足，风邪乘虚内入。症见遍身肿、面肿甚、语言壅塞、涎唾自流，合《内经》肾风“面跗庞然，壅害于言”之旨。邪凑其虚，肺肾受病，水气泛溢，故脉浮大而见言謇流涎。", ["浮", "大"]], "8423": ["病机", "脉浮大无力，浮为虚阳外浮，大为中气不足，无力为正气衰。因苦寒攻伐伤中，脾胃受损，气机壅滞，故胸腹饱闷、胀痛、气急。合症与脉，知为攻下伤中，非实邪，故以治中汤重剂温中而愈。", ["浮", "大"]], "8424": ["病机", "脉滑主痰盛，带数主火郁，涩为痰阻气机。原文“色赤脉滑”示痰火素盛；“脉虽滑而带数”示火郁上焦，故唇燥舌赤；后“脉转涩”示痰火久郁、气血不畅。脉象紧扣痰火郁结、上焦不通之噎食病机。", ["滑", "数", "涩"]], "8425": ["预后", "脉无紧涩而浮滑，示病仍在上焦气分，未入血分，故曰可治。浮滑主痰气壅滞上焦，非牢坚沉涩之比。原文“脉无紧涩，且喜浮滑”与“病犹在上”相应，说明痰气未深结，预后尚佳。", ["浮", "滑", "弦", "数"]], "8426": ["病机", "原文虽言“脉宜细数短涩”，但实际诊得“流利平和”，示痰热内阻而胃气未败。细数短涩为痰火郁结、津伤气滞之象；流利平和则说明虽经汗下，胃气尚存，故可治。脉象与噎食痰火病机相应。", ["细", "数", "短", "涩"]], "8427": ["病机", "寸口洪滑主痰火上攻肺胃。洪为火盛，滑为痰壅，与“气逆上而呃声甚厉，咽中闭塞”相应。原文“脉来寸口洪滑”且“目胞红突”，确为痰火升腾之征，故用四磨汤降气火、化痰浊。", ["洪", "滑"]], "8428": ["病机", "右尺数盛、人迎亦大，示火逆冲上。右尺候肾，数盛为肾火妄动；人迎主胃，大为冲气上逆。原文引“诸逆冲上，皆属于火”，故脉数大主火逆冲气，与“气上冲，咽喉窒塞”相应。", ["数", "大"]], "8429": ["病机", "脉沉而劲指，沉主里、劲主阴寒内结。原文“阴浊上攻”与“沉而劲指”相应，示寒湿痰浊壅塞阳气，故见气急痰鸣、大汗如雨。劲指为阴浊搏结、阳气不宣之象，非虚寒可比。", ["沉", "劲"]], "8430": ["预后", "脉来迟细，重按乃得，迟细主中虚有寒，然“细玩有神”示胃气未绝。原文“此症之可望生者，正得脉之迟细耳”，说明迟细而有神为可治之脉，与呃声甚长、中虚气逆相应。", ["迟", "细"]], "8431": ["病机", "脉弦大洪数，弦主肝火，大洪数主火盛。原文“明明肝火为病”，与“肩胛疼痛，牵引胸胁”相应。弦大洪数示小肠火乘胆木，子来乘母之实邪，故用当归龙荟丸泻火而愈。", ["弦", "大", "洪", "数"]], "8432": ["病机", "关弦尺数、洪而有力，乃肝阳暴升、木盛生火生风之象。弦主肝旺，数主火炽，洪为阳盛，故见肘膝痛楚、面白而光、舌黄而裂、鼻煤等症。原文谓“固非阳绝，亦非阴虚”，明示此非虚证，乃肝阳拂逆、木火炽盛之实火，与“诸禁鼓栗，皆属于火”相应。", ["弦", "数", "洪"]], "8433": ["病机", "脉弦涩带沉，弦主痛、涩主血滞、沉主里，合为蓄血之征。小便长利而大便数日不通，右睪丸牵引肿痛，腰屈不伸，皆瘀血内结、气机不通所致。原文断为“蓄血无疑”，以桃仁承气汤下黑粪而愈，脉证相符。", ["弦", "涩", "沉"]], "8434": ["病机", "脉浮大而缓，浮为风邪，缓为气虚，大则中气不足。寡居多郁，肝气不调，下坠之症误用疏导大黄，重闭愈增，显系中气久伤、风邪入脏。原文谓“阳气下陷”，故以三奇散加升麻提阳气，脉浮大缓正是虚风内陷之据。", ["浮", "大", "缓"]], "8435": ["病机", "两手弦数，弦属肝木，数主热，似木邪侮土，然原文究归“阴阳错杂之邪”，即胃中寒、肠中热。腹胁胀痛、呕利、时寒时热、唇红溺赤，皆寒热错杂、肝胃不和之象。脉弦数反映木火内郁而中焦有寒，故用黄连汤加减以平调寒热。", ["弦", "数"]], "8436": ["病机", "脉得沉弦，沉主里、弦主痛，为邪结下焦、气血瘀滞之象。少腹胀急、左睪丸偏坠、胯胁牵痛、大便不通而小水清利，显系蓄血而非溺涩。原文辨“在气在血”，以桃仁承气汤重用肉桂下瘀血而愈，沉弦正是瘀血内结之脉。", ["沉", "弦"]], "8437": ["病机", "脉滑沉而有力，滑主痰积，沉主里、主痼冷，合为肝胃二经痼冷沉寒、积凝胶聚之痃癖。少腹作痛、左胁筋突、上贯胃脘下连睪丸，形瘦而神不衰，脉证相参，知非虚证，乃寒痰胶结、日久成癖，故前投温补益甚。", ["滑", "沉"]], "8438": ["病机", "六脉时伏，痛极脉多停指，然汗大如雨、水米不入、神昏懒言，貌似虚极而口不作渴、小水清利，细究为内有积热、病方入里。伏脉在此非虚寒，乃热结气壅、脉道不利所致，故以芩连芍药清火平肝、槟朴下气而通利全愈。", ["伏"]], "8439": ["病机", "脉来弦紧而沉，弦紧主痛、主凝滞，沉主里，腹中必有宿食凝滞。素属阴亏而见凝滞之脉，原文谓“有凝滞之状”，伏邪未溃不可暴攻，先以四君子加枳壳固中缓散。误服姜茶峻下，致腹中绞痛、下利数十行，正邪气缓散之征被扰。", ["弦", "紧", "沉"]], "8440": ["病机", "脉来弦大，弦为肝木亢盛，大为阳明热壅。患者形禀木火，膏粱厚味不节，致肝火冲胃，胁痛冲脘，痛时由左直上撞心，呕涎，甚则吐血。弦大之脉正合木火内炽、胃络受损之病机，故主胁痛、呕逆、吐血等症。", ["弦", "大"]], "8441": ["病机", "原文未识脉名，但言“内外脉色，悉皆火象，独唇舌不燥”。火象脉当数，然唇舌不燥，知热不在气分，乃湿热下陷肝经血分，聚于阴器，故阴户肿胀溃烂、溺痛。脉色火象而唇舌不燥，正是湿热在血分之征，主肝经湿热下注之病机。", []], "8442": ["预后", "脉象不大、脉息亦微，示正气虽虚而邪不亢盛。所患处悉白色、水液流注、无秽脓漫肿，身凉便利，七恶不见，五善备陈，故脉微与症相符，预后可治。若脉大而数则邪毒炽盛，此脉微正说明病属虚证，非实火，故主预后良好。", ["微"]], "8443": ["病机", "原文未出脉象，论脱营失精之病机。营气内夺，五志之火煎迫，经久发外，坚硬如石，破后无脓，惟流血水。此因五火交煽于内，阴阳偏阻，瘕聚成形，上下连属如流注。虽无脉，然病机为营虚火郁、气血壅滞，主百死一生之证。", []], "8444": ["病机", "原文未出脉象，然述目赤羞明，目科清火散寒无效，饮食日减，形体日瘦。谛思经旨，五脏精华上注于目，禀气于脾，今中气久虚，五脏失禀，精不注目，虚火上炎。此内因之疾，非发散可解，非沉寒可清，当从甘温泻火，主中气久虚、虚火上炎之病机。", []], "8445": ["病机", "脉息属虚，而症见能食而疲、时饥嘈杂、小便赤涩，医误作实火，连服寒凉，致面黄形瘦。脉虚为正虚之据，能食而疲乃脾弱胃强，中气大虚则溲便为之变。此脉虚正说明病本在脾虚，非实火，主脾弱胃强、中气不足之病机。", ["虚"]], "8446": ["病机", "右脉洪而无力，左脉伏而不见。洪而无力为气血虚而热壅于外，伏为经络滞而气机不通。形羸唇白、声微舌润属虚，而气冲便秘、足腨红肿热痛属气实，此脚气壅疾，气血虽虚而经络必滞，脉象正示虚中夹实、壅滞不通之病机。", ["洪", "伏"]], "8447": ["病机", "脉举按皆滑，沉候略带微数。滑主痰湿脓血，数主热。少腹胀满、肛门重坠、时下脓血，脉滑数沉取，正合肠痈脓成、湿热壅聚之病机。滑为脓血内蕴，数为热毒，故主肠痈，当排脓解毒。", ["滑", "数"]], "8448": ["预后", "原文述产后受寒、恶露不下、腹满拒按、二便俱闭，经温通后瘀滞渐下而现泄泻口渴。此时“脉无洪大，神不昏迷”，说明虽津液暴失而邪热未炽、神明未扰，脉不洪大则热势不张，故预后尚可，非危候。", []], "8449": ["病机", "原文“两尺脉亦软濡”，尺候下焦，软濡为阳气不足、血寒凝滞之象。虽腹大如箕、便闭似蓄血，但小水甚长、渴喜热饮，脉不实不数，故知非瘀热内结，乃血寒凝滞使然，当温通而不可攻下。", ["濡", "软"]], "8450": ["病机", "原文“表里俱虚，脉象浮大”，浮为虚阳外浮，大为劳气不敛，非实热之洪大。产后少腹绞痛拒按，似实而形羸气馁，脉证合参知为寒入阴中、表里俱虚，故法当托里散邪，不可峻攻。", ["浮", "大"]], "8451": ["病机", "原文“脉来迟紧带弦”，迟主寒，紧主痛，弦主气机郁滞。小产后腹痛、夜热咳嗽，前医误作瘀血、痰食，致中虚血寒。脉迟紧带弦正示中焦虚寒、血分凝滞，故用黄芪建中汤温中而安。", ["迟", "紧", "弦"]], "8452": ["病机", "原文“脉象甚微，久按觉弦”，微为阳气衰微，久按弦为寒凝血脉、肝气郁滞。产后战栗、胁痛、呕清水，面红带青，知久寒在血、厥阴中寒，相火内郁，故非表散可解，当温经养血。", ["微", "弦"]], "8453": ["病机", "原文“脉来洪数，按之亦皆鼓指”，洪数为热盛之象，似属实热。但产后血下甚涌、阴营大伤，前服芩连而火愈腾，知为阴精内竭、孤阳外扰之假热，洪数鼓指乃虚阳浮越，非实火可攻。", ["洪", "数"]], "8454": ["病机", "原文未识脉名，然述小产后恶露如崩、胸紧气迫、怒目见鬼、人事大困，断为“心阳将脱”。恶露暴崩则阴血骤失，气随血脱，神不守舍，故见妄见鬼物、神魂将离之危象，急当固脱回阳。", []], "8455": ["病机", "原文“诊两脉，幸无洪大，知为神魂不藏”。产后劳神、肝火素禀，恶露顿止而发目瞪反张、见鬼战栗，闻声见人即发。脉不洪大则非实热上攻，乃正气大伤、神魂不藏、虚风内动之候。", []], "8456": ["病机", "脉亦甚微，示产后血虚津脱，气血大伤。微脉主阳气衰微、气血不足，与大汗如洗、衣被皆透相应，为津脱之兆。然脉无躁扰，神明未乱，说明正气虽虚而未至溃散，故可大剂人参养荣汤补气生血，佐五倍子敷脐敛汗。腹痛非瘀血，乃血虚内寒，后以当归生姜羊肉汤温养而愈。", ["微"]], "8457": ["病机", "脉虽洪而重按无力，为洪脉中空之象，主内液枯涸、虚阳外浮。产后汗出两日，身热烦扰，口干发渴，舌光如镜，边刺红燥，汗出黏手，皆津血大亏之征。洪而无力说明热非实火，乃阴血不足、气无所附而外越。故用黄芪、桑叶、麦冬、五味敛液收神，仿血生于气、水生于金之意，非清实热。", ["洪"]], "8458": ["病机", "原文未识脉名，然据诊毕而论，断为八脉失调、尾闾不禁，病在奇经。患者素患小产，五更必便，屡孕屡堕，服归脾、四神、理中无效，反沉困更甚。引《内经》骨空论督脉起于少腹、循阴器、合纂间，说明督脉失权，不司约束，故前堕胎而后晨泻。冲为血海，任主胞治，治当专固奇经，非脏腑肠胃之药所能及。", []], "8459": ["病机", "原文未识脉名，此按语承前案而发。四神丸本为五更火衰泄泻而设，今施于下虚关滑，故不中肯綮。五更为诸阳之会、八脉之聚，非专固奇经不能济。余粮、石脂虽重坠，然《内经》谓有故无殒，亦无殒也，故可用于下虚关滑之孕妇，非泥于伤胎之说。此段明奇经病机与用药之理。", []], "8460": ["病机", "原文未识脉名，然六部按之全无，似属不治。心主血脉，舌为心苗，脉不至而舌本不能萦，有内外交绝之象。然呼吸调匀，神明未乱，面无杂色，均非死候。因误投下乳之药，冲任大伤，子宫脱出；又误治致肾气散越而为肿满。少阴肾脉常萦舌本，今气坠散，脉道不能上朝，故脉不至。治当收摄，用大剂养荣人参汤加鹿茸、艾叶。", []], "8461": ["病机", "原文未识脉名，然脉无弦大，可进补剂。崩漏五载，肌肤干瘦，面浮跗肿，胸胁作胀，所下腥秽，前服十全、归脾无效，必是冲脉损伤。冲称血海，为五脏六腑之海，起于胞中，胞属命门。久崩调补气血不应，当责冲脉，非独血海，气海、髓海、水谷之海亦皆禀承于命门，故治从奇经。", []], "8462": ["其他", "原文未识脉名，此段述《内经》方治，非论脉。雀卵丸治伤肝，鸡矢醴治鼓胀，半夏汤治目不瞑。鸡矢醴一剂知，二剂已，服后腹鸣行黑水，足面渐皱至膝则愈。半夏汤以长流水扬万遍煮半夏，饮后复杯则卧，汗出则已。所谓一剂知，谓药病相知，药与病合；二剂已，谓病愈。此段明古方用法及效验。", []], "8463": ["病机", "脉得右大左伏，右大主气分邪实，左伏主肝郁血滞。面青唇白，舌苔边白中黑，久未更衣，小便短少，四肢僵痹，呼号鬼神。舌黑而滑，四肢僵冷，似虚寒；然脉非微细迟弱，复面青目瞪，左脉隐伏，有绸缪郁结之情。肝为刚脏，体阴用阳，魂被火迫外游，故未至先知。肝主筋，热盛筋急，故四肢僵痹。", ["大", "伏"]], "8464": ["病机", "原文以「沉涩之脉」点出食积内伏、燥结未下之机。桃李生硬助肝犯土，阻格中焦，胃气抑遏，故腹痛而厥、吐声洪、痛声厉；先泄后闭乃热结旁流，燥结未下则痛不减，水入即吐为肠槁有火。沉主里、涩主滞，正合内伏燥结，非无脉可温。", ["沉", "涩"]], "8465": ["误治", "此段未出脉，主旨在斥误认脾胃不足而投七味白术散。疫邪传胃、协热下利，本当清解，误用温补遂致目吊反张、牙紧气促、唇舌干燥。原文「徒执白术散为渴泻圣药」正是误治关键，脉象虽缺，病机为疫热内炽、津伤风动，非虚寒可补。", []], "8466": ["病机", "原文未载脉，以「面色赤中带青」「指纹透甲」「手足指尖略厥」辨寒邪入里、肝营受寒。寒伤营血，筋脉失养，故腹痛啼哭、目珠上瞪、四肢微搐；小水直无亦寒凝阳郁。拟姜桂通阳而虑稚阳血燥，终以当归四逆养血通脉，示寒痛非辛热可妄投。", []], "8467": ["病机", "此段无脉，主旨阐「痛一阵泻一阵属火」及木强反克之理。寒热咳嗽、腹痛泄泻，医误消耗则面浮气促、食减羸瘦，又误耆术则潮热愈重、痛泄愈多。病机在肝火犯脾、木旺克土，故戊己丸止痛泄、泻白散合生脉安潮嗽，非虚劳可补。", []], "8468": ["其他", "此段仅存「脉散」及方名，属方书互见之文，非独立脉案。脉散主气耗不收、虚阳浮越，故生脉散取人参麦冬五味以敛散固脱。原文未及具体症候，只可据「脉散」推知虚寒门误表戴阳之机，不可旁生枝节。", ["散"]], "8469": ["预后", "原文标「脉散」，又详述面现五色、唇红口圈青黑、鼻准黄两颧白，判为脾胃败、肺气败。脉散为真气涣散之象，本属不治；然五色尚有润泽、目中精光了然、呕吐犹可纳粥，故断在「方败未绝之界」而许可治，全赖参术叠进固中。", ["散"]], "8470": ["病机", "原文明言「脉息微细，显系脾虚」，非暑热之燥。夏月烦渴吐泻、唇红舌赤、尿短烦躁，皆津液上下亏耗之假热；面白神慢、气急多痰方是真机。微细主脾胃大虚、阳气不振，故舍香薷滑石苦寒分利，径与七味白术散健脾生津而安。", ["微", "细"]], "8471": ["预后", "此段未出脉，以「神已大败，呼吸将绝」及吐泻交作、小水赤涩、声微息促、昏睡露睛、四肢厥逆、手足微搐、喉内痰鸣诸症，断为脾肾两败、真脾慢风。所喜尚能饮乳不辍，示胃气未绝，故虽众谓皆死，犹有可治之机，全在固脾肾、挽虚阳。", []], "8472": ["病机", "脉息沉微，沉为在里，微为阳衰。患儿吐乳洞泄、澄彻清冷、指尖冷而热汤不畏，皆脾阳式微、阴寒内盛之象；唇燥口干乃津不上承，非实热。脉证合参，病机为脾阳衰败、慢脾风将作，故用理中附子丁香温运中阳，防其虚脱。", ["沉", "微"]], "8473": ["预后", "脉得急数无伦，急数而乱，是胃败津伤、五脏精华尽发于外，中无所蓄，阴阳两竭之候。眼沉囟陷、唇舌深红干刺、烦扰不宁，皆阴竭阳浮之象。脉无伦次，胃气已绝，故断为死证，虽欲阴阳两救，亦难挽回。", ["数", "急"]], "8474": ["病机", "原文未识脉名，然述脾胃素亏、误药致泄、肌肉消瘦、面唇俱白、舌光如镜、饮一溲二，显系脾肾两损、津液消泄之消渴候。病机在脾不散精、肾不摄水，遍身津液从二便消泄而上愈渴，阴阳两损，故前贤已无治法，惟两目精彩、声音犹响，生机尚存。", []], "8475": ["病机", "脉散为阴亏阳浮、根本失守之象。患儿木火阴亏之质，口糜舌烂、颊赤溲赤、惊叫搐掣，火症显然，然苦寒叠进其火愈盛，乃无水以制火，寒之不寒。脉散正示肾水亏竭、虚阳外越，故以六味、生脉滋肾敛阴而安。", ["散"]], "8476": ["病机", "脉得沉涩，沉为在里，涩为阳衰血滞。面唇俱白、厥逆昏睡，明是无火之症；前服芩连，泄虽稍止而阳气愈竭。骤进附桂理中，阳气通行如开冰解冻，然气已先亏不能上吸，遂随泻下脱。此寒则凝、热则流，脉沉涩正是阳微寒凝之据。", ["沉", "涩"]], "8477": ["其他", "此段为门人追述受业经历，无脉象可辨，亦无病机可析。文中言启明体弱肝强、因劳致疾，仅述体质与病因，未及脉诊。全段主旨在于感念师恩、记夫子慎重临症之语，属医案序跋类文字，故列其他。", []], "8478": ["病机", "原文未识脉名，然据病源诊脉断为肝肾精血暗亏，由至阴伤及阳明之脉。身半以上渐致拘束，非外来客邪，乃精血亏虚、经脉失养所致。病机在肝肾阴亏累及阳明，属内伤虚损，故以非客邪点明辨证关键。", []], "8479": ["病机", "原文未识脉名，述劳伤肝肾、奇脉不用，遇烦则腰痛背垂，虽有失血而不可沉阴滋降。病机在肝肾劳伤、奇经失充，失血乃虚损所致而非实火，故以柔剂温通补下、充养奇脉为法，体现虚损失血忌苦寒滋降之旨。", []], "8480": ["病机", "原文未识脉名，然述“肝肾下亏，跷维奇脉，不主用事”，夏秋失血再发，劳烦内伤，背痛腰板，子后汗出，阴阳发泄。此乃下元亏虚，奇脉失养，阴阳不相维系，故汗出而发泄。病机在肝肾精血耗损，累及跷维，非独一脏。治当温养勿迟，苟不安逸，药必无功，强调摄养与药并重。", []], "8481": ["病机", "脉左弱细，右尺中虚动。左弱细为阴血不足，右尺虚动乃肾阳不藏。早食颇安、晚食不化，是脾肾两虚，自阴伤及阳。故以阴药中佐温煦，崇坎水中真阳。脉虚动应于尺，正示下焦阳浮不潜，非实热鼓动，乃虚阳失守之象。", ["弱", "细", "虚", "动"]], "8482": ["病机", "初春脉动而不鼓，收藏之司浅，当壮年未育，晨吐咸痰，皆水亏火炎、精气不充之象。脉动为阳动不藏，不鼓则根本无力，故主下焦水亏，龙火不潜。胃旺能纳谷，则专理下焦，不必以痰为虑，明示病本在肾而非脾肺。", ["动"]], "8483": ["病机", "原文未识脉名，述少年奔走劳动，动则阳升，阳气不主内守，咳非外感。龙相内灼，冲阳上举致咳，误作肺治则徒耗胃口。病人自述腰以下筋脉不束，竟夜不寐，晨必咳呕，显系中下损极，冲任不摄，阳升无制，病本在肝肾，非肺之咎。", []], "8484": ["预后", "中年脉细便燥，五液不充，即是阴亏。长夏失血，交秋再发，食减什三，为下损及胃，劳怯难愈之症。脉细主精血内亏，便燥示津液不润，食减则胃气亦败，故断为难愈。用药不宜偏寒偏热，但养精血有情，勿损胃口，是重胃气以图生机。", ["细"]], "8485": ["病机", "脉小数，是精血内损成劳，阴虚生内热。小为精血不足，数为虚热内扰，久而不复，阳气不伤而阴不能涵，故夜不成寐。此非实火，乃劳损之虚数，治当包固大气，使阴平阳秘，不可苦寒直折，反伤生生之气。", ["小", "数"]], "8486": ["病机", "形瘦脉虚，左部空大，嗽病三年，行走气喘，脐下气冲，咳甚而呕。脉虚为空，左部空大乃阴不恋阳，冲阳由胃上犯于肺。经言久咳不已则三焦受之，此他处累及，非治肺矣。任脉失任，冲气上逆，故须固下摄纳滋养，肾病在下，形容憔悴。", ["虚", "大", "空"]], "8487": ["病机", "脉细小，色白食少，不易运，入夏更瘦，不独精血不充，气弱易泄，不耐烦劳。细小为气血两亏，色白食少示脾阳不运，脏阴腑阳交损。此非一脏之病，补三阴为是，以阴中求阳，使精血渐充，运化复常，不可峻补呆滞。", ["细", "小"]], "8488": ["治法", "原文未出脉名，以“老劳不肯充复”立论，夏月热燥令气泄，形肉日瘦、行动气喘、纳食日少，皆劳伤气阴、脾肺两虚之象；喜冷食更伤中气。故主用生脉四君子，益气养阴、培土生金，从虚损本质施治，非见症治症。", []], "8489": ["病机", "“脉垂入尺”示精气下夺、根蒂不固，尺部为肾所主；吸气短促如喘、面青黄、身热尤甚，是气不归元、肝肾损极，虚阳外浮。精血下夺则脉沉垂，气不归元则吸短，虽填精充髓亦难骤效，点明损深难复。", ["垂", "短"]], "8490": ["病机", "“脉下垂右大”，垂主精血下损，右大示气虚不敛。失血半载不复，饮食虽纳而不能充长精神，行动则喘、语言气怯、著枕冲气上逆咳呛，皆精血久损、肝肾不纳、八脉失养之征，故断为损及八脉、不易治之症。", ["垂", "大"]], "8491": ["病机", "“脉数虚右大”，数为虚热，虚大为劳伤气耗。入夏咳嗽失血、饮食顿减，是劳伤内因、胃阴受戕，土不生金。故以养胃阴甘药为治，取土旺金生之义，从脾胃根本复其化源，非单纯治咳止血。", ["数", "虚", "大"]], "8492": ["病机", "原文未出脉名，述吐血后形瘦气短、动则尤甚、便溏、著枕不安欲坐起，显系下焦冲脉之气上冲，致喘咳不已；痰为脂液所化，吐咯不清，乃下损劳怯、冲气不纳之候，故断为最不易治。", []], "8493": ["病机", "“脉形数垂入尺”，数主阴亏内热，垂入尺示精血下夺、肾根不固。壮年痰多嗽血、冬底盗汗，显然真阴不旺、精血不充，虚火内扰。若不加保养，久延必成劳怯，点明壮年损怯之渐。", ["数", "垂"]], "8494": ["病机", "“脉小数，垂尺及泽穴”，小为精血不足，数为阴火内动，垂尺示下元不固。少壮精血不肯充旺，情萌内震则阴火即动，致失血咳嗽、外寒内热，此非外来客病，乃内伤偏损，能保养则不致成怯。", ["小", "数", "垂"]], "8495": ["误治", "原文未出脉名，述阴伤及阳、形羸背寒，用复脉汤去参桂姜加北沙参甘蔗浆；又言河车丸属浊阴填精，必兼建立中阳以崇生气。若医咳治血滋阴，必然败坏决裂，主旨在于纠偏救误，强调护中阳、忌纯阴滋腻。", []], "8496": ["病机", "原文未明脉名，但言“验诸色脉”，结合“虚损自下起”“子后汗泄”“食减”，可知色脉必显虚象。血后阴伤，子后阳生无力，汗泄为卫外不固；咳嗽食减乃中虚木叩。清凉更伤中阳，故“愈治愈凶”，病机在脾肾两虚、虚火上浮。", []], "8497": ["病机", "左脉浮弦为肝阳不藏，右大而缓为脾虚湿困。泻血二十年，阴血大亏，肝失濡养则内风翔动，故大腿跳跃；《金匮》“脉大为劳”示阳虚，然“劳之必宜理阴”，阴损及阳，奇脉跷维失约，腑阳脏阴交损，故食少寐艰，病机为阴阳两虚、内风动络。", ["浮", "弦", "大", "缓"]], "8498": ["治法", "此段为附方，未出脉象。所列北沙参固本、生脉合六味、都气汤加青铅等，皆从固本培元、滋填精血立法，佐以茯神、莲肉安神健脾，龟版、阿胶、河车胶填精补髓。反映前文虚损病机，治当阴阳并补、固摄下元，非清凉攻邪所宜。", []], "8499": ["病机", "形瘦脉细色夺，为精血内亏之征。下焦气冲心、痛咳甚，乃冲脉之气逆上，肝肾精血亏虚不能镇纳冲气，致气从少腹上冲心胸。此非肺脏本病，故“治肺清润无益”，病机属肝肾精血内亏、冲脉气逆，为内损难治之症。", ["细"]], "8500": ["病机", "左脉弦大若有锋锐，为肝阳亢逆、木失柔润；右脉如数按之虚濡，为肺胃气阴两虚。左升太过则右降不及，木反刑金，故咳甚呕逆。冲年阴火易动，龙相交炽，下损及胃。病机为肝阳上逆、肺胃阴虚、龙相火炽，内动精气之恙。", ["弦", "大", "数", "濡"]], "8501": ["病机", "右脉弦大数，左小数，右脉大于左，为阳升太过、阴不敛阳。操持过烦则阳动，咳嗽失血后精血枯痿，下焦元海乏收摄之权，冲脉浮阳升举，有升无降，故喘促鼻息有音、咽痛乍缓。病机为下元虚怯、冲阳上逆、精血枯痿，子令母虚。", ["弦", "大", "数", "小"]], "8502": ["病机", "色㿠白、脉小，为精气内夺之象。不食不饥、便溏不爽，属脾胃气衰；久坐脊骨痛软、行动如喘，乃肾精亏耗、骨失所养。失血内损未复，又加时疟再伤，涎沫涌吐为五液所化。病机为脾肾精气内夺、液耗神伤，非阴腻之药所宜。", ["小"]], "8503": ["预后", "夏至阴气不生，当大热气泄愈甚，百脉诸气皆空，脂液尽耗，故曰“难更苏”。阴阳互乘则为寒为热；阳由阴上越则头巅痛，风木之火入中则呕逆咳呛。液涸神竭，预后不良，仅进两仪琼玉扶至稍凉再酌，示病深难复。", ["空"]], "8504": ["预后", "脉左数甚，左脉候肝肾，数甚为阴亏火旺之象。夏季嗽血，火刑金络；入冬声嘶喉痛，金水交亏，阴损成劳。脉数而阴损，正虚邪炽，故药不易治，预后不良。", ["数"]], "8505": ["病机", "脉细促数，细为阴伤，促数为虚火内扰。肾精肝血内耗，冲脉逆气自下泛上，气不收纳，故咳嗽呕吐清涎浊沫，喘而汗出。根本先拨，药难奏功。医见血治热、见嗽治肺，是速其凶。", ["细", "促", "数"]], "8506": ["治法", "向有失血阴虚，春夏时气更伤津液，秋咳呛、舌根白胎、形质软弱，皆热伤津液之征。脉象未载，然以复脉法滋阴复脉，针对津液亏耗，不得妄用苦寒。", []], "8507": ["病机", "劳损夜热咳甚，乃阳亏无以摄伏阳气，冲脉上扰为嗽。脉象未载，然病机在阳亏冲逆，非肺热。若以清肺治嗽，则嗽不愈而胃伤废食，强调不可见嗽治肺。", []], "8508": ["主病", "脉数形瘦，数主虚火，形瘦为阴血不足。久嗽不止，火灼肺金，肌肉消削，乃劳嗽之候。脉数形瘦并见，正虚邪恋，主阴虚火旺之嗽。", ["数"]], "8509": ["治法", "色苍脉数，色苍属肝，脉数为热。嗽已半年，纳食不多，胃气已弱。热灼阴伤而胃不纳，故用甘凉润剂，清润而不犯胃，示治嗽须顾胃气。", ["数"]], "8510": ["病机", "失血后咳呛、行走气喘、心热，脉细数促。细为精血内伤，数促为阳浮上炽。下焦肝肾精血伤损，阳不潜藏，上灼为咳，故清肺寒凉则谬，当滋填潜阳。", ["细", "数", "促"]], "8511": ["治法", "复脉汤中去人参，因阴亏而阳浮，人参温补易助浮阳，故去之。脉象未载，然承前文精血伤损、阳浮上炽之机，治法取复脉滋阴，避温补以敛浮阳。", []], "8512": ["病机", "脉左数，左脉候肝肾阴分，数为阳热之象。阴亏不能制阳，虚火内动，上冲犯肺则咳，气逆上冲。原文谓“此为阴亏，乃怯症之根萌”，指出数脉在此非实热，乃阴精亏虚、虚阳浮动之兆，为虚劳怯症初起之根，故咳而气上冲。", ["数"]], "8513": ["治法", "原文仅载“复脉去参姜桂”，未直接描述脉象。复脉汤本为炙甘草汤化裁，去人参、生姜、桂枝，是减其温补走表之力，偏于滋养阴血。此条属治法调整，针对阴亏液涸而设，非论脉主病，故脉象要素为空。", []], "8514": ["病机", "右脉虚大，右关候脾胃，虚为气馁，大为津亏气浮。症见色夺形瘦、肌燥疮痍、咳嗽经年、曾经失血，皆津亏气馁、精劳内损之象。虚大脉不主实邪，而主胃阴亏耗、气不内守，故治但理胃阴，不必治咳，以胃阴复则肺自安。", ["虚", "大"]], "8515": ["病机", "脉数虚右大，数为虚阳浮动，虚为大而无力，右脉候气。久嗽咽喉痛而足冷，是上热下寒、虚阳气浮越之候。曾服八味丸引导不应，说明非单纯肾阳虚，乃虚阳上浮、下元不摄。数虚大脉正合虚阳外越、根本不足之机。", ["数", "虚", "大"]], "8516": ["兼症", "左部平和，右关弦大带滑。右关候阳明胃气，弦为气逆，大为气盛，滑主痰食。此失血非虚损，乃阳明胃气不和，气逆扰动血络所致。问胸脘不爽，正合胃气壅逆之症。故只宜暂戒酒肉辛辣，胃和则愈，不须介怀，与虚损失血迥别。", ["弦", "大", "滑"]], "8517": ["病机", "脉细呛血，细为阴血不足、脉道不充。呛血而脉细，病从下焦，气冲根怯，是下元虚损、气不归原，冲气上逆迫血。原文谓“宜戒酒色，妥守百日可旺”，强调根怯当守，戒酒色以保下焦精血，使冲气渐平，脉细可复。", ["细"]], "8518": ["病机", "脉小弦虚，小为阴血少，弦为气逆，虚为不足。久嗽失血盈碗，血止仍纳食，晨起顿嗽甚，是劳伤嗽血、胃阴亏虚。弦虚并见，非实火迫血，乃胃阴不养、气逆动血。故宜养胃阴，治肺无用，以胃阴充则脉之弦虚可缓。", ["小", "弦", "虚"]], "8519": ["病机", "脉左如刃锋，即坚劲如循刀刃，为冲脉中阳升、下元精血不足之象。多呛、夜少熟寐，呛甚必血溢，是冲气上逆、阳升无制。坚脉不主实，乃阴亏不能涵阳，冲脉之气劲急上冲。法当滋填实下元，若但寒凉清热，必致胃减，便难调治。", ["坚"]], "8520": ["病机", "左脉空为肝血不足，右脉濡为胃气虚弱，肝胃络脉失养，故右胁先痛、呛痰血块。原文点明“肝胃络伤”，又归因“情怀不舒之郁”，郁则气滞络损，形瘦食减示脾胃亦弱，故以甘缓主治，缓肝急、养胃络。", ["空", "濡"]], "8521": ["病机", "形瘦脉数，阴分不足而虚热内生。长夏见血、入秋发疟，皆因阴亏不耐时令热蒸发泄，暑热再耗其阴。原文谓“皆阴分不足”，脉数为阴虚内热之征，故须静心保养，使阴渐复而热自退。", ["数"]], "8522": ["病机", "少年脉数形瘦，原文断为“先天遗热，真阴难旺”，阴虚不能制阳，热迫血上溢而衄血。疟热再伤阴，血来更频，延及损怯。脉数正是阴亏阳亢、虚热内扰之象，故治以静药补阴，不用苦寒伤胃。", ["数"]], "8523": ["病机", "形充而脉小，非阴虚火升之细数，乃辛燥之品劫动胃络，络伤血溢，故痰嗽带血。脉小示胃阴受劫、络脉不和，而非虚火内炽。原文明辨“非阴虚火升”，故只宜薄味清养胃阴，戒酒肉烦劳。", ["小"]], "8524": ["病机", "左脉数大而坚，左属肝，数大为阳亢，坚为气结，因用力致伤，气升血上而失血。原文谓“用力致伤，气升血上”，脉坚示肝气劲急，故静坐安养以平气，用养肝阴和胃阳方，使肝阳不亢、胃气和降。", ["数", "大", "坚"]], "8525": ["病机", "诵读心烦，阳易动而阴不能守，血随气升而失血。原文未出脉名，然“阳易动，阴不能守”即病机所在，所喜胃旺则化源尚足。脉络日固须安闲保养，药以壮水制火为主，使阴充阳潜、血不复升。", []], "8526": ["病机", "劳力络动而失血，脉大寸搏，大示气浮，寸搏为肺胃络脉受扰，气逆上冲。能食则胃气尚强，咳呛乃肺失清润。原文以甘药养肺胃之阴，使络脉安宁、气不上逆，则血自止。", ["大", "搏"]], "8527": ["病机", "脉数失血而不咳，面槁无华，数为虚热内扰，然不咳则病不在肺，面槁示血去而阳未亢。原文戒“勿进阴药”，盖此数非真阴虚火，乃失血后虚阳浮动，径用阴药恐遏阳气，当别求调养。", ["数"]], "8528": ["病机", "脉大为阳气上逆，缘嗜酒沉湎、胃虚络热，加之烦恼易怒，肝胆气火易炽，肝阳犯胃，血带痰而出。大脉主阳盛气逆，火性上炎，故阳气不潜而脉形宽大。脘闷嗳气、纳食不甘，皆气火上逆、胃络受灼之征，滋阴腻补反与体质相投不合。", ["大"]], "8529": ["病机", "久咳失血，食少便溏，脉来虚小。虚小为气血两亏、脾胃虚弱之象，咳血伤肺，食少便溏则中焦运化失职，后天化源不足，故脉道不充而形小力弱。此非实邪，乃正虚为主，故当以后天脾胃为要，清气滋水退居第二义。", ["虚", "小"]], "8530": ["病机", "失血后脉细促，两足皆冷，卧著呛甚欲坐，不饥纳食勉强。细为阴血亏少，促为气逆不续，元海气乏不能摄纳，冲脉之气逆而上冲，故呛咳欲坐、足冷。此虚怯门中气不归元之候，冲气上逆而脉见细促，最为难治。", ["细", "促"]], "8531": ["病机", "脉左细数，右关弦大。左细数示精血内损、阴亏有热；右关弦大为胃气尚安而肝木偏旺。失血两三年，咳嗽气塞、腰膝酸软，显系下焦不主收纳、精血内损。纳食颇安，故议填实下元，勿以治嗽肺药妨胃，戒怒勿劳以固根本。", ["细", "数", "弦", "大"]], "8532": ["病机", "右脉大，秋暑失血、初春再发，颇能纳食。引《金匮》\"男子脉大为劳，极虚亦为劳\"，辨脉大为烦劳伤气、气浮不敛所致，极虚则情欲致损。大脉非实热，乃劳伤气耗、虚阳外浮之象，故须安静调养一年，使气复脉敛，方可期愈。", ["大"]], "8533": ["病机", "脉细软涩，气冲失血，寐欲遗精，纳谷不运，神思日倦。细软为营血不足，涩为气机不畅、精血亏耗，缘操作太过，上下失交，心脾营虚。气冲、遗精、纳呆并见，是中焦失运、上下不交之候，故先治中焦，使心脾营旺，诸症渐复，偏寒偏热之品宜禁。", ["细", "软", "涩"]], "8534": ["病机", "原文言\"络脉空隙\"，未出具体脉名，故脉象要素从缺。络脉空隙则气游行作痛，春末夏初地中阳气上升，血从气溢，是阴虚络空、气不摄血之机。阴虚咳嗽乃他脏累及于肺，若以清凉治肺，必致胃伤食减而成虚损，故当填精益髓、绸缪未病。", []], "8535": ["病机", "原文未识别出脉名，故脉象要素从缺。失血后气从少腹上冲，咳逆坐起不得寐，乃肾虚不司摄纳、冲脉上升使然。冲脉为血海，男子藏精、女子系胎，今精气内空而血独升举，食入瘕泄，火土交惫。时师以清凉治肺治咳，仅通套而已，非论病之治。", []], "8536": ["病机", "脉左涩右弦，左涩为血少阴亏，右弦为冲气上逆。失血五年，阴血久耗，冲脉不摄，故冲气逆则咳甚；天明汗泄乃阳气不藏。议柔剂阳药治下，即从脉涩弦悟出下虚冲逆之机。", ["涩", "弦"]], "8537": ["病机", "原文未出脉名，然述气冲至喉、吐咯不出，显系冲脉阳气直冲于上，任脉不司担任。纳食多嗳、便溏，下损及胃，中气亦弱。故填补下焦必佐益胃，最忌清肺寒润，正恐更伤中气。", []], "8538": ["病机", "脉缓为营卫两怯之征，失血后脉不数不弦，反见缓弱，知非实热迫血，乃负重伤力、中气受损。故当以甘剂益中，勿见血辄与滋凉，以免寒凝伤脾。", ["缓"]], "8539": ["病机", "脉微而芤，微为阳气衰，芤为阴血脱，故曰失血之象。膺胸隐痛，乃肺胃之络失养。脉证合参，知血去络空，虚象已著，非实邪为患。", ["微", "芤"]], "8540": ["病机", "盛体失血，脉左涩右弦。左涩为血亏，右弦为木气偏旺。作酸嗳逆，合引血干之条、曲直作酸之旨，责之厥阴中阳气上乘，肝木犯胃，故治从厥阴。", ["涩", "弦"]], "8541": ["病机", "脉左数搏大，数主热，搏大主阳亢。骤然跌仆，吐血仍然，安谷如常，知胃气未败，而阳气暴升莫制，络血不得宁静而泛越。故戒嗔怒情欲，防其举发。", ["数", "大"]], "8542": ["病机", "脉缓大，缓为胃气尚存，大为阳明多气多血之象。吐血甚多而安谷，知病在阳明胃络，非关他脏。戒奔走烦劳，使胃络得宁，方可冀效。", ["缓", "大"]], "8543": ["病机", "老年秋燥咳嗽，食少胃弱，脉小数。小为胃气弱，数为燥热伤津。燥邪犯肺，胃弱不任寒凉，故以清润甘药，润燥而不伤胃，从脉小数定治法。", ["小", "数"]], "8544": ["病机", "脉虚数为气阴两虚而虚热内扰之象。形寒为阳气不足，心中烦热为虚火内动，五更气升咳呛乃肺燥失润、肃降无权。秋分燥金司令，大热发泄后化燥伤肺，肺为娇脏先受其冲，故脉虚数主肺燥阴伤、虚热上扰，治宜润燥滋化源。", ["虚", "数"]], "8545": ["病机", "左寸搏数主心火偏亢、君相不宁，左关小弦而动乃肝阳化风、内风陡升。巅顶眩、脑后筋惕皆阳动所致，脉弦动为肝风内动之征。原文谓阴弱不主配，非肝脏有余，故脉象示阴虚阳浮、水不涵木，法当益水滋木培母、养心脾之营。", ["数", "弦", "动"]], "8546": ["治法", "本段仅载复脉汤去参姜桂一方，未出脉象，属治法范畴。复脉汤本为气阴两虚、脉结代而设，去参姜桂者，避其温补助阳，专取滋阴复脉之意，示人凭脉辨证后灵活加减，非脉象本身所主病机，故脉象要素从缺。", []], "8547": ["病机", "脉小微涩为气血不足、络脉瘀滞之象。右痪舌喑无声，病起上年十二月，仍能纳食，知中于脾络而非胃败。小微软弱示正气虚，涩主血行不畅、痰瘀阻络，故脉象说明脾络痹阻、机窍失灵，治以宣通灵窍，通络开喑。", ["小", "微", "涩"]], "8548": ["病机", "脉缓而男子右瘫麻木，缓为湿滞或气血不充之象。丹溪议从血虚有风，起病值冰雪寒威，寒伤营血、筋脉失养，故麻木偏瘫。脉缓在此示血虚风动兼寒凝，非平人之和缓，治以舒筋汤养血祛风、温通筋脉。", ["缓"]], "8549": ["预后", "脉微色痿，阳气已衰之明证。中年麻木筋胀，内风自动，最怕痱中，脉微为正虚无力鼓动、阳气式微之象，色痿亦阳气不能外荣。脉证合参，示正衰风动、有卒中厥脱之虞，故宜温补通阳以固本防变，属预后警示之论。", ["微"]], "8550": ["兼症", "脉静为平和之象，寝食便调，向有胃痛而饮暖烧酒相安，示中阳尚可。今春季跌仆后右肢偏麻、语音不爽，乃气伤痰阻、内窍少灵之兼症。脉静说明正气未大虚，病在痰瘀阻络而非脱证，故以脉静对照症候，辨其虚实。", ["静"]], "8551": ["预后", "目瞑戴阳为虚阳上浮之危候，脉空大乃阴精亏竭、阳气外越、脉道失充之象。空大非实大，按之无力，示肝风正甚而根本已虚。原文谓肝风正甚易回，是就风阳之象尚显而言，然脉空大终属正虚邪盛，预后须防虚脱，故列预后。", ["空", "大"]], "8552": ["病机", "脉小濡而缓，小为阴虚，濡为湿滞，缓为胃弱。此案右痪舌喑、足痱面赤戴阳，乃肾纳失司、肝风突震，脉小濡缓正合虚风内动兼湿热客气。耳后暴肿为湿热上壅，脉缓不数，故断为虚中夹湿，非纯外邪，治仿地黄饮子浊药轻投。", ["小", "濡", "缓"]], "8553": ["病机", "原文未明脉象，仅言“左部稍振”，知水亏风动。左脉稍振为肾阴渐复之象，然风从内旋，阳化气而少纳，下元不藏，故左牙痛。频用韭子烟薰辛升助阳损真，更伤阴分。声音渐振是精气略宁，若再投辛苦必致虚症蜂起，当温养柔和。", []], "8554": ["病机", "未识脉名，以“阳明脉衰，厥阴风动”立论。阳明虚则气血不荣，厥阴风动则头晕心悸、肉𥆧麻木，此风痱之渐。少饮加谷易安，示胃气尚弱，当健中培土以息风，非外风可比。", []], "8555": ["病机", "中年脉弦，右臂肢指麻痹。弦为气郁痰凝，右属气分，气弱阳不运行则痰生，水谷不化精而凝为痰。脾胃主四肢，故肢麻。治当健中佐运，滋阴血药多腻反助痰，此脉弦非肝阳独亢，乃气虚痰滞之弦。", ["弦"]], "8556": ["病机", "六脉皆弦大，形神过劳，阳动不静。弦为肝阳不潜，大为阳亢阴亏，彻夜无寐乃心肝肾阴亏、阳不入阴。脉弦大而不数，非实火，故以静摄心肝肾之阴为治，使阳得阴涵则脉自敛。", ["弦", "大"]], "8557": ["病机", "未识脉名，以肾开窍于耳、胆脉出耳后立论。烦劳太过，液耗汁干，少阴少阳枢机不利，故失聪。中年液少风动使然，非外邪闭塞，治当滋液息风、疏利枢机。", []], "8558": ["病机", "脉数耳鸣吐痰，天柱骨腰膝酸，两足冷。数为阳升，耳鸣吐痰为虚阳上浮，腰膝酸、足冷为下元虚寒。此阴亏于下、阳升于上，下虚上实，故当填补实下，引火归元，不可清上。", ["数"]], "8559": ["病机", "未识脉名，述勉强摇精致阳缩囊纵、形弱伛偻、肛门脐窍收引、咽喉牵绊、食减。少阴厥阴脉循喉咙、开窍二阴，精血有形损伤，气不充八脉，故拘束。上年柔剂阳药反致巅胀耳鸣，知脏阴宜静，厥阴恶暖喜凉，仿丹溪法。", []], "8560": ["病机", "脉数主热，热盛于上而阴亏于下，故曰上盛下虚。数脉为阳热有余，然下虚则根本已亏，热势浮越不能内守。此脉示阴虚不能制阳、虚火上炎之病机，治当固其阴以敛浮阳，使阴复则阳有所附，数脉可平。原文直言'当固其阴'，正点出下虚为本、上盛为标。", ["数"]], "8561": ["病机", "脉濡主湿、主气虚，濡而食少、腹鸣、烦倦无力，是劳伤阳气、脾运不健之象。阳气亏则水湿不化，故脉濡；脾失健运则食少腹鸣；气乏则烦倦无力。原文断为'劳伤阳气'，治以甘温补营卫，正合虚则补之、劳者温之之义，非外邪实证可比。", ["濡"]], "8562": ["病机", "弦涩之形已退，示邪气已去而正气未复。食少、神不爽健、欲大便、肛门下坠，皆中气下陷、升举无力之候。原文谓'气不复为之''气陷不藏'，因忧思伤脾致气机下陷。脉象虽退而症状仍存，故以升阳法治之，并强调开怀怡悦以助气机舒展，不独恃药饵。", ["弦", "涩"]], "8563": ["病机", "左弱右弦，左候阳气不足故弱，右候湿郁气滞故弦。阳气素亏则背寒冬嗽，湿中有热蒸则纳谷䐜胀、口舌咽喉窒塞。原文指出'湿中有热气蒸，肺气𪱥郁'，是湿郁化热、肺气不宣之病机。弱脉示正虚，弦脉示郁滞，虚实夹杂，故见外寒内热、上窒中胀之症。", ["弱", "弦"]], "8564": ["病机", "本段未出脉名，纯论病机。夏秋气大发泄，久热伤气，虚体未能收肃，故肢节时寒、巅顶欲冷。原文谓'病久诸气交馁''液髓暗枯''血脉不营''阴乏内守'，皆生气浅薄之候。治当温养益气、填补充形，助秋冬收藏以豫为来春生发之用，体现因时调神之旨。", []], "8565": ["病机", "脉数而虚，数非实热，乃劳倦伤气、虚阳浮动之数；虚则正气不足。面黄肌瘦、形寒食少，皆脾阳亏虚、气血不荣之象。原文明言'劳倦致伤，不可为外感有余'，警示勿以数脉误作外邪实热而妄攻。此属内伤虚损，治当温补，与实证数脉之有力者迥别。", ["数", "虚"]], "8566": ["病机", "脉涩缓无神，涩主血少气滞，缓而无神主胃气衰败。胁痛吐痰腥秽，是肝病及胃、木邪犯土；减食、短气、寒热，则中气日损、营卫不和。原文断为'肝病入胃显然，劳伤不复'，示病由肝传胃、正气难复之机。无神之脉尤为关键，反映胃气已伤、生机不振。", ["涩", "缓"]], "8567": ["病机", "色夺脉小，色脉俱衰，形寒久嗽，是营卫二气久损之候。脉小主气血不足，色夺示荣华外竭，形寒久嗽则卫阳不固、肺气久伤。原文引《内经》'劳者温之，损者益之'，明此属劳伤虚损，当以温益为法。脉小与色夺并见，正合虚劳之诊，非邪实壅遏之小脉可比。", ["小"]], "8568": ["病机", "脉大缓而无力，大缓为脾胃气衰、中阳不振之象，无力则正气亏虚。色黄痿瘁、喜暖恶凉，皆脾阳不足、营血不荣之征；心下痛连胁肋，乃劳倦内伤日久，脾络失养、气机不畅，延为脾厥。故以辛甘温养血络为治，脉象正示劳倦内伤、脾营虚寒之病机。", ["大", "缓", "虚"]], "8569": ["病机", "咳喘频发而脉细畏寒，细为气血不足、阳气衰微之象。畏寒示下焦阳虚，肾不纳气，气逆于上则咳喘频作。脉细与畏寒并见，说明下元虚冷、摄纳无权，非外邪壅肺之实喘。原文断为「下不纳」，正指肾虚不能纳气归元之病机。", ["细"]], "8570": ["病机", "脉沉迟，沉主里、迟主寒，为阳气内衰、阴寒内盛之象。背寒色夺，背为阳位，阳气不能温煦则背寒；色夺乃气血不能上荣。久有劳倦伤阳，新年暴冷外袭，内外寒合，故脉沉迟。此段示劳倦阳虚复感暴冷之病机，非单纯外感。", ["沉", "迟"]], "8571": ["病机", "春交旬日形症小愈，但右脉仍弦，右关候脾胃，弦为肝木偏旺、木乘土位之象。舌白味变酸甜，味觉异常示胃气不和、脾津不布。喻嘉言谓当以气雄刚药「能变胃不为胃变」，即借药力振胃气以制肝木。脉弦未去，说明肝胃不和、木郁乘土之病机仍在。", ["弦"]], "8572": ["病机", "鼻痒心辣闪烁，继之大便下血，形瘦脉小数。小数主阴虚内热，热迫血溢则下血；鼻痒心辣闪烁为虚火上扰、心神不宁之象。形瘦示阴血耗伤已久，病延数年，脉小数正合阴虚火动、血热妄行之病机，非实热暴迫之证。", ["小", "数"]], "8573": ["病机", "疟变为痢，邪陷入里，阴液欲竭。鼻煤龈血、舌张干涸，示阴津将尽；肌如甲错、脉细尺不附骨，细为阴血亏虚，尺不附骨乃肾阴耗竭、根本失守。入夜烦躁不寐，邪热内迫阴分。脉细尺不附骨正说明阴虚伏邪、油干焰灭之危，故议护阴清阴中邪热。", ["细"]], "8574": ["病机", "下血后大便燥闭，继而自利白滑胶黏、日数行不禁，年五旬形衰脉沉。沉主里，形衰脉沉示阳气内弱、脾运失职。白滑胶黏乃久伏水谷之湿，湿浊内蕴、府气不通。府病宜通，故用温下法。脉沉说明湿伏于里、阳气不足之病机，非单纯燥结。", ["沉"]], "8575": ["病机", "脉弱形瘦，食不适必泄泻。弱为阳气虚衰之象，形瘦示脾气不运、肌肉失养。食不适即食入不化，泄泻乃脾阳不足、下焦先冷、腐熟无权所致。原文谓「阳气已伤未寒」，说明阳伤尚在初期，脉弱正合脾肾阳虚、运化失司之病机。", ["弱"]], "8576": ["病机", "脉微为阳气衰微之象，晨泄属脾肾阳虚，命火不能温煦中焦。原文谓\"初冬未及藏阳\"，说明阳气当藏而未藏，脾肾失于温养，故纳谷减少。脉微主虚主寒，脾肾两脏阳气不足，运化无力，当以中焦为主兼理下焦，温补脾肾为治。", ["微"]], "8577": ["病机", "脉左坚下垂，左脉候肝肾，坚为阴亏内热之象。平素阴亏，热邪注入下焦而为下利，粪结便出痛坠，是阴液不足、热结肠道所致。坚脉不主实而主阴虚内热，故不以脾胃燥药，恐燥更伤阴。此脉说明病本在阴亏热注，非脾虚湿盛。", ["坚"]], "8578": ["病机", "脉来数小，数为有热，小为气血不足。久痢久泻肛坠频频，是肾伤不固、气陷下坠之候。数小之脉说明肾阴亏虚而虚热内生，非脾胃实热。医作脾胃病治故不效，因病本在肾，当从肾治，脉数小正是肾伤虚热之征。", ["数", "小"]], "8579": ["病机", "脉沉迟为阳虚内寒之象，沉主里、迟主寒。下利血水、神呆不欲食、四肢冷、前已完谷，皆阳气衰微、脾肾虚寒、不能腐熟水谷所致。脉沉迟与诸症相应，说明阴寒内盛、阳气不振，故与温理其阳，温补阳气以散寒。", ["沉", "迟"]], "8580": ["病机", "脉两关弦虚，关候脾胃，弦为肝旺，虚为不足。先血后粪、两月未已，是脾虚不能统血、肝木乘脾之候。原文谓\"遇劳而发属虚\"，说明病根在虚，劳则气耗血失统摄。弦虚并见，主肝脾不和、中气虚弱，故仿仲景黄土汤温脾摄血。", ["弦", "虚"]], "8581": ["病机", "脉弦无胃，弦为肝脉，无胃即失柔和之胃气，是真脏脉见。面青呻吟、汗出目瞑，面青属肝，汗出目瞑为肝阳外泄、阴不敛阳之危候。弦无胃说明肝阳外越、胃气已败，故宜与肾同治，滋水涵木以敛浮阳，非单纯治肝。", ["弦"]], "8582": ["病机", "老年脉沉，沉主里主湿。目黄、不饥不食、腹痛自利后坠溺涩，是长夏湿邪伤于太阴脾位，阳不运行，湿热凝注所致。脉沉说明湿邪内阻、阳气不运，故法当温脾导湿，佐辛香宣浊，开太阳温太阴，使湿化气行。", ["沉"]], "8583": ["病机", "脉沉迟为里寒湿阻之象，沉主里、迟主寒。食入腹胀便溏、小便不爽，是平昔饮酒中伤，留湿阻气，脾运失职所致。脉沉迟说明湿浊内停、阳气不运，故用香砂平胃散燥湿运脾、行气化浊，使湿去气畅则胀溏自愈。", ["沉", "迟"]], "8584": ["病机", "原文未出脉名，以“不饥少寐，二便不爽，经脉中牵掣”述症。长夏水土之湿与水谷之湿互蒸，气阻三焦不通，故中焦不运则不饥少寐，下焦气化不利则二便不爽，湿流经脉则牵掣。此非风寒从表，乃湿浊内蒸、三焦气机壅滞之病机，久延恐成格胀。", []], "8585": ["病机", "脉小为阳气不足之象。夏秋内伏暑湿本属阴邪，久疮耗伤中阳，渐致食入痞满、形寒，脉小正应阳微。原文明言“当温中醒阳，莫以清凉治疮”，可知此脉小主中阳不振、阴湿内伏，非实热壅盛，故治从温中。", ["小"]], "8586": ["病机", "脉沉主里、主气机郁滞。汤饮食物呕吐吞酸、胸高腹胀、二便不爽，皆浊气上阻、中焦升降失司所致。沉脉说明病在里而不在表，浊阴内壅，气不通降，故以柔温宣通为治，使郁滞得开、浊气下行。", ["沉"]], "8587": ["预后", "脉微小而迟，为阳气衰微之征。久食物不进则化源告竭，形色枯悴畏寒更证阳衰。原文断为“此为无阳，延久成胀”，是据脉微迟与畏寒枯悴并见，判断阳气将败、久延必成胀病，属预后不良之论。", ["微", "小", "迟"]], "8588": ["病机", "左脉独弦，弦为肝木偏旺之象。脐突筋青乃肝胀显然之征，脾愈虚则肝愈实，木旺乘土。原文谓“不合实脾治肝之法，先泄肝”，说明此脉弦主肝实脾虚、木亢侮土之病机，故先泄肝以平木亢。", ["弦"]], "8589": ["病机", "腹右有形为聚，属六腑病。脉大主邪气盛实，食入即胀乃腑气壅滞、传化不行。原文“治在六腑”，说明脉大与有形之聚相应，主腑实气滞、食积内壅之病机，故从六腑通降论治。", ["大"]], "8590": ["病机", "脉微迟为阳气衰微、阴寒内盛之象。左胁宿痞渐至腹胀、便溺少，是浊阴上攻、气化不行。原文明言“明系浊阴上攻，当与通阳”，可知微迟之脉主阳微阴浊内壅，故治以通阳，使阴浊得化、气机得通。", ["微", "迟"]], "8591": ["病机", "原文未出脉名，以饮酒聚湿、湿生痰生热立论。维脉为湿热所阻则痹痛，久酿痰饮深处络中，阳气日衰，痰湿属阴浊乘夜冲举妨卧。总以脾阳不运化湿变痰、肾阳不藏水液上泛为病机，故先议越婢法宣上郁热以通痰饮。", []], "8592": ["病机", "脉沉主里，背寒为阳气不布，咳嗽吐稀涎、夜不得卧，是寒饮内伏、上逆犯肺之象。饮为阴邪，遇冷则阳气愈困，故遇冷即发。脉沉与伏饮内停、阳不温煦相应，病机在阳虚饮伏，非表邪所致。", ["沉"]], "8593": ["病机", "脉濡主湿、主虚，此段言中宫阳不主运，湿浊聚痰。脾阳不运则湿停成痰，故不饥不渴不食。濡脉与湿浊内困、阳气不充相应，病机为中阳不振、湿痰内聚，非单纯食滞。", ["濡"]], "8594": ["病机", "原文未出脉名，以幼年哮喘论饮邪聚络。寒暄失时、食味不调致饮伏络脉，内外感触则喘逆气填、夜坐不得卧，浊沫稀涎变浓痰则病势自缓。饮为阴邪，秋深冬月外凉相召而窃发，发时背冷气寒，病机在伏饮乘寒而动。", []], "8595": ["病机", "脉弦主饮、主痛，脊骨中冷、深夜痰升欲坐，是少阴寒饮上泛。寒饮循经上逆，阳气不温脊背，故冷而痰升。弦脉与寒饮内动相应，议通太阳者，以太阳主表、通阳化饮，病机在少阴寒饮上泛。", ["弦"]], "8596": ["病机", "左沉右弦虚，过劳阳伤，清气不主流行。沉为阳陷，弦虚为劳伤中气、清阳不升。温中丸不应，知非有形之滞，乃阳气微弱不能流通。脉与过劳伤阳、清浊失运相应，故以辛温微通其阳，病机在阳伤气滞。", ["沉", "弦", "虚"]], "8597": ["病机", "长斋数年，脾胃日弱，食进脘中少运，小溲入暮渐多，色萎黄，脉弦虚。弦为土虚木乘，虚为中气不足，故食少运迟、暮溲多而色萎。脉症合参，皆中气不足、脾失健运之候，病机在脾胃虚弱。", ["弦", "虚"]], "8598": ["病机", "左小涩右弦，阳微肢冷，脘痞不易运化，大便初结后溏。小涩为阳微血少，弦为脾阳受困、气机不畅。六旬有六，太阴脾阳不运，故便难而溏。脉与阳微肢冷、脘痞相应，病机在太阴脾阳受困，当温中醒阳。", ["小", "涩", "弦"]], "8599": ["病机", "原文未出脉名，言积劳伤阳、肝风内动，症如类中，温肾补脾、运痰熄风得效。今诊脉不附骨而洞泄，形瘦未复，频年久泻，是泻久伤肾、下焦不固。胃气弱、阳微呕酸，病机在脾肾阳衰、固摄失职，故以固摄下焦为法。", []], "8600": ["病机", "脉左涩伏，涩主血滞，伏主气郁，右弦为肝气横逆。肝厥心痛由惊起怫郁，气机逆乱，血行不畅，故脉涩伏；肝气犯胃，胃失和降，则呕吐脘痛引胁；痛甚气逆，阳气不达四末，故四肢冷麻。此脉象揭示肝郁气滞、血瘀络阻之病机。", ["涩", "伏", "弦"]], "8601": ["病机", "脉伏者起，似病减而实未减。痛胀脘痞、口涌涎沫、舌白鼻煤、面赤头汗，显系肝厥犯胃，左升之气逆乱攻络。脉伏为气机郁闭，辛香开气不应，便秘溺少，说明气滞血瘀、津液不布。此脉伏非虚，乃邪闭气机之象，故用金铃子散佐润液两通气血。", ["伏"]], "8602": ["病机", "脉沉小左弦，沉小为里虚，左弦主肝。冲气至咽欲厥，下坠入前阴，溲溺不能自利，此厥阴冲脉之病。冲脉隶于肝肾，脉弦为冲气上逆，沉小示下焦虚寒，浊阴不化，故当以秽药驱浊，通阳泄浊以平冲逆。", ["沉", "小", "弦"]], "8603": ["治法", "原文未识脉名，以甘药呕缓，因治嗽苦辛寒伤胃，冲脉亦阳明胃经管辖。此补胃以宁冲阳，实具至理。说明苦寒伤胃致冲脉上逆而呕，甘药补胃则冲阳自宁，体现冲脉隶于阳明、治胃即治冲之治法。", []], "8604": ["病机", "原文未识脉名，以虚里穴为阳明胃，阳明气血皆多，络脉窒塞为痛，映及背部。脉络不和，必宣通望其痛息。萸地之凝、耆术之守皆非络药，说明络脉窒塞、气血不通之病机，治当宣通络脉，非滋补凝守所宜。", []], "8605": ["病机", "脉来左部坚搏，坚主实、主郁。先有血淋，淋止胁痛，是少阳郁热乘络所致。左关候肝胆，坚搏为郁热内结、络脉不和，故胁痛；忌食酒肉厚味，恐助湿热。此脉象揭示少阳郁热、络脉瘀阻之病机。", ["坚"]], "8606": ["病机", "脉沉小，沉主里、小主虚。痛起胸脘，串及腰背，五年宿恙，寝食不改，此病在脉腠之间，痹阻不伤脏腑。脉沉小示气血痹阻于脉络肌腠，未及脏腑，故议流通周行气血，勿得峻剂，以免伤正。", ["沉", "小"]], "8607": ["病机", "中年以后阳气已微，午时嗳气、食纳上泛，皆胃弱气逆。面明脉弦，弦主饮、主痛，必伏痰饮。仲景胃虚客气上逆例，说明胃虚气逆、痰饮内伏，脉弦为饮邪内动之象，治当温胃化饮降逆。", ["弦"]], "8608": ["病机", "原文未出脉名，仅言「脉症乃气结在上」。气结于上则津液不布，蒸变浊痰，由无形渐成有形，是气滞生痰之病机。徐之才「轻可去实」正对无形气结，故非胶固阴药所宜，提示当以轻宣流动之品开其气结，而非滋腻凝滞。", []], "8609": ["病机", "脉小涩为气血不畅、湿郁内凝之象。面赤目黄、喉痛而咽物不碍、溺后淋浊，皆水谷之气凝聚成湿，气不升降、三焦不利所致。小涩示郁滞非虚，故主清肃上焦，使气化湿行，而非温补。", ["小", "涩"]], "8610": ["病机", "原文未出脉名。昔年强旺而热病后精采不复，鼻窍不通、左胁有声攻触痛呕、遇劳即发，是络中瘀血凝聚之征；食减少饥、病中衄血，更证大络聚血。劳则气动血瘀，故遇劳即发，属瘀留络脉之病机。", []], "8611": ["其他", "原文未出脉名。跌扑致经脉气血壅痹，胁背高凸，是外伤后瘀血壅聚、气血不通之形症。既言「非汤药可效」，则非内伤脏腑之病，当从外治或导引按跷求之，故归其他。", []], "8612": ["病机", "脉虚浮而沉取直上下行，虚为胃虚，浮而直上示冲气上逆。胃纳素减，气从下焦直冲至咽、手足厥逆发呃，正是相火挟冲脉上逆清道。冲脉并少阴夹巨阙而上，故治以滋水折火、崇土制龙雷，非泛治呃逆。", ["虚", "浮"]], "8613": ["病机", "右脉如控弦，弦为肝木劲急之象，见于右关则木乘土位。控弦者紧劲有力，示肝气横逆、胃土受克，与呕吐䐜胀、不纳物相应，为肝木犯胃、气逆不降之病机。", ["弦"]], "8614": ["病机", "右弦左涩，弦为肝旺，涩为血滞。因嗔怒致呕吐䐜胀不纳，是肝木犯胃、涌逆不已；浊阻上下不通，老年复虑关格。弦涩并见，示气逆而血滞，木克土之病机，预后当防关格。", ["弦", "涩"]], "8615": ["预后", "原文未出脉名，仅言「形脉症象，不受温热」。嗜酒积热、阴液下枯、阳津变痰，鼻塞多呛、减食、旬日更衣粪如羊屎，是老人关格之候。既云治之极难、酒客不喜黏腻甘柔，又不受温热，故预后不良，议琼玉减蜜方法。", []], "8616": ["预后", "脉小结涩，小为阳衰，结为气滞，涩为血少，反映阳气不旋、关格之证。上不纳食、下不更衣，乃阳气闭阻，三焦不通。脉象示正气虚衰、气血瘀滞，故曰“伤于无形，最为难治”，预后不良。", ["小", "结", "涩"]], "8617": ["病机", "脉弦为痰，弦主饮邪痰浊。原文谓“饮留气凝”，阳气结痹，浊阴壅遏，致反胃涌吐、完谷不化。面赤属饮，脉弦为痰，痰饮内阻，胃阳衰惫，气机不通，故痛。治当通阳镇逆，非攻下所宜。", ["弦"]], "8618": ["病机", "酒热伤胃，谷食入脘即噎，涌出涎沫，乃阳明脉不用事，胃失和降，筋脉牵绊。虽未识脉名，但病机为酒热灼胃、气机上逆，故用半夏泻心汤以和胃降逆、开结除痞。", []], "8619": ["病机", "右脉弦长而数，左脉带涩，弦主气郁，长主有余，数主热，涩主血滞。起自恚怒，肝气犯肺，金不及木，反侮肺金，气凝痰阻，阻在胃之上脘。眼胞证之，拟泄金平木，以调气机。", ["弦", "长", "数", "涩"]], "8620": ["病机", "食不得化，是无阳也，脉络映痛，乃阳气不足，阴寒内盛，气血凝滞。辛香芳温可效，取其温阳散寒、行气通络之功。虽未识脉名，病机为阳衰不化，治当温通。", []], "8621": ["病机", "吸入寒气，伤及络脉，胸痛饮热酒宣通小愈，然中年屡发，阳气受伤，必有瘀聚，漫延反胃噎膈。病机为寒伤络脉、阳气受损、瘀血内聚，治宜薄味节劳，以护阳气。", []], "8622": ["预后", "脉微而迟，微为阳衰，迟为寒凝，乃胃之冲和之气衰败，曲运神机所致。颗粒不食、呃逆不止，仓禀顿惫，胃气将绝，预后不良。脉象示阳气虚微，胃气衰败。", ["微", "迟"]], "8623": ["病机", "脉右弦，面色赤亮，纳谷咽干脘阻碍不下。五十四岁清阳日薄，转旋日钝，痰阻气结，脘窄不能宣通。弦主痰饮气滞，大便仍利，病在脘膈之上，治当宣通脘膈，化痰行气。", ["弦"]], "8624": ["病机", "脉沉主里，腹满为气机壅滞。原文言暑湿疟后中气不复，骤食大荤，致气结成胀。脉沉与腹满、二便不通相合，说明中焦气滞、升降失司，属里实气结之病机，非外感表证。", ["沉"]], "8625": ["病机", "脉左数搏，左脉候先天真阴，数搏为阴亏内热之象。原文谓先天真阴难充则生内热，疟热再伤其阴，故脉数搏。此脉主阴亏内热，与滋养甘药填阴之法相应，属虚热病机。", ["数", "搏"]], "8626": ["病机", "原文以“脉气怯神弱”描述色脉，未出具体脉名。气怯神弱示正气虚馁，疟止反复因正气不复。因病致虚，夏秋宜调中益气，说明脉气怯弱主中气亏虚、神气不足之病机。", []], "8627": ["治法", "原文仅“复脉去参姜桂”六字，未及脉象。复脉汤去参、姜、桂，属治法调整，意在减温补之力。此段主旨为治法，非论脉，故脉象要素从缺。", []], "8628": ["病机", "脉来小弱，小为阳气不足，弱为虚损。原文见寒自背起、不烦渴、麻木，近受温邪如疟，实为阳气久虚。脉小弱与阳气虚衰相应，主本病虚寒，当从本病调折，非新邪为主。", ["小", "弱"]], "8629": ["病机", "脉弱神倦，形丰而脉弱，外似有余、里真不足。原文言邪伏化火，疟久成三疟，正气日疲。脉弱主中气亏虚，与神倦、胸闷不知饥相应，说明伏邪伤正、里虚之病机。", ["弱"]], "8630": ["病机", "色黄脉小，小为营卫不足。原文谓年十三未出，营卫疏，客邪留著。脉小与上部先寒相应，主营卫空虚、客邪留恋之病机，属正虚邪留之候。", ["小"]], "8631": ["病机", "脉弦数可征，弦主厥阴、主痛，数主热。原文烦躁吐蛔，为厥阴疟重症。脉弦数反映肝经热盛、蛔扰气逆之病机，故拟苦辛酸法以泄热安蛔。", ["弦", "数"]], "8632": ["病机", "脉缓软涩，缓为胃气不足，软主阳气式微，涩则血少气滞。原文见胃脘不爽欲嗳、夜来腹胀、吐痰酸水、口鼻吸冷，显系中阳受损，运化失司，痰饮内停，胃气上逆。脉证合参，病机为寒饮伤中，脾阳不振，故用冷香饮子温中，暂缓参术之补。", ["缓", "软", "涩"]], "8633": ["病机", "脉沉缓，沉主里，缓主湿。原文目黄舌白、呕恶脘腹闷胀，乃冷暖不和，水谷之气酿湿，太阴脾阳不运，气机受阻。湿浊内蕴则目黄，胃气上逆则呕恶，脾运失职则胀闷。脉证相应，法当辛香温脾、宣气逐湿，用冷香饮子。", ["沉", "缓"]], "8634": ["病机", "原文未出脉名，然舌白黄不饥、筋骨甚软，乃暑湿内蒸，脾胃受伤。阳明胃脉不司分布流行，则纳运失职，湿困筋脉则软。此湿浊内蕴、脾胃气机壅滞之病机，若不早治，湿郁化热，必延为疟痢。", []], "8635": ["病机", "脉小数为阴伤。咳嗽二年、形瘦谷减，阴液亏耗；冬季喉垂渐痛，水亏阳不藏，春月阳结于上为喉痹。小脉主阴血不足，数脉主虚热内扰。近日寒热风温客气，阴伤更甚，故忌辛散劫阴。脉证合参，病机为阴亏阳结、虚热上炎。", ["小", "数"]], "8636": ["病机", "脉数右实左弦，数主热，右实主阳明热结，左弦主少阳枢机不利。服养阴药得效未愈，嘈杂恍惚、胸上动气，乃热郁少阳、胆胃不和，气机上逆。苦寒清热，用小柴胡汤治阳维之会，以和解枢机、清泄郁热。脉证相应，病机为少阳郁热、胆胃气逆。", ["数", "实", "弦"]], "8637": ["误治", "原文未出脉名，然温邪从口鼻直走膜原，本非太阳客邪，医投羌防辛温表汗，已为逆治；又妄下希图泄热，强汗劫精伤阳，妄下劫液亡阴。顷诊脉两手如搐而战，舌干燥无苔，嘴前干板目欲瞑口欲开，周身斑，皆阴阳重劫之危候。此段主旨为误治致变。", []], "8638": ["病机", "脉数，上出鱼际一寸，数为热盛，脉出鱼际为溢脉，主阳热上壅。心中热与背相控，乃热邪内郁，气机逆上，心胸与背相应。脉证合参，病机为阳热内盛、气火上逆，热扰心胸。", ["数"]], "8639": ["预后", "脉数上出鱼际一寸，是谓溢脉，阴气不能上承于阳也。寒热汗出身半以上，阳失阴守，阴阳不相维系。溢脉本为阴不敛阳之象，今更见半身汗出，乃阴阳离决之兆，故曰非寿征也。议摄阴救阳，以图挽回。此段主旨为预后判断。", ["数"]], "8640": ["病机", "原文未载脉象，以“牙齿常紫，膝盖酸痛，上年秋季为甚”点明湿邪阻于经络，阳明之气不司束筋利机。湿性黏滞，阻遏脉络，气血不得宣通，故见酸痛；秋令湿盛，故为甚。病机在湿壅经络、阳明失职，治以宣通脉络，使气血和平。", []], "8641": ["病机", "原文未出脉，述新沐后头痛鼻塞似风温，次日寒战大热、胁肋痛不可转侧、自利稀水，断为“湿聚于经脉，病在气分”。湿阻经脉，气分热炽，故寒战大热、胁痛；湿注大肠则自利。目黄上视、手肢发痉、舌白齿板燥、胸中隐痛，皆邪深痉变凶之候。", []], "8642": ["病机", "原文“脉郁伏湿邪已解”非具体脉名，故脉象要素从缺。用木防己汤后痉厥已缓，经脉郁伏之湿邪已解，然胃汁大伤，痰嗽气闪。病机由湿郁转为胃阴耗伤、痰气上逆，故与甘药不伤胃气，以养胃化痰为治。", []], "8643": ["病机", "脉小涩，小主气虚，涩主湿滞血少。原文谓天运寒水、地气湿土，秽浊从口鼻直走胃络募原，初病头胀痞闷呕恶、舌白，病在气分。暑必挟湿，湿邪无形，医却以有形之药消之清之不应。脉小涩、舌干口渴、胸次软而涩、呕逆，示湿困脾阳、气机不运，故当温脾阳以运湿，佐辛香。", ["小", "涩"]], "8644": ["病机", "脉大主邪气盛。舌赤头痛、恶心脉大，原文断为“温邪入募原也”。温邪从口鼻入，踞于募原，邪正交争于气分，故脉大；热邪上扰则舌赤头痛，犯胃则恶心。脉大与舌赤头痛恶心并见，说明温邪内蕴募原、热势鸱张之病机。", ["大"]], "8645": ["病机", "脉右大，右主气分，大主邪盛。舌黄不渴、呕吐黏痰、神躁语言不清、身热不除，原文谓“劳倦内伤，更感温邪”。劳倦伤中，温邪乘虚内陷，痰热蒙蔽心包，故神躁言不清；热郁气分则身热、舌黄。右脉大示邪在气分而正伤，须防热盛动风变痉。", ["大"]], "8646": ["病机", "脉软弱，软主湿困，弱主气阴不足。舌干黄、脘中不爽，原文谓“热伤津液，阴不上承，清热不应”。热邪耗伤胃津，阴液不能上承，故舌干黄而口渴；胃气不舒则脘中不爽。脉软弱与舌干黄并见，示热伤津液而气阴两伤，故以甘寒生津为治。", ["软", "弱"]], "8647": ["病机", "脉弱无力，主阳气虚衰。心中洞、入夜神昏谵语、面目皆红、烦渴微饮，原文谓“劳倦内伤，频与苦辛消导滋阴，阳愈伤则浮越，有虚脱之虑”。误治伤阳，虚阳上浮，故面红烦渴而脉弱无力；神昏谵语乃阳气浮越、心神不守。脉弱无力正是虚脱先兆，故议仲景救逆法。", ["弱"]], "8648": ["病机", "脉弦长为木火内郁，入尺而数则阴分有热，结合舌上沾苔、时或发热、大便或溏，显系素禀阴虚之体复受暑湿，暑湿郁于气分则发热便溏，阴虚内热则尺数，弦长乃肝木乘脾、湿郁气滞之象，非单纯外感暑湿可比。", ["弦", "长", "数"]], "8649": ["病机", "下焦诸脉既空，是肾精亏泄、阴不恋阳，故阳浮上灼而为痰嗽。原文明言「阴泄为遗」「治肺无益，必填实下元可愈」，指出病本在精亏阳浮，非肺脏本病；脉空正是下元不固、精血内夺之征，与遗精、痰嗽相应。", ["空"]], "8650": ["病机", "色夺脉虚，为精血内损、气失所养之象。原文述左胁中动气因遗精惊恐而得，乃下损精血，气因精伤，故脉虚不任按。夏秋烦倦非客邪所致，当补精以化气，脉虚正提示下元亏虚、气不归精之病机。", ["虚"]], "8651": ["病机", "脉缓小弱而四肢不温、膝酸足软、天暖犹欲火烘，是八脉不摄、冲任督脉失于温养，阳衰不能达于四末。尿血血淋虽多属小肠膀胱之热，此则脉不数而缓小弱，显系虚寒不摄，故以壮冲任督脉佐凉肝为复方之治。", ["缓", "小", "弱"]], "8652": ["病机", "体伟肌丰而脉得缓小，是形盛气弱、里实不足之征。阳气发泄行似有余，水谷之气不得畅遂，酿湿下注为浊，已三四年气坠不效。脉缓小正合脾阳不运、湿浊下渗之机，故直升阳为法，非少壮阴火自灼可比。", ["缓", "小"]], "8653": ["病机", "右数左小数入尺，淋浊不止继患目疾，是精血暗损、肝肾之症。操持用心则五志之火自亢，情志突起非六淫客邪，故脉数而小，为虚火内扰、精血亏耗之象，不可辛散清火，当从情志肝肾论治。", ["数", "小"]], "8654": ["病机", "脉左弱下虚入尺，有梦久遗、足软如痿、行动气促似喘，是督任交亏、冲阳升举之候。左脉主肾，弱而入尺为精亏不固，精窍不填则遗泄不止，下虚不能纳气则喘促足痿，故务以填塞精窍为急，不及傍治。", ["弱"]], "8655": ["病机", "原文未识脉名，然述饮食不司运纳、夏季湿郁伤太阴脾、湿甚生热窒于阳明胃脉，四末微肿黄未尽除，阳明之脉尚少流利机关。此以气分壅滞、湿热郁阻阳明为病机，故治以宣通气分，使气通湿走热清，忌厚味腥浊。", []], "8656": ["病机", "原文未出脉名，以「脾胃皆弱」「湿郁阻遏经脉流行之气」立论。久痢休息致脾胃先虚，夏令湿胜外袭，湿性黏滞阻遏经脉气机，故臂痛右痪、肢节牵强。治以温脾辛香，取「里中之表」之意，使脾运复而湿从表解；痛缓臂伸后减姜黄蒺藜走经络之品，防辛散耗气，正合虚中夹湿之病机。", []], "8657": ["病机", "脉缓软为湿邪偏盛、正气不充之象，缓主湿、软主虚。四月中时令湿邪入于经络，气血痹阻，故四肢牵强、环跳髀尻牵引。壮年见此，非虚损本证，乃湿邪外袭成痿痹。脉软不弦不紧，说明湿阻而未化热、未成实，故以宣通经络、化湿蠲痹为治，与痿痹之症相应。", ["缓", "软"]], "8658": ["兼症", "脉小足冷、形脉皆虚，是阳气不足、护卫无力之征。四肢发疹、骨骱肿痛，为风湿已入经络成痹。脉小示气血不能充脉，虚示正不胜邪，故虽痹证属实，却不可纯攻，当「护卫以攻邪」，扶正与祛邪并行。足冷尤见下焦阳弱，风湿乘虚内侵，与形虚脉虚之症相应。", ["小", "虚"]], "8659": ["病机", "原文未出脉名，以「风寒久必入脉络」「外卫阳失护」立论。风寒久羁，由经入络，卫阳失于外护，故现右肢麻木；鼻渊脑寒虽属上窍，然络虚不宜发散，恐耗卫阳。议和血脉以逐留邪，取通络和营之法，使久入之邪从血络渐解，与「不可发散」之戒相合，属络病正虚邪留之机。", []], "8660": ["病机", "脉形已小，为气血不足、阳明虚馁之象。痛移左右，由阳明虚而厥阴来侮，木乘土位，故痛无定处；重按痛缓，说明中虚为主，非实邪结聚。脉小与阳明虚相应，治当扶中土以御厥阴，使肝木不横，则痛自减，属虚实夹杂、土虚木侮之病机。", ["小"]], "8661": ["病机", "脉沉迟为阳微阴盛之征，沉主里、迟主寒。疝冲瘕聚、收引拘束痛甚，是阴浊痹阻、阳气不能温通所致。阳微则阴浊凝聚，冲气上逆，故痛甚而拘急。议以刚药者，取辛温刚燥之品破阴浊、复阳气，使沉迟之脉得振，阴凝得散，与疝瘕收引之症相应。", ["沉", "迟"]], "8662": ["病机", "脉沉伏为邪气深结、阳气郁闭之象，沉主里、伏主闭。逆痛不止，是厥阴挟冲气为患，冲气上逆而阳不能伸，故脉伏而痛剧。沉伏非虚，乃阴寒浊气痹阻之实，治当温通厥阴、降冲泄浊，使伏脉得起、逆痛可止，与「厥阴挟冲气」之病机相应。", ["沉", "伏"]], "8663": ["病机", "色悴脉芤，芤为中空之脉，主精血亏耗。下焦疝瘕，是冲任为病，乃肝肾精血不足致损。精血虚则冲任失养，气结而成瘕；色悴与芤脉相应，皆示根本已亏。治当补益肝肾精血、调养冲任，不可峻攻瘕聚，属虚中夹结之病机。", ["芤"]], "8664": ["病机", "脉微涩为阳气衰少、血行不畅，左弦主少腹疝瘕。跗廉麻冷、走动无力、畏风怕寒，皆阳虚失于温煦；少腹微满、睪丸日肿，为阳虚寒凝、疝瘕内结。神呆色衰示阳气大伤，故断为阳虚疝瘕难愈之疾。", ["微", "涩", "弦"]], "8665": ["病机", "原文未出脉象，以维脉立论。阳维司外护而苦寒热，阴维主内营而苦心痛，二气日衰则营护不周，劳倦寒暄乘虚为害。指出此属八脉奇经之病，温补不能入脉，若以湿淫客气搜逐反害大矣，明奇经病机与治法禁忌。", []], "8666": ["病机", "带脉横围于腰，维脉挟内外踝而行，劳伤受寒则脉络欹斜、不司拥护，故为瘕疝、麻木不仁。久而痿痹废弃淹淹，说明奇经失护、气血痹阻之病机由浅入深，非小病也。", []], "8667": ["病机", "产后十年晨泄形寒汗出，为下元阴伤及阳、奇脉不固。晨泄属肾阳虚衰，形寒汗出乃阳失卫外，产后久病耗损下元，阴损及阳，奇经失于固摄，故遵古人温固奇脉之法。", []], "8668": ["病机", "脉不和主气血郁痹、络脉不畅。少腹微膨、经来后期多痛、秋冬膝跗冰冷，为冲任虚寒、气血郁滞；冲气攻触左胁、脘胀痛不能食，乃肝胃络脉不和。虽无性命之危，然恐累及孕育。", ["不和"]], "8669": ["病机", "天癸当绝而屡次崩漏，乃冲任脉衰、固摄无权。久漏成带，延绵不愈，说明冲任虚损、带脉失约，病属延绵之疾，治当固其下元以复冲任统摄之职。", []], "8670": ["病机", "胎前疟热伤阴，产后下焦之阴更损，冲任不下固，故气冲咳逆呕、午后潮热、子后汗泄，皆阴虚损及阳位。夏令大热发泄，络空胁痛失血，便溏纳谷，蓐劳下损渐干中上，故延绵不愈。", []], "8671": ["病机", "少年怀妊恶阻误药殒胎，十余年不孕育，经来周身经络暨痛、少腹瘕触寒热皆至，乃八脉交损。冲任督带诸脉俱伤，气血交亏，故八脉之治非转展不效，示奇经久损难复之病机。", []], "8672": ["病机", "原文未出脉名，以“质偏于热，阴液易亏”立论。阴血根于阳，阳浮为热则阴弱不能恋阳，冲脉失蓄，故“从不孕育”；脊背常痛属督任失养。病机为阳浮阴亏、奇经空虚，主不孕与脊痛，治从督任二脉。", []], "8673": ["病机", "原文未出脉名，述形冷惊悸、经淋漏注、怔悸若悬。肝主惊、肾主恐，产后先虚在下，奇经不为固束，故漏注不止、心神不宁。病机为下元虚寒、八脉失固，主经漏与惊悸，治以温补固摄佐通药。", []], "8674": ["病机", "原文未出脉名，述产后五日恶露渐少，卒然右胁下痛引少腹、手不可按、身不能转侧。因卧右太早，败血横行入络，瘀腐浊气上冒胞络，故痛甚神迷昏乱。病机为瘀阻脉络、浊气上逆，属产后重病，议宣通脉络之壅。", []], "8675": ["病机", "原文未出脉名，以蓄血如狂喜忘为喻。络中瘀聚还注冲脉，故右胠痛缓而少腹痛胀，大便黏腻白滑为瘀浊所化。病机为瘀浊注冲、络脉壅滞，主少腹痛胀与便黏，需前通溺浊，痃痞症瘕可缓商调治。", []], "8676": ["治法", "原文未出脉名，述络通痛减、病已挽回，但少腹余氛、瘀留冲脉。病机为瘀浊未尽、冲脉余滞，故不以宿佝偻为重，只宜溺通瘀下。主旨在治法，用交加虎杖合方加炒灵脂，通瘀下行以竟全功。", []], "8677": ["病机", "原文出“脉来左数”，左脉候肝与冲任。胎前咳嗽、产后失血，咳甚呕吐，是下虚气逆、冲任内损，虚阳上浮故左数。屡投肺药不效，延为蓐劳。病机为下虚气逆、冲任内损，主咳嗽失血呕吐，断乳调理为上。", ["数"]], "8678": ["病机", "原文出“脉空虚”，奇脉空虚则八脉失养，腹中瘕痛由虚而气结。脉空虚正示下元不足、奇经不充，故温补佐宣通，使药力入八脉。病机为奇经空虚兼气滞，主腹中瘕痛，治宜温补宣通并行。", ["虚", "空"]], "8679": ["病机", "原文出“脉空”，三旬崩漏而形体反充壮，是发泄外盛内虚。背部肌腠热烘、肢体动摇，阴液内乏、阳气旋鼓，风木不宁则阳明脉空，暴中暴厥由此而起。病机为阴亏阳浮、阳明脉空，主崩漏与掉眩，引《病能篇》诸风掉眩属肝木为证。", ["空"]], "8680": ["病机", "原文未出脉名，以「气血不和，脉络不通」立论。气血失于流通，脉络壅阻，故成胀满；经水阻于左胁、宿瘕久聚，是病根深伏未去。胀减而经水仍阻，说明通络行气仅去其标，宿瘕未消则气血难和，病机重点在瘀阻脉络、积久成胀。", []], "8681": ["病机", "原文未出脉名，述腰胁刺痛、虚里尤甚、头晕跗肿、形寒临经诸症。病久八脉损伤，气血失养，故见虚里刺痛与形寒；清阳不升则头晕，水湿下注则跗肿。指出不可见病治病，当调经和养气血，病机属八脉虚损、气血两伤。", []], "8682": ["病机", "原文未出脉名，以「思虑忧愁谓之郁」为纲。气血暗伤则肌肉日瘦、不食不寐，郁结酿痰可成痫，枯槁则成损。又因失血后倏冷忽热、脘闷胸痛、腰脊酸软如折，是营卫偏欹、八脉失职。主张宣畅脉络，勿用滋滞补涩，病机在郁结伤气血、脉络不畅。", []], "8683": ["病机", "原文未出脉名，述阳浮汗泄、如饥忽胀、眩晕麻痹、产前心痛子悬。病起产后，由肝肾内虚、真气不收纳，内风掀旋，传于阳明脉络而筋骨不司步履。阳浮于上、汗泄于外，是虚阳不藏；沉锢之疾说明病机深在肝肾，非表浅之证。", []], "8684": ["病机", "原文未出脉名，述连次小产初伤冲任，久则督带跷维皆伤。八脉不匀约束，阴不下固则淋带晨泄，阳乃上浮则上热下冷浮肿，脊酸腰垂、耳鸣不寐皆久损不复之象。病机为八脉损伤、阴阳失于固摄，故须从阴引阳、通固兼用。", []], "8685": ["预后", "脉得细促，细为阴血不足，促为阳热内迫而数中一止，故见热升冲咽、咳嗽不止；两足冷如冰至骨，是下元虚寒、虚阳上浮。先天最弱、笄年不肯充长，若经水忽闭，则阴血无源，劳损难治，脉细促正示根本已虚而热扰不息。", ["细", "促"]], "8686": ["预后", "久病形神日消而脉象兼大，大而失和缓，是脉无胃气，生气不至之候。前诊便泻腹痛食减，舒肝健脾疏补无效，说明胃气难复。女子天癸将通之年，经脉气机怫逆，久郁热聚渐成枯涸，脉大为病进，故预后堪忧，议用郁劳治法。", ["大"]], "8687": ["治法", "原文未出脉名，述蓐劳下损不独病属八脉，且延及三焦，晨泄呕食、心热下冷、吸短寒热。下损及上，三焦气机失司，故不可止嗽清热，当扶胃气安谷，使月事仍来方得回春。病机为八脉虚损、三焦失职，治法重在扶胃气以复生化之源。", []], "8688": ["病机", "脉左坚搏仍然，左关候肝，坚搏为肝血枯涸、气失柔和之象。经来甚少而咳呛涎沫、夜热汗出，乃肝血肉枯、虚火刑金，已属劳损。坚搏非实邪，是阴血亏极而脉失濡养，故宜甘缓养肝胃、纳谷望愈；若见热投凉、希图治嗽，则胃伤速惫，反促其危。", ["坚", "搏"]], "8689": ["病机", "停经九月，少腹重坠而痛，少阴脉涩小，涩为血少、小为气虚，冲任虚馁，血海不充，故非妊象。涩小之脉示精血亏乏、脉道不利，冲任失养则少腹重坠而痛；虚极不能固摄，故怕其暴崩。此以脉断非孕，主冲任虚损、血枯经闭之病机。", ["涩", "小"]], "8690": ["病机", "经先期三日、热多寒少，脉右弦大。右关候脾胃，弦大主邪盛而血分偏热；弦为厥阴之脉，大则热邪壅盛。热入血分，迫经先期，邪窒在血，故治厥阴疟。脉弦大与热多寒少相应，示血分偏热、疟邪深伏血络之病机，非单纯表证。", ["弦", "大"]], "8691": ["病机", "暴崩去血过多，络中空虚，脉见酸软。软为气血不足、脉道失充之象，血去则络空，浮阳挟内风上扰，故心悸、筋脉酸软。此奇经病也，冲任失蓄，血海骤虚，虚风内动。脉软正合络虚风动之机，主崩后气血两亏、奇经不固之候。", ["软"]], "8692": ["病机", "阴伤于下，热气上冒，脉左坚数。左脉候肝肾，坚为阴亏脉失柔润，数为热象，阴亏于下则阳不潜藏，虚热上冒。坚数并见，示阴伤火旺、血热妄行之机，故虑其失血；不可强迫通经，通之则更伤阴血，反致血溢。此脉主阴虚内热、迫血妄行之病机。", ["坚", "数"]], "8693": ["病机", "脉象弦细而数，弦为肝旺，细为血少，数为热象。肝脾不统藏、任带失约束，故天癸妄行有块、腹痛作哕、谷食减少。弦细数示肝脾两虚、血热妄行而兼郁滞，统藏失职则经行妄下，再延有崩漏之渐。此脉主肝脾不调、任带不固之病机。", ["弦", "细", "数"]], "8694": ["病机", "湿温月余，弥漫三焦，身热不清、耳聋面瘦、结胸自利，脉息弦数。弦主湿郁气滞、少阳枢机不利，数主热邪内蒸；湿热胶结三焦，正虚邪恋，故脉弦数而症见结胸自利。深虑正不敌邪、致生歧变，此脉示湿热壅遏、正虚邪盛之病机，预后当慎。", ["弦", "数"]], "8695": ["病机", "湿温结胸自利，身热未清，已五候有余，脉象细濡。细为正气不足，濡为湿邪偏盛、脉道弛缓；湿热久羁，正气渐伤而湿仍未化，故脉不弦数而转细濡。此示正虚湿恋、邪少虚多之机，深虑正不敌邪、外生枝节，拟方获效乃吉，预后须防变。", ["细", "濡"]], "8696": ["病机", "脉象滑数，滑主湿痰内蕴，数主热邪偏盛。本案湿温延经月余，寒少热多，胸次不开，正合湿痰热邪交蒸之象。滑数并见，说明湿热痰浊壅滞气分，邪势未衰而正气渐耗，故虑正不敌邪、致生枝节。", ["滑", "数"]], "8697": ["病机", "脉象弦细而滑，弦主肝郁，细主阴血不足，滑主湿痰内扰。产后百脉空虚，湿温弥漫三焦近一月，右边发颐，谷食不进，正虚邪恋。弦细为肝郁血少，滑为湿痰，故深虑外脱之虞。", ["弦", "细", "滑"]], "8698": ["病机", "脉象弦涩，弦主肝木乘脾，涩主水湿困中、气血滞涩。湿温后肝木乘脾，水湿困中，脘腹膨胀而大，脉弦涩正合肝郁湿阻、气机壅塞之机，故再延有胀满之虑。", ["弦", "涩"]], "8699": ["病机", "脉来濡数，濡主湿邪偏盛，数主热邪内郁。湿温五候有余，身热不清，白㾦现而未透，舌苔白滑，渴不多饮，甚则作呕咳，皆湿热郁蒸、正虚邪恋之象，故虑正不胜邪、致生歧变。", ["濡", "数"]], "8700": ["病机", "脉息弦数，弦主肝郁湿痰入络，数主热邪内结。先后天不足，湿温结胸，自利月余不解，湿痰入络致左腿痹痛、伸屈不利，脉弦数正合正虚邪结、湿热痰浊交阻之机，故虑正不胜邪、致生歧变。", ["弦", "数"]], "8701": ["病机", "脉象细濡，细主正气不足，濡主湿邪内蕴。湿温九日，身热下利，白㾦现而未透，脉细濡说明湿邪留恋气分、正气已伤，邪有内陷化热逆传之势，故深虑化热逆传。", ["细", "濡"]], "8702": ["病机", "脉息细濡，细主正虚，濡主湿郁。湿温郁而不伸，寒热多日不清，白㾦未透，舌苔底白罩灰，脉细濡正合湿浊内郁、阳气不伸之机。原文谓水极似火证，谨防昏陷，说明湿郁化热、有内陷心包之危。", ["细", "濡"]], "8703": ["病机", "脉象弦细，弦主肝木乘脾，细主脾虚湿困。肝木乘脾，湿痰内困，遂令脘腹膨大、谷食减少，面浮肢肿，脉弦细正合肝郁脾弱、湿痰内阻之机，故再延防成胀满，治以温中化饮法。", ["弦", "细"]], "8704": ["病机", "脉弦为肝木偏旺，濡为湿痰内蕴之象。原文言\"肝木乘脾，湿痰互结中宫\"，弦应肝旺乘脾，濡应湿痰困阻，故胸次结痞；肝阳上升则头目眩晕。弦濡并见，正合木旺土湿、痰饮内结之病机，治以天麻二陈通络化饮。", ["弦", "濡"]], "8705": ["病机", "弦主肝旺，滑主湿痰。原文谓\"肝旺胆虚，湿痰入络，虚阳上升\"，弦为肝阳偏亢，滑为痰湿内盛，痰湿入络、虚阳上扰，故心悸头眩耳鸣、懊𢙐难名、惊悸麻痹善怯。右脉反关、左脉独见，示病在肝胆而痰湿阻络，脉症相合。", ["弦", "滑"]], "8706": ["病机", "沉主里、主水湿内困，弦主肝木偏旺。原文言\"肝木侮土，湿痰困中，少腹膨胀而大\"，沉弦并见，说明肝气横逆、湿痰困阻中焦，气机壅滞于里，故少腹膨胀。脉沉弦而见胀大，为木侮土、湿痰内结之征，延久恐成气臌。", ["沉", "弦"]], "8707": ["病机", "沉脉主里、主气滞湿困，弦脉主肝木乘脾。原文谓\"肝木乘脾，湿痰内伏\"，致脘腹两胁胀膨三年之久。沉弦示病位在里，肝气郁滞、湿痰内伏，气机不得宣通，故胀膨持久。脉症相应，宜远烦戒怒以疏肝气，缓图其本。", ["沉", "弦"]], "8708": ["病机", "弦主肝木乘脾，数主内热。原文言\"肝木乘脾，湿痰互结，致成痞块\"，又见\"内热熏灼，间或作哕\"。弦为肝旺气结，数为热象，湿痰与肝气互结而成痞块，内热熏灼则经频带下、作哕。弦数并见，示肝郁化热、痰结于里之病机。", ["弦", "数"]], "8709": ["病机", "沉主里、主不足，小主气血亏虚。原文谓\"肝肾血水两亏，不能涵养筋脉，故令左肢不遂\"。沉小示精血水液内亏，筋脉失养，故肢体不遂；水火不交则更伤肝肾。脉沉小而见偏废，为正虚不足、筋脉失濡之征，宜缓图补养。", ["沉", "小"]], "8710": ["病机", "沉主里，弦主肝木乘脾，滑主湿痰内伏。原文言\"肝木乘脾，湿痰内伏，虚阳上升\"，故胸次不开、头目旋运、哕吐涎沫、食少神疲。沉弦滑并见，示湿痰困中、肝阳上扰、胃气上逆之病机，脉症相符，宜徐图化饮平肝。", ["沉", "弦", "滑"]], "8711": ["预后", "沉细为气血不足、正气内虚之脉。原文谓体半气虚、多湿多痰，肝郁乘肺致膺胸痹闷，胃逆气逆血流盈碗。脉息尚幸沉细，说明虽有大出血而脉未洪大躁急，正气尚存，故言\"幸\"；然沉细示本虚，防涌脱之变，脉象关乎预后转归。", ["沉", "细"]], "8712": ["病机", "脉虚为正气不足，滑主湿痰内蕴。本案素本肝脾不和，湿痰入络，致胸次嘈杂、心悸头眩；热蕴曲肠则成赤白滞下、腹痛。脉象虚滑正合脾虚湿盛、痰热交阻之机，故法当先治其标，清化湿热痰浊。", ["虚", "滑"]], "8713": ["病机", "弦主肝郁气滞，细为血少，紧主寒痛。气滞血瘀、湿痰互结，日久成瘕聚，延二十五年；今夏肝郁引动，疟痢叠见，腹中脘胁作痛、漉漉有声、谷食减少。脉弦细而紧，示气结血涩、痰湿内阻，痛甚防厥，故须防气机闭阻。", ["弦", "细", "紧"]], "8714": ["病机", "沉主里，弦主饮主痛，滑主痰湿。悬饮内停，肝木侮土，脾胃交亏，命火不升，故心悸懊𢙐、哕吐涎沫、脘左作痛；水饮不能下输膀胱，则脘胀足肿、小水不利。脉沉弦而滑，正合饮邪内结、气化不利之机，再延防成气臌。", ["沉", "弦", "滑"]], "8715": ["病机", "沉脉主里，弦主饮癖，滑主痰湿。饮邪入络，结于脘胁，故悬饮成而心痹痛、漉漉有声、时作时止。脉沉弦而滑，说明饮停络脉、气机不畅，属里实饮盛之候，治宜缓图，化饮通络。", ["沉", "弦", "滑"]], "8716": ["病机", "沉主里主寒，弦主肝主痛。肝木侮土，气滞寒凝，故少腹作痛、痛甚哕吐、食入反出、大便秘塞，已作三次。脉沉弦，示寒凝气滞、肝胃不和，病在里而属寒实，故拟方徐图，温通降逆。", ["沉", "弦"]], "8717": ["病机", "弦主肝主风，滑主痰饮。肝阳化风，上腾清窍，饮邪入胃，故脘次左右作痛、甚则哕吐、两肋有形、心悸头眩、肉𥆧筋惕。脉弦滑，正合风阳上扰、痰饮内动之机，治宜缓图，熄风化痰。", ["弦", "滑"]], "8718": ["病机", "弦为肝风之象，滑为痰饮之征。肝阳化风，痰饮入络，扰乱上升，故目眩头晕、哕吐并见。书云“无风不眩，无痰不晕”，脉弦滑恰示风痰上扰清窍，治当缓图，平肝熄风、化痰降逆。", ["弦", "滑"]], "8719": ["病机", "弦主肝阳化风，滑主痰湿内蕴。肝阳上腾清窍，则头目眩晕；痰湿下扰精室，则间或梦遗。脉弦滑，说明风阳与痰湿相合为患，病机重点在肝风痰浊，故拟方善图，缓以调之，方可渐入佳境。", ["弦", "滑"]], "8720": ["病机", "脉弦而数，弦主肝胆，数主热，合之则示肝胆热盛。原文“肝胆之热上移于脑，致在鼻瘜”，热循经上攻，故右颧红肿、牙龈出脓。脉象与症相应，弦数为实热之征，非虚寒可比。", ["弦", "数"]], "8721": ["病机", "脉弦滑，弦主肝胆气郁，滑主痰饮内盛。原文“痰饮射肺，咳嗽气喘，声音不扬”，痰阻肺气，故脉见滑；肝胆郁而化风，故脉弦。弦滑并见，示痰饮与肝郁相合为病。", ["弦", "滑"]], "8722": ["预后", "脉弦数，弦为肝胆，数为热盛。原文“起于鼻渊，酿成损怯”，热久灼阴，损及根本，故脉象弦数不退。此脉示邪热未清而阴已伤，若数不减则损怯难复，故曰“应手乃吉”，以脉转缓为佳。", ["弦", "数"]], "8723": ["病机", "脉弦细，弦主肝郁，细主阴血不足。原文“湿热蕴于曲肠，致成肠癖”，久延数载，湿热伤阴，肝郁乘脾，故食少神疲、居经四月。弦细为虚实夹杂之象，久延防怯，正虚邪恋之机。", ["弦", "细"]], "8724": ["病机", "脉沉弦而滑，沉主里，弦主肝胆，滑主痰。原文“惊恐伤胆，郁痰内犯心胞”，痰郁化热，蒙蔽心神，故言语错乱、神识不清。沉弦滑示病在里，痰郁肝胆，上扰心包，似属癫症之机。", ["沉", "弦", "滑"]], "8725": ["预后", "原文“脉象就平”，谓脉已由病脉渐转平和，非具体脉象。调治后“肝胆渐和，郁痰渐化，心肾渐交”，脉平示邪退正复，症势有转机。此以脉象平和为预后佳兆，仍须守方续进。", []], "8726": ["病机", "脉沉弦而滑，沉主里，弦主肝胆，滑主郁痰。原文“仍属肝胆内蕴郁痰所致”，癫症复发，痰郁肝胆，蒙蔽心神。脉象与前案同，示病机未变，痰郁深伏，故需徐图缓治。", ["沉", "弦", "滑"]], "8727": ["病机", "脉象滑数，滑主痰湿，数主热。原文“胆热上移于脑，致成鼻渊，且生瘜肉”，热灼血络则鼻衄，痰热内蕴则嘈杂吐酸、胸胁胀痛。滑数示痰热交阻，胆热上攻，血行横逆之机。", ["滑", "数"]], "8728": ["病机", "脉沉而数，沉为里为阴，数主热主阳。本案鼻衄失血过多，肝阳上升，脾土受侮，郁痰内扰，头额昏痛、胸次嘈杂、面浮肢肿，皆阳升痰郁之象。脉沉示病在里，数示阳热内扰，血去阴伤而阳不潜藏，故见沉数，非表热之数，乃内伤虚阳之数，再延防损。", ["沉", "数"]], "8729": ["病机", "脉弦滑，弦主肝木气盛，滑主痰热内壅。本案阳明胃热上升致鼻衄，虚阳上僭，头目不清。胃热循经上冲，肝阳随之升腾，痰热交阻，故脉见弦滑。弦为肝旺，滑为热痰，与头目不清、衄血相应，拟方徐图，示病势缠绵需缓治。", ["弦", "滑"]], "8730": ["病机", "脉弦芤，弦主肝热相火有余，芤主阳络受伤、血去营亏。本案相火有余、肾气不充，遗滑并形，肝热胃寒，哕吐酸水，血吐成块，营卫交亏而寒热往来。弦为肝火亢盛，芤为失血之征，二者并见，示火盛而络伤，仍防涌吐再耗营血。", ["弦", "芤"]], "8731": ["病机", "脉细数，细主阴血亏少，数主热主虚。本案阳络受伤，气逆血溢，动辄盈碗，交春发作，近感客邪增患咳逆。细为营血不足，数为虚热内扰，血去阴伤而气逆不降，故脉细数。法当先治其标，示客邪咳逆为急，细数之脉反映本虚标实之机。", ["细", "数"]], "8732": ["病机", "脉弦涩，弦主肝气郁滞，涩主气机不利、血行不畅。本案向有疝气，膀胱之气不化，二便不通已两旬。疝属肝经，肝郁则气结，气不化则水道不行，脉道涩滞，故见弦涩。弦为肝旺，涩为气滞血瘀，二便不通与脉相应，治之不易。", ["弦", "涩"]], "8733": ["病机", "脉沉弦而涩，沉主里，弦主肝旺，涩主气滞血瘀。本案七疝统属于肝，肝旺侮土，脾胃受伤，脘肋胀大、面浮肢肿、谷食减少。肝木乘土，气结血滞，脉道不利，故沉弦而涩。沉示病在里，弦涩示肝郁土困，再延防其土败，预后堪忧。", ["沉", "弦", "涩"]], "8734": ["病机", "脉象沉细，沉主里主阳虚，细主气血不足。本案暑湿内蕴曲肠，酿成肠癖，胸次喜温，遍身皆寒，皆阳虚之故。暑湿伤中，阳气式微，不能温煦，故脉沉细。沉为阳虚不能鼓动，细为气血衰少，与遍身皆寒相应，治之不易，拟方力图。", ["沉", "细"]], "8735": ["病机", "脉弦而大，弦主肝气犯胃，大主邪盛病进。本案暑湿内蕴曲肠，酿成赤白滞下，肝气犯胃，郁痰内伏，胸痞作哕，右肋时痛，谷食难运。弦为肝木乘土，大为湿热壅盛，脉证相合，防成噤口，示邪盛正伤、胃气将败之危，获效乃吉。", ["弦", "大"]], "8736": ["病机", "脉弦为肝气不降，涩为气与痰搏、升降失常。原文言“气与痰搏，食入作阻，甚则哕吐饮食，脘腹时痛”，弦涩相合，主肝肺气机壅滞、痰阻中焦，故见食阻哕吐、脘腹痛，延久防神思间病。", ["弦", "涩"]], "8737": ["病机", "脉弦细而滑，弦主肝厥犯胃，细为湿痰困中，滑主痰湿内蕴。原文“脘痛哕吐，食入反出”，乃肝气横逆、胃失和降，湿痰阻滞中焦所致，故脉象弦细而滑，拟方徐图。", ["弦", "细", "滑"]], "8738": ["病机", "脉沉弦，沉主里、主水饮，弦主饮邪搏结。原文“命火、脾阳不振，水饮伏胃，呕吐涎沫，甚则食入反出”，命火脾阳不振则水饮内伏，胃气上逆，故脉沉弦，拟方获效乃吉。", ["沉", "弦"]], "8739": ["病机", "脉弦细而滑，弦为木来侮土，细为火不生土，滑主水饮停中。原文“土不制水，水饮停中，于是哕吐并见，甚则食入反出”，乃火不生土、木侮土、水饮内停之机，症延三载，非徐图不可。", ["弦", "细", "滑"]], "8740": ["病机", "脉弦涩，弦主肝气不降，涩主气与痰搏、道路妨碍。原文“肺气不升，肝气不降，气与痰搏，升而不降，道路妨碍，食入觉阻，动辄呕吐”，此关格之渐，弦涩示气痰交阻、升降失司。", ["弦", "涩"]], "8741": ["病机", "脉弦细而数，弦主肝气横逆，细为营阴不足，数主郁热内扰。原文“乘胃犯肺，脘中时痛，间作咳逆，营卫不和，为寒为热，声音不扬，向曾失血”，肝逆犯肺、营卫失和，久则防成肺痿。", ["弦", "细", "数"]], "8742": ["预后", "脉弦细无神，弦细为肝郁阴伤之象，无神则胃气衰败、根本已虚。原文“根株未尽，近来复作，殆有甚焉”，脉失神气，故谨防肺胀，示病势深重、预后堪虑，拟方以尽人力。", ["弦", "细"]], "8743": ["预后", "脉弦涩，弦主肝木侮土，涩主气机壅滞、血行不畅。原文“肝木侮土，脘腹膨大”，弦涩示肝郁乘脾、气滞血瘀，胀满已成，故谨防单胀，属预后警示之论。", ["弦", "涩"]], "8744": ["病机", "脉弦为肝木偏旺，滑为痰饮内盛。素有痰饮咳喘肿胀，痰浊上逆，肝气乘之，故脉见弦滑。弦主气机郁滞，滑主痰湿壅盛，二脉相合，提示痰饮上泛、肺气壅塞之势，谨防水溢高原成肺胀，即痰饮上逆犯肺之危候。", ["弦", "滑"]], "8745": ["病机", "脉弦为肝脾不和，细为营血不足，涩为水湿困中、气血运行不畅。居经五月，肝脾不和，水湿困中，肚腹膨胀而大，面肢肿，脉弦细而涩，正合肝郁脾虚、湿浊内停之机。弦细示肝脾两伤，涩示湿阻血滞，故主水湿困中之肿胀。", ["弦", "细", "涩"]], "8746": ["病机", "脉弦为肝木乘脾，细为营血亏少。暑湿蕴于曲肠，酿成滞下，脘腹膨胀而大，谷食减少，脉象弦细，说明暑湿伤中、肝脾不和，气机郁滞而血少。弦细并见，主肝郁脾虚、湿浊内蕴，再延防成胀满，即恐湿浊日盛、脾土日衰而成鼓胀。", ["弦", "细"]], "8747": ["病机", "脉弦为肝木乘脾，滑为湿浊盘踞，涩为气血瘀滞。产后肝木乘脾，湿浊盘踞中宫，脘腹膨大，左胁作痛，谷食减少，不能安卧，脉弦滑而涩，正合肝郁脾困、湿浊夹瘀之机。弦滑示湿浊壅盛，涩示血行不畅，谨防水溢高原酿成肺胀。", ["弦", "滑", "涩"]], "8748": ["病机", "脉弦为肝木偏旺，数为有热。天癸应至不至，肝木侮土，营卫交亏，少腹胀痛，或寒或热，食少神疲，脉象弦数，说明肝郁化热、乘犯脾土，营卫失调。弦数并见，主肝郁有热而脾土受侮，故见寒热、胀痛、食少神疲诸症。", ["弦", "数"]], "8749": ["病机", "脉弦为肝木乘脾，细为营血不足。肝木乘脾，湿邪内困，脘腹膨胀，临经期尤甚，脉象弦细，说明肝郁脾虚、湿浊内停，经期气血下注则脾土益虚，故胀甚。弦细示肝脾两伤、湿困血少，根蒂已深，非徐图不克。", ["弦", "细"]], "8750": ["病机", "脉弦为肝气郁滞，滑为痰湿内蕴。肝气入络，脾土受侮，前后心时而串痛，脘痛且胀，甚则作哕，脉象弦滑，说明肝郁乘脾、痰湿中阻、气机上逆。弦主气郁，滑主痰湿，故见串痛、胀满、哕逆，气虚多汗则久延非宜。", ["弦", "滑"]], "8751": ["病机", "脉弦为肝郁乘胃，细为阴血不足，芤为失血之后络脉空虚。肝郁乘胃，脘次及脘右胀痛，哕吐并见，病久入络，气血皆瘀，六年前阳络受伤曾失红，脉弦细而芤，正合肝郁血瘀、阴血亏虚之机。芤示络伤血少，故病久根深，治之不易。", ["弦", "细", "芤"]], "8752": ["病机", "脉细滑而数，细为营阴亏虚，滑为郁痰内扰，数为木火亢盛。木火凌金则咳嗽失红，肝胃不和则郁痰扰乱神明，营卫交亏故寒热互见。脉象反映火郁痰凝、阴伤营损之病机，久延防损，正虚邪恋之候。", ["细", "滑", "数"]], "8753": ["病机", "脉弦滑，弦主肝郁气滞，滑主水饮内蓄。肝脉布胁肋，脾脉络胸中，肝脾不和则水饮内停，故脘胁胀痛、漉漉有声。天癸先期亦肝郁化热之征。脉象示肝脾不调、水饮内蓄之病机，若不调治，防土败。", ["弦", "滑"]], "8754": ["病机", "脉弦细而滑，弦为肝火亢逆，细为阴血不足，滑为水饮内蓄。水饮困脾射肺则肿胀气喘，肝火上冲则目损。脉象示水饮与肝火交炽、本虚标实之病机，症势丛杂，故拟方徐图。", ["弦", "细", "滑"]], "8755": ["病机", "脉沉弦，沉主里主虚，弦主饮主痛。命火不足则水饮内蕴，脾胃交亏则脘腹胀痛、漉漉有声，脐旁有形乃水饮积聚。初发吐利为脾胃虚惫之象。脉象示命火式微、水饮内停之病机，根蒂已深，治之不易。", ["沉", "弦"]], "8756": ["病机", "脉沉细，沉为阳虚不能鼓动，细为阴血亏少。命阳不足则脾肾交亏，水饮聚胃，遇寒则哕吐并作；冲气上逆、精关不固亦由下元虚衰所致。脉象示脾肾阳衰、水饮内停之病机，故拟方缓图。", ["沉", "细"]], "8757": ["病机", "脉弦细，弦为肝木亢盛，细为土气衰微。肝木侮土，火不生土，则水饮停中。脉象示肝强脾弱、水饮内停之病机，再延则土败木贼，防成反胃，即胃气上逆、食入即吐之候。", ["弦", "细"]], "8758": ["病机", "脉弦细，弦主肝胆厥阳之气亢逆，细主阴血亏虚。厥阳之气由肺系上升于喉，故喉间不利、状如物阻；阴血不足则天癸应至不至。脉象示肝阳上逆、阴血亏虚之病机，已延二载，故拟方徐图。", ["弦", "细"]], "8759": ["病机", "脉弦滑，弦为肝胆厥阳上升，滑为宿饮随之上逆。厥阳与宿饮交阻喉间，故喉间不利、状如物阻；饮邪外溢则项外结核，上逆射肺则音嗄喘咳，营卫不和则寒热往来。脉象示阳亢饮逆之病机，再延防闭脱。", ["弦", "滑"]], "8760": ["病机", "脉弦沉，弦主肝胆气逆，沉主气机郁滞于里。原文述“肝胆厥阳之气上升，喉间不利，状如物阻，膺胸不开，间或哕吐”，正是厥阳上逆、气机壅塞之象。弦沉脉反映气逆于上而郁结于内，故主肝胆厥阳上升、胸膺不开之病机，与喉间物阻、哕吐症候相应。", ["弦", "沉"]], "8761": ["病机", "脉沉弦而滑，沉弦主气郁于里，滑主痰饮内聚。原文“肝胆厥阳之气上升，喉间不利，状如物阻，起于客冬，谷食懒进”，说明厥阳上逆兼痰浊阻滞，气机不畅故食少。沉弦滑脉正合气逆痰阻之病机，与喉间不利、谷食懒进相应，久延则痰气交结愈深。", ["沉", "弦", "滑"]], "8762": ["预后", "脉细数，细为阴血亏虚，数为虚热内扰。原文“肺痈溃后，未能完口，脉象细数，声音不扬，再延防痿”，肺痈溃后脓血久耗，气阴两伤，虚热不退，故脉细数；声音不扬乃肺气亏虚。此脉示正气已损而余热未清，若再迁延，防成肺痿之变。", ["细", "数"]], "8763": ["病机", "脉弦涩，弦主肝气横逆，涩主气血瘀滞。原文“肝脾不和，攻冲作痛，胸次结痞”，肝气犯脾，气机壅塞，血行不畅，故脉弦涩。弦涩并见，示气滞血瘀、肝脾失调之病机，与攻冲作痛、胸次结痞相应。痛甚则气逆更甚，故防厥逆。", ["弦", "涩"]], "8764": ["病机", "脉弦涩，弦为肝木乘脾，涩为气滞血瘀。原文“肝木乘脾，腹如束带，肝气入于肺管，膺胸不开，谷食不运，胸次结痞，已延二载”，说明肝气横逆日久，气血郁滞，脾运受困。弦涩脉正合肝郁气滞血瘀之病机，与腹如束带、胸痞食少相应，久病难速愈。", ["弦", "涩"]], "8765": ["病机", "脉弦细，弦主肝气郁滞，细主脾虚血少。原文“产后病疟，疟久伤脾，胸次结痞，大便时溏”，疟久耗伤气血，脾土虚弱，肝木乘之，气机结滞故胸痞，脾虚不运故便溏。弦细脉示肝郁脾虚、气血不足之病机，与胸次结痞、大便时溏相应，故需徐图缓治。", ["弦", "细"]], "8766": ["病机", "脉弦细而涩，弦主肝郁，细主血虚，涩主寒湿瘀滞。原文“产后肝脾受伤，寒湿内困，天癸逾期，少腹膨胀时大，胸次结痞，大便远血”，产后肝脾受损，寒湿困阻，气血瘀滞，故脉弦细涩。此脉示肝脾两伤、寒湿瘀结之病机，与经期异常、胸痞便血相应，久延防土败。", ["弦", "细", "涩"]], "8767": ["病机", "脉弦细，弦主肝木乘脾，细主气血不足。原文“肝木乘脾，气与痰抟，以致三焦不通，胸次结痞，天癸先期而少”，肝气横逆，痰气交阻，三焦气机壅塞，故胸痞、经少。弦细脉示肝郁脾虚、痰气互结之病机，与胸次结痞、天癸先期而少相应，病情夹杂，需次第调治。", ["弦", "细"]], "8768": ["病机", "脉软滑，软为气虚，滑为痰聚。原文谓肝木横逆、克脾犯胃，气与痰抟，故胸次结痞、胀痛哕吐；昔瘦今肥乃痰湿渐盛，天癸渐少且过期示脾运日衰、冲任乏源。脉软滑正合气虚痰抟之机，病延数年根蒂已深，故宜徐图。", ["软", "滑"]], "8769": ["病机", "脉弦滑，弦主肝木横逆，滑主痰湿内壅。原文言肝气横逆、克脾犯胃，致胸次结痞胀痛、哕吐；天癸先后不一亦由肝失疏泄、冲任不调。弦滑并见，示气逆与痰浊相搏，久延则胃气上逆日甚，故戒以再延防成反胃。", ["弦", "滑"]], "8770": ["病机", "脉弦细，弦为肝气横逆，细为脾胃交伤、气血不足。原文谓肝木横逆、脾胃交伤，少腹有块、胀痛作哕，根蒂有年。弦细示肝郁而脾虚，块由气滞血结，哕因胃气上逆；正虚邪结，攻补皆难，故非徐图不可。", ["弦", "细"]], "8771": ["病机", "脉弦细，弦主肝逆，细主气血衰少。原文述肝木克脾犯胃，胸次痞塞、胀痛哕吐涎沫、食入不运、形气消索。弦细示肝郁脾虚、化源不足，形气消索即气血日削之征；久延则神思间病，故戒再延。", ["弦", "细"]], "8772": ["病机", "脉象弦细，弦为肝木不舒，细为气虚不足。原文谓睪丸下坠由气虚下陷、肝木不舒所致，延已二载。弦细示肝郁而中气亏虚，升举无力，故坠；病久根深，非旦夕可复，故拟方徐图。", ["弦", "细"]], "8773": ["病机", "脉沉弦而芤，沉主里、弦主肝乘脾，芤主中虚血少。原文言肝木乘脾、湿痰互结，脘腹胀痛、谷食减少、脾阳不振、大便不实。沉弦示肝郁湿滞，芤示脾阳衰而气血内虚，土气将败，故戒再延防土败。", ["沉", "弦", "芤"]], "8774": ["病机", "脉沉弦，沉为病在里，弦为肝木横逆。原文谓肝木克脾犯胃，脘肋胀痛、哕吐涎沫，延十载根蒂已深。沉弦示肝郁气滞深入脾胃，木贼土困，升降失司；久病正伤，非徐图不克。", ["沉", "弦"]], "8775": ["病机", "脉弦沉而滑，弦主肝郁，沉主里、主水饮内停，滑主痰饮。原文谓命火不足、脾阳不振，水饮停中，见少腹膨胀、漉漉有声、肢肿且痛。弦沉滑正合阳虚水饮停聚之机，产后起病示冲任受损，再延则土败。", ["弦", "沉", "滑"]], "8776": ["病机", "脉虚弦而滑，虚为脾弱，弦为肝旺，滑主湿痰。肝木乘脾，脾运失职，湿痰内扰，故脘腹胀痛、按之有形、闻之有声。脉象与症相符，久延则脾土益虚，痰湿愈盛，故曰非宜。", ["虚", "弦", "滑"]], "8777": ["病机", "脉沉细而数，沉主里，细为阴伤，数为郁热。肝气横逆，肺胃交病，气机壅滞，故膺胸串痛、遍身酸痹。沉细数示病在里而阴分已伤，郁热内扰，非暴病可比，故拟方徐图。", ["沉", "细", "数"]], "8778": ["病机", "脉弦细而滑，弦为肝旺，细为阴伤，滑主痰湿。木叩金鸣，肝火犯肺，络伤血溢，故咳逆气喘。弦细示肝阴不足，滑为痰湿内蕴，脉症合参，病机在肝肺，故拟方徐图。", ["弦", "细", "滑"]], "8779": ["病机", "脉象弦细，弦为肝郁，细为阴血不足。天癸六载不至，阴血亏虚；木叩金鸣，络伤血溢，肝火犯肺；脾阳不振，大便不实。脉弦细反映肝郁阴伤、脾阳亦弱，乃虚损渐成之象。", ["弦", "细"]], "8780": ["病机", "脉象细数，细为阴血亏虚，数为内热。木火凌金，肝火犯肺，故咳逆频仍；肝脾不和，气机壅滞，故胀痛并见。细数脉示阴伤火旺，久延则损，故曰久防成损。", ["细", "数"]], "8781": ["病机", "脉弦滑，弦主肝郁，滑主湿痰。肝脾不和，湿痰内伏，气机不畅，故脘中胀痛；痰湿中阻，胃气上逆，故哕吐酸水。脉症相应，治当疏肝健脾、化痰降逆，获效乃吉。", ["弦", "滑"]], "8782": ["病机", "脉象细数，细为营卫交亏，数为虚热内扰。木叩金鸣，络伤血溢，肝火犯肺；营卫亏虚，故寒热往来；脾阳不振，故大便不实。细数脉示阴血不足而虚热内生，乃损之渐也。", ["细", "数"]], "8783": ["病机", "脉象弦细，弦为肝郁饮停，细为营卫交亏。久嗽金伤，饮邪射肺，故咳嗽；营卫亏虚，故寒热往来；脾阳不振，故大便不实。弦细脉示正虚邪恋，本虚标实，故拟方徐图。", ["弦", "细"]], "8784": ["病机", "脉弦为木旺，数主内热。原文谓“水不涵木，木叩金鸣”，弦乃肝木失养而亢，数因阴分不足、内热频来。木火刑金则经伤血溢，脾阳不振则大便不实，天癸愆期而少。弦数并见，示阴虚肝旺、虚热内扰，损情已萌。", ["弦", "数"]], "8785": ["病机", "脉弦细而数，弦为肝气逆，细为营血亏，数为虚热。原文“水弱肝虚，气逆血溢”，肝虚则气逆，血随气上而咳逆频仍、春时血涌；营卫交亏则寒热往来，天癸先期，谷食减少。弦细数并见，主阴血亏虚、肝热气逆，乃损之渐。", ["弦", "细", "数"]], "8786": ["病机", "脉弦滑数，弦主肝郁气逆，滑为痰，数为热。原文“血不荣肝，肝气横逆”，上不畏金则呛咳，下侮脾胃则脘胁串痛；产后气瘰、心悸善怯，皆痰热内扰、肝风上冒。弦滑数并见，示肝郁痰热、气血壅滞，症势多歧，防成疬劳。", ["弦", "滑", "数"]], "8787": ["病机", "脉弦细，弦为肝木乘脾，细为营卫两虚。原文“宿饮射肺，咳逆气喘”，饮邪上逆则脉弦；营卫两虚则寒热互见、盗汗；脾土不运则跗肿便溏。弦细并见，主土虚木乘、饮邪内伏，延防土败，即脾阳衰败之兆。", ["弦", "细"]], "8788": ["病机", "脉象细数，细为气血交亏，数为虚热内蒸。原文“木叩金鸣，络伤血溢”，肝火刑金则咳血；气血亏则寒热往来、形容消索；肝脾不和则天癸先期、谷食减少。细数并见，主阴血亏虚、虚火内扰，种种皆损情之渐。", ["细", "数"]], "8789": ["病机", "脉弦细而芤，弦为肝郁乘胃，细为气血皆瘀，芤主阳络受伤、失血。原文“肝郁乘胃，脘胁胀痛，哕吐并作”，痛久入络则气血瘀滞；六年前吐血，脉芤为血去络伤之征。弦细芤并见，示肝胃不和、气血瘀损，病久根深。", ["弦", "细", "芤"]], "8790": ["病机", "脉弦滑而数，弦为木火凌金，滑为痰热内扰，数为火盛。原文“咳逆失血”，木火刑金则咳血；痰热扰神明则营卫交亏、寒热互见；肝胃不和则痰热内生。弦滑数并见，主肝火痰热、灼金损络，延防成损。", ["弦", "滑", "数"]], "8791": ["病机", "脉细数，细为阴血亏虚，数为虚热内炽。原文“阳络受伤，吐血盈碗”，血去则阴亏，虚热灼络则血后咳逆、愈而复作；侧眠于右，尚未成怯。细数并见，主阴虚内热、络伤血溢，虽未成怯，仍须力图。", ["细", "数"]], "8792": ["病机", "脉弦细而滑，弦为木火亢盛，细为阴分不足，滑为痰热内蕴。木火凌金则咳逆失红，阴亏内热频来；脾阳不振则大便不实。脉象反映肝火犯肺、脾虚痰滞之病机，病根已深，需缓图。", ["弦", "细", "滑"]], "8793": ["病机", "脉象数，数为热为虚，此因先后天不足，木火凌金，阳络受伤而痰中带血；营卫交亏则寒热往来；天癸先期而少，为阴虚内热迫血妄行。脉数主虚热内扰，损情已萌。", ["数"]], "8794": ["病机", "脉细数，细为阴血亏虚，数为虚热内炽。劳伤咳逆愈而复作，阳络受伤曾经失红，乃肺阴耗损、虚火灼络之象。脉症合参，久延非宜，示劳损之渐。", ["细", "数"]], "8795": ["病机", "脉象细数，细主阴亏，数主虚热。先后天不足，木叩金鸣，络伤血溢；营卫交亏则寒热往来；经前带下、食少神疲为脾虚湿盛。脉细数反映阴虚内热、脾肺两伤，损之渐也。", ["细", "数"]], "8796": ["病机", "脉象弦数，弦为肝木亢盛，数为内热炽盛。木叩金鸣，络伤血溢；阴分不足，内热频来；天癸不至两月，侧眠食减形消，乃肝火灼肺、阴血亏耗之劳损根萌。", ["弦", "数"]], "8797": ["病机", "脉来细数，细为阴血不足，数为虚热内扰。先后天不足，天癸愆期；木叩金鸣，络伤血溢，呛咳形瘦侧眠；土受木侮则食少脘胀。脉细数示阴虚火旺、脾肺肝同病，久延防怯。", ["细", "数"]], "8798": ["病机", "脉弦数，弦主肝木横逆，数主热象。肝木横逆，肺胃交伤，则咳逆时作、间或作哕；营卫两亏则往来寒热。脉弦数反映肝火犯肺胃、营卫不和之病机，久延防损。", ["弦", "数"]], "8799": ["病机", "脉弦细，弦为肝木乘脾，细为阴血不足。脾肺交伤则面浮肢肿、少腹膨胀；阳络受伤则时形衄血；食少神疲为脾虚。脉弦细示肝郁脾虚、阴血亏耗，再延防损。", ["弦", "细"]], "8800": ["病机", "脉弦数者，弦为肝胆气逆，数为热为火。原文言\"肝胆厥阳之气上冲肺胃\"，故喉间如物阻、咳逆作哕、痰中带血，皆厥阳化火上迫肺胃之征；寒热往来、天癸先期亦肝火内扰、血热妄行之候。弦数并见，示病机为肝阳上亢、火热内盛，再延则阴伤而损。", ["弦", "数"]], "8801": ["病机", "脉弦细而涩，弦主肝、细主阴亏、涩主血少滞涩。原文\"疟母\"日久，\"肝肾交亏\"，故间或遗泄、面色无华；少腹膨胀、得大便方解，乃肝络瘀滞、脾运不健。弦细涩合见，示肝肾阴血两亏而兼气滞血瘀，久延则成胀满，故曰\"防成胀满\"。", ["弦", "细", "涩"]], "8802": ["病机", "脉来弦滑，弦为肝旺，滑主痰湿。原文\"邪客太阴\"成疟，左胁下疟母、胸次痞塞，乃肝脾不和、湿痰凝聚之象。弦滑并见，正合肝气郁结与痰湿内阻并存之机，故症属显然。治先中宫者，以脾为生痰之源，运中即所以疏肝化痰。", ["弦", "滑"]], "8803": ["病机", "脉象弦细，弦主肝木乘脾，细主脾胃气血不足。原文\"疟久脾胃受伤，湿痰困中\"，故脘腹作痛、心悸面黄、哕吐酸水，皆中虚湿困、肝木犯胃之候。弦细示土虚木贼、湿痰内阻，久则胃气上逆，故\"防成反胃\"，为虚中夹实之机。", ["弦", "细"]], "8804": ["病机", "脉象弦涩，弦主邪伏少阳、气机不畅，涩主久病入络、气血瘀滞。原文寒疟\"邪伏阴阳二维\"已七载，但寒不热，今寒热交作、得汗乃解，乃伏邪内动、正邪交争。弦涩并见，示病根深蒂固、气血郁滞，故曰\"根蒂已深，非徐图不可\"。", ["弦", "涩"]], "8805": ["病机", "脉象弦数，弦为少阳疟邪未解，数为温邪化热内盛。原文\"温邪化疟已经三月\"，邪留少阳而热象偏重，故脉见弦数。久延则热耗阴津、邪陷生变，故断曰\"久延非宜\"，提示当及早清透少阳、顾护阴液，不可再事迁延。", ["弦", "数"]], "8806": ["病机", "脉象弦数，弦主肝郁气滞，数主热。原文疟后\"气血交亏，湿痰下注\"，故小溲带浊而痛；天癸数月不至，乃血亏兼肝火灼阴。弦数示肝经郁热未清、阴血已伤，虚中夹实，故拟方徐图，不可峻攻，须养血清热、化湿并进。", ["弦", "数"]], "8807": ["病机", "脉象弦数，弦主饮邪内停、气机不利，数主郁而化热。原文\"积湿成痰，积痰成饮，痰饮射肺\"，故咳逆气喘。弦数并见，示痰饮内阻而兼郁热，肺失肃降。病属积渐而成，故拟方徐图，宜化痰蠲饮、清肃肺气，不可急于求成。", ["弦", "数"]], "8808": ["病机", "原文言积湿成痰、积痰成饮，痰饮射肺致咳逆气喘。弦主饮癖、气机不畅，滑主痰湿内盛，痰饮阻肺则脉道气机壅滞而见弦滑。此脉象说明痰饮内停、肺失宣降之病机，与咳逆气喘相应，故拟方获效乃吉。", ["弦", "滑"]], "8809": ["病机", "原文述肺气久虚、声音不扬，脾阳不振、大便不实，又曾失血、阳络受伤，刻下外邪与肝气入络致寒热不清、膺胸串痛。虚细为气血阴阳俱亏，数因外邪与肝气郁而化热。脉虚细而数正合本虚标实之机，故当先治其标。", ["虚", "细", "数"]], "8810": ["病机", "原文谓痰饮二载，肺脾肾交亏，咳逆哕吐、动辄气短。弦主饮邪内停、气机不利，滑主痰湿壅盛，虽三脏交亏而痰饮实邪仍著，故脉见弦滑。此脉说明痰饮内阻为当前主要病机，与咳逆哕吐、气短相应，拟方改重就轻。", ["弦", "滑"]], "8811": ["病机", "原文言痰饮射肺困脾，咳逆气喘，面色萎黄，四肢痿躄。弦主饮邪与气机郁滞，滑主痰湿内盛，痰饮困阻脾肺，气血不达四肢则痿躄、面黄。脉弦滑正说明痰饮内盛、脾肺受困之病机，与咳逆气喘、四肢痿躄相应。", ["弦", "滑"]], "8812": ["病机", "原文述肺脾肾三经皆亏，肝旺胆虚，痰饮内扰，龙雷之火上升，症势多歧。弦主肝旺与饮邪，细主三经亏虚，滑主痰饮内盛。脉弦细而滑说明正虚与痰饮、肝旺火升并见，虚实错杂，故症势多歧，拟方力图之。", ["弦", "细", "滑"]], "8813": ["病机", "原文言痰饮咳喘，曾经失血，已延八载。细主气血亏耗、久病正虚，滑主痰饮内盛，久病痰饮咳喘兼失血伤络，故脉细滑。此脉说明痰饮未除而正气已伤之病机，与咳喘、失血相应，拟方改重就轻以顾护正气。", ["细", "滑"]], "8814": ["病机", "原文谓素本肝脾不和，宿饮上干，客邪外抟，咳逆频仍，身热不清。弦主肝脾不和与饮邪，数主客邪化热，脉弦数说明宿饮与外邪相搏、肝脾失调而兼热象，故虑其正不胜邪，与咳逆、身热相应。", ["弦", "数"]], "8815": ["病机", "原文言痰饮射肺，咳逆气喘，脘腹膨胀，漉漉有声。滑主痰湿水饮内盛，饮邪射肺则咳喘，停于脘腹则胀而漉漉有声。脉滑正说明痰饮内停、水气泛滥之病机，与咳逆气喘、脘腹膨胀相应，虽调治较轻仍望获效。", ["滑"]], "8816": ["病机", "脉弦为肝木乘脾之象，细主阴血不足，数示木火内郁。原文“肝木乘脾，饮邪入络”致脘胁少腹窜痛、食少神疲，木火凌金则咳逆频仍。弦细而数正合肝郁化火、饮停络脉之机，故断“再延防损”，提示久延则正气更伤。", ["弦", "细", "数"]], "8817": ["病机", "弦属肝胆，数主内热，滑为郁痰内扰。原文“郁痰内扰神明”故胸中懊𢙐、多食善饥、舌白苔黄；“内热熏灼”则心悸头眩。弦数而滑正是痰热聚于肝胆、上扰心神之脉，故“渐近半载，再延防成痫症”，示痰火久郁有动风成痫之势。", ["弦", "数", "滑"]], "8818": ["病机", "弦为肝脉，数主热盛。原文“抑郁日久，痰热聚于肝胆，甚则犯于心包”，故神思恍惚、语言错乱、舌白苔黄。弦数反映肝胆郁热、痰火内炽，热扰心包则神明失主。故断“再延防生痉厥”，示痰热久郁有引动肝风、痉厥之变。", ["弦", "数"]], "8819": ["病机", "弦主肝郁，滑主湿热痰浊。原文“肝脾不和，任带交伤，湿热内蕴”，致天癸应竭不竭反而妄行、带下腥臭、少腹作痛。弦滑之脉正合湿热蕴于肝脾、下注任带之机，冲任不固则经带失常，故“再延防崩”，示湿热久蕴有迫血妄行之势。", ["弦", "滑"]], "8820": ["病机", "弦属肝胆，数主郁热。原文“肝胆不和，郁痰内扰”，故心悸头眩；湿热下注则小溲淋血、大便不实；肝热扰及冲任则天癸先期、时形带下。弦数之脉反映肝胆郁热、痰湿内蕴，热迫下焦则淋血带下，故拟方次第图之，示病机复杂需缓图。", ["弦", "数"]], "8821": ["病机", "本段未识脉名，纯论病机。原文“肝脉络于阴器，七疝统属于肝”，左有偏坠属肝经之疝；又“脾虚湿热下注膀胱”致小溲淋浊；肾气不充则善怯多疑。三脏同病，肝郁、脾虚湿热、肾气不足并见，故拟方速图之，示病势需早治。", []], "8822": ["病机", "弦主相火有余、肝郁不疏，滑主湿热下注。原文“先后天不足，相火有余，精关不固，湿热下移膀胱”，致成虚淋。弦滑之脉示本虚标实：脾肾不足为本，相火湿热为标，精关不固则淋浊不止，故拟方徐图之，示虚淋宜缓调脾肾、清利湿热。", ["弦", "滑"]], "8823": ["病机", "弦主肝郁相火，细主先后天不足、阴血亏虚。原文“湿痰困脾，加之相火有余，精关不固”，两腿时而酸痛。弦细之脉示脾肾本虚、湿痰内困而相火偏亢，虚实夹杂，故“拟方获效乃吉”，示正虚邪恋，调治得效方为佳兆。", ["弦", "细"]], "8824": ["病机", "脉弦主肝郁气滞，芤主阴血亏虚。心肾不交，热伤阴络，故小便带浊带血；弦芤并见，示阴虚火旺、络伤血溢之病机。延三月余，阴损难复，再延防损，提示久病正虚，预后须慎。", ["弦", "芤"]], "8825": ["病机", "脉弦滑，弦主肝阳上亢，滑主饮邪内扰。肾气不足则相火有余，遗滑并见；肝阳上升则头旋；饮邪内扰则心悸；阳明脉络不和，故脉象弦滑。此本虚标实、饮阳交争之病机。", ["弦", "滑"]], "8826": ["病机", "脉息细滑，细主肝肾不足，滑主瘀血入络。跌扑伤筋，瘀血阻络，故四肢麻痹、时形腰痛；脉细滑示正虚夹瘀。节劳静养佐以药石，可免类中，强调缓图防变。", ["细", "滑"]], "8827": ["病机", "脉弦芤，弦主气滞，芤主阴血亏虚。努力伤于阴络，血淋反复，乃络损血溢、阴虚气滞之病机。弦芤并见，示正虚邪恋，治之不易，拟方徐徐图之，提示不可峻攻。", ["弦", "芤"]], "8828": ["病机", "脉浮濡，浮主外邪，濡主湿伤。疮湿传里，脾肺交伤，咳喘肿胀，寒热不清，乃湿邪弥漫、肺脾同病之机。谨防水溢高原，肺胀致变，示湿邪上逆，预后须防喘脱。", ["浮", "濡"]], "8829": ["病机", "脉滑数，滑主湿浊，数主热。伏邪夹湿，身热不清旬余，乃湿热内蕴、伏邪未透之病机。滑数并见，示邪热与湿浊交蒸，拟方获效乃吉，提示邪正相争，治当清透。", ["滑", "数"]], "8830": ["病机", "脉沉弦而滑，沉主里，弦主邪郁，滑主痰湿。时邪入气分，神昏谵语，身热不清，乃邪陷气分、痰湿蒙蔽之病机。深虑正不敌邪，示邪盛正衰，预后堪忧。", ["沉", "弦", "滑"]], "8831": ["病机", "脉滑数，滑主湿浊，数主热。肝肾不足，吸受外邪，身热不清，大便不实，腰痛不已，乃正虚邪恋、湿热内蕴之病机。滑数示邪热未清，拟方力图之，当兼顾虚实。", ["滑", "数"]], "8832": ["病机", "脉弦细，弦为肝木偏旺，细为胃阴不足、土气受戕。原文见胀痛作哕、大便秘涩、脱肛下血，皆肝胃不和、气机逆乱之候。弦细并见，示肝横而胃弱，若再延宕，木愈克土，故曰“防土败”，脉象已露土气将败之机。", ["弦", "细"]], "8833": ["病机", "脉细濡，细主气血不足，濡主湿滞。原文谓湿热下注大肠致外痔有年，又见气虚下陷、坠不可言，是湿浊久蕴而中气已虚。细濡之脉正合虚中夹湿之机，故拟方获效，示湿热渐化、气虚可复，方可渐入佳境。", ["细", "濡"]], "8834": ["病机", "脉弦滑，弦主气滞，滑主痰凝。小产后正虚，气血凝滞，少腹结瘕攻冲作痛，痛牵两腰，天癸两月不至，是瘀滞与痰气相搏。弦滑示瘕结已成而正气已伤，攻补两难，故曰“治之不易”。", ["弦", "滑"]], "8835": ["预后", "脉细数，细为阴血亏少，数为虚火内动。产后四朝受外感，气血凝滞成瘕，腹痛，虚火灼金而咳逆，谷食少思，形气消索。细数之脉示阴亏火旺、正虚邪恋，久延则成劳，故原文戒“防劳”，属预后之判。", ["细", "数"]], "8836": ["病机", "脉弦滑，弦主肝气，滑主饮邪。肝气入络，饮邪乘势而入，遍身串痛，不能起卧，步履维艰，已经一载。弦滑并见，示气滞与饮邪胶结络脉，根蒂已深，非旦夕可拔，故曰“非缓图不可”。", ["弦", "滑"]], "8837": ["病机", "脉沉弦，沉主病在里，弦主肝邪。肝邪入肺，风池、风府痹痛，痛及肩臂，背俞皆所行经之地，间有咳逆。沉弦示肝邪深陷经俞，木反侮金，久则木乘土，故原文再延“防其土败”。", ["沉", "弦"]], "8838": ["病机", "脉弦细，弦为肝气郁滞，细为肺络失养。急躁伤肺络，致成胸痹，已经年余。弦细示气郁而络脉不充，胸阳痹阻，久病入络，非峻攻可效，故拟方徐图之，以缓调气血、通络宣痹。", ["弦", "细"]], "8839": ["病机", "脉弦滑，弦主风动，滑主痰湿。风邪中经络则口眼歪斜，中血脉则半身不遂，起于春正月，为期已久。弦滑示风痰阻络、气血痹阻，病根已深，非缓图不克，故治当渐化痰风、通经活络。", ["弦", "滑"]], "8840": ["病机", "脉弦数，左部倍大，弦为肝旺，数为火炎，左部候肝，倍大乃肝阳亢盛之象。肝旺胆虚，心火上炎，故见左目血贯瞳人、瞳凹陷、外眦白翳。此脉象揭示肝火循经上攻目窍，木火刑金，血热妄行，病位在肝胆心，主目疾。", ["弦", "数"]], "8841": ["病机", "脉象沉弦，沉主里主水，弦主肝主痛。肝木乘脾，水湿内困，中焦气机壅滞，故脘腹膨大、谷食减少。沉弦之脉反映肝郁克脾、水湿不化，病机为肝脾不和、水湿停聚，若不及时调治，恐成胀满之疾。", ["沉", "弦"]], "8842": ["病机", "脉象沉细，沉为水湿内停，细为气血不足。肝木乘脾，水湿停中，少腹时痛，腹大如鼓，乃脾虚不运、水湿泛滥之候。沉细之脉提示正虚邪实，脾阳不振，水湿困阻，治当温运脾阳、化湿利水，方免胀满之变。", ["沉", "细"]], "8843": ["病机", "脉弦细，弦为肝木乘脾，细为气血亏虚。命火不足，脾阳不振，水湿停中，故腹中胀痛、食入不运、形气消索、面色无华。弦细之脉反映本虚标实，脾肾阳虚为本，肝郁湿阻为标，再延必成胀满。", ["弦", "细"]], "8844": ["病机", "脉象弦滑，弦主肝郁，滑主痰浊。惊恐伤胆，抑郁伤肝，思虑伤脾，郁痰内扰神明，故神思恍惚、力倦神疲。弦滑之脉揭示肝郁脾虚、痰浊内蕴，痰气交阻，上扰清窍，病机为郁痰内扰，治当疏肝解郁、化痰安神。", ["弦", "滑"]], "8845": ["其他", "此段论述脉症合参之要，强调“症有真假恁脉而施治”“非审脉验症辨明定治何能干旋造化”，指出脉症难明、虚实疑似之际，须凭脉辨证以定攻补。原文未出具体脉象，主旨在于阐明脉诊在辨证论治中的关键作用，属医论范畴。", []], "8846": ["病机", "六脉全无，乃脾元下脱、胃气上浮、阴阳阻绝之危候。泄泻既久，冲和耗散，清阳不布，浊阴蔽塞，故卒然仆倒、四肢抽搦、体冷面青。此非风寒外中，实为肝脾相胜、虚风内动，脉象全无提示元气败脱，急宜大剂参附回阳救逆。", []], "8847": ["病机", "脉现细数，细为气血大虚，数为阴火攻冲。脾胃并虚，阴阳俱病，元气衰残，故身热如焚而寒必中伏，肌肉消铄、彻夜无卧、面无色泽。细数无力之脉，乃大虚之证，非阳明实热，若禁谷食、服寒凉则生气绝灭，宜甘温补中以救。", ["细", "数"]], "8848": ["病机", "六脉安静为常，右尺重按稍虚，揭示命门火衰。火不生土，脾胃虚弱，清阳不升，阴血失统，故下血。原文“土虚荣弱稍微下陷而成便血之候”正言此理，治以甘温培中升阳而安。", ["虚"]], "8849": ["病机", "两手浮洪，非外感实火，乃肾虚火动之候。少年酒色过度，真水亏而虚火独发，元气不足则闭藏弛而阴不固，故便血。原文“血乃精化精充而血始盛”点明精血关系，治以滋肾固阴而愈。", ["浮", "洪"]], "8850": ["病机", "六脉洪滑，右寸关尤汨汨动摇，为痰火内郁、风寒外束之象。邪正相搏，气凑于肺，橐籥失治节，故喘促声粗、汗出言断。原文“以脉合证知为痰火内郁风寒外束”明言病机，散寒驱痰则诸病自愈。", ["洪", "滑"]], "8851": ["病机", "两尺虚耎，知非实火奔迫，乃虚炎泛上。真阴衰耗，孤阳无依，虚火循经上冲，故左足一线之火直冲会厌。原文“虚症之中又有脾肾之分”辨析脾虚下陷与肾虚上僭，治以滋坎抑离而虚火退。", ["虚", "耎"]], "8852": ["预后", "六脉滑利，状若无病，然形肉已脱，环口黧黑，乃真阴耗散、孤阳依附之危候。原文“九候虽调形肉已脱法在不治”指出脉证相悖，胎元虽活而根本已拨，预判分娩时荣卫离决、元神无依，果如期而殁。", ["滑"]], "8853": ["病机", "抽掣不常，难以候脉，望色黄中现青，搐搦左甚于右。原文“东方属青入通于肝其病为惊骇”点明肝火风动。久患瘰疬，阴血不荣于内，惊骇触动肝火，火旺风生，木气摇土，故口眼歪斜、四肢搐搦、嚼舌流血。", []], "8854": ["病机", "左关芤而无力，为肝血枯竭之象。血虚不能荣养诸筋，筋脉挛缩，结块似瘰疬而实非。原文“此肝血枯竭不能荣养诸筋”直指病机，若误投败毒清火消痰化坚则胃气转伤，故以滋养肝血为要。", ["芤"]], "8855": ["病机", "六脉微弦，面色青黄，为肝旺凌脾之候。弦主肝旺，微主脾虚，土受木克，故腹痛。原文“切脉望色咸属肝旺凌脾”明言病机，前医作火治气治积皆误，治以建中抑木、六君子加消导而痛愈。", ["微", "弦"]], "8856": ["病机", "原文谓头眩症“六脉浮滑”，浮为风阳上扰，滑为痰湿内蕴，然服消痰顺气药无效，说明病本不在脾痰而在肾虚。作者引《素问》“头痛巅疾，下虚上实”，指出肾阴不充则肝火发而上动于巅，故脉浮滑为标痰之象，真机为下虚上实、肝火挟痰上逆，主头眩。", ["浮", "滑"]], "8857": ["病机", "崩漏半载，六脉“芤虚时或见涩”，芤主失血，虚主气弱，涩为久病生郁、血行不畅。原文断为“病久生郁大虚挟寒之象”，脾恶忧思寒湿，过用胶艾止涩则隧道壅塞，专用升柴则元气衰耗，故脉象反映气血大虚兼郁寒，主脾虚不摄之崩漏。", ["芤", "虚", "涩"]], "8858": ["病机", "血崩如涌泉，而“脉息安静全无病象”，肌体清癯非壮实，说明非血热妄行，乃脾胃气虚不能摄血。前医苦寒杂进反消阳气，故脉静而病重，正合气虚失摄之机。作者以甘温补中升阳取效，脉静正是虚证无实邪可据的佐证，主脾虚崩漏。", []], "8859": ["预后", "孕七月喘急不能卧，诸医杂治，作者诊得“脉幸洪滑”，断为产前可保无虑。洪滑为孕脉气血充盛之象，虽子悬喘急似危，脉与证相应，说明胎气虽逼而正气未败，故预后尚佳，唯分娩后需费周旋。此段以脉洪滑判断妊娠子悬的预后。", ["洪", "滑"]], "8860": ["病机", "左胁疼痛，服行气逐血反加呕逆，脉“左沉右洪”。左沉为肝郁怒动、气机内滞，右洪为肝火来侮脾阴、胃气受伤。原文谓峻药转伤胃气，三阴失职，仓廪无由而化，故中脘不通、食反上涌。脉象揭示怒动肝火侮脾、胃气虚败之病机，主胁痛呕逆。", ["沉", "洪"]], "8861": ["病机", "吐血后咳嗽气喘潮热，六脉“芤耎两足浮数”。芤耎为阴枯精竭、血失所养，浮数为孤阳气浮、壮火游行。原文断为“阴枯精竭而孤阳气浮”，肺金不能归纳丹田，壮火灼伤娇脏，故喘嗽乃发。脉象反映阴虚阳浮、虚火上炎之病机，主吐血后喘嗽。", ["芤", "耎", "浮", "数"]], "8862": ["病机", "久泻肉脱，少腹疼痛，食入即出，切脉“气口六部细弱无神”。细弱无神为阳气衰微、清阳不升，原文谓“原阴下陷，非但转输失职，将见闭藏倾败”。肾为胃关、脾之母，命门火衰则丹田气冷，脾不能运行精微。脉象示元阳衰败、脾肾虚寒，主久泻危候。", ["细", "弱"]], "8863": ["病机", "发热腹痛呕恶，六脉“沉郁”，面黑如薰。沉郁为气机郁滞、肝火内伏不舒。前用解郁调中症减，感怒气即发，说明郁火未清。后小便涩痛、小腹重坠，断为下焦肝火久郁已成小腹痈。脉沉郁正合郁火内结之机，主肝郁化火、酿痈之病。", ["沉"]], "8864": ["病机", "初诊六脉洪大，为阳明胃热血化为斑之象，热邪亢盛；斑未全透，故宜清胃解毒。药后壮热退而昏呆愈甚，再诊两手脉虚微，乃寒凉解邪后邪火虽退、正气独虚，胃脘真阳生机欲绝，故目闭僵卧如死。脉由洪大转虚微，反映病机由实热转为正虚，主胃气虚败，需急补胃气以回生机。", ["洪", "大", "虚", "微"]], "8865": ["病机", "脉人迎紧盛、右关洪大，人迎主外邪，紧盛为寒邪束表；右关候脾胃，洪大为阳明热盛。邪热拂郁，亢阳煽炽，火极似水而舌黑，神思昏愦如狂，将成燎原之势。脉象示表邪未解而里热已炽，热毒深入血分，故胸腹红斑，宜化斑清火凉血。", ["紧", "盛", "洪", "大"]], "8866": ["病机", "六脉洪大，形壮年高，卒然失声仆地、痰潮如锯、眼合遗尿，此气虚卒中而现脱证。洪大之脉非实热，乃正气浮越于外、内气飞越脱绝不续之象。原文辨闭脱，眼合遗尿属脱，小续命汤为闭证而设，用于脱证则妨于养正。脉洪大主虚阳外越，非邪实壅塞。", ["洪", "大"]], "8867": ["病机", "初诊六脉细数，细为阴亏，数为火旺，食饮即吐，知无阴则吐，诸呕吐皆属于火，季胁属肝肾，故以地黄汤滋阴降火。复发左关弦长，弦长主肝气有余，怒气伤肝，故现独大之象。后因劳怒，六脉虚耎，大虚而得盛候，脉证相反，法在不治，示正气已败。", ["细", "数", "弦", "长"]], "8868": ["病机", "六脉浮虚，浮为风邪在表，虚为卫阳不足。风为阳邪，卫为阳气，阳与阳合则伤表分，故伤风鼻塞、周身刺痛。脉浮虚示表虚受风，虽病属表分，但虚象已见，不可峻汗。前案呃忒自汗，脉尚有根，准头年寿温润，色脉生机犹存，主阳气虚而未尽脱。", ["浮", "虚"]], "8869": ["妇人", "手少阴脉动甚，两尺滑利，为结胎之兆。手少阴候心，心主血，动甚为血聚养胎；两尺候肾，滑利为肾气充盛、血海充盈。呕逆吐食、痰白沫、眩晕气急，乃恶阻之候，非翻胃脾败。脉象示妊娠，故以安胎和胃降逆取效，后产一女。", ["动", "滑", "利"]], "8870": ["病机", "产后发痉，口歪不语，角弓反张，时愈复作。原文未出脉象，然述肝为藏血之乡、风水之司，产后气衰于表、血衰于里，血耗则肝木枯而内风煽动，血不养筋则角弓反张，风淫胃脉则唇口引动。病机为血虚生风，非外风，故治风先治血，以滋润养肝血为主，少佐驱风。", []], "8871": ["病机", "六脉洪大，重按虚豁，右寸独数，此上盛下虚之候。洪大而重按虚豁，为肾水干涸、真阴虚竭，虚阳浮越；右寸独数，为肺中假阳旺，火灼津液成痰，胶结清虚之脏，久则肺热叶焦腐化为痈。脉象示本虚标实，肾阴亏而肺火炽，故咳咯脓血，法当清上焦痰火、滋化源。", ["洪", "大", "虚", "数"]], "8872": ["病机", "原文诊得「肾肝脉虚」，断为肾虚不能养肝，筋骨失濡。久历鞍马、餐风冒雾，外邪乘虚袭络，前医屡用解表，愈损真元，故两足无力顽麻不仁。脉虚正合气虚血少、肝肾亏乏之机，非风邪未净，乃本虚标实，故以神效黄耆汤加肉桂温养取效。", ["虚"]], "8873": ["病机", "「右手寸关俱见浮紧，重取带滑」，浮紧为新寒外束，滑为旧痰内搏。寒闭清道，痰随气逆，鼓动肺金，故咳嗽变哮喘、口张语言不续、呀呷有声。脉象正示表寒里痰互结之机，故主三拗汤宣发外邪、涌吐痰涎，使肺道通而痰行哮愈。", ["浮", "紧", "滑"]], "8874": ["预后", "「两手细数」，细为营血枯少，数为阴虚内热，血枯经闭年余、大肉去半、日晡寒热，正合二阳之病发心脾、女子不月之旨。心脾之气不充，血无以资，地道不行。脉细数示化源已竭，故断「证属难疗」，若不培补反攻，必至风消贲闭而不起。", ["细", "数"]], "8875": ["病机", "「六脉弦数不和」，弦属少阳，数为热，与寒热往来、大便溏、小便赤相应，明系少阳经症，非可汗下渗利。食停因邪未解，邪解则食自消。脉弦数不和正是邪郁少阳、枢机不利之象，故主小柴胡和解，去人参佐丹皮、山栀、花粉以清透。", ["弦", "数"]], "8876": ["预后", "原文「脉象和顺」，未及具体脉形，故脉象要素为空。盛暑发热六七日，昏沉不语、面赤苔焦、便闭，似危而脉和顺，兼身体软缓、唇吻红润、气息调匀，俱为吉兆。脉和则胃气未败，邪热虽传手少阴郁而不舒，犹可清透，故用导赤散加黄连、犀角灌服而愈。", []], "8877": ["病机", "「六脉虚大无力」，虚为气夺，大为脉体浮阔，按之无力则阳不内守。半产后血崩如注、头晕眼暗、面色青黄，甚至昏晕，正是血脱而阳气不能卫外固阴。脉虚大无力即阳微欲绝之征，故主补中益气、大虚必挟寒而加附子，非养阴止涩所宜。", ["虚", "大"]], "8878": ["病机", "「左手脉皆弦迟，右寸关虚大无力」，弦迟为寒凝气滞，右寸关虚大为中州阳气不布。饮食过饱伤脾，积痰成窠，寒中内结，故腹痛遇调即发。脉象示中脘阳虚、沉郁久凝，非温补辛散不能转否为泰，故用异功散加桂枝、半夏、炮姜、木香。", ["弦", "迟", "虚", "大"]], "8879": ["病机", "原文未载具体脉形，仅言「脉络胀张如不束之状」，属描述性语，故脉象要素为空。大肉削去、虚气攻冲、手足麻木不自主、夜寤不宁，乃阳明戊土虚而盗母气以养，心脾之气涣散，神伤恐惧自失，即「解㑊」之候。病机在补心脾以充元神，故与归脾汤。", []], "8880": ["病机", "原文载肝脉弦急，前医误作火热，用苦寒致洞泄、筋挛、少气。作者指出“寒束之脉每多见弦”，弦急非热，乃寒气入腹、清阳不升，故泄泻不止；寒主收引，筋脉失温则挛急，少气为清阳不升之征。此段辨弦急属寒，非火热，主病机为寒凝气滞、清阳下陷。", ["弦", "急"]], "8881": ["病机", "左脉沉紧、右脉沉涩，沉主里，紧主寒，涩主湿滞血瘀。原文断为“风湿寒三气杂至合而为痹”，以湿胜为著痹，即麻木之谓。沉紧示寒湿内着，沉涩示痰气凝结、郁而不畅，故足麻木不仁、背心麻木。脉象与“湿痰消而大气周流”之治相应，主病机为寒湿痰瘀痹阻经络。", ["沉", "紧", "涩"]], "8882": ["病机", "脉耎而气滑，耎即濡，主湿；滑主痰。原文断为“湿痰流注下焦为有余之症”，非不足。足肿痛而补血补气反剧，正因湿痰壅滞，滋阴则滞阳，补阳则固邪。濡滑相合，示湿痰内盛、邪实有余，故用燥湿化痰驱邪而肿痛消。此段以脉证辨虚实，主病机为湿痰流注、邪实壅滞。", ["濡", "滑"]], "8883": ["病机", "左手脉弦劲重按涩，右手洪滑。弦劲为肝气横逆，涩为积瘀，洪滑为痰热壅盛。原文断为“下焦积瘀、怒气伤肝”，致恶露不尽、臌胀青筋。弦劲涩示瘀阻肝经，洪滑示痰热内盛。又对比畜血与脾虚之辨，脉证合参，主病机为肝郁瘀阻、痰热互结。", ["弦", "劲", "涩", "洪"]], "8884": ["病机", "脉象迟微，原文谓“微为阳衰，迟为阴胜”，断为脾土虚而真阳衰。久泄不已，畏寒不减，初用四君子加姜桂不应，知非土中阳不旺，乃水中火不升，须助少火上蒸于脾。迟微并见，主阳气衰微、阴寒内胜，故温补少火而瘥。此段主病机为脾肾阳衰、阴寒内盛。", ["迟", "微"]], "8885": ["病机", "两手脉滑数，滑主痰，数主火。原文断为“沉湎于酒，酒能生湿，湿能助火，火湿相合而成痰，痰迷心窍则见鬼”。午余见鬼、恐惧昏沉、夜半发热，皆痰火扰心之象。滑数相合，正示湿火酿痰、痰热内扰，故用清化痰热之剂而神清鬼没。主病机为痰火迷心。", ["滑", "数"]], "8886": ["病机", "平昔脉弦洪兼数，右手更旺；今转数成迟，左手更觉无本根。原文谓“此至虚有盛候”，弦洪数似实，然转迟、左脉无根，示元气虚败、胃气将绝。腹中绞痛、发厥昏晕、中脘硬痛，状若实积，实为虚证。脉由数转迟，由洪转无根，主病机为脾胃虚寒、元气欲脱，故力主大补。", ["弦", "洪", "数", "迟"]], "8887": ["预后", "原文载壮热、发斑、狂乱、舌黑刺高、谵语直视，危候丛生。按诊脉“幸尚未散”，散为死脉，脉散则元气离散、预后不良；未散则胃气尚存，犹可救治。故用大剂白虎汤清阳明热，热退神安。此段以脉散与否判预后，脉未散示生机尚在，主病机为阳明热盛、胃气未绝。", ["散"]], "8888": ["病机", "原文虽未明言脉名，但述“脉尚未散”“脉气虚微”，知脉气已虚微而未至散乱，为阳气衰败、气随血脱之候。呕血百余碗、汗冷肢寒、目闭，皆阳气外脱、不能温煦固摄之象；药入即吐，胃气亦败。故病机为阳脱气衰，急当固气，非血药所宜。", []], "8889": ["病机", "六脉虚弱，为脾元亏损、气血不足之象。思虑过度伤脾，脾虚则气衰，气衰则火旺，火旺迫血上溢而吐血；血脱则气孤，气孤则胃闭而绝谷。脉虚弱正合脾虚气弱、气血两亏之机，故治以甘温扶脾、调和气血而愈。", ["虚", "弱"]], "8890": ["病机", "左关弦强搏指，为肝郁化火、火旺血沸之象；右关妈涩（疑为濡涩），主脾虚气结、血瘀不行。肝脾二脏喜疏利，忧思伤脾则气结血瘀，恚怒伤肝则气郁热生，火炎上腾空窍，故目胞生疙瘩红肿重坠。脉弦强主肝实，涩主瘀滞，治宜疏中泻东。", ["弦", "强", "涩"]], "8891": ["病机", "六脉微弱不堪重按，为神气损伤、心肝气虚之候。大惊则气乱，心失镇静而神气孤浮，魂无安宅而飘荡于外，故神思恍惚、目呆语言错乱。脉微弱正合气虚神馁，治以安神益气、固守飞扬之真，使魂随神摄。", ["微", "弱"]], "8892": ["预后", "原文未出脉名，但言“外证虽逆六脉尚存”，知脉气未绝，故为可治之预后。痢下赤脓、呕恶不食、冷汗肢冰、气促神昏，外证虽险，而六脉尚存则胃气未败，阳气犹可挽回。故用附子理中汤温阳，四肢渐温、自汗渐收而愈；若再投凉药，则气脱难救。", []], "8893": ["病机", "脉来洪大，为春温伏邪化热、里热炽盛之象。壮热神昏、自汗眼红、口渴舌黑、胸膈满闷，皆热邪充斥内外之症。洪大脉主阳明气分热盛，热灼津伤，故当速煎甘寒大剂清彻里邪，若泛用芩连苦寒，恐难救车薪之火。", ["洪", "大"]], "8894": ["病机", "六脉坚劲似芤类革，为冲和虚损、清阳散耗之候。坚劲非实，乃胃气衰而脉失柔和；芤革主中空，为阴血不足、阳气浮越。胸膈胀闷、四肢顽麻，皆脾虚郁结、清阳不布所致。脉为神机，全赖胃气充沛，今脉息无神，知郁结伤脾、脾病传胃，木失土养而肝亦自病。", ["坚", "芤", "革"]], "8895": ["病机", "脉带沉数，为火郁于中之象。痛势有时，非绵绵无间之寒痛；虽因食蟹感寒，然寒久成热，热郁于中，故脉沉数。热郁似寒，厥冷于外，此始末传变之道。前服姜桂理中反增胀痛，是以火济火。沉数脉主里热，故用四逆散加黄连透郁清热而愈。", ["沉", "数"]], "8896": ["病机", "脉形弦数，弦主邪郁少阳、三焦气机不畅，数主里热亢盛。原文谓“在里热邪，布于三焦，聚于阳明”，故见肌肤蒸热、舌苔黄、胸前痞闷、便泄溺黄，脉弦数正示热邪内郁、枢机不利，尚恐反复。", ["弦", "数"]], "8897": ["病机", "脉紧而数，紧主邪气搏结、湿阻气机，数主温邪内炽。原文述“温邪夹湿，招风以起，夹食难消”，故见身热不退、头痛节酸、痞闷按痛、耳聋溺赤，脉紧数反映邪势张皇、表里同病，每多传变。", ["紧", "数"]], "8898": ["病机", "热退身凉后脉仍数，原文谓“散而留者，舌上白苔，变作嫩黄之色，口鼻干燥，神倦妨食，溺黄”，此余邪未清、里热未净，数脉示郁热尚存，故清化为宜，不可骤补。", ["数"]], "8899": ["预后", "原文未出脉名，但言“脉静身凉，口干咽痛，容易发作”，白㾦转黄示“里有伏邪未尽”。脉静身凉似安而伏邪未净，故虽解而虑其复发，以栝贝养营法主之，属预后判断。", []], "8900": ["病机", "脉虽虚，原文谓“口尚干燥，津液未润之候”，虚脉示气营不足、津液未复，故养营一法在所必需。此虚为病后正伤、津亏未润之象，非单纯虚证。", ["虚"]], "8901": ["病机", "脉来不浮不沉而数，不浮不沉示邪不在表亦未深陷，数主里热郁蒸。原文见舌苔化嫩黄、身热少汗、口干苦、烦热不寐，脉数正应里热未清、气分郁热，故提化为主，虑其不战汗而变端。", ["数"]], "8902": ["预后", "脉息虽数，按之少神，数主温毒炽盛，少神示元气已衰。原文见青紫斑更多、紫黑血仍盛、身热口臭便黑，种种无向愈期，故脉数而少神为邪盛正衰、深恐猝然昏喘而败之危候。", ["数"]], "8903": ["预后", "脉无神而更见数促，数主温毒极盛，促示元气衰败、阴阳不相接续。原文见青紫斑更多、紫黑血涌、口舌糜烂、面青唇淡，一派“无阴则阳无以化”之恶候，故引“青斑为胃烂”，属危重预后。", ["数", "促"]], "8904": ["病机", "脉弦滑数，左右无神，弦主风动，滑主痰热，数主暑热内炽。暑先入心，伤气耗神，冷风外遏，袭入手足厥阴，故见神昏谵语、肢动头摇、气急痰声。面垢遗尿、口干苔剥为暑热伤津、痰热蒙窍之象，脉证合参，病机为暑热痰风交阻厥阴，有进无退。", ["弦", "滑", "数"]], "8905": ["病机", "脉弦滑数，弦主风动，滑主痰食，数主暑热。虽头摇肢动等症有和意，但身微热微汗、胸次不舒、得汤如噎、舌苔灰腻、口中干燥、大便旁流，显系暑风湿热痰食交阻三焦，邪势仍盛。脉象未缓，说明病邪未退，须凉膈清心分消其势。", ["弦", "滑", "数"]], "8906": ["病机", "脉来弦数，尺部软弱，弦数为暑热内伏营分，尺弱为津液暗伤。舌尖光红、汗收加热、痉象略重，皆暑伏营中、暗伤津液之征。似疟而作，为邪正交争。脉数不退，恐热极生变，故须天明以前微汗而解为正。", ["弦", "数", "弱"]], "8907": ["病机", "左脉稍和，右仍数滑，数主热，滑主痰湿。风动虽轻大半，而心包尚若明若昧，身热微汗、黄昏则剧、小溲频数、肢体易痉、舌苔灰浊、胸脘不舒，显系手足厥阴之邪欲归阳明中土，土中暑邪湿热结秘不开，气皆受病。脉右数滑，说明邪势未衰，病在险途。", ["数", "滑"]], "8908": ["病机", "脉数，左小右大，数主余邪未清，左小为阴分不足，右大为气分邪恋。舌尖稍红、口中干燥、夜频少寐、神少慧，皆阴虚邪恋之象。小便频数等症虽愈，而脉数未平，又值立秋大节，恐有反复，故清化余邪之中参入养阴。", ["数", "小", "大"]], "8909": ["预后", "脉平而带小数，平为邪退之象，小数则余热未清、正气已虚。神明已出、肢体更疲、言语无力、小寐妨食、舌色尖红、口时干燥，皆病渐退而正益虚之征。脉虽平而带数，说明暑邪未净，故仿七虚三实例，拟甘寒除热法，仍不出暑邪调治范围。", ["数", "小"]], "8910": ["病机", "脉形细小而按之至数则数，察其形象则滞，细小为元虚，数为暑邪内伏，滞为邪阻气机。失血之体元虚不复，又感暑邪，出入少阳阳明之界，故寒热分争于午后、胸前痞闷、舌苔满白、口中干腻、小溲色黄、大便或溏、咳嗽头痛体酸。脉证合参，虚中夹实，须提化时邪。", ["细", "小", "数", "滞"]], "8911": ["预后", "脉形虽然变小而数疾有力，小为肺损，数疾为热毒壅盛，有力为实邪内结。咳嗽臭痰、口中辟辟燥、胸前隐隐痛已半载，肺痈根底不清。脉数疾有力，说明热毒未衰，久延则声音渐烁，反成肺痿，不可救药。近来气息短促，肺金不能当令，更恐其喘，预后堪忧。", ["小", "数", "疾", "实"]], "8912": ["病机", "脉弱而色痿，神倦妨食、自汗心悸，皆元气虚衰之征。原文谓“元气因虚，余毒又走下腿”，溃而不敛、骱中强痛不和，是正气不能托毒外达，毒邪下注而局部失养。脉弱主虚，与色痿神倦相应，故断为虚证百出，须大补以扶元摄毒。", ["弱"]], "8913": ["病机", "右关脉息弦数，左寸关更甚，弦为相火内郁，数为火盛。原文谓舌为心苗、包络主相火，痛经日久津液暗伤，舌光绛无苔，是相火自戕根本；两目昏眩亦火升之象。脉弦数见于关部，正合火郁中焦、上炎为患，故恐口糜接踵而至。", ["弦", "数"]], "8914": ["病机", "脉息小弦，小为脾虚，弦主痰饮内停。原文以“脾为生痰之源，肺为贮痰之器”立论，咳嗽久而不轻、晨起更重、痰稠稀不一、苔薄白，皆脾运不健、痰湿上贮于肺之候。脉小弦正应脾虚饮聚，故欲清肺贮痰之器，必先绝脾生痰之源。", ["小", "弦"]], "8915": ["病机", "脉数而涩，数为热，涩为阴伤血少。原文谓阳络频伤之后，咳呛少痰、胸膈痞闷、喉痒干渴、少纳便结，乃酷暑内郁化火伤阴，肺失清肃。数涩并见，正合火郁阴亏、络伤血滞之机，故曰不宜久延，延则成损，与本来劳怯者有间。", ["数", "涩"]], "8916": ["病机", "右关脉数且急，右关属阳明，数为热，急为火势迫促。原文谓咳嗽久而已缓，尚易吐血，是阳明伏热上熏于肺、灼伤阳络所致。脉数急见于右关，正说明伏热在胃，非徒肺病，故以阳明伏热为病机根本。", ["数", "急"]], "8917": ["病机", "脉数主火邪未清。原文谓培养脾肺兼化火邪后得寐、咳嗽减，然尚形咳逆、吐出咸痰、喉痒口干、胸闷，是火郁肺金、痰热未净之候。脉数正应火邪尚存，故减不足言，仍须泻白散加味以清肺泻火，不可遽补。", ["数"]], "8918": ["病机", "脉数而左关浮大，浮大为风邪鼓动，数为化火。原文谓风邪深入肝经，化火伤肺，故咳嗽、咽痛音烁嗌干。左关候肝，浮大见于此部，正合风邪入肝、木火刑金之机；火灼肺津则音烁嗌干，故恐其成损。", ["数", "浮", "大"]], "8919": ["病机", "脉芤大，芤为血脱中空，大为气浮不敛。原文谓血已止而脉尚芤大，是“气分大虚，不能摄血之象”。血虽暂归，气不摄血则易复脱，故脉象未复。此正血脱益气之法所设，当补气以摄血，不可因血止而遽止。", ["芤", "大"]], "8920": ["病机", "脉形细数，细为阴血亏少、脉道不充，数为阴火内动、虚热鼓脉。原文谓阳络频伤、咳嗽咽痛、神倦少纳，乃积损成痨，阴火已冲之象。阴亏于下则细，火升于上则数，故脉细数正合虚劳阴火内炽、肺金受刑之机，主痨瘵虚损之候。", ["细", "数"]], "8921": ["治法", "此段仅载六味合生脉加百合方药，未出脉象，属治法范畴。六味丸滋肾填阴，生脉散益气敛阴，加百合润肺清金，合而观之，当为针对上段脉形细数、阴火冲肺之痨损而设，示滋阴降火、保肺生津之法，非论脉也。", []], "8922": ["预后", "脉形细数，细主阴精亏耗，数主阴火上升。原文谓漏疡日久，阴气下泄，阴火上升，肺金仍受其刑，口舌干燥，乃一损损于下、自下损及于上之形。细数之脉正应阴泄火升，故断其未有艾也，欲卜旋元吉而未许稳成，属预后难安之候。", ["细", "数"]], "8923": ["病机", "脉形弦紧带数，弦紧主寒邪束肺、气机不利，数则寒郁化热、内热渐生。原文谓形寒伤肺，传入大肠，咳嗽于上，外疡于下，久而不愈，咽烁嗌干，所谓一损损于肺。弦紧应形寒伤肺，数应咽干内热，故脉主肺损传变、寒郁化热之病机。", ["弦", "紧", "数"]], "8924": ["预后", "脉弦而数，弦主虚劳气机郁滞、脏气不和，数主阴亏内热。原文述时病中咳嗽失血经年未愈，加寒热盗汗，肌肉暗削，积虚成损。弦数并见而形肉日削，是虚损已深、阴火内炽之征，故恐至积损成劳，属预后不良之候。", ["弦", "数"]], "8925": ["病机", "脉形涩数，涩主血少气滞、脉络不畅，数主内热。原文谓咳嗽四载未痊，轻则生痰，重则动血，胸痛口干，是肺病也。涩应痰瘀阻络、血行不畅，数应肺热内蒸，故脉涩数主肺病痰热动血、久延成损之机，不宜再延。", ["涩", "数"]], "8926": ["病机", "脉数而右中按弦大、左沉按细急。细急者阴伤也，弦大者伏邪也；阴伤则热，伏邪化热亦然，故至数见数。原文述咯血、喉间黏痰、面赤火升、口干津不到咽，乃伏邪化热伤阴、薰蒸于上，阳络重叠受伤，非阴虚自内而生之弱症，故以清热为主。", ["数", "弦", "大", "细"]], "8927": ["预后", "脉形细数，细为阴血亏虚、脉道不充，数为虚热内蒸。原文谓咳伤血络，咳久不除，积虚成损，积损成劳，内热蒸蒸，神昏言微，不耐炎蒸，已露一斑。细数之脉与神昏言微并见，是阴竭热炽、损劳已成之象，故嘱速退林下，扶过三伏再商，预后堪忧。", ["细", "数"]], "8928": ["病机", "脉形弦细，弦为风动之象，细乃阴亏之征。患者咳嗽半载、寒热经月，苔白口腻、痰不畅出，显系阴虚受风，久而不化，又感暑邪，病情加剧。弦细脉反映阴虚风扰、暑热内蕴之病机，故原文谓“伤风成劳，伤暑成瘵”，劳瘵之根难拔，阳络新伤更添棘手。", ["弦", "细"]], "8929": ["病机", "脉数右部涩小，左太浮弦。数主热，涩小为阴亏血少，浮弦乃风阳上扰。咳嗽两月，上伤阳络，兼结肿肛门、便难口燥，显系阴亏之体不耐燥气，肺气自戕传及于肠。脉数涩小示阴亏燥热内结，浮弦示风阳未靖，极易成损，故嘱慎食色。", ["数", "涩", "小", "浮"]], "8930": ["病机", "左关脉弦虽当令，然过大过急，为肝阳内旺、肾水暗虚之象。弦大急者，肝木失柔、阳亢无制，水不涵木则肾阴亏虚。原文谓“肝阳内旺，肾水暗虚”，故于温升清降并行之中，更合养肝之法，以柔肝潜阳、滋水涵木。", ["弦", "大", "急"]], "8931": ["病机", "脉息细小，为元阳不足、肺本虚寒之征。咳嗽哮喘窃发，脘腹胀满、皮肤浮肿、四肢逆冷、舌苔白腻，皆阳虚寒饮内停、气化不利所致。细小微弱之脉示阳气衰微，外不耐风邪，内不耐浊气，交相为患，故原文恐其“塞厥而败”，病机重在阳虚寒凝。", ["细", "小"]], "8932": ["病机", "右脉滑大，滑主痰盛，大主邪实。形寒饮冷伤肺，所贮之痰因此而动，动则呀呷有声、卧难著枕，哮喘频作。原文谓“已昭肾气下虚，不独肺病而已”，然现在右脉滑大，标病为急，痰浊壅盛于肺，故宜先治其标，化痰降逆。", ["滑", "大"]], "8933": ["病机", "脉静而细弦，静为不发之时，细弦示元阳不足、肝木失柔。肺为娇脏，伤于悲哀发散，清肃失司，木寡于畏，怒则为哮，寒则亦发。不发时脉静细弦，说明病本在阳虚肝郁，痰饮内伏，故原文谓“元阳不足，非补不可，非温亦不可”，当温补元阳以固本。", ["细", "弦"]], "8934": ["治法", "本段纯列方药，未涉脉象。金水六君、生脉、牛膝、牡蛎、胡桃肉、杏仁，合金匮肾气丸、金水六君丸，清晨以青铅煎汤送下。此乃补肾纳气、化痰平喘、金水相生之法，针对肾虚痰喘之病机，属治法范畴，故脉象要素为空。", []], "8935": ["病机", "脉形小数，数为热，小示阴分不足。哮喘时发，胸闷咳逆，痰带红色、口中气秽、肩背酸痛，显系肺胃伏热在里，蒸开毛窍，容易招风。现哮止二日，痰黏且黄尚从咳出，脉小数正合伏热内蕴、阴伤痰热之机，故不能不以清法，清肺胃伏热。", ["小", "数"]], "8936": ["病机", "脉弦滑，弦主痰饮、滑主痰湿，正合原文“肺胃两经都被痰所贮”。伏痰招风则哮喘呀呷、卧难著枕，痰阻气机则呼吸短气、痰声不利。弦滑为痰浊内盛之象，非虚非寒，故以导涤法祛其痰贮，脉症相应。", ["弦", "滑"]], "8937": ["病机", "两手脉小，小为气虚，原文责其“肺气久虚，元府不闭，风邪得而袭之”。金实金破皆无声，此属金破，虚为本、实为标。脉小示肺气不足、卫外不固，故风邪易袭而声不外扬，虚中夹实之候。", ["小"]], "8938": ["病机", "脉小而滑，原文自释“滑则为痰，小则为虚”。语声喑喑不彻为心膈间病，肺病则次指无力。小示肺虚，滑示贮痰，肺虚则易贮痰，虚为本、痰为标，与“肺既虚矣，自易贮痰”相合。", ["小", "滑"]], "8939": ["预后", "胸痹心痛彻背，久而不化，又值燥气加临，咳嗽咽干、痰内带红。脉形细小，细为阴血不足、小为正气虚衰，正虚邪恋而燥伤肺络，故原文叹“理之不易”，示病情缠绵、预后难期。", ["细", "小"]], "8940": ["病机", "脉左弦甚，左关属肝，弦主肝风。胸痛彻背、呕吐厥逆，原文断为“中阳不旷，而肝风载痰上逆”。中阳不振则痰饮内停，肝风挟痰上扰，故脉左弦甚，弦为风痰上逆之应。", ["弦"]], "8941": ["病机", "胸痹初愈而脉形弦滑，舌苔糙浊。弦主饮、滑主痰，糙浊苔示湿浊未化。原文谓“脾胃阳虚，湿痰内阻”，阳虚则运化失职，湿痰留滞，脉弦滑正是痰湿内阻之象，虽初愈而病根未除。", ["弦", "滑"]], "8942": ["病机", "脉虚而弦，虚为阳气不足，弦主饮邪。背痛彻胸、胸痛彻背，原文慨“其中之阳气安在哉”，白苔满布、小溲短赤、气逆为噫，皆湿浊郁而不化之征。阳虚为本，湿浊为标，虚弦并见，正虚邪滞。", ["虚", "弦"]], "8943": ["病机", "胸脘作痛延及背胁，舌苔满布，脉象细弦。细为阳虚不足，弦主寒饮凝结。原文谓“阳虚不旷，湿邪寒气凝结于中，无从化解”，阳虚则寒湿内凝，脉细弦正合虚寒夹饮之病机，故从胸痹例治。", ["细", "弦"]], "8944": ["病机", "脉息小弦，弦主气郁痰阻，小示正气不足。动则气逆从胸膺逆入两肩作胀作酸，舌苔满白，乃胸阳不旷、湿痰阻气之征。痰湿内阻，气机升降失司，故气逆上冲；阳气不布，故胀酸并见。脉小弦正合湿痰阻气、阳郁不伸之病机。", ["弦", "小"]], "8945": ["预后", "脉形小数，小为病退，数为余邪，此以脉测病情进退。咳嗽虽轻尚未了了，说明邪势已衰而余邪未清。数脉主余热未净，小脉示正虚邪退，故治法补阴之中寓以消法，既扶正又清余邪，脉象与治法相应。", ["小", "数"]], "8946": ["病机", "原文未识脉名，仅言不寐由阳跷脉满使然。阳跷主一身左右之阳，跷脉满则阳气不得入于阴，阴阳失交，故目不瞑。此段以跷脉病理解释不寐病机，属病机范畴，非凭脉断病，故脉象要素为空。", []], "8947": ["病机", "左寸脉沉，心气下郁；右关脉弦，湿气内阻。一阻一郁，皆归于胃，胃欲和而不得和，故卧不安。沉主郁滞，弦主湿阻，脉象直接揭示胃不和之因在于心气郁与湿气阻，非胃本自病，乃他脏累及所致。", ["沉", "弦"]], "8948": ["病机", "原文未识脉名，以阳跷脉满释不寐，然夜间仍有寐时，寐时易惊惕而醒，又属肝经伏热不能藏魂。跷脉满主阳不入阴，肝热伏藏则魂不安舍，二者并见，故不寐而惊惕。此段重在剖析不寐之病机层次，非据脉立论。", []], "8949": ["预后", "血痢日久，溏泄腹胀如鼓，右脉弦滑而数。弦主肝木乘脾，滑主湿浊内壅，数主邪热未清。饮食递减、神情困倦示正气已衰，脐已平者防突，乃脾虚气陷、水湿泛滥之危候，脉象与症候合参，预后堪忧。", ["弦", "滑", "数"]], "8950": ["病机", "溏泄稍和而满痛时作，脉形弦滑，左亦太硬。弦为肝旺，滑为湿滞，左脉太硬示肝木偏亢。三虫共食一器，且被肝木所乘，说明虫积与肝木乘脾并见，脉弦滑正合木旺湿滞、虫扰中焦之病机。", ["弦", "滑"]], "8951": ["病机", "肝脉一和，腹痛自止，是肝木稍平之象。然右脉弦滑，腹形硬满，脐突溺短，大便还溏，所患之邪正属不少。弦滑主湿浊壅盛、肝木未驯，右脉候脾，弦滑见于右关，示脾湿肝乘，邪势仍盛，未可轻言向愈。", ["弦", "滑"]], "8952": ["病机", "脉形弦数，弦主肝郁湿滞，数主湿热内蒸。酒湿积二十余年，曾衄血、患黄疸，现单腹胀、二便违和、口干苦，皆湿热壅结肝脾、气机不畅之象。脐虽外突而食尚加餐，胃气未败，故可议下夺之法，然湿热深痼，理之棘手。", ["弦", "数"]], "8953": ["病机", "左脉多弦，左关候肝，弦为肝郁湿热未清之征。土郁夺之后腹胀虽平、小便已长，然尚兼黄色、鼻衄易流，显系肝经湿热余邪留恋，易乘虚传入中土而致反复。脉弦与衄、黄并见，正合肝湿热未净之机。", ["弦"]], "8954": ["预后", "血脱气亦脱，气不运化湿邪，故大腹胀满日久、脐突筋露，脉小色萎，为正虚邪盛、气血衰少之象。脉小示元气亏乏，色萎示营血不荣。原文谓一加喘息便不能下问，是脾肺气败、肾不纳气之危候，故列预后。", ["小"]], "8955": ["病机", "面肿曰风，风邪自肺传脾，致一身胀满、咳嗽气塞、溲短肢冷。脉小左浮右沉：左浮为风邪在表未解，右沉为脾肺气滞水停，脉小示正气已伤。风邪入脾、水湿不化，故恐喘塞而败，病机在肺脾受邪、气水交阻。", ["小", "浮", "沉"]], "8956": ["病机", "脉形弦细，弦主水湿气滞，细主阳气内亏。风湿余邪未清，元气未充，季夏腹胀至上下浮肿、舌苔满白、小水不长，皆阳气不化、湿邪内停之征。原文以昭阳气内亏，法当温化，脉弦细正合虚寒湿滞之机。", ["弦", "细"]], "8957": ["病机", "男子自下肿上为逆，湿邪无路可出，外气交结，故苔白口干、脉弦不能食。弦为气结湿滞、肝脾不运之象，气结则纳呆，湿阻则苔白。幸未气喘，说明病尚在脾胃气分而未及肺肾，然逆肿之势已见，病机重在湿气交结、升降失司。", ["弦"]], "8958": ["病机", "右脉软弱主脾经不足、湿气有余，左关带弦主肝气内逆。因于气为肿，气有虚实，此属脾虚湿盛兼肝逆风触。脉软弱势中气不足，弦为肝郁，脾虚不能运湿、肝逆乘土，故肿由气作，病机在脾虚肝逆、湿气内停。", ["软", "弱", "弦"]], "8959": ["预后", "脉息沉弦，沉主里、主水气内停，弦主饮邪与气机郁滞。咳喘于前、浮肿于后，病经一载，肺失清肃、脾失健运，痰湿上犯下流，漫无向愈之期。沉弦之脉与痰湿痼结、肺脾两伤相应，故原文叹为非所宜，属预后不良之候。", ["沉", "弦"]], "8960": ["病机", "脉形弦细，弦主风邪，细主湿滞正虚。原文谓风邪夹湿、脾肺两伤，面部浮肿延及周身、胀满咳嗽、寒热气逆不得卧，皆风邪外袭、湿困脾肺、气机壅塞之象。脐已外突，示水湿泛滥、正气不支，故理之棘手。", ["弦", "细"]], "8961": ["病机", "脉形细小，细主正虚，小主气血不足。原文述邪气填满脘中、正虚不克消化，故一饮一食一汤一药无一舒者；口干苦、溺短、咳嗽气短、四肢逆冷，皆脾阳不振、湿浊内壅、正虚邪实之候。筋露脐突，示病深难治。", ["细", "小"]], "8962": ["病机", "脉来冲急，冲主气逆上冲，急主邪势急迫。原文谓风邪脱入湿中，风性急疾与湿相合，故脉见冲急；大便溏泄、浮肿、寒热头痛，乃风湿内侵、脾运失职、表邪未解之象，势非轻者，示邪盛正伤。", ["急"]], "8963": ["病机", "原文未识脉名，仅言脉冲下体不温。太阴腹满，不惟寒湿有余，而且真阳不足，故脉冲而阳气不能温煦下体；干不能饮、妨食气满，皆脾阳衰微、寒湿内停之候。其势颇险，未便以寒热余邪为主治，示当顾护真阳。", []], "8964": ["病机", "右脉濡主湿，左部弦主风。原文谓阂疟之风留之于湿，曾经肿胀，今春又发，小有寒热、自汗不渴，皆风湿留恋、表气不和之象。既无便溺阳格，又无饮食速和，其治在表，防脱，示正虚邪恋、当先固表。", ["濡", "弦"]], "8965": ["病机", "脉弦带浮，浮主风邪在表，弦主水湿内停。原文谓面肿曰风、足胫肿曰水，风邪亲上、湿邪亲下，故面跗俱肿；白苔带黄、溺黄不多、气短不长，示风多于水、湿郁化热。不喘乃吉，示肺气未绝。", ["弦", "浮"]], "8966": ["病机", "脉息沉微，沉主里、微主阳虚；颈脉动乃水气上冲之征。原文述气上冲胸、时咳、阴股间寒、足胫肿、目下肿、腹大、卧不能正偃、小便不利，皆脾肺肾三经阳气内虚、不能运化湿邪，垂成水肿。恐其喘甚，示水邪犯肺之危。", ["动", "沉", "微"]], "8967": ["病机", "右脉弦涩，弦主湿郁，涩主阴分已虚；左关独浮过于弦，示湿郁化热、肝气偏亢。原文述湿邪从阴侵下，失治延及中焦，大腹胀满、脐突筋露、饮食作胀、小水短赤，皆湿郁为热、阴分已虚之候。近增咳嗽，防喘，示病势深入。", ["弦", "涩", "浮"]], "8968": ["病机", "脉形细小，为阴虚寒饮内伏之象。浮肿咳嗽、呕吐恶心、二便失调、苔白不渴、足部硬冷，皆阳虚不能化饮、寒饮上逆所致。细小之脉主正气不足、阴寒内盛，故断为阴虚寒饮使然，且虑其喘甚而败，示病机重在虚寒夹饮。", ["细", "小"]], "8969": ["病机", "脉息浮弦，浮主风邪在表，弦主饮邪内停。浮肿自上而下、自下而中，咳嗽无汗气短、胸痞妨食，皆风邪夹湿由外而之内之征。苔白便溏溺短，湿象明显；感邪已欲为热，故防喘，示风湿郁表、渐有化热之势。", ["浮", "弦"]], "8970": ["病机", "脉息沉弦，沉主里、弦主饮主痛。胸痞便溏似渐和，而中宫胀满、上下浮肿、苔白气短溺少口干，脉沉弦说明水湿内停、气机壅滞于里，非表邪未尽。防食恶风等症，正属不轻，示里湿未化、脾运不健之病机。", ["沉", "弦"]], "8971": ["病机", "脉小为湿郁正虚，左关独见浮弦，为风引动于上焦。苔白口腻、呕逆恶心、溺短便坚、耳鸣，皆湿郁化热、从下延及上焦之象。脉小示正气不足，浮弦示风阳上扰，故容易增喘，不能不虑，病机重在湿郁夹风、上焦受累。", ["小", "浮", "弦"]], "8972": ["病机", "脉浮已和，独形弦象，说明表邪渐解而饮湿未化。呕逆虽止，浮肿不消，弦脉主饮主气机不畅，水湿仍停。必得小便清长，则上甚之湿热或者下趋，示病机关键在膀胱气化不利、湿无出路，弦象即水饮内停之反映。", ["浮", "弦"]], "8973": ["病机", "脉弦中见数，弦主饮主气滞，数主热。小便不长，膀胱气化失其常度，上之湿难以下趋，徒增为热，故口稍干、龈带疼。脉弦数正合湿郁化热、气化不利之机，说明病机由湿阻渐转为湿热内蕴，小便不通是枢机所在。", ["弦", "数"]], "8974": ["病机", "脉形郁小，郁主气机不畅，小主正虚。先肿后咳，其治在脾，脾虚不能制湿反生痰，累及肺金为咳；形寒饮冷更伤肺气，肿满按之作痛、咳逆薄痰、饮食递减、溺短便溏，皆脾肺两虚、痰湿内壅之征。脉郁小示虚处有益、实虚无补，故虑清肃不行、健运失常而气喘败。", ["郁", "小"]], "8975": ["病机", "脉形弦数，弦主风主饮，数主热。面部之肿延及中下两焦，溺色短赤、舌苔黄浊、口味干甜，皆湿热内蕴之象。风邪袭入湿热之中，脉弦数正合风与湿热相搏之机。不喘乃吉，说明病机重点在湿热壅盛、风邪外袭，尚未上逆犯肺。", ["弦", "数"]], "8976": ["病机", "脉形沉小，沉主里、小主虚，与胸脘痞塞、浮肿、咳逆少痰、溲少并见，说明痰食湿交结不解，气机壅塞于里，水湿不化。原文断为“痰食湿交结不解，其气易塞咽喉”，故脉沉小正是邪结于里、正气受困之象，恐其喘厥而败，主病机而非单纯主病。", ["沉", "小"]], "8977": ["病机", "左关候筋，脉息弦急，弦主风、急主拘急，与四肢游行作痛、指臂强而难举相应。原文谓“风寒湿三气杂至，合而为痹”，风气胜者为行痹，春遇为筋痹，风邪客于筋脉故脉弦急，说明因风而成筋痹之病机。", ["弦", "急"]], "8978": ["病机", "左脉芤数而浮，芤主血虚，浮主风邪外袭，数与虚热相应。原文谓“血虚招风所致”，右肩臑酸痛延及臂肩，右属肺，久贮之痰从而和之为患。脉芤数浮正合血虚风入、痰随气动之机，故主病机兼症。", ["芤", "数", "浮"]], "8979": ["病机", "脉象弦数，弦主痛、主筋脉不舒，数主热，与右肢酸痛、筋脉不舒渐及于左、一手偏热、口中干苦相应。原文谓疟中风湿痰邪窜入经络，此名痹症，弦数说明邪郁经络化热、气血不畅之病机。", ["弦", "数"]], "8980": ["病机", "六脉细小，左关独浮大。细小主阴血大伤，浮大见于左关，为血不养筋、虚阳浮动之象。原文谓遗精日久、曾患痎疟、心力俱劳，阴血大伤，经筋为患漫无愈期，故脉细小而左关独浮大，说明血虚筋失所养之病机。", ["细", "小", "浮", "大"]], "8981": ["病机", "脉息浮弦，浮主风邪在表，弦主筋脉拘急，与痛痹偏左、痿而不举相应。原文谓“血虚之体，风邪乘此而入”，血虚则筋脉失养，风邪乘虚客于经络，故脉浮弦，说明血虚风入、痹阻不通之病机。", ["浮", "弦"]], "8982": ["病机", "脉形沉细而弦，沉主里、细主虚、弦主痛主饮，与股膝红肿作痛、膝骨日大而重、伸难屈相应。原文谓风寒湿三气杂至合而为痹，久而不愈欲成鹤膝风，沉细弦说明邪痹深入筋骨、气血壅滞而正虚之病机。", ["沉", "细", "弦"]], "8983": ["病机", "脉形细小，左关独弦数，右寸独滑。细小主虚，弦数主邪郁化热，滑主痰湿。原文谓肺肾先受风寒湿三气，郁蒸为热，故鼻流清涕、小溲常黄；身体偏侧肌肉暗削、行步无力，虚态百出，说明因病致虚、正不胜邪之病机，恐难支持。", ["细", "小", "弦", "数"]], "8984": ["病机", "原文谓湿热不攘致大筋软短为拘，脉弦濡小带数意，乃湿胜于热之象。濡小主湿，弦主筋急拘挛，数示热郁。湿性下先受之，故溺不变、口不渴、四肢酸软、经筋酸疼，甚则下病及上。脉证合参，知湿热独在大筋，湿重于热，故以羌活胜湿汤为第一要著。", ["弦", "濡", "小", "数"]], "8985": ["预后", "三阴大疟日久，三阴之阳衰而不旺，不能托邪外出，反被邪乘虚入，虚者益虚。脉微无神，正是阳气衰微、无阳则阴无以化之征，故见饮食大减、肌肉暗削、身热无力、大腹软满、足跗浮肿。际冬至阳生之候而脉微无神，阳气难复，故曰危乎危乎，属预后不良之候。", ["微"]], "8986": ["预后", "但热不寒之疟，渴喜热饮、苔腻节疼，显系邪盛；而脉微自汗，则阳气已虚，不能固表。脉微为阳虚之象，自汗为卫外不固，邪盛而正虚，故原文断为邪盛阳虚。阳虚不能胜邪，恐不克支持，进而增昏喘之变，属预后堪忧之候。", ["微"]], "8987": ["病机", "三阴疟后小溲见红、兼白浊，复寒热似疟、日夜分争，左胁疟母升逆，口干脉弦。弦为肝脉，主留邪于肝脾两经，疟母乘势升逆。脉弦与胁下痞块、寒热分争相应，示留邪未净、肝脾受病，故原文谓不宜再厥，当防厥逆之变。", ["弦"]], "8988": ["病机", "间疟变为三日一作，寒重热轻，脘腹胀闷，口鼻干燥而不发渴，脉形细弦，舌苔薄白。细弦为暑湿内伏、燥气加临之象：细主湿郁阴伤，弦主气机不畅。寒重热轻、脘胀、苔白示湿伏于内；口鼻干燥不渴，乃燥气外加之征，脉证相合，故断为暑湿内伏兼燥。", ["细", "弦"]], "8989": ["病机", "疟属脾寒，阴寒之气聚于脾经，发于阳明，寒热间日而作。脉息濡小之中隐隐带弦，濡小主阳虚湿盛，隐弦主阴寒内聚、脾经受病。面黄带白、汗多、溲夜多、少纳少寐、嗳气，皆阳虚阴寒不化之证。际冬至阳生而阳虚无以消阴，故疟漫无愈期，急须温化。", ["濡", "小", "弦"]], "8990": ["病机", "三阴大疟名曰痎疟，疟老于三阴之界，漫无愈期。近来自觉神呆、形痞硬、苔白脉迟，迟为阳气渐虚之象。阳虚不能化疟邪，反致疟邪欲成臌，故见神呆、痞硬。脉迟与苔白、神呆、痞硬相应，示脾阳大虚、阴寒凝聚，故急须大补脾阳，以防成臌。", ["迟"]], "8991": ["病机", "痎疟日久，黏汗头眩，脉形细而隐弦。细为阴血不足、正气已虚，隐弦乃疟邪久留、肝脾未和之象。黏汗头眩示虚阳上扰、卫外不固。原文明言此虚也，不可以作实治，故脉细隐弦当从虚论，不可因弦而攻伐，示人久疟正虚、治当扶正之意。", ["细", "弦"]], "8992": ["病机", "脉形弦细，弦主邪郁少阳、疟邪未解，细主阳气内伤、气血不足。原文谓\"痎疟仍然，隐癖僭逆中宫\"，疟邪与癖块踞于中焦，故脉见弦细；舌苔干腻、暑邪正甚，说明暑湿未化而阳气已伤，正虚邪恋之机，呕恶虽止而疟与癖未除。", ["弦", "细"]], "8993": ["病机", "脉细弦数，细为阴血内亏，弦为肝经留邪，数为邪热内扰。原文明言\"阴血内亏，留邪于肝\"，寒热如疟久而不已，邪伏肝络，阴血耗伤，故见口干苦、少寐少纳、咳逆。弦数并见，示邪热未清而正阴已损，属虚实夹杂之候。", ["细", "弦", "数"]], "8994": ["病机", "右脉弦细，左部模糊，右主气、左主血。痎疟日久，弦为邪踞少阳，细为气血亏耗；左部模糊则阴血元气俱受损。原文谓\"元阳元气，都被邪侵\"，正虚而邪深，脉象由实转虚，提示久疟伤正、本元受戕之病机。", ["弦", "细"]], "8995": ["病机", "右脉小为气分不足，左脉弦数为肝经邪热未清。原文断为\"气阴两伤\"，症见口干舌红、神疲盗汗、少纳言微，皆气阴耗损之征；弦数示疟邪尚留。脉症合参，属久疟正虚邪恋，故治法\"养中寓化\"，扶正与化邪并行。", ["小", "弦", "数"]], "8996": ["预后", "脉形弦细，弦为阴经之邪、细为阳气不足，正合\"三疟皆生于阴，无阳以化\"之说，故寒重热轻、汗多不渴。右尺上冲甚锐，尺主下焦肾命，冲锐示本元虚而气逆，原文忧\"枝叶未害，本实先拔\"，脉象反映邪伏阴经、元阳亏虚，预后堪虑。", ["弦", "细"]], "8997": ["预后", "脉微为阳气大虚，自汗为卫阳不固。但热不寒之疟而渴喜热饮、苔腻节疼，是邪盛于内；脉微自汗则阳衰于外。原文断\"邪盛阳虚\"，并虑\"不克支持，而增昏喘\"，脉微正是阳虚欲脱之兆，故列于预后险候。", ["微"]], "8998": ["病机", "脉息浮弦，浮主外感风暑之邪在表，弦主少阳枢机不利、疟邪往来。原文谓\"湿热召暑，风亦随之\"，寒热间日而作、苔白头痛口干、恶心多汗，皆暑风外袭、湿热内蕴之象，浮弦之脉正应外邪未解、邪正交争于半表半里。", ["浮", "弦"]], "8999": ["病机", "脉息浮弦，浮为暑风外感，弦为邪郁少阳、疟发间日。原文谓\"暑风外感使然\"，症见头痛腰痛、寒热转疟、苔白胸痞、便溏溺黄、渴喜热饮，皆外受暑风、内蕴湿滞之候，浮弦之脉示表邪未罢而枢机不利。", ["浮", "弦"]], "9000": ["病机", "原文谓痎疟生于阴，肝脾肾三经，脾肾之脉犹可，独左关肝部“弦而且浮”。弦为肝脉，浮主外感，风喜伤肝，肝为风脏，故弦浮并见说明外感之风留于肝部，非单纯内伤。此脉主痎疟兼挟外风之病机，与寒热往来、发作有时等疟症相应。", ["弦", "浮"]], "9001": ["病机", "脉形弦细，弦主疟、主肝，细主湿、主虚。原文谓寒热往来无定时，已发六五发，兼痞闷、舌苔薄白、饮食少、咳嗽、口淡溺黄，断为“暑风湿热，归并三阴”。弦细正示邪伏三阴而正气已伤，湿浊内阻，故主痎疟缠绵、脾运不健之病机。", ["弦", "细"]], "9002": ["预后", "原文述三阴痎疟，音烁于上、腹膨于中、便溏于下，三焦俱病，舌苔冷白、四肢厥冷，而“脉息全无”。脉息全无是阳气欲绝、有阴无阳之象，故断为阳分比阴分更亏，病势危笃。虽勉拟生阳一法，然恐鞭长莫及，此段主旨在于判断预后凶险。", []], "9003": ["预后", "原文“一阳来复，脉尚模糊”，指阳气初回而脉象仍模糊不清。脉模糊说明胃气未振、阳气微弱，虽无暴脱暴出之忧，却少微续渐复之喜，故曰“不足恃也”。此段以脉象模糊判断阳气来复不足、病情尚难恃为安，属预后分析。", []], "9004": ["治法", "原文仅载“生脉散煎送来复丹”，脉象写作脉散。散脉主气散不收、元气耗散，故用生脉散敛补气阴，配来复丹温运阳气、交通阴阳。此段以脉散示正气涣散之机，所载为针对该病机的治法方药，故归治法。", ["散"]], "9005": ["病机", "右脉细软，左太弦急。右主脾，细软示脾虚湿盛；左主肝肾，弦急示肝肾不足而肝气偏亢。原文直断“脾湿有余，肝肾不足”，脉象左右对举正合三阴疟本虚标实之机，与疟发、体倦等症相应。", ["细", "软", "弦", "急"]], "9006": ["病机", "脉弱体酸，胸闷少纳。弱脉主元气内虚，正不胜邪，故原文谓“元气内虚，无力化邪之候”。痎疟变为日作，邪从外向，然脉不浮紧而反弱，说明正虚不能托邪，只宜养化，不可峻攻。此段以脉弱论证虚邪恋之病机。", ["弱"]], "9007": ["病机", "脉形濡小，濡主湿、主暑，小主气血不足。原文述疟发先酸疼、继小热、后寒大作、汗出渐解、苔白不渴，断为“先患风湿，后患暑邪，气血同病”。濡小正示湿暑内蕴而气血两伤，故主风湿暑邪夹杂、气血同病之病机。", ["濡", "小"]], "9008": ["病机", "脉形弦数，弦主风邪、疟疾，数主热。原文谓痎疟日久，瘾疹外发瘙痒、咳嗽痰多、溺黄，乃风邪暑湿欲从三阴传出肺经而不能畅达。脉弦数正示邪郁化热、欲透未透之机，故主风暑湿郁而化热、肺气不宣之病机。", ["弦", "数"]], "9009": ["病机", "右脉小、左脉浮，浮主风邪在表，小示湿邪内阻、正气不畅。原文谓阴经受湿招风，足肿、脘痛、鼻衄、溺黄，风温之邪郁蒸为热布满三焦而不能从营卫畅达。脉浮为邪争于营卫，小为湿重于风、气机不利，故主湿重风轻、三焦郁滞之病机。", ["小", "浮"]], "9010": ["病机", "脉形弦数，弦主疟邪留连，数主热盛。原文谓热重于寒、口干头痛、苔白舌红、干咳少纳，阴血内亏不能速化，留邪之兆。脉弦数为邪热未清，阴血亏虚则邪难速解，故主热重阴亏、留邪不去之病机，与干咳少纳相应。", ["弦", "数"]], "9011": ["病机", "脉形细小之中而带隐弦，细小主阴血不足、正气无力，隐弦示暑湿热三气余邪尚羁三阴。原文谓得汗则寒气先消，而暑湿热尚在三阴之界无力以消。脉细小为正虚，隐弦为邪恋，故主正虚邪恋、三阴余邪未清之病机。", ["细", "小", "弦"]], "9012": ["病机", "脉弦而数，弦主疟、主三阴受邪，数主热。原文谓三阴深受风寒湿，寒热往来止而复作、口不渴、苔黄浊、四肢微浮。脉弦数为风寒湿郁于三阴、邪正相争之象，故主三阴疟邪留连、湿郁化热之病机，治当扶正达邪。", ["弦", "数"]], "9013": ["病机", "脉细弦数，细主血分本亏，弦主少阳，数主热。原文谓寒热往来、口干苦、苔薄白，为少阳见证；又言络伤之体血分本亏，营虚不能作汗。脉细弦数正合少阳邪郁兼阴血不足，故主少阳不和、营虚血亏之病机，咳嗽不过兼治。", ["细", "弦", "数"]], "9014": ["病机", "脉形弦细，弦主疟邪、主肝胆，细主阴血不足。原文谓三阴疟邪曾归腹而肿，已结疟母，邪窃踞肝胆，身热又如疟状，苔白不渴。脉弦细示疟母结于肝胆、阴分受耗，故主疟母内结、肝胆邪踞之病机，治宜温化。", ["弦", "细"]], "9015": ["病机", "脉弦而小，弦主阴结、主痛，小主阳虚气弱。原文谓脐下旁有内结按之硬、动之隐痛、苔白且滑，明言阴结阳虚所致。脉弦小正合阴寒内结、阳气不足之象，故主阴结阳虚、寒凝内结之病机，与按硬隐痛、苔白滑相应。", ["弦", "小"]], "9016": ["病机", "脉形细小，为营卫分争日久、邪少虚多之象。疟邪已移出阳经，寒热虽止而营卫未和，舌苔嫩黄、脘腹不舒、小溲短赤、夜寐少安、咳嗽吐痰、肢体无力，皆正虚邪恋之候。脉细小说明气血不足、正气已亏，故断为邪少虚多，治当扶正为先，积邪自去。", ["细", "小"]], "9017": ["病机", "脉弦而数，弦主邪郁少阳、数主热盛，合寒热往来、口中干苦、舌色光红，知伏暑化燥而发，阴气早伤。暑邪内伏化燥，耗伤阴液，故脉数而舌光红；邪郁少阳枢机，故寒热往来、脉弦。治欲提出其邪，势必兼顾其阴，不可纯用升散。", ["弦", "数"]], "9018": ["病机", "脉象弦数，弦为少阳邪郁、数为暑热内盛，与寒热往来、口中干苦相应，舌苔白腻则兼湿浊未化，故断为伏暑见症。久咳且嗽之体，肺气本虚，暑邪乘虚而伏，脉弦数正示邪郁热盛。治宜兼理，既解伏暑，又顾久咳之体。", ["弦", "数"]], "9019": ["病机", "左脉细小而带隐弦，右部弦急而滑。细小为少阴虚、精遗之征；隐弦应厥阴虚实各半、寒热往来、胁痛；右弦急而滑主太阴独实、面色黄滞，兼浮肿之邪留于脘腹。三阴之邪孰多孰少，脉象分明，故治疟先重清脾，兼和肝肾。", ["细", "小", "弦", "急"]], "9020": ["预后", "脉息芤弦，芤主中空血虚、弦主木旺邪滞。疟痢并行十六发，又加泄利日夜四五十行，元气更乏；六旬以外，饮食大减，痰涎上泛、呕哕恶心，神昏遗溺、气坠肛门，火升面赤少寐，皆脾胃营卫无一不虚。脉芤弦示正虚邪滞，故曰大非所宜，预后堪忧。", ["芤", "弦"]], "9021": ["病机", "脉息芤弦，芤为中空失血、弦为木旺克脾。心肝所藏之血不能统于脾，渗入下焦，鲜紫之血从粪前后而出，久则面容黑瘦、饮食大减。芤弦并见，示血虚而肝脾失调，将有浮喘之形，乃阴血亏耗、气不归元之兆，故慎之。", ["芤", "弦"]], "9022": ["预后", "前诊芤弦之革脉，今稍和缓，说明药后脉气渐复，所患诸症自属安适，前方对证无疑。革脉本主虚寒失血，稍和则虚损有渐复之机。所嫌小溲浑浊、内痔作痛，属余邪湿热未清，故须兼理，不可因脉和而遽停药。", ["芤", "弦", "革"]], "9023": ["病机", "温通瘀血后革脉已和，独形芤象，说明瘀滞渐化而阴血仍虚。腹痛已除，尚下渗血、痔痛溺浊，饮食虽增而口舌干痛，乃阴虚留热、暗伤营分可知。芤主中空血虚，革去而芤存，正示瘀去正虚、营阴未复，故仿黑止红之意，养阴清营。", ["芤", "革"]], "9024": ["预后", "脉形芤涩而数，芤主阴血亏虚、脉道失充，涩示血行滞涩、阴络暗伤，数则虚热内生。原文谓脾气虚失统领，血渗肠间日久，阴络暗伤，血从穿处而行，营卫肌肉皮毛筋骨有损无益，饮食减少、言语无神，故归入虚劳重候，属预后不良之象。", ["芤", "涩", "数"]], "9025": ["病机", "左关候肝，脉息虽旺而芤，旺为肝阳偏亢，芤则所藏之血不足、脉道中空。原文谓脾统血、肝藏血，统领失常则所藏者少，故左关旺而芤；大便余带血不已、舌苔黄燥，示血失所藏兼有燥热，法当清养兼施，此脉主肝血亏虚而兼热之病机。", ["芤"]], "9026": ["病机", "左脉大，左候肝肾，大则邪热壅盛、气血涌迫。原文谓气淋带浊、溺后更疼，气淋日久湿热蕴结下焦，左脉大示热势鸱张、血络受灼，故断为将见血之兆，速宜静养以防血淋。此脉主下焦湿热壅盛、迫血妄行之病机。", ["大"]], "9027": ["病机", "脉数主热，左部带大示热郁下焦、阴分受灼。原文谓热郁下焦，血淋久而不已，肾水大亏，心火失济，下入小肠而出之膀胱，故尿中带血。数大之脉正是水亏火旺、热迫血络之征，主肾阴亏虚、心火下移之病机。", ["数", "大"]], "9028": ["病机", "左脉沉数，沉主病在里、属下焦，数主热。原文谓阴亏之体，心火下郁小肠，传入膀胱之府，尿中带血时作时止，小溲不利。阴亏则水不济火，火郁下焦迫血，故脉沉数，主阴虚火郁、热迫膀胱之病机，与尿血、小溲不利相应。", ["沉", "数"]], "9029": ["病机", "脉形沉数，沉示病位在下焦，数示有热。原文谓肾虚乃膀胱受热，尿血成淋，肾虚则气化失司，膀胱受热则血络被灼，故尿血成淋。沉数之脉正合下焦肾虚蕴热之候，主肾虚膀胱湿热、迫血成淋之病机，治宜清养。", ["沉", "数"]], "9030": ["兼症", "脉细而见弦数，细主阴血不足，弦主痛、主气机郁滞，数主有热。原文谓欲便不通、不通而痛，此淋也；干不多饮，必有留热未清，不独下虚。弦数应淋痛与留热，细应下虚，又兼新感咳嗽，故本段以兼症辨析为主，示淋证下虚夹留热之病机。", ["细", "弦", "数"]], "9031": ["主病", "脉象沉数，沉主里、主下焦，数主热。原文谓小便频数而赤，或浑浊，或紫块，此淋症也。赤与紫块示热伤血络、血随尿下，浑浊为湿热下注，沉数之脉正应下焦湿热蕴结，故本段主淋症之诊断，脉沉数主下焦湿热、迫血妄行之病机。", ["沉", "数"]], "9032": ["病机", "脉小为虚，左弦为肝木偏旺。原文言膏淋日久，所下薄少而便时不利、便后隐疼，肢膝不温，是下焦阳气已馁；唇红嗌干又见阴伤内热。脉小左弦正示虚中夹木火，热未全愈而虚日益著，故主虚实夹杂之病机。", ["小", "弦"]], "9033": ["病机", "脉数主热，左弦应肝与肾位。膏淋变为血淋，久而不已，热灼阴络则血随便下。原文断为“肾被热伤”，数脉示热邪未清，弦脉示病位在肝肾，热伤肾阴，络损血溢，故脉数左弦主肾热伤络之病机。", ["数", "弦"]], "9034": ["病机", "脉数主热，苔腻主湿。尿血成块、小溲作痛，是湿热蕴结下焦，灼伤血络，血溢成块；湿热阻滞膀胱，故溺时作痛。原文直言“湿热下注使然”，数脉与苔腻相合，正说明热与湿交蒸于下，主湿热下注之病机。", ["数"]], "9035": ["病机", "左关脉硬，木旺之象；寸部浮急，心火偏亢；右濡数，湿与热并。原文谓水亏木旺，又见小便淋痛如脓、苔白口干、足冷转筋，断为心火湿热下注肾与膀胱。硬、浮急示火木不靖，濡数示湿热内蕴，故主本虚标实、湿热下注之病机。", ["硬", "浮", "急", "濡"]], "9036": ["病机", "左细为阴液不足，右弦主中宫湿郁，俱见数象则湿热内蒸。血淋日久，加以咳嗽时作，口燥苔黄，是湿热充斥上下，阴液受伤。脉细示阴亏，弦数示湿热未清，故主中宫湿热、上下充斥而阴液受损之病机。", ["细", "弦", "数"]], "9037": ["病机", "脉数主热，苔白示湿未化燥。尿血成淋，小便时无血亦疼，是湿热蕴于下焦，血络受伤而气化不利；嗌干为热伤阴津之征。原文断为“湿热伤阴”，数脉应热，苔白应湿，故主湿热久蕴、渐伤阴分之病机。", ["数"]], "9038": ["病机", "脉小而沉，小为阳虚，沉主里、主寒。淋久转为癃闭，少腹硬满，小便肿胀，苔白不渴，是下焦湿热本蕴，又被寒邪外遏，膀胱气化不行。原文称“最为急症”，脉小沉正示阳气被遏、气化不洗，故主寒遏湿热、膀胱气闭之病机。", ["小", "沉"]], "9039": ["病机", "脉形细数，细为阴亏，数主内热。原文引“湿热不攘，大筋软短，小筋弛长”，痿病未痊又尿血、更淋，是湿热久羁而阴分更亏。细数脉正示阴液耗伤而余热未清，故主湿热伤阴、痿淋并见之病机。", ["细", "数"]], "9040": ["病机", "脉弦数，弦为肝经郁滞，数为湿热内蕴。原文谓「肝肾湿热，不留于中，必犯于下」，湿热下注精房，故见膏淋血淋、小便无端而痛。气从少腹左升，正是肝经湿热拢动精房、气机逆上之象，白苔满布亦湿热之征，脉症相合，主湿热下注之淋证。", ["弦", "数"]], "9041": ["病机", "左尺候肾与阴分，脉浮而按之弦数，浮为湿热郁蒸于外，弦数示热郁肝经。原文「湿郁为热，变作沙淋，有如煮海为盐」，湿热煎熬阴液成沙，病经半载，阴分已伤，故按之弦数而阴亏，主湿热沙淋兼阴伤之病机。", ["浮", "弦", "数"]], "9042": ["病机", "脉弦细数，弦主肝经湿热未清，细为阴亏，数为邪火。原文谓「阴虚湿热，膏淋带血带沙」，沙血已愈而膏仍亏内，尚带血沙两意，正合细数示阴分不足、弦数示湿热余邪留恋，故主阴虚湿热未尽、膏淋缠绵之病机，治宜养化。", ["弦", "细", "数"]], "9043": ["病机", "脉反郁小而数，小为阴亏血少，数为邪火内郁。原文「湿热伤精，梦遗不作，变为白浊下行」，浊留海底而红热作疼，兼阴虚湿汗、疮疡外发，舌苔腻白。脉小示正虚，数示湿热邪火，郁而不畅，故主阴虚湿热交阻、正虚邪恋之病机，理之费周旋。", ["小", "数"]], "9044": ["病机", "原文自释「细属阴亏，数为邪火」，热淋变为血淋，热伤阴络则血下，阴液亏耗则脉细，邪火内炽则脉数。细数并见，正是阴亏火旺之象，故主热淋转血淋、阴虚邪火之病机，治以清补为宜，清其邪火、补其阴亏。", ["细", "数"]], "9045": ["病机", "本段未识脉名，纯述病情。疟邪与疔毒窜入大经小络，归并膏淋，邪又流入于肾，肛门前后气盘旋酸痛，袭入于冲，左腿内廉麻木抽痛。病情自上而下，势必自下而上以出之，主邪毒深窜经络、由下透出之病机，非仅化导可解。", []], "9046": ["病机", "脉形沉涩，沉主病在里，涩主血行瘀滞。原文「血因胬肉而瘀，瘀在海底，附在筋经，自幼作疼」，瘀血久留筋经，气血不畅，故脉沉涩。沉涩相合，正示瘀血内结、久病入络之病机，瘀着深痼，故理之不易。", ["沉", "涩"]], "9047": ["预后", "进桃仁承气汤后，海底已能不痛，阴茎尚带痒疼，涩脉渐有和意。涩主瘀血，涩渐和即瘀血渐化之征。原文谓「所瘀之血，消者已多，而其留落者，一时未能扫除」，故主瘀血渐消而未尽的预后判断，治当去瘀生新，仍寓毒药以攻余瘀。", ["涩"]], "9048": ["病机", "脉小左弦，俱见数象，小为气血不足，弦主肝郁，数主热。左弦尤显肝火偏亢，结合淋症膏淋日久，舌苔薄白，可知湿热之邪传入膀胱，肝火窜入其中，故脉见弦数。脉小则示久病正伤，湿热未清而肝火内扰，主淋症湿热夹肝火之病机。", ["小", "弦", "数"]], "9049": ["病机", "脉息微弦，微为阳气衰微，弦主痛、主饮。小便似和而不能畅通，少腹似和而尚硬满，舌苔湿白，皆阳气大虚，无力以通其痹。阳虚则气化不行，水湿内停，故脉微弦而少腹硬满，主阳气虚衰、湿痹不通之病机。", ["弦", "微"]], "9050": ["病机", "脉形带数，数为有热。湿白之苔渐变糙色，所结之邪郁而为热，然阳虚难化，故脉虽数而苔转糙。此乃阳虚湿郁化热之象，数脉示热郁于内，但非实火，乃阳虚不能化湿，湿郁生热所致，主阳虚湿郁化热之病机。", ["数"]], "9051": ["病机", "脉形弦数，弦主肝郁、主痛，数主热。大便已通，瘀血食积虽去，腹之坚者虽软而形尚大，苔嫩黄，口干溺热，小溲通而不利，显系湿热郁结于膀胱。弦数之脉，正是湿热内蕴、肝经郁热之征，主湿热郁结膀胱之病机。", ["弦", "数"]], "9052": ["病机", "左尺之脉浮而不静，昭肾气下虚；关部独大、独弦、独数，舌苔黄燥，乃厥阴肝部湿热之邪助其内火。火动乎中，必摇其精，肝主疏泄，故见胫酸体倦、口苦耳鸣、便坚等症。脉浮主虚，大弦数主肝经湿热火动，主肾虚肝火湿热之病机。", ["浮", "大", "弦", "数"]], "9053": ["病机", "左关之脉大者已小，弦数仍然，尺亦未静。大便畅行，干苦亦愈，示实邪渐去，故脉大者已小；然弦数未除，尺部未静，说明肝经湿热火邪尚未尽清，肾部亦未安。脉由大转小，为邪退正复之象，但弦数仍在，主湿热余邪未清之病机。", ["大", "小", "弦", "数"]], "9054": ["病机", "脉形弦数，数为有火，弦主乎肝，故知肝经有火。肝火不但顺乘中土，而且容易摇精，精虽四日未动，究须小心。弦数并见，明示肝火内炽，木旺克土，且火扰精室，主肝经火旺、乘土摇精之病机。", ["弦", "数"]], "9055": ["病机", "左脉细小，右脉弦数。精浊日久，又梦遗见血，显系精血内亏，故左脉细小；湿热所伤，郁于肝经，故右脉弦数。细小二脉主精血亏虚，弦数主湿热内蕴，左右合参，主精血内亏兼湿热下注之病机。", ["细", "小", "弦", "数"]], "9056": ["病机", "脉形濡小，濡主湿、小主虚，合参舌苔白腻，知湿热内蕴而肾精暗伤；左寸过大，为心火偏旺之象。原文列两端：湿热伤精而动、心火太旺不能下交于肾而肾气下泄，皆以濡小示肾虚为本、湿热与火为标，故治不独填精补髓。", ["濡", "小"]], "9057": ["病机", "脉形细小为阴血不足之征，左关独大独弦则肝木偏旺。原文谓肝主疏泄、肾主封藏，疏泄太过则封藏失职，故梦遗时作、小便余沥，甚则腰背俱痛、足膝无力。细小与左关弦大并见，正是肝肾两伤、木旺失藏之病机，久服寒热温凉而不愈，亦由药未中的。", ["细", "小", "弦"]], "9058": ["病机", "左关候肝，脉息独大独弦，是肝经湿热偏盛之象；余部皆形细小，示肾精亏虚。原文明言肝肾两经都被湿热所伤，以致精房不固，故左关独显弦大而余脉细小。弦大为邪实之征，细小为正虚之应，虚实并见，正合湿热伤精、封藏失职之病机。", ["弦", "大", "细", "小"]], "9059": ["病机", "脉来细数，细为阴分暗虚，数为虚热内起。原文谓精遗三年，阴分暗虚，虚者热从内起，蒸卫则肌肤灼热，郁营则手足心热，故见口干多饮、背脊疼、少腹不和、肢体无力。细数正应阴虚内热之机，病势有加，故虑夏至一阴不生而难救，先化热后补阴封髓。", ["细", "数"]], "9060": ["病机", "脉息不浮不沉，左关一部独见大弦。左关属肝，大弦为肝经火旺之象。原文以瓶水为譬，谓既非水满之覆，又非瓶破之漏，乃肝火摇动其精，如瓶水被外物所激而出，故遗精不由肾虚滑泄，而由肝火扰动，大弦独见于左关正是其据。", ["弦", "大"]], "9061": ["病机", "脉小而沉弦，小示正气不足，沉弦主阴寒内伏、痛结于里。原文述遇风作痛，从胃脘上及于背、旁及于臂，动则作而静可安，经年不愈，因想冷风中必有飞尸遁注之邪附而和之为患。沉弦应寒邪深伏，小应久病正伤，故痛处走注而缠绵。", ["小", "沉", "弦"]], "9062": ["预后", "脉软而头晕且眩，软为正气虚弱之象。原文谓一阴一阳结谓之喉痹，实由阳明湿热薰蒸于上，久则地道渐闭、饮食难下，甚则邪传奇经、带下赤白、气怯神倦，脉软不能支持。脉软正示正气已衰，故断为防脱，属预后危候之判。", ["软"]], "9063": ["预后", "原文未及具体脉象，只言进前方一剂后饮食下咽稍易、夜来得寐、晨起畅吐浊痰，因想冲脉隶于阳明，阳明湿热渐化，冲脉逆气亦能稍和。此为药后病势转松之象，然原文仍戒须日有起色，庶免喘脱，故主旨归于预后判断，示好转而未离险境。", []], "9064": ["病机", "原文未识脉名，然症见经期落后、带下绵绵、牙龈肿腐、心悸嘈鸣、口燥，乃血虚生热与湿郁为热交织，二者皆伤八脉。血虚则冲任失养，湿郁化热循经上炎则龈腐口燥，下注则带下绵绵，心神失养则心悸耳鸣。病机重在八脉受损，虚实兼夹。", []], "9065": ["病机", "脉细弦数，细为阴亏血弱，弦主肝郁风动，数示虚热内扰。血崩后阴血大亏，外感风邪无力消化，故寒热咳嗽久不已；腋下结核、足跗浮肿乃虚风挟痰湿流注。脉症合参，属阴亏血弱、风邪留恋之虚损先兆，不可因吐血不多而轻视。", ["细", "弦", "数"]], "9066": ["预后", "脉形细涩，细主阴血不足，涩主血行瘀滞。少腹瘕聚、脘胀经年，皮肤甲错为瘀血内结、肌肤失养；大便反溏、饮食不思乃脾阳亦伤。脉细涩与症相符，示气血瘀滞而化源告竭，故曰难以支持、防脱，属正虚邪结之危候。", ["细", "涩"]], "9067": ["病机", "左关候肝，脉弦而且数且浮，弦为肝郁，数为火旺，浮示气火升腾。女子以肝为先天，肝经气火少降多升，故月事不来、两目干涩。脉象与肝经气火循经上逆之机相应，非外感表浮，乃内火浮动之象。", ["弦", "数", "浮"]], "9068": ["病机", "脉象弦而带涩，又言脉皆虚，弦主气滞，涩主血瘀，虚为八脉亏损。寒凝血滞则症结攻痛、月事不来；八脉皆虚则带下绵绵、肌肉瘦削；口舌干苦、寒热留连乃瘀久化热伤阴。脉症示寒凝血滞兼八脉虚损，攻补两难，故称棘手。", ["弦", "涩", "虚"]], "9069": ["预后", "脉形弦细，又言脉交虚，弦细为阴血亏而气滞未净，虚示八脉交损。症结渐消、攻痛除是瘀滞稍减，然口舌干苦、留热加剧、便黑、月事未潮、食减，乃余邪未尽而形神俱夺。脉症示正虚邪恋，容易反复，故谆谆慎之。", ["弦", "细", "虚"]], "9070": ["误治", "右脉涩主血少瘀滞，左关弦数主肝郁化火。月事不来、带下赤色、瘕聚攻痛为任脉闭阻、瘀热互结；内热口干、咳痰带血、肉削乃自下损上。更因药误反增其病，变真寒假热之体，脉症与误治相合，故叹自古无治法，难之又难。", ["涩", "弦", "数"]], "9071": ["死脉", "原文未识脉名，仅言脉息少神。经尽之年月事尚来而无血色，是土败血枯、气虚不摄；面浮跗肿、嗌干心悸、饮食无味，乃脾肾衰败、化源告竭。脉息少神即胃气将绝之兆，诸症接踵而来，昭示不克支持，属危重之候。", []], "9072": ["病机", "原文未直接描述脉象，但以“胞脉闭”为核心，阐明经闭病机：心气不得下通，气上迫肺，导致月事不来，并见干咳、寒热等症。病机为气机上逆、营卫虚损，涉及肺心，故拟复脉汤与加味泻白散以调之。", []], "9073": ["病机", "脉形细涩而数，中沉两按有力，示气逆血溢，郁久化热。细涩为阴血亏耗，数主热，中沉有力说明病在里实。气逆上冲致喉痹失音，血随气升而盈盆盈盏，当脐作痛，虑其妨食喘厥，因病致虚，理之棘手。", ["细", "涩", "数"]], "9074": ["病机", "脉来涩数，按之有力，涩主血瘀，数主热，有力为实。气滞血痹，郁久化热，瘀阻回肠，故当脐作痛、扪之觉热、二便不利，左足经筋抽痛，肠间壅塞成痈。此脉象反映气血壅滞、热毒内结之病机。", ["涩", "数"]], "9075": ["病机", "脉弦数小，弦主气滞，数主热，小示气血不足。气坠未升，湿气聚而为痹，痹聚在肾，故少腹有形、按之坚硬作疼、溺时滴沥、交睫自遗。此脉象说明气滞湿聚、郁而化热，兼有正虚之病机。", ["弦", "数", "小"]], "9076": ["病机", "原文未直接描述脉象，但言“右尺相火之脉，宜大而不宜小，小则相火必衰”，又“左关一部，弦得太过”。右尺小主相火衰，左关弦主肝火偏旺，心肾不交，肾精易泄，故难有子。病机为相火衰、肝火旺、心肾不交。", []], "9077": ["病机", "原文未直接描述脉象，论述素禀湿热挟阴虚之病机。湿热与元气混合，出自先天，牢不可破；膏粱嗜欲外增湿热，内耗阴精，致脏腑荣卫常有春夏之情而无秋冬之气，风火相煽，耳鸣、脐冷齿痛等症。病机为湿热内蕴、阴精亏耗。", []], "9078": ["病机", "原文未直接描述脉象，但言“脉见双弦”，双弦主饮邪内动。秋分燥气加临，霜降始寒，寒气外侵，痰饮内动，动见青黄绿色水，属阳明胃。病机为阴亏阳衰，痰饮内停，阴阳偏胜，补偏救弊需因时制宜。", ["弦"]], "9079": ["预后", "脉而数疾无伦，数疾主热盛阴伤，无伦为脉律不齐，示阴阳将脱。阴络伤则血溢，阳络更伤，气不摄血，中焦失守，肝肾内虚，浮肿喘促，饮食不思，恶心欲吐，有阴从下脱、阳从上脱之意，预后凶险，急急大补恐鞭长莫及。", ["数", "疾"]], "9080": ["病机", "脉芤且弦，芤主血络空虚，弦主肝郁，合而名革，昭示血络空虚、元气难摄。元气不摄则温邪下注便溏、外走浮肿、上逆咳痰，甚则阴络伤血内溢、阳络伤血外溢。中虚少纳者遇此，恐不堪磨耐而败，故不可忽略。", ["芤", "弦"]], "9081": ["病机", "右脉大虚，大则邪气尚盛，虚则里气不纳。痛泻、寒热往来、呃忒频作，显系冷风外感内入少阳，里气不纳上逆冲激。汗吐下三法已尽而疟仍作、胸前痞闷，邪盛正虚，故三法不可再施，惟和寒温三例可行，丹田有热胸上有寒。", ["大", "虚"]], "9082": ["病机", "脉弦滑都带空象，弦滑为风寒湿热之邪未化，空象则元气阳气实已内虚。寒热来势颇轻、呕松苔薄，似有暗化之机，然脉空示正虚，虚而有邪，故不得不扶正化邪，恐邪未尽而正先尽。", ["弦", "滑", "空"]], "9083": ["病机", "脉已带滑，尽见空濡之象。滑主湿热痰浊内蒸，濡空示正虚。风入少阳寒热往来，寒时喜热饮、热时不渴，正因湿热痰浊兼夹。舌苔满布、面晦滞皆兼夹之征，欲去风须化湿化痰化热，化湿以温通为主，附子理中连理辈为章程。", ["滑", "濡"]], "9084": ["病机", "脉转弦数，弦主暑湿郁阻，数主阳分更热。暑湿热交蒸，湿未先除则热不能外达，湿去热从外达则阴伤气弱。鼻衄旧恙从清道出、身体困惫、饮食渐减、口内知干，种种见虚中有实之象，邪热偏于中上焦。", ["弦", "数"]], "9085": ["病机", "本段未识脉名，纯论左升太过、右降不及之病机。肝居左主升，肺居右主降，左升仅属肝、右降反属肺。横逆之邪加于清肃之所，木寡于畏反侮于金，故左气旋于右，不能透澈于上亦不能归缩于下，盘旋胁部得矢气则快，终下制于土。", []], "9086": ["治法", "右脉弦强，弦主肝郁气逆，强主气火有余。气有余便是火，气从左边起者肝火也，故以左金丸、当归龙荟丸主之。先左金如水投石，继以当归龙荟丸为法。又虑为痈为血不可不预防，故须有者求之无者求之，求左宜右宜之要法。", ["弦", "强"]], "9087": ["病机", "脉弦而芤，弦主肝阳横逆，芤主暑热伤阴血。伏暑晚发，邪伏三焦，病经十三日，日重一日，胸前痞闷、口中甜腻、二便失调。兹乃肢麻不已更见厥逆，显系邪不从三焦出反入肺肝，肝性横逆上犯肺气则厥，傍流中土则麻，麻厥并至，热盛且肝伤。", ["弦", "芤"]], "9088": ["病机", "原文未明言脉象，但述‘肝肾素虚，肺胃新感’，又经‘消克等剂’后‘已虚而益著’，症见咳嗽剧、痰黏、气短、形困、纳呆、苔剥、胁疼、膝屈、小水黄等，显系虚体受邪、因虚致实、虚实夹杂之候，病机重在肝肾亏虚、肺胃受病、正气益损。", []], "9089": ["病机", "原文谓‘清养之下，弦滑脉象较昨颇缓’，弦滑主痰热内蕴，脉缓为邪热稍退之象；然‘肺受热伤每易成痿’，说明热邪虽减而肺金已伤，病机为痰热渐化而肺阴受损，有转痿之虑。", ["弦", "滑", "缓"]], "9090": ["病机", "原文未出脉象，而论‘喘出于肾，关于肺’，‘热在上焦者，因咳为肺痿’，又谓‘外为热火所烁，内被肝火所逆，金不生水，水不涵木，木反侮金’，病机为肺热叶焦、肝火逆上、金水不相生，终致肺痿喘逆。", []], "9091": ["病机", "原文以‘脉之左者反浮、右者反细’为据，论燥火伤金。左浮为厥阳之火上炎，右细为肺金虚损；症见黄痰粉红、舌干糙、便结、肤热、手震睡语，显系‘热极生风，液涸风动’，病机为五志厥阳之火暗燥肺金，阴液亏耗。", ["浮", "细"]], "9092": ["病机", "右脉弦数主暑热化火、内挟饮食积结；左脉细小主真阴受伤。原文谓伏暑晚发，‘化火伤津’，‘火内挟饮食之积，结而不开’，症见口糜、便泄转痢、便痛，病机为暑热伤阴、积滞内结、邪盛属实。", ["弦", "数", "细", "小"]], "9093": ["病机", "原文谓‘右脉之弦数者能缓能和’为邪减佳兆，而‘左脉细小，按之仍属无神，且兼关部带弦’，弦主肝，细小无神主真阴不足；真阴亏虚难以涵养肝木，肝木顺乘土中，症见不思谷、干呕恶心，病机为真阴不足、肝木犯土、津液劫伤。", ["弦", "数", "细", "小"]], "9094": ["病机", "原文明言‘左脉细软，右关弦数，数则为火，弦则为痰，细软又主乎虚’，虚在肝肾，痰火结在脾胃；症见惊悸、颤振、寤寐不宁、肢体软弱、口燥身疼，病机为肝肾虚而痰火内胜、标本同病。", ["细", "软", "弦", "数"]], "9095": ["预后", "原文谓‘脉形细数，尚未见促，阴火虽旺，阴液未竭’，细数主阴亏火旺，未见促脉则阴液未至竭绝，故‘缓以图之，日进滋补’尚可望夏至阴生；症见咳血、声哑、咽痛喉痹，病机为金水久虚、阴火内结、渐成损症，预后尚可缓图。", ["细", "数"]], "9096": ["病机", "右寸脉滑数，关部濡软，左手细小模糊，示风邪外感引动伏邪，湿痰阻滞，元气受伤。滑数主痰热，濡软为湿，细小模糊乃元气虚衰。邪陷手足厥阴，故神昏、舌缩、下唇震动，势危。", ["滑", "数", "濡", "细"]], "9097": ["病机", "脉象空弦，空为元气虚，弦为邪气实。温邪秽邪湿痰食滞交结中宫，元气本虚无力消除，故脉空弦而神情困倦。正虚邪恋，非补不可，然舌苔白腻、下体痹麻，肾气亦衰，用药棘手。", ["空", "弦"]], "9098": ["病机", "左脉细空，右脉弦急。细空为阴血亏虚，弦急为邪滞未化。湿痰邪滞之外更有瘀血在里，故大便溏黑、喜饮热汤。邪从上出为逆，呕吐额汗，虑其虚波暗起，气不平则诸症难解。", ["细", "空", "弦", "急"]], "9099": ["病机", "脉尚弦急，弦主气机郁滞，急为邪势未衰。陈腐之邪内阻气机，犯肺为咳，犯胃为呕，直从中道而出，又带呃逆。所留宿邪尚在中宫，胃失下行为顺之理，故呕恶日重，必须去尽宿邪。", ["弦", "急"]], "9100": ["预后", "脉象稍和，为邪退胃气渐复之兆。荡涤宿邪后呕恶大减、呃忒更缓、呻吟渐除、大便叠通，皆胃有下行为顺之象。然去痰莫如尽，尚须磨荡下行，继之可卜旋元吉。", ["和"]], "9101": ["病机", "脉细而数，数为热，细为阴亏。阳络伤血外溢后脉宜静，今反细数，故气息短促、胸臆隐痛、便黑心悸，皆虚阳上扰、阴血下虚、气不归源之象。非真火，乃虚寒，阴不恋阳，血难配气，欲降气必补阴。", ["细", "数"]], "9102": ["病机", "脉细仍数，细为阴血内亏，数为阳气外露。上焦瘀血渐清，胸胁闷痛大减，但气息短促未长、火升心悸、口燥颧红，仍属阴不敛阳、虚火浮动。若能呼吸调和，即是转愈之机。", ["细", "数"]], "9103": ["病机", "左关无脉，寸部甚微，右尺亦绝，关前独大且滑。关前大滑为痰祟壅盛，左关无脉、寸微尺绝乃肝经气机闭阻、地水火风上逆于天。痰祟附于肝经，扰乱不宁，故昏不知人、手振肉𥆧、牙关紧急、两目上视。", []], "9104": ["病机", "脉浮不沉而数，浮为邪在表，数为热盛，结合原文“暑湿热三气将蒸”“木寡于畏，反侮其金”，说明湿温时疫初起，邪郁气分，湿热交蒸，木火刑金，故脉浮数。此脉主湿温、时疫之候，症见发热、气交染易等。", ["浮", "数"]], "9105": ["病机", "左三部静细为阴血不足，右动按弦滑数乃中焦痰热内蕴、肝木乘脾。原文“中焦消化甚迟，清浊相干，脘宇满闷”正是脾运失健、痰湿中阻之象，故脉见弦滑数；细为阴伤。此脉主脾虚湿困、肝胃不和，症见腹响、便干稀不定、神倦头眩。", ["细", "弦", "滑", "数"]], "9106": ["平脉", "左右静软，寸关尺三部一律平和，为脉无偏胜之象。原文“体虚，药久未能复元”“药有偏弊，中气反困”，说明久病正虚，但脉象平和，无邪实壅滞，故以饮食消息、固表和中调理。此脉主正气渐复、中气困顿，非病脉也。", ["软", "平"]], "9107": ["病机", "两手细软为气阴两虚，右关微见数象乃脾虚有热。原文“天气阳不得潜藏，背足俱为酸痛，咳嗽不平，牵引胸胁为痛”，说明虚阳上浮、肝肺气机不利。细软主虚，数主热，此脉主气阴不足、虚阳不潜，症见咳痛、酸软。", ["细", "软", "数"]], "9108": ["病机", "脉细而带数，左甚于右，细为阴亏，数为火浮。原文“病虚，火浮上则阳不潜藏，下焦虚而不固，遗泄复发”，正合阴亏火旺、虚阳上扰之机。此脉主阴虚火浮，症见头眩耳鸣、咳嗽、夜睡微汗，故仿食颐养法调摄。", ["细", "数"]], "9109": ["病机", "左右各部均见静软，为邪退正虚、脉象趋于和缓之象。原文“诸恙亦见向安，虚阳亦能潜藏”，但“肝尚为升，肺少下降，咳嗽略为见紧”，说明肝肺升降未复。静软主虚，此脉主病后正虚、肝肺失调，症见咳、耳鸣、胁痛肢酸。", ["软"]], "9110": ["病机", "左三部细软为脾虚阴弱，右寸关弦浮乃肝肺薄感、气机不降。原文“脾失健运，肝肺又有薄感”“腹痛，溏泻而兼糟粕”，说明脾虚湿盛、肝肺升降失司。细软主虚，弦浮主外感，此脉主脾虚兼感，症见泻、肢酸、胁背串痛。", ["细", "软", "弦", "浮"]], "9111": ["病机", "左弦细为水不涵木、木火上升，右细数为脾运不健、湿热下走。原文“木火上升，则右耳作堵”“脾湿下走，则气肿作痛”，说明肝肾阴亏、木火刑金，兼脾湿下注。弦细主阴虚阳亢，细数主湿热，此脉主阴虚火旺、脾湿下注。", ["弦", "细", "数"]], "9112": ["病机", "脉左细弱带弦，右细软微数，细弱示营虚水亏、脾虚气弱，弦为肝少滋养、气火不潜，微数为湿热停顿。故见耳鸣作堵、足跟肿痛、饮食下行迟慢，总属肝脾升降失司、湿热内滞之病机。", ["细", "弱", "弦", "数"]], "9113": ["病机", "脉左细软带弦，右软按久略数，细软为阴分不充、脾阳不振，弦为肝火不潜，数为湿滞化热。火浮则耳鸣作堵，湿滞则足跟痛、运化不利，故推病由在肾阴不足、脾阳不振，属虚中夹实之病机。", ["细", "软", "弦", "数"]], "9114": ["病机", "脉左关细弦，右关微数，余部均细，细为水亏，弦为肝火，数为湿郁化热。以脉和证，耳鸣、足跟热痛、窜痛、头晕、小泡皆水亏火浮、湿郁化热之象，病机在阴虚火浮、湿热内郁。", ["细", "弦", "数"]], "9115": ["病机", "脉左弦象稍加，右尚带微数，按久均细而少力，弦为肝亢，数为火浮，细少力为肾亏阴虚。肾开窍于耳，足跟为肾所主，肾亏则火浮，阴虚则湿阻，湿火相搏故热象渐来，病机属肾虚火浮、湿阻化热。", ["弦", "数", "细"]], "9116": ["病机", "脉左细、弦象较和，右部渐数，细为脾肾不足，弦为肝亢有余，数为湿热蒸腾。火浮于上则耳鸣耳堵，湿聚于下则足跟痛、便不流利，中焦转输失常，故病机为脾肾不足、肝亢湿停、上下不交。", ["细", "弦", "数"]], "9117": ["病机", "脉左部较静，右部尚带微数，左静示肝木上升较平，右微数为脾湿蒸热未解。肾阴内虚则闭藏不足，肝逆上浮则耳鸣，脾运不健则湿随下走而足跟热痛，病机为脾肾两虚、湿火未清。", ["数"]], "9118": ["病机", "脉左细稍带弦，右濡细微微带数，细弦为肾不摄肝、肝火上升，濡细数为脾少健运、湿滞化热。故耳鸣作堵、胃纳式微、足跟痛引足背，良由气弱湿阻、营络失宣，病机属肝脾不调、湿阻络瘀。", ["细", "弦", "濡", "数"]], "9119": ["病机", "脉右弦数左细数，细为阴虚，弦为风动，数为热，阴虚生风、气虚生湿，风上扰则耳鸣耳堵，湿下陷则足跟痛引踝骨，饮食少运、便干溏不调、口舌起泡，症半虚半实，病机为阴虚风动、气虚湿陷。", ["弦", "数", "细"]], "9120": ["病机", "脉弦象稍减而数仍未平，说明肝风略缓而虚火尚炽。虚火挟风上扰则耳鸣不止、右耳堵塞；火挟湿下注则足跟疼痛、牵连踝骨；中运不健故饮食不甚消化、大便见溏。脉数主虚火，弦主风与肝，弦减数存提示风势稍退而火未清，虚实参半。", ["弦", "数"]], "9121": ["病机", "脉浮弦且两手均数，浮主虚火外浮，弦主肝风，数主火炽。原文谓“火生风，耳鸣如昨”，风火循经上扰清空；火挟湿则足跟作痛，湿自脾生则中运欠健、食后运迟、早间便溏。络脉未通、升降未和，故头晕气怯。脉象反映风火湿交杂、上盛下虚之病机。", ["浮", "弦", "数"]], "9122": ["病机", "脉弦象较和而数象未静，说明肝风渐缓而虚火仍煽。原文谓“虚火煽烁，下关不固”，故腰酸气弱，属上盛下虚；耳闷稍减仍然作响、足跟作痛略减，是风火湿未尽；中焦运融未健、消化犹迟、便垢带溏，为脾运不健。弦和数静示风减火存，虚实错杂。", ["弦", "数"]], "9123": ["病机", "脉仍弦减而数未静，弦减示肝风稍退，数未静示水亏木旺、木火内炽。木火上扰清空则耳鸣不减；木邪下注底极则足跟犹痛；脾胃不协则头晕运迟、夜寐醒后痰泛。原文“虚实兼见”概括上盛下虚、木火挟痰之病机，脉象与症候相应。", ["弦", "数"]], "9124": ["病机", "脉弦数之象渐减轻，说明肝风虚火之势渐退，故耳堵较通、足痛已轻，但鸣响尚存、筋酸尚留，余邪未净。原文指出“向来脾胃虚弱，中之少冲和之气”，药饵未见备胜，反觉气体痰软，故宜暂缓进剂、调中醒胃，以观病机。脉减示邪退，虚象当顾脾胃。", ["弦", "数"]], "9125": ["病机", "两关弦数如昨，尺部较软，寸部不足，说明肝火仍炽而心肾已虚。原文谓“肾不济心，心不固肾”，故遗泄又发；肝不能潜则耳响重听，脾不能运则足跟痛、便不畅；腰酸寐欠实为下虚。关弦数主肝火，尺软寸不足主心肾亏虚，脉症合参为虚实夹杂。", ["弦", "数", "软"]], "9126": ["病机", "脉弦数较平而虚象更见，说明肝火渐退而心肾亏虚显露。原文谓“遗泄连作，有梦属心，无梦属肾”，心肾两亏则诸证纷沓；清升浊降未能流利，故耳鸣堵闷虽减、足痛步艰痰重、腰间发酸、大便一时俱发。弦数平而虚见，示邪减正虚，病机重心转虚。", ["弦", "数"]], "9127": ["病机", "脉左右一律细软俱见数象，细软主虚，数主虚火。原文谓“虚火非上扰即下迫”，上扰则耳鸣响闷，下迫则关门不固、叠次梦泄；上热下热必及于中，胃不能容、脾不能运，故消化迟缓、大便未畅。细软数并见，示虚火充斥三焦而脾胃受损，脉症相应。", ["细", "软", "数"]], "9128": ["病机", "左部数象为营阴不足、虚火内扰；右细主气弱，两尺软为下元亏虚。气弱不能流利机关，故腰股酸软、足跟痛减而耳响堵闷；气不蒸液则天凉口干，气少磨运则消化迟缓。脉证合参，病机为气阴两虚、虚火上炎，治拟益气养液潜火。", ["数", "细", "软"]], "9129": ["病机", "脉弦象得减而渐转虚软，按之带数，示肝郁稍缓而脾肾两虚、虚火未清。肝烁肾则生风耳鸣，挟湿则堵闭；肝乘脾、郁湿则足跟痛，挟风牵络则肩脾腰胯酸软。便溏、消化迟缓为脾肾两虚。脉证合参，主肝郁独炽、脾肾两虚，治拟泄风宣窍、清热和络。", ["弦", "虚", "软", "数"]], "9130": ["病机", "脉弦数较减轻而重按虚软无力，示肝火渐平而肾亏未复。腰为肾府，封藏有亏则腰痛上连背下及胯；肝木上升、脾湿下陷偏右，血不流灌，风湿窜经入络，故耳响作堵有增无减、足跟痛有减无增。脉证合参，主上盛下虚、肾亏肝亢、风湿入络。", ["弦", "数", "虚", "软"]], "9131": ["病机", "脉弦数俱见轻减而按之仍虚软少力，显属有虚无邪。肾不养肝，肝木侮中，脾胃久不复则纳食消化迟缓、大便溏结不一；肝火上炎则耳鸣作堵未减；下焦不能摄纳则足跟酸痛、腰膝酸软，寐时体颤。脉证合参，主肾亏肝亢、脾胃虚弱、虚风内动。", ["弦", "数", "虚", "软"]], "9132": ["病机", "脉又见弦数，弦为肝邪，数为火旺。水不涵木，木邪侮中，湿郁化火，火复生风，上扰下窜，故耳鸣堵响未减、腰膝足牵连痛而此重彼轻，足甚于腰、酸软无力且似经络发热。脉证参详，主肝火化风、湿郁络阻，治拟解热泄风、通络化湿，标本兼调。", ["弦", "数"]], "9133": ["病机", "脉弦数，旋平旋起，弦两关为甚、数两尺为多，示病本在肝肾。肝主筋，股足掣动之痛属肝；肾主骨，酸重之痛属肾；耳为肾窍，肝附胆经行耳侧，故鸣响堵闷。肝侮土、肾为胃关，则食运迟、大便不调。种种病机皆本肾肝两虚，治当清肝安肾。", ["弦", "数"]], "9134": ["病机", "两尺见数，所以又发遗泄，为水亏火动、肾失封藏；两关仍弦，为木旺克土。木火内燃，上升则耳鸣堵塞未减，下扰则足跟痛减而支窜腰胯；阴亏气痹，故口微渴、食物运迟、大便不畅。统核诸证合以脉情，主水亏木旺、阴亏气痹，治拟调气和阴。", ["数", "弦"]], "9135": ["病机", "脉细小兼带数，数属心肾两亏、虚火内炽，弦属肝脾不调，细小又属体虚本脉。证情未见轻减，镇坠则耳响相宜而恐碍下焦，兜涩则遗泻足痛得益而与上焦不符。既顾上下又须中权运动，使饮食能运、大便令畅。脉证合参，主心肾亏虚、肝脾不调、虚火内炽。", ["细", "小", "数", "弦"]], "9136": ["病机", "脉数较减而尺部依然软弱，示卫虚未复、肾根本虚。肾不涵木则木风挟湿蒙窍，故耳鸣作堵；肾反克脾则脾湿鼓风入络，足跟痛、食运迟、更衣不畅。脉数减为热势稍退，尺弱主肾亏，故需肝脾肾三阴同治，标本兼顾。", ["数", "弱"]], "9137": ["病机", "脉数均减，重按轻按气无力而软，示虚阳少潜、真阴不充。头为诸阳之会，虚阳上浮则耳堵眩晕；足为至阴之部，阴亏则足肢酸痛移腰胯。先天本虚、后天气弱，脾胃升降失度，清浊混淆，故脘胀嗳气、更衣溏结不调。治拟养阴熄风、调气化湿。", ["数", "软"]], "9138": ["病机", "脉细软如前，又起数象带弦。弦属阴虚火旺，数属阳不潜藏，故诸症纷叠：耳堵眩晕、足跟痛酸软，皆上盛下虚、肾真亏弱所致。腰酸痛甚，咳嗽转动牵引，显系肾亏不摄。然纳食消运迟、大便溏结不定，虚不受补，故拟镇肝泄热、安中和络，虚实兼顾。", ["细", "软", "数", "弦"]], "9139": ["病机", "左三关细软无力主阴虚于下，右寸关独濡浮主阳旺于上。阴不敛阳，浮阳上越则耳蒙鸣响、头晕口渴；阳不引阴，阴失下贯则足跟酸痛、筋络肘掣。肾封藏内虚，精关不固，遗泄后腰痛胯酸增剧，便溏纳酸。治拟运水谷精华、调气营敷布，以合阳平阴秘。", ["细", "软", "濡", "浮"]], "9140": ["平脉", "脉左右皆静而和，关部不弦，寸尺平调，示脉象平和无偏。所见证候耳响发堵、腰酸足痛，皆属虚发：耳堵为脑筋不充，腰足痛为血管不流贯。值长夏脾胃司令，当重清升浊降，忌滋腻重浊，宜调胃和脾，清煦汤随时酌进。", ["静", "和"]], "9141": ["病机", "左三部细软属阴虚于下，各部均浮属阳冒于上。阴不敛阳，阳旺内延，关门失固，故遗泄后腰胯坠痛增剧，口干心烦、满闷交作、坐卧倦懒。脾胃当令，燥则生风，滞则酝湿，气与阴虚、风与湿极为用事，故耳蒙足痛诸症丛生。治拟简括数味，标本兼顾。", ["细", "软", "浮"]], "9142": ["病机", "脉左右皆软，两尺尤甚，示气失运行、肾关不固。夏季损气，表虚气散，里滞气阻，冲和之气致偏：气火上升则耳病，气痹不宣则足病。气亏归肾，精生气、气化神之用不足，故腰胯痛增、神倦无力、心烦口渴、食运迟、便溏。治拟甘温益气，参以柔肝养心。", ["软"]], "9143": ["病机", "右寸濡细属肺气虚，左寸细小属心阴弱，左关右关细弦系木邪侮中，两尺按之无力为水火两亏。三焦俱及，故腰胯痛胀、便溏、舌泡、遗泄，无非阳不潜藏、生风郁热。耳窍蒙堵鸣响更甚，亦由虚阳上浮。治拟和阳清阴，以调三焦。", ["濡", "细", "弦"]], "9144": ["病机", "脉左右细涓，涓甚近数，尺部左软右细，细为阴亏，数为虚热，软为气弱，合之属正气内亏、真阴失固，关键在脾肾。脾不健化则大便不润，肾不坚守则梦泄又发；口渴心烦、头晕艰寐、气软体倦，皆脾肾虚牵连所致。上热下寒、耳鸣发堵、腰胯酸重，正是虚热上浮、下元不固之象。", ["细", "数", "软"]], "9145": ["病机", "左部静软，右三部细濡带数，细濡为阴亏，数为虚热，软为气弱，故曰阴虚于下、阳冒于上。遗泄后阴更亏，气阳升多降少，挟心热肝风上扰，则耳鸣发堵、孔窍被蒙；腰酸胯痛为机关不利。纳食运迟、大便弗实、气怯神倦嗜卧，又见中气不和，湿令助湿，故调心为主，柔肝运脾佐之。", ["软", "细", "濡", "数"]], "9146": ["病机", "左涩细，右濡带数，涩细为阴血亏涩，濡数为虚热挟湿。天令溽闷，虚火虚风挟湿上升更盛，故耳窍不清、且响且堵，上热愈炽则下虚益见，腰胯酸痛。中焦运行不健，化食见缓、大便勿匀；口渴头晕、神倦嗜卧，皆上盛下虚、中焦不运之候，故以养封藏为第一义。", ["涩", "细", "濡", "数"]], "9147": ["病机", "脉息细软，细软为气阴不足，数象时平时起，乃少火不藏、壮火转炽之征。关元不固则更衣频仍，火炽于脾胃则纷叠不一；耳窍堵响、起与眩晕、腰胯掣痛于步履、精神疲倦嗜卧，皆元气亏乏、虚火内扰所致。证同参而峻剂多有不合，故拟养心滋肾、柔肝和脾，缓调根本。", ["细", "软", "数"]], "9148": ["病机", "左三部静软，右关或滑或弦，今脉尚不失冲和，知胃气未败。滑弦为气分郁湿、阴虚生热逗留，故虚不受补，脘宇运迟、大便不畅，中气不调而真阴不复。耳响不减、腰痛胯掣较甚，因濡暑郁闷，机关更为不利；下虚转上热，则头晕时起、口发小泡。治当协肝脾而化湿，湿化则火自解。", ["软", "滑", "弦"]], "9149": ["病机", "脉软数，象平而未静，软为气阴虚，数为虚热，右关欠调则脾运不健。病本气阴虚、脾肾不足，而眩晕为风、便溏为湿，风湿合化，虚热自生，此皆标病。腰胯跳痛、鸣而作堵，亦风湿虚热之标。补则碍标，泻则碍本，故拟标本双合，既顾脾肾之本，兼化风湿之标。", ["软", "数"]], "9150": ["病机", "左部略缓，右部微数，缓为湿滞，数为郁热。木乘土位，湿蕴中宫：上泛则耳鸣气堵头晕，中滞则饮食不运，下注则便溏、腰胯掣痛。舌苔淡亦湿蕴之征。此乃肝木乘脾、湿热内蕴之候，故宜清肝运脾，兼治下焦，清利湿热，使木不乘土、湿化热清。", ["缓", "数"]], "9151": ["病机", "脉弦数，弦主湿邪痰滞交炽，数主热，热为湿遏故热不扬。湿痰阻滞，清阳不升则头晕腿酸；舌黄隐灰、溲少，皆湿热痰滞内蕴之象，便通则下焦尚通。病经四月，湿痰胶结，防寒热转重，故戒勿忽。此段以脉弦数断湿痰交炽、热郁不扬之病机。", ["弦", "数"]], "9152": ["病机", "脉细濡为体虚而有湿痰之象。细主血虚阴亏，濡主湿邪困阻。左血液不能下润肠腑，故大便难；浊气在上，则生腹胀、口腻胸闷；湿阻气化，则溲少。脉症合参，乃虚体夹湿痰，本虚标实，故当先治标分。", ["细", "濡"]], "9153": ["兼症", "脉软数为湿困中焦、兼有热象之征。软脉主湿主虚，数脉主热。湿困中焦，则神思困顿、胸闷不思纳、便溏；兼之喉肿痛而红碎，乃湿郁化热上攻。此段以湿困为主，兼见喉症，故曰兼顾立方。", ["软", "数"]], "9154": ["病机", "脉数主热，便秘为热结于里。表热四日，盛衰不定，痰多湿温痰滞交结，脉数示热邪内盛。热与痰湿交结，故变迁方多。此段重在湿温痰滞交结之病机，而非单纯表证，幸勿轻视。", ["数"]], "9155": ["病机", "脉弦数不畅，弦主湿阻气滞，数主热，不畅示湿邪黏滞、气机不利。触痧之后，乍寒乍热，舌黄，梦语少寐烦躁，便秘溲少，皆湿阻化热、蒙扰心神之象。此系湿阻重症，交四日而变迁易如反掌。", ["弦", "数"]], "9156": ["病机", "脉濡主湿，体乏而有湿痰。湿浊上蒙则头痛目胀，湿阻中焦则胸闷、口腻，湿滞肠道则大便不多。脉濡与诸症相应，皆湿痰内蕴之征。体虚湿痰，未易奏效，提示湿性黏滞，病程缠绵。", ["濡"]], "9157": ["预后", "脉弦数滑，重按少力，为湿温化热燥、阴损阳长之象。弦数滑主热盛痰壅，重按少力示阴液已亏。舌燥黄尖红、热甚于身、神识不清、大便旁流，皆热燥劫阴、痰热蒙窍之危候。阴损阳长则阴更竭，故防猝厥不返，大危。", ["弦", "数", "滑"]], "9158": ["预后", "脉左数而不调，已有根本欲离之势；右部滑数，痰热犹未全退。左数不调示阴液告乏、肝木上扰、肾气下动，气阻丹田上逆，故神思困惫、耳鸣头晕、舌干无津。右滑数示痰热未清。根本欲离，厥塞易如反掌，故勉拟方以尽人谋。", ["数", "滑"]], "9159": ["预后", "脉左不扬，右滑数。左不扬示正气不支、邪陷厥少；右滑数示肺胃痰热尚盛。温邪化火劫阴，直逼厥少，故昏蒙、坐卧不安、有汗热不解、气急旁流、渴饮、舌干糙。症情十分危险，防陡然厥变。", ["滑", "数"]], "9160": ["病机", "脉弦数，弦为温邪郁伏少阳、气机不畅，数为热盛于里。热郁九日，气急口渴、糊语少寐、舌黄腻，皆热邪内炽、扰及心神之象。脉数与热势相应，弦则示郁而不达，故断为温邪郁伏，恐正不胜病而骤然昏陷，属病机与预后并见之候。", ["弦", "数"]], "9161": ["病机", "脉数主热，温邪有汗而热不解，是邪不为汗衰，热势内蒸。舌灰干示津液已伤，少寐为热扰心神。脉数在此说明邪热炽盛、形将化火，非表证汗出可解，故原文戒以不可轻视，属热化伤津之病机。", ["数"]], "9162": ["病机", "脉弦数，弦主气郁火升，数主热盛。有汗不解、渴不引饮、头胀胸闷、舌尖绛，皆火热内郁、不得外达之征。脉弦数正合火郁之机，故原文谓火如燎原、理之不易奏功，示热势鸱张、难以骤清之病机。", ["弦", "数"]], "9163": ["预后", "原文未出具体脉名，仅言脉不扬，指脉气不能振扬外达。湿温一候，舌糙黄，是湿郁化热、邪阻气分而正气不能鼓脉。脉不扬与舌糙黄并见，示邪势方张而正不胜邪，故断势在转重、防昏陷，属据脉测预后之论。", []], "9164": ["病机", "两脉濡数，濡主湿、数主热，合为湿热内蕴。脾阳为湿所困，得食作胀，舌苔淡黄而白，大便日夜四五度、少腹沃涩而痛，皆湿滞中焦、脾运失职之症。脉濡数正应湿热挟土之机，故原文以挟土化湿为治，属湿困脾阳之病机。", ["濡", "数"]], "9165": ["病机", "脉濡滑，濡为湿象，滑主痰涎，合示痰湿内盛。痰湿与气机交阻，故咽哽不畅、胸次不舒、中脘易阻，皆气为湿痰所滞之症。脉濡滑与痰湿气阻相应，原文宜顺气疏中，正针对痰湿阻气之病机而言。", ["濡", "滑"]], "9166": ["病机", "原文未出具体脉名，仅言脉不畅，指脉气郁滞不舒。胸闷便泄、舌微黄、灼热气窒、吐痰不利，皆温邪内郁、表里相传之象。脉不畅正示邪郁气窒、不能透达，故原文谓未可泛视，属温邪内郁、表里同病之病机。", []], "9167": ["病机", "原文未出具体脉名，仅言脉不扬，指脉气不能外扬。形寒热不透、咳不畅、骨痛、舌白，皆表邪郁于肌表、不能透达之症。脉不扬与寒热不透相应，正示邪郁卫表、阳气不伸，故原文断为表邪郁不能达之象，须透之，属表郁之病机。", []], "9168": ["病机", "脉濡主湿，酒湿积久困阻中阳，运化失职，故大便易散。濡为湿盛阳微之象，湿滞中焦则脉道弛缓，与“中阳被困”相应，治宜从中焦立方以化湿醒脾。", ["濡"]], "9169": ["病机", "脉数主热，幼温邪内郁，表热未解，火升而脉数。耳下肿、咳皆温邪郁于少阳阳明之征，数脉示邪热内盛，法宜透达宣泄，使郁热外达。", ["数"]], "9170": ["病机", "脉形濡涩，濡主湿、涩主滞，暑湿热气内伏，因劳倦正气泄越而发。面垢油亮、目黄、头胀如束、胸脘痞闷皆湿热郁蒸之象，脉非表症，当以劳倦伤伏邪例诊治。", ["濡", "涩"]], "9171": ["病机", "脉弦主肝郁，脚气痛楚不能履地，乃肝失疏泄、络脉痹阻，兼风湿外袭。弦为肝脉，示气机郁滞，故宜疏肝宣络、祛风化湿以通痹。", ["弦"]], "9172": ["病机", "原文未识脉名，然腹中胀满、肛外臀间豆大肿粒，显系湿热下注、壅滞为病。脉象虽缺，据症可知湿热内蕴，法当内外两治以清利湿热。", []], "9173": ["预后", "脉不畅示伏邪内阻、气机不达，热八日而肢麻胸闷、烦躁不寐、口干，伏邪重症，脉不畅则邪无外达之机，故曰变迁可虑，当防内陷。", []], "9174": ["预后", "脉不扬示伏暑内郁、阳气不伸，病旬日而胸闷口干、夜热壮、不寐烦躁，邪势鸱张而脉不能鼓，故势在转重，勿忽。", []], "9175": ["病机", "脉细数主阴血不足而热，风湿骨痛日久不净，耗伤营阴，胸闷心悸寐不安乃心神失养、经脉痹阻。细为虚，数为热，故宜宽中宁神、宣通经脉。", ["细", "数"]], "9176": ["主病", "脉数主热，伏暑为病，暑热内蕴，故脉数。症见左表热交八日、肠鸣胸闷、舌黄，皆暑热夹湿、表里同病之象。脉数与表热、舌黄相应，提示热势偏盛，不可忽视，当清暑化湿。", ["数"]], "9177": ["病机", "脉软弦微滑，软主脾弱，弦主肝亢，滑主痰湿。症见寐中易惊惕、口干腻、胃纳呆顿，正合肝亢脾弱、痰湿热逗留之机。脉象与症候相参，说明本虚标实，须兼顾立方。", ["软", "弦", "滑"]], "9178": ["主病", "脉弦主风火，风火上升，故头痛从后项而上、暮夜发热。病缠两旬余，脉弦不减，说明风火未息，须速为解散，以防深入。脉弦与头痛、发热相应，为风火内动之征。", ["弦"]], "9179": ["预后", "脉数不扬，数主热，不扬为邪郁不达。伏暑旬日，胸闷口干、夜热壮、不寐烦躁，热势转重而脉不扬，说明邪热内闭，不能外达，故曰热在转重，勿忽。脉症合参，预后当慎。", ["数"]], "9180": ["预后", "脉不扬，湿温痰滞交结，表里相传。症见表热头胀晕、胸闷骨痛、便泄腹胀，湿痰阻滞，气机不畅，故脉不扬。表里同病，邪无出路，转重可虑，当化湿透表。", []], "9181": ["病机", "脉微数，微主湿阻，数主热。形寒灼热、头胀干呕、咽痒欲咳，为湿痰中阻、外袭风温之象。脉微数说明湿痰内阻而风温外袭，宜宣泄涤邪，使邪有出路。", ["微", "数"]], "9182": ["治法", "脉不畅，湿邪痰滞交结，气机不利。症见乍寒乍热、胸闷头痛、口腻泛呕，皆湿痰内阻、表气不宣之候。脉不畅与症相应，故宜先透达利湿兼进，使湿化气畅。", []], "9183": ["预后", "脉不扬，湿邪痰滞交结，气机郁滞。寒战发热得汗渐解，而头痛如破，脉不扬，说明湿痰内阻，邪未尽透。极易转成连热，殊不可忽，当化湿透邪，防其传变。", []], "9184": ["主病", "脉濡主湿，湿邪困阻中焦则神倦胃呆，湿郁肌表则形寒灼热。舌黄口溲为湿郁化热之象，左头晕乃清阳不升。脉濡与湿阻气机、表邪未解之症相应，故宜燥湿和中、疏解表邪。", ["濡"]], "9185": ["病机", "脉弦滑数，弦主邪滞交结，滑主痰湿，数主热蒸。湿温旬日，泛呕咳嗽为痰湿犯肺胃，舌白黄、溲赤、便溏乃湿热蕴结。脉象与邪滞交结、湿热蒸腾之机相符，故言殊不可忽。", ["弦", "滑", "数"]], "9186": ["病机", "脉弦不畅，弦主湿温痰滞内结，不畅示气机郁遏。寒轻热重、少寐口苦、舌黄为湿热蒸热，二便俱红乃积滞不下、热伤血络。脉弦与痰滞蒸热、积滞不下之病机相应，故虑其变迁。", ["弦"]], "9187": ["主病", "脉濡主湿，湿郁气阻则胸脘痞闷，舌滑亦为湿象。脉濡与湿郁气阻、中焦不运之症相应，故宜燥湿疏中，使气机得畅。", ["濡"]], "9188": ["病机", "脉不畅示湿温内郁、气机不畅。表热间日而作、热不外透为湿遏热伏，头晕胸闷、腹鸣作胀、遍体烦疼皆湿郁气阻、经络不利之象。舌苔不清、不思食，脉症合参，湿温内郁有转重之势。", []], "9189": ["病机", "脉微数，微为正气不足，数为邪热未清。秽邪自口鼻而入，清浊失常则吐泻交作，头胀重、胸闷腹胀膨大为邪滞未净，肢冷乃邪郁阳气不达。脉症示病方外达，急当乘势透达，防其转重。", ["微", "数"]], "9190": ["病机", "脉软弦，软为暑热伤气，弦主热炽气郁。幼热八日，得汗热缓而汗干热甚，胸闷、舌红口干，乃暑邪与阳明热交炽，津气已伤。脉软弦与暑热内炽、气机郁滞之机相应，故防转重。", ["软", "弦"]], "9191": ["病机", "脉不畅示暑湿内郁、气机被遏。形浮灼热、胸闷为暑湿郁表，便溏溲少而赤、得食中阻乃湿困中焦。暑湿为寒凉所束，表气不通，脉症合参，防连热不退，殊不可忽。", []], "9192": ["病机", "脉弦数不大，弦主湿滞内阻，数主暑热内蕴，不大者正气尚能约束。暑湿滞深重，困阻气机，故胸闷口腻、舌白；右腿酸便泄均减，示湿滞部分下行，但寒热依然，邪未尽解。脉象与暑湿滞深重之机相应，变迁可惧。", ["弦", "数"]], "9193": ["病机", "脉不畅，乃暑湿滞交阻气道，气机不得宣通之象。气阻则胸闷咳痰不利、舌白腻；腹痛便少、足冷，为湿滞内壅、阳气不达四末；左身热甚衰无定，暑湿郁蒸。脉不畅正合气道交阻之机，极易变迁。", []], "9194": ["预后", "脉弦数，弦主邪滞内阻，数主热盛，舌黄垢为热与积滞交蒸。发热旬日、胸闷便闭、不寐，邪滞壅遏，热不得泄。两候时届，脉弦数不退，示邪热鸱张，有内陷昏痉厥变之虑，故预后可虑。", ["弦", "数"]], "9195": ["病机", "脉数不扬，数主热，不扬者邪滞深伏、气机不达，故虽表热无汗而脉不浮扬。头晕胸闷、脘腹拒按、便闭、夜来糊语，皆邪滞积伏深重、壅遏气机之征。脉数不扬正合积伏深重之机，骤变可虑。", ["数"]], "9196": ["病机", "脉不畅，乃痰湿停阻中宫、气机壅塞之象。二便不通、不思食、胸闷，皆痰湿阻中、升降失司所致。触痧之后痰湿停阻，脉不畅正应气机壅滞之机，防蒸成寒热，未可忽。", []], "9197": ["病机", "右脉不畅，右主气，气机不畅则面浮头晕，风伤于上；脐下作痛、便溏、舌红，食滞中阻，郁而化热。脉不畅示气滞食阻、升降不利，与风伤于上、食滞中阻之机相应，延防转重。", []], "9198": ["病机", "脉数浮，浮主风邪在表，数主热，风水病五日寒热退而浮肿如昨、咳嗽较畅、寐则气急、头痛，乃风湿热互郁，风邪未净、湿热内郁，肺气不利。脉数浮正合风湿热互郁之机，宜肝脾兼治。", ["数", "浮"]], "9199": ["病机", "脉弦濡，弦主气机不畅，濡主湿，脱力伤阳，阳气不能运湿，湿郁肌肤发黄，四肢无力，舌白无华。二便俱通，湿尚可下泄，然阳运不及，防延腹满，脉弦濡正合阳虚湿运之机。", ["弦", "濡"]], "9200": ["病机", "脉软弦带数，软为湿郁之象，弦主气机郁滞，数则示火势方张。原文谓“湿郁化火，火势方张”，湿浊内郁，久则化火，火性急迫故脉数；湿性黏滞未化，故脉软；气机被郁，故兼弦。症见舌黄垢腻、大便燥结、茎中痛漏、血麻，皆湿热下注、火郁阴伤之候，故言“一时不易奏效”。", ["软", "弦", "数"]], "9201": ["病机", "脉浮数，浮主邪在表分，数主热盛。原文谓“风得温而化火，火性炎上”，风邪得温药或温化而转为火，火性上炎，故见鼻衄色鲜、头晕而重、面浮咳嗽。寒热退而复作、溲通便闭，示表邪未尽而里热已炽。浮数之脉正合风火相煽、邪热浮越之机，故宜清化泄降。", ["浮", "数"]], "9202": ["病机", "脉弦濡，弦主气滞，濡主湿困。原文谓“湿滞阻气，尚须疏通分利”，湿浊内滞，气机不畅，故脉弦；湿性濡软，故脉濡。症见大便泄泻转溏、得食脘痛、舌白腻，皆湿滞中焦、脾胃运化失司之候。形寒烘热均瘥，示表证渐解而湿滞未化，故仍须疏通分利。", ["弦", "濡"]], "9203": ["病机", "脉数重按少力，数主热，重按少力示正气不足、邪未深入。原文谓“湿温痰滞阻气”，湿温之邪与痰滞互结，阻遏气机，故胸痞头胀、遍体痛；畏风热不扬，示邪郁表分而正虚不能达邪。数而少力，正合湿温痰滞阻气、正虚邪郁之机，故宜先表里分解。", ["数", "虚"]], "9204": ["病机", "原文未识脉名，仅言“脉不畅”，属纯描述，故脉象要素为空。脉不畅示气机郁滞、湿浊内阻。饮食不节、寒暖不时，损伤脾胃，湿浊内生，气机不畅，故头胀口苦、肠如燥泄、舌白腻、脘部拒按。原文谓“防蒸成下痢”，湿郁化热，蒸迫肠道，有转痢之势，故殊不可忽。", []], "9205": ["病机", "脉弦数，弦主气滞痰结，数主热。原文谓“湿温痰滞交结”，湿温之邪与痰滞互结，气机郁滞故脉弦；邪热内蒸故脉数。症见形寒灼热、头晕口腻吐涎、舌微黄，皆湿温痰滞交结、邪热鸱张之候。原文言“变迁可惧”，示痰热互结，易生他变，故脉弦数主此病机。", ["弦", "数"]], "9206": ["病机", "原文未识脉名，仅言“脉不畅”，属纯描述，故脉象要素为空。脉不畅示湿温之邪郁遏气机，湿浊内阻。表热七日，舌黄口干，胸闷痰腻，咽间不易咯吐，皆湿温痰热壅阻上中二焦之候。原文谓“病方转重，此属湿温，正在发越之时”，示邪正交争，湿温有外透之势，故脉不畅主气机郁遏之病机。", []], "9207": ["病机", "原文未识脉名，仅言“脉不畅”，属纯描述，故脉象要素为空。脉不畅示气机郁滞、肝风未平。头胀晕减而未愈、畏风较瘥，示风邪渐退而肝阳未靖；呼吸胸口牵痛、大息少力，乃肝气郁滞、气机不畅之候。原文谓“宜泄风平肝、泄降主之”，脉不畅正合风阳上扰、气机郁滞之病机。", []], "9208": ["病机", "脉弦数不畅，弦主邪郁少阳，数主热盛，不畅为气机壅滞。秋凉引动伏暑，热郁于内不得外达，故壮热五日不退、胸闷头晕、舌黄、少寐糊语。脉症合参，示伏暑内闭、病无出路，有昏陷之虑。", ["弦", "数"]], "9209": ["治法", "脉不畅提示湿阻气机，耳鸣腹胀、头晕、溲赤为湿浊内蕴、清阳不升、下注膀胱之象。原文未识脉名，仅言脉不畅，结合症候，病机为湿阻中焦、气化不利，故以利湿疏中为法，使湿去则脉自畅。", []], "9210": ["病机", "脉数主热，表热五日、头胀胸闷、咳不畅、腹痛，为温邪内伏、热郁肺胃，气机不畅。脉数而症见表热，说明温邪有内传之势，故急急透之，使邪从外解，防其深入。", ["数"]], "9211": ["预后", "脉弦滑数，弦主邪郁，滑主痰热，数主热盛。伏邪晚发七日，热甚于夜、烦躁谵语、指搐、舌干黑无津、大便不通，为邪热内陷心包、痰热蒙蔽、阴液耗竭。脉症俱险，故断昏厥变幻可立而待。", ["弦", "滑", "数"]], "9212": ["病机", "脉滑数，滑主痰热内蕴，数主热盛。表邪化热，热甚于日晡，呕逆，通大便后腑邪渐有出路，但经邪留恋尚多，舌糙黄，病在阳明。脉滑数示阳明热盛、痰热未清，故治宜存阴清热。", ["滑", "数"]], "9213": ["预后", "原文未识脉名，仅言右脉未静，右脉候气，未静示余邪未清、气机未和。腑气畅下、表热得解，但口味不清、舌津未全回、搐搦止而不净，余邪尚有逗留。本体虚弱，时近大节，故预后须慎饮食寒暖，防借因生端。", []], "9214": ["病机", "脉细数而软，细主阴伤，数主热，软主虚。虚体邪郁，温邪不易外解而易传里，发热不退、焦寐不安、喃喃自语、手指搐动、舌白黄少津，为邪郁化热、阴液受灼、内风欲动。故拟泄火救阴、解肌透邪。", ["细", "数", "软"]], "9215": ["预后", "脉细软，细主阴血不足，软主气虚。表热退净、流注得消、舌津已回，均为佳象；但胃纳微、体本不充，脉细软示正气未复。时近夏至，故须珍重起居，方宜参调理法，以培补正气、渐图强健。", ["细", "软"]], "9216": ["病机", "脉来濡为气弱之象，濡主湿、主气虚。原文谓“气弱易积痰湿，阴薄易动心肝”，说明表症虽退而气阴未复，气虚则运化无力而痰湿内积，阴亏则心肝易动，故寐中惊惕自语、舌津不足。脉濡正合气弱湿滞之机，治宜清理调理兼进。", ["濡"]], "9217": ["预后", "原文仅言“脉状较昨稍畅和”，未出具体脉名，属脉象描述。较昨畅和说明气机渐得舒展，与“表症初得清解”相应，虽气阴未能遽复、寐中惊惕神思未振，但脉渐和畅、疡患得消，故断“可无他虑”，主预后向安。", []], "9218": ["病机", "脉右弦，右候脾胃，弦主气机不和、营分郁滞。原文谓“中气素弱，营分不和”，外疡虽消而内热未尽，胃气尚能知饥味，然脉右弦示中气弱而营分未和，余热郁于内。治宜存阴养胃、泄余热，正合弦脉所主之气郁营不和。", ["弦"]], "9219": ["病机", "脉状弦数，弦主邪滞郁阻，数主热盛。原文谓“邪滞郁阻未达”“阴分先伤”，复病伤阴，表热得汗不解，神志似昧、谵语指搐，皆邪郁化热、阴伤风动之兆。弦数并见，说明邪热内郁而阴液已亏，势恐陷逼厥少而起风动之波，故言其势颇重。", ["弦", "数"]], "9220": ["病机", "脉右软左弦数，右软为正气疲惫、中气不足，左弦数为肝经虚火内动。原文谓“因虚生火，火甚劫阴，阴乏生风”，复病发热而热不大壮，正虚阴匮，惊惕抽掣、神倦嗜卧，舌干光有白糜点，皆虚火劫阴、阴亏风动之候，故脉右软左弦数。", ["软", "弦", "数"]], "9221": ["预后", "原文未识脉名，仅言“脉状模糊”，属纯描述。脉模糊说明正气溃散、邪闭心包，与“正不敌邪，邪火劫津动风”相应，一身振惕搐搦、神昏热壮舌缩而干，病涉厥少，故防内闭外脱，断为“势实危急之至”，主预后凶险。", []], "9222": ["预后", "原文仅言“脉状较昨为和”，未出具体脉名。较昨为和说明邪退正渐安，与“复热幸已退清，肝风瘛疭亦得平静，舌糜大减”相应，虽津液未复，但脉渐和缓，故预后向善，嘱“格外珍卫，勿令寒热往来为要”。", []], "9223": ["病机", "左脉弦而不散，右脉软数。弦为肝脉，不散示内风虽平而肝气未和；软数为右脉，主气弱而有热。原文谓“营卫未能调畅”“阴损已极”，热退神清而脉尚弦软数，说明营卫未和、阴亏未复，最防往来寒热，又虑胃气不复，故宜慎护。", ["弦", "散", "软", "数"]], "9224": ["病机", "脉数而舌光淡少血色，数非实热，乃虚阳浮动之象；舌淡少血示气血两亏。原文谓“所虚已甚，表分不固则多汗，正气内乏则神思疲惫”，脉数正合虚体气不内守、营血不足之机，故主正虚不固、气血俱乏之病机，与多汗、神疲、运用不健相应。", ["数"]], "9225": ["病机", "脉微数软，微为阳衰，软为气弱，数亦虚性之数；合“肢冷畏寒，汗出不已，舌全光，头胀”，显系阳气式微、卫外不固、阴液亦亏。原文断为“一派虚象”，强调虽有小感冒仍以扶正为要，故此脉主正虚阳弱、表卫不固之病机，防猝起虚波。", ["微", "数", "软"]], "9226": ["预后", "进“气阴两补法”后，脉仍软弱至甚，软弱为气血未复之征；然“舌津得回，虚汗得定，头痛渐止”，是阴津渐复、虚阳渐敛。脉象未起而症候转安，说明正气虽弱尚能受补，故原文谓“循法善调，以御风波复起”，此段重在以脉症合参判断预后调护。", ["软", "弱"]], "9227": ["预后", "原文仅言“今脉尚静”，未著具体脉名，故脉象要素从缺。“肌灼头胀藉汗而解”后脉静、舌苔润，是邪随汗解、里无燥热之象；惟“本体素虚，一时不能复原”，又当溽暑薰逼，故脉静示邪退而正未复，主症情稍安、须慎调防复之预后判断。", []], "9228": ["病机", "左脉弦数、右软，弦数为肝胆热盛、阴伤风动，软为虚体不胜病。原文见“舌干光无津液，有糜点，寐即指搐手动”，是热灼阴液、虚风内动之候；大便不通、迷蒙嗜卧，皆阴亏热结所致。故脉主阴虚热炽、肝风内动之病机，原文谓“颇有可虑之处”，姑进救阴泄热。", ["弦", "数", "软"]], "9229": ["病机", "脉弦主邪郁络脉、气机不畅。原文述“表热两作，旋即口渴不已，肩肋酸痛入腹”，是温邪久羁伤阴，由表入络，阴伤而络气痹阻，故脉见弦。弦为温邪伤阴入络、经气不利之象，与口渴、肩肋酸痛入腹相应，治当表里分解。", ["弦"]], "9230": ["病机", "脉数不畅，数为邪热内郁，不畅为气机壅遏、表气不达。原文“左昨起寒热，头胀”，是外邪初袭、郁于表分，热为邪郁而不得宣畅，故脉数而不流利。此脉主邪郁表分、气机不畅之病机，与寒热、头胀相应，故用疏达法以宣透。", ["数"]], "9231": ["病机", "脉带弦数，弦属肝胆，数为热象。原文谓“湿热未楚，舌苔黄”，是湿与热合，郁于肝胆，肝胆之火偏亢，故脉弦而数。此脉主肝胆火旺、湿热未清之病机，与舌苔黄相应；治须清化分利，使肝胆之火与膀胱之湿各得平靖。", ["弦", "数"]], "9232": ["预后", "原文述“脉状未静”，虽未明指脉象，然疟疾初止而脉未静，示营卫未和、余邪未清，故所病未清。脉象不静反映正气未复、邪气留恋，须防反复。兼肝肾不足、风湿痹络，左腿痛酸，亦须速解以防结疡。此段重在预后判断，强调脉未静则病未愈。", []], "9233": ["主病", "脉数主热，此段头痛发热渐愈而肢冷畏寒尚甚、咳嗽痰多，脉数说明余热未清，痰热内蕴。数脉为热象，与咳嗽痰多相应，故以六安煎加减化痰清热。肢冷畏寒虽在，脉数则热未全退，不可纯温。", ["数"]], "9234": ["病机", "脉弦主肝旺、气机不畅。积滞已解而运化未醒，脉弦示肝木乘脾、气机未和。本体不充、素有湿热，弦脉亦主饮主痛，反映湿热内蕴、脾运不健。故当标本两治，既健脾化湿，又调肝理气。", ["弦"]], "9235": ["病机", "脉数转弦，数主热，弦主肝亢。头痛久不止、骨痛，阴薄肝亢，外受风邪，脉数转弦示热郁而肝阳偏亢、风邪外袭。弦为肝脉，数则为热，合见阴虚肝旺兼风，故拟清理风热、再培其本。", ["数", "弦"]], "9236": ["病机", "脉数主热，频咳不畅、夜来寒热，为风温留恋肺经，热邪内郁。数脉反映温邪未透，肺气不宣，故非透达不可。风温在肺，脉数而咳，当以透邪外出为要。", ["数"]], "9237": ["病机", "脉濡主湿、主虚，风痹后复原未足，脉濡示气血未充、风湿痰浊留滞。濡为湿象，亦见虚软，故当和气血、解散风湿痰浊。此脉反映正虚湿滞，痹阻未清。", ["濡"]], "9238": ["主病", "脉数而不畅，数主热，不畅示表邪郁遏。寒发热、头痛无汗、咳嗽鼻塞，为表邪外束，卫阳被郁，故脉数而不畅。宜疏散表邪，使邪从表解，脉自和畅。", ["数"]], "9239": ["预后", "脉弦细，弦主气滞、细主阴伤。胁刺痛、温痛，病甫得解表，未净之邪壅气作呃，脉弦细示邪壅气滞而阴血不足。病情尚在险途，仍防变迁，弦细脉反映正虚邪恋、气机壅塞，故预后须慎。", ["弦", "细"]], "9240": ["病机", "脉濡主湿，濡为湿邪困阻、气血运行不畅之象。原文左湿痰咽腻、劳伤骨痛并见脉濡，说明湿痰内蕴、劳伤耗气，湿性黏滞故脉气软弱而浮。稍有感冒，外邪引动内湿，故治当兼顾，不可单治一端。", ["濡"]], "9241": ["病机", "脉弦软，弦为气机郁滞、木旺乘土，软为正气不足、体虚之象。原文恶寒发热久不止而脉弦软，说明外邪留恋、本体内乏，正虚不能驱邪外出。弦而不劲、软而不弱，正合虚中夹郁之机，故言本体内乏未可忽视。", ["弦", "软"]], "9242": ["病机", "脉数主热，原文热势交暮为甚、舌白黄垢、口腻烦躁，皆邪热内蕴之征。脉数不甚鼓指，说明热邪虽盛而正气已伤，鼓动无力。大便溏泄、溲少不寐，为热扰心神、湿滞中焦。病未双透，正转重之时，示邪有内陷之势。", ["数"]], "9243": ["病机", "脉弦数为气郁化热之象。原文胃阳不振、泛酸、胃气呆木、大便溏，说明中阳不足、气机郁滞，郁久化热故脉数，气阻肝郁故脉弦。经郁气阻，木不疏土，胃失和降，故言未易奏效，需缓图气机。", ["弦", "数"]], "9244": ["病机", "脉滑数主痰热内盛。原文表热气急、舌糙黄、口干胸闷、便闭不寐，皆痰热壅阻、邪滞不通之候。滑为痰涎壅盛，数为热邪内迫，痰热交阻于胸膈，气机升降失司，故防塞逆变幻，须警惕痰热蒙窍之变。", ["滑", "数"]], "9245": ["病机", "原文自释软为脏阴亏乏，滑数为痰热有余。脉软滑数并见，说明正虚与邪实并存：阴亏则脉道不充而软，痰热内盛则脉形滑利而数。舌灰腻、口干咽燥、耳聋糊语、咳痰便闭，皆痰热蒙扰、阴液受灼之象，故言邪正交病、风波易起。", ["软", "滑", "数"]], "9246": ["病机", "脉数主热，原文形寒发热、头晕腹痛呕吐、舌白黄，为表邪未解、里热已生之候。数脉示热势内盛，呕吐腹痛为里气不和，形寒发热为表证仍在。表里同病，故当表里两治，不可偏执一端。", ["数"]], "9247": ["病机", "原文脉不畅，未识具体脉名，然脉不畅示气血运行受阻、邪郁不达。头重胸闷、表热、肢冷并见，说明邪郁肌表、气机壅遏，阳气不能外达四末故肢冷。病方鸱张，正气受困，邪势方盛，故变迁可虑，须防邪陷生变。", []], "9248": ["病机", "原文未识脉名，仅言“脉不畅”，提示痰湿内阻、表邪外束，气机不畅。左内阻痰湿，外感表邪，恶寒胸闷，舌黄，为湿郁化热之象。脉不畅反映邪阻气机，非虚非数，故防转重，勿忽。", []], "9249": ["病机", "脉数主热，左表热颇壮，胸闷咳，腹膨便溏溲少，为表热内传，湿热壅阻三焦。脉数示热势鸱张，病方发展，变迁易如反掌，故非轻症。", ["数"]], "9250": ["病机", "脉数主热盛，热经一候，胸闷便薄，少寐糊语，气急，舌糙黄起刺质红口干，为热入气营，阴伤津耗。脉数示邪热炽盛，非轻症，不敢忽视。", ["数"]], "9251": ["病机", "脉微数，微为阳浮，数为热，风邪伤卫，风性偏阳，卫亦属阳，以阳从阳，其气必浮，故夜来惊惕，咽痒咳塞窒。当专从上焦宣泄，勿使邪恋生波。", ["微", "数"]], "9252": ["病机", "左尺肤热脉盛躁者，病温也。温从热化，最易烁阴，舌白黄边尖绛，头痛胸次不适少寐，起经五日，正发越之时。脉盛躁示温邪热盛，阴分受灼。", ["盛", "躁"]], "9253": ["病机", "脉数不甚鼓指，温病由口鼻而入，首先犯肺，由肺达表，恶寒表热，热势不壮，头痛无汗，脘腹痞闷，二便俱少，夜烦少寐，舌黄口干，遍体痛。脉数不鼓指示热郁气分，湿阻不化，最防昏陷化燥。", ["数"]], "9254": ["病机", "脉数不大，恶寒发热已起六日，热势午后为甚，头胀痛胸闷，语言吃力，舌黄四末不暖，二便俱通。温邪恰交一候，脉数不大示热郁不宣，最防迁延转重。", ["数"]], "9255": ["病机", "原文未识脉名，仅言“脉不畅”，外寒内热，头晕胸闷，舌白黄口干，二便俱少，夜少安寐，遍体痛。温湿逗留，热不外达，脉不畅示湿遏气机，病势方张，变迁可虑。", []], "9256": ["病机", "原文谓「脉状尚能流利」，未出具体脉名，仅言脉气尚通利，说明湿郁虽困脾、遍体无力、知饥不能食、嗜卧、舌苔不清，然脉未至滞涩，湿浊尚未深锢，正气犹能流通。故病机为湿郁困脾、气机不畅，治以顺气疏中，先调气化湿，非虚损危候。", []], "9257": ["病机", "脉数不甚大，数主热，不甚大则热未炽盛，与「阳胜则身热喘粗、不得寐、咽痒咳窒、头晕胸闷」相应，示温邪郁于肺胃、热势方张而未化燥。脘拒按、便溏、溲热、舌白黄、口干作恶，为湿热挟滞交阻。病约八日正发越之时，脉数不甚大正是邪热欲透未透之象，极易化燥昏陷。", ["数"]], "9258": ["预后", "脉数不大而舌黄、口干少津、唇燥、脘腹拒按、二便俱少，数主热，不大则热郁不扬，津液已伤而邪滞未化。原文断「病势十分险恶，发越之变，可立而待」，正因脉不洪大而症见燥象，热郁津亏、邪无外达之路，故预后凶险，随时可生昏陷之变。", ["数"]], "9259": ["病机", "脉软主正气不足，与神疲嗜卧、一身无力、咳逆气急、痰多、咳则汗出、纳少相应，示体虚而中挟痰湿。舌根黄、前半少苔多裂纹，为阴伤而湿滞。脉软非实邪之象，乃虚中挟痰，气不摄津，故咳则汗来；体虚病深，最防痰壅作喘。", ["软"]], "9260": ["病机", "脉数主热，与热不退五日、汗得不足、咽间痰阻、舌黄垢、寐不安神相应，示温邪逗留肺胃，热郁而痰浊内阻，汗出不彻则邪无外解之机。脉数而痰阻舌垢，为湿热郁蒸、气分邪恋，故原文谓「最防逾后变幻」，虑其热久化燥内陷。", ["数"]], "9261": ["病机", "脉数不大，数主温邪在表，不大则热势未盛，与表热两日、遇风形浮、头胀胸闷、遍体不适、舌黄、咳嗽痰多相应，示温邪犯肺胃、表气不宣。脉数不大说明邪尚在肺胃气分而未深入，故宜肺胃两治，以防转重。", ["数"]], "9262": ["病机", "原文仅言「脉不大」，未出具体脉名，脉不大示邪未炽盛而正气尚能支撑。形寒表热、头晕口腻、胸闷腰痛、溲通便闭，为温邪与湿滞交结，表里气机不畅。脉不大而症见湿滞，说明邪郁未化热张，然原文谓「正在转重，勿忽」，示湿温逗留易生变。", []], "9263": ["病机", "脉弦数，弦主邪郁少阳、气机劲急，数主热盛，与尺肤热、脉盛躁、憎寒发热、热已七日不退、头痛胸闷烦躁、舌糙黄、口干渴欲饮、饮入复吐、寐则糊语相应，示温邪化热内郁、热扰神明。脉盛躁而弦数，为温病热盛邪实之象，故断为险重，昏厥易如反掌。", ["弦", "数"]], "9264": ["病机", "原文谓寒滞中阻、清浊相干、乱其中气，故见干呕水泻、时寒时热。脉数不大，数示邪扰、正气尚能鼓动抗邪，不大则邪势未至洪盛，与舌黄、溲少合参，属寒痧挟滞、湿浊内阻而化热未深之象，故称病方鸱张可虑。", ["数"]], "9265": ["病机", "脉弦数，弦主痰饮内结、气机壅滞，数主热盛。原文痰鸣如曳锯、气急鼻煽、咳不止，正是温邪痰热熏蒸肺胃，痰随热升、壅塞气道之候；溲少口干舌垢亦热灼津伤。弦数并见，示痰热胶结而热势方张，故极易痰升喘变。", ["弦", "数"]], "9266": ["病机", "脉濡数，濡主湿邪困阻、脉道弛缓，数主热郁。原文汗少热不退、胸闷、舌白口渴不引饮、溲少便不畅，皆湿温初候湿遏热伏、气机不宣之征。濡数相合，正示湿重于热、邪在气分，故谓病交一候、风翔浪飞之时。", ["濡", "数"]], "9267": ["病机", "脉濡数，濡为湿盛、数为热蕴。原文表热解而里蕴犹重，胸闷痞、便溏数次、溲少、躁不安寐、汗出溱溱，是湿温一候湿热内蕴、湿阻气机而热扰心神。濡数不去，示湿未化、热未清，故症情尚在险途，小效不足恃。", ["濡", "数"]], "9268": ["病机", "脉濡数，濡主湿浊黏滞、数主温热内郁。原文胸闷略松、便溏渐止、溲较利为湿有去路，然躁扰不宁、不得寐、有汗有矢气，示热为痰湿所裹、郁而未透。濡数并见，正合温热为痰湿所裹之机，故称出入关头、风波迭起。", ["濡", "数"]], "9269": ["病机", "脉数不大，数主温热内郁，不大则湿邪黏滞、热势未能张扬。原文表热不退、胸闷脘腹不适、便溏溲赤，皆湿温互郁、气机不畅之候。数而不大，恰示湿遏热伏、邪难透达，故谓温湿互郁转重可虑，非纯热亢盛之脉。", ["数"]], "9270": ["病机", "脉数主热，原文头痛头晕、咽关红碎、舌黄边尖绛、口渴引饮、百节烦疼，皆湿温化热、热灼营分之象；便溏溲黄则湿热下趋。数脉示热势已盛而湿未尽化，热蒸则易化燥内陷，故防化燥昏陷，与舌绛、躁扰相应。", ["数"]], "9271": ["病机", "脉数而溲少，数主温邪热盛，溲少示热灼津伤、化痰无源。原文热势颇甚、口干舌黄质绛、胸闷躁扰不宁、汗得不足，正温邪痰热熏蒸肺胃、热郁不能外达之候。数脉不退而津伤日甚，故极易化燥昏陷，风波易如反掌。", ["数"]], "9272": ["病机", "脉濡主湿，湿遏卫阳则发热不扬、汗少；湿困中焦则便溏溲少；湿郁化热则舌糙白黄。寒邪外束而体若燔炭，然脉不浮紧反濡，知湿邪偏盛、阳气被遏，病延六日正值发越之时，当从湿郁透解。", ["濡"]], "9273": ["病机", "脉软主虚，兼湿。头晕胸闷、心宕纳少、气急泛呕，为肝脾不和、湿浊中阻；腰酸带下，肾虚湿注。舌白亦湿象。原文断为肝脾肾同病、中挟湿热，脉软正示正气不足而湿邪留恋，故宜择要治之。", ["软"]], "9274": ["病机", "脉小弦数，小为湿郁，弦主郁滞，数主蒸热。舌灰垢、口苦、发热不壮、胸闷头晕，皆湿郁蒸热、表里同病之象。便通示里未结实。脉小弦数正合湿郁化热、气机不畅之机，故宜表里分治。", ["小", "弦", "数"]], "9275": ["病机", "脉数主热。病起六日热壮不为汗裹，舌黄垢、脘腹不适、便溏不畅、遍体痛，为温邪夹湿、热郁气分而表里俱病。数脉应热壮，汗不出则邪无外达之路，故宗温病银翘散主之，透表清里。", ["数"]], "9276": ["病机", "脉小弦数，弦数主邪热内炽，小示邪滞痰热胶结。舌糙黄灰垢厚边尖绛、口渴、便溏极臭、溲赤、糊语彻夜不寐，皆痰热熏蒸肺胃、邪入心包之兆。脉证相参，深恐陡然痉厥，故未敢忽视。", ["小", "弦", "数"]], "9277": ["病机", "脉弦数，弦主痰热郁滞，数主邪热未清。药后糊语止、舌垢化薄为小效，但热退不净、便闭、寐多梦纷坛，示痰热犹逗留气分与心包。脉仍弦数，说明邪势未衰，故防猝然厥变，不敢以小效为恃。", ["弦", "数"]], "9278": ["病机", "脉细数，细为素体不足、阴分已伤，数主湿热邪滞未清。大汗淋漓而脉不洪大反细数，是气阴两伤、邪热内恋之征；胸闷头晕、舌白黄、腿酸、寐则糊语，皆湿热逗留、易生波折之象，故戒毋忽。", ["细", "数"]], "9279": ["病机", "脉弦数，弦主痰热郁结，数主风温化热。表热三日但头汗出，为邪郁上焦、湿热熏蒸；口淡腻、舌白黄垢，示痰湿内蕴；二便俱通则里未结实。脉证合参，属风温痰热互郁，故防连热转重。", ["弦", "数"]], "9280": ["病机", "脉滑主痰，滑而不畅乃痰热壅阻、气机不展之象。原文谓「左痰热上升，神思迷糊」，痰热蒙蔽清窍则神思迷糊、健忘心乱；脉滑为痰之征，不畅示热郁气滞。故主痰热上扰、蒙蔽心脑之病机，治宜泄降。", ["滑"]], "9281": ["病机", "脉数主热，发热五日有汗不解，舌边糙、中根垢，示温邪在表里之间，热盛而津伤。脉数说明邪热亢盛、正邪交争，汗出不解则热不为汗衰，故宜解表疏里，表里双解以透邪泄热。", ["数"]], "9282": ["病机", "脉数不畅，数主热，不畅示邪阻气机。原文「温邪痰滞交蒸」，热为温邪，滞为痰阻，交蒸则胸闷不寐、气急、舌黄。脉数不畅正合痰热胶结、气机壅遏之机，故谓变迁可惧，防其内陷转重。", ["数"]], "9283": ["病机", "脉数主温邪内盛，暮夜更甚、胸闷、二便不利，示热与痰滞交结，腑气不通。脉数说明邪热鸱张，痰滞阻遏气机则二便不利、胸闷。原文断为「温邪痰滞交结，行将转重」，脉数正是热势方张之征，勿忽其变。", ["数"]], "9284": ["病机", "脉数主热，发热六日昼轻夜重、糊语，为温邪深入、热扰神明；胸闷便溏示痰湿内滞、脾胃受困。脉数说明邪热交蒸不解，故防转重。原文「温邪交蒸」四字点明热与湿痰相合，脉数即其热盛之应。", ["数"]], "9285": ["病机", "脉数不扬，数主热，不扬示邪郁气滞、热不外达。表热气急、心不食、舌垢，为温邪与肝气交阻，表里同病。脉数不扬正合邪热内郁、气机不宣之机，故原文谓「肝气而兼温邪，表里同病，不可忽」。", ["数"]], "9286": ["病机", "脉数主温邪化热，汗出式微、遍体烦疼、胸闷头痛咳嗽，示温邪挟痰湿滞蕴蒸肺胃。脉数说明热势方张，痰湿阻滞则汗出不彻、烦疼胸闷。原文谓「势方转重」，脉数正是邪热鸱张、病势进展之征，不可轻忽。", ["数"]], "9287": ["病机", "原文未识脉名，仅言「脉不畅」，故脉象要素从缺。寒湿滞中阻，胸脘闷塞、不欲食，脉不畅示寒湿凝滞、气机不畅、阳气不宣。寒湿困阻中焦，脾胃升降失司，故防增寒热，即防寒湿郁久化热或外邪再袭。", []], "9288": ["病机", "脉数主热，温邪痰滞蕴蒸肺胃，热势日盛，故脉数而大便不行、胸闷咳嗽。原文谓「行将化火转重」，数脉正是邪热内炽、化火之兆，热扰心神则无安寐，热灼津液则便闭，故不可泛视。", ["数"]], "9289": ["病机", "脉数不畅，数主温邪内蒸，不畅示肝气郁滞、邪不得透达。恶心发热不寐，乃温邪与肝气交争，气机壅遏，热扰心神。原文谓「势方转重」，数而不畅正是邪郁化热、正气受困之象，故不可忽。", ["数"]], "9290": ["病机", "脉数不畅，数主温邪，不畅主痰湿交郁、气机不利。发热八日便溏少寐，乃温邪痰湿互结，邪热内蒸而湿滞不化。原文谓「防正不胜病」，数而不畅示邪郁正伤，故须防病进。", ["数"]], "9291": ["病机", "脉数主邪热内盛，发热九日、口干溲少便闭，皆热灼津伤、邪滞交结之征。原文谓「邪滞交结，不可忽视」，数脉示热势未衰，邪滞互结则气机不通，故便闭溲少，热耗阴津则口干。", ["数"]], "9292": ["病机", "脉细数，细为阴血不足，数为邪热内蒸。发热九日胸闷不寐，乃体虚而邪热未解，正虚不能胜邪。原文谓「体虚病实，变迁可惧」，细数并见正是虚体实病、正不胜邪之象，故预后可虑。", ["细", "数"]], "9293": ["病机", "脉细主阴分亏虚，大便虽通而气坠腰脊作酸、小溲不流利，乃阴虚无以濡养，湿热下注阻滞气机。原文谓「阴分虚而湿热重，理之不易」，细脉示正虚，湿热重则气化不利，虚实夹杂故难理。", ["细"]], "9294": ["病机", "脉细数，细主正虚，数主温邪内蒸。表热恶寒胸闷头痛、舌灰黄、病起旬日，乃温邪痰滞交结，日久化热伤阴。原文谓「转重可虑」，细数示邪热未解而阴分已伤，痰滞交结则气机壅遏，故虑其转重。", ["细", "数"]], "9295": ["病机", "脉微数，微为正气不足，数主邪热未清。前病未清又恶寒发热、便溏腹痛，乃表邪未解、里气已伤。原文谓「宜解表疏里」，微数示正虚邪恋，故须表里兼顾，不可纯攻。", ["微", "数"]], "9296": ["预后", "湿温病十二日，脉滑数，滑主湿浊内蕴，数主热邪亢盛，湿热交蒸，故见头胀耳鸣、便秘。原文谓“正交两候之际，防陡然昏陷”，说明湿热郁蒸日久，有内陷心包、蒙蔽清窍之虞，脉象示邪势未衰，当警惕病情骤变。", ["滑", "数"]], "9297": ["预后", "发热呕吐、遍体烦疼、便溏胸闷，脉滑数，滑为湿浊，数为热象，湿热壅阻三焦，气机不畅。原文“防转重”，因湿热胶结，脉象持续滑数，示邪热未得透解，易致病情加重，须防湿热内陷或化燥伤阴。", ["滑", "数"]], "9298": ["预后", "湿温病将两候，四肢易冷、头痛胸闷、不得寐，脉数。数脉主热，热郁于里，阳气不达四末故肢冷；热扰心神则失眠。原文“形将转重”，脉数示邪热鸱张，有内陷厥阴、扰乱心神之势，故告诫“弗忽”。", ["数"]], "9299": ["治法", "发热畏风、头痛作泛、胸闷，脉数不畅。数主热，不畅示湿浊阻滞气机，热为湿遏，不得宣透。原文“宜透达泄化”，即针对湿温初起、邪遏卫气之机，治当宣透湿浊、泄化郁热，使邪从表解。", ["数"]], "9300": ["病机", "本体不充，无力运融痰湿，脉弦。弦主痰饮、气机不畅，因正气不足，脾运失健，痰湿内停，肝木失和，故脉见弦象。原文“宜标本两治”，提示既需补虚扶正，又须化痰运湿，标本兼顾。", ["弦"]], "9301": ["预后", "湿温旧病，发热不净、呕吐稍愈，脉滑数，伴骨痛胸闷。滑数示湿热余邪未清，仍蕴阻气分。原文“极易变迁”，因湿性黏滞，热性急迫，湿热胶结，脉象未趋缓和，故易生变证，须密切观察。", ["滑", "数"]], "9302": ["预后", "湿温病八日，热重于里，烦闷、脘肋痛，脉滑数，舌黑。滑数主湿热壅盛，舌黑示热灼阴伤或湿浊内闭。原文“正转重之时”，脉象滑数不减，邪热深入，有内陷营血、耗损真阴之危，故告诫勿忽。", ["滑", "数"]], "9303": ["病机", "湿温病后，发热稍衰，大便未行，舌黄垢质红，脉细数，右三部较大。细主阴伤，数主余热，右脉大示邪偏气分。原文“邪伏伤阴”，因热邪久羁，耗伤阴液，余邪伏于内，故脉细数，治须渐解散，不可峻攻。", ["细", "数"]], "9304": ["病机", "脉微弦而数，弦主邪郁少阳，数主热，微示正气已伤。原文谓湿热表邪蒸久伤阴，发热止作不定、时咳时呃、夜来口干、少寐，皆邪郁化热、阴液受灼之象。表病传里，正虚邪恋，故脉虽数而微，非纯实热可比，提示不易速效。", ["弦", "数", "微"]], "9305": ["病机", "脉弦滑数，右大于左，弦主邪郁，滑主痰湿，数主热盛。湿温十二日，热势夜甚、神思模糊、语言不清，是湿热酿痰、蒙蔽心包；大便未续下、舌干、胸闷口渴，为热灼阴伤、腑气不通。正届两候，邪正相争，险关防变。", ["弦", "滑", "数"]], "9306": ["病机", "脉滑数，滑主湿浊痰滞，数主热。寒战发热畅汗后便溏、胸闷呕吐转松，是邪有外达之机；但舌上灰黄垢，示湿热秽浊仍蕴结中焦未净。脉仍滑数，说明里热未清，故虽小效，仍防变迁。", ["滑", "数"]], "9307": ["病机", "脉数主热盛，湿温两候，头晕耳聋、舌灰黄垢、疹㾦不多，是湿热郁蒸、邪热偏亢而透达不畅。疹㾦不多而脉数，示热邪内壅，有内陷之虞。原文谓风波方兴，勿以小效为恃，正虑热势鸱张、变证丛生。", ["数"]], "9308": ["病机", "脉濡滑，濡主湿、主虚，滑主痰湿内蕴。头晕、心慌手振、胸闷、夜来寒热，是湿浊中阻、清阳不升，兼有痰湿扰及心神。濡滑之脉与湿痰内盛相应，邪未透解，故延防转重。", ["濡", "滑"]], "9309": ["病机", "脉左弦甚于右，弦主气郁、主痰火。痰火气机扰乱神明，故语言不自主；近有寒热，是痰火郁于少阳、枢机不利。左脉弦甚，示病偏于肝胆气分，当治所急，先清痰火、疏畅气机。", ["弦"]], "9310": ["病机", "脉数不畅，数主温邪内郁化热，不畅示邪郁气分、未能透达。乍寒乍热旬日、汗少、胸闷头痛，皆温邪郁遏卫气、枢机不利之象。邪无外达之路，故脉数而不畅，变迁可惧。", ["数"]], "9311": ["病机", "脉数主热，乍寒乍热十二日、胸闷头蒙，是温邪郁于气分、湿热交蒸，邪正交争而寒热起伏。脉数示里热偏盛，邪郁未透，故转重可虑，当防热势鸱张、内陷生变。", ["数"]], "9312": ["主病", "脉数主热，此段寒热并见而脉数，说明表邪未解、里热已生，故见寒发热、胸闷；热迫大肠则大便溏泄。脉数为里有热之征，与表证同见，示表里同病，故宜表里两解。", ["数"]], "9313": ["病机", "湿温十二日，表热内伏，便闭脘次不通，舌黄，脉不畅。脉不畅非虚，乃湿浊痰热壅阻气机、脉道不利之象。湿温久羁，热为湿遏，腑气不通，故脉不畅而见闭结，拟通导下法以泄壅滞。", []], "9314": ["主病", "脉细主气血不足，亦主湿邪阻络。风邪入络，四肢骨节肿痛，脉细者，风与痰湿痹阻，营血不能充脉；曾痰中带血，阴血已伤。细脉示正虚邪恋，故泄风宣络之中当顾营血。", ["细"]], "9315": ["主病", "脉数主热，寒发热解而不净，脘次不畅，腰痛，乃表邪未尽、里热未清。数脉为余热内蕴之征，热郁气机则脘不畅，腰为肾府，热邪波及则腰痛。表里同病，故宜表里两治。", ["数"]], "9316": ["病机", "脉数不畅，数主热，不畅主气机壅遏。胃脘作痛、恶寒热不透，乃表邪欲陷、里热与痰湿交阻，热郁而不能透达，故脉数而不畅。此非纯表纯里，乃表里气机失疏，宜解表疏里以透达郁热。", ["数"]], "9317": ["病机", "脉弦主气机郁滞、风动及痰饮。口味不醒、大便不下，乃肝脾不调、气郁津亏；左半体作麻，为风痰入络、营血不充。弦脉示肝风内动、络脉痹阻，故拟养营润肠、泄风宣络。", ["弦"]], "9318": ["病机", "脉数不畅，数主热，不畅主湿痰壅遏。发热旬日，胸闷脘阻，口干气急，舌灰白黄，显系湿温痰滞交结，热为湿郁，气机不得宣畅，故脉数而不畅。宜透㾦疏中，使湿痰热邪外达。", ["数"]], "9319": ["主病", "脉数主热，寒发热稍愈而胸闷、咳嗽恶心、心中热，乃表邪渐解而里热未清，痰热内扰胸膈。数脉示热邪内蕴，故见心中热、咳嗽恶心。虽寒热稍愈，脉仍数，示里热未除，故嘱重症勿忽。", ["数"]], "9320": ["预后", "脉数主热盛，旬日表热不退，神思迷蒙、糊语口干、咳不畅、舌灰黑，为热邪内陷、阴液耗伤之象。数脉示邪热炽盛而正不胜邪，故防正不胜病，预后堪忧。", ["数"]], "9321": ["病机", "脉弦数，弦主气机郁滞，数主热。左热半月、便秘，为温湿蕴蒸，热结肠腑，气机不畅。弦数并见，示湿热郁蒸而化火，故延防变迁，恐生他变。", ["弦", "数"]], "9322": ["病机", "脉弦主肝气郁滞，胸闷气短为肝肺升降不调，痰湿阻滞气机。弦脉应肝，肝失疏泄则肺气不降，痰湿内蕴，气机未能流利，故见胸闷气短。", ["弦"]], "9323": ["预后", "湿温十二日，化火伤阴，舌焦干灰黄、脉数，为热盛阴伤之候。无汗、糊语、便闭，示邪热内陷、阴液将竭。数脉主热炽，正虚邪盛，故防厥陷之危。", ["数"]], "9324": ["治法", "左脉弦主肝郁，右濡主湿滞。湿温内敛，大便溏、寒热不透、胸闷痰多，为表里同病、湿遏气机。弦濡并见，示肝郁湿阻，故宜表里两解，疏肝化湿。", ["弦", "濡"]], "9325": ["主病", "脉数主热盛，肚热四日、气急肋痛、舌灰黄，为热邪壅盛、气机不利。数脉示邪热炽盛，气急肋痛为热郁肺肝，故属重症，弗可忽视。", ["数"]], "9326": ["预后", "脉滑数，滑主痰湿，数主热。寒热复发、便阻、胸闷少寐，为阴伤邪恋、痰热内扰。滑数示邪热痰浊交结，阴液已伤，故防陡然昏厥，万弗忽视。", ["滑", "数"]], "9327": ["病机", "脉数主热，表热胸闷、头胀，为湿温痰滞交结，热邪与痰湿搏结，气机不畅。数脉示邪热方张，痰滞未化，其势方张，故弗忽。", ["数"]], "9328": ["病机", "原文言幼风邪湿热壅肺气阻、表热不达，气急一身尽肿而脉数。数脉主热，热为邪郁，肺气壅塞则气急，表热不能外达而尽肿，故脉数示邪热内壅、肺失宣降之病机，症见气急浮肿，防喘塞生波，即防痰热闭肺致喘。", ["数"]], "9329": ["病机", "原文谓左风湿痰入络，左半体作麻，筋络之间不能速效，胃口呆滞、痰吐不流利而脉弦。弦脉主痰饮、主络脉拘急，风湿痰阻于经络则气血不行，故半身麻木、痰滞难出，脉弦正应痰湿入络、筋络不和之机，故宜先清理痰湿。", ["弦"]], "9330": ["病机", "原文载发热三日、汗少、胸闷恶心、头晕而脉濡数。濡主湿、数主热，湿热郁蒸于内，故发热汗少；湿阻气机则胸闷恶心，清阳不升则头晕。脉濡数正示湿热内蕴、气机不畅之病机，原文断为势在转重，须防湿热蒙蔽加重。", ["濡", "数"]], "9331": ["预后", "原文言发热十二日、舌黑、体乏、病实而脉数。数脉主热盛，热久不退则阴伤，舌黑为热深之征，体乏示正气已耗而病邪仍实。脉数于此示邪热鸱张、正虚邪实之病机，故最防晕厥，即防热盛内闭、正气不支而昏厥，属险候。", ["数"]], "9332": ["病机", "原文述复发热、头痛恶心、腹痛腰痛、腿络抽掣而脉数。数脉主热，热邪复炽则发热；热扰清阳则头痛恶心，热壅气血则腹痛腰痛，热灼筋络则腿络抽掣。脉数正示热邪内盛、气血壅滞、筋脉失养之病机，故原文称重症毋忽。", ["数"]], "9333": ["病机", "原文谓身热作躁、自汗而脉数，断为温邪痰湿交蒸。数脉主热，温邪内盛则身热；热扰心神则躁；热迫津液则自汗。痰湿与温邪交蒸，邪热鸱张，故脉数而势不可忽，示湿热痰浊互结、邪热内盛之病机。", ["数"]], "9334": ["病机", "原文言幼壮热气急、口干弄舌、脚冷而脉数。数脉主热，热盛于内则壮热气急；热灼津液则口干弄舌；热郁于里，阳气不能达于四末则脚冷。脉数示时气郁遏、热不能外达之病机，故防厥，即防热深厥深、气机闭阻。", ["数"]], "9335": ["预后", "原文述湿温病三日，胸闷、烦躁不寐、便三闭泄、口干而脉不扬。脉不扬者，湿温之邪郁遏气机，脉道不畅，正气不能鼓动，故脉象不显扬。此示湿浊内闭、气机壅遏之病机，症见胸闷烦躁、二便失常，原文断为势极险重，毋忽。", []], "9336": ["病机", "脉状尚数，说明痰湿阻胃，郁而化热，热邪内扰，故不时作吐。数脉主热，痰湿为阴邪，郁久化热，脉数而吐，治须作速导之下行，以祛痰湿、清郁热。", ["数"]], "9337": ["病机", "脉细数微滑，细为阴伤，数为热，滑主痰湿。寒热不净、舌白带灰、咳嗽胸闷、心中烦热，乃痰湿内蕴、郁热伤阴之象。脉症合参，正邪出入之际，不可忽视。", ["细", "数", "滑"]], "9338": ["病机", "幼表热未净尽，小溲少，脉数，说明蕴热尚重，热邪未清，气化不利。数脉主热，热蕴于内，故表热虽减而未尽，小溲少为热伤津液、气化不行之征。", ["数"]], "9339": ["预后", "幼温邪内闭，气急神蒙，口干壮热，脉数，乃温邪内陷心包，热盛动风之危候。数脉主热盛，热闭心窍则神蒙，热灼肺金则气急，势将厥变，危急非常。", ["数"]], "9340": ["病机", "左发热，起初畏风，今交四日，舌黄，脉数，便闭，为湿温初起，邪从热化，里热渐盛。数脉主热，舌黄便闭为热结阳明之象，湿温转重可虑。", ["数"]], "9341": ["病机", "右乍寒乍热，有汗不解，脉数不畅，乃湿温重症。数脉主热，不畅为湿阻气机，湿热交蒸，故寒热起伏、汗出不解。湿温重症，勿忽。", ["数"]], "9342": ["病机", "左表热已解，里热未化，脉濡、舌白、胸闷，濡脉主湿，湿邪内蕴，气机不畅，故胸闷舌白。表热虽解，里湿未化，勿以热退为恃。", ["濡"]], "9343": ["病机", "左胸闷骨痛，发热便闭，脉数，为湿温痰滞交结。数脉主热，痰滞阻遏气机，故胸闷骨痛、便闭。湿热痰滞互结，转重可虑。", ["数"]], "9344": ["病机", "脉濡主湿、主虚。汗出不已而脉濡，是体虚卫外不固，湿邪留恋不去，正虚邪恋之象。濡为软而浮细，示气血不足而湿滞，故原文断为“体虚邪恋，不可忽视”，提示不可纯攻，须顾护正气兼化湿邪。", ["濡"]], "9345": ["病机", "脉实弦，实主邪盛，弦主郁、主痛。温邪为湿热所恋，发热不解而胀、神疲，脉见实弦，说明湿热郁阻气机、邪势尚盛而正气已困。原文“延防转重”，正因实弦之脉示邪郁不解，恐湿热久恋转生他变。", ["实", "弦"]], "9346": ["预后", "幼肺闭喘急稍平而壮热尚甚、神蒙口干，脉数。数脉主热盛，热邪内陷心营则神蒙，热灼津伤则口干。喘虽稍平而壮热脉数不退，示邪热鸱张、阴液已竭，故原文断为“危阴已极，挽回不易”，属预后险恶之候。", ["数"]], "9347": ["病机", "脉弦主郁、主痛。肢体无力、胯间结核、背脊痛而夜肌灼热，脉弦，是阴气内乏而温湿互郁，络气不通所致。弦为气机郁滞之象，阴亏则筋脉失养，湿郁则络阻作痛，故原文谓“阴气内乏，温湿互郁”，当标本两治。", ["弦"]], "9348": ["兼症", "脉濡主湿。胸次渐松而小溲热赤，脉濡，是湿热郁于下焦、气化不利之象。濡脉示湿邪黏滞未化，湿热下注则溺热而赤。原文“宜疏利二便，以通湿热”，正合濡脉所主湿滞、二便不利之兼症。", ["濡"]], "9349": ["预后", "脉数主热盛。湿温两候，胸闷神躁、糊语，脉数，是湿热化燥内陷心营、热扰神明之象。数脉示邪热炽盛而正不胜邪，故原文谓“势甚凶凶，不可忽视”，提示湿热有内闭外脱之虞，预后堪忧。", ["数"]], "9350": ["预后", "脉数主热。湿温病八日，适值经行而胸闷，脉数，是湿热内蕴、热势未衰之象。经期气血下注，正虚而邪易内陷，数脉示热盛不解，故原文断为“正在转重，不可忽视”，提示病情有增重之势。", ["数"]], "9351": ["病机", "脉弦主郁、主痛。骨痛稍愈而神疲、肌肤灼热，脉弦，是阴气不足、风湿热互郁于营络之象。弦示气机郁滞、络气不通，阴亏则肌肤失养而灼热，故原文谓“阴气不足，风湿热互郁”，治当清化营热、宣通络气。", ["弦"]], "9352": ["病机", "风水病后脉濡，濡为湿象，主湿邪未净、脾运不健。两足易冷、行步少力，乃湿阻阳气不达下肢，本原已虚。故治宜清理余湿之中稍顾本原，脉濡提示湿滞与正虚并存。", ["濡"]], "9353": ["预后", "表热渐解而脉数不退，足膝痛、便闭、舌黄，示邪热入里、壅滞经络腑气。脉数主热盛，热未清则病势易反复，故防反复生波，非单纯表证。", ["数"]], "9354": ["病机", "脉微弦，弦主少阳枢机不利、邪正交争。右寒热复来，乃旧恙未楚而新邪复乘，正虚邪凑，枢机失和。脉微弦提示病势尚浅但未解，须慎防传变。", ["弦"]], "9355": ["预后", "脉数而不畅，数主热，不畅示气机壅遏。脘腹痛、得食即吐、胸闷寒热，乃邪阻中焦、升降失司。脉数不畅提示热郁气滞，势在转重，勿忽。", ["数"]], "9356": ["病机", "脉滑主痰湿内蕴。素易心慌惊悸，今四肢麻木、溲短，乃湿痰阻遏气机、痰饮凌心、阳气不达四末。故宜化湿痰、顺气机，脉滑为痰湿之征。", ["滑"]], "9357": ["治法", "发热七日，夜热尤壮，咽痛口干，脉数，为热邪内盛、阴分受灼。脉数主热，夜热壮示热入阴分。治宜引邪外达、导热下行，使热有出路。", ["数"]], "9358": ["预后", "身热便闭、腹不舒、骨痛、舌干糙黄，脉数，示热邪壅盛、腑气不通、阴津受灼。交十一日而脉数不退，热势未衰，故防转重。", ["数"]], "9359": ["病机", "脉濡主湿，胸闷胃呆、腹胀乃湿阻中焦、气机不畅。濡脉示痰湿内蕴、脾运失健，故拟流利气机、疏畅痰湿，使湿化气行则胀闷自除。", ["濡"]], "9360": ["病机", "脉濡主湿，湿浊中阻，气机不畅，故见左胸脘闷塞、不能食；湿遏卫阳则恶寒，湿浊内扰则少寐。原文以“脉濡”点出湿邪黏滞之性，治宜透达疏化，正是针对湿郁气滞、表里不和之机，非虚非寒，重在化湿畅中。", ["濡"]], "9361": ["病机", "脉软弦，软为不足，弦主肝郁气滞。原文“肝气撑胀，风湿痰交郁”，说明肝失疏泄、气机壅滞，兼风湿痰浊互结，故头痛胸闷、痰腻神疲。软脉示正气已伤，弦脉示郁滞未解，虚实夹杂，故防寒热而须慎养。", ["软", "弦"]], "9362": ["病机", "脉濡滑数，濡主湿，滑主痰，数主热，合为湿热痰浊内蕴之象。原文胸闷减而头晕发热、口苦少寐如昨，说明表邪未净、里热痰湿尚存。脉数示热势未退，濡滑示湿痰黏滞，故拟再治表，透邪化湿并行。", ["濡", "滑", "数"]], "9363": ["病机", "脉弦滑，弦主风动，滑主痰湿。原文“营虚生风所致”，营血亏虚则筋脉失养，虚风内动，兼痰湿流注经络，故右手举动作痛、肩臂尤痛。弦滑之脉正合风痰阻络、营虚不荣之机，痛处固定而动作加剧，属虚实兼夹。", ["弦", "滑"]], "9364": ["病机", "原文“脉不畅”，未识具体脉名，然脉不畅示气机郁滞、邪阻不透。触痧之后便泄不已、胃气不来、胸闷溲赤、表热不透，皆因痧毒内陷、湿浊困阻、气化不利所致。脉不畅与表热不透相应，说明邪无外达之机，治宜疏化以畅气机、透邪外出。", []], "9365": ["病机", "脉重按带滑，滑主痰食积滞。原文腹膨胀、得食痛、气攻心脘，说明食积痰浊内阻，气机壅塞不通，重按始见滑象，示病位偏里、积滞较深。气攻心脘为浊气上逆，腹胀得食痛为积滞不化，故宜顺气疏中以消导畅中。", ["滑"]], "9366": ["病机", "脉软濡，软主正气不足，濡主湿邪黏滞。原文“本体不充，湿滞留恋”，说明素体亏虚而湿浊内蕴，正虚邪恋，故寒热日暮为甚、口腻咳嗽。软濡并见，示湿遏阳气、脾运不健，湿性黏腻故一时不易奏功，属虚实兼夹、缠绵难解之候。", ["软", "濡"]], "9367": ["预后", "脉弦数，弦主热郁厥阴，数主热盛。新产四朝瘀阻未行，湿温热壮，舌干糙、糊语、腹痛下痢，脉弦数示热毒鸱张、内陷营血，有动风厥变之势。原文“十分危险，防厥变”，正是据弦数之脉判断邪热亢盛、阴液耗伤、肝风欲动之危候。", ["弦", "数"]], "9368": ["病机", "脉软数，软为湿郁，数为热象，合之乃郁火湿热内蕴。原文“右咽间干热，头痛痰腻，心中懊恼，小溲热”皆湿热郁蒸、火性上炎之症。湿热郁于上焦则咽干头痛痰腻，扰于心神则懊恼，下注则小溲热。脉软数正应湿热郁火为患，非单纯虚数。", ["软", "数"]], "9369": ["病机", "原文“脉不畅”为脉气郁滞之象，非具体脉名。肝阳鼓动痰浊，痰浊阻遏气机，故脉来不畅。症见不时头晕、心荡惊恐，乃肝阳上扰、痰浊蒙蔽心神所致。脉不畅反映痰浊内阻、气机不利，故治宜平肝涤痰以畅脉气。", []], "9370": ["病机", "脉弦数，弦主湿郁气滞，数主热蒸。原文“身热恶寒，头痛胸闷，大便闭，不寐，舌黄”为湿温蒸热之候。湿温初起，湿热郁遏卫气则身热恶寒，上蒙清窍则头痛胸闷，热灼津液则便闭，热扰心神则不寐。脉弦数正示湿热蒸腾，防其转重。", ["弦", "数"]], "9371": ["病机", "脉濡主湿，为风湿相搏之象。原文“一身肿胀”乃风湿外袭，湿性弥漫，水气泛溢肌肤所致。濡脉示湿邪偏盛，气机为湿所困。风湿相搏，水湿不化，延防作喘，因湿邪上逆犯肺则喘。脉濡与肿胀并见，确为风湿为患。", ["濡"]], "9372": ["病机", "脉滑数，滑主痰湿，数主热。原文“湿温病一候，胸闷咳痰，不得寐，口干舌黄”为湿热酿痰、痰热内蕴之候。痰热阻肺则胸闷咳痰，热扰心神则不得寐，热灼津伤则口干舌黄。脉滑数正应痰热交蒸，故称重症毋忽。", ["滑", "数"]], "9373": ["病机", "脉数不畅，数为热，不畅为气机郁滞。原文“肺胃伏热”点明热伏肺胃，郁而不宣，故脉数而欠流利。热伏于内，不得外达，故治拟导热下行，使火不流为患。脉数不畅正是伏热郁遏、气机不宣之征。", ["数"]], "9374": ["病机", "脉濡主湿，原文“寒湿蒙遏清阳”明言寒湿为患。寒湿困阻阳气，清阳不升则神疲，湿浊内蕴则腹胀，湿溢肌肤则足肿滞。脉濡为湿盛阳微之象，寒湿久羁，延防中满，因湿困脾土，运化失职则胀满。", ["濡"]], "9375": ["病机", "脉软弦，软为湿盛，弦为暑湿郁遏气机。原文“发热十二日，舌黄、质红”为暑湿化热伤津之候。暑湿内蒸，热势缠绵，故发热日久不退；舌黄质红示热已入里。脉软弦正应暑湿郁蒸，防厥者，恐湿热蒙蔽心包而致厥。", ["软", "弦"]], "9376": ["病机", "脉滑主湿浊内蕴。左脉脱力久不复、纳少、胸腹不舒，为脾运失健、湿浊中阻之象；滑脉应之，说明湿邪壅滞气机，非虚证单纯可解，故治宜疏运化湿，以复中焦升降。", ["滑"]], "9377": ["病机", "幼童咳嗽、便溏、溲少、面浮，脉数，为风湿之邪郁于肺脾，数脉示邪热与风相搏、正气抗邪。原文谓“风湿尚非浅缈”，说明病邪未轻，数脉在此提示邪势尚盛，须防传变。", ["数"]], "9378": ["病机", "脉细主气血不足或湿阻脉道。右腹胀胸闷、气短、右腿酸，为肝脾不和、湿阻气机；细脉示正气偏弱而湿邪内滞，故拟疏肝和脾、化湿理气，标本兼顾。", ["细"]], "9379": ["病机", "脉弦主气机郁滞。气短胸闷、自汗神疲、舌碎腐作痛，为气郁日久化火，火性上炎而伤舌；弦脉应肝，示郁火内伏。原文谓“易于转重，勿忽”，说明弦脉在此提示病机有化火转重之势。", ["弦"]], "9380": ["病机", "右濡主湿阻营虚，左实弦不畅主肝郁气滞。营虚阴薄、肝脾两病，湿阻气机则运化迟钝，故大便不畅作泻、腹微痛、腰酸、日午头痛；濡弦并见，示虚实夹杂、湿郁并存，治宜疏化并进。", ["濡", "弦", "实"]], "9381": ["病机", "脉细主阴血不足。肝升胃热、头晕心荡、食下脘腹胀，为肝胃不和、阴血亏虚而气机上逆；细脉示正气已弱，故原文谓“一时不易奏功”，说明病机虚实夹杂，需缓图。", ["细"]], "9382": ["预后", "伏暑旬日，耳聋胸闷、神躁不寐、便溏、舌黄，脉数，为暑热内陷、邪正交争。数脉示热势鸱张，原文“防昏陷”，说明数脉在此提示邪热有内陷心包、昏愦陷脱之虞，属预后警示。", ["数"]], "9383": ["病机", "脉细主气血亏虚。头痛眩晕、食少易饱、肢节酸、胃气作痛，为脾胃虚弱、气血不足、清阳不升；细脉应之，示正气偏衰。原文“病繁当治所急”，说明细脉提示本虚为主，治当先顾脾胃之急。", ["细"]], "9384": ["病机", "脉数不畅，数主热，不畅为痰湿阻滞气机。痰湿中阻，脾胃交困，故胸闷不食、舌垢；郁而化热，故脉数。此脉象反映痰湿内蕴、气机不畅之病机，与胸闷不食、舌垢等症相应，治宜疏化。", ["数"]], "9385": ["预后", "脉伏为阳气内闭，不能鼓动血脉，见于转筋霍乱肢冷，乃暑湿秽浊闭阻阳气，大势危急。舌黄为内热之征，脉伏示邪闭正溃，防厥闭。此脉象提示邪闭心包、阳气欲脱之危候。", ["伏"]], "9386": ["预后", "脉伏而肢冷、音夺眶陷，为阳气衰微、邪闭内陷之象。转筋霍乱见此，乃暑湿秽浊闭阻，正气溃败，防内闭致脱。脉伏反映阳气不能外达，与肢冷、音夺眶陷相应，属危急之候。", ["伏"]], "9387": ["病机", "脉弦主气机郁滞、肝胆不和。病九日泻止呕停，但胸次未畅、心中犹热、舌灰黄，为余邪未清、气机未畅，郁而化热。脉弦与胸次未畅相应，示肝郁气滞、余热未清之病机，仍勿忽视。", ["弦"]], "9388": ["预后", "脉数带软，数主热，软为正气已伤。转筋霍乱初停，口干胸闷、汗多，乃暑热未清、气阴两伤。脉数示热未解，软示正虚，故防内闭外脱。此脉象反映正虚邪恋、有脱变之虞。", ["数", "软"]], "9389": ["预后", "脉左细、右弦数，细为阴伤，弦数为郁热。水泻三日不停，口干腹闷，乃泻伤阴液，肝脾不和，郁热内蕴。左细示阴夺，右弦数示热郁，故防阴夺。此脉象提示阴液耗伤、郁热未清之病机。", ["细", "弦", "数"]], "9390": ["预后", "脉不扬，即脉象沉滞不显，为暑湿秽浊闭阻气机、阳气不伸之象。转筋霍乱外象似定，但内暑未解，闷热如烧、脐肢痛、舌黄，脉不扬示邪闭正郁，防厥变。此脉象反映暑湿内闭、气机不畅之病机。", []], "9391": ["预后", "脉模糊如伏，为邪热内闭、阳气不能外达之象。壮热八日，神昏舌黄，脉模糊如伏，示热陷心包、闭阻阳气，防陡然厥陷。此脉象与神昏、舌黄相应，反映热闭心包、正虚邪陷之危候。", ["伏"]], "9392": ["预后", "原文谓“左伏邪病经久，恶款齐备，虚风大动，脉细如伏。危殆已极”。久病伏邪耗伤正气，虚风内动，脉道不充故细，邪郁气机不达故伏。细伏并见，是正虚邪陷、阴阳将竭之象，故断为危殆已极，勉拟方以尽人事，属预后不良之候。", ["细", "伏"]], "9393": ["病机", "原文言“右胆胃痰热不平”，致心无所依、神无所归、虑无所定，头胀蒙、惊惕。痰热内盛，脉道流利故滑，热邪鼓动故数。滑数主痰热，痰热扰及胆胃，上蒙清窍则头胀蒙，内扰心神则惊惕不定，故宜镇肝涤邪及痰。", ["滑", "数"]], "9394": ["病机", "原文谓“左肝胆痰热上亢，神机虚，语言易顿，夜少熟睡，惊惕，脉弦数”。弦为肝胆之脉，数主热，弦数相合示肝胆痰热上亢。痰热上扰，神机不运则语言易顿，扰及心神则少寐惊惕，故宜镇肝涤痰为法。", ["弦", "数"]], "9395": ["病机", "原文述“舌垢，发热不畅已旬日，糊语，不寐多梦，脉数。温邪痰湿交结蕴蒸”。数脉主热，温邪内蕴故脉数；痰湿交结，热为湿遏则发热不畅；痰热蒙扰心神则糊语、不寐多梦。脉数正示邪热蕴蒸之势，故谓变迁可虑。", ["数"]], "9396": ["病机", "原文云“表热留恋，腹瘕攻逆作痛，大便溏，纳少神疲，脉软。劳乏积湿所致”。软脉主虚，劳乏伤正、脾运不健则脉软；积湿内停，气机攻逆则腹瘕作痛，脾虚湿盛则便溏纳少神疲。脉软与诸症相合，正示劳乏积湿、正虚湿滞之机。", ["软"]], "9397": ["病机", "原文谓“腹满䐜胀，瘕撑食下阻。脉濡。肌肤发热。宜疏畅肝脾，流利湿热”。濡脉主湿，湿阻肝脾气机，则腹满䐜胀、瘕撑食阻；湿郁化热外蒸则肌肤发热。脉濡正合湿热内蕴、肝脾不疏之机，故治以疏畅肝脾、流利湿热。", ["濡"]], "9398": ["预后", "原文述“暑湿病已十八日，神识模糊，脉数不调，头晕，舌白黄。势防厥陷骤变”。数脉主热，暑湿久蕴，热邪内炽故脉数；脉不调示正气已乱、邪陷心包，故神识模糊。脉数不调与神糊并见，提示厥陷骤变之危，故戒毋忽。", ["数"]], "9399": ["病机", "原文谓“著凉停滞，加以春寒包里，阳邪外郁，遂致清不升、浊不降，悉被浑淆，吐泻交作，两腿弯转筋，舌垢，脉不扬”。脉不扬者，阳邪郁遏、气机不伸之象；清浊混淆则吐泻交作，筋脉失养则转筋。此属未至而至之春寒为病，脉不扬正合阳郁浊淆之机。", []], "9400": ["病机", "脉滑主痰浊内盛。原文言风邪痰浊鼓动肝阳，痰浊壅遏清窍则耳鸣重听、舌垢口腻；风痰流注肢体则遍体作酸。滑脉为痰湿内蕴之征，故治以平肝豁痰兼散风邪，脉滑正合痰浊为患之病机。", ["滑"]], "9401": ["病机", "脉数主热。原文述头胀痛、表热、喉关红、舌白黄、咽干、便闭溲少，皆温邪郁肺化热之象。数脉为热邪内盛、正邪交争之征，温邪郁肺不得透达，故虑其转重，脉数与温邪郁肺之病机相应。", ["数"]], "9402": ["病机", "脉濡主湿。原文言温邪外乘、湿热内阻，头胀蒙、遍体酸、胸闷，正合“因于湿，首如裹”之训。濡脉为湿邪困阻、气血运行不畅之象，湿热不攘则大筋软短、小筋弛长，神瘦嗜卧，脉濡紧扣湿热内阻之病机。", ["濡"]], "9403": ["病机", "脉数主热。原文述表热不净、汗多、起浆㾦、舌红少苔、口干、稍有咳，为温邪蒸郁化热、热盛伤津之候。数脉示热邪亢盛，温邪郁蒸不得透化，故宜泄化透邪，脉数正应其热郁之病机。", ["数"]], "9404": ["预后", "脉细软主正气亏虚。原文言幼发热得解后神思疲惫、痰嘶、四肢不暖，脉细软为气血不足、正气乏竭之征。病缠日久正虚，弱症渐著，故责效殊非易易，细软脉预示正虚难复之预后。", ["细", "软"]], "9405": ["预后", "脉数主热盛。原文述幼表热神迷、哭窒无泪、舌白口干、二便俱少，数脉示热邪鸱张、津液受灼。质小病重，热盛神迷而无泪，为正不胜邪之危候，脉数在此提示邪热炽盛、波澜莫测之预后。", ["数"]], "9406": ["病机", "原文未识脉名，仅言脉不畅。寒滞束伏肺胃，发热不扬、神迷气急、哭窒直喊、欲咳不出，脉不畅为寒邪闭遏、气血郁滞之象；脘部拒按、便溏溲少，皆邪滞交阻。小舟重载喻幼体不堪邪困，脉不畅正应寒滞闭伏之病机。", []], "9407": ["预后", "脉数主热。原文述表热较淡而舌黄垢、四维不暖、腹膨便闭，数脉示邪滞交结、郁而化热。表热虽淡而里滞未解，邪滞交结于内，故昏陷可虑，脉数在此提示邪郁化热、正虚邪陷之预后。", ["数"]], "9408": ["病机", "脉弦为肝风内动之象，原文引“诸风掉眩，皆属于肝”，左头旋目花、有眩仆之状，正是肝风上扰清窍所致。纳如常说明脾胃未伤，病机重点在肝，风痰上逆，故宜“肝涤痰”以平肝熄风、化痰降逆。", ["弦"]], "9409": ["病机", "脉数主热，暮发热、少汗泄、头胀、舌白黄，为湿热温邪逗留气分，邪热内蒸则脉数，热郁湿阻则汗少头胀。原文谓“湿热温邪，逗留防转重”，脉数反映邪热未清，有内传转重之势。", ["数"]], "9410": ["病机", "脉数不畅，数主温邪内郁，不畅为气机被滞所阻。恶寒发热、头胀痛、胸闷、便闭溲少、舌微黄口干，皆温邪挟滞交结、表里同病之象。原文谓“症属寒多热少，不可忽视”，脉数不畅正示邪滞交结、热势未透。", ["数"]], "9411": ["病机", "脉濡主湿，湿郁气阻则胸脘痞闷、口腻头胀蒙、恶寒微热、大便不畅。濡为湿邪黏滞、阳气不运之象，湿阻表里，气机不得宣畅，故原文断为“湿郁气阻”，治宜表里两解以化湿畅中。", ["濡"]], "9412": ["预后", "脉细小不大，为正气衰微、邪陷深沉之象。温邪不从表达，直陷厥少，神昏气鼾、舌黑垢、扬手掷足、脘拒按、矢气臭、便不行、溲自遗，皆邪伏深沉、正不胜邪之危候。原文谓“险如朝露”，脉细小正示正气无力托邪外出。", ["细", "小"]], "9413": ["预后", "痉后表热不退、无泪、咳窒汗多、膝间肿硬、满口碎腐，脉数主热毒内炽、阴液耗伤。质小任重，正虚邪盛，脉数示热势鸱张，有内陷厥闭之虞，故原文防其“厥闭陡变”，预后堪忧。", ["数"]], "9414": ["预后", "吐泻六日，败象齐备，虽泻减、肢冷得暖、气急平，但脉软为正气已衰、脾胃气弱之象，舌乾红、神气迷蒙示阴伤神扰。脉软无力，正虚难复，故原文谓“终恐发厥骤变，小效不足恃”，预后险恶。", ["软"]], "9415": ["预后", "泄泻起惊后，满口口糜、舌灰黄糙燥、胸闷肌灼、神蒙，脉数主热炽阴伤。胃阴大夺则舌燥口糜，肝火上亢则神蒙肌灼，脉数示邪热未衰，阴液难复，最防厥变，原文谓“势甚险恶”，预后不良。", ["数"]], "9416": ["病机", "脉软弦数，软为正气虚乏，弦主邪郁少阳，数示热炽。发热十七日而阴气大损，白㾦布而不绽、口干、足冷，皆虚体热郁、阴津耗伤之象；腑气未下、胃口不开，为邪滞未净、胃气不醒。脉证合参，属正虚邪恋、阴伤热炽之病机。", ["软", "弦", "数"]], "9417": ["病机", "脉数主热盛，表热四日而见头晕、胸闷烦躁不寐、舌糙黄、糊语、便闭腹拒按，是邪热与积滞交结于里，热扰心神、腑气不通。数脉应此邪滞交结之实热，故原文断为极易昏陷骤变，示热邪有内陷心包之势。", ["数"]], "9418": ["病机", "脉数主热。仲春腹痛、交夏失血，阴血已伤，近增咳嗽、午后形寒发热、舌白黄，为复感新暑之邪，暑热内郁而脉数。此非单纯旧病，乃虚体新暑相搏，故原文谓此复新暑也，当治所急，先清暑热。", ["数"]], "9419": ["预后", "脉如伏，为邪气深闭、阳气不能外达之象。转筋霍乱三日，冷汗、指甲紫黑、舌黄，是邪入三阴、阳衰阴盛、气血瘀滞。伏脉应此邪陷正溃之危候，故原文断为防骤然变端，属预后险恶之提示。", ["伏"]], "9420": ["病机", "脉细数而软，细为阴伤，数为热，软为虚体。病缠一候发热不退、喃喃自语、手指搐动、舌白黄少津，是湿邪郁而化热、劫灼阴津、内动肝风。虚体邪郁不易外解而易传里，故宜泄火救阴、解肌透邪，脉象正示阴虚热郁之机。", ["细", "数", "软"]], "9421": ["兼症", "原文未识脉名，仅言右脉未静。腑气畅下、表热得解后右脉未静，口味不清、舌津未回、搐搦止而不净，说明余邪尚有逗留，未全清化。右脉主气主脾，未静即气分余热未净之征，故须慎饮食寒暖，防借因生端。", []], "9422": ["病机", "脉左弦数、右软，左弦数为肝胆热郁动风，右软为气分虚弱。表热复来、迷蒙嗜卧、舌干光无津有糜点、寐即指搐、大便不通，是邪火劫津、虚体不胜病、肝风内动。脉证均不甚调，故谓复病可虑，姑进救阴泄热。", ["弦", "数", "软"]], "9423": ["预后", "脉状模糊，为正气溃散、脉道不清之象。复病发热、邪火劫津、动风振惕搐搦、神昏热壮、舌缩而干，病涉厥少，邪热内闭心包、肝风鸱张。模糊之脉应正不敌邪，故防内闭转外脱，势实危恶，属危重预后之判。", []], "9424": ["病机", "左脉弦而不静，是肝风内动未息、营阴不足而筋脉失柔；右脉软数，为胃气虚弱兼有余热。热退神清而脉未和，说明营卫未能调畅，故最防往来寒热复作；舌糜不退又示阴损已极，胃气难复，正虚与余热并存。", ["弦", "软", "数"]], "9425": ["预后", "原文仅言「脉状较昨为和」，未列具体脉象，故脉象要素为空。复热退清、肝风瘛疭平静、舌糜大减，脉亦转和，是邪退正渐复之兆；然津液尚未来复，故嘱格外珍卫，防寒热往来再起，属察脉以判预后。", []], "9426": ["病机", "右软为胃气虚弱，左弦数为肝经虚火内动。原文明言「因虚生火，火甚劫阴，阴乏生风」，正合此脉：虚火劫夺阴液则舌光干有白糜点，阴亏风动则惊惕抽掣、神倦嗜卧。脉不浮大而见软弦数，故非寻常表症，变幻极易。", ["软", "弦", "数"]], "9427": ["病机", "左大于右，是阴液亏而肝火偏亢、邪火劫夺阴液之象；右软数，为胃气虚弱兼热。宿垢畅下后神识虽清，而壮热、舌光干至甚、气促微汗仍在，脉左大右软数，正合「一派阴液为邪火劫夺之象」，故最怕正不胜病、猝然直陷。", ["大", "软", "数"]], "9428": ["病机", "脉软为正气内乏、气血不足之征，与舌光淡少血色相应。原文谓表分不固则多汗、正气内乏则神思疲惫、运融不健则得饮即肠鸣，皆虚体病后脾胃不健、气血两亏之象，故脉见软而不振，须格外加慎以图日起有功。", ["软"]], "9429": ["病机", "脉微软是阳气虚衰、气血不足之象，与舌全光胖、肢冷畏寒、汗出不已相合，原文径称「一派虚象」。起坐小溲后即肢冷汗出，说明正气虚馁、卫外不固，故虽小有感冒仍以扶正为要，否则猝虚生波，属虚证病机之判断。", ["微", "软"]], "9430": ["预后", "脉仍软弱至甚，是气血阴阳俱虚、正气未复之象，与遍体骨痛相应。进阴两补法后舌津得回、虚汗得定、头痛渐止，说明药合机宜而虚未骤复，故脉仍软弱；循法善调可望渐复，然须防风波复起，属凭脉判预后。", ["软", "弱"]], "9431": ["平脉", "原文仅言「今脉尚静」，未识具体脉名，故脉象要素为空。畅汗后肌灼头胀藉汗而解，脉静、舌苔润，症情安和，是邪解正安之象；惟本体素虚一时难复，当溽暑薰逼之际须格外加慎，此段以脉静印证病情安和，属平脉判断。", []], "9432": ["病机", "脉数不畅，数主热，不畅为邪郁不宣。罗新凉外乘，伏暑内发，热为寒遏，故发热无汗、头胀呕吐；暑热内扰心脘则烦热，舌黄带灰为热郁之征。脉数不畅正示邪热内伏、气机不畅之病机，势正发越，未可泛视。", ["数"]], "9433": ["病机", "脉右弦滑数，左细。弦主邪滞，滑主痰热，数主热，细为阴伤。伏暑未达，邪滞交结，故呕恶烦冤、汗少热不解；溏垢三下、胸腹较松为邪有下行之机。右脉弦滑数示痰热邪滞壅盛，左细示阴分已伤，急急表里两解为要。", ["弦", "滑", "数", "细"]], "9434": ["病机", "脉左弦数，右不大。弦主邪火，数主热盛，左脉应肝，邪火劫烁阴液，故壮热无汗、谵妄不寐、口干碎破起泡、舌绛苔少。右不大示邪热偏于厥少，阴液受灼。须从早化达，以防热入厥少，正吃紧之际。", ["弦", "数"]], "9435": ["病机", "脉数带弦，数主阳明邪热，弦主痰滞。热甚无汗、神昏谵妄、狂躁、唇燥齿干、口破疳腐、舌绛干灰苔，皆阳明邪热痰滞直逼厥少之象。脉数弦示邪热炽盛、痰滞交结，实恐昏厥内传，十分吃重。", ["数", "弦"]], "9436": ["病机", "脉弦数不调，弦主邪滞，数主热，不调为痰热郁蒸、气机失畅。虽表分颇解，里蕴痰热邪滞依然郁蒸不宣，故无汗泄、黎明烦冤、唇燥齿干、口碎、舌糙干白黄、耳聋目蒙。阴分已伤，深恐正不胜病，热陷变幻。", ["弦", "数"]], "9437": ["预后", "脉状不大，即脉不显大而反沉弱，为正气衰败之征。伏邪化热直逼厥少，神识昧多清少、掷足扬手、热深厥深、肢末发冷，恶象毕集。脉不大示正不胜邪，深恐厥陷陡变，故曰最不宜者莫如脉状不大，势实棘手。", []], "9438": ["病机", "脉数，重按少力。数主热，少力为阴分极薄、正气不足。伏邪病十一日，痰热极重而阴分极薄，表热留恋不净，神乏口干不引饮，舌糙黄质绛少津。脉数少力正示本虚标实、正不胜邪之病机，尚须慎之又慎。", ["数"]], "9439": ["病机", "脉弦数，左大于右。弦主邪滞，数主热，左大为邪热偏于厥少阴分。伏邪逾两候，既汗既下而痰热犹重、阴乏已甚，午后壮热、夜躁、耳鸣畏烦、神识清中略昧、舌根未退清。本虚标实，脉弦数示邪热未清，变幻易易。", ["弦", "数"]], "9440": ["病机", "脉细数带弦，细为阴液大夺、脉道不充，数为邪火痰热内逼，弦主厥少风动。原文“热缠两候，阴液大夺”致虚风内扰，故见不寐烦躁、风动谵语；便溏极臭、舌糙黄少津，皆痰热胶结、津伤之征。正不胜病，脉证相符，故言棘手。", ["细", "数", "弦"]], "9441": ["主病", "风温客肺，肺气上逆，故不能安卧而脉数。数脉主热，风温为阳邪，客于肺卫则肺失肃降，气逆而卧不安。原文“最防伤肺动营”，是热邪久羁易入营动血，故须静养以护肺阴，勿使热势鸱张。", ["数"]], "9442": ["预后", "咳逆、咽痒音闪，起经三月，脉不扬。脉不扬者，正气不足、邪陷不达之象，非脉象模糊可名。久咳三月而脉不振，示肺气耗伤、余邪留恋，故原文断“防纠缠不已”，即虑其迁延难愈，非言死候。", []], "9443": ["主病", "左受风作咳，表热自汗，脉数。数脉主热，风邪袭表，卫阳与邪相争则发热；表虚不固则自汗；风邪犯肺，肺气不利则咳。原文“宜从上焦泄化”，正合风热在表、肺卫失宣之病机，治当轻清宣透。", ["数"]], "9444": ["兼症", "右作寒、咳逆均减，是肺寒渐解；而舌红、口碎、腰腿抽痛、脉数，则示里热未清、阴伤风动。数脉主热，热灼津液则舌红口碎；热伤肝肾、筋脉失养则腰腿抽痛。原文“宜标本两治”，即外寒已减而内热阴伤并见，须兼顾本虚标实。", ["数"]], "9445": ["病机", "左咳痰如沫，脉来弦。弦脉主饮、主气机郁滞，痰如沫乃肺中寒饮或风痰之征。饮邪停肺，肺气不降，故咳而痰稀；脉弦应之，示饮阻气逆。原文“宜泄化宣肺法”，正合弦脉主饮、肺失宣降之病机，治当化饮宣肺。", ["弦"]], "9446": ["预后", "左阵呛、发热，脉软数。数为热，软为正气不足、脉道弛缓。发热而脉软数，示热势虽盛而正气已馁，肺气上逆则阵呛。原文“防喘塞生波”，虑热邪壅肺、气机闭塞而致喘逆，故脉软数见正虚邪盛，预后须防变。", ["软", "数"]], "9447": ["预后", "右寒微、热甚汗多、口干咽燥、咳嗽甚极，脉细软，形瘦色夺。细软为阴血亏虚、脉道不充，与形瘦色夺相应，示本体亏损。热甚汗多更耗津液，口干咽燥、咳甚皆虚热灼肺之征。原文“理之不易”，正谓虚损难复，脉证相合。", ["细", "软"]], "9448": ["病机", "原文述“音闪稍畅，咽干头痛，火升形寒。脉不扬”，脉不扬指脉象沉滞不显，为火郁于内、气机不宣之象。火升则咽干头痛，阳郁不达则形寒，脉气不扬正是郁火不得透达之征，故主病机为郁火上炎、气机不畅。", []], "9449": ["病机", "原文“幼蕴热恋肺，肺失清肃，咳呛阵作，二便俱热，口干，晨起头晕，灼热，语声重滞，脉数带浮”。脉数主热，浮主邪在表，数而带浮为热邪恋肺、表里俱热之象。热蕴于肺则咳呛，热灼津伤则口干、二便热，浮数之脉正合此病机。", ["数", "浮"]], "9450": ["病机", "原文“左体虚易感，不时背寒发热，咽痒咳窒，腰酸背痛，脉濡”。濡脉主虚主湿，为气血不足、湿邪内蕴之象。体虚易感、背寒发热为表气不固，咽痒咳窒为湿郁上焦，腰酸背痛为湿着经络，脉濡正合虚而兼湿之病机。", ["濡"]], "9451": ["病机", "原文“右温邪客肺，咳嗽，稍有表热，脉数”。数脉主热，温邪客肺，热郁于内，故脉数。咳嗽、表热为温邪犯肺、肺失宣降之症，脉数正是热邪内盛之征，法当泄化，即清泄肺热、透化温邪。", ["数"]], "9452": ["病机", "原文“左咳嗽稍平，满身痛，脉细”。细脉主虚，为气血不足、脉络不充之象。咳嗽稍平而满身痛，乃久咳伤气、营血亏虚、筋脉失养所致，脉细正合气血两虚之病机，故宜表里两治以调补兼疏。", ["细"]], "9453": ["病机", "原文“右脉细数，右弦，咳逆气急痰多，耳失聪，胃不醒，少寐。肺肾两病”。细数主阴亏火旺，弦主气逆痰滞。咳逆痰多、耳失聪为肺肾阴虚、虚火上炎，胃不醒、少寐为阴亏及中，脉细数弦正合肺肾两病、虚实夹杂之机。", ["细", "数", "弦"]], "9454": ["病机", "原文“左咳逆音闪，脉数。气火上浮，法宜泄降”。数脉主热，气火上浮，故脉数。咳逆音闪为气火上冲、肺失清降所致，脉数正是火升之征，法宜泄降，即清降上浮之气火，使肺得肃降。", ["数"]], "9455": ["病机", "原文“右温邪湿热，留恋阳明，表热，胸闷溲赤，脉数，咳嗽”。数脉主热，温邪湿热留恋阳明，热郁于内，故脉数。表热、胸闷、溲赤、咳嗽为湿热蕴阻、表里同病之症，脉数正合湿热内盛之病机，宜从表分立方以透化湿热。", ["数"]], "9456": ["病机", "咳嗽三月不止、咽痒痰白、头胀形寒，为温邪郁于肺卫、出入未解之象。脉数示邪热内扰，正气尚能抗邪，故宜辛散宣泄以透邪外出。数脉在此非纯虚，乃温邪留恋、肺失宣降之征，与头胀形寒并见，说明表邪未尽而里热已萌。", ["数"]], "9457": ["病机", "寒止而热在肌肤之内，腰酸咳嗽，脉细。细脉主阴血不足、正气亏虚。本症从感冒而起，邪虽渐退而正已受伤，热留肌肤、腰酸咳嗽，示余邪未清而营阴已耗，故言未易速解。细脉与腰酸并见，提示肾阴亦受牵累，不可纯作表证论治。", ["细"]], "9458": ["病机", "进宣泄上焦法后咳声稍减，但肢冷脉濡。濡脉主湿、主气虚，湿邪困阻阳气不能达于四末，故肢冷；脉濡示表分湿浊未清、气机不畅。咳减而脉未复，说明上焦虽得宣通，表分湿邪尚恋，故尚宜清理表分，不可骤补。", ["濡"]], "9459": ["病机", "咽哽积久、气升作咳不寐，脉细弦。细为阴血亏虚，弦为气机郁逆。体虚感温，阴亏于下而气逆于上，肝肺气机失调，故咽哽、咳逆、不寐并见。细弦并见示正虚邪恋、气郁化火，理之不易，须兼顾养阴与疏降，不可偏执一端。", ["细", "弦"]], "9460": ["预后", "寒热止、表病均解，惟咳嗽不已而脉数。表邪虽解，数脉不退，说明里热未清、肺络余热留恋。向有肺痈之根，数脉示热毒内蕴、腐瘀未净，最防复发。此段以脉数判断表解而里热未除，属预后警示，须清肺解毒以防痈疡再发。", ["数"]], "9461": ["预后", "咳久气阴两损，气冲痰多而脉数。数脉在此非实热，乃气阴亏虚、虚火浮越之象。久咳耗伤肺之气阴，虚火上炎则气冲痰多，体乏病深，正虚难以骤复，故脉数而预后不易奏功。数脉与气阴两损并见，提示虚火内扰、本原已伤，须慎养缓图。", ["数"]], "9462": ["病机", "咳久、嗜食形瘦而脉细。细脉主阴血亏少。久咳伤肺，阴液耗损，阴虚则火浮，故嗜食形瘦、虚火内扰。细脉示阴损为本，火浮为标，阴不制阳则火动。此段以脉细点明阴损火浮之机，不可忽视，须养阴清火、标本兼顾，防其进一步耗竭。", ["细"]], "9463": ["病机", "努力伤气，气道失宣，行动气急、胸闷、干呛不已，脉细微数。细为阴血不足，微为阳气衰微，数为虚火内动。气伤则宣降失职，故气急胸闷干呛；细微数并见，示气阴两伤而虚火浮越，渐渐近涉本原，说明病已由气及本，须加意慎养，不可再耗。", ["细", "微", "数"]], "9464": ["病机", "脉软弦，软为木郁不伸、弦乃火盛气逆之象。右木郁化火，火盛乘金，故咳逆气急、山根肿胀、头晕耳鸣，皆木火刑金、标本同病之候。脉软弦正示郁火内炽而正气已伤，最防喘塞，是肺金受灼、气机壅塞之危。", ["软", "弦"]], "9465": ["病机", "原文未识脉名，仅言脉不畅，指肺气郁遏、邪阻气机之象。左风邪上受，首先犯肺，肺失清肃下行之权，故咳逆痰多、大便带血、头目不清。脉不畅正合肺邪不达、气机壅滞之机，宜宣泄涤邪，免伤肺气。", []], "9466": ["病机", "脉微数，微为正气不足、阴薄感风，数为内热之征。咳嗽内热、时易腰痛、腹膨胀，皆阴薄感风、虚热内扰之候。脉微数示正虚而热郁，当先治所急，是急则治标、兼顾其本之意。", ["微", "数"]], "9467": ["病机", "脉弦数，弦主肝脾不和、数主火热。脾弱生湿，湿蕴蒸痰，二气涌肺则喘粗咳呛；舌中黄尖绛、口干不欲多饮、暮则肢冷火升有汗，皆痰湿热无从散布、火升之象。脉弦数正合痰火内郁、肝脾失调之机，故拟润肺降气、涤痰安神。", ["弦", "数"]], "9468": ["病机", "脉数不扬，数为热，不扬为邪郁气机不宣。风温郁肺，肺气失宣，故咳嗽咽痒、神疲。脉数不扬正示温邪内郁、肺气壅遏而未能透达，当疏泄治之，使邪从表解。", ["数"]], "9469": ["病机", "脉数主热，咳嗽不畅、气急头痛，为热郁上焦、肺气不宣之候。脉数示邪热内蕴，气机壅滞故咳不畅而气急，热上攻故头痛。宜宣泄上焦，使郁热得解、肺气宣畅。", ["数"]], "9470": ["病机", "脉细数，细为阴亏，数为伏热。阴虚伏热烁肺作咳，咳久音哑、咽关红丝满布，皆阴液耗伤、虚火灼肺之象。脉细数正合阴虚伏热之机，病道深远，须逐渐调理，不可峻攻。", ["细", "数"]], "9471": ["病机", "脉弦主肝旺气逆。晨间气升作咳、咳无痰、食下作酸、舌根黄白，皆肝气上逆、木火刑金、脾运不畅之候。脉弦正示肝郁气逆为病机关键，故宜平肝润肺、疏畅脾运，使肝平则气降、脾运则痰消。", ["弦"]], "9472": ["兼症", "原文脉右软、左细弦，右软示脾肺气虚，左细弦为肝阴不足、肝气偏亢。结合舌黑颇退、咳痰稍愈而精神疲乏，说明邪退正虚，气阴两伤，肝脾失调。脉象与疲乏、咳痰等症相应，故宜顾及本症，扶正兼顾。", ["软", "细", "弦"]], "9473": ["病机", "脉弦为肝气偏旺、气机郁滞之象。原文咳痰腻、气急、动即喘、头痛，痰浊阻肺而肝升太过，木叩金鸣，故脉见弦。弦脉主肝主痛主气逆，与咳喘头痛相应，故宜平肝泄肺，使肝肺气机调畅。", ["弦"]], "9474": ["病机", "脉数为热，温邪郁肺，热壅气急，故右咳嗽气急、寒热胸痛而脉数。腹冷乃中阳不足，热郁于上而寒在中下。数脉主热主急，温邪内郁有陷闭之虞，故防厥闭喉腐，须清透温邪、顾护中阳。", ["数"]], "9475": ["病机", "原文脉不扬，指脉气不能振扬外达，为风热痰浊交郁、肺气壅遏之象。咳嗽不畅、音哑，皆肺窍不利、痰浊阻络所致。脉不扬与痰郁气滞相应，说明邪郁较深，故言不可忽，当疏风清热、化痰宣肺。", []], "9476": ["预后", "脉软弦，软为气虚，弦为肝旺乘脾。痰喘咳逆乃肺气上逆，足膝软弱为脾肾不足、下元亏虚。脉象示本虚标实，喘久易生变波，故延防喘甚生波，须加意慎养，健脾平肝、纳气定喘。", ["软", "弦"]], "9477": ["预后", "左脉软、右细，软细并见为气血俱虚、肺肾交困之象。咳嗽积久、形瘦色夺、音哑、少安寐，皆虚损日久、五液蒸为痰浊所致。脉象与虚损症候相应，故断为虚损告成，理之棘手，示预后不良。", ["软", "细"]], "9478": ["病机", "脉微弦，微为阳虚，弦主饮主痛。咳嗽气急、吐痰浓薄不定、足肿面浮，正是支饮停聚、水气上逆之候。原文明言由脾经化湿生痰上输于肺，脉弦应饮，故属支饮，防喘满并增，当温脾化饮。", ["微", "弦"]], "9479": ["病机", "脉濡滑，濡主湿、滑主痰，为痰湿内蕴之象。恶寒作咳久不止、痰吐白腻、胃纳日减，皆寒郁化热、痰湿困脾伤阴之候，夜寐咽干即阴分受伤之征。脉与痰湿症相应，故须加意慎养，化痰湿兼护阴分。", ["濡", "滑"]], "9480": ["兼症", "左脉细为阴血不足，右脉软滑数为痰热内蕴。咳嗽痰吐如沫、气急不能安卧，是痰浊壅肺、肺失肃降之象；脉细示病根积深、正气已伤，软滑数则痰热未清。兼腹瘕上逆，乃肝气挟痰上冲，故治法须两顾，既化肺痰又平肝逆，正合脉症所示虚实夹杂之机。", ["细", "软", "滑", "数"]], "9481": ["预后", "脉左细、右数，细为阴亏，数为虚热。咳嗽久不愈、音闪咽燥口干，是肺阴耗伤、金失濡润；气急足肿、大便不实，则脾肾亦损、水湿不化。脉细数而见虚损诸症，故曰亏损已久、理之棘手，须多请高明斟酌，明示久病正虚、预后难速之旨。", ["细", "数"]], "9482": ["预后", "脉细为气血不足、肺气虚弱。咳逆气急而畏寒，是肺气虚寒、卫阳不固，宣降无力。脉细与畏寒、气急并见，示正气已虚而病势有进，故曰延防作喘，即虑其肺气日耗、肾不纳气而转为喘促，属未病先防之预后判断。", ["细"]], "9483": ["病机", "脉滑数为痰热之征。温邪为痰湿所敛，邪郁肺络，故咳嗽不已、音闪不扬；滑主痰湿内盛，数主热邪内郁，痰热交阻肺气，宣降失司。脉症相合，明示痰湿敛邪、肺气不宣之病机，故治法宜泄肺化邪，使痰热去而肺气自畅。", ["滑", "数"]], "9484": ["病机", "脉数不畅，数主邪郁化热，不畅示气机壅遏。表邪郁肺，咳久不畅，咽干作痒，是外邪束肺、肺气失宣、郁而化热之象。脉数而不畅，正合邪郁上焦、气机不利之病机，故宜宣泄上焦，透邪外出、宣畅肺气，使郁解而咳自平。", ["数"]], "9485": ["预后", "脉微数为气阴两虚而有虚热。干咳音闪、胸前不畅、背脊胀，是肺阴亏耗、肺气不利，虚热内扰。微为正气衰微，数为阴亏生热，脉症合参，示肺络受损、虚火灼津，故曰延防失血，虑其虚火伤络而致咳血，属防微杜渐之预后判断。", ["微", "数"]], "9486": ["治法", "脉数为邪郁化热之象。咳嗽咽痒、头痛气急，是风热犯肺、肺气上逆；腹痛则兼腑气不和。数脉主热、主邪盛，诸症皆由邪郁上焦、肺失宣降所致，故治法宜疏化宣泄，疏风清热、宣肺降气，使邪从表解、气机调畅而咳喘自安。", ["数"]], "9487": ["病机", "左脉弦为肝气偏亢、气机郁逆之征。咳逆气急、动即作喘，是肝气挟痰上逆犯肺，肺失肃降。弦脉主肝、主气逆，与咳喘动则加剧相应，明示上实下虚之病机：上则肝肺气逆为实，下则肾不纳气为虚，故曰理之不易，治当兼顾虚实。", ["弦"]], "9488": ["病机", "原文谓「左热为寒束，肺失宣畅」，脉弦主寒束气机、肺气不宣，数主热郁于内，弦数并见说明外寒束表、内热郁肺，肺失宣降故咳嗽气逆、气短。病位在上焦，治在上焦，脉象与咳逆气短之症相应。", ["弦", "数"]], "9489": ["主病", "右咳痰薄白、咽痒而脉数，数脉主热，然痰薄白、咽痒又似风热轻袭肺卫，热郁于肺则咳，咽痒为风热上扰。脉数在此提示肺经有热，与咳痰、咽痒之症相应，属上焦肺系病变。", ["数"]], "9490": ["病机", "脉虚弦，虚为正气亏损，弦主气机郁滞、痛证。原文谓「肺肾两病」，咳嗽复发、恶寒气急为肺病，腰肋痛为肾病及肝，虚弦说明正虚而气机不畅，肺肾同病故「理之不易」，脉与咳、寒、腰痛相应。", ["虚", "弦"]], "9491": ["预后", "左表热五日，咳嗽胁痛而脉数，数主热盛，表热入里、热郁肺肝则咳而胁痛。原文虑「防痰升气塞，骤生变端」，脉数示热势未衰，有痰热壅盛、气机闭塞之变，故不可轻视，属预后警示之论。", ["数"]], "9492": ["预后", "久咳阵来、畏寒痰少而脉细，细脉主气血亏虚、正气不足。久咳伤肺，畏寒为阳虚，痰少示津亏，脉细正合虚损之象。原文谓「亏损已甚，理之不易」，脉细与久咳虚损相应，提示预后调治困难。", ["细"]], "9493": ["病机", "左脉软，软主虚、主湿。咳嗽气急、气逆为肺气不降，腰腿酸软为肾虚失养。原文谓「积虚已甚，治宜求本」，脉软说明正气虚馁，肺肾两亏，与咳逆、腰腿酸软之症相应，故治当求本补虚。", ["软"]], "9494": ["病机", "脉滑数，滑主痰湿，数主热。咳逆痰多、音哑、胸次微闷、咽关红，皆痰热壅肺、风温逗留上焦之象。原文谓「风温逗留，当从上焦宣泄」，滑数脉正合痰热内蕴，与痰多、咽红等症相应。", ["滑", "数"]], "9495": ["治法", "脉弦数，弦主气郁、数主热。咳逆痰沫、胸脘痞闷、纳少、舌白黄，为痰热郁肺、气机不畅、波及中焦之象。原文谓「宜泄肺下匀」，脉弦数说明肺热气壅，故治以宣泄肺气、调畅气机，脉症与治法相应。", ["弦", "数"]], "9496": ["主病", "脉数主热，此因幼寒暖不调，表邪外束，午后发热咳嗽多嚏，舌花白，为表邪未解、里已有热之象。数脉应热，邪郁肌表则发热，肺气不宣则咳嚏，故宜表里两治，解表清里并行。", ["数"]], "9497": ["病机", "脉软弦，软为虚，弦主气机不畅。右干咳不已、咽痒无痰、胃纳减少，舌白黄，乃肺阴不足、气逆不降，木郁乘土。肺阴交困，最易见红，故宜润肺止嗽，养阴柔肝。", ["软", "弦"]], "9498": ["病机", "脉数主热，温邪上受，首先犯肺，肺失清肃，故咳嗽壮热、气粗无汗、头晕胸闷；腹部拒按、大便不行、舌垢，为邪热痰滞熏蒸肺胃，极易化燥痉厥。数脉示热盛，非轻症也。", ["数"]], "9499": ["病机", "脉软弦，软为不足，弦主气机拂逆。发热解后干呛不已、晨间鼻衄，乃余热未清、气逆上冲，络伤血溢。纳如常，胃气未败，故宜择要治之，降气润肺以平拂逆。", ["软", "弦"]], "9500": ["病机", "脉左细右滑，细为阴血不足，滑主痰气壅盛。咳嗽匝月不松、气逆不得安寐、手足心微热，乃肺气不降、痰阻气逆，久咳伤阴。左细应阴亏，右滑应痰壅，故宜泄肺顺气。", ["细", "滑"]], "9501": ["病机", "脉弦主气机郁滞，阴虚则热自内生。掌心热、咳嗽痰黏、心胸痛、肢节酸、鼻孔有血，乃阴亏火旺、木火刑金，灼津为痰，络伤血溢。弦脉应肝，故当标本两治，滋阴降火。", ["弦"]], "9502": ["预后", "脉软为虚，咳痰如沫、乍寒乍热、咽痒曾失血、腹痛恶心，乃肺脾两虚、气不摄血，痰沫为虚寒之象。软脉示正气不足，防成募损，即久咳损及肺募，故当补虚固本。", ["软"]], "9503": ["病机", "脉数主热，咳嗽吐痰极多，乃风温郁于肺胃，热蒸津液为痰。数脉应热，痰多示肺胃气壅，热郁不解则痰热互结，故宜泄化主之，清肺化痰以解郁热。", ["数"]], "9504": ["病机", "脉数主热，风郁化热，热邪犯肺则咳久转顿嗽；热伤肺络则鼻衄。数脉为热盛之征，结合咳、衄，病机为风热郁肺、肺胃热盛，故宜清润肺胃。", ["数"]], "9505": ["病机", "左脉软主脾虚，右脉数主热，咳吐痰沫为脾虚生痰、肺失宣降；经期少为脾肾不足、精血亏虚。脉软与数并见，示脾肾两病、虚实夹杂，故曰勿泛视之。", ["软", "数"]], "9506": ["病机", "脉数主热，表热未解，热邪壅肺则咳嗽痰多。数脉示病势方张，邪热正盛，故曰毋忽。病机为表热犯肺、痰热内蕴，属外感咳嗽之进展期。", ["数"]], "9507": ["病机", "脉细弦，细主阴血不足，弦主肝郁或痛。咳嗽日久，阴液耗损，肺燥失润，故乍寒乍热。细弦为阴损肺燥之象，病机为肺阴亏虚、肝郁化火，属内伤咳嗽。", ["细", "弦"]], "9508": ["预后", "脉细主气血不足，咳稍松而气仍塞、寒热胸腹痛、咽哽，为产后蓐劳、气血亏虚、瘀滞未清之象。细脉示正虚，故曰蓐损可虑，预后堪忧。", ["细"]], "9509": ["预后", "脉弦主肝旺或饮停，咳嗽宿恙、呛剧气急，为肝气上逆、肺失肃降。弦脉示病势未平，延防生波，即防喘逆、咯血等变证。病机为肝肺气逆、痰饮内伏。", ["弦"]], "9510": ["病机", "左脉细主血虚，右脉滑主痰湿。咳嗽复发、痰吐浓薄不一、腰酸，为湿痰内蕴、凉风外束，肺失宣降。细滑并见，示正虚痰盛，最防作喘。病机为外寒引动内湿，痰湿壅肺。", ["细", "滑"]], "9511": ["预后", "左脉细涩、右数虚，两手无神，为气血两亏、阴阳俱损。咳嗽动则更咳、痰臭秽白腻、舌糜、胸闷自汗、发热、便溏，示肺肾两竭、中土又夺。细涩数虚并见无神，预后极差，故曰顾此失彼。", ["细", "涩", "数", "虚"]], "9512": ["病机", "脉细为阴血不足，数为有热。咳嗽一年余，久咳伤肺阴，阴虚内热，故脉细数；胁痛恶心乃肺病及肝、气逆犯胃之象。原文谓“肺病积久，理之不易”，正因细数脉示阴亏热伏，非单纯外邪，故病程缠绵难愈。", ["细", "数"]], "9513": ["病机", "脉软主气虚湿困。咳嗽痰多、气短，为痰湿郁肺、肺气不宣；脉软而非弦紧，说明邪不在表而偏于里虚，痰湿内蕴。原文“疟邪痰湿郁肺，防作喘”，提示痰湿壅盛有上逆作喘之势，脉软正反映正虚湿滞之病机。", ["软"]], "9514": ["病机", "脉软弦数，软为阴虚，弦为相火不潜，数为热象。嗽后亡血已止而溲下未利，乃阴分亏虚、湿热下注；相火不潜则弦数并见。原文“阴分虚，湿热重相火不潜”，正合软弦数之脉，故一时不易速效。", ["软", "弦", "数"]], "9515": ["病机", "脉濡主湿。咳嗽不畅、舌黄不清，为湿浊郁于上焦，肺气不宣；濡脉不浮不数，说明湿性黏滞、非单纯风热。原文“宜宣泄上焦”，正是针对湿郁上焦之病机，以宣肺化湿为治。", ["濡"]], "9516": ["病机", "脉弦主气机郁滞。咳嗽咽痒，为肺气不宣、风邪郁于肺系；弦脉示气逆不降。原文“宜宣畅肺气”，说明此弦非肝阳亢盛，而是肺气郁滞之象，故治以宣肺畅气。", ["弦"]], "9517": ["病机", "左脉软为气虚，右脉微滑为痰湿未净。咳嗽渐止而腰酸肢酸，乃肺病渐愈、脾肾气虚未复；微滑示余痰尚存。原文“宜即守前章进步”，说明脉象由实转虚，正虚为主、余邪未尽，故守前法缓图。", ["软", "滑"]], "9518": ["病机", "脉弦数为阴亏火郁。咳嗽音哑、咽痛痰多恶心，为肺阴不足、虚火上炎，灼津成痰；弦主气郁，数主火旺。原文“阴薄火郁，最防失血”，正因弦数之脉火势上炎，有灼伤肺络、迫血妄行之虞。", ["弦", "数"]], "9519": ["病机", "脉濡主湿。寒热得解而胸闷气急、咳嗽不流利、口干腻，为湿浊留滞肺胃、气机不畅；濡脉示湿邪黏滞未化。原文“治在肺胃”，说明病位在肺胃，湿阻气机，故以化湿宣肺和胃为治。", ["濡"]], "9520": ["病机", "脉数主热，右弦主饮主痛。咳嗽夜甚、头胀胸肋痛，乃热郁于肺、饮停胸胁，气机不利。数示邪热内扰，弦示水饮痰浊结聚，故防呛甚见红，热伤肺络之兆。", ["数", "弦"]], "9521": ["病机", "脉数主热，咳嗽匝月不止、咽喉肿碎作痛，为肺胃邪热壅盛，上灼咽喉。数脉应热邪亢盛，故宜泄肺胃之邪热，使热从外解。", ["数"]], "9522": ["预后", "脉软少神且不调，为正气大虚、胃气将败之象。咳嗽年余，津液尽为痰浊，形瘦骨立、肤槁气短，乃久病耗伤，脾肺两损。脉失柔和之神，故曰病深，药石力薄。", ["软"]], "9523": ["病机", "脉数不畅，为湿热内蕴、风邪外束，邪正交争而气机不畅。作寒发热胸闷咳嗽，乃湿热为风邪所包，表里同病。数主热，不畅示湿阻气滞，故宜透达宣泄。", ["数"]], "9524": ["预后", "脉软弦细，软为气虚，弦为饮停，细为阴伤。因痰作咳、痰多神乏，乃脾虚失运，痰浊内盛，气血不足。脉象虚而兼弦细，桔槁已甚，故理之不易。", ["软", "弦", "细"]], "9525": ["病机", "脉数主热，热旬日而咳嗽胸闷，为邪热与痰滞交结于肺，气机壅塞。数脉示邪热炽盛，交结不解，故解散不易，当先清透。", ["数"]], "9526": ["病机", "脉弦数，弦主气滞、数主热。腹痛胀闷、咳逆，乃肝气犯肺、气机壅滞，郁而化热。弦数并见，示气滞热郁交阻，故宜宣泄疏中，调畅气机。", ["弦", "数"]], "9527": ["病机", "脉弦数，弦为气滞，数为热。腹痛胀闷、咳逆，乃肝气犯肺、气机壅滞，郁而化热。弦数并见，示气滞热郁交阻，故宜宣泄疏中，调畅气机。", ["弦", "数"]], "9528": ["预后", "脉数主热，咳嗽身热见数脉，为风湿之邪内蕴化热，正邪交争。原文谓“中挟风湿，延虑转重”，数脉示热势偏盛，若风湿不化，热邪易内陷，故预后堪虑。", ["数"]], "9529": ["病机", "左脉细为痰湿内阻、气机不畅，右脉弦主痰饮气逆。咳痰不利、气急腹胀、口苦便溏恶心，皆痰湿中阻、气机失畅之象。脉细弦与“流利气机，疏化痰湿”治法相应。", ["细", "弦"]], "9530": ["预后", "脉弦主肝风内动，咳嗽腰胁痛、身热神蒙糊语，为邪热内陷、肝风欲动之兆。原文谓“正不胜病，防厥”，弦脉示风阳鸱张，正虚邪盛，故预后不良。", ["弦"]], "9531": ["病机", "脉细主气血不足，咳嗽痰多、便泄少纳，为肺脾两虚、痰湿内生。细脉示正气亏虚，脾失健运则便泄少纳，肺失宣降则咳痰。原文“肺脾同病，理之不易”正合此机。", ["细"]], "9532": ["病机", "脉弦主痰饮内伏、气机郁滞。宿哮根深，痰伏肺络，适逢外感引动，故脉见弦。弦脉示痰气交阻，与“宣泄肺气”治法相应，以宣肺化痰、调畅气机为要。", ["弦"]], "9533": ["病机", "脉细数主阴虚内热，咳嗽腹满、面浮足肿、瘕逆，为肺脾肾同病、水湿泛滥。细为正虚，数为邪热，虚热与水湿互结，故原文谓“肺脾同病，理之棘手”。", ["细", "数"]], "9534": ["病机", "脉弦主痰饮内停、气机不利。咳嗽久不止、气急痰薄，为久咳肺虚、痰饮不化，弦脉示饮邪内踞。原文“病道深远，理之不易”，强调久病入络、痰气胶结之机。", ["弦"]], "9535": ["治法", "脉软弦主肝旺脾虚、痰气上逆。气急干咳、夜不安寐，为肝火犯肺、肺失肃降。软脉示脾虚，弦脉示肝旺，故“当镇肝泄肺”，以平肝降逆、清肺化痰为治。", ["软", "弦"]], "9536": ["病机", "脉细数，细为阴血不足，数为内热亢盛。劳乏之后干咳吃力，乃肺阴亏虚、虚火内灼，故脉细数。内热延防失血，因热伤血络，有动血之虞。此脉主阴虚内热，与干咳、乏力相应。", ["细", "数"]], "9537": ["病机", "脉左细右弦，左细为肺阴亏虚，右弦为脾土受克、水湿内停。咳嗽腹满、面浮足肿、腹瘕胀逆，乃肺脾交病，肺失宣降则咳，脾失健运则肿满。细弦并见，主本虚标实，理之不易。", ["细", "弦"]], "9538": ["病机", "脉微数，微为正气不足，数为风热袭肺。风热外袭，肺失清肃，故咳嗽复发。脉微数说明热势不盛而正气已伤，宜轻清泄化，透邪而不伤正。此脉主风热轻证，与咳嗽相应。", ["微", "数"]], "9539": ["病机", "脉左细右软弦，左细为肺阴亏虚，右软弦为脾虚湿困、肝木乘脾。多年咳嗽转甚，胸闷，乃肺病及脾，痰湿内阻。细软弦并见，主肺脾两虚、痰湿内蕴，宜泄肺宽中。", ["细", "软", "弦"]], "9540": ["病机", "脉软滑，软为气虚，滑为痰湿。咳嗽积久，甚则呕吐痰沫，乃肺胃气虚、痰湿内停，胃气上逆。软滑之脉主痰湿内蕴而正气已虚，治在肺胃，健脾化痰、降逆止咳。", ["软", "滑"]], "9541": ["病机", "脉数主内热。幼童哮，近日咳甚，痰中带红，乃肺胃热盛、灼伤血络。数脉为热邪内蕴之象，热伤肺络则痰红。宜清润肺胃，清热而不伤阴，润燥而止血。", ["数"]], "9542": ["病机", "脉数主热。肺主气，其状如钟，肺气失宣则鼻塞咽痒、咳窒痰吐不利、音哑，乃热邪壅肺、金实不鸣。数脉说明热邪内盛，肺气闭郁。当作金实无声治，宜宣肺清热、开郁利窍。", ["数"]], "9543": ["病机", "脉数主温邪内盛。温邪为风所束，头胀鼻塞、咳嗽吐痰不利，乃风热袭表、肺失宣降。数脉为温邪化热之象，邪在上焦。当从上焦宣泄，疏风清热、宣肺透邪，使邪从表解。", ["数"]], "9544": ["病机", "脉濡为湿象，又主气血不足。咳嗽四日，黄痰白沫并吐，气急肌灼，显系痰热壅肺而兼湿滞。然枯瘦已甚，脉濡而非滑数，说明正气已虚，湿浊内蕴，无力托邪外达。濡脉主湿、主虚，与肌灼气急并见，为虚实夹杂之候，故云理之不易。", ["濡"]], "9545": ["病机", "脉弦主肝、主饮，数主热。哮咳五年未发，近又喘急，痰沫卧醒后转浓，是伏痰因感而动，肝气上逆，痰热内扰。弦为肝旺饮停，数为热象，弦数并见，说明肝火挟痰上壅于肺，喘急难平，故防喘塞生波，即防痰壅气闭之变。", ["弦", "数"]], "9546": ["病机", "左脉弦、右脉数，弦属肝，数属热。至夜少寐、气急、晨咳舌干，为肝阴不足，阳不潜藏，虚火上炎，木火刑金。左弦示肝旺，右数示肺热，阴不敛阳则夜寐不安，故宜从阴引阳法，即滋肝阴以潜浮阳，使阴阳相交。", ["弦", "数"]], "9547": ["病机", "脉数为热。头胀咳嗽、胸闷，为风热犯肺，肺气不宣；两腿酸为热邪下注或表邪未解。数脉主热盛，表里俱有热象，故宜表里两治，既解表邪又清里热。数脉在此说明邪热方张，非虚数之候。", ["数"]], "9548": ["病机", "脉软主气血不足、阴分亏虚。三月前咳血涌吐，刻下痰红、头晕心恐、口腻，是失血之后阴液耗伤，虚火浮越，灼伤肺络。软脉示正气已馁，阴薄火浮，血不归经，故痰红不止，不可忽视者，防其血脱阴竭。", ["软"]], "9549": ["病机", "右部脉大，右属肺主气。失血咳嗽、形寒，为气分虚寒而血不归经。脉大者，气浮于上，血随气升之势已显。形寒而脉大，非实热之大，乃气虚阳浮之象，故防血随气升，再次失血，勿以轻视。", ["大"]], "9550": ["病机", "脉数主热。痧后冒风乱食，咳嗽顿作呛、痰带血、面浮腹膨、午后身热，是痧毒未清，复感风邪，食滞化热，热伤肺络，气机壅滞。数脉示热邪内炽，午后身热为阴虚或湿热之征，淹缠非宜，深防入怯，即防成虚劳。", ["数"]], "9551": ["病机", "脉来濡软，主湿、主虚。素体劳乏，内伤营络，咳嗽见血，舌苔白腻不渴，是劳伤中气，脾虚生湿，湿浊内蕴，络伤血溢。濡软示正气不足而湿滞，非实热迫血，故以泄降宣络为治，淹缠非宜，防其久延成损。", ["濡", "软"]], "9552": ["预后", "失血后阴血亏虚，虚热内生，故脉数；咳逆不已为肺失濡润、虚火灼肺之象。脉数示热象未清，久则肺叶焦痿，故延防肺痿，勿忽。此数脉非实热，乃阴亏阳浮之征，与咳逆并见，主肺燥津伤之机。", ["数"]], "9553": ["病机", "失血后血虚，虚火内煽，故脉软数。软为阴血不足、脉道不充，数为虚火鼓动。嘈杂如饥乃胃中虚火扰攘之症。脉软数与此症相应，主血虚火旺之病机，故宜甘润生阴以滋其化源。", ["软", "数"]], "9554": ["病机", "失血后经少带多、心宕头晕，虚象层出，口干最重，右寸及左关脉均不静。寸关不静示气火内动，阴血亏虚不能涵敛，故最防气火动发。脉象虽未明言，然不静即寓弦数躁动之意，主阴虚火旺、气逆将发之机。", []], "9555": ["预后", "血后咳嗽，起肛痈，虚汗，脉数。失血阴亏，虚热内炽故脉数；肺热下移大肠则肛痈，虚热迫津则汗。根蒂内乏指肾阴亏耗，脉数示虚热不敛，故虚怯可虑，预后堪忧。", ["数"]], "9556": ["病机", "咳痰如脓、呛血，脉右滑数、左细。右寸滑数主痰热壅肺，热灼肺络则呛血；左细为阴血不足。滑数痰热与细脉阴伤并见，主上焦痰热壅盛兼阴分受损之病机，故宜清润上焦。", ["滑", "数", "细"]], "9557": ["病机", "用力受损，痰中带红，脉软弦。软为阴血亏虚、脉道不充，弦为肝气偏旺、络脉拘急。用力伤络则血溢痰中，脉软弦正合阴分受伤、肝络不柔之机，故须善为调理，不可峻攻。", ["软", "弦"]], "9558": ["预后", "血后咳嗽，脉软滑数，纳少便溏。软为阴血虚，滑数为痰热内蕴；纳少便溏乃脾土亦弱。阴亏于下、痰热浮上，而中焦不运，虚实夹杂，故理之大非易易，预后调治棘手。", ["软", "滑", "数"]], "9559": ["病机", "吐血旧恙复发，满口不止，咳呛咽痒舌黄，脉弦数。弦为肝气有余，数为火旺，弦数相合主毒火浮风、肝胃热盛。火性炎上，迫血妄行，故最防血随气升，再致大吐。", ["弦", "数"]], "9560": ["病机", "久咳肺虚、形瘦失血而见脉数，数主热、主虚火内扰。肺阴亏耗，虚热迫血妄行，故满口失血；形瘦为阴血不足之征。脉数与咳、血并见，说明肺虚为本、虚热为标，热不除则血难止，故拟清润泄降以治所急。", ["数"]], "9561": ["病机", "吐血后腰痛神疲、足膝无力，脉左弦右软。左弦为肝失柔养、虚风内动，右软为脾肺之气亏弱。失血既多，肝肾亏损已甚，筋骨失养故腰膝无力；弦软并见，示虚中夹亢，故告诫亏损已甚、勿忽。", ["弦", "软"]], "9562": ["病机", "咳嗽痰多、胸痛气闷，脉弦。失血起因已及年半，阴血亏而肝木失养，肝亢犯肺，故脉弦、咳痰胸痛。弦为肝旺之象，肺损肝亢并见，气火上逆，久则金伤，故延防失音，示病机在肝肺同病。", ["弦"]], "9563": ["预后", "咳呛不已、吐血满口而脉数，数主热盛、火迫血溢。肺络为虚火所灼，血随气涌，故满口吐血；脉数示热势未平，气火有上涌之势，故防涌冒，即防血随气逆、涌溢更甚，属预后警示。", ["数"]], "9564": ["病机", "大失血后咳呛气急，脉细数。细为阴血亏少、脉道不充，数为虚热内扰。失血既多，肺肾之阴交亏，肾不纳气则气急，肺失濡润则咳呛，故曰肺肾交困。细数之脉正示阴亏火动，殊不可忽。", ["细", "数"]], "9565": ["病机", "抑郁不解致心肝交困，背寒鼻热、黎明虚汗、心痛如抽、少腹酸胀、腰痛不寐，脉细。细主阴血亏虚、脉道不充。情志郁结，心肝之阴暗耗，虚热内生故鼻热虚汗，筋脉失养故抽痛酸胀，吐血更伤阴血，故不易见功。", ["细"]], "9566": ["预后", "痰红止、喘势渐平，而浊泛口腻、咳即气升，脉弦。弦为肝旺、气逆之象。虽血止喘平，然肺肾同病未复，肝气仍逆，痰浊上泛，气升咳作，脉弦示根本未安，故最防反复，属预后告诫。", ["弦"]], "9567": ["病机", "产虚久不复，曾吐血，今火升、薄暮微寒而热，脉软。软为气血亏弱、脉道不充。产后阴血大伤，虚火浮升故寒热，火灼肺络故咳，渐成蓐损。脉软示正气虚馁，虚火与正虚并见，故不易治。", ["软"]], "9568": ["预后", "原文未识脉名，仅言“脉不静”，指吐血复发而脉失宁静之常，提示火势未平、血络不宁。脉不静则肺金受灼，最防热壅血腐而成肺痈，故急急泄火下气以折其势，属预后警示之论。", []], "9569": ["病机", "脉软为气阴不足，弦为邪郁络脉；左咳嗽白痰带血、左肋背作痛，乃邪郁肺损、络气不和之象。软弦并见，说明正虚而邪郁，肺损难骤复，故言“理之不易”。", ["软", "弦"]], "9570": ["病机", "左脉虚弦，虚为阴血亏耗，弦为虚火内动；咳嗽失血、音闪，乃阴损已甚、肺金失养、金破不鸣之候。脉证合参，病机重在阴损火浮，故须加意慎养。", ["虚", "弦"]], "9571": ["病机", "脉空弦者，空为血虚不充，弦为瘀滞不和；呕吐、胃纳呆木，乃伤血积瘀、胃气不降所致。空弦并见，示血伤而瘀积，虚实夹杂，故须善为调理。", ["空", "弦"]], "9572": ["预后", "脉弦数，弦为肝火亢盛，数为热迫血行；吐血盈碗、气急咳呛，乃火升气逆、血随气上。弦数不退，防壅冒者，虑其热壅气逆、血涌致冒，故以“防壅冒”为警。", ["弦", "数"]], "9573": ["病机", "脉弦数，弦属肝火，数属热盛；咳嗽吐血、舌光绛碎、腰痛腿热，皆阴虚火浮、灼伤肺络之征。舌光绛碎尤为阴亏火旺之据，故主阴虚火浮，静养为要。", ["弦", "数"]], "9574": ["病机", "吐血之后脉软、神疲，软为气血不足之象，神疲为气阴两伤之征。吐血既伤阴血，又耗正气，故脉软而神疲，主气阴两亏，宜加意慎养以复其元。", ["软"]], "9575": ["病机", "脉细为阴血亏少、脉道不充；吐血屡发、心胸咳嗽，乃阴损日久、虚火浮越、肺络不宁。细脉主阴损火浮，与舌光绛碎、腰痛腿热等阴虚火旺之症相应，故不可轻忽。", ["细"]], "9576": ["病机", "脉细为阴血亏少、脉道不充之象。原文谓“左血上下溢”，失血既多，阴气大损，故脉细；血虚不能上荣则面色不泽，阴津亏耗则口干。此脉此症互参，示阴血大伤、虚损已成，故曰“理之不易”，主病在阴血亏虚。", ["细"]], "9577": ["病机", "脉软弦者，软为肺气不足、弦为肝木偏旺。失血较瘥而咳痰仍带血，乃肺阴大损、虚火灼络；软中见弦，示肺虚而肝木易侮，气机有壅逆之虑，故原文防“壅冒”。此脉主肺阴亏虚、肝气上逆之机。", ["软", "弦"]], "9578": ["病机", "脉软弦，软主肺气阴两虚，弦主木气偏亢。失血后转为咳嗽，咳增音闪、痰厚薄不一，乃肺阴旱经所困、清肃失职；知饥不能食，胃气亦弱。软弦并见，示肺虚木侮、中土不运，病势深入，故叹“不易治”。", ["软", "弦"]], "9579": ["病机", "脉细数为阴虚内热之典型脉象。吐血咳嗽互缠不已，阴血耗伤则脉细，虚火内炽则脉数；甚则得食辄吐，胃阴亦亏、虚气上逆。细数并见，示气阴同病、虚火灼肺烁胃，故曰“理之不易”，主病在气阴两伤。", ["细", "数"]], "9580": ["病机", "脉弦为肝木偏旺、失于柔和之象。伤血复发，阴血亏虚不能涵木，肝阳化风上扰则心荡，筋脉失养则骨痛。弦脉在此示本体受损、肝木失养而亢逆，非外邪实弦，故原文戒“不可轻忽”，主病在阴亏木旺。", ["弦"]], "9581": ["治法", "脉数为热象，咳嗽不松、甚则带血、口干，皆肺热津伤、虚火上灼之征。数脉在此主上焦热盛，肺失清润，故原文立“宜清润上焦，宣泄肺气”之法，以数脉定热，以咳血口干定病位在肺，治法与脉症相合。", ["数"]], "9582": ["治法", "脉数主内热。吐血复发、头胀痛、内热，乃肝肺热盛、气火上逆，迫血妄行。数脉示热象明显，本体不充则虚热内生。原文谓“宜先治肝肺”，以数脉定热，以吐血头胀定肝肺，示先清肝肺之热以止血，治法切于脉症。", ["数"]], "9583": ["治法", "脉弦主肝气偏亢、气机郁滞。阵呛见红、胁痛、稍有寒热，乃肝气上逆犯肺，肺失宣降，络伤血溢。弦脉示木气不舒，故原文拟“先宣泄上焦，以畅肺气”，以弦脉定肝肺气逆，治法重在宣畅肺气以平木逆。", ["弦"]], "9584": ["预后", "吐血后咳嗽不净、气急便泄，脉细为阴血亏耗、脾肺两虚之象。吐血伤阴，阴损及气，气不摄纳则气急，脾失健运则便泄；脉细主气血俱衰，正虚而症见多端，故断为\"非轻症\"，提示预后堪忧，不可忽视。", ["细"]], "9585": ["病机", "咳嗽痰中带红、口干不作渴，脉细为阴分不足、虚火灼络之征。阴亏则津不上承而口干，然热不甚故不作渴；虚火伤肺络则痰中带红。脉细主阴血虚少，故治法宜\"滋养阴分，清化痰热\"，以复其阴、清其络。", ["细"]], "9586": ["预后", "咳嗽较松而痰血不净、口干，脉数示余热未清、阴分受灼。数脉主热，热在肺络则血不净，热灼津伤则口干。症虽减轻而脉数不退，说明邪热尚存、阴未复，故告诫\"此非细故，不可忽\"，提示须防热盛动血之变。", ["数"]], "9587": ["预后", "吐血复发、咳嗽无痰、遍体无力，脉细数为阴血亏乏而虚热内扰之象。细主阴血不足，数主虚火，阴亏火旺则血不宁而复发吐血；无痰、无力皆精气耗竭之征。原文断\"亏乏已甚，理之不易\"，正言其阴损及气、虚火难清，预后棘手。", ["细", "数"]], "9588": ["病机", "久咳忽增吐血、舌黄，脉弦为肝旺气逆、木火刑金之象。弦主肝病，肝气上逆则血随气升而吐血；舌黄示内有郁热。体虚而病实，即正虚邪盛、虚实夹杂，故告诫\"诸须加慎\"，提示调治须兼顾虚实，不可偏执。", ["弦"]], "9589": ["病机", "失血屡发、神疲口干，尺部软而余弦、心肝部不静，为阴薄火浮之候。尺软主肾阴不足，弦而不静示心肝火旺，阴不制阳则火浮于上，迫血妄行而屡发失血；神疲口干皆阴亏之征。原文断\"阴薄火浮\"，正合脉症，故须慎养。", ["软", "弦"]], "9590": ["预后", "吐血屡发、鲜红而多，脉软弦并见。软为阴血亏虚、脉道不充，弦为肝气偏旺、气逆动血，二者相合示正虚而肝火未靖，血不循经故屡发且色鲜量多。值火令之时，火热助肝，尤易迫血妄行，故言\"尤易转重\"，提示当令防变。", ["软", "弦"]], "9591": ["病机", "久咳络损、失血痰多、咳吐不流利，脉弦为肝气郁逆、肺络受损之象。弦主气机郁滞，久咳则肺络伤而血溢痰中；气郁痰阻，故咳吐不畅。积久不愈，肺叶枯萎，原文断为\"积久肺痿\"，言其病深络损、气阴俱伤之转归。", ["弦"]], "9592": ["病机", "脉左软弦、右滑，左脉软弦为阴血亏虚、肝失柔养，右滑主湿浊内蕴。白浊年余，湿热久羁，日前失血更伤阴分，故脉软弦不任重按。治宜存阴化湿热，正合脉症。", ["弦", "滑", "软"]], "9593": ["预后", "脉洪数而滑，洪为气分热盛，数为热迫，滑主痰壅。失血后大发，咳嗽痰鸣，发热口腻，显系痰热壅肺、气火上逆。脉洪数滑与症相应，防壅冒者，恐痰热上蒙清窍，致昏冒之变。", ["洪", "数", "滑"]], "9594": ["病机", "脉弦，右微数。弦为肝脉，失血十年未发，近因伤风作呛，痰中带红，脘下筑紧，乃肝气横逆、肺阴受损。右微数示肺有郁热。脉弦与脘下筑紧相应，肺阴受损故未可泛视。", ["弦", "数"]], "9595": ["治法", "脉状软数，软为阴血不足、脉道不充，数为热。旧有红症，近因感冒咳逆痰红，肋间微痛，乃风热犯肺、灼伤血络。脉软数示正虚邪热，宜先治上焦，清宣肺热以止血。", ["软", "数"]], "9596": ["预后", "脉弦，右如大。弦为肝气，大为邪盛。倾跌后血上下溢，向有腹满癖块，乃瘀血内结、肝气上逆，血不循经。脉弦大示受损已甚，正气难支，故不易见功。", ["弦", "大"]], "9597": ["病机", "脉微数，微为气血不足，数为虚热内扰。伤血后热血交作，乃阴血亏虚、虚热内生，热迫血行。脉微数正合虚热之机，宜慎养以复气血。", ["微", "数"]], "9598": ["预后", "脉数，数为热盛。吐血之后，干呛气急，胸闷，乃肺胃余热未清、气火上逆。脉数示热势未减，防陡然涌吐者，恐热迫血溢，再次大吐。", ["数"]], "9599": ["预后", "脉数微弦，数为热，弦为肝急。客冬起咳嗽痰多，有血，乃肝火犯肺、灼伤肺络。病深矣，脉数弦示热郁肝肺，不易奏功，预后堪虑。", ["数", "弦"]], "9600": ["预后", "脉软数，软为气阴不足，数为虚火内炽。左咳嗽吐血、音哑，乃肺阴亏耗，虚火上炎，灼伤肺络则吐血，熏蒸咽喉则音哑。脉软数示正虚而火旺，喉痹告成，理之不易，预后堪忧。", ["软", "数"]], "9601": ["病机", "脉数主热，左咳嗽咽痒、吐血、心嘈，皆阴伤火炎之象。阴液亏虚，虚火内扰，灼肺则咳痒，伤络则吐血，扰心则嘈。火性炎上，最防涌冒，即虚火冲逆致大吐血之变。", ["数"]], "9602": ["病机", "右咳久肺胃两病，干呛甚则作吐，痰中带血，暮夜发热，脉数。数脉主热，肺胃阴伤，虚火内炽，灼津为痰，伤络出血；暮夜热甚乃阴虚火旺之征。此非细故，不可轻忽。", ["数"]], "9603": ["病机", "脉软数，软为气阴两虚，数为虚火内郁。阵呛稍减、干咳尚甚、痰血得止，似有小效，但夜热神疲，脉仍软数，示阴损火郁未解，正虚火旺，小效未可恃也。", ["软", "数"]], "9604": ["病机", "脉软主气阴两虚。客冬大失血，阴血亏耗，气随血伤，故腹大神疲、不时寒热。软脉示正气不足，气阴两病，理之不易。", ["软"]], "9605": ["治法", "脉细数，细为阴血不足，数为虚热内扰。失血渐止而干咳尚甚，乃肺阴亏虚，虚火灼肺。脉症合参，宜润肺泄热，以滋肺阴、清虚火为治。", ["细", "数"]], "9606": ["病机", "脉软主气阴两虚。久咳不已、上年失血、痰薄而白，肺肾两虚之象；向患下痢、大便必痛，肝脾不调之征。软脉示正气亏虚，肝脾肺肾同病，理之不易。", ["软"]], "9607": ["预后", "脉软弦数，软为气阴不足，弦为肝郁，数为虚火。咳嗽音散、失血、满咽红、著枕即咳，乃阴虚火炎，肝郁化火，灼肺伤络。防成虚损喉痹，预后宜慎。", ["软", "弦", "数"]], "9608": ["病机", "脉细主气血不足，肺脾两虚。痰中带血、小溲浑浊、大便不实、咳嗽，皆脾虚失运、肺失宣降之象。脉细为正气亏虚，脾不统血则血溢，湿浊下注则溲浊，脾虚湿盛则便溏。肺脾同病，气血生化乏源，故言不可轻忽。", ["细"]], "9609": ["病机", "左脉弦数，弦主肝郁，数主热。咽关红肿为热壅上焦，咳久音散失血乃肝火犯肺、灼伤肺络。暑天阳气外浮，内热更炽，故难奏功。脉弦数反映肝经郁热，木火刑金，血随气逆，病势缠绵。", ["弦", "数"]], "9610": ["病机", "脉软弦数，软为气虚，弦为肝郁，数为有热。咳嗽起于失血之后，音闪痰多，胃纳式微，乃肺胃两损，中土渐衰。肝郁化火刑金，脾虚生痰贮肺，脉软弦数正合土虚木亢、痰热内蕴之机，病深入重地。", ["软", "弦", "数"]], "9611": ["病机", "脉细数，细主阴亏，数主虚热。血止复来、干咳胁痛、心宕，乃肺肾阴亏，虚火内扰，灼伤血络。胁痛为肝络失和，心宕为心阴不足。阴虚火旺，血不循经，故病易反复，当慎调护。", ["细", "数"]], "9612": ["病机", "脉弦右软，弦主肝旺，软主脾虚。客冬吐血、鼻衄，刻下胸闷神疲，乃肝木乘脾，痰湿内阻。胸闷为痰湿痹阻气机，神疲为脾虚气弱。脉弦右软示肝旺脾弱、痰湿内蕴，故拟清理痰湿为先。", ["弦", "软"]], "9613": ["病机", "脉软数，软为阴亏，数为虚热。吐血纠缠，吐时头顶发热，乃肝肾阴虚，虚阳上浮，热迫血溢。头顶为肝经所过，虚阳循经上扰故发热。脉软数正合阴虚阳浮之机，宜育阴潜阳、导热下行。", ["软", "数"]], "9614": ["病机", "脉细弦、左软，细为阴亏，弦为肝旺，软为气虚。昔年吐血后咳嗽不已、左胁痛、易寒易热，乃肺肾阴亏，不能收摄肝木，木火烁金。胁痛为肝络不和，寒热为阴阳失调。脉象示阴虚肝旺，最防血症反复。", ["细", "弦", "软"]], "9615": ["治法", "脉弦主肝木乘肺胃。咳嗽失血、肾关不固、脘次结硬，乃肝气横逆，犯肺则咳血，犯胃则脘硬，下及肾关则不固。脉弦为肝旺之征，故宜先治所急，清肝肃肺、和胃固肾，方用沙参、桑皮、黛蛤散等。", ["弦"]], "9616": ["病机", "脉细为阴血亏少，数乃火郁于内。原文谓\"满口失血\"后\"痰嗽带红\"，失血伤阴，阴不制火，虚火灼肺，故脉细数。细数并见，示阴伤火郁，非实热亢盛，故言\"不可忽视\"，防其渐成虚损。", ["细", "数"]], "9617": ["病机", "左脉细数，细主阴薄，数主火浮。原文\"满口失血，咳嗽胸闷\"，失血则阴薄，阴薄则火无所制而浮越，上壅胸肺，故咳而胸闷。脉细数正合\"阴薄火浮\"之机，最防虚火壅冒清窍，故曰\"最防壅冒\"。", ["细", "数"]], "9618": ["预后", "脉细数见于\"咳嗽带血，纳少神疲\"，细为阴精亏耗，数为虚火内动。纳少则化源不足，神疲则气亦受损，阴亏火动而气血并耗，故断为\"渐成虚损\"。此段以脉细数合症，示虚损将成之预后，戒人勿忽。", ["细", "数"]], "9619": ["治法", "脉弦为肝木偏旺，微数为火郁未清。\"咳嗽少松，痰多、血不净\"，木火刑金，灼津为痰，迫血妄行，故痰多血不净。弦数并见，示阴亏而火不降，故治法\"存阴泄火\"，滋水以制木火，火降则咳血可减。", ["弦", "数"]], "9620": ["病机", "\"伤血后咳嗽不已，骨节痛，食下腹中不适\"，脉弦。失血伤阴，肝木失养而偏亢，弦为肝旺之象。木旺则侮肺作咳，克脾则食下腹中不适，阴血不足濡养筋骨故骨节痛。弦脉示木郁不柔，故曰\"理之不易\"。", ["弦"]], "9621": ["病机", "原文\"咳嗽四月不止，近日吐血，咳不畅，脉不畅\"，脉象仅言不畅，未成具体脉名，故不取脉字。久咳四月，热郁于肺，肺伤络损则吐血，气机不利则咳不畅、脉不畅。热郁肺伤为本，故\"防吐血大作\"，方用清肺凉血、化痰和络之品。", []], "9622": ["病机", "脉软弦，软为气阴不足，弦为木旺。\"失血屡发，干呛无痰，面无华，胃呆\"，失血伤阴，金水两亏，肝木失濡而弦，脾土失运则胃呆、面华不荣。\"子母同病\"指肺金肾水俱病，故\"宜金水双调\"，防延成虚损本症。", ["软", "弦"]], "9623": ["病机", "\"咳嗽激痛胸次，失血止，痰仍厚，大便溏\"，脉弦。弦主肝木偏旺，木旺上刑肺金则咳而胸痛，下克脾土则便溏、痰厚。失血虽止而木郁未平，肺脾同病，故\"宜肺脾\"，治当清金抑木、健脾化痰。", ["弦"]], "9624": ["病机", "脉软弦，软为虚象，弦主饮邪与气机不和。咳呛呕吐、乍寒乍热、便溏，显系脾虚失运，痰饮内停，肺胃气逆。体虚而脉见软弦，正虚邪恋，故云病不易奏功。", ["软", "弦"]], "9625": ["病机", "脉微数，微为阳气不足，数主痰饮郁而化热。咳嗽痰多气急，乃脾虚不运，痰饮上贮于肺，肺失肃降。脉微数正合痰饮本虚标热之机，故治在肺脾。", ["微", "数"]], "9626": ["病机", "脉弦主饮邪内结、气机郁滞。积痰不出、咽痒痛、口干，起于痰饮喘急之后，是痰饮久踞，气郁化火，上灼咽喉。弦脉应饮应郁，故知痰饮为本、气火为标，理之非易。", ["弦"]], "9627": ["病机", "脉软数，软为脾虚湿盛，数主痰湿郁蒸化热。脾湿蒸痰贮肺，肺气上逆，咳逆气急不得卧，舌白黄、背恶寒，皆湿痰内壅、肺失肃降之征。脉软数示正虚邪盛，故防作喘。", ["软", "数"]], "9628": ["预后", "脉虚数促，虚为阴阳并亏，数为虚阳浮动，促主脏气衰败、真元欲脱。病久无脏不虚，肾不纳、肺不降、浮阳上越、自汗气急，六昼夜不能合目，脏真如失所司，脉证俱危，故云理之颇非易易。", ["虚", "数", "促"]], "9629": ["病机", "原文未识脉名，仅言以脉合证，似乎中有痰浊。阴分不足则气火偏升，头晕耳鸣、遍体作胀；痰壅无形之气，气灼有形之痰，夜躁多梦痰黏。标本同病，痰浊与气火交阻，故宜择要先治。", []], "9630": ["病机", "脉细涩，细为气血不足，涩主痰湿阻滞、气机不畅。痰湿阻碍气化，清浊不分，气少下达，脘次如隔，舌白黄少寐。细涩之脉正合痰湿内阻、气血不充之机，病根实深，草木之功有限。", ["细", "涩"]], "9631": ["病机", "脉濡主脾虚湿盛。脾为生痰之源，脾湿蒸痰上输于肺，肺气不降，故咳逆痰多、动即气急，舌薄白。濡脉正应脾虚湿困之机，病根深远，理之当从脾肺着手。", ["濡"]], "9632": ["病机", "脉软主气虚湿困。原文谓右积痰贮肺、肺失清肃，咳逆痰多白、胸闷知饥不能食，显系脾虚生痰上贮于肺，肺脾同病。脉软为正气不足、湿痰内蕴之象，非实邪壅盛，故曰肝木乘之、病实，实指痰湿为患而本虚标实，治当择要兼顾。", ["软"]], "9633": ["病机", "左脉细弦、右软，细弦为肝木偏旺、脾土受制，软为脾虚不运。原文谓脾不健运则生痰贮肺、咳逆气急痰白，胃呆午后躁，正是木乘土、痰湿内阻之候。脉细弦应肝，软应脾虚，故断为病深药浅、不易见功，示虚实夹杂、病程缠绵。", ["细", "弦", "软"]], "9634": ["预后", "脉数而不畅，数为郁热内扰，不畅为痰湿阻滞气机。原文谓痰湿内阻、风寒外乘、中焦运融不宣、胸背彻痛，病属胸痹。音哑脉数不畅，提示痰气交阻、津不上承，久则气结血瘀，故最防渐转噎膈，属预后警示之论。", ["数"]], "9635": ["病机", "脉软弦带滑，软为脾虚，弦为饮邪内动，滑为痰湿壅盛。原文谓痰饮气急、咳嗽冬寒尤剧、腹中不舒、大便不实，正合脾阳不运、水饮上泛之机。脉象与症相符，故宗《金匮》外饮治脾立法，从脾阳不足、饮邪内停论治。", ["软", "弦", "滑"]], "9636": ["预后", "脉沉细，沉主里、细主虚，为阳气衰微、饮邪深伏之象。原文谓向患积饮作吐、形瘦纳少、咳嗽带血，显示久病饮停伤及脾肺，气血俱亏。脉沉细而症见形瘦咳血，正虚邪恋，故曰病道深远、不易治，属预后不良之判断。", ["沉", "细"]], "9637": ["病机", "脉细主阳气不足、饮邪内阻。原文谓肠鸣濯濯如囊裹浆、小溲少、痰多胸闷，正是饮停中焦、阳不化气、水湿泛溢之候。脉细与积饮阻遏中阳相应，阳微则水饮不化，故一时不易速效，须温阳化饮缓图。", ["细"]], "9638": ["病机", "脉濡主湿、主气虚。原文谓痰湿壅阻气分、气虚升降未能自如、足肿入腿、少腹胀、夜卧气升，显系湿浊弥漫、气机壅滞、脾虚不运。脉濡正应湿郁气弱之机，湿邪有下趋之势，故须速为解散，防其浸淫日深。", ["濡"]], "9639": ["病机", "脉软带微弦，软为气虚湿困，微弦为气机郁滞。原文谓气不化湿、湿郁蒸痰、痰气窒滞、腹中不能舒转、大便不流利、头蒙，正合三阴同病、痰湿气郁之候。脉软弦与湿郁气滞相应，故当循序理之，不可峻攻。", ["软", "弦"]], "9640": ["主病", "脉软主胃气虚弱，运化无力。原文“胃浊不降，积饮作吐”致饮食不思、脘腹作痛，脉软正合胃虚浊逆之机。痛久神疲、不寐惊惕，乃胃不和则卧不安，舌黄为浊郁化热之象。脉证相参，防积饮日久成膈，故以软脉示胃虚为本。", ["软"]], "9641": ["病机", "脉带弦主痰湿热逗留，气机不畅。原文“左痰湿热尚多逗留”致胃纳呆钝、脘次未舒，舌根苔不清，皆痰湿阻遏中宫、升清降浊失常之征。弦为气郁痰滞之脉，故拟流利气机、舒畅中宫，以复升降之常。", ["弦"]], "9642": ["主病", "脉数主热，痰堵胸次、大便不行，昨宵发热，舌黄，显系痰热内结、表里俱病。数脉为邪热亢盛之应，热与痰搏，腑气不通，故急宜表里两治，外解发热，内通大便，以撤痰热。", ["数"]], "9643": ["病机", "脉软弦滑数，软为虚，弦主饮，滑主痰，数主热。原文“积痰作迷，迷则神蒙”乃痰湿蒙蔽清窍，兼小溲色深为湿热下注。脉象示痰湿化热、本虚标实之机，故宜先治痰湿，痰去则神自清。", ["软", "弦", "滑", "数"]], "9644": ["病机", "脉弦滑主痰饮内盛。原文“脾不运则生痰，肺不降则咳呛”，吐出白沫黏韧之痰，咳甚头晕、右耳鸣响失聪，皆痰浊上扰清窍之征。弦为饮邪，滑为痰盛，脉证合参，宗金匮外饮治脾，以绝生痰之源。", ["弦", "滑"]], "9645": ["病机", "脉弦主饮邪内停、气机郁滞。原文“积痰积湿，肺脾受病”，气急咳逆、吐痰不爽利，乃痰湿壅肺、肺气不降所致。弦脉应饮，故宜泄肺下气，以防痰壅气逆作喘。", ["弦"]], "9646": ["病机", "脉软弦，软为脾虚，弦为饮邪。原文“脾不化湿，由湿蒸痰痰输于肺，肺气不降”致咳逆不已，精微尽化为痰。舌垢、口干不多饮、不渴，皆中无阳、气不化津之象。脉证示脾肺两虚、痰饮内停，故宜标本两治。", ["软", "弦"]], "9647": ["预后", "脉至数不匀，为肺虚久喘动肾、胃家痰热上亢之危候。气急痰嘶、神识迷蒙、舌糙燥无津，乃痰热蒙窍、阴津耗伤；肢振为虚风内动。脉律不匀示脏气衰败，故曰“病深药浅，不易立方”，预后堪忧。", []], "9648": ["病机", "脉濡滑，濡主湿、滑主痰，正合原文“痰湿阻遏升降”之机。舌白根腻、得食作泛、腹鸣溲少，皆痰湿中阻、脾运失司之象；右肋下痛、腰脊酸，为湿阻气机、络脉不和。痰湿久郁，升降之道渐塞，故防延噎膈，是脉症相参而知其传变。", ["濡", "滑"]], "9649": ["病机", "脉来弦动不调，弦属肝木、动主火扰，与原文“火甚则逼动肝木”相应。痰饮为表邪所遏，肺胃不降，痰湿热从火化，故咳逆气粗、肌灼神躁、吐浓黄黏痰；心营素亏，浮火益烈，致抽搦糊语、喘急不寐。弦动不调正是上实下虚、正不敌邪之脉候。", ["弦", "动"]], "9650": ["预后", "本段未识脉名，仅言“脉状较能敛静”，是据脉之敛静与舌垢化薄、气急较平、形色较正、寐宁并见，断为“有减无增之佳象”。然气阴已乏、痰火犹重，肺降肾纳不充，故脉虽敛静而病本未复，预后转佳中仍寓可虑，须养阴清痰以善其后。", []], "9651": ["病机", "脉左弦、右滑数，左弦应肝火升，右滑数应痰热壅肺。原文谓“肝火升则气火亦升，火升则痰来”，痰浓带黑为邪火煅炼积饮而成；咳多气急、夜来语多错杂，皆阴不涵阳、痰火上扰神明。脉已无错综之状，示痰热虽重而病机渐趋分明，本元虽弱不可骤补。", ["弦", "滑", "数"]], "9652": ["病机", "右脉滑数得减，左部尚弦疾上驶。滑数减则上焦痰热较化，弦疾上驶则心营虚而肾不摄肝、肝木未平。原文谓“痰火解开，心肾交而肝肺升降得和”，故右脉先减；左脉弦疾，正是肝虚不摄、浮阳上驶之征，故药须清痰养阴利气以治本。", ["滑", "数", "弦", "疾"]], "9653": ["预后", "脉数象较退、弦象较和，已无鼓指上驶之象，是痰火渐平、肝风渐息之佳兆。然“和缓不足”且舌苔发黄、痰热尚多未解，说明胃气未复、余邪留恋。原文历述风寒、停痰积饮蒸热化火、上壅下动之危象，今脉转退和，故断为化险为夷，而所损已非浅少。", ["数", "弦"]], "9654": ["病机", "脉软、尺更弱，右寸关滑数。软弱主气虚，尺弱为下摄不足，滑数则湿痰蒸饮贮肺。原文谓“湿痰生于脾，贮于肺，蒸为痰饮”，脾虚运迟故面浮足肿、动即如喘；右寸关滑数应肺胃痰热。脉症合参，属上实下虚、喘满将剧之候，未可忽视。", ["软", "弱", "滑", "数"]], "9655": ["病机", "脉软弦、按之不调，软为气虚，弦为肝木偏旺，按之不调则气机壅滞、升降失司。原文谓痰饮积久，肺病累及肝肾，上气喘急、胸次不宽，正合上实下虚之机；舌尖中干、边灰余糙，示痰热伤津而浊未化。攻补两碍，故云棘手。", ["软", "弦"]], "9656": ["预后", "脉细软为气血两虚之象。久病咳嗽，下汲肾水，由肺传脾，脾失健运则腿足肿、大便溏泄；气急面浮、杏不思食，乃脾肺气虚、水湿泛滥。细软脉示正气已衰，病深及肾脾，故言“理之不易”，预后堪忧。", ["细", "软"]], "9657": ["病机", "脉濡弦，濡主湿、弦主饮。痰饮由脾传肺，肺病作咳，累及于肾，气急、吐痰、小溲赤；大便溏、腿足肿为脾虚水湿不化。舌垢、口渴不多饮，乃中阳不足、气不化津。脉象示痰饮内停、脾肾阳虚，久则脏真日竭，最虑腹满增喘。", ["濡", "弦"]], "9658": ["预后", "右脉细主气衰，左脉弦主肝郁。噎膈重症兼吐血，乃气结于上、血不循经。右细左弦示脾胃气弱而肝木偏亢，本虚标实，故“不易奏效”，预后不良。", ["细", "弦"]], "9659": ["治法", "脉不畅，乃气机壅塞之征。右气逆上塞，不能食，为胃气上逆、中焦不疏。脉象虽未明言，然“不畅”示气滞，故宜下气疏中，使气降则食进。", []], "9660": ["预后", "脉弦主气郁、主饮。得食作噎，噎甚则吐，右脉不畅，乃气结于上、胃失和降。弦脉示肝气偏亢，木旺克土，久则膈塞不通，故“延防成膈”，当及早疏肝降逆。", ["弦"]], "9661": ["兼症", "左脉濡主脾虚湿困，右脉滑主痰饮内停。膈气稍愈，呕吐渐止，食下作痛得瘥，惟腹胀不已、肠鸣嘈杂，乃肝脾不调、湿浊中阻。脉象示脾虚湿盛、痰气交阻，故宜肝脾两治。", ["濡", "滑"]], "9662": ["病机", "脉软数，软主气虚，数主热。食下咽阻，呕吐腻痰黄水，乃上焦膈塞、痰热内蕴。近增寒热，为邪正交争。软数脉示正气已虚而痰热未清，故当治所急，先解寒热。", ["软", "数"]], "9663": ["兼症", "脉数主热。上焦膈塞稍松，寒热稍愈，而脉数、腮肿，乃余热未清、邪毒上攻。腮肿为热毒壅结少阳阳明，故当治所急，清解余热。", ["数"]], "9664": ["病机", "脉弦为肝木偏亢之象。左食下气顶作吐、脘肋胀，是肝气横逆犯胃，胃失和降；便闭膈症渐著，乃气机郁滞、腑气不通。弦脉主痛、主气郁，此段以脉弦点明肝郁气逆为病机关键，故理之不易。", ["弦"]], "9665": ["病机", "脉细为气血不足、脉道不充。胸脘腹痛不已、腹满自汗、不安寐而惊惕，是木土相攻、脾胃虚弱而肝木乘之；大便不通为腑气不降。细脉示正气已虚，故防成膈气，病机在虚实夹杂。", ["细"]], "9666": ["病机", "原文未识脉名，仅言脉不畅。咽间哽噎、吞不下吐不出如梅核气膈，舌黄，是肝木痰气不平、痰气交阻于咽膈；脉不畅示气机郁滞。病机为肝郁痰凝、气机不畅，故宜平肝涤痰。", []], "9667": ["病机", "脉软弦为肝胃不和、痰饮内停之象。食下作暖、嗳久闷胀稍松、易泛酸、吐清沫痰，是痰饮与气机交郁于中焦，胃气上逆。软主虚、弦主郁，示中虚而肝木乘之，延防膈气。", ["软", "弦"]], "9668": ["病机", "脉细弦为肝木犯胃、胃浊不降之象。得食作噎、脘次作痛、易于辄吐、舌白黄，是肝气上逆、胃浊不降，中挟痰浊。细示阴血不足，弦主肝郁气逆，故最防迁延成膈，急急通阳泄浊、镇逆疏中。", ["细", "弦"]], "9669": ["病机", "脉细软为胃阳式微、气血不足之象。脘次作痛、泛吐酸水、得食辄吐、大便旬日一行、少腹胀硬，是肝木乘虚犯胃、痰湿气机互郁、中运无权。细软示阳气虚衰，故体乏病深，防成膈气。", ["细", "软"]], "9670": ["病机", "脉细数为阴分枯乏、邪热内郁之象。寒热咽痛、痧子隐约、口干，是温邪欲透而阴分先亏，正虚不能托邪外达。细主阴伤，数主热，故非寻常表症，不可泛视，治当存阴透邪。", ["细", "数"]], "9671": ["病机", "脉弦数不畅为温邪夹痰浊交黏中焦、气机不畅之象。身热、丹痧隐约、咽关红肿起腐、舌苔黄垢、不甚渴饮，是浊毒内蕴、痰浊阻滞，邪不能透达。弦主郁、数主热，不畅示痰浊交黏，故须存阴透达。", ["弦", "数"]], "9672": ["病机", "脉弦数，弦主邪郁少阳、数主热盛。原文谓少阴之气先伤、阳明厉毒窃发，温邪厉毒阻中，欲达未达，故脉见弦数。身热、丹痧密布、咽关肿腐、脘闷形寒、便泄，皆毒邪内壅、表里同病之象。素体阴薄，邪热易化燥内陷昏陷，脉数正是热炽阴伤之征。", ["弦", "数"]], "9673": ["病机", "脉弦，主气机郁滞、浊邪内阻。原文谓表分未解、浊阻中焦，故虽身热似衰、痧子较显，而喉关肿势不退、舌苔白垢、脘窒腹鸣，脉仍见弦。弦为肝木乘脾、浊痰壅遏之象，非表邪尽解，故治以泄肺化痰、宣透上焦，使气机畅则弦脉可缓。", ["弦"]], "9674": ["病机", "脉弦数，弦主邪恋、数主热炽。原文谓表热较衰、痧子渐回、白腐退，而紫肿依然、舌边炎绛，是邪热未清、阴液已伤。弦数并见，说明余邪郁于营分、阴亏不能制火，故治宜养阴与泄热兼顾，防邪热再炽。", ["弦", "数"]], "9675": ["病机", "脉弦数，弦为温邪郁遏、数为热盛。原文谓壮热烦闷、神思躁扰、经事先期、舌绛中苔黄、渴饮干恶，是温邪化热伤营、血热妄行之象。弦数示邪热内逼营血，故慎防传里，热入血室之变。", ["弦", "数"]], "9676": ["病机", "脉弦数，弦主火郁、数主热炽。原文谓痧子渐回而舌苔转光红，是阴液被灼、火势未衰。阴薄火炽，故脉见弦数，变迁易易，未可忽。光红舌与弦数脉并见，说明营阴亏而邪火仍炽，最易生变。", ["弦", "数"]], "9677": ["病机", "脉弦数，弦主郁热、数主火炽。原文谓喉关红肿尚甚、哽咽、舌绛红刺、经事先期，是营液被邪火消烁、血热妄行。弦数示邪火内迫营血，故最易热入血室，治以养营泄热，使火降则脉数可减。", ["弦", "数"]], "9678": ["病机", "脉弦数，弦主肝阳升动、数主火盛。原文谓经事先期、头晕耳鸣、神疲不安寐、关节痛、舌绛满刺，是温邪化热伤营、胃阴日损、木火上升。弦数正示肝阳化火、阴不制阳，故尤易起波，须防虚风内动。", ["弦", "数"]], "9679": ["预后", "脉数，主热盛邪深。原文谓痧子隐约、喘咳壮热、便泄，是邪厉深重、内陷闭肺之象。痧隐不透而脉数，说明正不胜邪、热毒内攻，故防厥闭陡变，十分危险。数脉在此非单纯热象，而是邪盛正衰、预后险恶之征。", ["数"]], "9680": ["病机", "脉弦滑数，弦主火郁，滑主痰壅，数主热盛。原文谓“厉毒痰热，蒸郁上焦”，痰火交炽，故脉见弦滑而数；热毒腐肉，发为紫黑斑，火势燎原，痰热上涌，最防喘闭。此脉象直接反映痰热内盛、火毒上攻之病机，与满喉黑腐、斑疹相应。", ["弦", "滑", "数"]], "9681": ["预后", "脉数主热盛，原文谓“痧子甫透，邪已化火”，风火险证，表热脉数，说明邪热炽盛，有化火内陷之势。数脉为热邪亢盛之征，与满喉全白、表热相应；热盛易致痰涌喘厥，故曰“喘厥骤变，易如反掌”，脉数在此提示病情险恶，预后堪忧。", ["数"]], "9682": ["预后", "脉不大，非谓平和，乃余毒熏蒸而脉象不显亢盛，说明邪毒深伏，正气受遏。原文谓“非轻症，弗忽”，表热口干骨痛，脉反不大，提示毒热内郁，不能鼓脉于外，与一般热盛脉数不同，故虽脉不显而症重，预后须慎。", ["不大"]], "9683": ["病机", "脉数主热，幼痧后邪火郁肺，阵呛气急，脉数说明余邪化火，郁闭肺气。数脉为热邪内郁之征，与阵呛气急相应；肺气郁闭，热盛生痰，易致痰涌喘闭发厥，故原文防“喘闭发厥”，脉数在此揭示邪火郁肺、热盛动风之病机。", ["数"]], "9684": ["病机", "脉数主温邪痰热内郁，原文谓“温邪痰热互郁肺气”，表热不甚而痧子不绽，寐醒烦躁，咽关红碎，舌白口干痰多，脉数说明热郁于里，痰热交阻。数脉与痰多、烦躁相应，肺气郁闭，防音闪骤变，脉数揭示痰热内郁、肺气不宣之病机。", ["数"]], "9685": ["病机", "脉弦数，弦主邪热劫阴，数主火盛。原文谓“化火劫阴，阴液受损”，舌光红无液，唇燥，喉间红肿起腐，邪热厉毒蟠踞肺胃。弦数脉反映热毒炽盛、阴液耗伤之病机，与舌光红、唇燥相应；热毒内闭，防痧缩变幻，脉弦数揭示邪热厉毒内盛之危候。", ["弦", "数"]], "9686": ["预后", "脉数主余热未清，原文谓“腐甚大退，红肿尚甚，痧子盈体”，脉数说明邪热仍盛，虽腐退而热未衰。数脉与红肿尚甚相应，热毒未尽，防痧缩内陷，故须透达之。脉数在此提示余邪未清、仍须透解之预后判断。", ["数"]], "9687": ["病机", "脉浮数，浮主邪在表，数主热盛。原文谓“温热袭郁肺胃”，喉关红累密密，右咽白点哽痛，舌黄，泛恶胸腹红晕，脉浮数灼热，说明温邪袭表，热郁肺胃，有布丹痧之势。浮数脉与表热、红晕相应，揭示温邪外袭、热郁肺胃之病机。", ["浮", "数"]], "9688": ["病机", "脉郁数不扬，郁者气机壅遏，数者热邪内蒸。温厉痰湿滞交结，枢机阻塞，故脉气不畅而数。胸脘不舒、痧点不透、喉关紫肿，皆邪郁热伏、痰湿阻滞之象。脉数主热，郁而不扬说明热被湿痰所遏，邪有内陷之势，故称病方鸱张。", ["数"]], "9689": ["病机", "脉左遏数、右弦大。遏数者热郁于内而不透达，弦大者邪热亢盛、肝胆火炽。丹痧透而不畅，身热入夜尤甚，舌绛干饮，神情若昧，皆邪已化热、郁蒸不解之征。弦大为病进，遏数示热郁，深恐内犯心包，故虑其险变。", ["数", "弦", "大"]], "9690": ["病机", "脉弦数且不甚畅，弦主肝胆火旺，数主热炽，不畅则热郁营分。丹痧夹斑虽透，而舌光绛起刺、唇腐且肿，显系邪热深入、劫烁阴津。阴虚之体，热邪最易内陷，故云最易劫陷。脉弦数不畅，正是热郁阴伤、邪有内传之势。", ["弦", "数"]], "9691": ["预后", "脉象极弦极数，弦为肝胆火炽，数为邪热燔灼，极则阴液受劫。喉痧渐回而舌绛碎痛、唇肿起腐、烦躁心慌、痰多带血、目中妄见，皆邪火燥阴、热扰神明之候。脉极弦极数示热势鸱张，阴津将竭，故恐痉厥险变。", ["弦", "数"]], "9692": ["病机", "脉细弦数，细为阴伤，弦为肝胆火动，数为热炽。邪热内炽，扰动肝胆，蒸伤阴气，故神躁不寐、心慌自汗、唇焦目赤、舌糜质紫绛少液。脉细弦数正是阴液被灼、肝火内扰之象，肺胃热燔，势属燎原，深恐阴竭厥变。", ["细", "弦", "数"]], "9693": ["预后", "脉弦数，弦主肝风内动，数主邪热未清。丹痧面部已回而胸次统片，神识恍惚，手指抽搐，舌绛糙起刺，皆阴气大伤、热灼营阴、肝风欲动之征。脉弦数不去，说明邪热未解而阴伤日甚，故深恐痉厥之变。", ["弦", "数"]], "9694": ["病机", "脉左细数、右带滑数。左细数者阴涸于下、火炎于上；右滑数者痰热内壅。邪毒痰热交扰，故目不交睫、语不停声、唇焦口烂。细数为阴亏火旺，滑数为痰热，火状不一而作，势危矣，正言其病机复杂而险。", ["细", "数", "滑"]], "9695": ["预后", "原文未识脉名，仅言今得脉状尚能如昨。前段阴涸火炎，危殆已极，昨日几几沉脱，今脉尚能维持，故谓症情似有一线生机。然舌津不复、浮火不敛，说明阴液难复、虚火仍浮，变幻易如反掌，预后仍属凶险。", []], "9696": ["病机", "脉左细数较滑大，细数主阴液亏虚、邪火内炽，滑大为痰热壅盛之象。原文谓“气阴略立定，邪火又复上炎”，正虚而邪火未清，水不济火，故脉见细数中兼滑大，提示正不敌邪，有猝变之虞。", ["细", "数", "滑", "大"]], "9697": ["病机", "脉细数，细为阴液内乏，数为火毒未泄。原文谓“痧后阴液内乏，火毒不泄，流走阳明络分”，故见两手腕红肿热痛、手指抽掣。脉细数正合阴亏火旺、余毒流络之病机，极易节外生枝。", ["细", "数"]], "9698": ["病机", "脉弦数，弦主风阳震动，数主余火燥阴。原文谓“阳明脉络为风阳震动”，故手指抽搐、关节痛；唇燥舌干、苔灰边绛多刺，皆火盛伤阴之征。脉弦数反映气营皆伤、余火不能速化，仍恐起波。", ["弦", "数"]], "9699": ["病机", "脉细数，细为阴伤，数为火烈。原文谓“虚象渐定，余火复烈”，两手红肿大痛、舌干燥、大便不行，皆阴亏火炽之候。脉细数正示阴液不足而邪火内迫，故急急救阴泄火，以防反复变迁。", ["细", "数"]], "9700": ["病机", "脉弦细数，弦主火郁阳时机关不利，细主阴伤，数主热炽。原文谓“余火充斥阳时机关不利”，两手腕红肿焮痛、唇燥舌干、大便秘，皆火盛阴亏之象。脉弦细数提示正虚邪实，大有变迁之势。", ["弦", "细", "数"]], "9701": ["病机", "脉细弦数，细为阴伤，弦为肝风，数为痰火。原文谓“痰火扰络激动风阳，肝风大动”，故口目歪斜、手指震动、神识时清时蒙；肌肤灼热、便闭、腕肿皆火盛之征。脉细弦数正合阴亏火旺、肝风内动之机，痉厥易如反掌。", ["细", "弦", "数"]], "9702": ["病机", "脉细数，细主阴分枯乏，数主邪火欲透。原文谓“邪火方欲外透，阴分先已枯乏”，故寒热咽痛、痧点隐约、口干。脉细数示阴亏而邪火内郁，非寻常表症，不敢泛视。", ["细", "数"]], "9703": ["病机", "脉弦滑不畅，弦主温邪郁遏，滑主痰浊内壅，不畅示邪阻气机。原文谓“一派温邪挟痰交黏中焦”，故身热、丹痧隐约、咽关红肿起腐、苔黄垢而不甚渴饮。脉弦滑不畅正合温邪痰浊交黏之病机，治须存阴透达。", ["弦", "滑"]], "9704": ["病机", "脉弦数，弦主邪郁少阳、数主热盛。原文谓少阴阴气先伤、阳明厉毒窃发，身热丹痧、咽关肿腐，是温邪厉毒中阻、欲达未达，弦数为邪热内郁、阴伤不能托邪外达之象，故恐化燥昏陷。", ["弦", "数"]], "9705": ["病机", "脉弦滑，弦主表邪未解、滑主痰浊内壅。原文谓面部痧子较显、身热似衰而喉关肿腐不退，脘窒腹鸣，舌苔垢白，正合表分未解、痰浊中阻之机，故以泄肺化痰宣上焦为治。", ["弦", "滑"]], "9706": ["病机", "脉弦数，弦为邪恋、数为热盛。原文谓热较退、痧子渐回、咽关白腐较退而紫肿依然不退，舌黄边尖绛，是温邪留恋而阴液已伤，弦数示邪热未清、阴分受灼，故治宜兼顾邪正。", ["弦", "数"]], "9707": ["病机", "脉弦数，弦主邪郁、数主热盛。原文谓壮热烦闷、神躁扰、经事先期、舌绛中苔黄、渴饮干恶，是温邪化热伤营，弦数为邪热内逼营分之象，故慎防传里。", ["弦", "数"]], "9708": ["病机", "脉弦数，弦为邪火内郁、数为营热炽盛。原文谓咽关红肿尚盛、舌绛满布红刺、经事先期而行，是营阴被邪火消烁，弦数示火炽阴伤，故虑热入血室，拟养阴清营泄热。", ["弦", "数"]], "9709": ["病机", "脉弦数，弦主火郁、数主热炽。原文谓痧子渐回而舌苔转光红，是阴薄火炽之候，弦数示邪火未息、阴液已亏，故谓变迁易易、未可忽，须防阴伤火炽生变。", ["弦", "数"]], "9710": ["病机", "脉弦数，弦主肝阳升动、数主热盛。原文谓经事先期、眩晕耳鸣、神疲不寐、关节痛、舌绛满刺，是温邪化热伤营、胃阴日损、木火上冲，弦数正合肝阳化火、阴伤未复之机。", ["弦", "数"]], "9711": ["病机", "脉数主热盛。原文谓表热痧子满布、舌白尖红、口干咳、烦躁少寐、便溏溲少，是温邪时气互郁肺胃，数脉示邪热郁蒸于肺胃气分，故当清经泄化，以防痧缩变幻。", ["数"]], "9712": ["病机", "脉软弦，软为脾虚不运，弦为肝气偏旺。右向病肝气，尽日脾损，肝木乘脾，脾失健运则易于便泄作胀；舌白亦示湿浊内蕴。此脉象反映肝郁脾虚、木土不和之病机，故治宜疏肝和脾并进。", ["软", "弦"]], "9713": ["病机", "脉濡滑，濡主湿，滑主痰，为痰湿内蕴之象。左肝胃气，攻逆作痛，乃肝气犯胃，胃失和降，痰湿阻滞气机所致。脉濡滑正合痰湿中阻、肝胃气逆之病机，故见攻逆作痛。", ["濡", "滑"]], "9714": ["病机", "脉濡为湿盛困脾之征。右肝郁困脾胃，清浊升降失常，脾不升清、胃不降浊，湿浊内停，故胸腹胀满不食。脉濡紧扣湿困中焦、肝郁脾滞之病机，治宜疏畅二焦以复升降。", ["濡"]], "9715": ["病机", "脉弦滑数，弦主肝，滑主痰，数主热，为肝火挟痰之象。右恶心肌烁，乃肝胃不和、痰热内扰，胃气上逆而恶心，热灼津液而肌烁。脉弦滑数正合肝胃痰热之病机，故治以肝胃。", ["弦", "滑", "数"]], "9716": ["病机", "脉软弦，软为肝营不足、肾气不摄，弦为肝气横逆。肋下撑胀无定，胀入腰背，上逆作咳，皆肝气挟肾气上逆之候。脉软弦示正虚邪实、根深难拔，故云积深根远，未易速效。", ["软", "弦"]], "9717": ["病机", "脉弦主肝，为气机郁滞、肝阳不潜之象。肋瘕攻胀，昼夜无寐，乃心肝不潜，气机上逆，扰及心神。脉弦紧扣肝气上逆、心肝不潜之病机，故非轻证，告诫勿忽。", ["弦"]], "9718": ["病机", "左脉弦为肝木偏旺，右脉甚滑为阳明痰饮内积。阳明积饮，肝木乘之，胃气上逆而吐。脉弦滑并见，正合肝木乘胃、痰饮上逆之病机，故治以下气和中涤痰。", ["弦", "滑"]], "9719": ["病机", "脉濡细，濡主痰湿，细主阴血不足。痰气中堵，肝木上亢，曾头汗面麻连及左半体，乃痰湿阻络、肝阳上扰之候。脉濡细示痰湿内蕴而阴血已伤，故宜静养，不可峻攻。", ["濡", "细"]], "9720": ["病机", "脉软弦，软为脾虚不运，弦为肝气偏旺，合之示肝胃不和、木乘土位。原文'积饮作泛'即脾运失职、水饮内停上泛之症，脉软弦正合肝胃气逆、饮邪内动之机，故宜导之下行以疏肝降逆、化饮下行。", ["软", "弦"]], "9721": ["病机", "脉细主气血不足、脉道不充。原文'右少腹胀，胀则气升晕'，少腹属肝，胀而气升作晕，是肝血亏虚、肝气失柔而升逆，脾亦失健。脉细示肝脾两虚为本，气机失调为标，故治在肝脾，养血柔肝、健脾理气。", ["细"]], "9722": ["兼症", "脉左细数为肝阴不足、虚热内扰，右较大为胃有邪扰。原文'感冒伤风，扰动肝胃'致头晕作泛、口苦心烦、稍有表热，正合肝胃不和兼表邪之候。细数示本虚有热，故宜暂停补药，先解外邪、清肝胃，免补而恋邪。", ["细", "数", "大"]], "9723": ["病机", "脉软弦，软主脾弱，弦主肝强，合示肝木乘脾、胃强脾弱。原文'能食不消，腹鸣溏泄'，能食为胃强，不消、腹鸣、溏泄为脾运不及、水谷不化，脉软弦正应木乘土位、运化失司之机，故宜疏肝健脾、疏补并进。", ["软", "弦"]], "9724": ["病机", "脉软弦不畅，软为脾虚，弦为肝郁，不畅示气机壅滞。原文胎育后腹痛、脘闷食胀，是产后气血未复，肝气郁滞、脾运不健，气营同病。脉软弦不畅正合肝郁脾虚、气滞血涩之机，故宜疏肝和脾、气营两治。", ["软", "弦"]], "9725": ["病机", "脉软弦，软主中虚，弦主肝旺，示脾土虚弱而肝木乘之。原文'脾为肝木所乘，中脘痛，呕吐酸苦黄水'，是肝气犯胃、胆热上逆、中运失宣之候，小溲短赤亦示郁热内蕴。脉软弦正应木乘土、中运不宣之机，故理之不易。", ["软", "弦"]], "9726": ["病机", "脉软弦，软为脾土不足，弦为肝木偏亢，合示土被木乘。原文始病肝胃气，转脘胀满、小溲不利，是肝气犯胃、脾运失职、水湿不化之候。脉软弦正应肝木乘脾、气滞湿阻之机，故宜疏肝化气、分利小便。", ["软", "弦"]], "9727": ["预后", "脉软微弦，软为脾虚，微弦为肝气渐和而未全平。原文脘腹痛减、寒热甫止，是邪退正未复；泛恶头晕、胸闷便溏、溲热，示脾运未健、湿浊未清。脉象渐缓而病根尚存，故谓'病道深远，不易旦夕奏功'，属预后判断。", ["软", "微", "弦"]], "9728": ["病机", "原文述“脉不畅”，未及具体脉象，然肝痹气滞，木郁不达，气机壅塞，故脉道不畅。得食腹胀、遍体酸痛、头痛寒热，皆肝气郁而乘脾、外涉营卫之象。脉不畅正应气滞血涩、木郁达之之机，主肝痹气滞证。", []], "9729": ["病机", "脉数主热，左肝脾不调，热自内生，故脉数。腹膨硬、小溲少、舌糙，乃肝热乘脾、脾运失职、津伤化燥之候。热郁日久，渐成疳积，脉数正是内热鸱张之征，不可轻视。", ["数"]], "9730": ["病机", "脉弦为肝旺，濡为脾虚湿滞。食下作饱、午后脘胀入腹、便闭、舌黄，皆木土克贼、肝气犯脾、湿阻气壅之象。弦濡并见，正合肝强脾弱、湿郁化热之机，延防腹满，不可忽也。", ["弦", "濡"]], "9731": ["病机", "脉左弦为肝亢，右软滑为肾虚痰湿内蕴。腹胀瘕逆、经居三月、带下不已、腰痛，乃肾虚肝亢、冲任不固、痰湿下注之候。弦与软滑并见，正示虚中夹实、肝亢肾弱之病机。", ["弦", "软", "滑"]], "9732": ["主病", "右脉弦，弦为肝脉，主气机郁滞。瘕攻作痛，乃肝气横逆、气血瘀结而成瘕块，攻冲作痛。治在肝脾，以弦脉主肝病，瘕痛多涉肝脾不和、气滞血瘀，故脉弦为瘕痛之枢机。", ["弦"]], "9733": ["病机", "脉弦为肝亢之征。阴虚不能涵木，肝阳化风上升，风燥搏于肌腠，故满头体作痒如虫行。脉弦正是肝风内动、阴亏阳亢之象，再宜泻降，以平肝潜阳、息风降逆为治。", ["弦"]], "9734": ["病机", "脉滑数主痰热内蕴。肝升晕跌、头晕目花、懊恼、脘腹胀、汗少，乃肝阳上扰、痰热中阻、表气不宣之候。滑为痰，数为热，滑数并见，正合痰热内郁、肝升太过之病机，宜表里两治。", ["滑", "数"]], "9735": ["病机", "脉数主热，胸痞腹胀、得食尤甚、头晕，乃肝郁化热、脾运不健、气机壅滞之候。数脉示内热郁蒸，肝失疏泄，脾不宣运，故宜疏肝宣脾两进，以解郁清热、运脾消胀。", ["数"]], "9736": ["病机", "原文谓「脉细带软弦」，并自释「弦者，肝偏亢也，细为阴虚，软则气弱」。细为阴血不足，软为气弱不任，弦为肝木偏亢，三象合见，正合「禀赋不充，气阴俱乏」之体，肝失柔养而偏亢。故本段脉象所主为气阴两虚、肝木偏亢之病机，治当求本培养，使水火相济、气血来复。", ["细", "软", "弦"]], "9737": ["病机", "本段未出脉名，专论病机：右肾水亏、血分虚，肝木失养而横逆，乘胃则痞阻呕恶，入络则攻注作痛，上升则头晕眩，下陷则带脉不固。诸症皆由「本元虚乏」而来，肝气横逆为标，肾水亏虚为本。故当蛰藏之时峻补其本，以符治病求本之法。", []], "9738": ["病机", "本段未识脉名，主论「心肝浮于上，脾胃亏于下，气血两乏」，经脉失灌，故手足少力如重滞、恶寒如风吹。原文点明「皆本原之内虚，风痰遂乘虚而入阻」，即正虚为本、风痰为标。病机属本元内虚、虚风痰浊乘虚阻络，治须专力培养根本。", []], "9739": ["病机", "脉弦数为肝经气火之象。原文谓脚肝气痛甚则「气火因痛而升」，痛定火平而神思疲乏、动作无力，手心热、大便未行，皆气火内郁、营络不通之征。弦主肝郁气滞，数主火升，故脉弦数主肝郁化火、积湿未解、营络未通、气化窒滞之病机，须速解以防痛甚生波。", ["弦", "数"]], "9740": ["病机", "脉软弦者，软为正气不足，弦为肝木偏亢。原文谓「水亏血少，肝木失养，肝气上亢」，致心脘作痛、肢冷自汗、欲吐不吐、大便溏，是「土被木乘」之候。水亏血少为本，肝亢乘土为标，故脉软弦主本虚标实、肝木乘脾之病机，理之非易。", ["软", "弦"]], "9741": ["预后", "脉来弦为肝气偏旺之象。原文谓「肝气上逆，逆则心脘大痛，甚至肢冷汗淋」，弦脉应肝，肝升太过则气逆攻冲，故见大痛、肢冷、汗淋等厥脱先兆。末言「防痛剧致厥」，是据弦脉与剧痛、汗淋并见，提示有致厥之虞，故本段主旨归于预后判断。", ["弦"]], "9742": ["病机", "原文谓「脉左大于右」，左候肝、右候肺脾，左大于右提示肝气偏旺而肺脾不足。症见气顶塞咽、腰左酸软、夜来足肿，是肝升有余、下元不固、水湿不化之象。脉之偏大偏左，正应肝气偏亢、本元不足之病机，故治当循序调养，不可峻攻。", ["大"]], "9743": ["病机", "脉弦应肝，主肝气偏旺。原文谓「肝升太过，胃降不及」，故大便坠塞、午后腹胀、夜来热气冲咽，上升之气自汗而甚，皆肝升无制、胃失和降之征。弦脉在此示肝木过升、胃气不降、气逆上冲之病机，故非疏泄并进不可。", ["弦"]], "9744": ["病机", "脉濡主湿，濡为湿邪困阻、阳气不运之象。原文述“左肝胃不和，胀闷不能多食”，肝气犯胃，胃失和降，湿浊内停中焦，故脉见濡软。治在中焦，以旋覆花、代赭石、左金丸等疏肝和胃、化湿降逆，正合濡脉所主湿滞中焦、肝胃不和之病机。", ["濡"]], "9745": ["主病", "脉弦主痛、主气滞。原文“右便闭小溲少，少腹痛，腰痛，脉弦”，弦为寒滞气机、疏泄失职之象。寒凝气阻，腑气不通则便闭溲少，气血不畅则少腹腰痛。故宜疏通导下以解寒滞气机，弦脉在此提示气机郁滞、寒凝作痛之病机。", ["弦"]], "9746": ["病机", "脉细主气血不足、脉道不充。原文“肝气乘胃，胃脘大痛不已，大便秘，脉细”，肝气横逆犯胃，胃气不通则大痛便秘；脉细示正气已虚，气血不足，不耐攻伐。故防“痛甚生波”，细脉提示本虚标实、气痛伤正之病机，不可忽视。", ["细"]], "9747": ["病机", "原文“脉不畅”为脉象描述而非具体脉名，故脉象要素从缺。所述“体乏气阻，寒滞交结，少腹痛甚，大便闭，恶心”，显系阳气不足、寒滞内结、气机不畅之候。脉不畅正应气阻寒凝、气血运行不利之病机，故宜温通疏泄以散寒行滞。", []], "9748": ["病机", "脉软弦，软主虚、弦主气滞。原文“少腹瘕胀稍松，其气移至中脘，胃不醒”，瘕胀为气结，气移中脘则胃气不醒。软弦示正气不足而气机郁滞，三阴同病，非温通疏泄不可。此脉说明虚中夹滞、寒凝气结之病机，温通则气行，疏泄则结散。", ["软", "弦"]], "9749": ["病机", "脉弦主气滞、主痛。原文“肝肺络气失宣，右胁肋作痛，痛甚则纳减，甚则上及咽喉，下及足膝”，弦脉应肝，肝络气郁则胁痛，气机上下走窜则症涉咽喉足膝。脉弦正示肝肺络气郁滞、宣降失职之病机，病程日久，故云“未易解散”。", ["弦"]], "9750": ["兼症", "脉细主气血两虚。原文“脘腹痛，腰脊酸，少寐，呕恶，恶寒”，症涉中焦与下焦，呕恶恶寒为阳虚寒凝，腰脊酸为肾虚，少寐为血不养心。细脉示正气不足、气血亏虚，故宜标本两治，既温中止痛，又补益脾肾，细脉正是本虚标实之凭据。", ["细"]], "9751": ["病机", "脉细主虚。原文“肝木乘胃土，气痛顶心脘，痛及背脊，大便溏”，肝气犯胃则脘痛彻背，脾土受克则便溏。细脉示脾肾阳气不足、气血亏虚，故拟“通阳泄浊”并“顾及脾肾”。细脉在此说明本虚标实、肝乘脾肾之病机，单通阳恐伤正，故须兼顾。", ["细"]], "9752": ["病机", "脉沉滑主湿热内蕴、气阴不足。沉为病在里，滑为湿浊痰热，右带数则湿热郁而化热之象。原文述痔疾便后绕肛易肿，乃气阴亏虚、湿热下陷肛门所致；脘脐作痛、感冒咳嗽，为肝脾不调、湿热阻气之兼症。脉沉滑数正合湿热下陷、气阴两伤之病机。", ["沉", "滑", "数"]], "9753": ["病机", "脉细数主气营交困、阴血亏虚而内有郁热，右微滑为肝脾克贼、痰湿夹滞之象。原文经停血崩、腹块上下冲突、胀时极甚，乃肝脾不调、气营两伤、瘀滞内结所致；神疲形寒为阳气亦弱。细数而滑，正示虚中夹实、病绪杂出之机。", ["细", "数", "滑"]], "9754": ["病机", "脉弦而不畅，主肝气郁滞、气机不得疏泄。弦为肝脉，不畅示气阻。原文气痛入肋、背脊胸次均痛，皆肝经循行部位，气郁则痛，故脉弦而不流畅。此脉主肝郁气滞之病机，与胁肋胸背走痛相应，治宜下气疏泄以解郁。", ["弦"]], "9755": ["病机", "左弦右滑，左候肝、右候脾，弦为肝气偏旺，滑为脾湿痰滞。原文满腹胀大攻撑无定、神疲形寒，兼经停血崩、三阴俱乏，乃肝脾互乘、气营失调之候。弦滑并见，正示肝木乘脾、湿阻气滞之病机，故理之不易。", ["弦", "滑"]], "9756": ["病机", "脉软弦，软为正气不足、脾虚湿盛，弦为肝气偏旺。原文产后胀满因泻得松、久不断根，今遍体肿、胃纳少，乃脾虚失运、水湿泛溢，肝木乘脾所致。软弦并见，示正虚邪实、肝脾不调之病机，病根深远故未易速效。", ["软", "弦"]], "9757": ["病机", "脉弦主肝气郁滞。原文左胁痛、呃逆，左胁为肝经所布，肝气郁而上逆则呃逆，气滞则胁痛。脉弦与胁痛呃逆相应，说明肝气郁逆、胃气不降之病机。减而未尽，示郁未全解，故宜守前意续治。", ["弦"]], "9758": ["病机", "脉弦左软，弦为肝气升逆，左软示肝经本部正气偏弱。原文肝气升逆作痛、甚则呕吐、齿痛，乃肝阳上扰、风火上攻之候。脉弦主肝逆，软示虚象，故病机为肝气升逆兼风火上炎，治宜平肝泄风。", ["弦", "软"]], "9759": ["病机", "原文仅言脉不畅，未识具体脉名，故脉象要素从缺。脉不畅示气机郁滞、升降不利。原文气急胀满、腰痛、吐沫，乃气逆不降、中焦壅滞之候，气滞则胀满气急，浊气上泛则吐沫。脉不畅正合气机郁阻之病机，治拟顺气疏中。", []], "9760": ["病机", "脉弦细，弦为肝气横逆，细为阴血不足。右腰背痛、痛及心脘、腹瘕攻逆，皆肝气挟阴血亏虚而攻冲走窜之象。弦细并见，说明病在足三阴，肝脾肾阴分不足而气机郁逆，故治在三阴，以养阴柔肝、调畅气机为法。", ["弦", "细"]], "9761": ["病机", "脉软弦细，软为阳气不足，弦为肝气不柔，细为阴血亏少。呕吐后头痛如故、寒从背起、因寒作抽、抽入脘肋、腰痛咳嗽，皆肝肾两虚、阳分受伤，寒邪乘虚内动之象。脉软弦细正合虚寒内动、筋脉失养之机，故须逐渐调理。", ["软", "弦", "细"]], "9762": ["病机", "脉软，为正气不足、阳气式微之象。肾亏则肝失所养而升逆，故发热头痛不已、筋络抽掣；舌黄为内热兼见。脉软而症见肝升风动，说明下元亏虚、虚阳上浮，本虚标急，故原文告诫此非轻症，勿忽。", ["软"]], "9763": ["病机", "脉弦为肝气郁滞之象。当脐痛、二便不流利，乃肝气横逆、疏泄失职，影响脾运与膀胱气化。弦脉主痛、主气郁，正合肝脾不调、气机壅滞之机，故宜调和肝脾、疏利二便，使气畅则痛止、二便通利。", ["弦"]], "9764": ["病机", "脉弦主肝气郁滞。肝气撑胀、腰背酸、咯痰不利，为肝气横逆犯肺、气机升降失司，痰随气滞而咯吐不爽。弦脉应肝，说明病本在肝气郁结，标在痰气交阻，故宜标本两治，既疏肝理气，又化痰利肺。", ["弦"]], "9765": ["病机", "脉软弦，软为脾胃气虚，弦为肝气偏旺。肝胃不和则痰饮气机交郁，食下作嗳、嗳久闷胀稍松、泛酸吐清痰，皆气郁痰阻、胃失和降之象。脉软弦正合土虚木乘、痰气交郁之机，久则恐成隔气，故严防之，未可因循。", ["软", "弦"]], "9766": ["病机", "脉软弦数，软为阴分不足，弦为阳升风动，数为火象。阴不涵阳则阳升作晕烘热，阳有余便是火，火降则畏寒，胸闷纳少少寐、舌黄咽干口燥，皆阴虚阳亢、虚火上炎之候。脉软弦数正合阴亏火升之机，带下杂病宜治所急。", ["软", "弦", "数"]], "9767": ["病机", "脉细为气血不足、脾虚运化无力之象。脾弱运融不健则大便溏薄、纳少，不时腹痛乃中虚气滞、络脉失养。细脉主虚，正合素体不充、脾胃虚弱之机，故须加意慎之，以健脾益气、调养气血为要。", ["细"]], "9768": ["病机", "脉软弦，软为胃气不足、痰湿内蕴，弦为肝木偏旺。左肝木犯胃，胃浊不降，故得食辄吐；舌白黄示湿浊中阻、渐有化热之势。脉软弦正合肝胃不和、木乘土位之机，故宜肝胃两治，柔肝降浊并行。", ["软", "弦"]], "9769": ["病机", "脉数而右虚汗遍体、少力纳少、食后不运，舌白。数脉非必实热，此处乃气虚阳浮、营卫不固之象，汗多伤气，气耗则运化无力。脉数说明虚阳外越、正气不足，故宜标本两治，益气固表与健脾助运兼顾。", ["数"]], "9770": ["病机", "脉软弦，软主中气不足、湿浊内蕴，弦主肝木偏亢。左胸闷、食后腹中不适、口甜，皆脾运不健、湿浊上泛之征；多汗足酸、语言吃力为气虚之象。脉软弦反映肝脾不和、标本俱病，故宜标本并治，健脾化湿与疏肝并举。", ["软", "弦"]], "9771": ["病机", "脉软弦，软为下元不足、正气亏虚，弦为肝升有余。下摄不足则肝阳上扰，故漫动即头旋、目花、耳鸣；大病之后气血未复，舌黄示兼有郁热。脉软弦正示下虚上实、标本同病之机，故宜标本两治，潜降与扶正并行。", ["软", "弦"]], "9772": ["病机", "脉细弦，细主阴血不足、痰浊内阻，弦主肝木犯胃。肝木犯胃、胃浊不降，故得食作噎、脘次作痛、易于取吐；舌白黄示痰浊夹热。脉细弦说明中挟痰浊、气机壅塞，最防迁延成膈，故急通阳泄浊、镇逆疏中。", ["细", "弦"]], "9773": ["病机", "脉弦数，弦为肝气偏旺，数为郁热内扰。肝木犯胃、胃为气逆，故脘次作痛、泛吐涎沫、胃纳不香；舌白、二便如常示病在气分而未及下焦。脉弦数正合肝胃气逆、郁热内生之机，故称肝胃病，一时不易奏效。", ["弦", "数"]], "9774": ["病机", "脉细软，细为阳气衰微、气血不足，软为痰湿内蕴、中运无力。胃阳式微，肝木乘之，故脘次作痛、泛吐酸水、得食辄吐；大便旬日一行、少腹胀硬，乃痰湿气机互郁、中运无权。脉细软正示体乏病深，防成膈气，理之不易。", ["细", "软"]], "9775": ["病机", "脉弦，弦为肝气偏旺、气机冲逆。下摄不足而肝升有余，故每发必从少腹上冲心下，甚则气短，状如奔豚。脉弦正合肝气上逆、冲脉为病之机，病根深远，非一时可拔，故云理之不易。", ["弦"]], "9776": ["病机", "脉弦为肝郁气阻之象，肝失疏泄则气机不畅，故得食胸次筑紧、纳少；气郁化热则内热，舌苔少示郁热伤津。弦脉主肝病、主气郁，与胸紧、纳少、内热诸症相应，治宜顺气疏中，使肝气条达则诸症自解。", ["弦"]], "9777": ["病机", "脉细软为血脱气浮、肝木独亢之象。原文谓肝为刚脏，必得肾水濡之、血液养之，今血脱则脉细，气浮则脉软，水不涵木而肝阳上亢，故见头旋、耳鸣、目花、火升、心荡、食后不运。细软脉正示阴血亏虚、肝失柔养之病机。", ["细", "软"]], "9778": ["病机", "脉细软示肝病积久、下汲肾水，水虚不能养木，木乘中土。细为阴血不足，软为正气亏虚，肝木失养而横逆犯脾，故脘次筑紧、痰多瘕逆撑胀、大便燥结、遍体不适。脉细软与肝病及肾、木乘中土之深远病根相应，理之不易。", ["细", "软"]], "9779": ["病机", "脉濡主湿郁气阻。湿邪内蕴，气机不畅，肝脾不调，故腹痛、大便溏薄不畅、溲少；舌白黄亦为湿郁化热之征。濡脉为湿盛之象，与腹痛、便溏、溲少诸症相应，治宜疏化，使湿去气行则肝脾自和。", ["濡"]], "9780": ["病机", "脉软弦为肝胃不和、痰湿逗留之象。弦主肝郁气滞，软主中气不足，肝胃不和则中运易滞，故气满纳减、不时举发；舌中少液示痰湿内阻、津不上承。软弦脉与气满纳减、痰湿逗留相应，治宜流利气机、疏畅三焦。", ["软", "弦"]], "9781": ["病机", "脉濡细示肝气纠缠、脾运不健。濡为湿滞，细为气阴不足，肝气郁结则气急、头浑、心胸痛，脾运不健则食下运化不健。濡细脉与肝气纠缠、湿阻气机之病机相应，当先治所急，急则治标以缓气急心痛。", ["濡", "细"]], "9782": ["病机", "脉濡主湿滞气分。肝脾不调，气机郁滞，湿阻中焦，故腹痛久不止、心中懊恼。濡脉为湿郁气阻之征，病在气分而非血分，与腹痛、懊恼诸症相应，治在气分，使气行湿化则肝脾调和、腹痛自止。", ["濡"]], "9783": ["病机", "脉细示肝胃不和、阳气不运。脘痛久不止，气血不足，阳郁不伸，浊阴内聚，故脉细。细脉主虚、主阳衰，与脘痛日久、肝胃不和之病机相应，治宜通阳泄浊、疏运和中，使阳气宣通、浊阴下降则脘痛可缓。", ["细"]], "9784": ["病机", "脉濡主湿、主气虚，湿阻气机则脉道弛缓而见濡象。原文言「左气机不通，中脘阻塞」，正合濡脉所主之湿滞中焦、气化不利。气机不畅则中脘阻塞，湿浊内停故脉濡，治以流利气化法，即化湿行气以通中脘。", ["濡"]], "9785": ["病机", "左脉细数，细为营血不足，数为有热；右微滑，滑主痰。原文「肝气郁结，心营不足，痰热气火乘之」，郁久化火，痰热扰心，故见疑惑恐惧。细数示营虚火旺，微滑示痰浊内蕴，标本两治即养营清火与化痰并进。", ["细", "数", "滑"]], "9786": ["病机", "脉虚弦，虚为脏气不足，弦为气郁、为肝病。原文「气郁」「惊恐」「脏气大为所困，肉脱面㿠，咳嗽气急，动作无力」，皆脏虚气郁之候。虚弦并见，示正气已亏而郁结未解，七情内伤，故云理之不易。", ["虚", "弦"]], "9787": ["病机", "脉弦主肝、主痛。原文「肝痛不已，痛则发热作躁，大便燥结」，肝郁化火，亢阳内扰则发热作躁，津伤肠燥则便结。弦脉为肝亢之征，兼肾虚不能涵木，故断为「肝亢肾虚」，当标本两治。", ["弦"]], "9788": ["病机", "脉濡主湿。原文「肝胃不和，恶心作吐，已历年余」，肝气犯胃，胃失和降，湿痰内蕴，故脉见濡。濡为湿滞之象，湿阻中焦则恶心呕吐，治宜平肝和胃、化痰湿，使肝胃调和而湿化。", ["濡"]], "9789": ["病机", "脉弦主肝。原文「肝肾气化较前日稍和，少腹、腰间作痛渐减」，痛减而脉仍弦，示肝郁未全解；「胃气索然，饮食无味」，因肾为胃关，肾病则胃困。弦脉在此示肝肾气郁未复，故须标本两治。", ["弦"]], "9790": ["病机", "脉弦主肝郁、主痛。原文「脘次结块作胀，甚则上逆作恶」，肝气郁结，气滞血瘀则结块作胀，肝气犯胃上逆则作恶。弦脉为肝郁气滞之征，故治当疏肝和胃，使肝气条达则胀逆自平。", ["弦"]], "9791": ["病机", "脉软弦细，软为正气渐复之象，弦细示肝郁血少未全解。原文「腰痛渐止，夜寐较安，胃口略醒」，诸症向愈而脉仍弦细，说明病后气血未充、肝气未和，故宜逐渐培补，不可峻补，以缓图恢复。", ["软", "弦", "细"]], "9792": ["病机", "脉弦为肝木偏旺之象。右头晕、恶心虽止，而脘痛、腰痛、少腹痛如昨，溲热，是肝气横逆、郁而化热，下扰膀胱、上干清窍。弦脉主痛、主肝，诸痛未除而脉仍弦，说明肝郁气滞、湿热未清之病机尚在，故拟守前意增损，继续疏肝理气、清利湿热。", ["弦"]], "9793": ["病机", "脉来数主热。左肝木乘胃，呕吐、脘闷，是肝气犯胃、胃失和降；兼感寒热，为外邪束表。数脉示里有郁热，与肝木化火、胃气上逆相应，外寒里热并见，故宜表里两解，既疏表邪又清里热、平肝和胃。", ["数"]], "9794": ["病机", "脉左濡、右滑。濡为湿滞、脾虚不运，滑主痰湿内蕴。膈气颇解、呕吐渐止、食下痛稍愈，是气逆渐平；惟腹胀不已、肠鸣、嘈杂，乃肝脾不和、湿浊中阻、气机壅滞。左濡右滑正合肝脾同病、湿痰内停之机，故宜肝脾两治。", ["濡", "滑"]], "9795": ["病机", "脉濡主湿。满腹䐜胀、小溲短少、大便闭，是湿浊内蕴、气机壅塞、三焦水道不利。濡脉示湿邪困阻、脾运失职，湿阻气滞则胀满，水湿不化则溲短便闭。故宜疏化分利，理气化湿、通利二便，使湿去气行则胀消。", ["濡"]], "9796": ["病机", "脉濡为湿滞、脾胃气弱之象。寒热得解而胃气不来，脘腹不舒、腰微痛，是外邪虽退，湿浊中阻、肝胃不和、气机未畅。濡脉说明湿困脾土、胃气不苏，故治在肝胃，疏肝和胃、化湿理气，使胃气来复则脘腹自舒。", ["濡"]], "9797": ["病机", "脉濡主湿、主脾虚。胀满日松、酸气渐平，是气滞渐解；而头痛、肢痛不净，为湿浊未清、肝脾不和、经络气机不畅。濡脉示湿邪留恋、脾运未复，故治在肝脾，健脾化湿、疏肝理气，使湿去气畅则头痛肢痛自除。", ["濡"]], "9798": ["病机", "脉细主气血不足、正虚。畏寒、腹痛、神疲，是阳气虚弱、寒凝气滞；细脉示表邪郁遏、正气不足，不能鼓动外达。原文谓“表邪郁，不能达，延防转重”，说明正虚邪陷、无力托邪外出之病机，故须防病情转重，治当扶正达邪。", ["细"]], "9799": ["病机", "脉软弦，右部尤软。弦主肝郁气结，软为不足、湿困。腹右结瘕作痛攻逆，是肝气郁结、气血凝滞；神疲、两足肿，为脾虚湿盛、肝脾同病。软弦并见，示肝郁而正气已虚、湿热内蕴，故拟和肝脾、利湿热，以防腹大成膨。", ["软", "弦"]], "9800": ["病机", "脉软主湿盛土衰，右肝木乘脾胃，湿气无从解散，故见足肿、腹痛、呕恶、大便不实。软脉为湿困气弱之象，木乘土位，标本同病，脾运失健则湿邪留滞，诸症由生。", ["软"]], "9801": ["病机", "尺部弱主脾肾不足，余部弦为肝气偏旺。左脾胃不健，运化迟钝，故胸脘不畅、饮食式微。弱脉示中气亏虚，弦脉示木气失和，脾虚肝乘，气机不畅，治宜流利气机、疏畅中宫。", ["弱", "弦"]], "9802": ["病机", "脉濡主湿，稍带弦为肝强。肝强脾弱，不克运融湿热，湿滞则肠鸣、大便润而不畅；肝风上扰则头蒙作抽、牙痛。濡弦并见，示湿阻而木旺，脾运不健，湿热内蕴，宜疏和并进。", ["濡", "弦"]], "9803": ["病机", "脉软仍主湿困脾弱。便溏稍愈、腹痛呕恶均减，是脾胃渐和之兆；腿足仍痛，则湿邪未尽，下注筋骨。软脉示中气未复，湿滞未清，故宜守前法增损，继续健脾化湿。", ["软"]], "9804": ["病机", "脉左大右软，左大为肝气横逆，右软为脾土不足。肝气从心脘痛入少腹、骨节亦痛，是肝郁气滞、筋脉失和。本体不充，脉大而软，示正虚邪滞，须慎防虚中夹实，理之宜扶正达邪。", ["大", "软"]], "9805": ["病机", "脉状尚带弦，示肝木之气未平。中运渐醒、气化较畅、胃纳稍增，是脾胃渐复之象；然弦脉未去，说明脾升胃降未能尽如常度，肝脾未和，气机尚欠调畅，故宜守前意增损调治。", ["弦"]], "9806": ["病机", "脉滑主痰湿内蕴。脘次痞胀、头晕、不时咽痛，是痰湿中阻、肝肺胃气机不和。滑脉为痰湿之征，湿聚成痰，上扰清窍则晕，阻于咽则痛，滞于脘则痞。宜肝肺胃并治，化痰调气。", ["滑"]], "9807": ["病机", "脉左弦不静，右寸部为大，弦主肝旺，大为气逆。肝气乘胃侮脾，故胸脘腹作痛不已、大便坚塞；轰热寐中惊惕，是肝阳扰心。体虚病深，弦大不静示木气亢逆，正虚邪实，理之不易。", ["弦", "大"]], "9808": ["病机", "脉微数为虚而有热之象。表证虽解，腹中宿患瘕作痛，乃肝气郁结、脾运不健，郁久化热，故脉微而数。微为正气不足，数为郁热内扰，与瘕痛并见，说明本虚标实、肝脾不和，故拟疏肝和脾，标本兼顾。", ["微", "数"]], "9809": ["病机", "原文仅言脉不畅，未成脉名，指脉气郁滞、往来不利。左胁肋下结瘕，顶心脘，食下恶心，乃肝气横逆、胃失和降，气机壅塞故脉不畅。瘕结于胁，肝经所过，木郁克土，胃气上逆则恶心，治肝胃即调畅气机、降逆和胃。", []], "9810": ["病机", "脉软主正气虚弱，气血不足。胸痛由脘次上逆，近有寒热，体乏，脉软，说明中气亏虚、升降失司，气逆于上则胸痛，营卫不和则寒热，正虚无力鼓动脉道故软。此非实邪壅盛，乃虚中夹逆，故云理之不易，治当扶正调气。", ["软"]], "9811": ["病机", "脉濡主湿、主虚，为湿邪困阻、脾气不运之象。腹瘕攻逆，面黄，脉濡，说明肝气郁结、脾虚湿盛，湿浊内停则面黄，气机攻逆则瘕痛。濡脉不主实热，而主湿滞中焦，故治在肝脾，疏肝运脾、化湿理气，使湿去气畅则瘕逆可缓。", ["濡"]], "9812": ["病机", "左软为肝气不足、正气偏虚，右滑为脾胃湿滞、痰食内蕴。病后腹痛，右半硬，二便不畅，脉左软右滑，说明肝脾不和，脾运失健则湿滞右半而硬，气机不畅则二便不利。软滑并见，虚中夹滞，治在肝脾，疏肝运脾、化滞通利。", ["软", "滑"]], "9813": ["病机", "脉软弦为肝郁脾虚之象。弦主肝气郁结，软主正气不足、脾运不健。食下腹痛，乃肝气犯脾、木郁克土，食入则气滞更甚而痛。脉软弦说明肝郁而脾虚，兼有郁热湿滞，故宜疏肝和脾，泄热利湿，使肝脾调和、湿热分消则痛止。", ["软", "弦"]], "9814": ["病机", "右濡细为脾虚湿困、气血不足，左弦为肝气郁结。心脘痛、头晕头痛，脉右濡细左弦，说明肝脾不和，脾虚生湿则濡细，肝郁气逆则弦，清阳不升则头晕头痛，气机不畅则心脘痛。治在肝脾，流利气机，使肝舒脾运则诸症可减。", ["濡", "细", "弦"]], "9815": ["病机", "脉软弦为肝郁脾虚之候。软主正气不足、脾胃虚弱，弦主肝气郁结。肝脾不和，胃纳久不醒，痛经，少寐，说明木郁克土则纳呆，肝郁气滞则痛经，气血不足、心神失养则少寐。脉软弦正合肝郁脾虚之机，故宜疏和并进，疏肝健脾、调和气血。", ["软", "弦"]], "9816": ["病机", "脉软弦者，软为营虚水亏之象，弦乃肝亢内热之征。右营虚水亏则脉道不充故软，肝亢失柔则脉气劲急故弦。此脉主本虚标实、虚实夹杂之病机，与营阴虚亏、肝阳偏亢、内热由生相应，故曰病绪杂出，须由渐调养，非旦夕可复。", ["软", "弦"]], "9817": ["病机", "脉软弦，软示肝肾素薄、精血不足，弦为肝气失柔、横逆为患。肾不摄肝，肝失所养而气偏亢，故左胁作痛、日有三次。此脉主肝肾两亏、肝气不敛之病机，与胁痛频作相应，本元既薄，故未易速效。", ["软", "弦"]], "9818": ["病机", "脉软弦，软为营血亏虚、本元不足，弦乃肝木失柔、气机偏亢。心悸不得寐、腰痛、胃纳式微，皆本虚所致，肝亢扰心则悸而不寐，肾虚则腰痛，脾弱则纳减。此脉主本虚为病、肝脾肾俱损之病机，故须逐渐调养。", ["软", "弦"]], "9819": ["病机", "脉软弦，软主本虚，弦主肝升太过。肝升作晕、脾弱腹胀，又当溽暑熏蒸、气分受损，舌白垢、气短，皆本虚标实之候。软弦正示虚体夹肝亢、气分受困，故曰本虚标实，非兼顾不可，责效尤非易易。", ["软", "弦"]], "9820": ["病机", "脉细软，细为营血不足、脉道不充，软为气分虚弱、鼓动无力。气营两虚则火浮湿郁，腰酸、面浮、心悸作闷、目花神疲、舌光，皆虚象兼郁之候。此脉主气营两虚、虚火夹湿之病机，本虚为主，故宜择要调理。", ["细", "软"]], "9821": ["病机", "脉濡，濡为湿象，主脾运不健、湿邪内蕴；左较大者，肝气偏旺于左。肝脾不调则脘胀，湿郁肌肤则面浮脂肿。此脉主肝脾不调、湿阻气滞之病机，与脘胀、面浮相应，故拟疏和并进，疏肝与和脾兼施。", ["濡"]], "9822": ["预后", "脉软弦，软为正气已虚，弦为肝肺升降失和、气逆于上。两耳失聪鸣响、偏右头痛、心荡、鼻塞，皆升降不和之候。病缠日久，软弦示本虚而气逆，故延恐积虚成损、积损成怯，属预后警示之论。", ["软", "弦"]], "9823": ["治法", "脉弦数，弦为肝气偏亢，数为热象，弦数相合主肝胆痰热上亢。痰热扰及神机则语言易顿、夜少熟睡、惊惕。此脉示痰热内盛、肝阳上扰之病机，故宜镇肝涤痰为治，弦数正是痰热亢盛之凭据。", ["弦", "数"]], "9824": ["病机", "右脉软弦，软为胃阳不振、中气无力，弦为木气乘土、气机郁滞。胃阳式微则不复用事，食入脘胀格拒，必吐清涎酸苦腻末始爽，正是胃虚不降、痰浊上逆之象；舌白、小溲不利亦示阳弱水停。故治以苦降辛通、佐利痰清膈，而戒燥烈劫阴。", ["软", "弦"]], "9825": ["病机", "脉软弦，软属阴分不足、肝体失养，弦为气火易升、肝阳不潜。左阴亏则气火上升，面赤戴阳、心中胆怯不宁、少寐惊惕，皆肝阳挟痰上扰、神魂不安之候；舌黄垢更示痰热内蕴。故宜镇肝涤痰，使浮阳下潜、痰火清降。", ["软", "弦"]], "9826": ["病机", "脉软弦，软主脾虚气弱，弦主肝郁气滞。头晕、胸闷、舌白、腹中不适、气机攻撑、心嘈不思食，正肝脾同病之象：肝气横逆则攻撑嘈杂，脾运不健则胸闷纳呆。软弦并见，说明本虚而标实，故拟择要治之，调肝理脾兼顾。", ["软", "弦"]], "9827": ["病机", "脉小弦数，小为阴虚体弱，弦为肝旺，数为邪热内郁。素体阴虚肝旺，又畏药致表邪逗留，故背寒灼热、头重胸闷；舌糙白、口干、便燥溲热、少腹瘕气撑胀，皆邪郁化热、阴分受灼之征。经谓邪凑其虚，邪不去则虚更甚，故先去其邪、稍参其本。", ["小", "弦", "数"]], "9828": ["病机", "脉软弦，软为肾水虚乏、肝体失濡，弦为木气横肆。肝病积久下吸肾水，水虚无以制木，其气乘胃则泛吐酸水，乘脾则胀，中阻则脘痛；时易恶寒、形浮、心中懊恼莫可名状，皆木郁不达、水不涵木之候。故拟标本两治，滋水柔肝以制其横。", ["软", "弦"]], "9829": ["病机", "脉濡主湿，为湿邪困阻、阳气不运之象。面浮足肿、胸脘阻塞、腹胀并见，说明湿浊弥漫三焦，中宫失畅则胸脘阻塞，水道不利则面浮足肿。濡脉不数不弦，偏于湿滞而非热结，故治宜疏畅中宫、分利水道，使湿有出路而肿胀自消。", ["濡"]], "9830": ["病机", "脉濡为湿盛阳微之候。腹大、溲通便泄、得食中阻、口腻，皆湿浊内壅、脾运不健所致；便泄而腹仍大，说明湿滞不因下泄而减。濡脉示水湿泛滥，防其肿甚作喘，是虑湿邪上逆犯肺。故特嘱不可忽，当早图运脾化湿。", ["濡"]], "9831": ["病机", "脉弦濡，弦为肝木乘脾、气机郁滞，濡为湿阻阳运、肌肤失养。脱力伤肠，阳气不能运经，故肌肤发黄、四肢无力、舌白无华；口苦示郁而化热，二便俱通说明非关燥结。弦濡并见，主阳气不运而湿郁发黄，防延腹满，是虑木郁克土、湿壅日甚。", ["弦", "濡"]], "9832": ["病机", "脉濡主湿，湿郁气阻则水湿不化，故见腹满足肿、溲少面黄。濡为湿困之象，气机被遏，水湿泛溢肌肤而为肿，湿阻中焦则腹满。原文言「延防喘塞变幻」，正虑湿浊上壅、肺气不利而生喘塞之变，故以濡脉示湿郁气阻之病机。", ["濡"]], "9833": ["病机", "脉软为气弱，右微弦则土虚木乘。左脱力不复、足肿神疲、胃呆畏寒溲少，皆脾肾气弱、水湿不运之候。软而微弦，示正气不足而肝木偏亢，脾受克伐，运化失职，故湿停为肿、胃气呆钝。原文「拟清理治」，正合虚中挟滞之机。", ["软", "弦", "微"]], "9834": ["病机", "脉软弦者，软为气弱，弦主木旺。胃气呆木、两足肿、一身无力神乏，乃脾虚不运、肝木乘土之象。软示中气不足，弦示木气偏强，土受木克则纳运呆滞，水湿下注则足肿。原文「宜先治所急」，急在木土不和、气机壅滞，故以软弦示虚实夹杂之病机。", ["软", "弦"]], "9835": ["病机", "脉细主阴血不足、气机不畅。满腹胀大、大便燥结艰行、溲少、舌黄腻，乃湿浊内蕴、气结不行，久则阴伤。细脉示正气已弱而邪滞未去，故原文「防涉膨」，虑其胀满日甚成膨。细而兼黄腻舌，为湿郁化热、气阴两伤之候，理之不易。", ["细"]], "9836": ["病机", "脉弦数少力，弦主气郁，数主热，少力示正虚。面浮口腻、动则气急、腿足酸软而肿、伏块上攻作痛、大便带血，皆湿热内蕴、气机壅滞、血络受伤之候。原文明言「中挟湿热，法须兼顾」，弦数应湿热，少力应虚，故不能以虚字概括，示虚实兼挟之病机。", ["弦", "数"]], "9837": ["病机", "脉细主气阴不足而浊滞内结。浊气在上生䐜胀、得食腹中尤甚、大便燥结不畅、溲少舌黄，乃湿浊壅阻、腑气不通之候。细脉示正气渐弱，邪滞日深，故原文「膨状渐著」，虑其成膨。宜疏利二便，正以细脉示正虚邪实、气机壅塞之病机。", ["细"]], "9838": ["病机", "脉状不畅，未识具体脉名，然百节烦疼、满腹肿胀、经居带多并见，示湿浊痹阻、气血不畅。脉不畅即气机郁滞之征，湿阻关节则烦疼，湿停腹中则肿胀，带下多亦湿浊下注。原文「病绪繁丛，理之不易」，正因湿郁气滞、虚实错杂，脉不畅恰应其气机壅遏之病机。", []], "9839": ["病机", "脉数主热。胀满腹大已久，自汗寒热，近增咽痛，乃久病正虚而邪热内蕴。数脉示热象偏盛，热蒸则自汗，邪正相争则寒热，热上攻则咽痛。原文「标本同病」，标为邪热，本为胀满正虚，数脉应其邪热之标，故理之不易，示本虚标热之病机。", ["数"]], "9840": ["病机", "脉软数，软为正气不足、脾虚湿困，数为湿热内蕴或虚热扰动。表解后神疲足肿、不欲食、少寐、大便不畅，皆脾运失健、湿浊内停之象；溲不禁为气化失司。软数相合，示正虚而湿热未清，故须逐渐清理，不可峻补峻攻。", ["软", "数"]], "9841": ["病机", "右脉软主脾虚湿困、阳气不振，左微弦主肝木偏旺、气机不畅。便血虽止而头晕、足肿入大腿、心悸、面浮，乃阳虚水泛、痰浊上扰之候。脉软弦并见，说明本虚标实、痰湿阻遏阳气，故以通阳泄浊、涤痰顺气为治。", ["软", "弦"]], "9842": ["病机", "脉濡主湿，为痰湿内蕴、阳气被遏之象。气升得平而腿足肿胀如昨、阳缩，说明湿浊下注、阳气不达，痰湿阻遏气机。濡脉不主虚寒而主湿滞，故治以通阳泄浊、通痰湿，使湿去则阳自通。", ["濡"]], "9843": ["病机", "脉濡为痰湿壅阻之征。痰湿壅阻气分，气虚升降不能自如，故足肿入腿、少腹胀、夜卧气升。濡脉示湿邪黏滞、气机被遏，非单纯气虚，故须速为解散，以化痰湿、畅气机，防其壅塞日甚。", ["濡"]], "9844": ["病机", "脉弦主气机郁滞、湿阻中焦。积湿蒸黄、食下脘阻、恶心、小溲赤短，皆湿热蕴结、肝胆疏泄不利、胃气上逆之象。弦脉示湿浊阻滞、气机不畅，故宜疏畅中宫、分利湿热，使湿去热清则黄自退。", ["弦"]], "9845": ["病机", "脉数主湿热内蕴或脾虚有热。面浮足肿、腹大、食下不适、大便溏，为脾运失健、湿浊内停、郁而化热之候。数脉在此示湿郁化热，非单纯外感，故宜醒脾利湿，使脾运复则湿化热清，肿满可减。", ["数"]], "9846": ["病机", "脉濡主湿，右微滑主痰湿内蕴。积湿蒸热、面目发黄、便溏纳少，为湿热困脾之象；左踹红肿乃湿热下注。濡滑并见，说明湿浊痰热交阻、内外皆病，故急须内外两治，分利湿热兼清外疡。", ["濡", "滑"]], "9847": ["预后", "脉左不畅，未成典型脉名，示气机郁滞、升降不利。病起四旬，咳嗽转腹满、面浮足肿、瘕胀，为肺脾肾气化失司、水湿痰浊内停、渐成臌胀之势。脉不畅与胀满并见，说明气滞湿阻日深，故延防成臌，属预后警示。", []], "9848": ["病机", "脉濡主湿，湿邪困脾，脾失健运，水湿泛溢则腿足肿甚；湿阻气机则胸闷神疲。便泄后湿未尽，脉濡示湿滞未化，故宜疏运利湿，以复脾运。", ["濡"]], "9849": ["病机", "脉濡为湿盛之象，湿阻中焦，气机壅滞则胀满腹痛；湿渗大肠则大便溏。湿性黏滞，故不易疏通，治当化湿运脾，以通壅滞。", ["濡"]], "9850": ["病机", "脉细数主阴伤湿热，肺脾同病。脾失运化则腹满、面浮足肿；肺失宣降则咳嗽；瘕逆为气逆上冲。细为阴亏，数为热象，湿热壅肺困脾，故理之棘手。", ["细", "数"]], "9851": ["病机", "左脉细软，左尺带涩，舌白，示阳气式微，阴水内停。通阳泄浊而火象不显，足肿茎囊肿延及少腹，气短气急，小溲不利，皆肺降、肾纳、脾运失职，水湿泛滥之中满。", ["细", "软", "涩"]], "9852": ["病机", "脉左细右弦，细为湿郁阴伤，弦主气滞饮停。积湿蒸成黄疸，腹满撑胀，湿阻中焦，肝胆疏泄不利。治宜在中焦，化湿疏运，以复升降。", ["细", "弦"]], "9853": ["病机", "脉左细右弦，细示湿郁阴亏，弦主气滞。黄疸胀满，腹胀不能食，湿浊壅阻中焦，脾运失职。宜燥湿疏运，使湿化气行，胀满自消。", ["细", "弦"]], "9854": ["病机", "脉濡主湿，风湿相搏，湿邪泛溢肌肤则一身肿胀。风性善行，湿性黏滞，风湿合邪，肺气失宣，延防作喘，当及早疏风利湿。", ["濡"]], "9855": ["预后", "脉濡为湿盛，腹满腹胀已五旬，湿阻气滞日久，脾运渐衰，水湿壅聚，行将成臌。脉濡示湿浊未化，正气尚存，然久延必致臌胀，故告诫弗忽。", ["濡"]], "9856": ["病机", "脉细为气血不足、脾阳不振之象。原文谓诸湿肿满皆属于脾，脾阳不振则积湿泛滥，满腹胀硬、两腿俱肿，正因阳气不能运化水湿，脉道不充故细。舌白、夜溲多亦示阳虚湿盛。肝脾交困，湿浊内壅，最防因肿增喘，即水湿上凌于肺之变。", ["细"]], "9857": ["病机", "脉浮数主表热，与表热时有时无相应；湿热温邪留恋，蒸郁化热而发黄，故目白黄、舌黄。浮为邪在表分，数为热蒸之象，热郁湿中，故不思饮、小溲少、大便不畅。此脉说明湿热郁蒸、表里同病之机，故治当表里两治。", ["浮", "数"]], "9858": ["病机", "脉软弱无力为气血内损、正气不足之征。少腹胀滞、阳痿、腿膝无力，皆下元虚惫；便后下血，更耗气营。脉软无力正合内损为病，说明气营两亏、脾肾不足，故原文叹理之不易。此脉主虚损，非实热便血之数实脉可比。", ["软", "弱"]], "9859": ["病机", "原文仅言脉不畅，未出具体脉名，故脉象要素从缺。湿热蒸化为痢，口苦、心中烦热，示湿热内蕴、气机不畅，脉道因之不畅。脉不畅与湿热壅遏、气血流行受阻相应，故治宜苦泄辛通，以开泄湿热、通畅气机。", []], "9860": ["预后", "脉濡细主湿盛而气血不足。红白痢、腹痛肛坠为湿热滞下，濡细示正气已伤、湿邪未化；不欲食则胃气受困。原文防转噤口，正因濡细之脉见脾胃虚弱，湿热浊邪上逆犯胃，易致噤口不食，故以预后为虑。", ["濡", "细"]], "9861": ["预后", "脉细数为阴血亏耗而热邪未清。下痢转为粪水，示肠中滞浊已去而正气亦伤；舌灰黄、口干为热灼津伤。细数之脉见于久痢，正不胜病，故原文谓变迁可惧，提示正虚邪恋、预后堪忧。", ["细", "数"]], "9862": ["预后", "吐泻六日，败象齐备，脉软示正气大伤、阳气衰微。虽肢冷得暖、势稍减，然气急不平、神气迷蒙、舌红干，皆阴阳两伤、虚风内动之兆。脉软无力而症见迷蒙，终恐发厥骤变，故原文谓小效不足恃，属危重预后。", ["软"]], "9863": ["病机", "便血之后面浮足肿、畏寒神疲，脉软为气营交困、脾肾阳虚之象。便血耗伤气血，气不化水则面浮足肿，阳失温煦则畏寒神疲。脉软无力正说明正气虚衰、气血两亏，故原文谓气营交困，理之不易。", ["软"]], "9864": ["病机", "便血久不止而脉左软、右较大，左脉候血分，软为营血亏虚、脉道不充；右脉较大，是湿浊偏盛于气分。久血伤营，脾运不健则湿内生，故断为营虚夹湿，治拟养营化湿，正合脉左软右大所示虚实兼夹之机。", ["软", "大"]], "9865": ["病机", "脉弦数为湿热蟠踞肠胃之象，弦主气机壅滞、里急后重，数主热蒸。痢下不止、舌白、恶寒咳嗽，是脱力伤脾、湿滞不化而兼表邪。弦数见于下痢，说明湿热积滞未清，气机不畅，故曰不易奏功。", ["弦", "数"]], "9866": ["预后", "脉细小虚数，是气阴两乏、无脏不虚之征。细小微弱为阴血亏耗、脉道不充，数则阴虚生内热、火浮于上。形肉消瘦、肌灼溲赤、怯寒疲惫，正合阴竭于下、火浮于上，故断虚脱一途已近，不能重用补药，预后堪忧。", ["细", "小", "虚", "数"]], "9867": ["病机", "脉数为热，便后下血属远血，是湿热下注大肠、灼伤血络所致。神乏纳少，为湿困脾运、气血受耗。数脉在此主肠腑湿热，故治当清化分利，使湿热去而血自止，非虚寒便血之比。", ["数"]], "9868": ["病机", "脉濡主湿，湿滞阻遏气机，故大便断下不畅、溲少、舌垢。濡为湿邪黏滞、脉道受困之象，湿阻则气机不宣，积滞内停，恐渐成痢疾。治宜疏通积滞，使湿化气畅，正合脉濡所示湿滞之机。", ["濡"]], "9869": ["病机", "右软左弦大，右脉软为脾虚湿困，左脉弦大为肝木偏旺、阴分不足。肝脾不调则肠胃湿热内蕴，便溏带血、心脘腹均痛。弦大见于阴薄之体，是肝旺乘脾、湿热未清，故须速为清理，不可迁延。", ["软", "弦", "大"]], "9870": ["病机", "幼童饮食不慎渐成疳积，脉软为脾胃虚弱、气血不足之象，积滞日久耗伤中气，脉道不充故软。近日少有伤风，是虚体易感外邪。脉软说明本虚为主，法须两顾，既健运消积又兼顾表邪，不可专攻。", ["软"]], "9871": ["病机", "脉弦主气机郁滞、湿热内蒸。湿热蒸为肠辟，口苦腹胀，是湿浊壅阻肠腑、胆热上溢之征。弦脉应肝，木郁则湿热不化，故须速为清解，使湿热去而气机畅，则口苦腹胀可除。", ["弦"]], "9872": ["病机", "脉弦为肝升太过，右细为脾虚不运，左反大则肝木乘脾、气血壅滞。原文“脾病肝升”点明土虚木贼，故见下痢不止、转血水、肠鸣肛痛、腹瘕攻撑，皆肝气横逆、脾络受伤之候，不可再忽。", ["弦", "细", "大"]], "9873": ["主病", "脉细主气血不足、中焦运化无力。原文“运化不健，大便溏泄”，细脉正合脾虚湿盛、肠腑传导失职，故治在中焦，以健运为要，非关外邪。", ["细"]], "9874": ["病机", "脉濡为湿邪困表，带数则湿郁化热。原文“寒热，便泄转为下痢”，乃表邪未解、湿热内迫大肠，表里同病，故急当表里两解，濡数之脉正示湿与热搏。", ["濡", "数"]], "9875": ["病机", "脉弦主肝胆气逆，数主热。原文“寒热，下痢便泄交作，咳嗽痰多”，乃少阳枢机不利、木火刑金，表里俱病，弦数之脉示邪热内迫、肝肺同病，故急当表里两解。", ["弦", "数"]], "9876": ["预后", "脉濡主湿滞中焦、脾运不健。原文“溏泄约已匝月，支急腹痛”，濡脉示湿邪久困、气机不畅，延防转痢，即湿郁日久可化热伤肠，故当早治中焦。", ["濡"]], "9877": ["主病", "脉数主热邪内盛。原文“红白痢七日，表热不净，舌黄垢”，数脉示湿热蕴结大肠、表邪未彻，红白痢乃热伤血络、湿滞气分，故非轻症，不可忽。", ["数"]], "9878": ["病机", "脉微数示湿热内蕴而正气已伤。原文“湿热表邪，挟食滞内阻，由便泄转腹痛下痢，有表热，心嘈”，微数之脉正合湿遏热伏、表里同病，故须速为分解。", ["微", "数"]], "9879": ["兼症", "脉数主热，舌垢主湿浊内滞。原文“下痢稍稀，少腹痛，表热不净”，数脉示湿热未清、表邪留恋，故虽痢稍稀而表里同病未解，宜表里两解。", ["数"]], "9880": ["病机", "下痢积久，脾胃土气耗夺，肝木失土所养而摇动，故脉弦。弦为肝脉，土虚木乘，肝阳上扰则增头痛、齿痛。原文谓“土夺木摇”，正指土虚不能制木、木气横逆之机，病道深远，理之不易，示其虚实夹杂、根深难拔。", ["弦"]], "9881": ["预后", "下痢起糜，脾胃已伤，脉细为气血不足、正气内馁之象；舌黄、呕逆则湿热中阻、胃气上逆。脉细而见呕逆舌黄，是正虚邪恋、胃气败伤之征，故原文断为“病深矣，难治”，示预后不良。", ["细"]], "9882": ["预后", "病缠两月余，形、色、脉无一不虚，是气血阴阳俱损之候；先腰痛旋即腹痛，下白痢、舌花白腻、口燥，乃脾肾两亏、积虚之体。虚而兼积，攻则伤正、补则恋邪，故云“攻补两难”，深恐猝然厥变，示正气溃败、有厥脱之危。", []], "9883": ["病机", "痢伤脾肾，积滞虽除而溏稀淹缠，肾不化水、脾失堤防，水气泛滥为肿。脉右弦大、左弦滑，弦为肝邪内扰、疏泄不灵，大滑主水湿痰浊壅盛。脾肾为病，水湿不化，肝木乘之，故曰不能滋补，拟崇土导水，尚防喘逐。", ["弦", "大", "滑"]], "9884": ["病机", "乍寒乍热、咳痰、脐腹痛、大便匀利，通体虚乏已极，又加抑郁燥劳。脉沉细而弦，沉细为虚损不足，弦主肝郁气滞、木邪犯土。舌白、脐腹痛，是虚寒夹郁、肝脾不和之机，故调理非易，须扫尽思虑以助药力。", ["沉", "细", "弦"]], "9885": ["病机", "左脉滑数而软，滑主痰，数主热，软为营卫不足、正气偏弱。乍寒发热久不止，是营卫失调、痰热内扰，正邪交争于表里之间。脉滑数而软，说明痰热虽盛而正气已馁，故寒热缠绵难愈。", ["滑", "数", "软"]], "9886": ["主病", "寒热类疟、有汗形冷、头痛泛呕、舌苔薄白不渴，脉数。数脉主邪正交争、阳气奋起抗邪，虽见寒象而脉数，是湿邪郁遏、阳气被扰之征。原文拟“达邪化湿”，正合脉数所示邪郁化热、湿阻气机之病机。", ["数"]], "9887": ["病机", "幼暑湿内阻，发疟旬余，有汗热退不清，腹膨面浮，舌苔黄，脉数。数脉主热，暑湿内蕴、湿热交蒸，故脉数而苔黄；腹膨面浮是湿阻气机、脾运不健。小儿易虚易实，淹缠非宜，示湿热留恋、正气易伤之机。", ["数"]], "9888": ["病机", "右脉细小、左微弦，为久疟三疟缠绵，正气已虚而邪气未净。细小微弱主气血不足，弦脉主邪郁肝脾。干咳为肺阴耗伤，经不行乃血虚经闭。体虚邪恋，正虚为主，故曰未可轻视，当扶正达邪。", ["细", "小", "弦", "微"]], "9889": ["病机", "脉濡主湿邪内蕴、脾气不运。三疟淹缠日久，脾虚生湿，湿滞肠道则便溏不畅；湿邪上犯于肺，肺失宣降则增咳嗽。脉濡与便溏、咳嗽相应，示湿浊未化、脾肺同病，故告诫勿忽。", ["濡"]], "9890": ["病机", "脉数主热，疟邪内郁化热，热壅气机则气急头晕、胀满口干；热郁肌表则表热，热耗津液则溲少。脉数与表热、口干相应，示邪热亢盛。若肿甚增喘，则热与水搏、肺气上逆，病势转重。", ["数"]], "9891": ["病机", "脉左软、右微弦，软为气营不足，微弦为肝脾郁结。三疟延久，气营失和，脾肝交困，腹起之瘕时痛、攻胀不已，皆肝郁脾虚、气血瘀滞之象。曾失血则营阴更亏，病深繁，故理之不易。", ["软", "微", "弦"]], "9892": ["病机", "脉弦左细，弦主肝郁阳浮，细主阴血不足。往来寒热止作不定，延至肝升阳浮，盗汗、不得安寐、轰热、遗精，皆阴虚阳浮、肝失藏泄之候。易作疟者，正虚邪伏。脉症合参，本虚为主，故宜从本虚立方。", ["弦", "细"]], "9893": ["病机", "脉来濡主湿邪未化、脾气虚弱。疟邪不净，湿浊内蕴，日暮神倦火升，乃脾虚湿困、虚火上浮之象。濡脉与神倦、火升相应，示正虚邪恋、湿郁化火，故宜进调理法，健脾化湿以清余邪。", ["濡"]], "9894": ["病机", "脉不畅，为邪滞交结、气机壅遏之象。间疟来四日，转为灼热形寒、胸闷、头胀重、骨痛，皆邪正交争、滞结不解之候。脉不畅与诸症相应，示邪势鸱张而正气受困，正属转重之时，不可轻忽。", []], "9895": ["病机", "脉软弦，软为气营俱乏，弦为肝郁不舒。疟久气营两伤，四肢酸软；肝郁血滞，背后抽痛。软弦并见，示正虚邪郁、气血不畅。病道深远，理之不易，当扶正与疏调并施。", ["软", "弦"]], "9896": ["病机", "脉弦数，弦主肝郁，数主热，合见午后但热不寒、面㿠浮、大便不行，是肝郁化热、热结阳明之象。由来两月，邪热久羁，阴液受灼，故不易奏效。", ["弦", "数"]], "9897": ["病机", "脉细数，细为阴伤，数为热，疟后鼻衄、口干，乃疟邪入阴分，随肝火上升，迫血妄行。细数脉正示阴分亏虚而热未清，宜泄降化热。", ["细", "数"]], "9898": ["病机", "疟后体乏形瘦、面浮纳少神疲，脉数而不知戕本原，是疟邪久恋，正气已伤而余热未清。数脉主热，亦主虚，此虚热内扰，病不可忽。", ["数"]], "9899": ["病机", "三疟愈后营卫不调，恶寒出汗，肝气不平，脉软。软脉主虚，示正气未复，营卫失谐，肝气横逆，故拟两顾法，扶正与调肝并施。", ["软"]], "9900": ["病机", "脉弦濡，弦主肝郁，濡主湿，三疟后发面浮肢肿、便通溲少，是营卫失谐，中土受戕，水湿不化。弦濡并见，示肝郁乘脾、湿浊内停，须慎。", ["弦", "濡"]], "9901": ["病机", "往来寒热、头痛胸闷，脉数，是体虚邪恋，少阳枢机不利，邪正相争。数脉主热，亦示正虚不耐邪扰，故未可忽视。", ["数"]], "9902": ["病机", "三疟后骨节酸、脘闷咳嗽、寒热，脉濡。濡主湿，示疟后湿浊未化，困阻中焦，营卫不和，病道深远，不可忽视。", ["濡"]], "9903": ["病机", "暑湿类疟，汗出不足、胸闷水泻，脉弦数。弦主暑湿郁遏肝脾，数主热，是暑湿凉滞交郁，气机不畅，故转重可虑。", ["弦", "数"]], "9904": ["病机", "脉濡不畅，为湿邪内蕴、气机不畅之象。遗泄久不愈，肾气不固，腰酸、舌尖红刺、脘腹拒按、便溏溲赤，显系湿浊阻滞中焦，气化不利。脉濡主湿，不畅示气滞，故先治所急，醒机轴以化湿畅中。", ["濡"]], "9905": ["病机", "无梦而遗，肾关不固，脉弦为阴分不足、肝失濡养之征。弦脉主肝，亦主虚，此因肾阴亏虚，相火不潜，肝阳偏亢，故宜从阴分立方，滋肾柔肝以固关。", ["弦"]], "9906": ["病机", "脉细为阴血不足之象。心脘痛如钻刺、小溲茎痛、浊下、腹胀，乃阴亏湿热下注，络脉瘀滞。细脉主虚，亦主湿，故宜育阴利湿，标本兼顾。", ["细"]], "9907": ["预后", "脉濡为阳气式微、湿浊内困之象。气弱阳衰，久病肾关不固，神疲脘痛，脉濡无力，示病道深远，正虚难复，理之不易，预后堪忧。", ["濡"]], "9908": ["病机", "脉滞弦数，为湿热内蕴、肝胆火旺之征。舌苔黄，湿热未楚，滞主湿阻，弦数主肝胆之火，故须清化分利，使肝胆之火与膀胱之湿各得平靖。", ["滞", "弦", "数"]], "9909": ["病机", "淋浊四旬余，浊色黄白不一，溲痛，脉弦。弦为肝脉，主痛主饮，此因湿热久蕴，阴分已伤，肝失柔养，湿热犹阻，故当先清化分利，兼顾阴分。", ["弦"]], "9910": ["病机", "淋痛得瘥，浊下未已，脉细。细脉主阴血虚，示湿热虽减而阴分已伤，余浊未清，故宜标本两治，清余浊兼养阴血。", ["细"]], "9911": ["病机", "脉软数，软主虚，数主热，为肾虚湿热下陷之象。溲逡、有渴、腰酸、舌白、头痛，乃肾虚不固，湿热下注，清阳不升。故宜清理，清湿热兼固肾。", ["软", "数"]], "9912": ["病机", "脉细为阴血不足、脉道不充之象。原文谓水液浑浊由蕴热所致，溲时淋痛而脐腹痛，热蕴下焦、湿浊内阻，久则耗伤阴分，故脉见细。细脉在此提示湿热久蕴已伤阴血，与淋痛、脐腹作痛相应，治所急者当先清利湿热以缓其痛。", ["细"]], "9913": ["预后", "脉数为热象，淋痛日久而近日增腰痛，是湿热久羁下焦、耗及肾阴。数脉示邪热未清而阴分已伤，故原文断为防阴日损、不可轻忽。数而日久，热灼阴液，与淋痛、腰痛并见，提示病势有深入损阴之虞，非仅一时之热。", ["数"]], "9914": ["病机", "脉弦为肝木偏旺之象。齿痛由右而左、左半头痛麻木，是肝阳上扰、络脉不和；脘不舒为木郁乘土；易走泄乃肝肾不藏。原文直断肝肾病也，非育阴潜阳不可，正以弦脉应肝，说明阳亢阴亏、肝风内动之机，诸症皆由此出。", ["弦"]], "9915": ["病机", "脉软弦数，软为阴分虚而脉不任按，弦属肝木相火不潜，数为湿热内蒸。原文谓嗽逡之血已止而溲下未利，是血去阴伤、湿热仍重，相火失潜。软弦数三象并见，正合阴虚湿热相火交炽之机，故断为一时不易速效。", ["软", "弦", "数"]], "9916": ["病机", "脉濡主湿，为湿邪困阻、阳气不运之象。少腹胀、小溲淋漓不畅、腰酸，皆湿浊下注、气化不利所致。濡脉不主虚而主湿滞，原文宜疏泄分利，正合湿郁下焦、气机不畅之机，与腹胀、溺涩、腰酸诸症相应。", ["濡"]], "9917": ["病机", "脉弦应肝，主气机郁滞、木失调达。不时寒热、遍体烦痛，是营卫不和而肝郁不舒；痰气急为木郁生痰；夜溲多、易遗泄乃肝疏泄太过、肾失封藏。弦脉统摄诸症，说明肝郁气滞、痰扰下元之病机，故当择要调理。", ["弦"]], "9918": ["病机", "脉软弦，软为气弱不运，弦属肝木偏旺。淋浊四月不作痛而浊色带绿，是气不化湿、湿浊久留；气不化则湿愈滞，湿久化热尤易伤阴。原文谓气不化湿、尤易伤阴，宜标本两治，软弦之脉正示气虚湿滞而阴分渐损之机。", ["软", "弦"]], "9919": ["病机", "脉软为气血不足、脉道不充之象。原文谓心肾不足、肝阳独旺，少安寐易遗泄、惊惕头胀，皆由下元亏虚而肝阳上扰。软脉示本虚，与心肾不足相应；阳旺于上而根本不足，故宜柔肝培本，参泄化痰热，标本兼顾。", ["软"]], "9920": ["病机", "白浊湿热两月不净，脉弦为肝木偏旺、湿热郁于阴分，弦主气机郁滞而阴血受伤。原文谓「阴分伤关」，即湿热久羁耗伤阴分，关隘失守，故须慎调，不可峻利。", ["弦"]], "9921": ["病机", "素病遗泄，头晕不已、腿膝软弱，脉软弦。软为虚，弦为肝旺，乃肝肾阴亏、肝木失柔而横逆，故见眩晕膝软。原文「法宜柔肝」，正以柔缓制其弦劲，养阴以敛肝阳。", ["软", "弦"]], "9922": ["病机", "肾纳不足易下遗，又见胃气渐馁、大便不实，脉细软。细软为气血两虚、脾肾不足之象，肾病及胃则纳化失职。原文「宜标本两治」，即补肾纳气与健运胃气并行。", ["细", "软"]], "9923": ["病机", "肝肾不足而梦遗，气短耳失聪，脉软弦。软示精血亏虚，弦示肝阳不潜、虚风内动，耳失聪、气短皆内损之征。原文谓「内损为病，未易奏功」，说明虚损深重，非旦夕可复。", ["软", "弦"]], "9924": ["病机", "积虚下后神疲遗泄，脉左弦右软，舌质红。左弦为肝阴不足、木失涵养，右软为胃气虚弱，舌红示阴伤。原文「宜养阴醒胃」，即滋肝阴以敛弦，扶胃气以救软。", ["弦", "软"]], "9925": ["病机", "肾阴不足梦遗，腰酸胸闷、胃不开、舌垢，脉软弦。软为肾阴亏虚，弦为肝木乘胃，原文「肾为胃关，肾病及胃，胃气渐衰」，正合脉象。治宜补不足、损有余，缓图有功。", ["软", "弦"]], "9926": ["病机", "湿热下走肝肾，营络内痹，睪丸偏大作胀、腰酸，脉微弦。微为湿滞不显，弦主肝经气结、络脉痹阻，故原文「当疏泄厥少」，疏肝泄湿以通营络。", ["微", "弦"]], "9927": ["病机", "咳嗽气急渐止而睪囊胀坠尚甚，寒、神疲，脉濡。濡主湿盛而阳气不足，湿浊下注则囊坠，阳虚则寒、神疲。原文「防餐后生波」，虑脾运不健、湿滞再起。", ["濡"]], "9928": ["病机", "脉细为气血不足、肝肾亏虚之象。程睪丸偏大、时时腰痛而酸，腰为肾府，睪丸属肝肾所主，脉细正应肝肾不足、湿热兼虚下陷之机。细脉主虚，湿热内蕴而正气已损，故脉不显滑数而见细弱，虚陷与湿热并存，病属虚实夹杂。", ["细"]], "9929": ["病机", "脉软弦，软为不足，弦属肝木。陆向病疝气，近增胁痛，胁为肝之分野，疝属肝经之病。脉软示肾气不足，弦示肝木失养而寒气横肆莫制。软弦并见，正合肾虚肝郁、寒凝气滞之机，故宜先急则治标，先散寒疏肝。", ["软", "弦"]], "9930": ["病机", "脉濡主湿，亦主气虚。俞疝气胀大而长，年余不消，脉濡，说明湿痰随气下注厥阴、少阴二经。濡为湿象，湿性黏滞，故病根深远不易速解。疝胀久不消而脉濡，正应湿痰内阻、气机下陷之病机，非单纯寒疝可比。", ["濡"]], "9931": ["病机", "脉濡为湿盛之征。方腰酸少腹胀、睪丸肿大、胸闷恶心，皆湿痰内阻、气机不畅之候。腰酸少腹属肝肾，睪丸肿大属厥少二经，胸闷恶心为湿痰上扰。脉濡正应痰湿内蕴、厥少经气不利之机，故宜疏泄厥少、宣畅痰湿。", ["濡"]], "9932": ["病机", "脉软为气血亏损、正气不足之象。范经阻两月余、腹痛便溏、面无华、腰酸，皆脾肾亏虚、气血生化不足之候。脉软正应亏损已甚之机，经阻非实滞，乃虚而无力行血；面华不荣、便溏腰酸，皆虚象昭然，故理之不易。", ["软"]], "9933": ["病机", "脉软主气虚不足。汪少腹宿瘕、胸升窒、经至腹胀、骨酸，瘕为气营瘀滞，胸窒腹胀为气机不畅，骨酸为肾虚。脉软示正气已虚，而瘕阻经胀又属气营同病，故宜气营两治。软脉在此说明虚中夹滞，不可纯攻。", ["软"]], "9934": ["病机", "脉濡主湿、主气虚。沈癸水淋漓不断、色紫腰酸、纳减神疲，为脾肾两虚、湿浊内蕴；头痛偏右、晨起面浮而肿，为湿浊上泛；兼伤风咳嗽，为新感外邪。脉濡正应湿困气虚之机，虚实兼夹，故宜择要者先治。", ["濡"]], "9935": ["病机", "脉濡为湿滞、气虚之象。林痛经、经净痛止、乳块消而不净，说明气滞血瘀兼湿痰凝结，乳块属肝经气滞痰凝。脉濡示湿浊内阻、气机不畅，痛经随经净而止，为瘀随经去、气机暂通之候，故宜守前意缓图。", ["濡"]], "9936": ["主病", "产后热纠缠，气急咳嗽，脉软。脉软主气血不足，产后本虚，热邪留恋，气急咳嗽为虚热上逆，正虚邪恋，故宜表里两治，扶正祛邪并施。", ["软"]], "9937": ["病机", "木土克贼，气不流利，晨间腹胀，癸水不多，脉软滑数。脉软为脾虚，滑数为湿热内蕴，木克土则气滞腹胀，阴血不足故癸水少，治宜气营两治。", ["软", "滑", "数"]], "9938": ["兼症", "经漏初止，腰酸较好，营阴一亏，肝气易发，纳少少寐头眩，手足心热，腰腹不舒，脉弦滑。弦主肝郁，滑主痰湿，肝气横逆，营阴亏虚，标本同病。", ["弦", "滑"]], "9939": ["妇人", "屡患滑胎，冲任受伤已甚，今经居五月，而脉状尚满。脉满为冲任不固之象，胎元不坚，须格外慎养，以防再次滑胎。", []], "9940": ["预后", "妊娠病吐泻，小溲不通，咽痛吐酸，脉浮大。浮大为正虚邪盛，吐泻伤津，溲闭毒留，势危殆，勉拟方以希万一，预后不良。", ["浮", "大"]], "9941": ["预后", "产虚久不复，曾吐血，兹火升，薄暮微寒而热，脉软，咳嗽渐成蓐损。脉软为气血大虚，虚火上炎，蓐损已成，不易治。", ["软"]], "9942": ["病机", "日晡颧右发赤，寐则口舌干燥，脉软数，舌黄，带下不已。软数主阴虚内热，湿热带下，阴分亏虚，治在阴分。", ["软", "数"]], "9943": ["病机", "经至不畅，少腹痛甚，脉弦细。弦主气滞，细主血少，寒郁气阻，经行不畅，防因痛生波，治宜温通。", ["弦", "细"]], "9944": ["病机", "脉弦细，弦为肝气郁滞，细为营血不足。经至不多、少腹痛，是肝郁血少、冲任不畅；胸闷口干，乃气郁化热、营阴受灼。脉症合参，属气营两病，故拟气营两治，弦细正示气滞与营亏并存之机。", ["弦", "细"]], "9945": ["病机", "左弦右滑，左候肝，弦为肝气横逆；右候脾，滑主痰湿内蕴。经崩后三阴俱乏，肝脾互乘，满腹胀大、攻撑无定，是肝气挟痰湿作胀；神疲形寒，则脾阳亦弱。脉象反映肝脾不调、气营失和之病机。", ["弦", "滑"]], "9946": ["病机", "脉软弦，软为营血不足、脉道不充，弦为肝气失柔。肝肾不足则癸水不能如期、所下不多；气营失调则脉见软弦。此脉示虚中夹郁，肝气不舒而营血亏乏，故拟顺气养营，标本兼顾。", ["软", "弦"]], "9947": ["病机", "脉软主营气不足、脉道软弱。癸水未畅而止，腹痛恶寒，是营血虚少、气机不畅，兼有寒凝。软脉不主实邪，而示气血两虚、冲任乏力，故宜顺气养营，使气行则血行，营充则寒散。", ["软"]], "9948": ["病机", "脉软为气血不足之象。癸水淋漓旬外，腰以下酸痛，是营血亏虚、冲任不固，兼肾气不足。软脉示正气已虚，非实热迫血，故拟气营两治，补气摄血、养营固冲，使淋漓可止。", ["软"]], "9949": ["预后", "原文仅言脉状较前为和畅，未列具体脉象，故脉象要素从缺。诸恙尚安而脉转和畅，是正气渐复、病势向愈之兆；但气营未能和畅、湿热逗留，腿酸作胀、腹不舒、癸水不行，说明余邪未清，仍须化湿养营两进。", []], "9950": ["病机", "轻取细软，细为营虚，软为气弱；重按寸关均弦，弦主肝郁。产后营虚肠燥，热自内生，气后下陷，大便不通，时觉支急如胀，正是血不养肝、肝热素旺、肝气横逆之候。脉象示气营两虚为本，肝木偏亢为标。", ["细", "软", "弦"]], "9951": ["病机", "左脉细，细为营血不足；右脉滑颇有，滑主痰湿或妊娠。经居三月余，药下三日不至，左细示营虚，右滑颇有提示或有胎孕之象，亦可能为痰湿内阻。脉象反映营虚与滑实并见，当细辨经闭与妊娠。", ["细", "滑"]], "9952": ["病机", "脉微数，微为阳伤气弱，数为营热内扰。产后逾四月瘀带淋漓、色泽不一，乃奇脉不摄、阳伤营热之象。脉微主阳气虚损，数主热，虚热相合，故见恶露不绝、色质不纯，治须逐一调理。", ["微", "数"]], "9953": ["病机", "脉状软弱，软为气血不足，弱主虚损。经居三月、恶阻见象，然脉软弱无力，未能遽断为孕，乃血虚气弱、胎元未固之象。故先养血顺气，使气血渐充，脉象转滑，方可确认。", ["软", "弱"]], "9954": ["病机", "脉软弦，软为血分不足，弦为气分不畅。癸水少、腹胀恶心、少纳、腰痛，皆血虚气滞、肝脾不调之候。软弦并见，示虚中夹滞，故宜标本两治，养血与理气并行。", ["软", "弦"]], "9955": ["病机", "脉左沉滑、右软，左沉滑主血分有滞，右软主气分不足。癸水不调，始则一月两行，今二月末至，乃气血失调、冲任不畅。沉滑为血滞，软为气虚，故拟顺气养营，使气行血调。", ["沉", "滑", "软"]], "9956": ["病机", "脉濡滑，濡主湿困，滑主痰滞。少寐少纳近两旬，经居两月余，腹痛作胀，乃湿痰内阻、气机不畅。濡滑之脉示湿浊中阻，故当先治所急，化湿理气以通经。", ["濡", "滑"]], "9957": ["病机", "脉稍有滑象，滑主痰湿。口甜腻、恶寒、神疲、恶心少纳、头晕，皆胃浊痰湿交阻之候。滑脉虽微，已示痰湿内蕴，故宜先疏化，使浊降痰消，诸症自减。", ["滑"]], "9958": ["病机", "脉濡，濡主湿滞气弱。胸闷不能食、食下撑胀、神疲兼寒热、经漏腹痛，乃气营失调、肝脾交困。濡脉示湿困中焦、气血不畅，肝脾同病，故曰不易治。", ["濡"]], "9959": ["病机", "脉细，细主营阴内乏。癸水旬余后至，脉细无力，乃营血亏虚、冲任不充。阴血不足，最防崩漏，因虚而血不守也。故当养营固冲，以防崩漏之变。", ["细"]], "9960": ["病机", "产后左手臂无力不暖、汗出偏沮，脉弦。弦为血虚不能濡养筋脉、阳气偏沮之象，血分亏虚则经脉失养，故肢弱不温而汗出偏于一侧。此段以脉弦点明血分亏虚、筋脉失濡之病机，非外感弦脉可比。", ["弦"]], "9961": ["病机", "经色紫滞、带下多而脉濡细。濡细为气血不足、肝肾亏虚之象，肝肾不充则冲任失养，带脉下陷则带下绵绵、经色紫滞。脉濡细正合虚损之机，说明病本在肝肾不足、带脉失约，而非实邪阻滞。", ["濡", "细"]], "9962": ["病机", "带下、腰酸、癸水少、神思疲乏、肝气时作而脉软，兼头痛。软脉主虚，示肝脾气血不足、筋脉失养，故神疲而肝气易动；腰酸癸少为肝肾亏虚。脉软说明病属虚损渐积，故原文谓宜由渐调理养，非旦夕可复。", ["软"]], "9963": ["预后", "经不调、胸闷胃呆、往来寒热而脉数。数脉主热，亦主虚，此由肝胃不和、寒热错杂，久则耗伤正气。原文谓延防涉怯，即虑其迁延日久转为虚怯之证，故脉数在此提示病势有内耗之虞，当及早调治。", ["数"]], "9964": ["预后", "寒热止作不定、胃不醒、经不调、右臂酸痛而脉微数。微为正气不足，数为虚热内扰，脉微数示本原亏虚而兼郁热。原文谓本原为病，不能旦夕计功，说明此属虚损为本、病根深固，非短期可效，脉象正合其缠绵难愈之势。", ["微", "数"]], "9965": ["妇人", "胎孕而脉滑，左为主。滑为血盛养胎之象，左脉候血，左脉滑甚示胎元得血濡养。原文谓须作速安胎药佑之，尤宜善慎养，说明脉滑虽属妊娠常象，然左甚则需及时安胎调护，以防胎动不安，重在慎养保胎。", ["滑"]], "9966": ["病机", "肝脾不和、胃纳久不醒、痛经、少寐而脉软弦。软为脾虚气弱，弦为肝气郁滞，软弦并见正合肝脾不和之机：脾虚则纳呆，肝郁则痛经少寐。原文谓宜疏和兼进，即疏肝与和脾并施，脉象揭示了虚实夹杂的病理基础。", ["软", "弦"]], "9967": ["预后", "产后五朝壮热、瘀露仍阻、便泄不寐糊语、舌干黄而脉数。数脉主热盛，产后瘀阻兼热，热扰心神则糊语不寐，热迫大肠则便泄，舌干黄示热伤津液。原文谓防骤变，即虑热毒内陷、瘀热交结而生变证，脉数正是邪热鸱张之征。", ["数"]], "9968": ["主病", "脉滑数主痰热内蕴，胎气不安。原文“肝气痛，腰酸，带下红白兼见”乃肝郁化热、湿热下注，扰动胎元。滑为痰湿，数为热，热迫血行则带下红白，气滞则痛，腰酸为肾虚胎动之兆。脉症合参，胎气不安殊为可虑，故主病为胎动不安。", ["滑", "数"]], "9969": ["病机", "脉濡主气血不足、湿滞。原文“血分不充，气失流畅，癸水先期，小腹作痛，痛甚有作寒之状”乃三阴内乏，累及奇经。濡为虚软，示血海空虚、气机不畅，故经行先期而痛，胃纳减、带下、腰痛皆脾肾不足之征。病机在气血亏虚兼奇经失养。", ["濡"]], "9970": ["病机", "脉软弦主肝脾不调。软为虚，弦为肝郁，原文“少寐，少纳，虽有寒热，气血未能流利，经至作痛”乃肝郁乘脾、气血不畅。弦示肝气郁滞，软示脾虚不运，故经痛、纳少、少寐。病机为肝脾不和、气血失于流利，治宜疏化和中。", ["软", "弦"]], "9971": ["预后", "脉软主虚。原文“冬腊未足月而产，积虚不复，变为咳嗽，纳呆，人暮寒热汗出发潮”乃产后积虚成损。软脉示气血大虚，正不胜邪，故见咳嗽、寒热、汗出等虚损之象。延恐积虚成损、积损成劳，预后堪忧，需善为调摄。", ["软"]], "9972": ["病机", "脉空虚而数主产后百脉空虚、虚热内扰。原文“产经十九朝，百脉空虚，遍体痛，头晕，胸闷，不思食”乃气血大亏，虚阳浮动故脉数。空虚无以荣养则遍体痛、头晕；脾运失健则纳呆、便溏。病机为产后气血虚损兼虚热，防迁延生波。", ["空", "虚", "数"]], "9973": ["病机", "脉数主热。原文“右满喉红肿，喉风，两关渐腐，咽燥口干，痰黏”乃肺胃热盛，风热上攻咽喉。数脉为热邪内炽，热灼肉腐则红肿渐腐，咽燥口干、痰黏皆热盛津伤之征。病机为肺胃热毒壅盛，其势方张，当从肺胃立方清解。", ["数"]], "9974": ["病机", "脉虚弦主阴虚肝升。虚为阴血不足，弦为肝气上逆。原文“右喉痛止，易少寐，腹胀，甚则上至巅顶”乃阴亏于下，肝阳上扰，故少寐、腹胀气逆至巅顶。虚弦示本虚标实，病机为阴虚肝升，宜循理调之。", ["虚", "弦"]], "9975": ["病机", "脉数主热。原文“左烂喉风，肿腐”乃风温郁于肺胃，热毒上攻咽喉。数脉示热势方张，热壅则肿，热腐则烂。风温之邪郁于肺胃，不得透达，故肿腐并见。病机为风温热毒郁于肺胃，其势方张，弗可泛视。", ["数"]], "9976": ["病机", "脉左数右细，数主热盛，细主阴津亏耗。原文谓“舌上劫津”，正合右细为津伤；左数则表热壮盛、邪郁深重。热郁化风，故断“势将风动”，属温邪内陷、阴亏风动之重证，非轻浅表热可比。", ["数", "细"]], "9977": ["病机", "舌津回而喉风红肿、咽底腐，脉仍数，是阴气虽略复而温毒炽盛未衰。数脉主热，热毒壅于咽喉则红肿腐溃。原文断“阴气虚，温毒盛”，正说明数脉所主非单纯表热，而是虚中夹实、毒热鸱张，故“极易生波”。", ["数"]], "9978": ["兼症", "左喉风略松而头痛仍甚，脉数，示喉部肿腐虽减，温热之邪未清，上攻头目故头痛不减。数脉为热邪内盛之征，与喉风、头痛并见，说明病势尚在进展，故主“内外两治”，内清温毒、外解郁热。", ["数"]], "9979": ["病机", "右烂喉风肿腐，口干、躁不安寐，脉数，是温邪化热、热扰心神之象。数脉主热盛，热灼津液则口干，热扰心营则烦躁不寐。原文断“温邪化热”，故治法宜清透泄化，使热从气分透解，不致内陷营血。", ["数"]], "9980": ["预后", "肿腐大退、红肿亦减、舌灰黄较化，而脉仍数、音不扬，是喉症虽退而痰热未清。数脉示热邪尚盛，音不扬为痰热壅肺、肺气不利之征。原文断“痰热壅肺，最防作喘”，说明数脉在此提示热痰内壅、肺失肃降，有喘逆之变。", ["数"]], "9981": ["预后", "烂喉风肿腐，胸脘隐约有痧点、胸闷嗜卧，脉数不大，是时气重症而热毒郁遏、痧毒内闭之象。数而不大，示热郁于里而未张扬于外，痧点隐约不透，故原文断“防痧隐猝变”，脉数不大正提示邪毒内陷、透发无力之险。", ["数"]], "9982": ["病机", "脉软弦，软为阴亏、弦为阳亢，合唇燥、心惕，正是阴虚阳浮、痰热内扰之候。原文以“育阴潜阳，涤痰泄热”为法，说明软弦之脉主阴不制阳、虚风内动，兼痰热壅结喉部，故红肿硬痛而心惕不宁。", ["软", "弦"]], "9983": ["妇人", "妊娠之体患右烂喉风，肿腐、表热而脉数，数主温邪热盛。妊娠阴血养胎，热邪易伤胎元，且热壅咽喉可致音闪之变。原文特标“妊娠之体，尤不可忽”，说明数脉在此不仅示热盛，更关胎孕安危，须防热毒内陷、胎动之虞。", ["数"]], "9984": ["病机", "原文以「左脉右为大」言脉势偏盛于右，未列具体脉形，故脉象要素从缺。所述咳嗽较稀、喉风红肿、防腐甚音闪，乃温邪内伏、由渐外达之象；脉右偏大提示邪势偏于肺胃气分，正邪相争而未全透，故当防其内陷与音哑之变。", []], "9985": ["主病", "原文「左寒热头痛，脉数。烂喉风肿腐」，脉数为热盛之征，与寒热头痛并见，说明温厉之邪郁于肺胃、热毒炽盛而外显寒热；烂喉风肿腐为热毒熏灼咽喉所致。病重势速，脉数正示邪热方张，故告诫千万弗忽。", ["数"]], "9986": ["主病", "「右喉风肿腐，痛不能咽，寒热脉数」，脉数主热，与寒热并见，为温厉热毒壅盛于肺胃、上攻咽喉之候；肿腐疼痛致不能咽，说明热毒结聚较深。原文断为温厉重症，脉数正是邪热鸱张之象，故防升塞变端。", ["数"]], "9987": ["预后", "烂喉风白腐脱而未净、红肿全瘥，而畏寒至甚、脉数，说明余毒未清、正气已伤，脉数示内热尚伏，与畏寒并见为邪恋正虚之象。原文尚防反复，仍弗忽视，脉数在此提示热毒未尽，不可因外症减轻而松懈。", ["数"]], "9988": ["预后", "「右双乳蛾，僵伏尚甚，消净不易，内热，脉数」，脉数应内热，说明热毒郁结咽喉、僵伏难消；乳蛾僵伏尚甚而脉数不退，为正邪相持、邪热未衰之候。原文防反复生波，千万勿忽，脉数正是判断余热未清、病易反复的关键。", ["数"]], "9989": ["病机", "「冷热失调，肺胃受之，喉痛红肿，子舌坠，表热脉数」，脉数与表热并见，说明邪热郁于肺胃、上蒸咽喉；冷热失调为病因，肺胃受之为病位，喉痛红肿、子舌坠为热壅之症。原文主从上焦宣泄以畅肺气，脉数正示热郁上焦气分。", ["数"]], "9990": ["病机", "「缠喉痈，肿甚，肿连上腭，痛楚勺水难咽，形寒脉数」，脉数与形寒并见，为温疠痰浊蒸郁肺胃、热毒壅结咽喉之象；肿连上腭、勺水难咽说明痰热壅塞气道。原文断其势不轻，防塞逆骤变，脉数正是热毒鸱张、病势急重之征。", ["数"]], "9991": ["病机", "幼表热，喉疳、舌疳、唇疳并起，两腮下结核，脉数，二便不爽，脉数主热，说明花毒蕴热交织、郁于肺胃而外发口舌咽喉；结核、二便不爽为热毒壅结之症。原文当清化法，脉数正示热毒内蕴，须清解透化。", ["数"]], "9992": ["病机", "脉数主热，此热在表未解，故见头痛、溲少。原文“左表热较和，喉腐渐减”示表热稍退而里热未清，脉数反映温邪内郁，热势未定，防其音闪，即热盛伤阴、肺金受灼之变。", ["数"]], "9993": ["病机", "脉数主温邪郁于肺胃，热毒上攻咽喉，故见咽关碎腐肿痛、作寒发热。数脉为热盛之征，温邪郁肺胃则气分热炽，不可泛视，防其内陷。", ["数"]], "9994": ["病机", "脉数主风热痰浊交郁，热毒壅盛于喉，故右喉风红肿、子舌坠、痰痈肿硬。数脉示热势方张，痰热互结，其势未可忽，防其壅塞气道。", ["数"]], "9995": ["预后", "幼烂喉风满腐，腐肉堆起，子舌已腐去，表热不解而脉数，示温毒炽盛，热灼营阴，腐肉溃烂。脉数主热毒鸱张，防音哑喘闭，乃热毒壅肺、气道闭塞之险候，十分险恶。", ["数"]], "9996": ["病机", "脉数不畅，数主温邪内盛，不畅示本体虚而邪阻气机，故烂喉风灰腐堆起。虚体受邪，正不胜邪，热毒郁遏不得透达，势不可忽，防其内陷。", ["数"]], "9997": ["病机", "脉数主热毒壅盛，左喉痈肿色非常，身热脉数，示热毒结于咽喉，气血壅滞。数脉为热盛之征，最防气逆痰壅，即热毒上攻、痰随气逆而阻塞气道。", ["数"]], "9998": ["病机", "脉数带滑，数主热，滑主痰，示痰热内盛。右咽关痈肿、乍寒乍热、痰多，乃痰热交结于咽喉，正邪交争故寒热。其势方张，痰热壅盛，勿忽。", ["数", "滑"]], "9999": ["病机", "脉数不畅，数主温疠热毒，不畅示邪郁气机、不得透达。烂喉风肿腐极甚，表热两日而脉数不畅，乃温疠深重、热毒壅遏之象，不可泛视，防其内陷生变。", ["数"]]});